int n;
int maze[505][505];
int dx[4]={1,0,-1,0};
int dy[4]={0,1,0,-1};

int bfs(int sx, int sy){
	if(sx==0||sy==0||sy==n-1||sy==n-1) return 0;
	priority_queue<pair<int,PII>, vector<pair<int,PII>>, greater<pair<int,PII>>> q;
	int d[505][505];
	int ret=INF;
	rep(i,n)rep(j,n) d[i][j]=INF;
	q.push(MP(0,MP(sx,sy))); d[sx][sy]=0;
	while(q.size()){
		pair<int,PII> u=q.top(); q.pop();
		if(u.first>=ret) return ret;
		PII p=u.second;
		if(p.first==n-1||p.first==0||p.second==n-1||p.second==0) return u.first;
		rep(i,4){
			int nx=p.first+dx[i], ny=p.second+dy[i];
			if(0<=nx&&nx<n&&0<=ny&&ny<n){
				if(maze[nx][ny]){
					if(d[nx][ny]>d[p.first][p.second]+1){
						d[nx][ny]=d[p.first][p.second]+1; q.push(MP(d[nx][ny],MP(nx,ny)));
						// if(nx==0||ny==0||nx==n-1||ny==n-1) return d[nx][ny];
					}
						// cerr<<"BFS MP" SP nx SP ny<<endl;
				}else{
					if(d[nx][ny]>d[p.first][p.second]){
						d[nx][ny]=d[p.first][p.second]; q.push(MP(d[nx][ny],MP(nx,ny)));
						// if(nx==0||ny==0||nx==n-1||ny==n-1) return d[nx][ny];
						// cerr<<"BFS MP" SP nx SP ny<<endl;
					}
				}
			}
		}
	}

	rep(i,n){
		chmin(ret,d[i][0]); chmin(ret,d[i][n-1]); chmin(ret,d[0][i]); chmin(ret,d[n-1][i]);
	}

	return ret;
}


