int d[MAXN][MAXN];
bool isempty[MAXN][MAXN];
deque<pair<int, int>> q;

void upd(int sx, int sy, int sd) {
	q = deque<pair<int, int>>();
	d[sx][sy] = sd, q.PB(MP(sx, sy));
	while (!q.empty()) {
		int x, y; tie(x, y) = q.front(); q.pop_front();
		REP(k, 4) {
			int nx = x + DX[k], ny = y + DY[k], nd = d[x][y] + (isempty[x][y] ? 0 : 1);
			if (nx < 0 || nx >= n || ny < 0 || ny >= n || nd >= d[nx][ny]) continue;
			d[nx][ny] = nd; if (nd == d[x][y]) q.push_front(MP(nx, ny)); else q.PB(MP(nx, ny));
		}
	}
}

ll solve() {
	REP(x, n) REP(y, n) d[x][y] = min(min(x, n - x - 1), min(y, n - y - 1));
	REP(x, n) REP(y, n) isempty[x][y] = false;
	ll ret = 0;
	REP(i, n * n) {
		int x = p[i] / n, y = p[i] % n;
		isempty[x][y] = true;
		ret += d[x][y];
		upd(x, y, d[x][y]);
	}
	return ret;
}

