ll N;
ll ans;

// 0-indexedでx, yを渡すこと
ll to_idx(ll x, ll y){
  return y * N + x;
}

void to_xy(ll idx, ll &x, ll &y){
  x = idx % N;
  y = idx / N;
}

void bfs(ll cust_idx, ll org_cost, vector<ll> &cbuckets, vector<bool> &visited){


  ll x, y;
  to_xy(cust_idx, x, y);
  visited[cust_idx] = true;
  cbuckets[cust_idx] = max(0LL, cbuckets[cust_idx] - 1);

  rep(ti, 4){
    ll i = dx_4[ti];
    ll j = dy_4[ti];

    ll tmpx = x - i;
    ll tmpy = y - j;
    if (tmpx < 0 || tmpx >= N || tmpy < 0 || tmpy >= N) continue;
    else{
      ll tmpidx = to_idx(tmpx, tmpy);
      if (visited[tmpidx]) continue;
      else if (cbuckets[tmpidx] <= org_cost){
        visited[tmpidx] = true;
        continue;
      }
      else{
        assert(cbuckets[tmpidx] == org_cost + 1);
        bfs(tmpidx, org_cost+1, cbuckets, visited);
      }
    }

  }

}

void exit_xy(ll cust_x, ll cust_y, vector<ll> &cbuckets){
  ll cust_idx = to_idx(cust_x, cust_y);
  ll cust_cost = cbuckets[cust_idx];
  ans += cust_cost;

  // 今回のループで探索済みの客番号をvec<bool>で管理
  vector<bool> visited(N*N, false);

  // 今回の客の席を更新
  cbuckets[cust_idx] = max(0LL, cbuckets[cust_idx] - 1);
  visited[cust_idx] = true;
  bfs(cust_idx, cust_cost, cbuckets, visited);

}


