vector< ii > edg[2750];

void dijkstra(int start){
    priority_queue< ii, vector< ii >, greater< ii > > pq;
    memset(dist,-1,sizeof(dist));
	memset(vis,0,sizeof(vis));
	pq.push( ii(0,start));
    dist[start] = 0;
    while(!pq.empty()){
        ii cur = pq.top();
        pq.pop();
        if(vis[cur.second]){
            continue;
        }
        dist[cur.second] = cur.first;
        vis[cur.second] = true;
        rep(i,0,edg[cur.second].size()){
            ii nxt = edg[cur.second][i];
            int weight = nxt.first;
            int vertex_index = nxt.second;
            if(!vis[vertex_index]){
                pq.push(ii(weight + cur.first, vertex_index));
            }
        }
    }
}
