		ll w = val;
		if(nx == n+1 || nx == 0 || ny == n+1 || ny == 0) w = 0;
		ll nxt = ny * (n+2) + nx;
		edg[cur].pb(ii(w, nxt));
		edg[nxt].pb(ii(w, cur));
	}
}
