typedef pair<li, li> PI;

li n;
li nn;

li value[505050];
bool live[505050];

inline PI toPos(li x) {
    return {x / n, x % n};
}

inline li fromPos(PI p) {
    return p.F * n + p.S;
}

li dx[] = { -1, 1, 0, 0};
li dy[] = {0, 0, -1, 1};

int main() {
    cin >> n;
    li nn = n * n;
    rep(i, n) {
        rep(j, n) {
            li dx = min(j, n - j - 1);
            li dy = min(i, n - i - 1);
            value[fromPos({i, j})] = min(dx, dy);
            live[fromPos({i, j})] = true;
        }
    }
    li res = 0;
    rep(i, n * n) {
        li pos;
        cin >> pos;
        pos--;
        li tres = value[pos];
        res += tres;
        live[pos] = false;

        // run dijkstra
        priority_queue<PI> pq;
        pq.push({ -tres, pos});
        while (!pq.empty()) {
            li now_cost = -pq.top().F;
            li now = pq.top().S;
            pq.pop();
            //p3(i, now, now_cost);
            if (value[now] < now_cost) {
                continue;
            }
            if (value[now] == now_cost && now != pos) {
                continue;
            }
            value[now] = now_cost;
            rep(k, 4) {
                PI next = {now / n + dy[k], now % n + dx[k]};
                if (min(next.F, next.S) < 0 || max(next.F, next.S) >= n) {
                    continue;
                }
                li pn = fromPos(next);
                li next_cost = now_cost;
                if (live[now]) {
                    next_cost++;
                }
                if (value[pn] <= next_cost) {
                    continue;
                }
                pq.push({ -next_cost, pn});
