void rec(int i, int j, int d, bool st=0)
{
    if(i<0 || i>=n || j<0 || j>=n) return;
    if(vis[i][j]) return;
    if(!st && d>=dist[i][j]) return;
    vis[i][j]=1;
    v.pb({i, j});
    dist[i][j]=d;
    int add = 1 - gone[i][j];
    int dn = d + add;
    rec(i-1, j, dn);
    rec(i+1, j, dn);
    rec(i, j-1, dn);
    rec(i, j+1, dn);
}
void solve(int i, int j, int d)
{
    rec(i, j, d, 1);
    for(auto u: v)
    {
        vis[u.F][u.S]=0;
