int cal(int x,int y)
{
    if(y==0) y=n;
    int res1=0,res2=0,res3=0,res4=0;
    for(int i=x-1;i>=1;--i) if(!vis[i][y]) ++res1;
    for(int i=x+1;i<=n;++i) if(!vis[i][y]) ++res2;
    for(int j=y-1;j>=1;--j) if(!vis[x][j]) ++res3;
    for(int j=y+1;j<=n;++j) if(!vis[x][j]) ++res4;
    vis[x][y]=1;
    return min(res1,min(res2,min(res3,res4)));
}
