int bfs01(vvi &grid, vvi &dist, pii src) {
    int H = grid.size();
    int W = grid[0].size();
    vector<pii> directions = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};
    vector<vector<bool>> visited(H, vector<bool>(W, 0));
    deque<tuple<int, int, int>> que;
    int h, w, dh, dw, h2, w2, cost;

    tie(h, w) = src;
    que.pb({0, h, w});
    visited[h][w] = 1;
    dist[h][w] = 0;
    while (!que.empty()) {
        tie(cost, h, w) = que.front(); que.pop_front();
        for (auto p : directions) {
            tie(dh, dw) = p;
            h2 = h + dh;
            w2 = w + dw;
            if (h2 < 0 || w2 < 0 || h2 >= H || w2 >= W) {
                tie(h, w) = src;
                dist[h][w] = cost;
                return cost;
            }
            if (visited[h2][w2]) {
                continue;
            }
            visited[h2][w2] = 1;
            if (dist[h2][w2] == -1) {
                que.push_front({cost, h2, w2});
            } else {
                que.pb({cost+1, h2, w2});
            }
        }
    }
}

