				if(vis[x-1][y]>vis[x][y]){
					tail++;
					zhanx[tail]=x-1;
					zhany[tail]=y;
					vis[x-1][y]=vis[x][y];
				}
			}
			if(book[x+1][y]==1&&x<=n){
				if(vis[x+1][y]>vis[x][y]){
					tail++;
					zhanx[tail]=x+1;
					zhany[tail]=y;
					vis[x+1][y]=vis[x][y];
				}
			}
			if(book[x][y-1]==1&&y>=1){
				if(vis[x][y-1]>vis[x][y]){
					tail++;
					zhanx[tail]=x;
					zhany[tail]=y-1;
					vis[x][y-1]=vis[x][y];
				}
			}
