				if(vis[x][y+1]>vis[x][y]){
					tail++;
					zhanx[tail]=x;
					zhany[tail]=y+1;
					vis[x][y+1]=vis[x][y];
				}
			}
			head++;
		}
		head=now1;
		now2=tail;
		while(head<=now2){
			x=zhanx[head];
			y=zhany[head];
			if(book[x-1][y]==0&&x>=1){
				if(vis[x-1][y]>vis[x][y]+1){
					tail++;
					zhanx[tail]=x-1;
