					tail++;
					zhanx[tail]=x+1;
					zhany[tail]=y;
					vis[x+1][y]=vis[x][y]+1;
				}
			}
			if(book[x][y-1]==0&&y>=1){
				if(vis[x][y-1]>vis[x][y]+1){
					tail++;
					zhanx[tail]=x;
					zhany[tail]=y-1;
					vis[x][y-1]=vis[x][y]+1;
				}
			}
			if(book[x][y+1]==0&&y<=n){
				if(vis[x][y+1]>vis[x][y]+1){
					tail++;
					zhanx[tail]=x;
					zhany[tail]=y+1;
