    fornum(i,0,N*N){
        scanf("%lld", &P[i]);
        P[i]--;
    }
    fornum(i,0,N){
        fornum(j,0,N){
            mk[i * N + j] = min(min(i, N - i - 1), min(j, N - j - 1));
        }
    }
    g[0] = 1;
    g[1] = N;
    g[2] = -1;
    g[3] = -N;
    uf.init(N * N + 5);
    ll ans = 0;
    fornum(i,0,N*N){
        fornum(j,0,4){
            ll nx = P[i] + g[j];
            if(nx<0&&N*N<=nx)
                continue;
            if(!mk2[nx])
                continue;
            mk[P[i]] = min(mk[P[i]], mk[uf.find(nx)]);
            uf.unite(P[i], nx);
        }
        ans += mk[uf.find(P[i])];
        mk2[P[i]] = 1;

    }
    printf("%lld\n", ans);
    return 0;
}

