            if (r != n - 1) {
                if (chmin(s[r + 1][c], s[r][c] + (b[r][c] ? 0 : 1))) q.emplace_back(r + 1, c);
            }
            if (c != 0) {
                if (chmin(s[r][c - 1], s[r][c] + (b[r][c] ? 0 : 1))) q.emplace_back(r, c - 1);
            }
            if (c != n - 1) {
