void updBIT_ROW(int ind, int p, ll val = 1){ 
    p++;	// esto es porque el bit esta indexado desde 1
    for(; p < maxN; p += p&-p) // se puede cambiar maxN por n+1 si hace falta mas velocidad
    	BIT_ROW[ind][p] += val;
}
ll sumBIT_ROW(int ind, ll p){
    p++;
    ll ret = 0;
    for(; p; p -= p&-p) 
    	ret += BIT_ROW[ind][p];
    return ret;
}

void updBIT_COL(int ind, int p, ll val = 1){ 
    p++;	// esto es porque el bit esta indexado desde 1
    for(; p < maxN; p += p&-p) // se puede cambiar maxN por n+1 si hace falta mas velocidad
    	BIT_COL[ind][p] += val;
}
ll sumBIT_COL(int ind, ll p){
    p++;
    ll ret = 0;
    for(; p; p -= p&-p) 
    	ret += BIT_COL[ind][p];
    return ret;
}

