int d[4] = {0, 1, 0, -1};
long long n;
vector<long long> perm;
vector<vector<long long>> cost;
vector<vector<bool>> ch;

bool isvalid(int x, int y) { return x >= 0 && x < n && y >= 0 && y < n; }
long long solve();

int main() {
  cin >> n;
  perm.resize(n * n);
  for (auto &x : perm) {
    cin >> x;
    --x;
  }
  cout << solve() << endl;
  return 0;
}

long long solve() {
  cost.resize(n, vector<long long>(n, 0));
  ch.assign(n, vector<bool>(n, 0));
  for (int i = 0; i < n; ++i)
    for (int j = 0; j < n; ++j)
      cost[i][j] = min({(long long)i, n - 1 - i, (long long)j, n - 1 - j});
  long long res = 0;
  for (auto p : perm) {
    int x = p / n, y = p % n;
    res += cost[x][y];
    ch[x][y] = 1;
    queue<int> qu;
    qu.push(p);
    while (qu.size()) {
      int now = qu.front();
      qu.pop();
      x = now / n, y = now % n;
      for (int i = 0; i < 4; ++i) {
        int tx = x + d[i], ty = y + d[1 ^ i], c = cost[x][y];
        if (!isvalid(tx, ty)) continue;
        c += 1 - ch[x][y];
        if (c < cost[tx][ty]) {
          cost[tx][ty] = c;
          qu.push(tx * n + ty);
        }
      }
    }
  }
  return res;
}

