using namespace std;

const int DXS[] = {0, -1, 1, 0};
const int DYS[] = {-1, 0, 0, 1};

int main() {

	const int n = read_item();
	vector<int> ps(n * n);
	for(auto i : range(n * n)) {
		ps[i] = read_item();
		ps[i] = ps[i] - 1;
	}

	vector<vector<int>> dist(n);
	vector<vector<bool>> seat(n);
	for(auto& d : dist) {
		d.resize(n, 0);
	}
	for(auto& s : seat) {
		s.resize(n, true);
	}
	for(auto i : range(n)) {
		for(auto j : range(n)) {
			dist[i][j] = min(min(i, n - 1 - i), min(j, n - 1 - j));
		}
	}

	i64 ans = 0;

	for(auto p_it : range(n * n)) {

		int p = ps[p_it];
		int sx = p / n;
		int sy = p % n;

		ans += dist[sx][sy];
		seat[sx][sy] = false;

		deque<pair<int,int>> q;

		for(auto i : range(4)) {
			int x = sx + DXS[i];
			int y = sy + DYS[i];
			if(x >= 0 && y >= 0 && x < n && y < n) {
				q.push_back({x, y});
			}
		}

		while(!q.empty()) {

			int cx = q.front().first;
			int cy = q.front().second;
			q.pop_front();

			int d = dist[cx][cy];

			for(auto i : range(4)) {
				int x = cx + DXS[i];
				int y = cy + DYS[i];
				if(x >= 0 && y >= 0 && x < n && y < n) {
					int nd = dist[x][y] + (seat[x][y] ? 1 : 0);
					d = min(d, nd);
				}
			}

			if(d >= dist[cx][cy]) {
				continue;
			}
			dist[cx][cy] = d;

			for(auto i : range(4)) {
				int x = cx + DXS[i];
				int y = cy + DYS[i];
				if(x >= 0 && y >= 0 && x < n && y < n) {
					if(seat[cx][cy]) {
						q.push_back({x, y});
					} else {
						q.push_front({x, y});
					}
				}
			}
		}
	}

	printf("%lld\n", ans);

	return 0;
}

