		ans += dist[x][y];
		a[x][y] = 0;

		vector<pair<int, int>> queue;
		queue.emplace_back(x, y);
		for (size_t j = 0; j < queue.size(); j++) {
			tie(x, y) = queue[j];

			for (int dx = -1; dx <= 1; dx++)
				for (int dy = -1; dy <= 1; dy++) {
					if (abs(dx) + abs(dy) != 1) continue;

					int xx = x + dx, yy = y + dy;
					if (xx < 0 || xx >= n || yy < 0 || yy >= n) continue;
