int dx[4] = {1, -1, 0, 0};
int dy[4] = {0, 0, 1, -1};

queue<int> q;

void SPFA() {
    while(q.size()) {
        int x = q.front(); q.pop();
        int y = q.front(); q.pop();
        for (int dir = 0; dir < 4; dir++) {
            int nx = x + dx[dir];
            int ny = y + dy[dir];
            if (valid[nx][ny] && dis[nx][ny] > dis[x][y] + !done[nx][ny]) {
                dis[nx][ny] = dis[x][y] + !done[nx][ny];
                q.push(nx);
                q.push(ny);
            }
        }
    }
}

