void join(int x, int y){
	int tmp1=pa(x), tmp2=pa(y);
	if(tmp1==tmp2){
		return;
	}
	int sz1=a[tmp1].size(), sz2=a[tmp2].size();
	int mn=min(mem[tmp1], mem[tmp2]);
	if(sz1>sz2){
		for(auto it:a[tmp2]){
