		}
		par[tmp2]=tmp1;
		mem[tmp1]=mn;
		if(a[tmp1].find(y)!=a[tmp1].end()){
			a[tmp1].erase(a[tmp1].find(y));
		}
		if(a[tmp1].find(x)!=a[tmp1].end()){
			a[tmp1].erase(a[tmp1].find(x));
		}
	}
	else{
		for(auto it:a[tmp1]){
			a[tmp2].insert(it);
		}
		par[tmp1]=tmp2;
		mem[tmp2]=mn;
		if(a[tmp2].find(x)!=a[tmp2].end()){
			a[tmp2].erase(a[tmp2].find(x));
		}
		if(a[tmp2].find(y)!=a[tmp2].end()){
