template <typename T>
class que : public queue<T> {
    using parent = queue<T>;
public:
    que() : parent() {}

    que(const que<T>& q) : parent(q) {}

    que(que<T>&& q) noexcept: parent(move(q)) {}

    T pop() {
#ifdef LOCAL
        if (parent::empty()) {
            throw "Pop on empty queue";
        }
#endif
        T res = parent::front();
        parent::pop();
        return res;
    }

    que<T>& operator=(que<T>&& __x) noexcept {
        parent::operator=(__x);
        return *this;
    }

    que<T>& operator=(const que<T>& __x) {
        parent::operator=(__x);
        return *this;
    }
};

using qi = que<int>;


class BJoker {
public:
    void solve() {
        int n = in.readInt();
        auto p = in.readIntArray(n * n);
        decreaseByOne(p);

        arr2d<bool> done(n, n, false);
        arr2d<int> dist(n, n);
        for (int i : range(n)) {
            for (int j : range(n)) {
                dist(i, j) = min({i, j, n - 1 - i, n - 1 - j});
            }
        }
        ll answer = 0;
        for (int i : p) {
            int r = i / n;
            int c = i % n;
            answer += dist(r, c);
            done(r, c) = true;
            que<pii> q;
            q.emplace(r, c);
            while (!q.empty()) {
                r = q.front().first;
                c = q.pop().second;
                int cost = dist(r, c) + (done(r, c) ? 0 : 1);
                for (int j : range(4)) {
                    int nr = r + DX4[j];
                    int nc = c + DY4[j];
                    if (isValidCell(nr, nc, n, n) && dist(nr, nc) > cost) {
                        dist(nr, nc) = cost;
                        q.emplace(nr, nc);
                    }
                }
            }
        }
        out.printLine(answer);
    }
};


