  //showv2(c);
  //rep(i,n*n) show3(i,i/3+1,i%3+1);

  auto bfs = [&](int sy, int sx, int gy, int gx) {
    //vvi d(n,vi(n,INF));
    vvi d(n+2,vi(n+2,INF));
    d[sy][sx] = 0;
    //vv(P) prev(h,v(P)(w,P(-1,-1)));
    //int sy = 0, sx = 0, gy = h-1, gx = w-1;
    queue<P> q;
    q.push(P(sy,sx));
    while(!q.empty()) {
      P p = q.front(); q.pop();
      int y = p.fi, x = p.se;
      if (y == gy && x == gx) break;
      //if (y == 0 || y == n+1 || x == 0 || x == n+1) break;
      rep(i,4) {
