        //if (c[ny][nx] == 'X') continue;
        if (d[ny][nx] != INF) continue;
        //d[ny][nx] = d[y][x] + 1;
        d[ny][nx] = d[y][x] + (c[ny][nx]== -2 || c[ny][nx] == -1 ? 0 : 1);
        //prev[ny][nx] = P(y,x);
        q.push(P(ny,nx));
      }
    }
    return d[gy][gx];
  };

  ll ans = 0;
