    int sy = p/n+1;
    int sx = p%n+1;

    int res = INF;
    srep(j,1,n+1) {
      int gy = 0;
      int gx = j;
      int d = bfs(sy,sx,gy,gx);
      chmin(res, d);
    }

    srep(j,1,n+1) {
      int gy = n+1;
      int gx = j;
