        int y = (P-1) / N + 1;
        int x = (P-1) % N + 1;
        memcpy(minHated.data(), minHatedInf.data(), sizeof(int) * gridSize());
        setAt(x, y, minHated, 0);
        ans += getMinHated(x, y);
