constexpr ll N = 505;
ll dp[N][N];
bool used[N][N];
ll di[4] = {-1, 1, 0, 0};
ll dj[4] = {0, 0, -1, 1};

void solve(){
    ll n; cin >> n;
    rep(i, n)rep(j, n){
        dp[i][j] = min((ll)min(i, j), (ll)min(n - i - 1, n - j - 1));
        used[i][j] = true;
    }

    ll ans = 0;
    rep(_, n * n){
        ll p; cin >> p; p--;
        ll i = p / n, j = p % n;
        ans += dp[i][j];
        used[i][j] = false;
        // dfs
        vector<pair<ll, ll>> stack{{i, j}};
        while(stack.size()){
            auto [i, j] = stack.back(); stack.pop_back();
            rep(t, 4){
                ll ni = i + di[t], nj = j + dj[t];
                if(!(0 <= ni and ni < n and 0 <= nj and nj < n)){
                    continue;
                }
                if(chmin(dp[ni][nj], dp[i][j] + used[i][j])){
                    stack.emplace_back(ni, nj);
                }
            }
        }
    }

    cout << ans << '\n';
}

