ll bfs(ll x,ll y){
    fill(passed[0],passed[0]+502*502,false);
    priority_queue<vector<ll>> que;

    vector<ll> v={0,x,y};
    que.push(v);
    passed[x][y]=true;

    while(que.size()){
        vector<ll> t=que.top(); que.pop();

        if(t[1]==0||t[1]==n+1||t[2]==0||t[2]==n+1){
            return -t[0];
        }//終了条件
        for(ll i=0;i<4;i++){ //tについて探索
            ll xx=t[1]+dx[i];
            ll yy=t[2]+dy[i];
            if(!passed[xx][yy]){
                que.push({t[0]-occupied[xx][yy],xx,yy});
                passed[xx][yy]=true;
            }
        }
    }
    return 0;
}

