const int MAXN = 505;

int n,ans;
int f[MAXN][MAXN];

bool vis[MAXN][MAXN];

queue<pair<int,int> > Q;

int main()
{
	scanf("%d",&n);
	for (int i = 1;i <= n;i++)
		for (int j = 1;j <= n;j++)
		{
			vis[i][j] = 1;
			f[i][j] = min(min(i - 1,j - 1),min(n - i,n - j)) + 1;
		}
	for (int p,i = 1;i <= n * n;i++)
	{
		scanf("%d",&p);
		int x = (p - 1) / n + 1,y = p - (x - 1) * n;
		ans += f[x][y] - 1;
		vis[x][y] = 0;
		f[x][y] = min(min(f[x - 1][y],f[x][y - 1]),min(f[x + 1][y],f[x][y + 1]));
		Q.push(make_pair(x,y));
		while (!Q.empty())
		{
			x = Q.front().first,y = Q.front().second;
			Q.pop();
			if (x > 1 && f[x - 1][y] > f[x][y] + vis[x - 1][y])
			{
				f[x - 1][y] = f[x][y] + vis[x - 1][y];
				Q.push(make_pair(x - 1,y));
			}
			if (y > 1 && f[x][y - 1] > f[x][y] + vis[x][y - 1])
			{
				f[x][y - 1] = f[x][y] + vis[x][y - 1];
				Q.push(make_pair(x,y - 1));
			}
			if (x < n && f[x + 1][y] > f[x][y] + vis[x + 1][y])
			{
				f[x + 1][y] = f[x][y] + vis[x + 1][y];
				Q.push(make_pair(x + 1,y));
			}
			if (y < n && f[x][y + 1] > f[x][y] + vis[x][y + 1])
			{
				f[x][y + 1] = f[x][y] + vis[x][y + 1];
				Q.push(make_pair(x,y + 1));
			}
		}
	}
	printf("%d\n",ans);
	return 0;
}

#include <iostream>//TLE
