constexpr int nax = 500;

const pair< int, int > adj[] = {{1, 0}, {0, 1}, {-1, 0}, {0, -1}};

int n, res;
pair< int, int > tab[nax * nax]; // cords sorted by order of leaving cinema
bool gone[nax][nax]; // is certain viewer gone
int dis[nax][nax]; // distances from exit

pair< int, int > operator+(const pair< int, int >& a, const pair< int, int >& b)
{ return {a.first + b.first, a.second + b.second}; }

bool valid(const pair< int, int >& v)
{ return 0 <= v.first and v.first < n and 0 <= v.second and v.second < n; }

void dfs(const pair< int, int > v)
{
    int old_dis = dis[v.first][v.second];

    for (auto off : adj)
    {
        auto s = off + v;
        if (not valid(s))
            continue;
        dis[v.first][v.second] = min(
            dis[v.first][v.second], dis[s.first][s.second] + !gone[s.first][s.second]
        );
    }

    if (old_dis > dis[v.first][v.second])
        for (auto off : adj)
            if (valid(off + v))
                dfs(off + v);
}

int main()
{
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> n;

    for (int i = 0; i < n * n; ++i)
    {
        int v; cin >> v; --v;
        tab[i] = {v / n, v % n};
    }

    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j)
            dis[i][j] = min({i, j, n - 1 - i, n - 1 - j});

    for (int i = 0; i < n * n; ++i)
    {
        pair< int, int > v = tab[i];
        res += dis[v.first][v.second];
        gone[v.first][v.second] = true;

        for (auto off : adj)
            if (valid(off + v))
                dfs(off + v);
    }

    cout << res << '\n';
}

