int odrad[N][N][N / 2];
queue < pair < pii, int > > Q[N * N];

const int px[4] = {1, -1, 0, 0};
const int py[4] = {0, 0, 1, -1};

inline int get_dis(int x, int y){
	return min(min(x, y), n - max(x, y) - 1);
}

int main(){
	memset(dis, INF, sizeof(dis));
	memset(odrad, -1, sizeof(odrad));
	scanf("%d", &n);
	for(int i = 0;i < n * n;i++){
		int x; scanf("%d", &x); x--;
		P[x % n][x / n] = i;
	}
	for(int i = 0;i < n;i++){
		Q[0].push({{0, i}, 0}); dis[0][i][0] = 0;
		Q[0].push({{n - 1, i}, 0}); dis[n - 1][i][0] = 0;	
		Q[0].push({{i, 0}, 0}); dis[i][0][0] = 0;
		Q[0].push({{i, n - 1}, 0}); dis[i][n - 1][0] = 0;		
	}
	for(int i = 0;i < n * n;i++){
		for(;!Q[i].empty();Q[i].pop()){
			int cx = Q[i].front().X.X;
			int cy = Q[i].front().X.Y;
			int ck = Q[i].front().Y;
			if(ck && dis[cx][cy][ck - 1] <= dis[cx][cy][ck])
				continue;
			for(int m = 0;m < 4;m++){
				int mx = cx + px[m], my = cy + py[m];
				if(mx < 0 || mx >= n || my < 0 || my >= n) continue;
				if(max(dis[cx][cy][ck], P[cx][cy]) < dis[mx][my][ck]){
					dis[mx][my][ck] = max(dis[cx][cy][ck], P[cx][cy]);
					Q[dis[mx][my][ck]].push({{mx, my}, ck});
				}
				if(ck < get_dis(mx, my) && dis[cx][cy][ck] < dis[mx][my][ck + 1]){
					dis[mx][my][ck + 1] = dis[cx][cy][ck];
					Q[dis[cx][cy][ck]].push({{mx, my}, ck + 1});
				}
			}
		}
	}
	int odg = 0;
	for(int i = 0;i < n;i++){
		for(int j = 0;j < n;j++){
			int k = 0;
			for(;dis[i][j][k] > P[i][j];k++);
			odg += k;
		}
	}
	printf("%d\n", odg);
	return 0;
}

