int vx[]={ 0, 1, 0,-1};
int vy[]={ 1, 0,-1, 0};

bool min_u(int&m, int v)
{
	if(m>v)
	{
		m=v;
		return true;
	}
	return false;
}


int get_armin(vvi&f, int x, int y)
{
	int ret=999999;

	for(int d=0;d<4;d++)
	{
		int nx=x+vx[d];
		int ny=y+vy[d];
		min_u(ret, f[ny][nx]);
	}
	return ret;
}


void remove(int n, vvi&f, vvi&used, int x, int y)
{
	used[y][x]=0;
	f[y][x]=get_armin(f, x, y);

	queue<pair<int,int> > q;
	q.push(make_pair(x, y));
	while(!q.empty())
	{
//printf("x=%d y=%d\n", x, y);
		tie(x, y)=q.front();
		q.pop();
		for(int d=0;d<4;d++)
		{
			int nx=x+vx[d];
			int ny=y+vy[d];
			if(f[ny][nx]<0) continue;

			int v=get_armin(f, nx, ny);
			if(min_u(f[ny][nx], v+used[ny][nx]))
			{
				q.push(make_pair(nx, ny));
			}
		}
	}
}


int solve(int n, vvi&f, vi&p)
{
	int ret=0;
	vvi used(n+2);
	for(auto&m:used) m.assign(n+2, 1);

	for(int m:p)
	{
		int x=(m-1)%n+1;
		int y=(m-1)/n+1;

		ret+=f[y][x];
		remove(n, f, used, x, y);
	}

	return ret;
}


int main(void)
{
	int n;
	while(scanf("%d", &n)==1)
	{
		vi p(n*n);
		for(auto&mp:p) scanf("%d", &mp);

		vvi f(n+2);
		for(auto&mf:f) mf.assign(n+2, -1);

		for(int y=1;y<=n;y++)
		{
			for(int x=1;x<=n;x++)
			{
				int v=x-1;
				min_u(v, n-x);
				min_u(v, y-1);
				min_u(v, n-y);
				f[y][x]=v;
			}
		}

		printf("%d\n", solve(n, f, p));
	}
	return 0;
}

