    dist = vector<vector<int>>(n, vector<int>(n));
    have = vector<vector<int>>(n, vector<int>(n, 1));
    for (int i = 0; i < n; ++i) {
      for (int j = 0; j < n; ++j) {
        dist[i][j] = min(i, min(j, min(n - 1 - i, n - 1 - j)));
      }
    }
    int res = 0;
    for (int at : p) {
      int r = at / n;
      int c = at % n;
      have[r][c] = 0;
      res += dist[r][c];
      for (int dr = -1; dr <= 1; ++dr) {
        for (int dc = -1; dc <= 1; ++dc) if (abs(dr) + abs(dc) == 1) {
          upd(r + dr, c + dc, dist[r][c]);
        }
      }
    }
    out << res << "\n";
  }

  void solve(std::istream &in, std::ostream &out) {
    int nt = 1;
    for (int it = 0; it < nt; ++it) {
      solveOne(in, out);
    }
  }
};


int main() {
  ios_base::sync_with_stdio(false);
  cin.tie(NULL);
  TaskB solver;
  std::istream& in(std::cin);
  std::ostream& out(std::cout);
  solver.solve(in, out);
  return 0;
}

