bool isVisited[501][501];

void update(vector<vector<int>> &dp, int r, int c, int val)
{
    if(r < 0 || r >= dp.size() || c <0 || c >= dp.size() || dp[r][c] <= val)
        return;

    dp[r][c] = val;
    if( isVisited[r][c])
    {
        update(dp,r-1,c,val);
        update(dp,r,c-1,val);
        update(dp,r+1,c,val);
        update(dp,r,c+1,val); 
    }
    else
    {
        update(dp,r-1,c,val+1);
        update(dp,r,c-1,val+1);
        update(dp,r+1,c,val+1);
        update(dp,r,c+1,val+1);
    }
}


