template <class F>
class FixPoint : private F {
public:
    explicit constexpr FixPoint(F &&f) : F(std::forward<F>(f)) {}
    template <class... Args>
    constexpr decltype(auto) operator()(Args &&... args) const { return F::operator()(*this, std::forward<Args>(args)...); }
};
template <class F>
constexpr decltype(auto) funcs(F &&f) { return FixPoint<F>{std::forward<F>(f)}; }
template <class T>
std::vector<T> vecs(int n, T &&val) { return std::vector<T>(std::forward<int>(n), std::forward<T>(val)); }
template <class... Args>
decltype(auto) vecs(int n, Args &&... args) { return std::vector<decltype(vecs(std::forward<Args>(args)...))>(std::forward<int>(n), vecs(std::forward<Args>(args)...)); }
template <class V, class T>
void fill(V &x, const T &val) { x = val; }
template <class V, class T>
void fill(vector<V> &vec, const T &val) {
    for (auto &&v : vec)
        fill(v, val);
}

template <class T, class U>
struct fpair {
    T first;
    U second;
    fpair(T fi = T(), U se = U()) : first(fi), second(se) {}
    bool operator<(const fpair &x) const {
        return first < x.first;
    }
    bool operator>(const fpair &x) const {
        return first > x.first;
    }
};

void solve() {
    int n;
    cin >> n;
    vector<int> p(n * n);
    rep(i, n * n) cin >> p[i];

    auto h = vecs(n, n, int());
    auto seated = vecs(n, n, bool(true));
    rep(i, n) rep(j, n) h[i][j] = min({i, j, n - 1 - i, n - 1 - j});

    int ans = 0;
    const int dx[] = {1, 0, -1, 0};
    const int dy[] = {0, -1, 0, 1};
    each(val, p) {
        int x = (val - 1) / n;
        int y = (val - 1) % n;
        ans += h[x][y];
        seated[x][y] = false;
        priority_queuel<fpair<int, pair<int, int>>> que;
        que.emplace(h[x][y], make_pair(x, y));
        while (!que.empty()) {
            auto p = que.top();
            que.pop();
            auto x = p.second.first;
            auto y = p.second.second;
            if (h[x][y] != p.first) continue;
            rep(i, 4) {
                auto nx = x + dx[i];
                auto ny = y + dy[i];
                if (nx < 0 || nx >= n || ny < 0 || ny >= n) continue;
                if (h[nx][ny] > h[x][y] + seated[x][y]) {
                    h[nx][ny] = h[x][y] + seated[x][y];
                    que.emplace(h[nx][ny], make_pair(nx, ny));
                }
            }
        }
    }
    cout << ans << endl;
}

signed main() {
    cin.tie(nullptr);
    ios::sync_with_stdio(false);
    cout << fixed << setprecision(15);
    solve();
    cout.flush();
    return 0;
}

