void update(int** field, int n,int r,int c) {
	bool flag = false;
	if (field[r][c] % 2 == 1) {
		flag = true;
		field[r][c]--;
	}
	if (r < n - 1) {
		if (field[r + 1][c] > field[r][c]) {
			update(field, n, r + 1, c);
		}	
	}
	if (c > 0) {

			if (field[r][c - 1] > field[r][c]) {
				update(field, n, r, c - 1);
			}

	}

	if (c < n - 1) {

			if (field[r][c + 1] > field[r][c]) {
				update(field, n, r, c + 1);
			}


	}
	if (r > 0) {

			if (field[r - 1][c] > field[r][c]) {
				update(field, n, r - 1, c);
			}
	}
	if (flag) {
		field[r][c]++;
	}
	field[r][c]-=2;
}

