        cost = dp[x][y];
        ans += cost;
        seated[x][y] = false;
        queue<int> q;
        q.push(pos);
        while(!q.empty()){
            pos = q.front(); q.pop();
            x = pos / N; y = pos % N;
            if (seated[x][y]) {
                cost = dp[x][y]+1;
            } else {
                cost = dp[x][y];
            }
            REP(t, 4) {
                nx = x + dx[t]; ny = y + dy[t];
                if( nx < 0 || N <= nx || ny < 0 || N <= ny ) continue;
                if( dp[nx][ny] > cost ) {
                    dp[nx][ny] = cost;
                    q.push(nx*N+ny);
                }
            }
        }
    }

    print(ans);

    return 0;
}

