template<class T, T n>
struct mod_t
{
    static_assert(n > 0, "invalid divisor");

    T value;

    constexpr mod_t() : value() { }
    constexpr mod_t(T x) : value(normalize(x)) { }
    constexpr mod_t(const mod_t& x) : value(normalize(x.value)) { }

    explicit constexpr operator T() const {
        return value;
    }
    constexpr auto operator+(mod_t<T, n> right) const {
        return mod_t<T, n> { (value + right.value) % n };
    }
    constexpr auto& operator+=(mod_t<T, n> right) {
        return *this = *this + right;
    }
    constexpr auto& operator++() {
        return *this = *this + mod_t<T, n>(1);
    }
    constexpr auto operator++(int) {
        decltype(*this) tmp(*this);
        *this = *this + mod_t<T, n>(1);
        return tmp;
    }
    constexpr auto operator-(mod_t<T, n> right) const {
        return mod_t<T, n> { (value - right.value + n) % n };
    }
    constexpr auto& operator-=(mod_t<T, n> right) {
        return *this = *this - right;
    }
    constexpr auto& operator--() {
        return *this = *this - mod_t<T, n>(1);
    }
    constexpr auto operator--(int) {
        decltype(*this) tmp(*this);
        *this = *this - mod_t<T, n>(1);
        return tmp;
    }
    constexpr auto operator*(mod_t<T, n> right) const {
        return mod_t<T, n> { (value * right.value) % n };
    }
    constexpr auto& operator*=(mod_t<T, n> right) {
        return *this = *this * right;
    }
    constexpr auto operator/(mod_t<T, n> right) const {
        return *this * right.pow(n - 2);
    }
    constexpr auto& operator/=(mod_t<T, n> right) {
        return *this = *this / right;
    }
    constexpr auto pow(ll nn) const {
        return fast_pow(*this, nn);
    }
    constexpr auto inv() const {
        return pow(n - 2);
    }

    static constexpr auto normalize(T x) {
        if (x < 0) {
            return (n + x % n) % n;
        } else {
            return x % n;
        }
    }
};
template<class T, T n>
auto& operator>>(istream& in, mod_t<T, n>& out) {
