public:
    combi_t() : factn(0), ifactn(0), maxn(0) { }

    combi_t(ll maxn)
        : factn(maxn + 1)
        , ifactn(maxn + 1)
    {
        init(maxn);
    }

    void init(ll maxn) {
        factn.resize(maxn + 1);
        ifactn.resize(maxn + 1);

        this->maxn = maxn;
        factn[0] = 1;
        ifactn[0] = 1;
        for (ll i = 1; i <= maxn; ++i) {
            factn[i] = i * factn[i - 1];
            ifactn[i] = value_t(i).inv() * ifactn[i - 1];
        }
    }

    constexpr auto combi(ll a, ll b) const {
        if (b <= 0 || a - b <= 0) {
            return value_t(1);
        } else {
            return factn[a] * ifactn[b] * ifactn[a - b];
        }
    }

    constexpr auto perm(ll a, ll b) const {
        return factn[a] * ifactn[a - b];
    }

    constexpr auto operator()(ll a, ll b) const {
        return combi(a, b);
    }
};
#define USE_COMBI(maxn) combi_t<ll, MOD> combi(maxn);

template<class T>
auto fast_pow(T a, ll n) {
    if (n <= 0) {
        return T(1);
    } else if (n == 1) {
        return T(a);
    } else if (n % 2 == 0) {
        auto work = fast_pow(a, n / 2);
        return work * work;
    } else {
        return fast_pow(a, n - 1) * a;
    }
}

ll gcd(ll a, ll b)
{
    if (a < b) {
        return gcd(b, a);
    }
    ll r;
    while (r = a % b) {
        a = b;
        b = r;
    }
    return b;
}

