int dy[] = {0, 0, -1, 1};

bool valid(int gg) {
	return gg >= 0 && gg < n;
}

int has[500][500];
int vis[500][500];

void dfs(int x, int y, int cx) {
	vis[x][y] = cx;
	for (int i = 0; i < 4; i++) {
		int nx = x + dx[i];
		int ny = y + dy[i];

		if (valid(nx) && valid(ny) && vis[nx][ny] != cx) {
			if (cost[nx][ny] > cost[x][y] + has[x][y]) {
				cost[nx][ny] = cost[x][y] + has[x][y];
				dfs(nx, ny, cx);
			}
		}
	}
}

