const int DI[4] = { 0, 0, +1, -1 };
const int DJ[4] = { +1, -1, 0, 0 };
int main() {
    int N; cin >> N;
    vector<int> P(N * N); for (auto &p : P) cin >> p, p--;
    vector<vector<int>> A(N, vector<int>(N)), B(N, vector<int>(N));
    for (int i = 0; i < N; i++) {
        for (int j = 0; j < N; j++) {
            A[i][j] = min({ abs(i - 0), abs(i - (N - 1)), abs(j - 0), abs(j - (N - 1)) });
            B[i][j] = 1;
        }
    }
    Int ans = 0;
    for (int p : P) {
        int i = p / N, j = p % N;
        ans += A[i][j];
        B[i][j] = 0;
        queue<pair<int, int>> Q;
        Q.emplace(i, j);
        while (!Q.empty()) {
            auto [i, j] = Q.front(); Q.pop();
            for (int k = 0; k < 4; k++) {
                int ni = i + DI[k];
                int nj = j + DJ[k];
                if (0 <= ni && ni < N && 0 <= nj && nj < N && A[i][j] + B[i][j] < A[ni][nj]) {
                    A[ni][nj] = A[i][j] + B[i][j];
                    Q.emplace(ni, nj);
                }
            }
        }
    }
    cout << ans << endl;
    return 0;
}

