using LL = long long;
using PII = pair<int, int>;

int main() {
	ios_base::sync_with_stdio(0);
	cin.tie(0);

	int n;
	cin >> n;
	int q = n * n;
	vector<int> p(q);
	REP(i, q) cin >> p[i], p[i]--;

	int inf = 1e9;
	vector<int> dst(q + 1, inf), w(q, 1);
	priority_queue<PII> Q;

	auto is_edge = [&](int i) {
		return (i < n || i % n == 0 || i % n == (n - 1) || q - n <= i);
	};

	REP(i, q) {
		if(is_edge(i)) {
			dst[i] = 1;
			Q.emplace(-dst[i], i);
		}
	}

	auto bfs = [&]() {
		while(!Q.empty()) {
			int v = Q.top().ND;
			Q.pop();

			for(int d : {-1, +1, -n, +n}) {
				int u = v + d;
				if(0 <= u && u < q) {
					if(dst[u] > dst[v] + w[u]) {
						dst[u] = dst[v] + w[u];
						Q.emplace(-dst[u], u);
					}
				}
			}
		}
	};

	bfs();

	LL ans = 0;
	REP(i, q) {
		if(is_edge(p[i])) {
			dst[p[i]] = 0;
			Q.emplace(0, p[i]);
		}
		else for(int d : {-1, +1, -n, +n}) {
			int u = p[i] + d;
			if(0 <= u && u < q)
				Q.emplace(-dst[u], u);
		}

		w[p[i]] = 0;	
		bfs();
		ans += dst[p[i]];	
	}

	cout << ans << "\n";
}

