void dfs(int y, int x, int c, int f) {
	if (y < 1 || x < 1 || y > n || x > n) return;
	if (f && r[y][x] <= c) return;
	r[y][x] = c;
	dfs(y-1,x,r[y][x]+z[y][x],1);
	dfs(y+1,x,r[y][x]+z[y][x],1);
	dfs(y,x-1,r[y][x]+z[y][x],1);
	dfs(y,x+1,r[y][x]+z[y][x],1);
}

