    }

    lli ans = 0;
    REP(_,0,n*n){
        lli a;
        cin>>a;
        lli nowY = (a-1)/n+1;
        lli nowX = (a-1)%n+1;

        priority_queue< pair< lli, pair<lli,lli> >,
                        vector< pair <lli, pair<lli,lli> > >,
                        greater< pair <lli, pair<lli,lli> > > >  q;
        q.push({dd[nowY][nowX],{nowX,nowY}});
        set<pair<lli,lli>> s;

        lli dx[4]={-1,0,1,0};
        lli dy[4]={0,1,0,-1};

        while(q.size()){
            pair<lli,lli> now = q.top().second;
            lli nowD = q.top().first;
            lli nowX = now.first;
            lli nowY = now.second;
            q.pop();
            if(nowX<=-1 || nowX >= n+2 || nowY <= -1 || nowY >= n+2)continue;
            s.insert({nowX,nowY});

            if(nowX == 0 || nowX == n+1 || nowY == 0 || nowY == n+1){
                LOG4(a,nowY,nowX,nowD);
                ans += (nowD-1);
