                lli nx = nowX+dx[k];
                lli ny = nowY+dy[k];
                if(s.find({nx,ny}) != s.end())continue;
                q.push({nowD+dd[ny][nx],{nx,ny}});
            }
        }
        dd[nowY][nowX] = 0;
    }
    cout<<ans<<endl;


    return 0;
}

