        {
            pair<int, int> u = dq.front();
            dq.pop_front();
            int i = u.first, j = u.second;

            if (vis[i][j] == vid)
                continue;

            if (!i || !j || i == n - 1|| j == n - 1)
                return dist[i][j];

            vis[i][j] = vid;

            rep(mv, 0, 4)
            {
                int ni = i + di[mv], nj = j + dj[mv];
                if (valid(ni, nj))
                {
                    int w = danger[ni][nj];


                    if ((dist[ni][nj] > dist[i][j] + w && assigned[ni][nj] == vid) || assigned[ni][nj] != vid)
                    {
                        dist[ni][nj] = dist[i][j] + w;
                        assigned[ni][nj] = vid;
                        if (w)
                            dq.push_back({ni, nj});
                        else
                        {
                            dq.push_front({ni, nj});
                            size++;
                        }
                    }
                }
            }
        }
    }
    assert(false);
}

