int N = 500;

inline int gridSideLength() {
    return N+2;
}

inline int gridSize() {
    return gridSideLength() * gridSideLength();
}

int xyToIndex(int x, int y) {
    return gridSideLength() * y + x -1;
}

int getAt(int x, int y, vector<int>& grid) {
