int dy[] = { -1, 0, 0, 1 };
int dx[] = { 0, -1, 1, 0 };

//! get the min number of people who would hate me, when I get out from (x, y)
int getMinHated(int x, int y) {
    int best = INF;
    queue<pair<int, int>> q;
    q.push({x, y});
    while (!q.empty()) {
        int currX = q.front().first;
        int currY = q.front().second;
        int currV = getAt(currX, currY, minHated);
        q.pop();
        if (best <= currV) continue;
        bool foundExit = false;
        rep(i, 4) {
            int nextX = currX + dx[i];
            int nextY = currY + dy[i];
            if (getAt(nextX, nextY, occupied) == EXIT) {
                best = min(best, currV);
                foundExit = true;
                break;
            }
        }
        if (!foundExit) {
            rep(i, 4) {
                int nextX = currX + dx[i];
                int nextY = currY + dy[i];
                if (getAt(nextX, nextY, occupied) == GONE) {
                    if (currV < getAt(nextX, nextY, minHated)) {
                        setAt(nextX, nextY, minHated, currV);
                        q.push({nextX, nextY});
                    }
                } else if (getAt(nextX, nextY, occupied) == OCCUPIED) {
                    if (currV+1 < getAt(nextX, nextY, minHated)) {
                        setAt(nextX, nextY, minHated, currV+1);
                        q.push({nextX, nextY});
                    }
                }
            }
        }
    }
    return best;
}

