void bfs(ll cust_idx, ll org_cost, vector<ll> &cbuckets, vector<bool> &visited, vector<bool> &occ_buckets){

  ll x, y;
  to_xy(cust_idx, x, y);
  visited[cust_idx] = true;

  rep(ti, 4){
    ll i = dx_4[ti];
    ll j = dy_4[ti];

    ll tmpx = x - i;
    ll tmpy = y - j;
    if (tmpx < 0 || tmpx >= N || tmpy < 0 || tmpy >= N) continue;
    else{
      ll tmpidx = to_idx(tmpx, tmpy);
      if (visited[tmpidx]) continue;
      else if (cbuckets[tmpidx] <= org_cost + occ_buckets[cust_idx]){
        visited[tmpidx] = true;
        continue;
      }
      else{
        assert(cbuckets[tmpidx] == org_cost + occ_buckets[cust_idx] + 1);
        cbuckets[tmpidx]--;
        // 見つけたマスから更にbfs
        bfs(tmpidx, cbuckets[tmpidx] + occ_buckets[tmpidx], cbuckets, visited, occ_buckets);
      }
    }

  }

