  // 0-indexed!!
  vector<ll> cbuckets(N*N, 0);
  vector<bool> occ_buckets(N*N, true);

  if (N%2==0){
    // 偶数の場合
    rep(x, N / 2){
      rep(y, N / 2){
        // 0 ~ y ( y <= N / 2 - 1 ) までの数字を使って埋める
        rep(i, N / 2){
          cbuckets[to_idx(i, y)] = min(y, i);
          cbuckets[to_idx(N-1-i, y)] = min(y, i);
          cbuckets[to_idx(i, N-1-y)] = min(y, i);
          cbuckets[to_idx(N-1-i, N-1-y)] = min(y, i);
        }
      }
    }
  }
  else{
    // 奇数の場合
    rep(x, N / 2){
      rep(y, N / 2){
        // 0 ~ y ( y <= N / 2 - 1 ) までの数字を使って埋める
        rep(i, N / 2){
          cbuckets[to_idx(i, y)] = min(y, i);
          cbuckets[to_idx(N-1-i, y)] = min(y, i);
          cbuckets[to_idx(i, N-1-y)] = min(y, i);
          cbuckets[to_idx(N-1-i, N-1-y)] = min(y, i);
        }
      }
    }
    // 十字に埋める
    rep(xy, N / 2 + 1){
      if (xy == N / 2) cbuckets[to_idx(xy, xy)] = xy;
      else{
        cbuckets[to_idx(xy, N / 2)] = xy;
        cbuckets[to_idx(N-1 - xy, N / 2)] = xy;
        cbuckets[to_idx(N / 2, xy)] = xy;
        cbuckets[to_idx(N / 2, N-1 - xy)] = xy;
      }
    }
  }

