#include <iostream>
#include <vector>
#include <queue>
using namespace std;
using pairint = pair<int, int>;
using queIntDijkstra = priority_queue<pairint, vector<pairint>, greater<pairint>>;

int main(void){
    int N, Pbuf;
    vector<int> P;
    cin >> N;
    for(int i=0; i<N*N; i++){
        cin >> Pbuf;
        P.push_back(Pbuf);
    }
    vector<vector<int>> Graph(N*N+1);
    for(int i=1; i<=N*N; i++){
        if(i%N == 1){
            Graph[i].push_back(0);
        }else Graph[i].push_back(i-1);
        if(i%N == 0){
            Graph[i].push_back(0);
        }else Graph[i].push_back(i+1);
        if(i<=N){
            Graph[i].push_back(0);
        }else Graph[i].push_back(i-N);
        if(i>N*N-N){
            Graph[i].push_back(0);
        }else Graph[i].push_back(i+N);
    }
    vector<bool> Occupied(N*N+1, true);
    int res = 0;
    Occupied[0] = false;
    for(int i=0; i<N*N; i++){
        vector<bool> Visited(N*N+1, false);
        queIntDijkstra que;
        que.push(pairint(0, P[i]));
        Occupied[P[i]] = false;
        int hated = 0;
        while(!que.empty()){
            pairint curStatus = que.top();
            que.pop();
            if(Visited[curStatus.second])continue;
            if(curStatus.second == 0){
                hated = curStatus.first;
                break;
            }
            Visited[curStatus.second] = true;
            for(int nxtPoint: Graph[curStatus.second]){
                if(Visited[nxtPoint])continue;
                if(Occupied[nxtPoint]){
                    que.push(pairint(curStatus.first+1, nxtPoint));
                }else que.push(pairint(curStatus.first, nxtPoint));
            }
        }
        res += hated;
    }
    cout << res << endl;
    return 0;
}

