    for (int j = 0; j < N; j++) {
      chmin(dp[i][j], i);
      chmin(dp[i][j], j);
      chmin(dp[i][j], N - 1 - i);
      chmin(dp[i][j], N - 1 - j);
      p[i * N + j]--;
    }
  }
  int ans = 0;
