using namespace std;

vi dy = {1, 0, -1,  0};
vi dx = {0, 1,  0, -1};
void solve() {
  int n;
  scan(n);
  vi p(n*n, 0);
  scan(p);
  rep (i, n*n) {
    p.at(i) -= 1;
  }
  vvi dist(n, vi(n, 0));
  rep (i, (n+1) / 2) {
    int min_val = i;
    int max_val = n - i;
    FOR (j, min_val, max_val) {
      dist.at(min_val).at(j) = i;
      dist.at(max_val - 1).at(j) = i;
      dist.at(j).at(min_val) = i;
      dist.at(j).at(max_val - 1) = i;
    }
  }
  vvi seated(n, vi(n, 1));
  int ans = 0;
  deque<int> q;
  rep (i, n*n) {
    int y = p.at(i) / n;
    int x = p.at(i) % n;
    ans += dist.at(y).at(x);
    seated.at(y).at(x) = 0;
    rep (k, 4) {
      int ny = y + dy.at(k);
      int nx = x + dx.at(k);
      if (ny < 0 || n <= ny || nx < 0 || n <= nx) { continue; }
      int new_dist = dist.at(ny).at(nx) + seated.at(ny).at(nx);
      dist.at(y).at(x) = min(dist.at(y).at(x), new_dist);
    }
    q = {y * n + x};
    while (!q.empty()) {
      int u = q.front();
      q.pop_front();
      int uy = u / n;
      int ux = u % n;
      rep (k, 4) {
        int ny = uy + dy.at(k);
        int nx = ux + dx.at(k);
        if (ny < 0 || n <= ny || nx < 0 || n <= nx) { continue; }
        int new_dist = dist.at(uy).at(ux) + seated.at(uy).at(ux);
        if (dist.at(ny).at(nx) <= new_dist) { continue; }
        dist.at(ny).at(nx) = new_dist;
        q.push_back(ny * n + nx);
      }
    }
    //debug2(p.at(i), dist);
  }
  print(ans);
}

int main() {
  solve();
  return 0;
}

