int n;
int dr[]={1,-1,0,0};
int dc[]={0,0,-1,1};

int main() {
	ios_base::sync_with_stdio(false);
	cin >> n;
	rep(row, 0,n+2) {
		d[row][0] = d[row][n+1] = -1;
	}
	rep(col, 0, n+2) {
		d[0][col] = d[n+1][col] = -1;
	}
	rep(row,1,n+1) rep(col,1,n+1) d[row][col] = min({row - 1, n - row, col-1, n - col});
	// rep(row, 0, n+2) {
	// 	rep(col, 0, n+2) {
	// 		printf("%2d ", d[row][col]);
	// 	}
	// 	printf("\n");
	// }
	int res = 0;
	rep(i,0,n*n) {
		cin >> ord[i];
		--ord[i];
		int row = ord[i] / n, col = ord[i] % n;
		row = row + 1, col = col + 1;
		res += d[row][col];
		rem[row][col] = 1;
		queue<pii> q;
		q.push({row, col});
		while (!q.empty()) {
			auto cur = q.front(); q.pop();
			int npossible = d[cur.st][cur.nd] + 1 - rem[cur.st][cur.nd];
			rep(dir, 0, 4) {
				int nr = cur.st + dr[dir], nc = cur.nd + dc[dir];
