    //   for(int y=0;y<N;++y){
    //     printf("%d ,",cost[x][y]);
    //   }
    //   printf("\n");
    // }

    update(x+1,y  );
    update(x  ,y+1);
    update(x-1,y );
    update(x  ,y-1);

    //printf("%d: %d\n",i,id);

    // for(int x=0;x<N;++x){
    //   for(int y=0;y<N;++y){
    //     printf("%d ,",cost[x][y]);
    //   }
    //   printf("\n");
    // }

    //printf("\n");
  }
  printf("%d",count);
}

