using namespace std;
int N;
long ans;
int X[500][500];
bool vis[500][500];
int d[4]={1,0,-1,0};
main()
{
	cin>>N;
	for(int i=0;i<N;i++)
	{
		for(int j=0;j<N;j++)X[i][j]=min(min(i,N-1-i),min(j,N-1-j));
	}
	for(int i=0;i<N*N;i++)
	{
		int P;cin>>P;P--;
		int x=P/N,y=P%N;
		ans+=X[x][y];
		vis[x][y]=true;
		queue<pair<int,int> >Q;
		Q.push(make_pair(x,y));
		while(!Q.empty())
		{
			int nx=Q.front().first,ny=Q.front().second;
			Q.pop();
			int c=X[nx][ny];
			if(!vis[nx][ny])c++;
			for(int r=0;r<4;r++)
			{
				int tx=nx+d[r],ty=ny+d[r^1];
				if(0<=tx&&tx<N&&0<=ty&&ty<N&&X[tx][ty]>c)
				{
					X[tx][ty]=c;
					Q.push(make_pair(tx,ty));
				}
			}
		}
	}
	cout<<ans<<endl;
}

#include "bits/stdc++.h"

using namespace std;

int minHates(const vector<vector<int> >& seats, int startr, int startc) {
    int N = seats.size();
    queue<int> que;
    vector<vector<int> > arrived(N, vector<int>(N, 0));

    queue<pair<int, int> > nextSearch;
    nextSearch.push(make_pair(startr, startc));
    arrived[startr][startc] = 1;
    for (int nbHates = 0; nbHates < N; ++nbHates) {
        queue<pair<int, int> > que = nextSearch;
        queue<pair<int, int> >().swap(nextSearch);
        while (!que.empty()) {
            int r = que.front().first;
            int c = que.front().second;
            que.pop();
            if (r == 0 || r == N - 1 || c == 0 || c == N - 1) {
                return nbHates;
            }

            if (arrived[r + 1][c] == 0) {
                arrived[r + 1][c] = 1;
                (seats[r + 1][c] == 0 ? que : nextSearch).push(make_pair(r + 1, c));
            }
            if (arrived[r - 1][c] == 0) {
                arrived[r - 1][c] = 1;
                (seats[r - 1][c] == 0 ? que : nextSearch).push(make_pair(r - 1, c));
            }
            if (arrived[r][c + 1] == 0) {
                arrived[r][c + 1] = 1;
                (seats[r][c + 1] == 0 ? que : nextSearch).push(make_pair(r, c + 1));
            }
            if (arrived[r][c - 1] == 0) {
                arrived[r][c - 1] = 1;
                (seats[r][c - 1] == 0 ? que : nextSearch).push(make_pair(r, c - 1));
            }
        }
    }
}

void Main() {
    int N;
    cin >> N;
    int N2 = N * N;
    vector<int> P(N2, 0);
    for (int i = 0; i < N2; ++i) {
        cin >> P[i];
        P[i] -= 1;
    }

    int ans = 0;
    vector<vector<int> > seats(N, vector<int>(N, 1));
    for (int i = 0; i < N2; ++i) {
        int p = P[i];
        int r = p / N;
        int c = p % N;
        seats[r][c] = 0;
        ans += minHates(seats, r, c);
    }
    cout << ans << endl;
}

int main() {
    std::cout << std::fixed << std::setprecision(15);
    Main();
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

const int N = 3e5;

int n;
int a[N],h[N],x[N],y[N],g[N];
int ans;

void upd(int x)
{
    int nx = h[x];
    if(!g[x]) nx++;
    if(x-n>=1) if(h[x-n]>nx) h[x-n] = nx,upd(x-n);
    if(x+n<=n*n) if(h[x+n]>nx) h[x+n] = nx,upd(x+n);
    if(x%1!=0) if(h[x-1]>nx) h[x-1] = nx,upd(x-1);
    if(x%n!=0) if(h[x+1]>nx) h[x+1] = nx,upd(x+1);
}

int main()
{
    ios_base::sync_with_stdio(0); cin.tie(0);

    cin >> n;
    for(int i = 1;i <= n;i++) for(int j = 1;j <= n;j++) x[(i-1)*n+j] = i,y[(i-1)*n+j] = j;
    for(int i = 1;i <= n*n;i++) cin >> a[i],h[i] = min(min(n-x[i],x[i]-1),min(n-y[i],y[i]-1));
    for(int i = 1;i <= n*n;i++)
    {
        int x = a[i];
        ans+=h[x];
        g[x] = true;
        upd(x);
    }
    cout << ans;
}

#include "bits/stdc++.h"
using namespace std;

int n;
#define MAX 502

vector<int> v;

bool flag[MAX][MAX];
int dx[]={0,0,1,-1};
int dy[]={1,-1,0,0};
int dist[MAX][MAX];
queue<pair<int,int> > q;
void upd(int a,int b){
	if(a<0||b<0||a>=n||b>=n)return;
	int cur=dist[a][b];
	dist[a][b]=INT_MAX;
	for(int i=0;i<4;i++){
		int xx=a+dx[i];
		int yy=b+dy[i];
		if(xx>=0&&yy>=0&&xx<n&&yy<n){
			dist[a][b]=min(dist[a][b],dist[xx][yy]+1-flag[xx][yy]);
		}
		else{
			dist[a][b]=0;
		}
	}
	if(cur>dist[a][b]){
		for(int g=0;g<4;g++){
			q.push(make_pair(a+dx[g],b+dy[g]));
		}
	}
}
int main(){
	cin>>n;
	for(int i=0;i<n*n;i++){
		int p;
		scanf("%d",&p);
		v.push_back(p);
	}
	long long int ans=0;
	for(int i=0;i<n;i++){
		for(int j=0;j<n;j++){
			dist[i][j]=min(min(min(i,j),n-i-1),n-j-1);
		}
	}
	for(int i=0;i<v.size();i++){
		v[i]--;
		int x=v[i]/n;
		int y=v[i]%n;
		ans+=dist[x][y];
		//cerr<<x<<" "<<y<<" "<<dist[x][y]<<endl;
		flag[x][y]=true;
		for(int k=0;k<4;k++){
			q.push({x+dx[k],y+dy[k]});
		}
		while(!q.empty()){
			auto f=q.front();
			q.pop();
			upd(f.first,f.second);
		}
	}
	printf("%lld\n",ans);
	return 0;
}

