            if(abs(b-j)+a-u[a][j]<best)
            {
                best=abs(b-j)+u[a][j]-a;
                dir={'U',j};
            }
            if(abs(b-j)+d[a][j]-a<best)
            {
                best=abs(b-j)+d[a][j]-a;
                dir={'D',j};
            }
            if(abs(a-j)+b-l[j][b]<best)
            {
                best=abs(a-j)+b-l[j][b];
                dir={'L',j};
            }
            if(abs(a-j)+r[j][b]-b<best)
            {
                best=abs(a-j)+r[j][b]-b;
                dir={'R',j};
            }
        }
        res+=best;
        if(dir.first=='U'||dir.first=='D')
        {
            for(int j=b;j<=dir.second;j++) add(a,j);
            for(int j=b;j>=dir.second;j--) add(a,j);
            if(dir.first=='U') for(int j=a;j>a-(best-abs(b-dir.second));j--) add(j,dir.second);
            else for(int j=a;j<a+(best-abs(b-dir.second));j++) add(j,dir.second);
        }
        else
        {
            for(int j=a;j<=dir.second;j++) add(j,b);
            for(int j=a;j>=dir.second;j--) add(j,b);
            if(dir.first=='L') for(int j=b;j>b-(best-abs(a-dir.second));j--) add(dir.second,j);
            else for(int j=b;j<b+(best-abs(a-dir.second));j++) add(dir.second,j);
        }
    }
    cout << res/2 << "\n";
    return 0;
}

