int n, p, res;
deque <pii> de;
int d[505][505];
bool dd[505][505], isout;

void go(int r, int c, int val){
    if (isout) return;
    if (r < 1 || c < 1 || r > n || c > n){
        isout = true;
        res += val;
        return;
    }
    if (d[r][c] <= val) return;
    if (dd[r][c]){
        d[r][c] = val;
        de.push_front(pii({r, c}));
    }else{
        d[r][c] = val + 1;
        de.push_back(pii({r, c}));
    }
}

void bfs(int r, int c){
    dd[r][c] = true;
    for (int i = 1; i <= n; i++)
        for (int j = 1; j <= n; j++)
            d[i][j] = 1e9;
    d[r][c] = 0;
    de.clear();
    de.push_back(pii({r, c}));
    isout = false;
    while (!isout && !de.empty()){
        r = de.front().fr, c = de.front().sc;
        de.pop_front();
        go(r + 1, c, d[r][c]);
        go(r, c + 1, d[r][c]);
        go(r - 1, c, d[r][c]);
        go(r, c - 1, d[r][c]);
    }
}

