inline void bfs(int x,int y)
{
    while(!q.empty())
        q.pop();
    ans += d[x][y];
    q.push(mp(x, y));
    vis[x][y] = 1;
    while(!q.empty())
    {
        int x = q.front().first, y = q.front().second;
        q.pop();
        for (int k = 0; k < 4;++k)
        {
            int nx = x + dx[k], ny = y + dy[k];
            if(nx<1||ny<1||nx>n||ny>n||d[nx][ny]<=d[x][y]+1-vis[x][y])
                continue;
            d[nx][ny] = d[x][y] + 1 - vis[x][y];
            q.push(mp(nx, ny));
        }
    }
}

void solve()
{
    scanf("%d", &n);
    for (int i = 1; i <= n * n; ++i)
        scanf("%d", &p[i]);
    memarray(d, inf);
    for (int i = 1; i <= n; ++i)
    {
        if (d[1][i])
            d[1][i] = 0, q.push(mp(1, i));
        if (d[n][i])
            d[n][i] = 0, q.push(mp(n, i));
        if (d[i][n])
            d[i][n] = 0, q.push(mp(i, n));
        if (d[i][1])
            d[i][1] = 0, q.push(mp(i, 1));
    }
    while(!q.empty())
    {
        int x = q.front().first, y = q.front().second;
        q.pop();
        for (int k = 0; k < 4;++k)
        {
            int nx = x + dx[k], ny = y + dy[k];
            if(nx<1||ny<1||nx>n||ny>n||d[nx][ny]<=d[x][y]+1)
                continue;
            d[nx][ny] = d[x][y] + 1;
            q.push({nx, ny});
        }
    }
    for (int i = 1; i <= n * n;++i)
    {
        int x = (p[i] - 1) / n + 1, y = (p[i] - 1) % n + 1;
        bfs(x, y);
    }
    printf("%d\n", ans);
}

