ll sqN, N;
vector<vector<ll>> mp;

ll has(ll h, ll w){
    return h * sqN + w;
}

bool valid(ll h, ll w){
    return (0 <= h && h < sqN && 0 <= w && w < sqN);
}

int main(){
    cin >> sqN;
    N = sqN * sqN;
    mp.resize(sqN, vector<ll>(sqN));
    vector<ll> p(N);
    rep(i, N) cin >> p[i];
    rep(i, N) --p[i];
    rep(i, sqN)rep(j, sqN){
        mp[i][j] = i;
        chmin(mp[i][j], j);
        chmin(mp[i][j], sqN - i - 1);
        chmin(mp[i][j], sqN - j - 1);
    }
    ll ans = 0;
    rep(i, N){
        ll now = p[i];
        queue<P> que;
        ans += mp[now / sqN][now % sqN];
        que.push(P(now, mp[now / sqN][now % sqN]));
        while(!que.empty()){
            P cu = que.front(); que.pop();
            ll y = cu.first / sqN;
            ll x = cu.first % sqN;
            if (valid(y + 1, x)) if(chmin(mp[y + 1][x], cu.second)) que.push(P(has(y + 1, x), cu.second + 1));
            if (valid(y - 1, x)) if(chmin(mp[y - 1][x], cu.second)) que.push(P(has(y - 1, x), cu.second + 1));
            if (valid(y, x + 1)) if(chmin(mp[y][x + 1], cu.second)) que.push(P(has(y, x + 1), cu.second + 1));
            if (valid(y, x - 1)) if(chmin(mp[y][x - 1], cu.second)) que.push(P(has(y, x - 1), cu.second + 1));
        }
        mp[now / sqN][now % sqN] = 0;
    }
    pt(ans);
}

