ll t;
vector<vector<ll>> seats;

void bfs(ll x, ll y) {
    queue<pair<ll,ll>> q;
    q.push({x,y});
    while(!q.empty()) {
        auto&& xy = q.front(); q.pop();
        ll x = xy.first, y = xy.second;
        if(y > 0 && seats[y - 1][x] > seats[y][x] +  1) {
            seats[y - 1][x] = seats[y][x] +  1;
            q.push({y - 1,x});
        }
        if(y < t - 1&& seats[y + 1][x] > seats[y][x] +  1) {
            seats[y + 1][x] = seats[y][x] +  1;
            q.push({y + 1,x});
        }
        if(x > 0 && seats[y][x - 1] > seats[y][x] +  1) {
            seats[y][x - 1] = seats[y][x] +  1;
            q.push({y,x - 1});
        }
        if(x < t - 1 && seats[y][x + 1] > seats[y][x] +  1) {
            seats[y][x + 1] = seats[y][x] +  1;
            q.push({y,x + 1});
        }
    }
}

int main() {
    cin >> t;
    for(ll y = 0; y < t; y++) {
        vector<ll> row;
        for(ll x = 0; x < t; x++) {
            row.push_back(min({x, t - x - 1, y, t - y - 1}));
        }
        seats.push_back(row);
    }
    ll result = 0;
    for(ll i = 0; i < t * t; i++) {
        ll number;
        cin >> number;
        number--;
        ll x = number % t;
        ll y = number / t;
        result += seats[y][x];
        seats[y][x]--;
        bfs(x, y);
    }
