void dij(int x, int y, int f) {
    ans += dis[x][y];
    queue<pair<int, pair<int, int>>> que;
    que.push({dis[x][y], {x, y}});
    vis[x][y] = f;
    mk[x][y] = true;
    while (!que.empty()) {
        auto [d, p] = que.front();
        auto [x, y] = p;
        que.pop();
        for (int i = 0; i < 4; i++) {
            int xx =  x + dx[i], yy = y + dy[i];
