static int N;

void UpdateSeat(int x, int y, int givenValue = -1){
	int newDist = 10000;
	if(IsVacant[x][y]){
		givenValue -= 1;
	}
	if(givenValue == -1){
		IsVacant[x][y] = true;
		if(x-1 >= 0){
			newDist = min(newDist, Seat[x-1][y]);
		}
		if(x+1 <= N+1){
			newDist = min(newDist, Seat[x+1][y]);
		}
		if(y-1 >= 0){
			newDist = min(newDist, Seat[x][y-1]);
		}
		if(y+1 <= N+1){
		newDist = min(newDist, Seat[x][y+1]);
		}
	}else{
		if(Seat[x][y] > givenValue){
			newDist = givenValue;
		}
	}

	if(Seat[x][y] > newDist){
		Seat[x][y] = newDist;
		if(x-1 >= 0){
			UpdateSeat(x-1,y,newDist+1);
		}
		if(x+1 <= N+1){
			UpdateSeat(x+1,y,newDist+1);
		}
		if(y-1 >= 0){
			UpdateSeat(x,y-1,newDist+1);
		}
		if(y+1 <= N+1){
			UpdateSeat(x,y+1,newDist+1);
		}
	}
}

int GetMinDist(int x, int y){
	int newDist = 1000000;
	if(x-1 >= 0){
		newDist = min(newDist, Seat[x-1][y]);
	}
	if(x+1 <= N+1){
		newDist = min(newDist, Seat[x+1][y]);
	}
	if(y-1 >= 0){
		newDist = min(newDist, Seat[x][y-1]);
	}
	if(y+1 <= N+1){
		newDist = min(newDist, Seat[x][y+1]);
	}
	return newDist;
}

