		else if (n < 0)n = (n%mod + mod) % mod;
	}
	operator int() { return n; }
};
bool operator==(modint a, modint b) { return a.n == b.n; }
modint operator+=(modint &a, modint b) { a.n += b.n; if (a.n >= mod)a.n -= mod; return a; }
modint operator-=(modint &a, modint b) { a.n -= b.n; if (a.n < 0)a.n += mod; return a; }
modint operator*=(modint &a, modint b) { a.n = ((ll)a.n*b.n) % mod; return a; }
modint operator+(modint a, modint b) { return a += b; }
modint operator-(modint a, modint b) { return a -= b; }
modint operator*(modint a, modint b) { return a *= b; }
modint operator^(modint a, int n) {
	if (n == 0)return modint(1);
	modint res = (a*a) ^ (n / 2);
	if (n % 2)res = res * a;
	return res;
}

ll inv(ll a, ll p) {
	return (a == 1 ? 1 : (1 - p * inv(p%a, a)) / a + p);
}
modint operator/(modint a, modint b) { return a * modint(inv(b, mod)); }
const int max_n = 1 << 18;
modint fact[max_n], factinv[max_n];
void init_f() {
	fact[0] = modint(1);
	for (int i = 0; i < max_n - 1; i++) {
		fact[i + 1] = fact[i] * modint(i + 1);
	}
	factinv[max_n - 1] = modint(1) / fact[max_n - 1];
	for (int i = max_n - 2; i >= 0; i--) {
		factinv[i] = factinv[i + 1] * modint(i + 1);
	}
}
modint comb(int a, int b) {
	if (a < 0 || b < 0 || a < b)return 0;
	return fact[a] * factinv[b] * factinv[a - b];
}

int dx[4] = { 1,0,-1,0 };
int dy[4] = { 0,1,0,-1 };

int a[500][500];

int id[500][500][251];

bool f[500][500];
void solve() {
	int n; cin >> n;
	vector<int> in(n*n);
	rep(i, n*n)cin >> in[i];
	rep(i, n*n) {
		in[i]--;
		a[in[i] / n][in[i] % n] = i + 1;
	}
	/*rep(i, n) {
		rep(j, n) {
			cout << a[i][j] << " ";
		}
		cout << "\n";
	}*/


	int sz = n / 2;

	int sup = n * n + 1;
	rep(i, n)rep(j, n)rep(k, sz + 1)id[i][j][k] = sup;
	rep(i, n)rep(j, n) {
		if (i == 0 || j == 0 || i == n - 1 || j == n - 1) {
			id[i][j][0] = a[i][j];
			id[i][j][1] = 0;
		}
	}
	rep(k, sz + 1) {
		vector<queue<P>> qs(sup + 1);
		vector<vector<bool>> used(n, vector<bool>(n, false));

		rep(i, n)rep(j, n) {
			if (f[i][j])continue;
			if (id[i][j][k] == sup)continue;
			qs[id[i][j][k]].push({ i,j });
			if (id[i][j][k] == 0)f[i][j] = true;
		}
		rep(t, sup) {
			while (!qs[t].empty()) {
				P p = qs[t].front(); qs[t].pop();
				int x = p.first, y = p.second;
				if (used[x][y])continue;
				used[x][y] = true;
				rep(d, 4) {
					int nx = x + dx[d], ny = y + dy[d];
					if (nx < 0 || ny < 0 || nx == n || ny == n)continue;
					if (used[nx][ny])continue;
					if (f[nx][ny])continue;
					//if (a[nx][ny] < id[x][y][k])continue;
					int td = max(a[nx][ny], id[x][y][k]);
					if (td < id[nx][ny][k]) {
						id[nx][ny][k] = td;
						qs[td].push({ nx,ny });
					}
				}
			}
		}
		if (k < sz) {
			rep(x, n)rep(y, n) {

				rep(d, 4) {
					int nx = x + dx[d], ny = y + dy[d];
					if (nx < 0 || ny < 0 || nx == n || ny == n)continue;
					id[nx][ny][k + 1] = min(id[nx][ny][k + 1], id[x][y][k]);
				}
			}
		}
	}
	ll ans = 0;
	rep(i, n)rep(j, n) {
		int z = 0;
		rep(k, n + 1)if (id[i][j][k] == a[i][j]) {
			z = k; break;
		}
		//cout << "? " << a[i][j] << " " << z << "\n";
		ans += z;
	}
	cout << ans << "\n";
}


