int ans;

int dist[MAXN][MAXN];
bool used[MAXN][MAXN];

void build() {
	for (int i = 0; i < n; i++) {
		for (int j = 0; j < n; j++) {
			used[i][j] = false;
			dist[i][j] = n;
			chkmin(dist[i][j], i);
			chkmin(dist[i][j], n - i - 1);
			chkmin(dist[i][j], j);
			chkmin(dist[i][j], n - j - 1);
		}
	}
}

vector<int> dx = {1, 0, -1, 0}, dy = {0, 1, 0, -1};

bool checkCell(int x, int y) {
	return x >= 0 && x < n && y >= 0 && y < n;
}

void upd(int x, int y) {
	//cout << "x, y = " << x << " " << y << endl;
	ans += dist[x][y];
	//cout << "dist[x][y] = " << dist[x][y] << endl;
	queue<pair<int, int>> q;
	q.push({x, y});
	used[x][y] = true;
	while (!q.empty()) {
		auto v = q.front();
		x = v.first;
		y = v.second;
		q.pop();
		for (int it = 0; it < 4; it++) {
			int nx = x + dx[it], ny = y + dy[it];
			if (!checkCell(nx, ny)) continue;
			int nd = dist[x][y];
			if (!used[x][y]) nd++;
			//cout << "x, y = " << x << " " << y << " used[x][y] = " << used[x][y] << endl;
			if (dist[nx][ny] <= nd) continue;
			dist[nx][ny] = nd;
			//cout << "nx, ny = " << nx << " " << ny << " nd = " << nd << endl;
			q.push({nx, ny});
		}
	}
}

