#include <bits/stdc++.h>
using namespace std;
using LL = int64_t;
using ULL = int64_t;
using P = pair<LL, LL>;
#define rep(i, n) for (LL i = 0; i < (n); ++i)
#define all(v) (v).begin(), (v).end()
#define DEBUG

LL n; // number of viewers.
vector<LL> inuse;

bool is_on_edge(LL id) {
  return (id < n) || (id % n == 0) || (id % n == n - 1) || (id >= n * (n - 1));
}

LL costcost(LL id) {
  if (is_on_edge(id)) {
    return 0;
  }

  // Dijkstra
  priority_queue<P, vector<P>, greater<P>> q; // current cost, node id.
  vector<bool> completed(n * n, false); // current cost, node id.
  vector<LL> c(n * n, 999999999LL); // completed node cost.

//  rep(i, n * n) {
//    cout << i << " is in use::" << inuse[i] << endl;
//  }

  // Start node.
  q.push(make_pair((LL)0, id));
  while (!q.empty()) {
    const LL cost = q.top().first; // pivot node cost
    const LL ii = q.top().second; // pivot node id
    q.pop();

    if (completed.at(ii)) continue;

    c.at(ii) = cost;
    completed.at(ii) = true;
//    cout << ii << ":" << cost << endl;

    // check four edges
    if (ii >= n) {
      // has upper
      if (!completed[ii - n]) q.push(make_pair(cost + inuse[ii - n], ii - n));
    }
    if (ii % n != 0) {
      // has left
      if (!completed[ii - 1]) q.push(make_pair(cost + inuse[ii - 1], ii - 1));
    }
    if (ii % n != n - 1) {
      // has right
      if (!completed[ii + 1]) q.push(make_pair(cost + inuse[ii + 1], ii + 1));
    }
    if (ii < n * (n - 1)) {
      // has lower
      if (!completed[ii + n]) q.push(make_pair(cost + inuse[ii + n], ii + n));
    }
  }

  // check four edges [(n - 2) * 4 nodes]
  LL min_cost = 999999999LL;
  for (int i = 1; i <= n - 2; ++i) {
    if (c.at(i) < min_cost) min_cost = c.at(i);
  }
  for (int i = n * (n - 1); i <= n * n - 1; ++i) {
    if (c.at(i) < min_cost) min_cost = c.at(i);
  }
  for (int i = n; i <= n * (n - 2); i += n) {
    if (c.at(i) < min_cost) min_cost = c.at(i);
  }
  for (int i = n * 2 - 1; i <= n * (n - 1) - 1; i += n) {
    if (c.at(i) < min_cost) min_cost = c.at(i);
  }

  return min_cost;
}

int main() {
  cin >> n;
  vector<LL> p(n * n);
  rep (i, n * n) {
    cin >> p.at(i);
    p.at(i) -= 1;

    //cout << i << " " << is_on_edge(i) << endl;
  }

  if (n <= 2) {
    cout << 0 << endl;
    return 0;
  }

  inuse.assign(n * n, 1);
  LL sum = 0;
  rep (i, n * n) {
    sum += costcost(p.at(i));
    inuse.at(p.at(i)) = 0;
  }
  cout << sum << endl;


  return 0;
  #ifdef DEBUG
//  cout << n << endl;
//  rep (i, n * n) {
//    cout << p.at(i) << endl;
//  }
  #endif
}

