void pd(const vector<vector<int>>& dist, const vector<vector<bool>>& left) {
  REP(i, dist.size()) {
    REP(j, dist.size()) {
      if (left[i][j])
        cerr << ' ';
      else
        cerr << dist[i][j];
    }
    cerr << endl;
  }
