        if (row2 < 0 || row2 >= N || col2 < 0 || col2 >= N) continue;
        i64 s = d + int(!left[r][c]);
        if (dist[row2][col2] > s) {
          dist[row2][col2] = s;
          q.emplace_back(row2, col2, s);
        }
      }
    }
  };

  i64 total_cost = 0;
  //  int i = 0;
  for (const auto& p : P) {
    int col = p % N;
    int row = p / N;
    left[row][col] = true;
    total_cost += dist[row][col];
