    }

    while(que.size()){
      ll pos_tmp = que.front(); que.pop();
      ll x_tmp = pos_tmp/N;
      ll y_tmp = pos_tmp%N;
      if(used.find(make_pair(x_tmp, y_tmp))!=used.end()) continue;
      used.emplace(make_pair(x_tmp, y_tmp));

      if(x_tmp==0 || x_tmp==N-1 || y_tmp==0 || y_tmp==N-1) continue;

      ll New_Cost = INFLL;
      {
        //ll target_pos = (x_tmp-1)*N+y_tmp;
