        //chmin(New_Cost, Cost[x_tmp][y_tmp+1] + mp[make_pair(pos_tmp, target_pos)]);
        chmin(New_Cost, Cost[x_tmp][y_tmp+1] + mp[mapa(x_tmp, y_tmp, x_tmp, y_tmp+1)]);
        //if(New_Cost < Cost[x_tmp][y_tmp]) debug_print(x_tmp, y_tmp+1);
