const int N = 505;
const int K = 1 << 9;

struct seg {
	int a[N];
	int t[2*K];

	void build() {
		for (int i=1; i<N; i++) t[i+K-1] = a[i];
		for (int i=K-1; i>=1; i--) t[i] = t[i+i] + t[i+i+1];
	}

	void upd(int id, int x) {
		id += K-1;
		while (id) {
			t[id] += x;
			id /= 2;
		}
	}

	int get(int l, int r) {
		l += K-1;
		r += K-1;
		int res = 0;
		while (l <= r) {
			if (l % 2 == 1) res += t[l++];
			if (r % 2 == 0) res += t[r--];
			l /= 2;
			r /= 2;
		}
		return res;
	}
};

seg r[N];
seg c[N];

void Solve() {
	int n;
	cin >> n;
	for (int i=1; i<=n; i++) {
		for (int j=1; j<=n; j++) {
			r[i].a[j] = 1;
			c[j].a[i] = 1;
		}
	}
	for (int i=1; i<=n; i++) r[i].build();
	for (int j=1; j<=n; j++) c[j].build();
	int ans = 0;
	for (int i=1; i<=n*n; i++) {
		int cur;
		cin >> cur;
		int x = (cur - 1) / n + 1;
		int y = cur % n;
		if (!y) y = n;
		int lef = r[x].get(1, y);
		int rig = r[x].get(y, n);
		int down = c[y].get(1, x);
		int up = c[y].get(x, n);
		int res = lef;
		mini(res, rig);
		mini(res, up);
		mini(res, down);
		ans += res - 1;
		r[x].upd(y, -1);
		c[y].upd(x, -1);
	}
	cout << ans << "\n";
}

