int main() {
  cin.tie(nullptr); ios::sync_with_stdio(false);

  int n; cin>>n;

  vector<vector<int>> H(n, vector<int>(n));
  vector<vector<bool>> exist(n, vector<bool>(n, true));
  for (int i = 0; i < n; i++) {
    for (int j = 0; j < n; j++) {
      H[i][j] = min({
        i,n-1-i,
        j,n-1-j
      });
    }
  }

  int ans = 0;
  for (int i = 0; i < n*n; i++) {
    int p; cin>>p; p--;
    int row = p/n;
    int col = p%n;
    ans += H[row][col];
    exist[row][col] = false;

    deque<pair<int,int>> qs;
    qs.emplace_back(row, col);
    while (not qs.empty()) {
      auto [r,c] = qs.front(); qs.pop_front();
      auto h = H[r][c] + (exist[r][c] ? 1 : 0);
      for (auto d:dir) {
        auto nr = r+d[0];
        auto nc = c+d[1];
        if (nr < 0 or nr >= n or nc < 0 or nc >= n)
          continue;
        if (h >= H[nr][nc])
          continue;
        H[nr][nc] = h;
        if (exist[nr][nc]) {
          qs.emplace_back(nr,nc);
        } else {
          qs.emplace_front(nr,nc);
        }
      }
    }
  }
  cout << ans << endl;

  return 0;
}

