lld bfs(vector<vector<lld>> &seats, lld p) {
	lld i, j, n, tmp, cost=1e18;
	lld row, col;

	n = seats.size();
	col = (p-1)%n;
	row = (p-1)/n;
	seats[row][col] = 0;

	queue<pair<lld, lld>> q;
	vector<bool> vis(n*n+1, false);
	q.push({p, 0});

	pair<lld, lld> pr;
	while(!q.empty()) {
		pr = q.front();
		//cout<<"Dequeued: "<<pr.first<<" "<<pr.second<<"\n";
		q.pop();
		col = (pr.first-1)%n;
		row = (pr.first-1)/n;
		vis[pr.first] = true;

		if(row==0 || row==n-1 || col==0 || col==n-1) {
			cost = min(cost, pr.second);
			continue;
		}

		if(!vis[pr.first+1])
			q.push({pr.first+1, pr.second + seats[row][col+1]}); // right
		if(!vis[pr.first-1])
			q.push({pr.first-1, pr.second + seats[row][col-1]}); // left
		if(!vis[pr.first+n])
			q.push({pr.first+n, pr.second + seats[row+1][col]}); // up
		if(!vis[pr.first-n])
			q.push({pr.first-n, pr.second + seats[row-1][col]}); // down
	}

	return cost;
}

void solve(lld n, vector<lld> p) {
	vector<vector<lld>> seats(n, vector<lld>(n, 1));
	lld cost = 0;
	for(lld i=0; i<p.size(); ++i) {
		//cout<<p[i]<<"\n";
		cost += bfs(seats, p[i]);
	}

	cout<<cost<<"\n";
}

