	lld t=1;
	//cin>>t;

	for (lld cs=1; cs<=t; ++cs) {
		lld n;
		cin>>n;
		vector<lld> p(n*n, 0);
		input_vector(p, n*n);
		solve(n, p);
	}

	return 0;
}

