ll N;
template <typename T>class my_PQ{
public:
    vector<T> q;
    my_PQ(){}
    my_PQ(ll N){q.resize(N);}
    my_PQ(ll N,T a){q.resize(N);for(ll i=0;i<N;i++)q[i]=a;}
    size_t size(){return q.size();}
    typename vector<T>::iterator begin(){return q.begin();}
    typename vector<T>::iterator end(){return q.end();}
    void resize(ll N){q.resize(N);}
    T& operator[](ll n)&{return q[n];}
    const T& operator[](ll n)const&{return q[n];}
    void push_back(T&& x){q.push_back(x);}
    void clear(){q.clear();}
    void erase(ll i){q.erase(q.begin()+i);}
    ll insert(T x,bool (*comp)(T a,T b)){
        ll left = -1;
        ll right = (ll)q.size();
        while (right - left > 1) {
            ll mid = left + (right - left) / 2;
            if (!comp(q[mid],x)) right = mid;
            else left = mid;
        }
        q.insert(q.begin()+right,x);
        return right;
    }
};

bool comp(vll a,vll b){
    return a[2]<b[2];
}

int main(){
    ios::sync_with_stdio(false);
    cin.tie(0);

    cin>>N;
    vvll P(N,vll(N));

    for(ll i=0;i<N*N;i++){
        ll a;
