    /**for(ll i=0;i<N;i++){
        for(ll j=0;j<N;j++){
            printf("%d,",P[i][j]);
        }
        printf("\n");
    }/**/

    ll ans=0;
    vvll score(N,vll(N,-1));
    for(ll i=0;i<N;i++){
        for(ll j=0;j<N;j++){
            my_PQ<vll> open;
            open.push_back(vll{i,j,0});
            vector<vector<bool>> done(N,vector<bool>(N,false));
            done[i][j]=true;
            while(open.size()>0){
                vll node=open[0];
                if(node[2]==0 && score[node[0]][node[1]]==0){
                    score[i][j]=0;
                    break;
                }
                if(node[0]==0 || node[0]==N-1 || node[1]==0 || node[1]==N-1){
                    ans+=node[2];
                    score[i][j]=node[2];
                    //printf("%d,%d,%d\n",i,j,node[2]);
                    break;
                }
                open.erase(+0);

                if(!done[node[0]+1][node[1]]){
                    if(P[node[0]+1][node[1]]>P[i][j])open.insert(vll{node[0]+1,node[1],node[2]+1},comp);
                    else open.insert(vll{node[0]+1,node[1],node[2]},comp);
                    done[node[0]+1][node[1]]=true;
                }
                if(!done[node[0]-1][node[1]]){
                    if(P[node[0]-1][node[1]]>P[i][j])open.insert(vll{node[0]-1,node[1],node[2]+1},comp);
                    else open.insert(vll{node[0]-1,node[1],node[2]},comp);
                    done[node[0]-1][node[1]]=true;
                }
                if(!done[node[0]][node[1]+1]){
                    if(P[node[0]][node[1]+1]>P[i][j])open.insert(vll{node[0],node[1]+1,node[2]+1},comp);
                    else open.insert(vll{node[0],node[1]+1,node[2]},comp);
                    done[node[0]][node[1]+1]=true;
                }
                if(!done[node[0]][node[1]-1]){
                    if(P[node[0]][node[1]-1]>P[i][j])open.insert(vll{node[0],node[1]-1,node[2]+1},comp);
                    else open.insert(vll{node[0],node[1]-1,node[2]},comp);
                    done[node[0]][node[1]-1]=true;
                }
            }
        }
    }

    cout<<ans<<endl;
    return 0;
}
