const int gox[] = {1, 0, -1, 0};
const int goy[] = {0, 1, 0, -1};

bool inside(int x, int y) {
  return 0 <= x && x < n && 0 <= y && y < n;
}

int d[maxn][maxn];
int alive[maxn][maxn];
deque<pair<int, int>> q;

void bfs() {
  while (!q.empty()) {
    int x = q.front().first, y = q.front().second;
    q.pop_front();
    for (int dir = 0; dir < 4; dir++) {
      int nx = x + gox[dir], ny = y + goy[dir];
      if (!inside(nx, ny)) {
        continue;
      }
      int nd = d[x][y] + (alive[x][y] ? 1 : 0);
      if (nd < d[nx][ny]) {
        d[nx][ny] = nd;
        if (alive[x][y]) {
          q.push_back(make_pair(nx, ny));
        } else {
          q.push_front(make_pair(nx, ny));
        }
      }
    }
  }
}

void solve() {
  q.clear();
  for (int i = 0; i < n; i++) {
    for (int j = 0; j < n; j++) {
      d[i][j] = inf;
      alive[i][j] = true;
      if (i == 0 || i == n - 1 || j == 0 || j == n - 1) {
        d[i][j] = 0;
        q.push_back(make_pair(i, j));
      }
    }
  }
  bfs();
  int res = 0;
  for (int i = 0; i < n * n; i++) {
    int id = p[i];
    int x = id / n, y = id % n;
    res += d[x][y];
    alive[x][y] = false;
    q.clear();
    q.push_back(make_pair(x, y));
    bfs();
  }
  printf("%d\n", res);
}

