template<typename T1, typename T2> bool CompareByInverse(pair<T1, T2> a, pair<T1, T2> b) { return a.first != b.first ? a.first < b.first : a.second > b.second; }


/* -------- <templates end> -------- */


void solve() {
  int n; cin >> n;
  vi arr(n*n); cin >> arr;

  Graph<int> dist(n, vi(n));
  int MAX = (n - 1) / 2;
  repeq(i,MAX) {
    int j = n - 1 - i;
    REP(k,i,j) {
      dist[i][k] = dist[j][k] = dist[k][i] = dist[k][j] = i;
    }
  }

  vb seen(n*n, false);

  int ans = 0;

  for (auto &p : arr) {
    --p;
    ans += dist[p / n][p % n];
    seen[p] = true;

    queue<pii> q;
    q.emplace(p, dist[p / n][p % n]);

    while (!q.empty()) {
      int v, d, nv;
      tie(v, d) = q.front(); q.pop();

      auto add = [&]() -> void {
        if (chmin(dist[nv / n][nv % n], d + !seen[v])) {
          q.emplace(nv, d + !seen[v]);
        }
      };

      if (v >= n) {
        nv = v - n;
        add();
      }
      if (v < n * (n - 1)) {
        nv = v + n;
        add();
      }
      if (v % n > 0) {
        nv = v - 1;
        add();
      }
      if (v % n < n - 1) {
        nv = v + 1;
        add();
      }
    }
  }

  cout << ans << endl;
}


/* -------- <programs end> -------- */


signed main() {
  cin.tie(nullptr);
  ios::sync_with_stdio(false);
  cout << fixed << setprecision(10);
  solve();
  return 0;
}

