const ll INF = (1ll<<60);
vector<ll> dx = {-1, 0, 1, 0}, dy = {0, -1, 0, 1};

int main(){
    cin.tie(0);
    ios::sync_with_stdio(false);

    ll N;
    cin >> N;
    vector<ll> A(N*N);
    vector<vector<ll>> D(N, vector<ll>(N, INF));
    vector<vector<ll>> H(N, vector<ll>(N, 1));
    REP(i, N*N) cin >> A[i];
    REP(i, N*N) A[i]--;

    REP(i, N){
        REP(j, N){
            vector<ll> vals = {j, N-1-j, i, N-1-i};
            REP(k, 4){
                chmin(D[i][j], vals[k]);
            }
        }
    }

    ll res = 0;
    REP(i, N*N){
        ll r = A[i]/N;
        ll c = A[i]%N;
        res += D[r][c];
        H[r][c]--;

        queue<pll> qu;
        qu.push({r, c});

        while(!qu.empty()){
            auto now = qu.front();qu.pop();
            ll nr = now.first;
            ll nc = now.second;
            REP(d, 4){
                ll er = nr + dx[d];
                ll ec = nc + dy[d];
                if(er<0 or er>N-1 or ec<0 or ec>N-1) continue;
                if(D[er][ec]>D[nr][nc]+H[nr][nc]){
                    D[er][ec] = D[nr][nc];
                    qu.push({er, ec});
                }
            }
        }
    }

    cout << res << endl;

    return 0;
}

