int bfs(int x, int y,int N,vvi &A,vvi flag) {
	queue<pii> que;
	que.push(pii(x, y));
	while (que.size()) {
		//キューの先頭を取り出す
		pii p = que.front(); que.pop();
		//ここに処置を記入
		int sx = p.first;
		int sy = p.second;

		AFOR(i, 4) {
			int nx = sx + dx[i]; int ny = sy + dy[i];
			if (0 <= nx && nx < N && 0 <= ny && ny < N) {
				if (A.at(sx).at(sy) + flag.at(sx).at(sy) < A.at(nx).at(ny)) {
					A.at(nx).at(ny) = A.at(sx).at(sy) + flag.at(sx).at(sy);
					que.push(pii(nx, ny));
				}
			}
		}
	}
	return 0;
}


