void into(){
  scanf("%d",&n);
  for (int i=1;i<=n*n;++i){
	int x;
	scanf("%d",&x);
	p[i][0]=(x-1)/n+1;p[i][1]=(x-1)%n+1;
  }
}

int dis[N+9][N+9],vis[N+9][N+9];
queue<int>qx,qy;

bool Out_map(int x,int y){return x<1||x>n||y<1||y>n;}

void Bfs_dis(){
  for (int i=1;i<=n;++i){
	dis[1][i]=dis[i][1]=dis[n][i]=dis[i][n]=1;
	qx.push(1);qy.push(i);
	qx.push(i);qy.push(1);
	qx.push(n);qy.push(i);
	qx.push(i);qy.push(n);
  }
  for (;!qx.empty();){
	int x=qx.front(),y=qy.front();qx.pop();qy.pop();
	vis[x][y]=1;
	for (int i=0;i<4;++i){
	  int nx=x+dx[i],ny=y+dy[i];
	  if (Out_map(nx,ny)) continue;
	  if (dis[nx][ny]) continue;
	  dis[nx][ny]=dis[x][y]+1;
	  qx.push(nx);qy.push(ny);
	}
  }
}

void Dfs_dis(int x,int y){
  for (int i=0;i<4;++i){
	int nx=x+dx[i],ny=y+dy[i];
	if (Out_map(nx,ny)) continue;
	if (dis[nx][ny]<=dis[x][y]+vis[nx][ny]) continue;
	dis[nx][ny]=dis[x][y]+vis[nx][ny];
	Dfs_dis(nx,ny);
  }
}

int ans;

void Get_ans(){
  for (int i=1;i<=n*n;++i){
	int x=p[i][0],y=p[i][1];
	vis[x][y]=0;
	ans+=--dis[x][y];
	Dfs_dis(x,y);
  }
}

void work(){
  Bfs_dis();
  Get_ans();
}

void outo(){
  printf("%d\n",ans);
}

