	return x;
}
template <typename T, typename ...K>
T smin(T a, const K &...args) {
	return min(a, smin(args...));
}

const int N = 505;

const int mov[4][2] = {{1, 0}, {0, 1}, {-1, 0}, {0, -1}};

int n;
int ans = 0;
int f[N][N];
int vis[N][N];
bool occupy[N][N];

queue<int> qx0, qy0, qx1, qy1;
void update(int x, int y) {
	static int dfc = 0;
	++dfc;
	qx0.push(x);
	qy0.push(y);
	while (!qx0.empty() || !qx1.empty()) {
		int ex = -1, ey = -1;
		if (!qx0.empty()) {
			ex = qx0.front();
			ey = qy0.front();
			qx0.pop();
			qy0.pop();
		} else {
			ex = qx1.front();
			ey = qy1.front();
			qx1.pop();
			qy1.pop();
		}
		if (vis[ex][ey] == dfc) {
			continue;
		}
		vis[ex][ey] = dfc;
		int w = f[ex][ey] + occupy[ex][ey];
		for (int i = 0; i < 4; i++) {
			int nx = ex + mov[i][0];
			int ny = ey + mov[i][1];
			if (nx >= 1 && nx <= n && ny >= 1 && ny <= n && w < f[nx][ny]) {
				f[nx][ny] = w;
				if (!occupy[ex][ey]) {
					qx0.push(nx);
					qy0.push(ny);
				} else {
					qx1.push(nx);
					qy1.push(ny);
				}
			}
		}
	}
}

int main() {
	scanf("%d", &n);
	for (int i = 1; i <= n; i++) {
		for (int j = 1; j <= n; j++) {
			f[i][j] = smin(i - 1, j - 1, n - i, n - j);
			occupy[i][j] = true;
		}
	}
	for (int i = 1, _ = n * n, t, x, y; i <= _; i++) {
		scanf("%d", &t);
		x = (t - 1) / n + 1;
		y = t - (x - 1) * n;
		ans += f[x][y];
		occupy[x][y] = false;
		update(x, y);
	}
	printf("%d\n", ans);
	return 0;
}

