int N, d[509][509], x[509 * 509], y[509 * 509], ap[509][509];
int dx[] = {-1, 1, 0, 0};
int dy[] = {0, 0, -1, 1};

void update (int i, int j)
{
    bool ok = 0;
    if ((i == 1 || j == 1 || i == N || j == N) && ap[i][j] == 0 && d[i][j] == 1)
        d[i][j] = 0, ok = 1;
    for (int k=0; k<4; k++)
    {
        int x = i + dx[k], y = j + dy[k];
        if (1 <= x && x <= N && 1 <= y && y <= N && d[x][y] + ap[i][j] < d[i][j])
            d[i][j] = d[x][y] + ap[i][j], ok = 1;
    }
    if (ok)
    {
        for (int k=0; k<4; k++)
        {
            int x = i + dx[k], y = j + dy[k];
            if (1 <= x && x <= N && 1 <= y && y <= N)
                update (x, y);
        }
    }
}

