        bool vis[n+1][n+1];
        memset(vis,false,sizeof vis);
        int dist[n+1][n+1];
        memset(dist, 0, sizeof dist);
        dist[index[curr].first][index[curr].second] = 0;
        while(!dq.empty()){
            pair<int,pair<int, int> > now = dq.front();
            dq.pop_front();
            vis[now.second.first][now.second.second] = true;
            bool isend = false;
            for(int j=0;j<4;j++){
                if(isExit(now.second.first+dx[j], now.second.second+dy[j],n)){
                    isend = true;
                    break;
                }
            }
            if(isend){
                ans += dist[now.second.first][now.second.second];
                break;
            }
            for(int j=0;j<4;j++){
                int goi = now.second.first + dx[j],goj = now.second.second + dy[j];
                int goNum = (goi-1)*n + goj;
                if(!vis[goi][goj]){
                    if(ord[goNum] > ord[curr]){
                        dist[goi][goj] = 1 + dist[now.second.first][now.second.second];
                        dq.push_back({1,{goi,goj}});
                    }
                    else{
                        dist[goi][goj] = dist[now.second.first][now.second.second];
                        dq.push_front({0,{goi,goj}});
                    }
                }
            }
        }
    }
    cout<<ans;
}

