      Cost[i][j] = min(min(i, N-1-i), min(j, N-1-j));
    }
  }

  //map<pair<ll, ll>, ll> mp;
  vvll mp(N*N, vll(4, 0));
  REP(i,N-1){
    REP(j,N){
      /*
