        int sat = 0;
        for (int col = x - 1; col >= 1; col--) {
            if (t[y][col] == 0)
                sat++;
            else
                mn = min(mn, sat + group[t[y][col]]);
        }
        sat = 0;
        for (int col = x + 1; col <= n; col++) {
            if (t[y][col] == 0)
                sat++;
            else
                mn = min(mn, sat + group[t[y][col]]);
        }
        sat = 0;
        for (int row = y - 1; row >= 1; row--) {
            if (t[row][x] == 0)
                sat++;
            else
                mn = min(mn, sat + group[t[row][x]]);
        }
        sat = 0;
        for (int row = y + 1; row <= n; row++) {
            if (t[row][x] == 0)
                sat++;
            else
                mn = min(mn, sat + group[t[row][x]]);
        }
        bool noGroups = 1;
        for (int i = 0; i < 4; i++) {
            int xx = x + dx[i];
            int yy = y + dy[i];
            if (xx >= 1 && xx <= n && yy >= 1 && yy <= n) {
                if (t[xx][yy] != 0) {
                    noGroups = 0;
                    mn = min(mn, group[t[xx][yy]]);
                }
            }
        }
        if (noGroups) {
            t[x][y] = last_group++;
            group[t[x][y]] = mn;
        } else {
