                int xx = x + dx[i];
                int yy = y + dy[i];
                if (xx >= 1 && xx <= n && yy >= 1 && yy <= n) {
                    if (t[xx][yy] != 0) {
                        group[t[xx][yy]] = mn;
                        t[x][y] = t[xx][yy];
                    }
                }
            }
        }
        ans += mn;
    }
    cout << ans;
}

