vector<vector<int>> d;
vector<vector<bool>> in;
int n;

bool check(int x, int y)
{
    return 0<=x && x<n && 0<=y && y<n;
}

vector<pair<int, int>> neighbours(int x, int y)
{
    vector<pair<int, int>> tmp =  {mp(x-1, y), mp(x+1, y), mp(x, y+1), mp(x, y-1)};
    vector<pair<int, int>> ans;
    for (auto it: tmp) if (check(it.first, it.second)) ans.push_back(it);
    return ans;
}

void dfs(int x, int y)
{
    auto n = neighbours(x, y);
    for (auto it: n)
    {
        int d1 = d[x][y];
        if (in[x][y]) d1++;
        if (d1<d[it.first][it.second])
        {
            d[it.first][it.second] = d1;
            dfs(it.first, it.second);
        }
    }
}

int main() {
    ios_base::sync_with_stdio(0);
    cin.tie(nullptr);


    cin>>n;
    vector<pair<int, int>> a(n*n);
    for (int i = 0; i<n*n; i++)
    {
        int t; cin>>t; t--;
        a[i] = mp(t/n, t%n);
    }

    d = vector<vector<int>>(n, vector<int>(n));
    in = vector<vector<bool>>(n, vector<bool>(n, true));

    for (int i = 0; i<n; i++)
        for (int j = 0; j<n; j++) d[i][j] = min({i, n-i-1, j, n-j-1});

    ll res = 0;
    for (auto it: a)
    {
        res+=d[it.first][it.second];
        in[it.first][it.second] = false;
        dfs(it.first, it.second);
    }

    cout<<res<<endl;


}

