int n;

void update(vv(int) &dist, vv(bool) &emp, int y, int x)
{
	int z = dist[y][x];
	if (!emp[y][x])
		++z;

	// 上下左右の席をzと比較
	// より短い距離に更新できる場合 => 更新してその席の上下左右も見る(再帰)
	if (y > 0 && dist[y-1][x] > z)
	{
		dist[y-1][x] = z;
		update(dist, emp, y-1, x);
	}
	if (y < n-1 && dist[y+1][x] > z)
	{
		dist[y+1][x] = z;
		update(dist, emp, y+1, x);
	}
	if (x > 0 && dist[y][x-1] > z)
	{
		dist[y][x-1] = z;
		update(dist, emp, y, x-1);
	}
	if (x < n-1 && dist[y][x+1] > z)
	{
		dist[y][x+1] = z;
		update(dist, emp, y, x+1);
	}
}

int		main(void)
{
	cin >> n;

	vector<int> P(n*n);
	for (int i = 0; i < n*n; ++i)
	{
		cin >> P[i];
	}

	vv(bool) emp(n, vector<bool>(n, false));
	vv(int) dist(n, vector<int>(n));
	// 00000
	// 01110
