	// 01110
	// 00000
	for (int i = 0; i < n; ++i)
	{
		for (int j = 0; j < n; ++j)
		{
			dist[i][j] = min(min(j, n-j-1), min(i, n-i-1));
		}
	}

	int ans = 0;
	for (int i = 0; i < n*n; ++i)
	{
		int x = P[i] % n - 1;
		int y = P[i] / n; 
		if (P[i] % n == 0)
		{
			x = n-1;
			y--;
		}

		ans += dist[y][x];
		emp[y][x] = true;

		update(dist, emp, y, x);
	}
	cout << ans << endl;
}

