using namespace std;

const int N = 501;
const int dx[4] = {0, 0, 1, -1};
const int dy[4] = {1, -1, 0, 0};

int n, a[N], is[N][N], h[N][N];
long long ans = 0;

bool check(int x, int y) {
    return (x >  0 && y > 0 && x <= n && y <= n);
}

void calc_h() {
    for (int i = 1; i <= n; i++)
        for (int j = 1; j <= n; j++)
            h[i][j] = min(min(i - 1, n - i), min(j - 1, n - j));
}

void relax(int x, int y) {
    is[x][y] = 0;
    queue<pi> q;
    q.push({x, y});
    while (!q.empty()) {
        int x = q.front().x, y = q.front().y;
        q.pop();
        for (int d = 0; d < 4; d++) {
            int ax = x + dx[d], ay = y + dy[d];
            if (check(ax, ay) && h[ax][ay] > h[x][y] + is[x][y]) {
                h[ax][ay] = h[x][y] + is[x][y];
                q.push({ax, ay});
            }
        }
    }
}

int main()
{
    cin >> n;
    for (int i = 1; i <= n; i++)
        for (int j = 1; j <= n; j++)
            is[i][j] = 1;
    calc_h();
    for (int i = 1; i <= n * n; i++) {
        int pos;
        cin >> pos;
        int x = pos / n + 1, y = pos % n;
        if (pos % n == 0)
            x--, y = n;
        //cout << h[x][y] << ' ' << h[3][1] << ' ' << h[3][2] << endl;
        ans += h[x][y];
        relax(x, y);
    }
    cout << ans;
    return 0;
}

