using ll = long long;
using P = pair<int, int>;

const ll INF=1e9;
const ll MOD=1e9+7;

int main(int, char**)
{
    int n;
    cin >> n;

    vector < vector<int> > cost(n, vector<int>(n));
    rep(i,n) rep(j,n) {
        cost[i][j] = min(min(i, j), min(n-i-1, n-j-1));
    }
    vector < vector<bool> > pleft(n, vector<bool>(n, false));

    ll ans = 0;
    rep(_,n*n) {
        int ps;
        cin >> ps; ps--;
        int sx = ps / n;
        int sy = ps % n;

        ans += cost[sx][sy];
        pleft[sx][sy] = true;

        int dx[4] = { 0, 1, 0, -1 };
        int dy[4] = { 1, 0, -1, 0 };

        map<P, bool> done;
        queue<P> q;
        P sp = P(sx, sy);
        q.push(sp);
        done[sp] = true;
        while (!q.empty()) {
            int x = q.front().first;
            int y = q.front().second;
            q.pop();

            rep(i,4) {
                int nx = x + dx[i];
                int ny = y + dy[i];
                if (nx < 0 || ny < 0 || nx >= n || ny >= n) continue;

                P np = P(nx, ny);
                if (done[np]) continue;

                if (pleft[x][y]) {
                    cost[nx][ny] = min(cost[nx][ny], cost[x][y]);
                } else {
                    cost[nx][ny] = min(cost[nx][ny], cost[x][y]+1);
                }

                q.push(np);
                done[np] = true;
            }
        }
    }

