// suma de rangos [0,n-1]
void updBIT_ROW(int ind, int p, int val = 1){ 
    p++;	// esto es porque el bit esta indexado desde 1
    for(; p < maxN; p += p&-p) // se puede cambiar maxN por n+1 si hace falta mas velocidad
    	BIT_ROW[ind][p] += val;
}
int sumBIT_ROW(int ind, int p){
    p++;
    int ret = 0;
    for(; p; p -= p&-p) 
    	ret += BIT_ROW[ind][p];
    return ret;
}

void updBIT_COL(int ind, int p, int val = 1){ 
    p++;	// esto es porque el bit esta indexado desde 1
    for(; p < maxN; p += p&-p) // se puede cambiar maxN por n+1 si hace falta mas velocidad
    	BIT_COL[ind][p] += val;
}
int sumBIT_COL(int ind, int p){
    p++;
    int ret = 0;
    for(; p; p -= p&-p) 
    	ret += BIT_COL[ind][p];
    return ret;
}

int get_row(int x){
	return x/n;
}

int get_col(int x){
	return x%n;
}

int main(){
	ri(n);
	FOR(i,0,n){
		FOR(j,0,n){
			updBIT_COL(j,i);
			updBIT_ROW(i,j);
		}
	}

	ll ans = 0;
	FOR(i,0,n*n){
		int aux;
		ri(aux);
		aux--;


		int row = get_row(aux);
		int col = get_col(aux);

		updBIT_ROW(row,col,-1);
		updBIT_COL(col,row,-1);

		ll go_l = sumBIT_ROW(row,col);
		ll go_r = sumBIT_ROW(row,n) - sumBIT_ROW(row,col);
		ll go_u = sumBIT_COL(col,row);
		ll go_d = sumBIT_COL(col,n) - sumBIT_COL(col,row);

		ans += min( min(go_l, go_r) , min(go_u, go_d) );
	}

	printf("%lld\n", ans);

	return 0;
}

