}

void solve() {
    int res = 0;
    rep (i,n*n) {
        int x=p[i]%n, y=p[i]/n; 
        res += step[x][y];
        isAvaliable[x][y] = 0;
        update(x,y); 
    }
    printf(IN,res);
}


