void solve(istream &cin = std::cin, ostream &cout = std::cout)
{
	int n;

	cin >> n;

	vector<int> ord(n * n);

	for (auto &it : ord)
	{
		cin >> it;
		it--;
	}

	vector<vector<bool>> alive(n, vector<bool>(n, true));
	vector<vector<int>> ans(n, vector<int>(n));

	for (int y = 0; y < ans.size(); y++)
		for (int x = 0; x < ans[y].size(); x++)
			ans[y][x] = min(min(y, (int) ans.size() - 1 - y), min(x, (int) ans.size() - 1 - x)) + 1;

	int sum = 0;

	function<void(int, int, int)> dfs = [&ans, &alive, &dfs](int x, int y, int ns)
	{
		if (y < 0 || y >= ans.size() ||
		    x < 0 || x >= ans[y].size())
			return;

		if (alive[y][x])
			ns++;

		if (ns >= ans[y][x])
			return;

		ans[y][x] = ns;

		for (int i = 0; i < 4; i++)
			dfs(x + dx[i], y + dy[i], ns);
	};

	for (auto it : ord)
	{
		int y = it / (int) ans.size();
		int x = it % (int) ans.size();

		auto add = ans[y][x] - 1;
		sum += add;
		alive[y][x] = false;

		dfs(x, y, add);
	}

	cout << sum << endl;
}


