void build(int row,int i,int l,int r){
    if(l==r){
        segment[row][i]=1;
        return;
    }
    int m = (l+r)/2;
    build(row,i<<1,l,m);
    build(row,i<<1|1,m+1,r);
    segment[row][i]=segment[row][i<<1]+segment[row][i<<1|1];
}
void update(int row,int i,int l,int r,int pos){
    if(l==r){
        segment[row][i]=0;
        return ;
    }
    int m = (l+r)/2;
    if(m>=pos)
        update(row,i<<1,l,m,pos);
    else
        update(row,i<<1|1,m+1,r,pos);
    segment[row][i]=segment[row][i<<1]+segment[row][i<<1|1];
}
int query(int row,int i,int l,int r,int x,int y){
    if(l>=x&&r<=y){
        return segment[row][i];
    }
    int m = (l+r)/2;
    int ans = 0 ;
    if(m>=x)
        ans+=query(row,i<<1,l,m,x,y);
    if(m<y)
        ans+=query(row,i<<1|1,m+1,r,x,y);
    return ans;

}
