using namespace std;

typedef long long ll;
#define fi first
#define se second
#define pb push_back

const int N = 512;
int g[N][N], n, vis[N*N], mp[N*N], ed[N*N];
int dx[4] = {0, 1, 0, -1};
int dy[4] = {-1, 0, 1, 0};

int get_idx(int x, int y) {
	if (x < 1 || x > n || y < 1 || y > n) return 0;
	return (x - 1) * n + y;
}

pair <int, int> get_pos(int x) {
	if (x % n == 0) {
		return {x / n, n};
	} else {
		return {x / n + 1, x % n};
	}
}

int _01BFS(int x, int y, int T) {
	deque <pair <int, int> > dq;
	dq.push_back({x, y});
	mp[get_idx(x, y)] = 0;
	ed[get_idx(x, y)] = T;
	while (!dq.empty()) {
		int cx = dq.front().fi, cy = dq.front().se;
		dq.pop_front();
		if (cx < 1 || cx > n || cy < 1 || cy > n) {
			return mp[get_idx(cx, cy)];
		}
		if (vis[get_idx(cx, cy)] == T) continue;
		vis[get_idx(cx, cy)] = T;
		int dis = mp[get_idx(cx, cy)];
		for (int i = 0; i < 4; i++) {
			int nx = cx + dx[i], ny = cy + dy[i];
			if (ed[get_idx(nx, ny)] == T) {
				if (dis + g[nx][ny] < mp[get_idx(nx, ny)]) {
					mp[get_idx(nx, ny)] = dis + g[nx][ny];
					dq.push_front({nx, ny});
				}
			} else {
				mp[get_idx(nx, ny)] = dis + g[nx][ny];
				ed[get_idx(nx, ny)] = T;
				if (g[nx][ny] == 1) {
					dq.push_back({nx, ny});
				} else {
					dq.push_front({nx, ny});
				}
			}
		}
	}
	return 0;
}

