	scanf("%d", &n);
	int m = n * n;
	for (int i = 1; i <= n; i++) {
		for (int j = 1; j <= n; j++) {
			g[i][j] = 1;
		}
	}
	ll ans = 0;
	for (int i = 0; i < m; i++) {
		int x;
		scanf("%d", &x);
		pair <int, int> p = get_pos(x);
		g[p.fi][p.se] = 0;
		int temp = _01BFS(p.fi, p.se, i + 1);
		//cout << p.fi << " " << p.se << " " << temp << endl;
		ans += temp;
	}
	printf("%lld", ans);
	return 0;
}

