void solution() {
  int n;
  cin >> n;
  int mat[n + 2][n + 2];
  int dst[n + 2][n + 2];
  vector<ii> pos(n * n + 1);
  int val = 1;
  for (int i = 1; i <= n; i++) {
    for (int j = 1; j <= n; j++) {
      pos[val] = ii(i, j);
      mat[i][j] = val++;
    }
  }

  for (int i = 0; i <= n + 1; i++)
    mat[0][i] = mat[i][0] = mat[i][n + 1] = mat[n + 1][i] = -1;
  for (int i = 0; i <= n + 1; i++) {
    for (int j = 0; j <= n + 1; j++) dst[i][j] = INF;
  }

  int ans = 0;
  for (int i = 0; i < n * n; i++) {
    int st;
    cin >> st;
    int x = pos[st].ff;
    int y = pos[st].ss;
    vector<ii> vis;
    deque<ii> q;
    q.push_back(ii(x, y));
    vis.pb(ii(x, y));
    dst[x][y] = 0;
    while (q.size() > 0) {
      int cx = q.front().ff;
      int cy = q.front().ss;
      q.pop_front();

      if (cx == 0 || cx == n + 1 || cy == 0 || cy == n + 1) {
        ans += dst[cx][cy];
        break;
      }

      // move
      if (dst[cx][cy] + (mat[cx + 1][cy] != -1) < dst[cx + 1][cy]) {
        dst[cx + 1][cy] = dst[cx][cy] + (mat[cx + 1][cy] != -1);
        vis.pb(ii(cx + 1, cy));
        if (mat[cx + 1][cy] == -1)
          q.push_front(ii(cx + 1, cy));
        else
          q.push_back(ii(cx + 1, cy));
      }

      if (dst[cx][cy] + (mat[cx - 1][cy] != -1) < dst[cx - 1][cy]) {
        dst[cx - 1][cy] = dst[cx][cy] + (mat[cx - 1][cy] != -1);
        vis.pb(ii(cx - 1, cy));
        if (mat[cx - 1][cy] == -1)
          q.push_front(ii(cx - 1, cy));
        else
          q.push_back(ii(cx - 1, cy));
      }

      if (dst[cx][cy] + (mat[cx][cy + 1] != -1) < dst[cx][cy + 1]) {
        dst[cx][cy + 1] = dst[cx][cy] + (mat[cx][cy + 1] != -1);
        vis.pb(ii(cx, cy + 1));
        if (mat[cx][cy + 1] == -1)
          q.push_front(ii(cx, cy + 1));
        else
          q.push_back(ii(cx, cy + 1));
      }

      if (dst[cx][cy] + (mat[cx][cy - 1] != -1) < dst[cx][cy - 1]) {
        dst[cx][cy - 1] = dst[cx][cy] + (mat[cx][cy - 1] != -1);
        vis.pb(ii(cx, cy - 1));
        if (mat[cx][cy - 1] == -1)
          q.push_front(ii(cx, cy - 1));
        else
          q.push_back(ii(cx, cy - 1));
      }
    }
    for (ii p : vis) dst[p.ff][p.ss] = INF;
    mat[x][y] = -1;
  }
  cout << ans << endl;
}

