template<class T> struct Seg { 
	const T ID = 0; // comb(ID,b) must equal b
	T combine(T a, T b) { return a+b; } 
	int n; vector<T> seg;
	void init(int _n) { n = _n; seg.assign(2*n,ID);}

	void update(int p, T value) {	// set value at position p
		seg[p += n] = value;
		for (p /= 2; p; p /= 2) seg[p] = combine(seg[2*p], seg[2*p+1]);
	}

	T query(int l, int r) {	 // sum on interval [l, r]
		T ra = ID, rb = ID; 
		for (l += n, r += n+1; l < r; l /= 2, r /= 2) {
			if (l&1) ra = combine(ra,seg[l++]);
			if (r&1) rb = combine(seg[--r],rb);
		}
		return combine(ra,rb);
	}
};

int N;

vector<pii> solve(vi row) {
	vector<pii> res (N);
	Seg<int> seg; seg.init(N);
	vector<pii> newarr (N);
	F0R(i, N) newarr[i] = {row[i], i};
	sort(newarr.rbegin(), newarr.rend());
	for (pii data : newarr) {
		int i = data.second;
		int onl = seg.query(0, i);
		int onr = seg.query(i, N-1);
		res[i] = {onl, onr};
		seg.update(i, 1);
	}
	return res;
}

pair<vector<vi>, vector<vi>> calc(vector<vi> grid) {
	vector<vi> d1 (N, vi (N));
	vector<vi> d2 (N, vi (N));
	F0R(i, N) {
		vi row = grid[i];

		vector<pii> res = solve(row);
		F0R(j, N) {
			d1[i][j] = res[j].first;
			d2[i][j] = res[j].second;
		}
	}
	return {d1, d2};
}

