void removeTargetSub(int *personmap, int *distancemap, int *flagmap, int x, int y, int index, int n, int dx, int dy)
{
    int t1 = x + n * y;
    int t2 = x + dx + n * (y + dy);
    if( flagmap[t2] < index)
    {
        if( ( distancemap[t1] + 1 == distancemap[t2] && personmap[t2] < index) || ( distancemap[t1] + 2 == distancemap[t2] && personmap[t2] > index) )
        {
            removeTarget(personmap, distancemap, flagmap, x + dx, y + dy, index, n);
        }
    }
}

void removeTarget(int *personmap, int *distancemap, int *flagmap, int x, int y, int index, int n)
{
    int t = x + n * y;
    distancemap[t]--;
    flagmap[t] = index;
    if( x > 0 ) removeTargetSub(personmap, distancemap, flagmap, x, y, index, n, -1, 0);
    if( x < n - 1 ) removeTargetSub(personmap, distancemap, flagmap, x, y, index, n, 1, 0);
    if( y > 0 ) removeTargetSub(personmap, distancemap, flagmap, x, y, index, n, 0, -1);
    if( y < n - 1 ) removeTargetSub(personmap, distancemap, flagmap, x, y, index, n, 0, 1);
}

int getShortest(int x, int y, int n)
{
    int ans = x;
    if( ans > n - 1 - x ) ans = n - 1 - x;
    if( ans > y ) ans = y;
    if( ans > n - 1 - y ) ans = n - 1 - y;
    return ans + 1;
}

