    for (int j = 0; j < n; ++j) {
      dist[i][j] = min(min(i+1, n-i), min(j+1, n-j));
      a[i][j] = 1;
    }
  }
  int nn = n * n;
  int ans = 0;
  for (int i = 0; i < nn; ++i) {
    int v = p[i];
    queue<int> que;
    int r = v / n, c = v % n;
