int n, a[250004], kyo[504][504], ans, cnt;
bool did[504][504];

void solve(int x, int y, int now, bool f = 0) {

    if (!f)
        if (kyo[x][y] <= now)
            return;
    kyo[x][y] = now;
    cnt++;
    if (x) {
        if (kyo[x - 1][y] > now + !did[x][y])
            solve(x - 1, y, now + !did[x][y]);
    }
    if (y) {
        if (kyo[x][y - 1] > now + !did[x][y])
            solve(x, y - 1, now + !did[x][y]);
    }
    if (x < n - 1) {
        if (kyo[x + 1][y] > now + !did[x][y])
            solve(x + 1, y, now + !did[x][y]);
    }
    if (y < n - 1) {
        if (kyo[x][y + 1] > now + !did[x][y])
            solve(x, y + 1, now + !did[x][y]);
    }
}
signed main() {
    ios::sync_with_stdio(false);
    std::cin.tie(nullptr);
    cin >> n;
    rep(i, n) {
        rep(j, n) {
            cin >> a[i * n + j];
            a[i * n + j]--;
        }
    }

    rep(i, n) {
        rep(j, n) {
            kyo[i][j] = min({i, j, n - i - 1, n - j - 1});
        }
    }

    rep(k, n * n) {
        int x = a[k] / n;
        int y = a[k] % n;
        ans += kyo[x][y];
        did[x][y] = 1;
        solve(x, y, kyo[x][y], 1);
    }
    cout << ans << endl;
}

