void solve() {
    int n;
    cin >> n;
    int p[n*n+1];
    for(int i = 1; i <= n*n; i++)
        cin >> p[i];
    int ans[n+3][n+3];
    bool vis[n+3][n+3];
    memset(vis, 0, sizeof(vis));
    memset(ans, 0, sizeof(ans));
    for(int i = 1; i <= n; i++){
        for(int j = 1; j <= n; j++){
            ans[i][j] = min({i-1, j-1, n-i, n-j});
        }

    }
    int cnt = 0;
    for(int i = 1; i <= n*n; i++){
        int ii = p[i]/n+(p[i]%n > 0);
        int jj = p[i]%n;
        if(jj == 0)jj = n;
        cnt += ans[ii][jj];
        //cout << ans[ii][jj] << endl;
        vis[ii][jj] = 1;
        queue<pii> q;
        q.push(mp(ii, jj));
        ans[ii][jj]--;
        while(!q.empty()){
            int curi = q.front().F;
            int curj = q.front().S;
            q.pop();
            if(curj+1 <= n && ans[curi][curj+1] > ans[curi][curj]+!vis[curi][curj+1]){
                ans[curi][curj+1] = ans[curi][curj]+!vis[curi][curj+1];
                q.push({curi, curj+1});
            }
            if(curj-1 > 0 && ans[curi][curj-1] > ans[curi][curj]+!vis[curi][curj-1]){
                ans[curi][curj-1] = ans[curi][curj]+!vis[curi][curj-1];
                q.push({curi, curj-1});
            }
            if(curi+1 <= n && ans[curi+1][curj] > ans[curi][curj]+!vis[curi+1][curj]){
                ans[curi+1][curj] = ans[curi][curj]+!vis[curi+1][curj];
                q.push({curi+1, curj});
            }
            if(curi-1 > 0 && ans[curi-1][curj] > ans[curi][curj]+!vis[curi-1][curj]){
                ans[curi-1][curj] = ans[curi][curj]+!vis[curi-1][curj];
                q.push({curi-1, curj});
            }
        }
    }
    cout << cnt << endl;
}

