const int dx[4] = {-1, 0, 1, 0};
const int dy[4] = {0, -1, 0, 1};
using pii = pair<int,int>;

int main() {
    int N;
    cin >> N;

    vector<vector<bool>> out(N, vector<bool>(N, false));
    vector<vector<int>> step(N, vector<int>(N, N));

    for_(y,0,N) for_(x,0,N) {
        step[y][x] = min(step[y][x], x);
        step[y][x] = min(step[y][x], N - 1 - x);
        step[y][x] = min(step[y][x], y);
        step[y][x] = min(step[y][x], N - 1 - y);
    }

    int ans = 0;
    for_(i,0,N*N) {
        int P;
        cin >> P;
        --P;

        int sx = P % N;
        int sy = P / N;
        int val = step[sy][sx];

        ans += val;
        out[sy][sx] = true;

        deque<pii> que;
        que.push_back({sx, sy});
        while (!que.empty()) {
            auto [x, y] = que.front(); que.pop_front();
            for_(d,0,4) {
                int nx = x + dx[d], ny = y + dy[d];
                if (nx < 0 or nx >= N or ny < 0 or ny >= N) continue;
                if (step[ny][nx] > val + (out[y][x] ? 0 : 1)) {
                    step[ny][nx] = val + (out[y][x] ? 0 : 1);
                    if (out[y][x]) que.push_front({nx, ny});
                    else que.push_back({nx, ny});
                }
            }
        }
    }
    cout << ans << endl;
}

