		ofo[y][x]=0;
		amo[x][y]=0;
		ll w=accumulate(ofo[y].begin(),ofo[y].begin()+x,0);
		ll j=accumulate(ofo[y].begin()+x,ofo[y].end(),0);
		ll l=accumulate(amo[x].begin(),amo[x].begin()+y,0);
