const int INF = 1001001001;
const int dx[] = {1, 0, -1, 0};
const int dy[] = {0, 1, 0, -1};

struct UnionFind {
  vector<int> data;
  vector<int> minv;
  UnionFind(int n) {
    data.assign(n, -1);
    minv.assign(n, INF);
  }
  pair<int, int> root(int k) {
    if (data[k] < 0) return pair<int, int>(k, minv[k]);
    auto temp = root(data[k]);
    int mi = min(minv[k], temp.second);
    temp.second = mi;
    return temp;
  }
  void unite(int x, int y) {
    x = root(x).first;
    y = root(y).first;
    if (x == y) return;
    if (data[x] > data[y]) swap(x, y);
    data[x] += data[y];
    data[y] = x;
    minv[x] = min(minv[x], minv[y]);
  }
  bool same(int x, int y) {
    return root(x) == root(y);
  }
  int size(int k) {
    return -data[root(k).first];
  }
  int minvalue(int x) {
    return root(x).second;
  }
};

void solve() {
  int n;
  cin >> n;
  vi32 p(n * n);
  cin >> p;
  rep(i, n * n) p[i]--;
  vector<vi32> b(n, vi32(n));
  rep(i, n * n) {
    int x = p[i] % n;
    int y = p[i] / n;
    b[x][y] = i;
  }
  UnionFind uf(n * n);
  rep(i, n) rep(j, n) {
    int mi = min({i, n - i - 1, j, n - j - 1});
    uf.minv[b[i][j]] = mi;
  }
  i64 ans = 0;
  rep(i, n * n) {
    int x = p[i] % n;
    int y = p[i] / n;
    rep(k, 4) {
      int nx = x + dx[k];
      int ny = y + dy[k];
      if (nx < 0 || nx >= n || ny < 0 || ny >= n) continue;
      if (i > b[nx][ny]) {
        uf.unite(i, b[nx][ny]);
      }
    }
    ans += uf.minvalue(i);
  }
  cout << ans << endl;
}

