inline int get_dis(int x, int y){
	return min(min(x, y), n - max(x, y) - 1);
}

int main(){
	memset(dis, INF, sizeof(dis));

	scanf("%d", &n);
	for(int i = 0;i < n * n;i++){
		int x; scanf("%d", &x); x--;
		P[x % n][x / n] = i;
	}
	for(int i = 0;i < n;i++){
		Q[0].push({{0, i}, 0}); dis[0][i][0] = 0;
		Q[0].push({{n - 1, i}, 0}); dis[n - 1][i][0] = 0;	
		Q[0].push({{i, 0}, 0}); dis[i][0][0] = 0;
		Q[0].push({{i, n - 1}, 0}); dis[i][n - 1][0] = 0;		
	}
	for(int i = 0;i < n * n;i++){
		for(;!Q[i].empty();Q[i].pop()){
			int cx = Q[i].front().X.X;
			int cy = Q[i].front().X.Y;
			int ck = Q[i].front().Y;
			if(odrad[cx][cy][ck]) continue;
			odrad[cx][cy][ck] = 1;
			for(int m = 0;m < 4;m++){
				int mx = cx + px[m], my = cy + py[m];
