        ans += dist[x][y];
        available[x][y] = false;

        queue<ii> q;
        for(int k = 0; k < 4; k ++){
            int nx = x + dx[k];
            int ny = y + dy[k];
            if(dist[nx][ny] > dist[x][y]){
                dist[nx][ny] = dist[x][y];
                q.push(ii(nx, ny));
