vector<int> conn(int x){
    vector<int> res;
    if(x%n != 0)
        res.push_back(x+1);
    if((x-1)%n != 0)
        res.push_back(x-1);
    if(x+n<=n*n)
        res.push_back(x+n);
    if(x-n >= 1)
        res.push_back(x-n);
    return res;
}
pair<int,int> getInd(int x){
    int row=(x-1)/n;
    int col=x-row*n-1;
    return {row,col};
}
int ans[N][N];
bool taken[N][N];
int main(){
