    loop(i,n){
        loop(j,n){
            ans[i][j] = min({i,j,n-i-1,n-j-1});
        }
    }
    int res=0;
    loop(i,n*n){
        int x=arr[i];
        auto p=getInd(x);
        taken[p.first][p.second]=true;
        int cost = ans[p.first][p.second];
        res+=cost;
        queue<int> q;
        auto nbrs=conn(x);
        for(int g:nbrs){
            auto pg=getInd(g);
            if(ans[pg.first][pg.second]>cost){
                ans[pg.first][pg.second]=cost;
                q.push(g);
            }
        }
        while(!q.empty()){
            int cur=q.front();
            q.pop();
            p=getInd(cur);
            nbrs=conn(cur);
            cost = ans[p.first][p.second]+!taken[p.first][p.second];
            for(int g:nbrs){
                auto pg=getInd(g);
                if(ans[pg.first][pg.second]>cost){
                    ans[pg.first][pg.second]=cost;
                    q.push(g);
                }
            }
        }
    }
    printf("%d\n",res);
}

