int dijkstra(int s,int N)
    {
        int cnt=INF;
        vector<int> dis((N+2)*(N+2),INF);
        dis[s]=0;
        priority_queue<pair<int,int>,vector<pair<int,int>>,greater<pair<int,int>>> que;
        que.push(mp(dis[s],s));
        int u,v;
        while (!que.empty())
        {
            u=que.top().se;
            //cout << u << endl;
            que.pop();
            vector<int> around={u-1,u+1,u+N+2,u-N-2};
            int x;
            for (int i=0;i<4;i++)
            {
                x=around[i];
                //cout << x <<"x"<< endl;
                if (dis[x]>dis[u]+graph[u][x])
                {
                    dis[x]=dis[u]+graph[u][x];
                    if (1<=x%(N+2) &&x%(N+2)<=N && x>N && (N+2)*(N+1)>x) que.push(mp(dis[x],x));
                    else
                    {
                        cnt=min(cnt,dis[x]);
                    }
                }
            } 
        }
        return cnt;
    }
