using namespace std;
#define int long long

vector<vector<int>> seat;
int n;

int bfs(int src) {
    vector<vector<int>> vis(n + 2, vector<int>(n + 2));
    vis[(src - 1) / n + 1][(src - 1) % n + 1] = 1;
    queue<tuple<int, int, int >> q;
    q.push({(src - 1) / n + 1, (src - 1) % n + 1, 0});

    auto valid = [&](int x, int y) {
        return 0 <= x && x <= n + 1 && 0 <= y && y <= n + 1;
    };

    vector<tuple<int, int>> del = {
            {-1, 0},
            {0,  1},
            {1,  0},
            {0,  -1}
    };

    int dx, dy, mx, my;
    int minn = INT_MAX;
    while (!q.empty()) {
        int x, y, d;
        tie(x, y, d) = q.front();
        q.pop();
        if (x == 0 || x == n + 1 || y == 0 || y == n + 1) {
            minn = min(minn, d);
            continue;
        }

        for (auto i:del) {
            tie(dx, dy) = i;
            mx = x + dx;
            my = y + dy;
            if (valid(mx, my) && !vis[mx][my]) {
                q.push({mx, my, d + seat[mx][my]});
                vis[mx][my] = 1;
            }
        }
    }
    return minn;
}

