    seat.resize(n + 2, vector<int>(n + 2));
    for (int i = 1; i <= n; ++i) {
        for (int j = 1; j <= n; ++j) {
            seat[i][j] = 1;
        }
    };

    int sum = 0;
    for (int i = 0; i < n * n; ++i) {
        int a;
        cin >> a;
        sum += bfs(a);
//        cout << a << " " << sum << endl;
        seat[(a - 1) / n + 1][(a - 1) % n + 1] = 0;
    }
