    int n = input<int>();

    vector<vector<int>> graph(n * n + 1);
    auto add_edge = [&](int a, int b) {
        graph[a].push_back(b);
        graph[b].push_back(a);
    };

    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j) {
            if (min(i, j) == 0 or max(i, j) == n - 1)
                add_edge(n * n, i * n + j);

            if (i != 0)
                add_edge((i - 1) * n + j, i * n + j);
            if (j != 0)
                add_edge(i * n + (j - 1), i * n + j);
        }

    vector<int> dist(n * n + 1, TYPEMAX(int)); dist[n * n] = 0;
    vector<char> isbad(n * n + 1, true); isbad[n * n] = false;

    queue<int> q;
    q.push(n * n);

    while (not q.empty()) {
        int v = q.front();
        q.pop();

        for (int u: graph[v])
            if (dist[u] == TYPEMAX(int)) {
                dist[u] = dist[v] + 1;
                q.push(u);
            }
    }

    std::function<void(int)> recalc_neighbors = [&](int v) {
        for (int u: graph[v])
            if (dist[u] > dist[v] + isbad[u]) {
                dist[u] = dist[v] + isbad[u];

                recalc_neighbors(u);
            }
    };

    vector<int> perm(n * n);
    for (int& elem: perm)
        elem = input<int>() - 1;

    int64_t ans = 0;
    for (int x: perm) {
        ans += --dist[x];
        isbad[x] = false;

        recalc_neighbors(x);
    }

    cout << ans << "\n";

    return 0;
}

