template <typename F>
struct y_comb {
  F func;

  template <typename... Args>
  decltype(auto) operator()(Args&&... args) {
    return func(*this, std::forward<Args>(args)...);
  }

  template <typename... Args>
  decltype(auto) operator()(Args&&... args) const {
    return func(*this, std::forward<Args>(args)...);
  }
};

template <typename F>
y_comb(F) -> y_comb<F>;

int main() {
  int n;
  cin >> n;
  int n2 = n + 2;
  auto to2 = [&](int i, int j) {
    return (i + 1) * n2 + j + 1;
  };

  auto dist = vector<int>(n2 * n2);
  for (int i = 0; i < n; i++) {
    for (int j = 0; j < n; j++) {
      dist[to2(i, j)] = min({i, n - 1 - i, j, n - 1 - j});
    }
  }
  auto isOccupied = vector<bool>(n2 * n2, true);
  int ans = 0;

  auto update = y_comb{[&](auto& self, int u) -> void {
    int d = dist[u] + isOccupied[u];
    for (int v : {u - n2, u - 1, u + 1, u + n2}) {
      if (dist[v] > d) {
        dist[v] = d;
        self(v);
      }
    }
  }};

  for (int i = 0; i < n * n; i++) {
    int u;
    cin >> u;
    u--;
    u = to2(u / n, u % n);
    ans += dist[u];
    isOccupied[u] = false;
    update(u);
  }
  cout << ans << '\n';
  return 0;
}

