            A[i][j] = min({i,N-1-i,j,N-1-j});
            if (A[i][j]) check[i][j] = 1;
        }
    }
    auto func=[&](auto&& self, int y, int x)->void {
        rep(i,4) {
            int ny = y + dy[i];
            int nx = x + dx[i];
            if (ny < 0 or ny >= N or nx < 0 or nx >= N) continue;
            if (chmin(A[ny][nx],A[y][x] + check[y][x])) {
                self(self,ny,nx);
            }
        }
    };
    int ans = 0;
    rep(i,N*N) {
        ans += A[y[i]][x[i]];
        check[y[i]][x[i]] = 0;
        func(func,y[i],x[i]);
    }

    cout << ans << ln;
}

