// 四方向への移動ベクトル
const int dx[4] = {1, 0, -1, 0};
const int dy[4] = {0, 1, 0, -1};

// 入力
long long int N;
vector<string> field;
long long int dp[510][510];
bool flag[510][510];

void dfs(long long int h, long long int w) {
  	dp[h][w] -= 1;
  	for (long long int dir = 0; dir < 4; dir++){
      	long long int nh = h + dx[dir];
      	long long int nw = w + dy[dir];
        if (nh < 0 || nh >= N || nw < 0 || nw >= N) continue;
        if (flag[nh][nw] == true && dp[nh][nw] <= dp[h][w] + 1) continue;
      	if (flag[nh][nw] == false && dp[nh][nw] <= dp[h][w]) continue;
      	dfs(nh, nw);
    }
}

int main() {
  	cin >> N;
  	long long int P[N][N];
  	for (long long int i = 0; i < N; i++) for (long long int j = 0; j < N; j++) cin >> P[i][j];
  	for (long long int i = 0; i < N; i++) for (long long int j = 0; j < N; j++) flag[i][j] = true;

  	for (long long int i = 0; i < N; i++) for (long long int j = 0; j < N; j++) {
      	dp[i][j] = i + 1;
      	dp[i][j] = min(dp[i][j], N - i);
      	dp[i][j] = min(dp[i][j], j + 1);
      	dp[i][j] = min(dp[i][j], N - j);
    }

  	long long int count = 0;

  	for (long long int i = 0; i < N; i++) for (long long int j = 0; j < N; j++) {
      	long long int A = P[i][j] - 1;
      	count += dp[A % N][A / N] - 1;
      	flag[A % N][A / N] = false;
      	dfs(A % N, A / N);
    }

  	cout << count << endl;
}

