int A[maxN*maxN];
ll dp[maxN*maxN][4];

ll f(int ind, int choice){ 
	if ( ind == n*n )
		return 0;
	if ( dp[ind][choice] != -1 )
		return dp[ind][choice];

	ll &ret = dp[ind][choice];
	ret = LLINF;

	int row = get_row(A[ind]), col = get_col(A[ind]);
	ll aux = 0;
	if ( choice == 0 ){ // go up
		mat[row][col] = 0;
		FOR(i,0,row)
			aux += mat[i][col];

		FOR(i,0,4)
			ret = min(ret, aux + f(ind+1, i) );

		mat[row][col] = 1;
	}
	else if ( choice == 1 ){ // go down	
		mat[row][col] = 0;
		FOR(i,row+1,n)
			aux += mat[i][col];

		FOR(i,0,4)
			ret = min(ret, aux + f(ind+1, i) );

		mat[row][col] = 1;	
	}
	else if ( choice == 2 ){ // go left
		mat[row][col] = 0;

		FOR(i,0,col)
			aux += mat[row][i];

		FOR(i,0,4)
			ret = min(ret, aux + f(ind+1, i) );

		mat[row][col] = 1;
	}
	else{ // go right
		mat[row][col] = 0;

		FOR(i,col,n)
			aux += mat[row][i];

		FOR(i,0,4)
			ret = min(ret, aux + f(ind+1, i) );

		mat[row][col] = 1;
	}
	return ret;
}

