int main() {

    ios::sync_with_stdio(false); // stdioを使うときはコメントアウトすること
    cin.tie(nullptr);            // インタラクティブ問題ではコメントアウトすること

    int n = in1;
    vector<int> p = qin(n*n);
    FOREACH(x, p) x--;

    vector dp(n*n, 0);
    REP(i, n*n) dp[i] = min({i%n, i/n, n-1-i/n, n-1-i%n});

    vector g(n*n, 1);

    ll ans = 0;
    REP(i, n*n) {
        ans += dp[p[i]];
        g[p[i]] = 0;
        deque<int> q = {p[i]};
        while (q.size()) {
            int u = q.front(); q.pop_front();
            int ux = u % n, uy = u / n;
            if (ux-1 >= 0) { int v = u-1; if (chmin(dp[v], dp[u] + g[u])) q.push_back(v); }
            if (ux+1 <  n) { int v = u+1; if (chmin(dp[v], dp[u] + g[u])) q.push_back(v); }
            if (uy-1 >= 0) { int v = u-n; if (chmin(dp[v], dp[u] + g[u])) q.push_back(v); }
            if (uy-1 <  n) { int v = u+n; if (chmin(dp[v], dp[u] + g[u])) q.push_back(v); }
        }
    }
    say(ans);

}

