typedef pair<int, int> ii;
int da[4] = {0, 1, 0, -1}, db[4] = {1, 0, -1, 0};
long long ans[505][505];
bool seats[505][505];
queue<ii> bfs;
int n, p;
long long curr_ans, final_ans;
#define INF 1023456789123456789

int main(){
    scanf("%d", &n);
    int n2 = n*n;
    memset(seats, true, sizeof seats);
    final_ans = 0;
    for (int i=0; i<n2; ++i){
        scanf("%d", &p);
        int a = (p-1)/n, b = (p-1)%n;
        ans[a][b] = 0;
        seats[a][b] = false;
        bfs.push(ii(a, b));
        curr_ans = INF;
        while (!bfs.empty()){
            int ua, ub; tie(ua, ub) = bfs.front(); bfs.pop();
            //printf("%d %d\n", ua, ub);
            if (ua==0||ua==n-1||ub==0||ub==n-1) curr_ans = min(curr_ans, ans[ua][ub]);
            for (int i=0; i<4; ++i){
                int na = ua + da[i], nb = ub + db[i];
                if (na<0||na>=n||nb<0||nb>=n) continue;
                if (abs(na-a)<abs(ua-a)||abs(nb-b)<abs(ub-b)) continue;
                ans[na][nb] = ans[ua][ub]+(int)seats[na][nb];
                bfs.push(ii(na, nb));
            }
        }
        //printf("%d\n", curr_ans);
        final_ans += curr_ans;
    }
    printf("%lld", final_ans);
    return 0;
}

