template<class T, class U> bool chmin(T& a, U b) { if (a > b) { a = b; return 1; } return 0; }
const int dx[] = {1, 0, -1, 0};
const int dy[] = {0, 1, 0, -1};

int main() {
    int n;
    cin >> n;
    const int m = n * n;
    vector<int> p(m);
    for (int &e : p) { cin >> e; e--; }

    vector<vector<int>> dat(n, vector<int>(n));
    vector<vector<bool>> use(n, vector<bool>(n, false));
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            dat[i][j] = min({i, j, n - i - 1, n - j - 1});
        }
    }

    auto bfs = [&] (int i, int j) {
        use[i][j] = true;
        queue<pair<int, pair<int, int>>> que;
        que.emplace(dat[i][j], pair(i, j));
        while (not que.empty()) {
            auto [val, _p] = que.front();
            auto [x, y] = _p; que.pop();
            if (x < 0 or n <= x or y < 0 or n <= y) continue;
            for (int k = 0; k < 4; k++) {
                int nx = x + dx[k], ny = y + dy[k];
                if (nx < 0 or n <= nx or ny < 0 or n <= ny) continue;
                long long cost = val + (not use[x][y]);
                if (chmin(dat[nx][ny], cost)) {
                    que.emplace(cost, pair(nx, ny));
                }
            }
        }
    };

    long long ans = 0;
    for (const int &e : p) {
        int i = e / n, j = e % n;
        ans += dat[i][j];
        bfs(i, j);
    }

    cout << ans << '\n';

    return 0;
}

