        xy[i] = make_pair(p[i] / n, p[i] % n);
    }

    vector<vector<bool>> isstay(n, vector<bool>(n, true));
    ll ans = 0;

    REP(i, n * n){
        vector<vector<bool>> seen(n, vector<bool>(n, false));

        auto comp = [&](meme a, meme b){
            return (a.first > b.first);
        };

        priority_queue<meme, vector<meme>, decltype(comp)> que {comp};

        que.push(make_pair(0LL, xy[i]));
        seen[xy[i].first][xy[i].second] = true;

        while(!que.empty()){
            auto data = que.top();
            que.pop();
            ll x = data.second.first, y = data.second.second;
            seen[x][y] = true;
            if(x <= 0 || x >= n-1 || y <= 0 || y >= n-1){
                ans += data.first;
                break;
