            REP(j, 4){
                if(seen[x+dx[j]][y+dy[j]] == true) continue;
                if(isstay[x+dx[j]][y+dy[j]] == true){
                    que.push(make_pair(data.first + 1, make_pair(x+dx[j], y+dy[j])));
                }else{
                    que.push(make_pair(data.first, make_pair(x+dx[j], y+dy[j])));
                }
            }
        }

        isstay[xy[i].first][xy[i].second] = false;

    }

    cout << ans <<endl;

