ll solve(ll x,ll y){
    dis[x][y]--;
    queue <pii> q;
    q.push({x,y});
    while(q.size()){
        ll v=q.front().F,u=q.front().S;
        q.pop();
        ll z=dis[v][u]+vis[v+1][u];
        ll b=upd(v+1,u,z);
        if (b){
            q.push({v+1,u});
        }
        z=dis[v][u]+vis[v-1][u];
        b=upd(v-1,u,z);
        if (b){
            q.push({v-1,u});
        }
        z=dis[v][u]+vis[v][u+1];
        b=upd(v,u+1,z);
        if (b){
            q.push({v,u+1});
        }
        z=dis[v][u]+vis[v][u-1];
        b=upd(v,u-1,z);
        if (b){
            q.push({v,u-1});
        }
    }
}
