#include <bits/stdc++.h>

using namespace std;

const int di[4] = {-1, 0, 1, 0};
const int dj[4] = {0, -1, 0, 1};

int main() {
  ios::sync_with_stdio(false);
  cin.tie(0);
  int n;
  cin >> n;
  vector<int> order(n * n);
  for (int i = 0; i < n * n; i++) {
    cin >> order[i];
    --order[i];
  }
  vector<vector<int>> mat(n, vector<int>(n, 1));
  vector<vector<int>> dist(n, vector<int>(n));
  for (int i = 0; i < n; i++) {
    for (int j = 0; j < n; j++) {
      dist[i][j] = min(min(i, j), min(n - 1 - i, n - 1 - j));
    }
  }
  vector<pair<int, int>> que;
  vector<vector<int>> inq(n, vector<int>(n, 0));
  long long ans = 0;
  for (int id : order) {
    int i = id / n;
    int j = id % n;
    ans += dist[i][j];
    mat[i][j] = 0;
    que.clear();
    que.emplace_back(i, j);
    inq[i][j] = 1;
    for (int b = 0; b < (int) que.size(); b++) {
      int mi = que[b].first;
      int mj = que[b].second;
      inq[mi][mj] = 0;
      int val = dist[mi][mj] + mat[mi][mj];
      for (int dir = 0; dir < 4; dir++) {
        int ni = mi + di[dir];
        int nj = mj + dj[dir];
        if (ni >= 0 && nj >= 0 && ni < n && nj < n && val < dist[ni][nj]) {
          dist[ni][nj] = val;
          if (inq[ni][nj] == 0) {
            que.emplace_back(ni, nj);
            inq[ni][nj] = 1;
          }
        }
      }
    }
  }
  cout << ans << '\n';
  return 0;
}

