template<class T, size_t N>
struct InitArray{
  int epoch = 1;
  array<int, N> t{};
  array<T, N> data{};
  // array<T, N> base_data{}
  T& operator[] (size_t at){
    if(t[at] != epoch){
      t[at] = epoch;
      data[at] = T();
      // data[at] = base_data[at]
    }
    return data[at];
  }
  void reset(){
    epoch++;
  }
};

int solve(int n, vector<int> p){
  int M = n+2;
  vector<int> val(M*M, 0);
  for(int i=0; i<n*n; i++){
    int j = p[i]-1;
    int y = j/n + 1;
    int x = j%n + 1;
    int z = y * M + x;
    val[z] = i+1;
  }

  const int inf = M*M;
  vector<int> dist(M*M, inf);
  for(int i=0; i<M; i++){
    dist[0*M + i] = 0;
    dist[i*M + 0] = 0;
    dist[i*M + M-1] = 0;
    dist[(M-1)*M + i] = 0;
  }
  for(int y=1; y<=n; y++){
    for(int x=1; x<=n; x++){
      int z = y * M + x;
      int dy = min(y, M-1-y);
      int dx = min(x, M-1-x);
      dist[z] = min(dy, dx);
    }
  }

  int dx[] = {0, 0, 1,-1};
  int dy[] = {1,-1, 0, 0};

  InitArray<vector<int>, 502> hoge;

  long long ans = 0;
  for(auto i: p){
    hoge.reset();

    int y = (i-1) / n + 1;
    int x = (i-1) % n + 1;
    int z = y*M + x;

    int w = dist[z];
    for(int k:range(4)){
      int yy = y + dy[k];
      int xx = x + dx[k];
      int zz = yy * M + xx;
      w = min(w, dist[zz]);
    }

    dist[z] = w;
    int mn = w;
    int mx = w+1;
    hoge[w].push_back(z);

    while(mn != mx){
      if(hoge[mn].size() == 0){
        mn++;
        continue;
      }
      auto now = hoge[mn].back();
      hoge[mn].pop_back();
      int d = dist[now];
      int y = now / M;
      int x = now % M;

      for(int k:range(4)){
        int yy = y + dy[k];
        int xx = x + dx[k];
        int zz = yy * M + xx;
        int dd = d + (val[z] >= val[zz] ? 0 : 1);
        if(dd < dist[zz]){
          dist[zz] = dd;
          hoge[dd].push_back(zz);
          mx = max(mx, dd+1);
        }
      }
    }
    ans += dist[z];
  }

  println(ans);

  return 0;
}

