inline void push(const int &x, const int &v) {
  if (v < dp[x]) {
    dp[x] = v;
    q.push(x);
  }
}

inline void bfs() {
  while (q.size()) {
    int u = q.front();
    q.pop();
    if (u%n != 1) push(u-1, dp[u]+a[u]);
    if (u%n != 0) push(u+1, dp[u]+a[u]);
    if (u-n > 0) push(u-n, dp[u]+a[u]);
    if (u+n <= n*n) push(u+n, dp[u]+a[u]);
  }
}

