    inv[0]= 0;
    for(int i = 1;i<maxn;++i){
        inv[i] = power((ll)i,MOD1-2LL);
    }
}

/*compute gcd(a,b)*/
template<typename T>
T gcd(T a,T b){
    while(b){
        T t = b % a;
        a = b;
        b = t;
    }
    return a;
}


int main(){
    int n;
    readint(n);
    vector<int> order(n*n + 1); vector<pair<int,int>> pos(n*n+1);
    for(int i = 1;i<=n*n;++i) readint(order[i]);

    int c = 0;
    for(int i = 0;i<n;++i)
        for(int j = 0;j<n;++j)
            pos[++c] = {i,j};


    int ans = 0;
    vector<vector<int>> vis(n,vector<int>(n,0));
    function<bool(int,int)> safe =[&](int x,int y){
        return x>=0 && x<n && y>=0 && y < n;
    };

    function<bool(int,int)> isborder = [&](int x,int y){
        return x ==0 || y == 0 || x == n-1 || y == n-1;
    };

    for(int i = 1; i < (int)order.size();++i){
        int o = order[i];
        // cout << o << " " << pos[o].first << " : " <<pos[o].second<<" => ";
        if(isborder(pos[o].first,pos[o].second)){
            // cout << 0 <<"\n";
            vis[pos[o].first][pos[o].second] = 2;//2 -> confirmed exit
            continue;
        }
        vis[pos[o].first][pos[o].second] = 1;//1 -> initiated exit
        queue<pair<int,pair<int,int>>> q;
        q.push({0,pos[o]});
        set<pair<int,int>> cross;
        int res = -1;
        while(!q.empty()){
            auto p = q.front();
            q.pop();
            if(isborder(p.second.first,p.second.second)){
                res = res ==-1?p.first:min(res,p.first);
                continue;
            }
            for(int i=-1;i<=1;++i){
                for(int j = -1;j<=1;++j){
                    if(abs(i) == abs(j)) continue;
                    int x = p.second.first + i;
                    int y = p.second.second + j;
                    if(!safe(x,y) || vis[x][y] == 1 || cross.count({x,y})) continue;
                    cross.insert({x,y});
                    q.push({p.first + (!vis[x][y]),{x,y}});
                }
            }
        }
        // cout << res <<"\n";
        vis[pos[o].first][pos[o].second] = 2;//1 -> confirmed exit
        ans += res;
    }

    printf("%d\n",ans);


    return 0;
}

