void upd(int x,int y,int z){
	if(!used[x][y])z++;
	if(dist[x][y]<=z)return;
	dist[x][y]=z;
	if(x>0)upd(x-1,y,z);
	if(x<n)upd(x+1,y,z);
	if(y>0)upd(x,y-1,z);
	if(y<n)upd(x,y+1,z);
}

