int dx[] = {0, 0, 1, -1};
int dy[] = {1, -1, 0, 0};

void solve(__attribute__((unused)) bool read) {
  int n;
  cin >> n;
  vector<vector<int>> dist(n, vector<int>(n));
  for (int i = 0; i < n; ++i) {
    for (int j = 0; j < n; ++j) {
      dist[i][j] = min(min(i, n - i - 1), min(j, n - j - 1));
    }
  }
  vector<vector<char>> filled(n, vector<char>(n, true));
  int res = 0;
  queue<pair<int, int>> q;
  for (int w = 0; w < n * n; ++w) {
    int key;
    cin >> key;
    --key;
    int x = key / n, y = key % n;
    res += dist[x][y];
    filled[x][y] = false;
    q.push({x, y});
    while (!q.empty()) {
      int x = q.front().first, y = q.front().second;
      q.pop();
      int candy = dist[x][y] + (filled[x][y] == true);
      //cout << x << " " << y << " " << candy << endl;
      for (int d = 0; d < 4; ++d) {
        int i = x + dx[d], j = y + dy[d];
        if (i >= 0 && i < n && j >= 0 && j < n && dist[i][j] > candy) {
          dist[i][j] = candy;
          q.push({i, j});
        }
      }
    }
  }
  cout << res << "\n";
}

