    {
        for (int j=1;j<=n;j++)
        {
            tot++;
            pos[tot]={i,j};
            f[i][j]={i,j};
            u[i][j]=i; d[i][j]=i;
            l[i][j]=j; r[i][j]=j;
        }
    }
    int ans=0;
    for (int i=1;i<=n*n;i++)
    {
        cin>>p[i];
        ans+=solve(p[i]);
    }
    cout<<ans;
    getchar(); getchar();
    return 0;
}

