  };
  auto conv = [&n](int i, int j) -> int {
    return n * i + j;
  };
  int dist[n][n];
  REP(i, n){
    REP(j, n){
      int x = min(i, n - 1 - i);
      int y = min(j, n - 1 - j);
      dist[i][j] = min(x, y);
    }
  }
  bool exists[n][n];
  REP(i, n) REP(j, n) exists[i][j] = true;
  int ans = 0;
  typedef pair<int, int> P;
  typedef pair<P, int> Pd;
  int dx[] = {1, 0, -1, 0};
  int dy[] = {0, 1, 0, -1};
  REP(num, n * n){
    int i = num / n;
    int j = num % n;
    exists[i][j] = false;
    ans += dist[i][j];
    queue<Pd> q;
    q.push(Pd(P(i, j), -1));
    while(!q.empty()){
      Pd pt = q.front();
      q.pop();
      int x = pt.first.first, y = pt.first.second, d = pt.second;
      REP(k, 4){
        if(d == 0 && k == 2) continue;
