        if(!valid(nx, ny)) continue;
        if(exists[x][y]){
          if(dist[x][y] + 1 < dist[nx][ny]){
            dist[nx][ny] = dist[x][y] + 1;
            q.push(Pd(P(nx, ny), k));
          }
        }else{
          if(dist[x][y] < dist[nx][ny]){
            dist[nx][ny] = dist[x][y];
            q.push(Pd(P(nx, ny), k));
          }
        }
      }
    }
  }
  cout << ans << endl;   
  return 0;
}

