void dijkstra(int sy, int sx, int sd){
	// priority_queue<pair<int,pair<int,int>>,vector<pair<int,pair<int,int>>>,greater<pair<int,pair<int,int>>>> Q;
	queue<pair<int,pair<int,int>>> Q0, Q1;
	bool flag = true;
	d[sy][sx] = sd;

	Q0.push({sd,{sy, sx}});


	while(!Q0.empty() || !Q1.empty()){

		pair<int,pair<int,int>> p;

		if(flag) {
			if(Q0.size()) { //cout<<"<><>"<<endl;
				p = Q0.front();Q0.pop();
			} else {
				flag = !flag;
				continue;
			}
		} else {
			if(Q1.size()) {
				p = Q1.front();Q1.pop();
			} else {
				flag = !flag;
				continue;
			}
		}

		int cost = p.first;
		int vx = p.second.second;
		int vy = p.second.first;
		bool flag = false;

		// cout<<"vy = "<<vy<<" vx = "<<vx<<" cost = "<<cost<<" d = "<<d[vy][vx]<<endl;

		if(d[vy][vx] < cost) continue;

		// if(vx < 1 || vx > N || vy < 1 || vy > N) {
		if(ex[vy][vx]) {
			flag = true;
		}

		for(int k = 0; k < 4; k++){
			int ny = vy + dy[k], nx = vx + dx[k];
			int nc = 1;
			// cout<<"k = "<<k<<endl;
			// cout<<"ny = "<<ny<<" nx = "<<nx<<endl;
			if(nx < 0 || nx > N+1 || ny < 0 || ny > N+1) {
				continue;
			}
			// cout<<"ny = "<<ny<<" nx = "<<nx<<endl;
			if(ex[ny][nx]) {
				if(flag) nc = 0;
			}

			if(ex[ny][nx]) nc = 0;

			// cout<<"ny = "<<ny<<" nx = "<<nx<<endl;

			if(d[ny][nx] > cost + nc) {
				d[ny][nx] = cost + nc;

				if(flag) {
					if(nc == 0) Q0.push({d[ny][nx], {ny, nx}});
					else Q1.push({d[ny][nx], {ny, nx}});
				} else {
					if(nc == 1) Q0.push({d[ny][nx], {ny, nx}});
					else Q1.push({d[ny][nx], {ny, nx}});
				}

			}
		}
	}	
}

