const int N = 500;
int seq[N * N + 5];
int arr[N + 5][N + 5];
int not_empty[N + 5][N + 5];
pair<int,int> pos[N * N + 5];
int ST[2][2 * N + 5][4 * N + 5];
int sz[2][2 * N + 5];

int sudah[N + 5][N + 5];

pair<int,int> idx[N * N + 5];

void update(int t, int k, int idx, int l, int r, int tar, int v) {
	if(l == r) {
		ST[t][k][idx] = v;
		return ;
	}
	int mid = (l + r) / 2;
	if(tar <= mid) update(t, k, 2 * idx, l, mid, tar, v);
	else update(t, k, 2 * idx + 1, mid + 1, r, tar, v);
	ST[t][k][idx] = min(ST[t][k][2 * idx], ST[t][k][2 * idx + 1]);
}

int query(int t, int k, int idx, int l, int r, int le, int ri) {
	if(ri < l || r < le) return 1000;
	if(le <= l && r <= ri) return ST[t][k][idx];
	int mid = (l + r) / 2;
	return min(query(t, k, 2 * idx, l, mid, le, ri), query(t, k, 2 * idx + 1, mid + 1, r, le, ri));
}

int py[] = {1, 0, -1, 0};
int px[] = {0, 1, 0, -1};

void dfs(int y, int x, int n) {
	update(0, y + x, 1, 0, sz[0][y + x], idx[arr[y][x]].F, 0);
	update(1, y - x + n, 1, 0, sz[1][y - x + n], idx[arr[y][x]].S, 0);
	sudah[y][x] = 0;
	not_empty[y][x] = 1;
	for(int i = 0;i < 4;i++) {
		int ny = y + py[i];
		int nx = x + px[i];
		if(sudah[ny][nx] == 1) dfs(ny, nx, n);
	}
}

void hora(int tc) {
