	int dy[] = { 0,1,0,-1 };
	rep(i, n * n) {
		int x = (p[i] - 1) / n;
		int y = (p[i] - 1) % n;
		ans += dis[x][y];
		ex[x][y] = false;
		int change = inf;
		if (x != 0) chmin(change, dis[x - 1][y] + ex[x - 1][y]);
		if (x != n - 1) chmin(change, dis[x + 1][y] + ex[x + 1][y]);
		if (y != 0) chmin(change, dis[x][y - 1] + ex[x][y - 1]);
		if (y != n - 1) chmin(change, dis[x][y + 1] + ex[x][y + 1]);
		chmin(dis[x][y], change);
		queue<str> que;
		que.push({ dis[x][y],x,y });
		while (!que.empty()) {
			str q = que.front(); que.pop();
			rep(d, 4) {
				int nx = q.px + dx[d];
				int ny = q.py + dy[d];
				if (0 <= nx && nx < n && 0 <= ny && ny < n&&dis[q.px][q.py] + ex[q.px][q.py] < dis[nx][ny]) {
					dis[nx][ny] = dis[q.px][q.py] + ex[q.px][q.py];
					que.push({ dis[nx][ny],nx,ny });
				}
			}
		}

	}
	cout << ans << '\n';
}

