void Judge(ll gyo,ll re,ll co) {
	b = gyo * N + re;
	if (A[b] <=co) {
		return;
	}
	else {
		A[b] = co;
		if (gone[b]==false)co++;
		if (gyo > 0){
			Judge(gyo - 1, re, co);
		}

		if (gyo < N-1) {
			Judge(gyo + 1, re, co);
		}

		if (re > 0) {
			Judge(gyo, re-1, co);
		}

		if (re < N-1) {
			Judge(gyo, re + 1, co);
		}

	}

}

