bool isEdge(const int N, const int h, const int w) {
    return h == 0 || w == 0 || h == N - 1 || w == N - 1;
}

vector<vector<int>> build(const vector<vector<bool>>& filled) {
    const int N = filled.size();
    // if went to <h,w>, cost will be dist[h][w]
    vector<vector<int>> dist(N, vector<int>(N, INF));
    queue<pii> q;
    rep(h, N)rep(w, N) if (isEdge(N, h, w) && !filled[h][w]) {
        q.push({ h,w });
        dist[h][w] = 0;
    }
    rep(h, N)rep(w, N) if (isEdge(N, h, w) && filled[h][w]) {
        q.push({ h,w });
        dist[h][w] = 1;
    }

    while (!q.empty()) {
        int h, w;
        tie(h, w) = q.front(); q.pop();
        rep(d, 4) {
            int nh = h + dh[d], nw = w + dw[d];
            if (!isin(N, N, nh, nw))continue;
            int ndist = dist[h][w] + (filled[h][w] ? 1 : 0);
            if (dist[nh][nw] <= ndist)continue;
            dist[nh][nw] = dist[h][w] + 1;
            q.push({ nh,nw });
        }
    }
    return dist;
}

