        int h = p / N, w = p % N;
        ress.push_back(dist[h][w] - 1);
        dist[h][w]--;
        filled[h][w] = false;

        queue<pii> q;
        rep(d, 4) {
            int nh = h + dh[d], nw = w + dw[d];
            if (isin(N, N, nh, nw))q.push({ nh,nw });
        }

        while (!q.empty()) {
            auto now = q.front(); q.pop();
            int score = INF;
            rep(d, 4) {
                int nh = now.first + dh[d], nw = now.second + dw[d];
                if (!isin(N, N, nh, nw))continue;
                score = min(score, dist[nh][nw] + (filled[now.first][now.second] ? 1 : 0));
            }
            if (score < dist[now.first][now.second]) {
                dist[now.first][now.second] = score;
                rep(d, 4) {
                    int nh = now.first + dh[d];
