	vl a(s.size());
	ll si = s.size();
	rep2(i, 1, s.size()) {
		if (i + a[i - c] < c + a[c])
		{
			a[i] = a[i - c];
		}
		else {
			ll j = max(0LL, a[c] - (i - c));
			while (i + j < si && s[j] == s[i + j])
			{
				j++;
			}

			a[i] = j;
