int leave(int row, int col, int bad_pair, int *seat)
{
  if (seat[(row+1)*(n+2)+col] == 0 || seat[(row-1)*(n+2)+col] == 0 ||
      seat[row*(n+2)+col+1] == 0 || seat[row*(n+2)+col-1] == 0) {
    return bad_pair;
  }

  seat[row*(n+2)+col] = 2;
  bad_pair += 1;
  int pair = n;
  if (seat[(row+1)*(n+2)+col] != 2) {
    int tmp = leave(row + 1, col, bad_pair, seat);
    if (tmp < pair) {
      pair = tmp;
    }
  }
  if (seat[(row-1)*(n+2)+col] != 2) {
    int tmp = leave(row - 1, col, bad_pair, seat);
    if (tmp < pair) {
      pair = tmp;
    }
  }
  if (seat[row*(n+2)+col+1] != 2) {
    int tmp = leave(row, col + 1, bad_pair, seat);
    if (tmp < pair) {
      pair = tmp;
    }
  }
  if (seat[row*(n+2)+col-1] != 2) {
    int tmp = leave(row, col - 1, bad_pair, seat);
    if (tmp < pair) {
      pair = tmp;
    }
  }
  seat[row*(n+2)+col] = 1;
  return pair;
}


