pll f(ll n, ll val){
  ll x = (val-1) / n + 1;
  ll y = val % n;
  if(y == 0){
    y = n;
  }
  return {x,y};
}

void dfs(ll n, vvll& grid, vvll& exi, pll cur){
  ll x = cur.first;
  ll y = cur.second;
  ll val = grid[x][y] + exi[x][y];
  REP(i,0,3){
    ll nx = x + dx[i];
    ll ny = y + dy[i];
    if(val < grid[nx][ny]){
      grid[nx][ny] = val;
      dfs(n, grid, exi, {nx, ny});
    }
  }
}

