  cin >> n;

  vector<char> occ(n * n, true);
  vector<int> cost(n * n, false);

  auto outside = [&](int x, int y) {
    return !(0 <= x && x < n && 0 <= y && y < n);
  };

  auto at = [&](int x, int y) -> auto& {
    static char unocc = false;
    if (outside(x, y)) return unocc;
    return occ[x + y * n];
  };

  auto cost_at = [&](int x, int y) -> auto& { return cost[x + y * n]; };

  seq(i, 0, n * n) {
    int x = i % n;
    int y = i / n;
    cost_at(x, y) = min({x, y, n - x - 1, n - y - 1});
  }

  vi A(n * n);
  for (auto& x : A) cin >> x;
  int res = 0;
  for (auto i : A) {
    --i;

    //seq(y,0,n) {
    //  seq(x,0,n) {
    //    cout << cost_at(x,y) << " ";
    //  }
    //  cout << "\n";
    //}
    //cout << "\n";
    int c = cost_at(i%n,i/n);
    res += c;

    // Update
    deque<tuple<int, int, int>> Q;
    Q.push_front({i % n, i / n, c});
    at(i % n, i / n) = false;
    while (!Q.empty()) {
      auto [x, y, cost] = Q.back();
      //cout << x << ", " << y << ", " << cost << endl;
      Q.pop_back();

      int nc = cost + at(x, y);
      auto f = [&nc, &Q, &cost_at, &outside](int nx, int ny) {
        if (!outside(nx, ny) && cost_at(nx, ny) > nc) {
          cost_at(nx, ny) = nc;
          Q.push_front({nx, ny, nc});
        }
      };

      f(x + 1, y);
      f(x - 1, y);
      f(x, y + 1);
      f(x, y - 1);
    }
  }
  cout << res << "\n";
}

