    xy=IN();xy+=(xy-1)/N*2+N+2;a+=dist[xy];p=0,q=0;
    que[p++]=xy;vacant[xy]=1;
    while(p>q)
    {
      xy=que[q++],d=dist[xy]-vacant[xy]+1;
      if(dist[xy-N-2]>d){dist[xy-N-2]=d;que[p++]=xy-N-2;}
      if(dist[xy+N+2]>d){dist[xy+N+2]=d;que[p++]=xy+N+2;}
      if(dist[xy-1]>d){dist[xy-1]=d;que[p++]=xy-1;}
      if(dist[xy+1]>d){dist[xy+1]=d;que[p++]=xy+1;}
    }
  }
  OUT(a-3*N*N);return puts(""),0;
}

