void dij(int x, int y, int f) {
    ans += dis[x][y];
    priority_queue<pair<int, pair<int, int>>, vector<pair<int, pair<int, int>>>, greater<pair<int, pair<int, int>>>> que;
    que.push({dis[x][y], {x, y}});
    mk[x][y] = true;
    while (!que.empty()) {
        auto [d, p] = que.top();
        auto [x, y] = p;
        que.pop();
        if (vis[x][y] == f) continue;
        vis[x][y] = f;
        for (int i = 0; i < 4; i++) {
            int xx =  x + dx[i], yy = y + dy[i];
            if (xx <0 || yy < 0 || xx >= n || yy >= n) continue;
            int v = d + !mk[x][y];
            if (v < dis[xx][yy]) {
                dis[xx][yy] = v;
                que.push({v, {xx, yy}});
            }
        }
    }
}
