queue<pii > qu;

void ins(int x, int y) {
	in[x][y] = 1; qu.push(make_pair(x, y));
}

void work() {
	while (!qu.empty()) {
		pii p = qu.front(); qu.pop();
		in[p.fi][p.se] = 0;
		for (int i = 0; i < 4; ++i) {
			pii q = p;
			q.fi += dir[i][0]; q.se += dir[i][1];
			if (q.fi > 0 && q.fi <= n && q.se > 0 && q.se <= n) {
				int w = dis[p.fi][p.se] + (!is[q.fi][q.se]);
				if (w < dis[q.fi][q.se]) {
					dis[q.fi][q.se] = w;
					if (!in[q.fi][q.se]) ins(q.fi, q.se);
				}
			}
		}
	}
}

