void addEdge(int u,int v,int w){
	//cout<<"add "<<u<<" "<<v<<" "<<w<<endl;
	e[++cnt].v=v;
	e[cnt].w=w;
	e[cnt].nxt=head[u];
	head[u]=cnt;
}
int id(int x,int y){
	return (x-1)*n+y;
}
void setup(){
	for(register int i=1;i<=n*n;i++)dis[i]=1e9;
	vis[0]=1;
	q.push(0);
}
void calc(){
	while(!q.empty()){
		int u=q.front();q.pop();vis[u]=0;
		for(register int i=head[u];i;i=e[i].nxt){
			int v=e[i].v;
			if(dis[v]>dis[u]+e[i].w){
				dis[v]=dis[u]+e[i].w;
				if(!vis[v]){
					vis[v]=1;
					q.push(v);
				}
			}
		}
	}
}
