	for(register int i=1;i<=n;i++){
		for(register int j=1;j<=n;j++){
			if(i==1||i==n||j==1||j==n)addEdge(0,id(i,j),0);
			for(register int k=0;k<4;k++){
				x=i+dx[k];y=j+dy[k];
				//cout<<i<<" "<<j<<" "<<x<<" "<<y<<endl;
				if(x<0||x>n||y<0||y>n)continue;
				else addEdge(id(i,j),id(x,y),1);
			}
		}
	}
	setup();
	calc();
	for(register int i=1;i<=n*n;i++){
		scanf("%d",&x);
		//cout<<"   dis["<<x<<"]="<<dis[x]<<endl;
		ans+=dis[x];
		for(register int j=head[x];j;j=e[j].nxt){
			e[j].w=0;
			int v=e[j].v;
			//cout<<"v="<<v<<endl;
			if(dis[v]>dis[x]){
				dis[v]=dis[x];
				vis[v]=1;
				q.push(v);
				//cout<<"q.push "<<v<<endl;
			}
		}
		calc();
		//for(register int j=1;j<=n*n;j++)cout<<"re["<<j<<"]="<<dis[j]<<endl;
	}
	printf("%d",ans);
	return 0;
}

