  lli d[4]={-1,1,N,0-N};
  Vec(P,lli,N*N,0);
  Vec(G,lli,N*N,0);
  Vec(Fl,bool,N*N,0);
  rep(i,0,N*N)cin >> P[i];
  Vec(dist,lli,N*N,0);
  rep(i,0,N*N){
    A=i%N;
    B=i/N;
    dist[i]=min(min(A,N-A-1),min(B,N-B-1));
  }
  rep(i,0,N*N){
    sum+=dist[P[i]-1];
    queue<lli>que;
    que.push(P[i]-1);
    Vec(sc,bool,N*N,1);
    while(!que.empty()){
      auto v=que.front();que.pop();
      rep(j,0,4){
        auto nv=v+d[j];
        if(0>nv||nv>=N*N)continue;
        if(sc[nv])continue;
        sc[nv]=0;
        chmin(dist[nv],dist[v]);
        if(Fl[nv])que.push(nv);
      }
    }
    Fl[P[i]-1]=1;
  }
  Out(sum);
}

