template<class T = int, class A, class B = int> T my_pow(A a, B b = 2) {
    if(b < 0)return (T)1 / my_pow<T>(a, -b);
#if __cplusplus >= 201703L
    if constexpr(is_floating_point<T>::value) { return pow((T) a, (T) b); }
