int main() {
    init();

    int n; cin >> n;
    VI p(n * n); cin >> p;
    auto a = vec<int>(n + 2, n + 2);
    FOR(i, 0, n)FOR(j, 0, n)a[i + 1][j + 1] = i * n + j + 1;

    vector<pair<int, int>> wh(n * n);
    FOR(i, 0, n * n)wh[i] = make_pair(i / n + 1, i % n + 1);
    VI cost(n * n + 1, 1);
    cost[0] = 0;

    auto dis = defvec<int>(INF, n + 2, n + 2);
    PQ<tuple<ll, int, int>> dik;
    int dy[] = { -1,0,0,1 }, dx[] = { 0,-1,1,0 };
    function<void()> solve = [&]() {
        while (!dik.empty()) {
            int d, y, x;
            tie(d, y, x) = dik.top();
            dik.pop();
            if (dis[y][x] < d)continue;
            FOR(i, 0, 4) {
                int ny = y + dy[i], nx = x + dx[i];
                if (out(ny, nx, n+2, n+2))continue;
                if (!chmin(dis[ny][nx], d + cost[a[ny][nx]]))continue;
                dik.emplace(d + cost[a[ny][nx]], ny, nx);
            }
        }
    };
    dis[0][0] = 0;
    dik.emplace(0, 0, 0);
    solve();

    ll ans = 0;
    FOR(i, 0, n * n) {
        auto [y, x] = wh[p[i] - 1];
        int d = INF;
        FOR(j, 0, 4) {
            int ny = y + dy[j], nx = x + dx[j];
            if (out(ny, nx, n + 2, n + 2))continue;
            chmin(d, dis[ny][nx]);
        }
        cost[p[i]] = 0;
        dis[y][x] = d;
        dik.emplace(d, y, x);
        solve();
        ans += dis[y][x];
    }

    print(ans);

    return 0;
}

