inline void solve() {
    vector<vector<char>> q(n, vector<char>(n, true));

    int ans = 0;

    for (int i = 0; i < n * n; ++i) {
        vector<vector<int>> d(n, vector<int>(n, inf));
        deque<pii> s;

        int x = a[i] / n, y = a[i] % n;
        s.emplace_front(x, y);
        q[x][y] = false;
        d[x][y] = 0;

        while (!s.empty()) {
            pii u = s.front();
            if (u.F == 0 || u.S == 0 || u.F == n - 1 || u.S == n - 1) {
                ans += d[u.F][u.S];
                break;
            }
            s.pop_front();

            vector<pii> g;
            g.emplace_back(u.F - 1, u.S);
            g.emplace_back(u.F + 1, u.S);
            g.emplace_back(u.F, u.S - 1);
            g.emplace_back(u.F, u.S + 1);
            for (auto [v, w] : g) {
                if (d[v][w] > d[u.F][u.S] + q[v][w]) {
                    d[v][w] = d[u.F][u.S] + q[v][w];
                    if (q[v][w]) {
                        s.emplace_back(v, w);
                    } else {
                        s.emplace_front(v, w);
                    }
                }
            }
        }
    }

    cout << ans << "\n";
}

