typedef pair <int, int> pii;

const int MAXN = 5e2 + 5;

int N;
bool vis[MAXN][MAXN];
bool bio[MAXN][MAXN];
int dist[MAXN][MAXN];
int perm[MAXN * MAXN];
vector <pii> todo;

void load() {
	scanf("%d", &N);
	for (int i = 0; i < N * N; i++) {
		scanf("%d", perm + i);
		perm[i]--;
	}
}

void dfs(int x, int y) {
	todo.push_back({x, y});
	vis[x][y] = true;
	for (auto delta : vector <pii>{{0, -1}, {0, 1}, {-1, 0}, {1, 0}}) {
		int nx = x + delta.first;
		int ny = y + delta.second;
		if (nx >= 0 && ny >= 0 && nx < N && ny < N && !vis[nx][ny] && dist[nx][ny] == dist[x][y] + !bio[x][y])
			dfs(nx, ny);
	}
}

int solve() {
	for (int i = 0; i < N; i++)
		for (int j = 0; j < N; j++)
			dist[i][j] = min(min(i, N - i - 1), min(j, N - j - 1));

	int sol = 0;
	for (int i = 0; i < N * N; i++) {
		int cx = perm[i] / N;
		int cy = perm[i] % N;
		sol += dist[cx][cy];
		todo.clear();
		dfs(cx, cy);
		for (auto it : todo) {
			vis[it.first][it.second] = false;
			if (it.first != cx || it.second != cy) 
				dist[it.first][it.second]--;
		}
		bio[cx][cy] = true;
	}

	return sol;
}

int main() {
	load();
	printf("%d\n", solve());
	return 0;
}

