struct Point{
    int x;
    int y;
    void build(int a,int b){
      x=a;y=b;
    }
    vector<Point> next;
    void get_next(vector<vector<int>> const& map){
        int py=y+1;int px=x;
        if(map[py][px]!=inf){
            Point buf;
            buf.x=px;buf.y=py;
            next.push_back(buf);
        }
        py=y-1;px=x;
        if(map[py][px]!=inf){
            Point buf;
            buf.x=px;buf.y=py;
            next.push_back(buf);
        }
        py=y;px=x+1;
        if(map[py][px]!=inf){
            Point buf;
            buf.x=px;buf.y=py;
            next.push_back(buf);
        }
        py=y;px=x-1;
        if(map[py][px]!=inf){
            Point buf;
            buf.x=px;buf.y=py;
            next.push_back(buf);
        }
    }
};

signed main(){
  int n;cin>>n;
  vector<int> p(n*n);
  rep(i,n*n)cin>>p[i];
  vector<vector<int>> cost(n+5,vector<int>(n+5,inf));
  rep1(i,n){
    rep1(j,n){
      int bufy=min(i-1,n-i);
      int bufx=min(j-1,n-j);
      cost[i][j]=min(bufy,bufx);
    }
  }
  int res=0;
  vector<vector<int>> seki(n+5,vector<int>(n+5,1));
  for(const auto& val:p){
    int x=(val-1)%n+1;
    int y=(val-1)/n+1;
    seki[y][x]=0;
    res+=cost[y][x];
    Point s;
    s.build(x,y);
    queue<Point> que;
    que.push(s);
    while(!que.empty()){
      Point buf=que.front();que.pop();
      buf.get_next(cost);
      int num=buf.next.size();
      rep(i,num){
        if(cost[buf.next[i].y][buf.next[i].x]>cost[buf.y][buf.x]+seki[buf.y][buf.x]){
          cost[buf.next[i].y][buf.next[i].x]=cost[buf.y][buf.x]+seki[buf.y][buf.x];
          que.push(buf.next[i]);
        }
      }
    }
  }
  cout<<res<<"\n";
  return 0;
}

