pair<int,bool> min_dist;
pair<int,bool> check(int x,int y)
{
    vis[x][y]=1;
    min_dist.F = min(min_dist.F,min({x,y,n-1-x,n-1-y}));
    if(x==0 || x==n-1 || y==0 || y == n-1){
        min_dist.S = true;
        return min_dist;
    }

    if(c[x-1][y]==0 && !vis[x-1][y])
        min_dist = MP(min(min_dist.F, check(x-1,y).F),min_dist.S);
    if(c[x][y+1]==0 && !vis[x][y+1])
        min_dist = MP(min(min_dist.F, check(x,y+1).F),min_dist.S);
    if(c[x+1][y]==0 && !vis[x+1][y])
        min_dist = MP(min(min_dist.F, check(x+1,y).F),min_dist.S);
    if(c[x][y-1]==0 && !vis[x][y-1])
        min_dist = MP(min(min_dist.F, check(x,y-1).F),min_dist.S);

    return min_dist;
}

