        c[i]=min(min(u,n-1-u),min(v,n-1-v));

    }
    int ans=0;
    ref(i,nn){
        int y;
        cin>>y;
        ans+=c[y];




        used[y]=1;

        sort(a[y].begin(),a[y].end());

        ref(j,a[y].size()-1)
            if (a[y][j-1]==a[y][j]) {a[y].erase(a[y].begin()+j-1);j--;}


        ref(j,a[y].size()){
            sort(a[a[y][j-1]].begin(),a[a[y][j-1]].end());
            ref(k,a[a[y][j-1]].size()-1){
                if (a[a[y][j-1]][k]==a[a[y][j-1]][k-1]) {a[a[y][j-1]].erase(a[a[y][j-1]].begin()+k-1);k--;}
                if(a[a[y][j-1]][k-1]==y) a[a[y][j-1]].erase(a[a[y][j-1]].begin()+k-1);
            }
        }

        ref(j,a[y].size()){
            ref(k,a[y].size())
                if(a[y][j-1]!=a[y][k-1]) a[a[y][j-1]].push_back(a[y][k-1]);

        }

        queue<int> q;
        q.push(y);
        while(q.size()){
            int x=q.front();
            q.pop();
            if(used[x])
                ref(i,a[x].size()){
                    if(!used[a[x][i-1]]&&c[a[x][i-1]]>c[x]) {
                        c[a[x][i-1]]=c[x];
                    q.push(a[x][i-1]);
                }
            }
            else ref(i,a[x].size()){
                if(!used[a[x][i-1]]&&c[a[x][i-1]]>c[x]+1) {
                    c[a[x][i-1]]=c[x]+1;
                    q.push(a[x][i-1]);
                }
            }
        }
    }
