int* hate_buf;
bool *occp_buf;
int** hate;
bool **occp;

int N = 0;

int main()
{

	int i = 0, j = 0;
	int next = 0;
	int hate_pairs = 0;

	cin >> N;	

	// Allocate hate matrix
	hate_buf = new int[N * N];
	hate = new int* [N];	
	for (i = 0; i < N; ++i)
	{
		hate[i] = hate_buf + i * N;
	}

	// Allocate "occupied" matrix
	occp_buf = new bool[N * N];
	occp = new bool* [N];
	for (i = 0; i < N; ++i)
	{
		occp[i] = occp_buf + i * N;
	}

	// Initialize hate array. The deeper, the more hate
	for (i = 0; i < (N / 2 + N % 2); i++)
	{
		for (j = i; j < N - i; j++)
		{
			hate[i][j] = i;
			hate[j][i] = i;
			hate[N - i - 1][j] = i;
			hate[j][N - i - 1] = i;
		}
	}

	// Initialize "occupied" array. 
	for (i = 0; i < N; i++)
	{
		for (j = 0; j < N; j++)
		{
			occp[i][j] = true;
		}
	}

	// Exfil people one by one
	for (i = 0; i < N * N; i++)
	{
		cin >> next;
		next--;	// We start our count from 0, not 1.
		//cout << next << " (" << next / N << ", " << next % N << ")" << "\n";	// NOTE DBG
		occp[next / N][next % N] = false;
		hate_pairs += hate[next / N][next % N];

		//print_hate();	// NOTE DBG

		updt_hate(next % N, next / N);
	}

	cout << hate_pairs;


}

void updt_hate(int y, int x)
{
	find_min_hate(y, x);

	// Propagate outwards from center
	for (int i = 1; i < N; i++)
	{		
		if(x + i/2 > N && x - i/2 <= 0 && y + i / 2 > N && y - i / 2 <= 0)
		for (int j = 0; j < i; j++)
		{
			(find_min_hate(y + (i - j), x + j));
			(find_min_hate(y + (i - j), x - j));
			(find_min_hate(y - (i - j), x + j));
			(find_min_hate(y - (i - j), x - j));
		}
	}

}

bool find_min_hate(int y, int x)
{
	int min_hate = 0;
	int left = 0, right = 0, up = 0, down = 0;

	if (y < 0 || y >= N || x < 0 || x >= N)
		return false;

	if (y > 0)
		left = hate[y - 1][x] + occp[y - 1][x];
	if (y < N - 1)
		right = hate[y + 1][x] + occp[y + 1][x];
	if (x > 0)
		up = hate[y][x - 1] + occp[y][x - 1];
	if (x < N - 1)
		down = hate[y][x + 1] + occp[y][x + 1];

	min_hate = min(min(min(left, right), up) ,down);
	hate[y][x] = min_hate;

	return true;
}


