pi id2g(int id) {
    id -= 1;
    return mp(id / n, id % n);
}

int g2id(int i, int j) {
    if (i < n and i >= 0 and j < n and j >= 0)
        return i * n + j + 1;
    else
        return -1;
}

void solve(int ti) {
    re(n);
    order.resize(n * n);
    re(order);
    adj.clear(), dists.clear(), seen.clear(), exited.clear();
    F0R(i, n) {
        F0R(j, n) {
            int id = g2id(i, j);
            int u = g2id(i, j + 1), d = g2id(i, j - 1), l = g2id(i - 1, j), r = g2id(i + 1, j);
            for (auto nei:{u, d, l, r}) {
                adj[id].ep(nei);
                adj[nei].ep(id);
            }
        }
    }

    priority_queue<pi> pq;//-dist,id
    pq.emplace(-(-1), -1);
    while (not pq.empty()) {
        auto top = pq.top();
        pq.pop();
        if (seen.count(top.second))
            continue;
        else {
            int id = top.second, cost = -top.first;
            dists[id] = cost;
            seen.emplace(id);
            for (auto nei:adj[id]) {
                pq.emplace(-(cost + 1), nei);
            }
        }
    }
    //dijkstra finished round 0
//    auto &distsdbg = dists;


//    _repre.clear();
//    { trav(client, order)_repre[client] = client; }
    int hate = 0;
    function<void(int, int)> update = [&](int updated, int newdist) {
        if (ckmin(dists[updated], newdist)) {
            trav(nei, adj[updated]) {
                update(nei, newdist + (1 - exited.count(updated)));
            }
        }
    };
    trav(leaving, order) {
        hate += dists[leaving];
        exited.emplace(leaving);
//        int mindist = max(0, dists[leaving]);
        trav(nei, adj[leaving]) {
            update(nei, dists[leaving]);
        }
    }
    cout << hate << endl;

}

