struct UnionFind {
  vector<int> data;
  vector<int> minv;
  UnionFind(int n) {
    data.assign(n, -1);
    minv.assign(n, INF);
  }
  pair<int, int> root(int k) {
    if (data[k] < 0) return pair<int, int>(k, minv[k]);
    auto temp = root(data[k]);
    int mi = min(minv[k], temp.second);
    temp.second = mi;
    data[k] = temp.first;
    minv[k] = temp.second;
    return temp;
  }
  void unite(int x, int y) {
    x = root(x).first;
    y = root(y).first;
    if (x == y) return;
    if (data[x] > data[y]) swap(x, y);
    data[x] += data[y];
    data[y] = x;
    minv[x] = min(minv[x], minv[y]);
  }
  bool same(int x, int y) {
    return root(x) == root(y);
  }
  int size(int k) {
    return -data[root(k).first];
  }
  int minvalue(int x) {
    return root(x).second;
  }
};

