ll power(ll x, ll y){
	x %= mod;
	ll ans = 1;
	while(y){
		if(y&1) ans = (ans*x)%mod;
		y /= 2;
		x = (x*x)%mod;
	}
	return ans;
}

void solve(){

	int n;
	cin >> n;
	vector <int> a(n*n);
	rep0(i,n*n) cin >> a[i];

	int val[n][n];
	rep0(i,n) rep0(j,n) val[i][j] = (i-1)*n + j+1;

	ll ans = 0;
	rep0(i,n*n){
		int r = (a[i]-1)/n, c = (a[i]-1)%n;
		int mn = n, tmp = 0;
		rep0(j,r) if(val[j][c]) tmp++;
		mn = min(mn,tmp);
