int calc_max(int h, int w){
    int ret = INF;
    for(int i = 0; i < 4; i++){
        if(in_field(h+dx[i], w+dy[i])){
            ret = min(ret, ans[h+dx[i]][w+dy[i]]);
        }else{
            ret = 0;
        }
    }
    if(used[h][w]) ret++;
    return ret;
}

