    ans[h][w] = calc_max(h, w);
    for(int i = 0; i < 4; i++){
        if(in_field(h+dx[i], w+dy[i])){
            if(calc_max(h+dx[i], w+dy[i]) < ans[h+dx[i]][w+dy[i]]) dfs(h+dx[i], w+dy[i]);
        }
    }
}

