#define MAXN 502
int seat[MAXN][MAXN];
int P[MAXN*MAXN];

char isVisited[MAXN*MAXN];

void init(int N)
{
    int i,j;
    for(j=0;j<N;j++)
    {
        for(i=j;i<N-j;i++)
        {
            seat[j][i]=j;
            seat[i][j]=j;
            seat[N-j-1][i]=j;
            seat[i][N-j-1]=j;
        }
    }
}

int inRange(int x,int y,int N)
{
    return 0<=x && x<N && 0<=y && y<N;
}

void dfs(int x,int y,int N,int val)
{
    isVisited[x*N+y]=1;
    int i,dx,dy;
    int dir[4][2]={{1,0},{-1,0},{0,-1},{0,1}};
    for(i=0;i<4;i++)
    {
        dx=dir[i][0];
        dy=dir[i][1];
        if(inRange(x+dx,y+dy,N))
            {
            if(seat[x+dx][y+dy]<0 && isVisited[(x+dx)*N+(y+dy)]==0)
            {
                dfs(x+dx,y+dy,N,val);
            }
            if(seat[x+dx][y+dy]>val)
            {
                seat[x+dx][y+dy]=val;
            }
        }

    }

}

void output(int N)
{
    int i,j;
    for(i=0;i<N;i++)
    {
        for(j=0;j<N;j++)
        {
            printf("%4d",seat[i][j]);
        }
        printf("\n");
    }
}

int main(void)
{
    int i,N;
