    init(N);
    for(i=0;i<N*N;i++)
    {
        scanf("%d",P+i);
    }
    int x,y;
    int kirai=0;
    for(i=0;i<N*N;i++)
    {
        x=(P[i]-1)/N;
        y=(P[i]-1)%N;
        kirai+=seat[x][y];
        seat[x][y]=-seat[x][y];
        dfs(x,y,N,-seat[x][y]);
        memset(isVisited,0,MAXN);
    }
    printf("%d\n",kirai);

    return 0;
}

