const int INF = 1001001001;
const int dx[] = {1, 0, -1, 0};
const int dy[] = {0, 1, 0, -1};

struct UnionFind {
  vector<int> data;
  vector<int> minv;
  UnionFind(int n) {
    data.assign(n, -1);
    minv.assign(n, INF);
  }
  pair<int, int> root(int k, int v) {
    if (data[k] < 0) {
      minv[k] = min(minv[k], v);
      return pair<int, int>(k, minv[k]);
    }
    auto temp = root(data[k], minv[k]);
    data[k] = temp.first;
    minv[k] = min(minv[k], temp.second);
    temp.second = minv[k];
    return temp;
  }
  void unite(int x, int y) {
    x = root(x, INF).first;
    y = root(y, INF).first;
    if (x == y) return;
    if (data[x] > data[y]) swap(x, y);
    data[x] += data[y];
    data[y] = x;
    minv[x] = min(minv[x], minv[y]);
  }
  bool same(int x, int y) {
    return root(x, INF) == root(y, INF);
  }
  int size(int k) {
    return -data[root(k, INF).first];
  }
  int minvalue(int x) {
    return minv[root(x, INF).first];
  }
};

