using namespace std;

const int N = 505;

int n;
int dist[N][N];
int unused[N][N];
void prec() {
	for(int i = 0; i < n; i++) {
		for(int j = 0; j < n; j++) {
			dist[i][j] = min(j, n - 1 - j);
			dist[i][j] = min(dist[i][j], i);
			dist[i][j] = min(dist[i][j], n - 1 - i);
			unused[i][j] = 1;
		}
	}
}

int dx[] = {1,-1, 0, 0};
int dy[] = {0, 0, 1,-1};

int getmn(int i, int j) {
	int mn = dist[i][j];
	for(int k = 0; k < 4; k++) {
		int x = i + dx[k], y = j + dy[k];
		if(x < 0 or x >= n or y < 0 or y >= n) {
			mn = 0;
			break;
		}
		mn = min(mn, dist[x][y] + unused[x][y]);
	}
	return mn;
}

void push(int i, int j, int val) {
	deque<pair<int, int>> q;
	dist[i][j] = val;
	q.emplace_back(i, j);
	while(!q.empty()) {
		tie(i, j) = q.front(); q.pop_front();
		for(int k = 0; k < 4; k++) {
			int x = i + dx[k], y = j + dy[k];
			if(x < 0 or x >= n) continue;
			if(y < 0 or y >= n) continue;
			if(unused[i][j]) {
				if(dist[x][y] > dist[i][j] + 1) {
					dist[x][y] = dist[i][j] + 1;
					q.emplace_back(x, y);
				}
			}
			else {
				if(dist[x][y] > dist[i][j]) {
					dist[x][y] = dist[i][j];
					q.emplace_front(x, y);
				}
			}
		}
	}
}

int solve(int u) {
	int i = u / n, j = u % n;
	int ret = dist[i][j];
	unused[i][j] = 0;
	push(i, j, getmn(i, j));
// 	printf("%d\n", ret);
	return ret;
}

int p[N*N];
int main() {

	scanf("%d", &n);

	prec();

	for(int i = 0; i < n * n; i++) scanf("%d", p+i), p[i]--;

	int ans = 0;

	for(int i = 0; i < n * n; i++) {
		ans += solve(p[i]);
	}

	printf("%d\n", ans);
}

