bool dead[500][500];
int dist[500][500];

inline bool issafe(int y, int x) noexcept {
  return 0 <= y && y < N && 0 <= x && x < N;
}

inline int safe_dist(int y, int x) {
  return issafe(y, x) ? dist[y][x] : 0;
}
inline int safe_dead(int y, int x) {
  return issafe(y, x) ? dead[y][x] : 1;
}

void update(int y, int x) {
  dead[y][x] = 1;

  int du = safe_dist(y-1, x) + !safe_dead(y-1, x);
  int dd = safe_dist(y+1, x) + !safe_dead(y+1, x);
  int dl = safe_dist(y, x-1) + !safe_dead(y, x-1);
  int dr = safe_dist(y, x+1) + !safe_dead(y, x+1);

  int cd = min<int>(du, min<int>(dd, min<int>(dl, dr)));
  dist[y][x] = cd;

  queue<pair<int, int>> que;
  que.emplace(y, x);
  while(!que.empty()) {
    int y = que.front().first;
    int x = que.front().second;
    que.pop();

    int alive = !dead[y][x];
    int d = dist[y][x];
    for (auto v : FourMoving) {
      int y2 = y + v[0];
      int x2 = x + v[1];
      if (!issafe(y2, x2)) continue;
      if (dist[y2][x2] > d + alive) {
        dist[y2][x2] = d + alive;
        que.emplace(y2, x2);
      }
    }
  }

}

int main() {
  scanner >> N;

  repeat(i, N) {
    auto dy = min(i, N-1-i);
    repeat(j, N) {
      dist[i][j] = min(dy, min(j, N-1-j));
    }
  }

  const int nn = N*N;
  ll result = 0;
  repeat(i, nn) {
    int a; scanner >> a; --a;
    if (a < 0) break; // for debug
    int y = a/N;
    int x = a%N;
    // LOG << FMTM(dist, N, N);
    result += dist[y][x];
    update(y, x);
  }

  cout << result << endl;

  return 0;
}

