			inv[p[i*N+j]] = i*N+j;
			grid[i][j] = i*N+j;
		}
	}


	ll ans = 0;

	for (int k = 0; k < N*N; k++) {
		int val = p[k];
		int i = val / N;
		int j = val % N;
		// Try each of the 4 directions.
		int cur = N;
		for (int q = 0; q < 4; q++) {
			int ii = i;
			int jj = j;
			int count = 0;
			while (inside(ii + dx[q], jj + dy[q], N)) {
				ii += dx[q];
				jj += dy[q];
				if (inv[grid[ii][jj]] > k) count++;
			}
			cur = min(cur, count);
		}
		ans += cur;
	}

	cout << ans << endl;
}

#include<iostream>
#include<vector>
using namespace std;

vector<int> G[250001];
int h[250001];
int e[250001];

void visit(int v){
    int i;

    h[v]--;

    for(i=0; i<G[v].size(); i++){
        if(h[v]+e[v]<h[G[v][i]]){
            visit(G[v][i]);
        }
    }
}

void search(int v){
    int i;
    for(i=0; i<G[v].size(); i++){
        if(h[v]<h[G[v][i]]){
            visit(G[v][i]);
        }
    }
}

int main(){
    //input
    int N;
    cin >> N;
    int P[N*N+1];
    int i,j;
    for(i=1; i<=N*N; i++){
        cin >> P[i];
    }

    //calc
    for(i=0; i<=N-1; i++){
        for(j=1; j<=N-1; j++){
            G[i*N+j].push_back(i*N+j+1);
            G[i*N+j+1].push_back(i*N+j);
        }
    }
    for(j=1; j<=N; j++){
        for(i=0; i<=N-2; i++){
            G[i*N+j].push_back((i+1)*N+j);
            G[(i+1)*N+j].push_back(i*N+j);
        }
    }
    for(i=0; i<=N-1; i++){
        for(j=1; j<=N; j++){
            h[i*N+j]=i;
            h[i*N+j]=min(h[i*N+j],N-1-i);
            h[i*N+j]=min(h[i*N+j],j-1);
            h[i*N+j]=min(h[i*N+j],N-j);
        }
    }
    for(i=1; i<=N*N; i++){
        e[i]=1;
    }
    int ans=0;
    for(i=1; i<=N*N; i++){
        ans += h[P[i]];
        e[P[i]]=0;
        search(P[i]);
    }

    //answer
    cout << ans << endl;
    system("pause");
    return 0;
}

