int p[N * N];
int sz[N * N];
int ans[N * N];

int find(int x){
	if (x == p[x]){
		return x;
	}
	return p[x] = find(p[x]);
}

bool alive[N * N];

void unite(int x, int y){
	x = find(x);
	y = find(y);
	if (x == y){
		return;
	}

	if (sz[x] < sz[y]){
		swap(x, y);
	}

	p[y] = x;
	sz[x] += sz[y];
	setmin(ans[x], ans[y]);
}

int idx[N][N];
PII IDX[N * N];

