int main(){
    int n;
    vector<int> p;
    cin >> n;
    for(int i = 0; i < n*n; i++){
        int j;
        cin >> j;
        p.push_back(j);
    }
    int mp[n+2][n+2];
    for(int i = 1; i <= n; i++){
        for(int j = 1; j <= n; j++){
            mp[i][j]=min(n-i,n-j);
            mp[i][j]=min(mp[i][j],i-1);
            mp[i][j]=min(mp[i][j],j-1);
        }
    }
    for(int i = 0; i <= n+1; i++){
        mp[i][0] = 0;
        mp[i][n+1] = 0;
        mp[0][i] = 0;
        mp[n+1][i] = 0;
    }

    ll ans = 0;
    int dir1[] = {1,0,-1,0};
    int dir2[] = {0,1,0,-1};
    for(int i = 0; i < n*n; i++){
        int h = p[i]/n +1;
        int w = p[i]%n;
        if(w == 0){
            w = n;
            h--;
        }
        ans+=mp[h][w];
        queue<pair<int,pair<int,int> > > bq;
        map<pair<int,int>,int> done;
        bq.push(make_pair(mp[h][w],make_pair(h,w)));
        mp[h][w] = -1;
        while(bq.size() > 0){
            auto tmp = bq.front();
            bq.pop();
            int c = tmp.first;
            auto pt = tmp.second;
            done[pt] = 1;
            for(int j = 0; j < 4; j++){
                auto next = make_pair(pt.first+dir1[j],pt.second+dir2[j]);
                if(done.count(next)) continue;
                if(mp[next.first][next.second] > c){
                    mp[next.first][next.second] = c;
                    bq.push(make_pair(c+1,make_pair(next.first,next.second)));
                } else if(mp[next.first][next.second] == -1){
                    bq.push(make_pair(c,make_pair(next.first,next.second)));
                }
            }
        }
    }

    std::cout << ans << endl;
    return 0;
}

