const int kMaxN = 512;

int n;
int dist[kMaxN][kMaxN];
bool occupied[kMaxN][kMaxN];

int dr[4] = {-1, 0, 1, 0};
int dc[4] = {0, -1, 0, 1};

void Recompute(int sr, int sc) {
	queue<pii> q;
	q.push({sr, sc});

	while (!q.empty()) {
		auto [r, c] = q.front();
		q.pop();
		for (int i = 0; i < 4; ++i) {
			int nr = r + dr[i];
			int nc = c + dc[i];
			if (nr < 0 || nc < 0 || nr >= n || nc >= n) { continue; }
			int cand = dist[r][c] + occupied[r][c];
			if (dist[nr][nc] > cand) {
				debug() << imie(nr) << imie(nc) << imie(dist[nr][nc]) << imie(r) << imie(c);
				dist[nr][nc] = cand;
				q.push({nr, nc});
			}
		}
	}
}

int main() {
	ios_base::sync_with_stdio(0);
	cin.tie(0);
	cout << fixed << setprecision(11);
	cerr << fixed << setprecision(6);

	cin >> n;
	for (int i = 0; i < n; ++i) {
		for (int j = 0; j < n; ++j) {
			dist[i][j] = min({i, j, n-i-1, n-j-1});
			occupied[i][j] = true;
		}
	}

	ll ans = 0;

	for (int i = 0; i < n * n; ++i) {
		int who;
		cin >> who;
		--who;
		int row = who / n;
		int col = who % n;
		ans += dist[row][col];
		occupied[row][col] = false;
		Recompute(row, col);
	}

	cout << ans << "\n";
}

