struct tree {
    int t[N];
    void update(int id, int add) {
        while(id <= 500) {
            t[id] += add;
            id += id & (-id);
        }
    }
    int get(int id) {
        int ret=0;
        while(id) {
            ret += t[id];
            id -= id & (-id);
        }
        return ret;
