void insert(int x,int y){
	//cout2(x,y);
	x=find(x);
	y=find(y);
	if(x==y)
		return;
	if(size[x]<=size[y]){
		size[y]+=size[x]+1;
		a[x]=y;
		l[y]=min(l[y],l[x]);
		r[y]=max(r[y],r[x]);
		u[y]=min(u[y],u[x]);
