int main() {
  int32_t N = 0;
  std::cin >> N;
  std::vector<int32_t> ord(N * N);
  for (auto &&o : ord) std::cin >> o;

  std::vector<std::vector<bool>> grid_e(N, std::vector<bool>(N, true));
  std::vector<std::vector<uint32_t>> grid(N, std::vector<uint32_t>(N, 0));
  for (int32_t c = 0; c < (N + 1) / 2; c++) {
    for (int32_t i = 0; i < N - c * 2; i++) {
      grid[c][c + i] = c;
      grid[(N - 1) - c][c + i] = c;
    }
    for (int32_t i = 1; i < N - c * 2 - 1; i++) {
      grid[c + i][c] = c;
      grid[c + i][(N - 1) - c] = c;
    }
  }

  auto row = [=](int32_t no) { return (no - 1) / N; };
  auto col = [=](int32_t no) { return (no - 1) % N; };

  uint64_t cost = 0;
  for (auto &&e : ord) {
    cost += grid[row(e)][col(e)];
    grid_e[row(e)][col(e)] = false;

    std::queue<int32_t> Q;
    Q.push(e);

    while (!Q.empty()) {
      int32_t q = Q.front();
      int32_t r = row(q), c = col(q);
      Q.pop();

      for (size_t i = 0; i < dx.size(); i++) {
        // todo:dx/dy範囲外チェック
        if ((r + dx[i]) >= 0 && (r + dx[i]) < N && (c + dy[i]) >= 0 &&
            (c + dy[i]) < N)
          if (grid[r + dx[i]][c + dy[i]] > grid[r][c] + grid_e[r][c]) {
            grid[r + dx[i]][c + dy[i]] = grid[r][c] + grid_e[r][c];
            Q.push(q + N * dx[i] + dy[i]);
          }
      }
    }
  }

  std::cout << cost << std::endl;

  return 0;
}

