using namespace std;

constexpr int MAXN = 505;
constexpr int dirX[] = {1, 0, -1, 0}, dirY[] = {0, 1, 0, -1};
int n;
int P[MAXN * MAXN];
int dis[MAXN][MAXN];
bool use[MAXN][MAXN];

queue<pair<int, int>> que;

bool inG(int x, int y) { return 1 <= x && x <= n && 1 <= y && y <= n; }

void BFS() {
  while (!que.empty()) {
    auto [x, y] = que.front();
    que.pop();
    for (int i = 0, d = dis[x][y] + use[x][y]; i < 4; ++i) {
      if (int nx = x + dirX[i], ny = y + dirY[i];
          inG(nx, ny) && dis[nx][ny] > d) {
        dis[nx][ny] = d;
        que.emplace(nx, ny);
      }
    }
  }
}

pair<int, int> id_to_pos(int id) {
  return {(id - 1) / n + 1, (id - 1) % n + 1};
}

int calc() {
  for (int i = 1; i <= n; ++i) fill_n(dis[i] + 1, n, n * n);
  for (int i = 1; i <= n; ++i) fill_n(use[i] + 1, n, true);
  for (int i = 1; i <= n; ++i) dis[i][1] = dis[i][n] = 0;
  for (int i = 2; i < n; ++i) dis[1][i] = dis[n][i] = 0;
  for (int i = 1; i <= n; ++i) {
    que.emplace(i, 1);
    que.emplace(i, n);
  }
  for (int i = 2; i < n; ++i) {
    que.emplace(1, i);
    que.emplace(n, i);
  }
  BFS();
  int ret = 0;
  for (int i = 1; i <= n * n; ++i) {
    auto [x, y] = id_to_pos(P[i]);
    ret += dis[x][y];
    use[x][y] = false;
    que.emplace(x, y);
    for (int i = 0; i < 4; ++i) {
      if (int nx = x + dirX[i], ny = y + dirY[i]; inG(nx, ny))
        que.emplace(nx, ny);
    }
    BFS();
  }
  return ret;
}

