    int cost = h[x][y] + a[x][y];
    for (int k = 0; k < 4; k++) {
        int tx = x + dx[k], ty = y + dy[k];
        if (h[tx][ty] > cost) {
            h[tx][ty] = cost;
            dfs(tx, ty);
        }
    }
}

