#define MAXN 507
using namespace std;
int dist[MAXN][MAXN],ind[MAXN][MAXN],rev[MAXN*MAXN],n;
bool vi[MAXN][MAXN];
bool inside(int x,int y) {return x>=1 && x<=n && y>=1 && y<=n;}
void upd(int x,int y,int nd)
{
	int add=(nd>=ind[x][y])?0:1;
	if(inside(x+1,y) && dist[x+1][y]>dist[x][y]+add) {dist[x+1][y]=dist[x][y]+add; upd(x+1,y,nd);}
	if(inside(x-1,y) && dist[x-1][y]>dist[x][y]+add) {dist[x-1][y]=dist[x][y]+add; upd(x-1,y,nd);}
	if(inside(x,y+1) && dist[x][y+1]>dist[x][y]+add) {dist[x][y+1]=dist[x][y]+add; upd(x,y+1,nd);}
	if(inside(x,y-1) && dist[x][y-1]>dist[x][y]+add) {dist[x][y-1]=dist[x][y]+add; upd(x,y-1,nd);}
}
