		if(inside(x-1,y) && !vi[x-1][y]) {vi[x-1][y]=true; q.push(ind[x-1][y]); dist[x-1][y]=dist[x][y]+1;}
		if(inside(x,y+1) && !vi[x][y+1]) {vi[x][y+1]=true; q.push(ind[x][y+1]); dist[x][y+1]=dist[x][y]+1;}
		if(inside(x,y-1) && !vi[x][y-1]) {vi[x][y-1]=true; q.push(ind[x][y-1]); dist[x][y-1]=dist[x][y]+1;}
	}
	for(int i=1;i<=n*n;i++)
	{
		int x=rev[i]%n,y=(rev[i]-1)/n+1;
		if(x==0) x=n;
		rez+=dist[x][y];
		upd(x,y,i);	

	}
	printf("%d",rez);
}

