        for (j=1;j<=n;j++) upd(i,j);
    }

    for (k=1;k<=n*n;k++) {
        scanf("%d",&p); p--;
        i=p/n+1; j=p %n+1;
        ans+=f[i][j];
        g[i][j]=0;
        dfs(i,j);
    }
    printf("%d",ans);
