ll dijkstra(ll s,ll t,ll N)
    {
        ll cnt=INF;
        vector<vector<ll>> dis(N+2,vector<ll> (N+2,INF2));
        dis[s][t]=0;
        priority_queue<pair<ll,pair<ll,ll>>,vector<pair<ll,pair<ll,ll>>>,greater<pair<ll,pair<ll,ll>>>> que;
        que.push(mp(dis[s][t],mp(s,t)));
        ll u,v;
        while (!que.empty())
        {
            u=que.top().se.fi;
            v=que.top().se.se;
            que.pop();
            vector<pair<ll,ll>> around={mp(u-1,v),mp(u+1,v),mp(u,v+1),mp(u,v-1)};
            ll x,y;
            for (ll i=0;i<4;i++)
            {
                x=around[i].fi;
                y=around[i].se;
                if (dis[x][y]>dis[u][v]+graph[u][v][x][y])
                {
                    dis[x][y]=dis[u][v]+graph[u][v][x][y];
                    //cout << dis[x][y] << " " << x <<y<< endl;
                    if (1<=x &&x<=N && 1<= y&&y <=N) que.push(mp(dis[x][y],mp(x,y)));
                    else
                    {
                        cnt=min(cnt,dis[x][y]/INF);
                    }
                }
            } 
        }
        return cnt;
    }
