    int ans = 0;
    vector<int> s(n * n, 1);
    for(int i = 0; i < n * n; i++)
    {
        function<int(int)> sp = [&](int t) -> int
        {
            vector<int> vis(n * n, 0);
            int x = t / n, y = t % n;
            vis[t] = 1;
            priority_queue< pair<int, int> > pq;
            pq.push(mk(0, t));

            while(pq.size())
            {
                int d = pq.top().fi;
                int t = pq.top().se;
                pq.pop();

                for(int i = 0; i < 4; i++)
                {
                    int nx = t / n + dx[i];
                    int ny = t % n + dy[i];

                    if(nx < 0 || nx >= n || ny < 0 || ny >= n) return -d;
                    int nt = nx * n + ny;
                    if(vis[nt]) continue;
                    vis[nt] = 1;
                    pq.push(mk(d - s[nt], nt));
                }
            }
        };
//        cout <<p[i] <<" " <<sp(p[i]) <<endl;
        ans += sp(p[i]);
        s[p[i]] = 0;
    }
    cout <<ans <<endl;
}

