const int sz = 500;
int id(int i, int j){
    return i * sz + j;
}
int dx[] = {-1, 0, 0, 1};
int dy[] = {0, -1, 1, 0};
int n;
bool ok(int i,int j){
    return 0<= i and i < n and 0 <= j and j < n;
}
int dist[sz * sz];
bool not_used[sz * sz];
void update(int x, int y){
    int temp = dist[id(x, y)] + not_used[id(x, y)];
    for(int i = 0; i < 4; i++){
        int xx = x + dx[i];
        int yy = y + dy[i];
        if(!ok(xx, yy))continue;
        if(dist[id(xx,yy)] > temp){
            dist[id(xx, yy)] = temp;
            update(xx, yy);
        }
    }
}
