    for(int tt = 0; tt < n * n; tt++){
        int p;
        cin >> p;
        p--;
        int x = p / n;
        int y = p % n;
        ll temp = dist[id(x, y)];
        ans += temp;
        not_used[id(x, y)] = false;
        update(x, y);
    }
