int hate[500][500];
bool sheet[500][500];
ll ans;

void update(int x, int y) {
  if (x<0 || x>=N || y<0 || y>=N) return;
//  if (hate[x][y] == 0) return;
//printf("update(%d,%d)\n", x, y);

  if (x>0) {
    if (sheet[x-1][y] && hate[x-1][y] > 0 && hate[x-1][y]+1 < hate[x][y]) {
//printf(" hate[%d][%d] = %d -> %d\n", x, y, hate[x][y], hate[x-1][y]+1);
      hate[x][y] = hate[x-1][y]+1;
      update(x-1, y);update(x+1, y);update(x, y-1);update(x-1, y+1);
    } else if (!sheet[x-1][y] && hate[x-1][y] < hate[x][y]) {
//printf(" !hate[%d][%d] = %d -> %d\n", x, y, hate[x][y], hate[x-1][y]);
      hate[x][y] = hate[x-1][y];
      update(x-1, y);update(x+1, y);update(x, y-1);update(x-1, y+1);
    }
  }

  if (x<N-1) {
    if (sheet[x+1][y] && hate[x+1][y] > 0 && hate[x+1][y]+1 < hate[x][y]) {
//printf(" hate[%d][%d] = %d -> %d\n", x, y, hate[x][y], hate[x+1][y]+1);
      hate[x][y] = hate[x+1][y]+1;
      update(x-1, y);update(x+1, y);update(x, y-1);update(x-1, y+1);
    } else if (!sheet[x+1][y] && hate[x+1][y] < hate[x][y]) {
//printf(" !hate[%d][%d] = %d -> %d\n", x, y, hate[x][y], hate[x+1][y]);
      hate[x][y] = hate[x+1][y];
      update(x-1, y);update(x+1, y);update(x, y-1);update(x-1, y+1);
    }
  }

  if (y>0) {
    if (sheet[x][y-1] && hate[x][y-1] > 0 && hate[x][y-1]+1 < hate[x][y]) {
//printf(" hate[%d][%d] = %d -> %d\n", x, y, hate[x][y], hate[x][y-1]+1);
      hate[x][y] = hate[x][y-1]+1;
      update(x-1, y);update(x+1, y);update(x, y-1);update(x-1, y+1);
    } else if (!sheet[x][y-1] && hate[x][y-1] < hate[x][y]) {
//printf(" !hate[%d][%d] = %d -> %d\n", x, y, hate[x][y], hate[x][y-1]);
      hate[x][y] = hate[x][y-1];
      update(x-1, y);update(x+1, y);update(x, y-1);update(x-1, y+1);
    }
  }

  if (y<N-1) {
    if (sheet[x][y+1] && hate[x][y+1] > 0 && hate[x][y+1]+1 < hate[x][y]) {
//printf(" hate[%d][%d] = %d -> %d\n", x, y, hate[x][y], hate[x][y+1]+1);
      hate[x][y] = hate[x][y+1]+1;
      update(x-1, y);update(x+1, y);update(x, y-1);update(x-1, y+1);
    } else if (!sheet[x][y+1] && hate[x][y+1] < hate[x][y]) {
//printf(" !hate[%d][%d] = %d -> %d\n", x, y, hate[x][y], hate[x][y+1]);
      hate[x][y] = hate[x][y+1];
      update(x-1, y);update(x+1, y);update(x, y-1);update(x-1, y+1);
    }
  }

}
void out(int o) {
  int x,y;

  o--;
  //席o(座標(x,y))の人がいなくなった場合の座席のコスト変化

  x = o/N; y= o%N;

  ans += hate[x][y];    //その席のコストが結果に加算される
//printf("out(%d) %d %lld\n", o+1, hate[x][y], ans);
  sheet[x][y] = false;  //その席を空席にする

  update(x, y);
  //退席した人の前の人
  if (x>0) {
    update(x-1, y);
  }
  //退席した人の左の人
  if (y>0) {
    update(x, y-1);
  }
  //退席した人の後ろの人
  if (x<N-1) {
    update(x+1, y);
  }
  //退席した人の右の人
  if (y<N-1) {
    update(x, y+1);
  }
  update(x, y);
}

