{

  cin >> N;
  P.resize(N*N);
  for (int i=0; i<N*N; i++) {
    cin >> P[i];
    hate[i/N][i%N]=min(min(i/N,N-i/N-1),min(i%N, N-i%N-1));
    sheet[i/N][i%N] = true;
  }

  for (int i=0; i<N*N; i++) {
    out(P[i]);
  }


  cout << ans << endl;
  return 0;
}

