constexpr int kDirections = 4;
constexpr int kDx[kDirections] = {-1, +1, 0, 0};
constexpr int kDy[kDirections] = {0, 0, -1, +1};

int main() {
  ios::sync_with_stdio(false);
  cin.tie(nullptr);

  int n;
  cin >> n;

  vector<int> p(n * n);
  for (int& e: p) {
    cin >> e;
  }

  vector<vector<int>> used(n, vector<int>(n, 0)), value(n, vector<int>(n));
  for (int i = 0; i < n; ++i) {
    for (int j = 0; j < n; ++j) {
      value[i][j] = min({i, j, n - i - 1, n - j - 1});
    }
  }

  long long result = 0;
  for (int e: p) {
    --e;
    int x = e / n;
    int y = e % n;

    result += value[x][y];

    queue<pair<int, int>> q;
    q.push({x, y});
    used[x][y] = 1;
    while (!q.empty()) {
      int x = q.front().first;
      int y = q.front().second;
      q.pop();
      int cost = value[x][y] + (!used[x][y] ? 1 : 0);
      for (int dir = 0; dir < kDirections; ++dir) {
        int nx = x + kDx[dir];
        int ny = y + kDy[dir];
        if (nx < 0 || ny < 0 || nx >= n || ny >= n) continue;
        if (value[nx][ny] <= cost) continue;
        value[nx][ny] = cost;
        q.push({nx, ny});
      }
    }
  }

  cout << result << '\n';
}

