		int x = u.first; int y = u.second;
		inq[x][y] = 0;
		int newDist = dist[x][y] + seats[x][y];
		for (int d = 0; d < 4; d++){
			int x2, y2;
			x2 = x + dx[d];
			y2 = y + dy[d];
			if (inBound(x2,y2)){
				if (newDist < dist[x2][y2]){
					dist[x2][y2] = newDist;
					if (!inq[x2][y2]){
						inq[x2][y2] = 1;
						q.push_back({x2, y2});
					}
				}
			}
		}
	}
}
