void dfs(vector<vector<int> > &ans,vector<vector<bool> > &vis,int row,int col,int &flag,int n){
	if(row==0||col==0||row==n+1||col==n+1)
	{  
		flag=1;
		return;
	}
	if(vis[row][col]==true||ans[row][col]!=0)
	return;
	vis[row][col]=true;
	dfs(ans,vis,row,col+1,flag,n);
	dfs(ans,vis,row,col-1,flag,n);
	dfs(ans,vis,row+1,col,flag,n);
	dfs(ans,vis,row-1,col,flag,n);
	vis[row][col]=false;
}
