std::vector<PII> dirs{MP(0, 1), MP(1, 0), MP(-1, 0), MP(0, -1)};

bool bounds(PII p){
	return p.X >= 0 && p.X < n && p.Y >= 0 && p.Y < n;
}

PII operator +(PII a, PII b){
	return MP(a.X+b.X, a.Y+b.Y);
