int main(){
	std::ios_base::sync_with_stdio(false);
	std::cin.tie(0);
	std::cin >> n;
	FOR(i, n) FOR(j, n) dist[i][j] = std::min(i, std::min(j, std::min(n-1-i, n-1-j)));
	FOR(i, n) FOR(j, n) alive[i][j] = 1;
	ll ans = 0;
	tick = 5;

	FOR(i, n*n){
		int a;
		std::cin >> a;
		a--;
		int x = a/n;
		int y = a%n;
		alive[x][y] = 0;
		ans += dist[x][y];
		auto start = MP(x, y);

		std::queue<PII> que;
		for(auto dir : dirs){
			auto pos = dir+start;
			if(!bounds(pos)) continue;
			que.push(pos);
			last[pos.X][pos.Y] = tick;
		}

		while(SZ(que)){
			auto v = que.front();
			que.pop();

			int old = dist[v.X][v.Y];
			int was = 0;
			for(auto dir : dirs){
				auto pos = dir+v;
				if(!bounds(pos)) continue;
				if(dist[pos.X][pos.Y]+alive[pos.X][pos.Y] < old) was = 1;
			}

			if(was){
				dist[v.X][v.Y]--;
				for(auto dir : dirs){
					auto pos = dir+v;
					if(!bounds(pos)) continue;
					if(last[pos.X][pos.Y] != tick){
						last[pos.X][pos.Y] = tick;
						que.push(pos);
					}
				}
			}
		}

		tick++;

	}
	std::cout << ans;

	return 0;
}

