    b[x][y] = i;
  }
  UnionFind uf(n * n);
  rep(i, n) rep(j, n) {
    int mi = min({i, n - i - 1, j, n - j - 1});
    uf.minv[b[i][j]] = mi;
  }
  i64 ans = 0;
  rep(i, n * n) {
    int x = p[i] % n;
    int y = p[i] / n;
    ans += uf.minvalue(p[i]);
    rep(k, 4) {
      int nx = x + dx[k];
      int ny = y + dy[k];
      if (nx < 0 || nx >= n || ny < 0 || ny >= n) continue;
      if (i > b[nx][ny]) {
        uf.unite(i, b[nx][ny]);
      }
    }
  }
  cout << ans << endl;
}

