template <typename T>
class fenwick{
	private:
	vector<T> bit;
	int n;
	public:
	fenwick(){
		n=MAX;
		bit.assign(n,{0});
	}
	fenwick(int size){
		n=size;
		bit.assign(n,{0});
	}
	void update(int id, T z){
		while(id<=n){
			bit[id]= bit[id] + z;
			id+=(id & (-id));
		}
	}
	T query(int id){
		T ans={0};
		while(id>0){
			ans= ans + bit[id];
			id-=(id & (-id));
		}
		return ans;
	}
};

signed main(){
	ios_base::sync_with_stdio(false);
	cin.tie(0);cout.tie(0);
	int n,i,j;
	cin>>n;
	vector<fenwick<int> > rows(n+1,fenwick<int>(n+1)),cols(n+1,fenwick<int>(n+1));
	for(i=1;i<=n;i++){
		for(j=1;j<=n;j++){
			rows[i].update(j,1);
			cols[j].update(i,1);
		}
	}
	int ans=0;
	for(i=0;i<n*n;i++){
		int x,r,c;
		cin>>x;
		x--;
		r=x/n+1;
		c=x%n+1;
		int rleft = rows[r].query(c-1),rright = rows[r].query(n);
		int cleft = cols[c].query(r-1),cright = cols[c].query(n);
		ans+=min(rleft,min(rright-rleft-1, min(cleft,cright-cleft-1)));
		rows[r].update(c,-1);
		cols[c].update(r,-1);
	}
	cout<<ans<<"\n";
	return 0;
}

