const int maxn = 501;

int pr[maxn * maxn], sz[maxn * maxn];
int p[maxn * maxn], a[maxn][maxn];
int can[maxn][maxn], d[maxn][maxn];
bool kl[maxn][maxn];
int n;

int getp(int x) {
    if (pr[x] == -1) return x;
    return (pr[x] = getp(pr[x]));
}

void unions(int x, int y) {
    x = getp(x); y = getp(y);
    if (x == y) return;
    if (sz[x] < sz[y]) swap(x, y);
    if (sz[x] == sz[y]) ++sz[x];
    pr[y] = x;
}

void upd() {
    for (int i = 0; i < n; i++)
        for (int j = 0; j < n; j++)
            d[i][j] = ((min(i, j) == 0 || max(i, j) == n - 1) ? 1 : -1);
    queue<pi> q;
    for (int i = 0; i < n; i++) {
        q.push({0, i});
        if (i) q.push({i, 0});
        q.push({n - 1, i});
        if (i < n - 1) q.push({i, n - 1});
    }
    while (!q.empty()) {
        int r = q.front().l,
            c = q.front().r;
        q.pop();
        if (r && d[r - 1][c] == -1) {
            q.push({r - 1, c});
            d[r - 1][c] = d[r][c] + 1;
        }
        if (c && d[r][c - 1] == -1) {
            q.push({r, c - 1});
            d[r][c - 1] = d[r][c] + 1;
        }
        if (r < n - 1 && d[r + 1][c] == -1) {
            q.push({r + 1, c});
            d[r + 1][c] = d[r][c] + 1;
        }
        if (c < n - 1 && d[r][c + 1] == -1) {
            q.push({r, c + 1});
            d[r][c + 1] = d[r][c] + 1;
        }
    }
}

void dfs(int r, int c) {
    if (r && d[r][c] + (!kl[r - 1][c]) < d[r - 1][c]) {
        d[r - 1][c] = d[r][c] + (!kl[r - 1][c]);
        dfs(r - 1, c);
    }
    if (c && d[r][c] + (!kl[r][c - 1]) < d[r][c - 1]) {
        d[r][c - 1] = d[r][c] + (!kl[r][c - 1]);
        dfs(r, c - 1);
    }
    if (r < n - 1 && d[r][c] + (!kl[r + 1][c]) < d[r + 1][c]) {
        d[r + 1][c] = d[r][c] + (!kl[r + 1][c]);
        dfs(r + 1, c);
    }
    if (c < n - 1 && d[r][c] + (!kl[r][c + 1]) < d[r][c + 1]) {
        d[r][c + 1] = d[r][c] + (!kl[r][c + 1]);
        dfs(r, c + 1);
    }
}

