    FOR(i, 0, n)FOR(j, 0, n)a[i + 1][j + 1] = i * n + j + 1;

    vector<pair<int, int>> wh(n * n);
    FOR(i, 0, n * n)wh[i] = make_pair(i / n + 1, i % n + 1);
    VI cost(n * n + 1, 1);
