    //0-1BFS(笑)
    deque<pair<ll, ll>> que;
    que.push_back({sx, sy});
    rev.push({sx, sy});
    while (!que.empty())
    {
        pair<ll, ll> p = que.front();
        que.pop_front();
        ll x = p.first, y = p.second;
