        {
            ll nx = x + dx[d], ny = y + dy[d];
            if (nx < 0 || nx >= N || ny < 0 || ny >= N)
            {
                ll ret = dist[x][y];
                while (!rev.empty())
                {
                    auto pp = rev.front();
                    dist[pp.first][pp.second] = 1e9;
                    rev.pop();
                }
                return ret;
            }
            ll d2 = dist[x][y];
            if (field[nx][ny] == '#')
                d2++;
            if (dist[nx][ny] > d2)
            {
                dist[nx][ny] = d2;
                rev.push({nx, ny});
                if (field[nx][ny] == '#')
                {
                    que.push_back({nx, ny});
                }
                else
                {
                    que.push_front({nx, ny});
                }
            }
        }
    }
}
