int reff(int x, int y, vvi & A,int N,vvi flag) {


	if (x + 1 < N) {
		if (A.at(x).at(y) + flag.at(x).at(y) < A.at(x + 1).at(y)) {
			A.at(x + 1).at(y) = A.at(x).at(y)+flag.at(x).at(y);
			reff(x + 1, y, A,N,flag);
		}
	}
	if (0 <= x - 1) {
		if (A.at(x).at(y) + flag.at(x).at(y) < A.at(x - 1).at(y)) {
			A.at(x - 1).at(y) = A.at(x).at(y) + flag.at(x).at(y);
			reff(x - 1, y, A, N,flag);
		}
	}
	if (y + 1 < N) {
		if (A.at(x).at(y) + flag.at(x).at(y) < A.at(x).at(y + 1)) {
			A.at(x).at(y + 1) = A.at(x).at(y) + flag.at(x).at(y);
			reff(x, y + 1, A, N,flag);
		}
	}
	if (0 <= y - 1) {
		if (A.at(x).at(y) + flag.at(x).at(y) < A.at(x).at(y - 1)) {
			A.at(x).at(y - 1) = A.at(x).at(y) + flag.at(x).at(y);
			reff(x, y - 1, A, N,flag);
		}
	}

	return 0;
}

