    for (int i = 0; i < n * n; i++) {
        int p;
        cin >> p; p--;
        int x = p / n, y = p % n;
        ans += g(x, y);
        queue<pair<size_t, size_t>> q;
        for (auto p : g.adjacent_indexes(x, y)) {
            q.push(p);
        }
        Grid<int> visited(n, n);
        while (!q.empty()) {
            auto [t, u] = q.front(); q.pop();
            if (g(t, u) != -1) {
                g(t, u) = min(g(t, u), g(x, y));
            } else if (!visited(t, u)) {
                visited(t, u) = 1;
                for (auto [v, w] : g.adjacent_indexes(t, u)) {
                    if (!visited(v, w)) {
                        q.emplace(v, w);
                    }
                }
            }
        }
        g(x, y) = -1;
    }

    cout << ans << '\n';
}

