void solve(istream &cin = std::cin, ostream &cout = std::cout)
{
	int n;

	while (cin >> n)
	{
		vector<int> order(n * n);
		for (int &it : order)
		{
			cin >> it;
			--it;
		}

		vector<vector<int>> dist(n, vector<int>(n));
		vector<vector<int>> taken(n, vector<int>(n, 1));
		for (int i = 0; i < n; i++)
			for (int j = 0; j < n; j++)
				dist[i][j] = min({i + 1, n - i, j + 1, n - j});

		ll ans = 0;
		for (const int seat : order)
		{
			const int row = seat / n, col = seat % n;
			assert(taken[row][col] == 1);
			/// we don't actually anger ourselves
			ans += dist[row][col] - 1;

			dist[row][col]--;
			taken[row][col] = 0;

			queue<pair<int, int>> q;
			q.emplace(row, col);

			while (!q.empty())
			{
				int r, c;
				tie(r, c) = q.front();
				q.pop();

				static array<int, 4> dr = {-1, +1, 0, 0}, dc = {0, 0, -1, +1};

				for (int d = 0; d < int(dr.size()); d++)
				{
					const int nr = r + dr[d], nc = c + dc[d];
					if (0 <= nr && nr < n && 0 <= nc && nc < n && dist[nr][nc] > dist[r][c] + taken[nr][nc])
					{
						dist[nr][nc] = dist[r][c] + taken[nr][nc];
						q.emplace(nr, nc);
					}
				}
			}
		}

		cout << ans << endl;
	}
}

