class segtree {
public:
	int t[2000];

	void build(int v, int tl, int tr) {
        if (tl == tr)
            t[v] = 1;
        else {
            int tm = (tl + tr) / 2;
            build(v*2, tl, tm);
            build(v*2+1, tm+1, tr);
            t[v] = t[v*2] + t[v*2+1];
        }
    }

    void leave(int v, int tl, int tr, int pos) {
        t[v]--;
        if (tl != tr) {
            int tm = (tl + tr) / 2;
            if (pos <= tm)
                leave(v*2, tl, tm, pos);
            else
                leave(v*2+1, tm+1, tr, pos);
        }
    }

    int sum(int v, int tl, int tr, int l, int r) {
        if (l > r) 
            return 0;
        if (l == tl && r == tr)
            return t[v];
        int tm = (tl + tr) / 2;
        return sum(v*2, tl, tm, l, min(r, tm)) + sum(v*2+1, tm+1, tr, max(l, tm+1), r);
    }
};

