		cost = min(cost, row[r].sum(1, 0, n - 1, c + 1, n - 1));
		cost = min(cost, col[c].sum(1, 0, n - 1, 0, r - 1));
		cost = min(cost, col[c].sum(1, 0, n - 1, r + 1, n - 1));
		row[r].leave(1, 0, n - 1, c);
		col[c].leave(1, 0, n - 1, r);
		ans += cost;
	}
