  int32_t N;
  cin >> N;
  vector<int32_t> P(N);
  Solution *solution = new Solution(N);
  for (int32_t i = 0; i < N; ++i) {
    cin >> P[i];
  }
  const int64_t result = solution->CalculateNumberOfPairs(P);
  cout << result << endl;
  delete solution;

  return 0;
}

