		ans+=dis[x][y];
		//cout<<"After "<<x<<','<<y<<" leaves, ans added by "<<dis[x][y]<<"\n";
		occ[x][y]=0;
	int nd=min(min(dis[x-1][y]+occ[x-1][y],dis[x+1][y]+occ[x+1][y]),min(dis[x][y+1]+occ[x][y+1],dis[x][y-1]+occ[x][y-1]));
		dis[x][y]=nd;
		q.push(mp(x,y));
		while(!q.empty()){
			pii cur=q.front();q.pop();
			int i=cur.F,j=cur.S;
			int nd=dis[i][j]+occ[i][j];
			if (nd<dis[i][j+1]) dis[i][j+1]=nd,q.push(mp(i,j+1));
			if (nd<dis[i][j-1]) dis[i][j-1]=nd,q.push(mp(i,j-1));
			if (nd<dis[i+1][j]) dis[i+1][j]=nd,q.push(mp(i+1,j));
			if (nd<dis[i-1][j]) dis[i-1][j]=nd,q.push(mp(i-1,j));
		}
	}
	cout<<ans<<endl;

	return 0; 
}

