                dist[ni * N + nj] = dist[s];
                que.emplace(ni * N + nj);
            }
        }
        while(que.size()) {
            int now = que.front();
            que.pop();
            for(int k = 0; k < 4; k++) {
                int ni = now / N + dy[k];
                int nj = now % N + dx[k];
