void updrow(int r)
{
    for(int i=1;i<=n;i++)
    {
        dif[r][i] = min (dif[r][i-1]+per[r][i-1] , dif[r][i]);
    }
    for(int i=n;i>0;i--)
    {
        dif[r][i] = min(dif[r][i] , dif[r][i+1]+per[r][i+1]);
    }
}
void updcol(int c)
{
    for(int i=1;i<=n;i++)
    {
        dif[i][c] = min(dif[i-1][c]+per[i-1][c] , dif[i][c]);
    }
    for(int i=n;i>0;i--)
    {
        dif[i][c] = min(dif[i][c] , dif[i+1][c]+per[i+1][c]);
    }
}
