{
    for(int i=0;i<=n+1;i++)dif[0][i]=0;
    for(int i=0;i<=n+1;i++)dif[n][i]=0;
    for(int i=0;i<=n+1;i++)dif[i][0]=0;
    for(int i=0;i<=n+1;i++)dif[i][n]=0;
    for(int i=0;i<=n+1;i++)dif[n+1][i]=0;
    for(int i=0;i<=n+1;i++)dif[i][n+1]=0;
}
