int solve(int i, vvi &g, vpii &v) {
	vvi dis(g.size(), vi(g[0].size(), INF));
	// vvi prev(g.size(), vi(g[0].size(), -1));
	vi di = { 1, 0, -1, 0 }, dj = { 0, 1, 0, -1 };
	int si, sj; tie(si, sj) = v[i];
	priority_queue<pair<int, pii>, vector<pair<int, pii>>, greater<pair<int, pii>>> pq;	
	queue<pii> q;
	dis[si][sj] = 0;
	// pq.push(make_pair(dis[si][sj], pii(si, sj)));
	q.push(pii(si, sj));
	while (!q.empty()) {
		auto t = q.front(); q.pop();
		int ui, uj; tie(ui, uj) = t;
		rep(dir, 4) {
			int vi = ui + di[dir], vj = uj + dj[dir];
			// dbs(ui, uj, vi, vj);
			if (vi < 0 or g.size() <= vi) continue;
			if (vj < 0 or g[0].size() <= vj) continue;
			if (g[vi][vj] <= i) { // 空席
				if (dis[vi][vj] > dis[ui][uj]) {
					dis[vi][vj] = dis[ui][uj];
					if (0 < vi and vi < g.size() - 1 and 0 < vj and vj < g[0].size() - 1) {
						// 出口のマスでない場合で，かつ，距離が短くなった場合のみqに入れる
						q.push(pii(vi, vj));
					}
				}
			} else if (dis[vi][vj] > i) { // 客がいる
				if (dis[vi][vj] > dis[ui][uj] + 1) {
					dis[vi][vj] = dis[ui][uj] + 1;
					if (0 < vi and vi < g.size() - 1 and 0 < vj and vj < g[0].size() - 1) {
						// 出口のマスでない場合で，かつ，距離が短くなった場合のみqに入れる
						q.push(pii(vi, vj));
					}
				}
			}
		}
		// dbl(pq.size()); dbvv(dis);
	}
	int res = INF;
	rep(k, g.size()) {
		chmin(res, dis[0][k]);
		chmin(res, dis[g.size() - 1][k]);
		chmin(res, dis[k][0]);
		chmin(res, dis[k][g.size() - 1]);
	}
	// dbl(i); dbvv(dis); dbl(res);
	return res;
}

int N;

void rec(int ui, int uj, const vvi &g, vvi &dis, int i) {
	vi di = { 1, 0, -1, 0 }, dj = { 0, 1, 0, -1 };
	rep(dir, 4) {
		int vi = ui + di[dir], vj = uj + dj[dir];
		if (vi < 0 or N <= vi) continue;
		if (vj < 0 or N <= vj) continue;
		int d = g[vi][vj] > i ? 1 : 0;
		if (dis[vi][vj] > dis[ui][uj] + d) {
			dis[vi][vj] = dis[ui][uj] + d;
			if (0 < vi and vi < N - 1 and 0 < vj and vj < N - 1) {
				rec(vi, vj, g, dis, i);
			}
		}
	}
}

int dfs(int i, const vvi &g, const vpii &v) {
	int si, sj; tie(si, sj) = v[i];
	vvi dis(N, vi(N, INF));
	dis[si][sj] = 0;
	rec(si, sj, g, dis, i);
	int res = INF;
	rep(k, g.size()) {
		chmin(res, dis[0][k]);
		chmin(res, dis[g.size() - 1][k]);
		chmin(res, dis[k][0]);
		chmin(res, dis[k][g.size() - 1]);
	}
	// dbl(i); dbvv(dis); dbl(res);
	return res;
}

