        ll v1 = y - bity[x].sum(y-1);
        ll v2 = n - y - 1 - (bity[x].sum(n-1) - bity[x].sum(y));
        ll v3 = x - bitx[y].sum(x-1);
        ll v4 = n - x - 1 - (bitx[y].sum(n-1) - bitx[y].sum(x));


        ll res = min(min(v1, v2), min(v3, v4));
        res = max(res, 0LL);
        ans += res;
        bitx[y].add(x, 1LL);
        bity[x].add(y, 1LL);
    }




