#include<bits/stdc++.h>
using namespace std;
using UL = unsigned int;
using ULL = unsigned long long;
using LL = long long;
#define rep(i, n) for(UL i = 0; i < (n); i++)

struct Problem {
public:

	UL G[502][502];
	bool Save[502][502];
	bool S[502][502] = {};

	void DFS(UL x, UL y, UL d = 0) {
		if (G[x][y] <= d && Save[x][y] == S[x][y]) return;
		G[x][y] = d;
		Save[x][y] = S[x][y];
		if (S[x][y]) d++;
		DFS(x - 1, y, d);
		DFS(x + 1, y, d);
		DFS(x, y - 1, d);
		DFS(x, y + 1, d);
	}

	void Solve() {
		UL N; scanf("%d", &N);

		rep(i, N) rep(j, N) S[i + 1][j + 1] = true;
		rep(i, N + 2) rep(j, N + 2) { G[i][j] = 10000; Save[i][j] = S[i][j]; }
		rep(i, N + 2) {
			G[0][i] = G[N + 1][i] = 0;
			G[i][0] = G[i][N + 1] = 0;
		}
		rep(i, N) {
			DFS(1, i + 1);
			DFS(N, i + 1);
			DFS(i + 1, 1);
			DFS(i + 1, N);
		}

		UL ans = 0;

		rep(i, N * N) {
			UL P; scanf("%d", &P);
			UL x = (P - 1) % N + 1;
			UL y = (P - 1) / N + 1;
			UL d = G[x][y];
			ans += G[x][y];
			S[x][y] = false;
			DFS(x, y, d);
		}

		printf("%d", ans);
	}
};

int main() {
	unique_ptr<Problem> p(new Problem());
	p->Solve();
	return 0;
}

