int N; 
vi per;
vi cost;
vector<bool> out;

void update(int curr, int c, bool first=true) {
    if (curr <= 0 || curr > N*N) return; // out of the square
    if (!first && cost[curr] <= c) return; // do not yield improvements

    cost[curr] = c;
    // cout << "update "<<curr<<endl;
    c += (out[curr] == false);
    if (curr%N != 0) update(curr+1 , c, false); // cell to the right
    if (curr%N != 1) update(curr-1, c, false); // cell to the left
    update(curr+N, c, false);
    update(curr-N, c, false);
}

void solve() {
    cin >> N;
    per = vi(N*N+1, 0);
    cost = vi(N*N+1, 0);
    out = vector<bool>(N*N+1, false);
    for (int i=1; i<N*N+1; ++i) {
        int p; cin >> p;
        per[i] = p;
    }

    // assign cost
    for (int i=0; i<N; ++i) {
        for (int j=0; j<N; ++j) {
            cost[i*N+j+1] = min(min(i, N-i-1), min(j, N-j-1));
        }
    }

    ll ans = 0;
    for (auto i : per) {
        if (i == 0) continue;
        out[i] = true;
        ans += cost[i];
        // cout << "person "<<i<<" cost "<<cost[i]<<endl;
        update(i, cost[i]);
    }

    cout << ans << "\n";
}

int main () {
    solve();
    return 0;
}

