  const usize m = n * n;

  std::vector<usize> dist(m, 0);
  for (const usize i : rep(0, m)) {
    const usize x = i % n;
    const usize y = i / n;
    dist[i] = std::min({x, n - x - 1, y, n - y - 1});
  }

