void bfs(ll x, ll y) {
    queue<pair<ll,ll>> q;
    q.push({x,y});
    while(!q.empty()) {
        auto&& xy = q.front(); q.pop();
        ll x = xy.first, y = xy.second;
        if(y > 0 && seats[y - 1][x] > seats[y][x] + humans[y - 1][x]) {
            seats[y - 1][x] = seats[y][x] + humans[y - 1][x];
            q.push({y - 1,x});
        }
        if(y < t - 1&& seats[y + 1][x] > seats[y][x] + humans[y + 1][x]) {
            seats[y + 1][x] = seats[y][x] + humans[y + 1][x];
            q.push({y + 1,x});
        }
        if(x > 0 && seats[y][x - 1] > seats[y][x] + humans[y][x - 1]) {
            seats[y][x - 1] = seats[y][x] + humans[y][x - 1];
            q.push({y,x - 1});
        }
        if(x < t - 1 && seats[y][x + 1] > seats[y][x] + humans[y][x + 1]) {
            seats[y][x + 1] = seats[y][x] + humans[y][x + 1];
            q.push({y,x + 1});
        }
    }
}

