int N;

vi childs(int num){
    int row = num / N;
    int col = num % N;
    vi childs;
    if(row > 0){
        childs.pb((row - 1)* N + col);
    }
    if(row < N - 1){
        childs.pb((row + 1) * N + col);
    }
    if(col > 0){
        childs.pb(row * N + col - 1);
    }
    if(col < N - 1){
        childs.pb(row * N + col + 1);
    }
    return childs;
}

