int CST[MAXN][MAXN][MAXN];
int dirI[4] = {0, 0, 1, -1};
int dirJ[4] = {1, -1, 0, 0};
int n;
int iter = 0;
pair<int, int> getCell(int c) {
    c--;
    return {c / n, c % n};
}
bool outSide(int x, int y) {
    return x < 0 || y < 0 || x >= n || y >= n;
}
int dijkstra(int x, int y) {
    priority_queue<pair<int, pair<int, int>>, vector<pair<int, pair<int, int>>>, greater<pair<int, pair<int, int>>>> Q;
    Q.push({0, {x, y}});
    while (!Q.empty()) {
        pair<int, pair<int, int>> tp = Q.top();
        Q.pop();
        int cc = tp.first;
        int xx = tp.second.first;
        int yy = tp.second.second;
        if (outSide(xx, yy)) {
            return cc;
        }
        if (dp[xx][yy] == 0) return cc;
        CST[iter][xx][yy] = min(CST[iter][xx][yy], cc);
        for (int k = 0; k < 4; k++) {
            int nx = xx + dirI[k];
            int ny = yy + dirJ[k];
            if (outSide(nx, ny)) {
                Q.push({cc, {nx, ny}});
            } else if (CST[iter][nx][ny] > cc + (mat[nx][ny] != 0)) {
                CST[iter][nx][ny] = cc + (mat[nx][ny] != 0);
                Q.push({cc + (mat[nx][ny] != 0), {nx, ny}});
            }
        }
    }
    return 0;
}
void clearIt() {
    for (int i = 0; i < MAXN; i++) {
        for (int j = 0; j < MAXN; j++) {
            dp[i][j] = inf;
            for (int k = 0; k < MAXN; k++) {
                CST[i][j][k] = inf;
            }
        }
    }
}
