        for (int j = 0; j < n; j++) {
            mat[i][j] = ++cnt;
        }
    }
    int res = 0;
    for (int i = 0; i < n * n; i++) {
        cin >> v;
        pair<int, int> pos = getCell(v);
        mat[pos.first][pos.second] = 0;
        int cur = dijkstra(pos.first, pos.second);
        dp[pos.first][pos.second] = cur;
        res += cur;
        iter++;
        if (i % 500 == 0) {
            clearIt();
            iter = 0;
        }
    }
    cout << res << endl;

    return 0;
}

