// 宣言
char maze[503][503]; // 迷路データ
int H; // 高さ
int W; // 幅

int sh, sw; // スタート地点
int gh, gw; // ゴール地点
vector< vector<int> > score(503, vector<int> (503, 100)); // 手数
bool visited[503][503]; // 訪問履歴
const int dh[] = {1, -1, 0, 0};
const int dw[] = {0, 0, 1, -1};

// 幅優先探索
void bfs(int i, int j) {
  // キューを準備
  deque<pair<int,int> > Q;
  // スタート地点のスコアを0にセット
  score[i][j] = 0;
  // スタート地点の座標をキューにプッシュ
  Q.push_back(make_pair(i, j));
  // キューが空になるまで処理を実行
  while(!Q.empty()) {
    // 探索の起点となる座標を記憶してからポップ
    pair<int,int> q = Q.front();
    Q.pop_front();
    int h = q.first;
    int w = q.second;
    // 起点を元に座標を移動
    for (int k = 0; k < 4; k++) {
      int nh = h + dh[k];
      int nw = w + dw[k];
      // 移動先が迷路の範囲外なら処理をスキップ
      if (nh < 0 || nh >= H || nw < 0 || nw >= W) {
        continue;
      }
      // 移動先が壁ならdequeの最後尾にプッシュ
      if (score[nh][nw] > (score[h][w] + 1) && maze[nh][nw] == '#') {
        Q.push_back(make_pair(nh, nw));
        // 移動先のスコアを起点のスコア+1にする
        score[nh][nw] = score[h][w] + 1;
      }
      // そうでなければdequeの先頭にプッシュ
      if (score [nh][nw] > score[h][w] && maze[nh][nw] != '#'){
        Q.push_front(make_pair(nh, nw));
        // 移動先のスコアを起点のスコアと同じにする
        score[nh][nw] = score[h][w];
      }
    }
  }
}

int main() {
  // 入力
  ll nn;
  cin >> nn;
  H=nn+2;
  W=nn+2;
  ll qq;
  // 迷路データ
  ll ans=0,tmp;
  for (ll i = 0; i < H; i++) {
    for (ll j = 0; j < W; j++) {
      if(j==0||j==nn+1||i==0||i==nn+1){
        maze[i][j]='.';
      }
      else maze[i][j]='#';
    }
  }
  for (ll ii = 0; ii < nn*nn; ii++) {
    cin >> qq;
    sh=(qq-1)/nn+1;
    sw=(qq-1)%nn+1;
    maze[sh][sw]='.';
    tmp=999999999;
    for(ll jj=0;jj<=nn+1;jj++){
	  for(ll kk=0;kk<=nn+1;kk++){
        score[jj][kk]=99999999;
      }
    }
    bfs(sh,sw);
    for(ll jj=0;jj<=nn+1;jj++){
	  for(ll kk=0;kk<=nn+1;kk++){
		if(jj==0||jj==nn+1||kk==0||kk==nn+1){
          if(tmp>score[jj][kk])tmp=score[jj][kk];
        }
      }
    }
    ans+=tmp;
  }
  cout << ans << endl;
  return 0;
}

