void dfs(int i, int j, int dst) {
    if (dst >= d[i][j]) return;
    d[i][j] = dst;
    if (i > 0) dfs(i-1, j, dst + (1 - a[i-1][j]));
    if (i < N-1) dfs(i+1, j, dst + (1 - a[i+1][j]));
    if (j > 0) dfs(i, j-1, dst + (1 - a[i][j-1]));
    if (j < N-1) dfs(i, j+1, dst + (1 - a[i][j+1]));   
}

