struct union_find {
    ll par[MAX_N];
    ll Size[MAX_N];
    union_find(ll n) {
        for(int i = 0; i < n; i++) {
            par[i] = i;
            Size[i] = 1;
        }
    }
    ll root(ll x) {
        if(par[x] == x)
            return x;
        return par[x] = root(par[x]);
    }
    bool same(ll x, ll y) { return root(x) == root(y); }
    void unite(ll x, ll y) {
        if(same(x, y))
            return;
        Size[root(x)] += Size[root(y)];
        par[root(y)] = root(x);
    }
};
void solve() {
    union_find uni(n * n);
    rep(i, n) {
        rep(j, n) { VS[i * j + n].insert(i * j + n); }
    }
    rep(i, n) {
        rep(j, n - 1) {
            g[i * n + j].pb(i * n + j + 1);
            g[i * n + j + 1].pb(i * n + j);
            g[(j + 1) * n + i].pb(j * n + i);
            g[j * n + i].pb((j + 1) * n + i);
        }
