            // cout << "safs" << endl;
            if(uni.Size[x] > uni.Size[x - n]) {
                VS[uni.root(x)].erase(x - n);
                VS[uni.root(x - n)].erase(x);
                uni.unite(x, x - n);
                for(auto ite = VS[uni.root(x - n)].begin(); ite != VS[uni.root(x - n)].end(); ite++) {
                    VS[uni.root(x)].insert(*ite);
                }
            } else {
                VS[uni.root(x)].erase(x - n);
                VS[uni.root(x - n)].erase(x);
                uni.unite(x - n, x);
                for(auto ite = VS[uni.root(x)].begin(); ite != VS[uni.root(x)].end(); ite++) {
                    VS[uni.root(x - n)].insert(*ite);
                }
            }
            D[uni.root(x)] = min({D[x], D[x - n], D[uni.root(x)], D[uni.root(x - n)]});
        }

        if(a < n - 1 && used[x + n] && uni.root(x) != uni.root(x + n)) {
