void dfs(int a, int b, int o)
{
	if (a<1 || b<1 || a>n || b>n)
		return;
	o-=out[a][b];
	if (odl[a][b]<=o)
		return;
	odl[a][b]=o;
	dfs(a+1, b, o+1);
	dfs(a-1, b, o+1);
	dfs(a, b+1, o+1);
	dfs(a, b-1, o+1);
}

