#define FOR(i, a, b) for(i = (a); i < (b); ++i)
#define RFOR(i, a, b) for(i = (a) - 1; i >= (b); --i)
#define EACH(it, a) for(auto it = (a).begin(); it != (a).end(); ++it)
#define CLEAR(a, b) memset(a, b, sizeof(a))
#define SIZE(a) int((a).size())
#define ALL(a) (a).begin(),(a).end()
#define MP make_pair

const int DR[] = {-1, 1, 0, 0};
const int DC[] = {0, 0, -1, 1};

void solve(int test)
{
    int N;
    cin >> N;
    int i, j;
    VInt p(N*N);
    FOR(i, 0, SIZE(p)) cin >> p[i];

    vector<VInt> v(N, VInt(N, 1));
    vector<VInt> d(N, VInt(N));
    FOR(i, 0, N)
        FOR(j, 0, N)
            d[i][j] = min(min(i, N - 1 - i), min(j, N - 1 - j));

    Int res = 0;
    FOR(i, 0, SIZE(p))
    {
        int r = (p[i]-1) / N;
        int c = (p[i]-1) % N;
        res += d[r][c];
        v[r][c] = 0;
        queue<PII> q;
        q.push(PII(r, c));
        while(!q.empty())
        {
            r = q.front().first;
            c = q.front().second;
            q.pop();
            FOR(j, 0, 4)
            {
                int rr = r + DR[j];
                int cc = c + DC[j];
                if(rr < 0 || N <= rr || cc < 0 || N <= cc) continue;
                if(d[rr][cc] > d[r][c] + v[r][c])
                {
                    d[rr][cc] = d[r][c] + v[r][c];
                    q.push(PII(rr, cc));
                }
            }
        }
    }
    cout << res << endl;
}

