    for(int i = 0; i <= n+1; i++){
        for(int j = 0; j <= n+1; j++){
            mp[i][j]=1;
        }
    }
    for(int i = 0; i <= n+1; i++){
        mp[i][0] = 0;
        mp[i][n+1] = 0;
        mp[0][i] = 0;
        mp[n+1][i] = 0;
    }
    ll ans = 0;
    for(int i = 0; i < n*n; i++){
        priority_queue<pair<int,pair<int,int> >,vector<pair<int,pair<int,int> > >, greater<pair<int,pair<int,int> > > > pq;
