        int y = p[i]/n;
        if(x == 0){
            y--;
            x = n;
        }
        y++;
        auto st = make_pair(x,y);
        pq.push(make_pair(0,st));

        map<pair<int,int>,int > ev;
        ll t_ans = 0;
        int dirx[] = {1,0,-1,0};
        int diry[] = {0,1,0,-1};
        while(pq.size() > 0){
            auto tmp = pq.top();
            pq.pop();
            auto w = tmp.first;
