                if(mp[pt.second+diry[j]][pt.first+dirx[j]] == 1){
                    pq.push(make_pair(w+1,next));
                } else {
                    pq.push(make_pair(w,next));
                }
            }
        }

        mp[y][x] = 0;
        ans += t_ans;
    }

    cout << ans << endl;
    return 0;
