void solve(int T)
{
	int n;
	cin>>n;
	VI axd(n*n);
	for(auto &&u : axd)
	{
		cin>>u;
		u--;
	}
	vector<VI> dist(n, VI(n, n*n));
	vector<vector<bool> > vis(n, vector<bool>(n, 0));
	vector<VI> pe(n, VI(n, 1));
	for(int i=0;i<n;i++)
	{
		for(int j=0;j<n;j++)
		dist[i][j] = min({i, j, n-1-i, n-1-j});	
	}
	auto bfs_visit = [&](int x, int y){
		queue<PII> Q;
		pe[x][y] = 0;
		Q.emp(x, y);
		while(!Q.empty())
		{
			PII px = Q.front();
			Q.pop();
			vis[px.ff][px.ss] = 0;
			int df = dist[px.ff][px.ss] + pe[px.ff][px.ss];
			for(int i=0;i<4;i++)
			{
				int cx = px.ff + NE[i].ff;
				int cy = px.ss + NE[i].ss;
				if((cx >= 0) && (cx < n) && (cy >= 0) && (cy < n) && (df < dist[cx][cy]))
				{
					dist[cx][cy] = df;
					if(!vis[cx][cy])
					{
						vis[cx][cy] = 1;
						Q.emp(cx, cy);
					}
				}	
			}	
		}
	};
	int fd = 0;
	for(auto &&u : axd)
	{
		int r = u/n, c = u%n;
		fd += dist[r][c];
		bfs_visit(r, c);
	}
	cout<<fd<<"\n";
	return;	
}

