            REP(k, 4){
                int ni = ci + di[k], nj = cj + dj[k];
                if(valid(ni, nj) and cost<dist[ni][nj]){
                    dist[ni][nj] = cost;
                    que.emplace(ni, nj);
                }
            }
        }
    }

    void solve(std::istream& in, std::ostream& out){
        ios_base::sync_with_stdio(false);
        in.tie(nullptr), out.tie(nullptr);
        in>>N;
        vc<int> P(N*N);
        for(auto& p : P) in>>p, p--;
        dist.resize(N, vc<int>(N, INF));
        flag.resize(N, vc<bool>(N, true));
        REP(i, N) REP(j, N){
            dist[i][j] = min(min(i, N-i-1), min(j, N-j-1));
        }
        int ans = 0;
        for(auto& p : P){
            int row = p / N, col = p % N;
            ans += dist[row][col];
            flag[row][col] = false;
            bfs(row, col);
        }
        out<<ans<<'\n';
    }
};


int main() {
	BJoker solver;
	std::istream& in(std::cin);
	std::ostream& out(std::cout);
	solver.solve(in, out);
	return 0;
}

