void update_map(int row, int col, vector<vector<int>>& vv, vector<vector<int>>& m, int val) {
    int n = m.size();
    if (row < 0 || col < 0 || row >= n || col >= n) return;
    if (m[row][col] <= val) return;
    m[row][col] = val;
    update_map(row + 1, col, vv, m, m[row][col] + vv[row][col]);
    update_map(row - 1, col, vv, m, m[row][col] + vv[row][col]);
    update_map(row, col - 1, vv, m, m[row][col] + vv[row][col]);
    update_map(row, col + 1, vv, m, m[row][col] + vv[row][col]);
}

int main() {
