    }
    vector<vector<int>> vv(n, vector<int>(n, 1));
    vector<vector<int>> m(n, vector<int>(n, n * n));
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            m[i][j] = min(min(i, j), min(n - 1 - i, n - 1 - j));
        }
    }
    int res = 0;
    for (int i = 0; i < n * n; i++) {
        int row = (v[i] - 1) / n, col = (v[i] - 1) % n;
        res += m[row][col];
        if (row != 0) m[row][col] = min(m[row][col], m[row - 1][col] + vv[row - 1][col]);
        if (row != n - 1) m[row][col] = min(m[row][col], m[row + 1][col] + vv[row + 1][col]);
        if (col != 0) m[row][col] = min(m[row][col], m[row][col - 1] + vv[row][col - 1]);
        if (col != n - 1) m[row][col] = min(m[row][col], m[row][col + 1] + vv[row][col + 1]);
        vv[row][col] = 0;
        update_map(row - 1, col, vv, m, m[row][col]);
        update_map(row + 1, col, vv, m, m[row][col]);
        update_map(row, col - 1, vv, m, m[row][col]);
        update_map(row, col + 1, vv, m, m[row][col]);
    }
    cout << res << endl;
}

