void dfs(int x, int y){
    int tr = use[x][y] + res[x][y];
    ff(i,0,3){
        int px = dx[i] + x;
        int py = dy[i] + y;
        if(px >= 0 && px <= n-1 && py >= 0 && py <= n-1){
            if(res[px][py] > tr){
                res[px][py] = tr;
                dfs(px, py);
            }
        }
    }
}


