ll up(ll i){
    if(i<=n) return 0;
    else return i-n;
}

ll down(ll i){
    if(i>n*n-n) return 0;
    else return i+n;
}

ll left(ll i){
    if(i%n==1) return 0;
    else return i-1;
}

ll right(ll i){
    if(i%n==0) return 0;
    else return i+1;
}

void make(ll u){
    r[u]=1;
    if(right(u)){
        ll v=right(u);
        if(r[v]){
            a[u].pb(v);
            a[v].pb(u);
        }     
    }
    if(left(u)){
        ll v=left(u);
        if(r[v]){
            a[u].pb(v);
            a[v].pb(u);
        }     
    }
    if(up(u)){
        ll v=up(u);
        if(r[v]){
            a[u].pb(v);
            a[v].pb(u);
        }     
    }
    if(down(u)){
        ll v=down(u);
        if(r[v]){
            a[u].pb(v);
            a[v].pb(u);
        }     
    }
}

void closer(int n){
    for(ll i=1;i<=n*n;i++){
        ll u=i,c1=0,ans=INF;
        u=i;
        while(u){
            u=right(u);
            c1++;
        }
        ans=min(c1,ans);
        u=i;
        c1=0;
        while(u){
            u=left(u);
            c1++;
        }
        ans=min(c1,ans);
        u=i;
        c1=0;
        while(u){
            u=up(u);
            c1++;
        }
        ans=min(c1,ans);
        u=i;
        c1=0;
        while(u){
            u=down(u);
            c1++;
        }
        ans=min(c1,ans);
        close[i]=ans-1;
    }
}

