void Free(int x, int y){
    D[x][y]--;
    U[x][y]=0;
    res += D[x][y];
    int tail=0, tt=0, i, j;
    Q[++tail]={x,y};
    while(tail){
        tt = 0;
        for(i=1;i<=tail;i++){
            point t = Q[i];
            for(j=0;j<4;j++){
                int tx = t.x+dx[j], ty = t.y+dy[j];
                if(!U[tx][ty] && D[tx][ty] > D[t.x][t.y]){
                    Q[++tail]={tx,ty};
                    D[tx][ty]=D[t.x][t.y];
                }
            }
        }
        for(i=1;i<=tail;i++){
            point t = Q[i];
            for(j=0;j<4;j++){
                int tx = t.x+dx[j], ty = t.y+dy[j];
                if(U[tx][ty] && D[tx][ty] > D[t.x][t.y] + 1){
                    T[++tt]={tx,ty};
                    D[tx][ty]=D[t.x][t.y] + 1;
                }
            }
        }
        for(i=1;i<=tt;i++)Q[i]=T[i];
        tail=tt;
    }
}
