    start = std::chrono::system_clock::now(); // 計測開始時間

    vector<vector<pair<int, int>>> distance(N, vector<pair<int, int>>(N));
    vector<vector<bool>> exist(N, vector<bool>(N, true));
    rep(i,0,N) rep(j,0,N) {
        vector<pair<ll,int>> el = {{i,-1}, {j,-1}, {N-i-1,-1}, {N-j-1,-1}};
        distance[i][j] = *min_element(all(el));
    }
    ll answer = 0;
    const vector<int> dx = {1, 0, 0, -1}, dy = {0, 1, -1, 0};
    rep(i,0,N*N) {
        int x = P[i] % N;
        int y = (P[i] - x) / N;
        answer += distance[y][x].first;
        exist[y][x] = false;
        queue<pair<int, int>> que;
        que.push({x, y});
        while (!que.empty()) {
            auto current = que.front();
            que.pop();
            rep(j,0,4) {
                pair<int, int> next = {current.first + dx[j], current.second + dy[j]};
                if (next.first < 0 || next.first >= N || next.second < 0 || next.second >= N) continue;
                if (distance[next.second][next.first].second == i) continue;
                int update = distance[current.second][current.first].first + (exist[current.second][current.first] ? 1 : 0);
                if (distance[next.second][next.first].first > update) {
                    distance[next.second][next.first] = {update, i};
                    que.push(next);
                }
            }
        }
    }
    cout << answer << endl;
    end = std::chrono::system_clock::now();  // 計測終了時間
    double elapsed = std::chrono::duration_cast<std::chrono::milliseconds>(end-start).count();
    debug(elapsed);
    return 0;
}

