vector<vector<int>> dist;

int calc(pii pp) {
	int L = leave[pp.x][pp.y];
	dist.assign(n, vector<int>(n, 1e9));
	dist[pp.x][pp.y] = 0;
	deque<pii> deq{pp};
	while (!deq.empty()) {
		pii pp = deq[0];
		deq.pop_front();
		for (pii sh : {mp(-1, 0), mp(0, -1), mp(1, 0), mp(0, 1)}) {
			pii sub = mp(pp.x + sh.x, pp.y + sh.y);
			if (0 <= sub.x && sub.x < n && 0 <= sub.y && sub.y < n) {
				int w = dist[pp.x][pp.y] + (leave[sub.x][sub.y] > L);
				if (dist[sub.x][sub.y] > w) {
					dist[sub.x][sub.y] = w;
					deq.pb(sub);
				}
			}
		}
	}
	int rez = 1e9;
	for (int i = 0; i < n; i++) {
		rez = min({rez, dist[i][0], dist[0][i], dist[n - 1][i], dist[i][n - 1]});
	}
	return rez;
}

void solve(int l, int r, int dl, int dr) {
	if (l > r) return;
	if (dl == dr) {
		for (int i = l; i <= r; i++) {
			rez[i] = dl;
		}
		return;
	}
	int m = (l + r) / 2;
	rez[m] = calc(mp(p[m] / n, p[m] % n));
	solve(l, m - 1, rez[m], dr);
	solve(m + 1, r, dl, rez[m]);
}

