using namespace std;
using UL = unsigned int;
using ULL = unsigned long long;
using LL = long long;
#define rep(i, n) for(UL i = 0; i < (n); i++)

struct Problem {
public:

	UL G[502][502];
	bool Save[502][502];
	bool S[502][502] = {};

	void BFS(UL x, UL y, UL d = 0) {
		queue<pair<pair<UL, UL>, UL>> Q;
		Q.push({ {x, y}, d });
		while (Q.size()) {
			UL x = Q.front().first.first;
			UL y = Q.front().first.second;
			UL d = Q.front().second;
			Q.pop();
			if (G[x][y] <= d && Save[x][y] == S[x][y]) continue;
			G[x][y] = d;
			Save[x][y] = S[x][y];
			if (S[x][y]) d++;
			Q.push({ {x-1, y}, d });
			Q.push({ {x+1, y}, d });
			Q.push({ {x, y-1}, d });
			Q.push({ {x, y+1}, d });
		}
	}

	void Solve() {
		UL N; scanf("%d", &N);

		rep(i, N) rep(j, N) S[i + 1][j + 1] = true;
		rep(i, N + 2) rep(j, N + 2) { G[i][j] = 10000; Save[i][j] = S[i][j]; }
		rep(i, N + 2) {
			G[0][i] = G[N + 1][i] = 0;
			G[i][0] = G[i][N + 1] = 0;
		}
		rep(x, N) rep(y, N) {
			UL tmp = 10000;
			tmp = min(tmp, x);
			tmp = min(tmp, y);
			tmp = min(tmp, N - 1 - x);
			tmp = min(tmp, N - 1 - y);
			G[x + 1][y + 1] = tmp;
		}

		UL ans = 0;

		rep(i, N * N) {
			UL P; scanf("%d", &P);
			UL x = (P - 1) % N + 1;
			UL y = (P - 1) / N + 1;
			UL d = G[x][y];
			ans += G[x][y];
			S[x][y] = false;
			BFS(x, y, d);
		}

		printf("%d", ans);
	}
};

int main() {
	unique_ptr<Problem> p(new Problem());
	p->Solve();
	return 0;
}

