int n, n2, p[250014], b[514][514], edg[514][514], d[510014], bd[510014];
map<int, pii> rmap;

int getv (int i, int j)
{
  return i * n2 + j;
}

int getoutv (int i, int j)
{
  return getv(i, j) + n2 * n2;
}

void solve ()
{
  R(n);
  FOR(k, 0, n * n) R(p[k]);
  n2 = n + 2;
  SSSP<int> g(2 * n2 * n2, INF);
  FOR(i, 0, n2) FOR(j, 0, n2)
  {
    int inv = getv(i, j);
    int outv = getoutv(i, j);
    edg[i][j] = g.add_edge(inv, outv, 1);
    if (i > 0 && i <= n && j > 0 && j <= n)
    {
      FOR(di, -1, 2) FOR(dj, -1, 2) if (di * di + dj * dj == 1)
      {
        int targetv = getv(i + di, j + dj);
        g.add_edge(outv, targetv, 0);
      }
    }
  }
  int ci, cj;
  ci = cj = 1;
  FOR(i, 1, n * n + 1)
  {
    rmap[i] = MP(ci, cj);
    ++cj;
    if (cj > n)
    {
      cj = 1;
      ++ci;
    }
  }
  FOR(i, 0, 510014) bd[i] = INF;
  int res = 0;
  FOR(k, 0, n * n)
  {
    pii en = rmap[p[k]];
    int pi = en.first;
    int pj = en.second;
    g.edges[edg[pi][pj]].weight = 0;
    if (pi == 1 || pi == n || pj == 1 || pj == n) 
    {
      bd[getv(pi, pj)] = 0;
      continue;
    }
    bool go = true;
    FOR(di, -1, 2) FOR(dj, -1, 2) if (di * di + dj * dj == 1)
    {
      int ni = pi + di;
      int nj = pj + dj;
      if (!bd[getv(ni, nj)])
      {
        bd[getv(pi, pj)] = 0;
        go = false;
      }
    }
    if (!go) continue;
    g.dijkstra(getv(pi, pj), d);
    FOR(i, 0, n2) bd[getv(pi, pj)] = min({bd[getv(pi, pj)], d[getv(0, i)], d[getv(i,0)], d[getv(n + 1, i)], d[getv(i, n + 1)]});
    res += bd[getv(pi, pj)];
  }
  printf("%d\n", res);
}

