int n, p[N*N], a[N][N], d[N][N], inq[N][N], ans;
queue<pii> q;

bool inside( int x, int y ) {
	return x >= 1 && x <= n && y >= 1 && y <= n;
}

void update( int sx, int sy ) {
	q.push( pii(sx, sy) );
	inq[sx][sy] = 1;
	while( !q.empty() ) {
		pii tmp = q.front(); q.pop();
		int x = tmp.first, y = tmp.second;
		inq[x][y] = 0;
		for( int dir = 0; dir < 4; ++dir ) {
			int nx = x + dx[dir];
			int ny = y + dy[dir];
			if( inside(nx, ny) && d[x][y] + a[nx][ny] < d[nx][ny] ) {
				d[nx][ny] = d[x][y] + a[nx][ny];
				if( !inq[nx][ny] ) {
					inq[nx][ny] = 1;
					q.push( pii(nx, ny) );
				}
			}
		}
	}
}

int calc_init( int x, int y ) {
	return min(min(abs(x-1), abs(x-n)), min(abs(y-1), abs(y-n))) + 1;
}

void init() {
	for( int i = 1; i <= n; ++i )
		for( int j = 1; j <= n; ++j ) {
			a[i][j] = 1;
			d[i][j] = calc_init(i, j);
		}
	ans = 0;
	for( int i = 1; i <= n*n; ++i ) {
		int now = p[i];
		int x = (now-1)/n+1;
		int y = (now-1)%n+1;
		ans += d[x][y] - 1;
		--d[x][y];
		a[x][y] = 0;
		update(x, y);
	}
	cout << ans << endl;
}

void solve() {
	init();
}

