        b[x] = true;
    }

    int root(int x) { // データxが属する木の根を再帰で得る：root(x) = {xの木の根}
        if(par[x] == x) return x;
        return par[x] = root(par[x]);
    }

    bool rootb(int x) { // xの人が嫌われるか否か = 根が四隅か
        int rx = root(x);
        if(rx == 1 || rx == N || rx == N*N || rx == N*N-N+1) return true;
        return false;
    }

    //退室する人がxと仮定
    void unite(int x, int y, bool o) {
        int rx = root(x); //xの根rx
        int ry = root(y); //yの根ry
        if(rx == ry) return; //xとyの根が同じ(=同じ木にある)時はそのまま
        if(o){
            //嫌われない場合

            //yが退出済みならばxの根にuniteする
            //そうでない場合は対象yの値を無理矢理xの根に挿げ替える
            if(b[y]){
                par[ry] = rx;
            }else{
                par[y] = rx;
            }
        }else{
            //嫌われる場合

            //yの根がrootbでtrueを返す場合なにもしない
            //そうでない場合は統合
            if(!rootb(y)){
                par[ry] = rx;
            }
        }
    }

    bool same(int x, int y) { // 2つのデータx, yが属する木が同じならtrueを返す
        int rx = root(x);
        int ry = root(y);
        return rx == ry;
    }

    void display(){
        for(int i=0;i<=N*N;i++) {
            std::cout << root(i) << " ";
        }
        std::cout << std::endl;
    }
};

int main(void){
    int N;
    int cnt=0;
    std::cin >> N;
    UnionFind uf(N);

    for(int i=0;i<N*N;i++){
        int P;
        std::cin >> P;

        bool isDisliked = uf.rootb(P);
        //上
        if((P-1)/N != 0) uf.unite(P, P-N, isDisliked);
        //左
        if((P-1)%N != 0) uf.unite(P, P-1, isDisliked);
        //右
        if(P%N != 0) uf.unite(P, P+1, isDisliked);
        //下
        if(P+N <= N*N) uf.unite(P, P+N, isDisliked);

        if(!isDisliked) cnt++;

        uf.deleted(P);

        //uf.display();
    }

    std::cout << cnt << std::endl;

    return 0;
}

