void hora(int tc) {
	int n;
	cin>>n;
	int ctr = 0;
	for(int i = 1;i <= n;i++) {
		for(int j = 1;j <= n;j++) {
			arr[i][j] = ++ctr;
			sz[0][i + j]++;
			sz[1][i - j + n]++;
			idx[arr[i][j]] = {sz[0][i + j], sz[1][i - j + n]};
			not_empty[i][j] = 1;
			pos[ctr] = {i, j};
			cin>>seq[ctr];
		}
	}

	//build
	for(int i = 0;i <= 2 * n;i++) {
		sz[0][i]++, sz[1][i]++;
		for(int j = 0;j <= sz[0][i];j++) {
			int val = 1000;
			if(j == 0 || j == sz[0][i]) val = 0;
			update(0, i, 1, 0, sz[0][i], j, val);
		}

		for(int j = 0;j <= sz[1][i];j++) {
			int val = 1000;
			if(j == 0 || j == sz[1][i]) val = 0;
			update(1, i, 1, 0, sz[1][i], j, val);
		}
	}

	int tot = 0;
	for(int i = 1;i <= ctr;i++) {
		int val = seq[i];
		int y = pos[val].F;
		int x = pos[val].S;
		int iter = min(min(y, n - y + 1), min(x, n - x + 1));
		int res = iter;
//		cout<<"ITER "<<iter<<endl;
		for(int j = 1;j <= iter;j++) {
			int uy = y - j;
			int by = y + j;
			int lx = x - j;
			int rx = x + j;

			int l = 0, r = sz[0][lx + y];
			if(uy != 0) l = idx[val - j * n].F;
			if(lx != 0) r = idx[val - j].F;
			res = min(res, query(0, lx + y, 1, 0, sz[0][lx + y], l, r) + j - 1);

			l = 0, r = sz[0][rx + y];
			if(rx != n + 1) l = idx[val + j].F;
			if(by != n + 1) r = idx[val + j * n].F;
			res = min(res, query(0, rx + y, 1, 0, sz[0][rx + y], l, r) + j - 1);

			l = 0, r = sz[1][y - lx + n];
			if(lx != 0) l = idx[val - j].S;
			if(by != n + 1) r = idx[val + j * n].S;
			res = min(res, query(1, y - lx + n, 1, 0, sz[1][y - lx + n], l, r) + j - 1);

			l = 0, r = sz[1][uy - x + n];
			if(uy != 0) l = idx[val - j * n].S;
			if(rx != n + 1) r = idx[val + j].S;
			res = min(res, query(1, uy - x + n, 1, 0, sz[1][uy - x + n], l, r) + j - 1);
		}
//		cout<<"ITER "<<i<<" VAL "<<val<<" "<<y<<" "<<x<<" "<<res<<endl;
		tot += res;

	update(0, y + x, 1, 0, sz[0][y + x], idx[arr[y][x]].F, res);
	update(1, y - x + n, 1, 0, sz[1][y - x + n], idx[arr[y][x]].S, res);
		sudah[y][x] = 1;
		bool bisa = false;
		for(int j = 0;j < 4;j++) {
			int ny = y + py[j];
			int nx = x + px[j];
			if(not_empty[ny][nx] == 0) bisa = true;
		}

		if(bisa) dfs(y, x, n);
	}
	cout<<tot<<endl;
}

