int n,ans;
int p[MAXN];
int dis[505][505];
queue<pii> q;
void pre(int i,int j)
{
    if(!dis[i][j])return;
    dis[i][j]=0;
    q.push({i,j});
}

int d[4][2]={{0,1},{0,-1},{1,0},{-1,0}};
bool chk(int i,int j)
{
    if(i<1||j<1||i>n||j>n)return false;
    return true;
}

bool vis[505][505];

void deal(int x,int y)
{
    ans+=dis[x][y];
    q.push({x,y});
    vis[x][y]=0;
    while(!q.empty())
    {
        int x,y;
        tie(x,y)=q.front();q.pop();
        for(int i=0;i<4;i++)
        {
            int dx=x+d[i][0],dy=y+d[i][1];
            if(!chk(dx,dy))continue;
            if(dis[dx][dy]>dis[x][y]+vis[x][y])dis[dx][dy]=dis[x][y]+vis[x][y],q.push({dx,dy});
        }
    }
}

void solve()
{
    memset(vis,1,sizeof(vis));
    memset(dis,0x3f,sizeof(dis));
    ans=0;
    R(n);
    for(int i=1;i<=n*n;i++)R(p[i]);
    for(int i=1;i<=n;i++)pre(1,i),pre(n,i),pre(i,1),pre(i,n);
    while(!q.empty())
    {
        int x,y;
        tie(x,y)=q.front();q.pop();
        for(int i=0;i<4;i++)
        {
            int dx=x+d[i][0],dy=y+d[i][1];
            if(!chk(dx,dy))continue;
            if(dis[dx][dy]>dis[x][y]+1)dis[dx][dy]=dis[x][y]+1,q.push({dx,dy});
        }
    }
    for(int i=1;i<=n*n;i++)
    {
        deal((p[i]-1)/n+1,(p[i]-1)%n+1);
    }
    W(ans);
}

