        int hor,ver;
        queue<pair<pair<int,int>,ll>> que;
        ver = (p[i]-1)/n+1;
        hor = p[i]%n;
        if(hor == 0) hor = n;
        que.push({{ver,hor},0});
        bool finish = false;
        int seen[n+1][n+1] = {0};
        ll min_num = INF;
        while(!que.empty()){
            pair<pair<int,int>,ll> np = que.front();
            que.pop();
            int h = np.first.second;
            int v = np.first.first;
            ll num = np.second;
            seen[v][h] = 1;
            if( h == 1 || v == 1 || h == n || v == n){
                finish = true;
                min_num = MIN(min_num,num);
                continue;
            }
            if(seen[v+1][h] == 0){
                if(moov[v+1][h] == 0){
                    que.push({{v+1,h},{num+1}});
                }else{
                    que.push({{v+1,h},{num}});
