                if(moov[v-1][h] == 0){
                    que.push({{v-1,h},{num+1}});
                }else{
                    que.push({{v-1,h},{num}});
                }
            }
        }
        moov[ver][hor] = 1;
        hate += min_num;
    }
    cout << hate << endl;

    return 0;
}

