using namespace std;
using ll = long long;
using ld = long double;
using P = pair<int, int>;

/* BIT: 区間和の更新や計算を行う構造体
    初期値は a_1 = a_2 = ... = a_n = 0
    ・add(i,x): a_i += x とする
    ・sum(i): a_1 + a_2 + ... + a_i を計算する
    計算量は全て O(logn)
*/
template <typename T>
struct BIT {
    int n;          // 配列の要素数(数列の要素数+1)
    vector<T> bit;  // データの格納先
    BIT(int n_) : n(n_ + 1), bit(n, 0) {}
    void add(int i, T x) {
        for (int idx = i; idx < n; idx += (idx & -idx)) {
            bit[idx] += x;
        }
    }
    T sum(int i) {
        T s(0);
        for (int idx = i; idx > 0; idx -= (idx & -idx)) {
            s += bit[idx];
        }
        return s;
    }
};

int main() {
    int n;
    cin >> n;
    vector<int> p(n*n);
    rep(i, n*n)cin >> p[i];
    vector<BIT<int>> col;
    vector<BIT<int>> row;
    BIT<int> b(n);

    rep(i, n){
        col.push_back(b);
        rep(j, n)col[i].add(j+1, 1);
        row.push_back(b);
        rep(j, n)row[i].add(j+1, 1);
    }

    ll ans = 0;
    rep(i, n*n){
        int x = (p[i]-1) % n;
        int y = (p[i]-1) / n;
        int l, r, u, d;
        if(x == 0)l = 0;
        else l = row[y].sum(x);
        if(x == n-1)r = 0;
        else r = row[y].sum(n) - l - 1;
        if(y == 0)u = 0;
        else u = col[x].sum(y);
        if(y == n-1)d = 0;
        else d = col[x].sum(n) - u - 1;
        ans += min({l, r, u, d});
        row[y].add(x+1, -1);
        col[x].add(y+1, -1);
    }
    cout << ans << endl;
}

#include <bits/stdc++.h>

using ll = long long int;
using P = std::pair<int, int>;

#define rep(i, n) for (int i = 0; i < n; ++i)

int n;

P conv(int m)
{

    return P((m + n - 1) / n, ((m % n == 0) ? n : m % n));
}

int dis(P p)
{
    return std::min({p.first - 1, p.second - 1, n - p.first, n - p.second});
}

int dx[] = {0, 1, 0, -1}, dy[] = {1, 0, -1, 0};

std::vector<std::vector<P>> pars;
std::vector<std::vector<int>> mindis;

P root(P p)
{

    return (pars[p.first][p.second] == p) ? p : root(pars[p.first][p.second]);
}

void unite(P p1, P p2)
{

    p1 = root(p1);
    p2 = root(p2);

    if (mindis[p1.first][p1.second] < mindis[p2.first][p2.second])
        pars[p2.first][p2.second] = p1;
    else
    {
        pars[p1.first][p1.second] = p2;
    }
}

int main()
{
    std::cin >> n;

    std::vector<P> a(n * n);

    rep(i, n * n)
    {
        int m;
        std::cin >> m;
        a[i] = conv(m);
    }

    pars.resize(n + 1, std::vector<P>(n + 1));
    mindis.resize(n + 1, std::vector<int>(n + 1));

    std::vector<std::vector<bool>> used(n + 1, std::vector<bool>(n + 1));

    rep(i, n)
    {
        rep(j, n)
        {
            pars[i + 1][j + 1] = P(i + 1, j + 1);
            mindis[i + 1][j + 1] = dis(P(i + 1, j + 1));
        }
    }

    int ans = 0;

    rep(i, n * n)
    {
        int x, y;
        std::tie(x, y) = a[i];

        rep(j, 4)
        {
            int nx = x + dx[j], ny = y + dy[j];
            if (nx <= 0 || nx > n || ny < 0 || ny > n || !used[nx][ny])
                continue;
            unite(P(nx, ny), P(x, y));
        }

        P r = root(P(x, y));

        ans += mindis[r.first][r.second];

        used[x][y] = 1;
    }

    std::cout << ans << std::endl;

    return 0;
}

