void rollback(int x,int y)
{
	++tim;
	a[x][y]=0;li.push_front(mp(x,y));
	while(!li.empty())
	{
		pii T=li.front();li.pop_front();
		int u=T.first,v=T.second;
		if(vis[u][v]==tim)continue;vis[u][v]=tim;
		for(int k=0;k<4;k++)if(in(u+dx[k],v+dy[k]))
		{
			int p=u+dx[k],q=v+dy[k];
			if(f[p][q]>f[u][v]+a[u][v])
			{
				f[p][q]=f[u][v]+a[u][v];
				if(!a[u][v])li.push_front(mp(p,q));
				else li.push_back(mp(p,q));
			}
		}
	}
}
