const int mod_int = 1000000007;

int N;
LL P[250000];

LL ans = 0;

void solve(){
	//番号iの観客の位置をpos_h[i],pos_w[i]で表す
	vector<LL> pos_h(N*N+1);
	vector<LL> pos_w(N*N+1);
	//位置(h,w)に座っている人が退席するコストをcost[h][w]とおく
	vector<vector<LL>> cost(N,vector<LL>(N));
	for(int h=0;h<N;h++){
		for(int w=0;w<N;w++){
			cost[h][w] = min(min(h,N-h-1),min(w,N-w-1));
			pos_h[N*h+w+1] = h;
			pos_w[N*h+w+1] = w;
		}
	}

	vector<vector<LL>> seat(N,vector<LL>(N,1));

	for(int i=0;i<N*N;i++){
		LL leaving_h = pos_h[P[i]];
		LL leaving_w = pos_w[P[i]];

		queue<pair<LL,LL>> q;
		q.push(pair<LL,LL>(leaving_h,leaving_w));

		auto spread = [&](LL h,LL w){
			int dh[4] = {-1,1,0,0};
			int dw[4] = {0,0,-1,1};
			for(int j=0;j<4;j++){
				if(h+dh[j]>=0 && h+dh[j]<=N-1 && w+dw[j]>=0 && w+dw[j]<=N-1){
					if(seat[h][w]==0){
						if(cost[h+dh[j]][w+dw[j]]>cost[h][w]){
							cost[h+dh[j]][w+dw[j]] = cost[h][w];
							q.push(pair<LL,LL>(h+dh[j],w+dw[j]));
						}
					}
					if(seat[h][w]==1){
						if(cost[h+dh[j]][w+dw[j]]>cost[h][w]+1){
							cost[h+dh[j]][w+dw[j]] = cost[h][w]+1;
							q.push(pair<LL,LL>(h+dh[j],w+dw[j]));
						}
					}
				}
			}
		};
		auto show_cost = [&](){
			for(int h=0;h<N;h++){
				for(int w=0;w<N;w++){
					cout << cost[h][w] << " ";
				}
				cout << endl;
			}
			cout << endl;
		};

		spread(leaving_h,leaving_w);
		ans += cost[leaving_h][leaving_w];
		seat[leaving_h][leaving_w] = 0;
		//printf("P[%d]=%lld\n",i,P[i]);
		//show_cost();
		while(!q.empty()){
			LL now_h = q.front().first;
			LL now_w = q.front().second;
			q.pop();
			//cout << "+=" << cost[now_h][now_w] << endl;
			spread(now_h,now_w);
			//show_cost();
		}
	}
}

int main(){
    cin >> N;
    for(int i=0;i<N*N;i++) cin>>P[i];

    solve();

    cout << ans << endl;
    return 0;
}

