void add(ll l, ll r, ll rc, ll id, ll pos, ll tar, ll val) {
	if(tar < l || r < tar)
		return;
	if(l == r) {
		strc[rc][id][pos] += val;
		return;
	}
	add(l, (l+r)/2, rc, id, pos*2, tar, val);
	add((l+r)/2+1, r, rc, id, pos*2+1, tar, val);
	strc[rc][id][pos] = strc[rc][id][pos*2] + strc[rc][id][pos*2+1];
}

ll get_s(ll l, ll r, ll rc, ll id, ll pos, ll L, ll R) {

	if(R < l || r < L) {
		return 0;
	}
	if(L <= l && r <= R) {
		return strc[rc][id][pos];
	}

	return get_s(l, (l+r)/2, rc, id, pos*2, L, R) + get_s((l+r)/2+1, r, rc, id, pos*2+1, L, R);

}

