    static int p[250001], pinv[250001], dist[250001];

    cin >> n;
    for(int i=1;i<=n*n;++i){
        cin >> p[i];
        pinv[p[i]] = i;
        int x = (i-1) / n, y = (i-1) % n;
        dist[i] = min({x, y, n-1-x, n-1-y});
    }

    int64_t ans = 0;

    for(int i=1;i<=n*n;++i){
        int j = p[i];
        int x = (j-1) / n, y = (j-1) % n;
        int c = dist[j];
        if(x   > 0) c = min(c, dist[j-n] + (pinv[j-n] > i ? 1 : 0));
        if(x+1 < n) c = min(c, dist[j+n] + (pinv[j+n] > i ? 1 : 0));
        if(y   > 0) c = min(c, dist[j-1] + (pinv[j-1] > i ? 1 : 0));
        if(y+1 < n) c = min(c, dist[j+1] + (pinv[j+1] > i ? 1 : 0));
        ans += dist[j] = c;
        queue<int> q;
        q.push(j);
        while(!q.empty()){
            int v = q.front();
            int vx = (v-1) / n, vy = (v-1) % n;
            q.pop();
            int cc = dist[v] + (pinv[v] > i ? 1 : 0);
            if(vx   > 0 && dist[v-n] > cc){ q.push(v-n); dist[v-n] = cc; }
            if(vx+1 < n && dist[v+n] > cc){ q.push(v+n); dist[v+n] = cc; }
            if(vy   > 0 && dist[v-1] > cc){ q.push(v-1); dist[v-1] = cc; }
            if(vy+1 < n && dist[v+1] > cc){ q.push(v+1); dist[v+1] = cc; }
        }
    }
    cout << ans << endl;

    return 0;
}

