    vector<P> order;
    for (int i = 0; i < n * n; i++) {
        int p;
        cin >> p;
        p--;

        int r = p / n,
            c = p % n;
        order.emplace_back(r, c);
        cost[r][c] = min({r, n - r - 1, c, n - c - 1});
    }

    auto isInside = [&](int r, int c) {
        return 0 <= r && r < n && 0 <= c && c < n;
    };

    memset(moved, false, sizeof(moved));
    int dr[] = {1, 0, -1, 0},
        dc[] = {0, 1, 0, -1};
    int ans = 0;
    for (P p : order) {
