  vector<pair<int, int>> pr(n * n);
  for (int i = 1; i <= n; i++) {
    for (int j = 1; j <= n; j++) {
      pr[cnt++] = {i, j};
    }
  }
  vector<pair<int, int>> arr;
  for (int i = 0; i < n * n; i++) {
    int x;
    cin >> x;
    x--;
    arr.pb(pr[x]);
  }
  vector<vector<int>> cur(n + 1, vector<int>(n + 1));
  for (int i = 1; i <= n; i++) {
    for (int j = 1; j <= n; j++) {
      cur[i][j] = min({i - 1, n - i, j - 1, m - j});
    }
