        for (int j = 1; j <= N; j++) {
            C[i][j] = min({i-1, j-1, N-i, N-j});
        }
    }
    auto X = [&](auto x) { return (x - 1) / N + 1; };
    auto Y = [&](auto x) { return (x - 1) % N + 1; };    

    long long ans = 0;

    auto bfs = [&](int x, int y) {
        ans += C[x][y];
        U[x][y] = 1;
