        Q.emplace(C[x][y], x, y);
        while (!Q.empty()) {
            auto [z, x, y] = Q.front(); Q.pop();
            for (int i = 0; i < 4; i++) {
                int xt = x + dx[i], yt = y + dy[i];
                if (z+1 == C[xt][yt]) {
                    C[xt][yt]--;
                    if (U[xt][yt]) Q.emplace(C[xt][yt], xt, yt);
                }
            }
        }
    };

    for (int i = 0; i < M; i++) {
        bfs(X(P[i]), Y(P[i]));
    }

