struct union_find{
    vector<int> par;
    vector<int> rank;
    vector<int> size;
    vector<lint> data;

    union_find(int n) : par(n), rank(n), size(n), data(n){
        for(int i = 0; i < n; i++){
            par[i] = i; rank[i] = 0; size[i] = 1;
        }
    }
    int root(int x){
        if(par[x] == x) return x;
        par[x] = root(par[x]);
        data[par[x]] = min(data[par[x]], data[x]);
        return par[x];
    }
    void unite(int x, int y){
        int rx = root(x);
        int ry = root(y);
        if (rx == ry) return;
        if (rank[rx] < rank[ry]){
            par[rx] = ry;
            data[ry] = min(data[ry], data[rx]);
            size[ry] += size[rx];
        }
        else{
            par[ry] = rx;
            data[rx] = min(data[rx], data[ry]);
            if (rank[rx] == rank[ry]) rank[rx]++;
            size[rx] += size[ry];
        }
    }
    bool same(int x, int y){
        int rx = root(x);
        int ry = root(y);
        return rx == ry;
    }
    lint getdata(int x){
        int rx = root(x);
        return data[rx];
    }
};

int main(){
    int n; cin >> n;

    vector<vector<int>> vp(n, vector<int>(n));
    vector<int> inv(n*n);
    rep(k, n*n){
        int p; cin>>p; p--;
        inv[k] = p;
        vp[p/n][p%n] = k;
    }

    union_find uf(n*n);
    rep(i,n) rep(j,n){
        uf.data[i*n+j] = min({i,n-1-i,j,n-1-j});
    }

    lint ans = 0;
    vector<P> d = {P(0,1),P(0,-1),P(1,0),P(-1,0)};
    rep(i, n*n){
        int p = inv[i]/n, q = inv[i]%n;
        rep(k, 4){
            int pp = p+d[k].fi, qq = q+d[k].se;
            if(pp<0||pp>=n||qq<0||qq>=n) continue;
            if(vp[pp][qq] < i){
                uf.unite(inv[i], pp*n+qq);
            }
        }
        ans += uf.getdata(inv[i]);
    }
