int main(int, char**)
{
    int n;
    cin >> n;

    vector < vector<int> > cost(n, vector<int>(n));
    rep(i,n) rep(j,n) {
        cost[i][j] = min(min(i, j), min(n-i-1, n-j-1));
    }
    vector < vector<int> > existp(n, vector<int>(n, 1));

    ll ans = 0;
    rep(_,n*n) {
        int ps;
        cin >> ps; ps--;
        int sx = ps / n;
        int sy = ps % n;

        ans += cost[sx][sy];
        existp[sx][sy] = 0;

        int dx[4] = { 0, 1, 0, -1 };
        int dy[4] = { 1, 0, -1, 0 };

        vector< vector<bool> > done(n, vector<bool>(n,false));
        queue<P> q;
        q.push(P(sx, sy));
        done[sx][sy] = true;
        while (!q.empty()) {
            int x = q.front().first;
            int y = q.front().second;
            q.pop();

            rep(i,4) {
                int nx = x + dx[i];
                int ny = y + dy[i];
                if (nx < 0 || ny < 0 || nx >= n || ny >= n) continue;
                if (done[nx][ny]) continue;
                int nc = cost[x][y] + existp[x][y];
                if (nc < cost[nx][ny]) {
                    cost[nx][ny] = nc;
                    q.push(P(nx,ny));
                }
                done[nx][ny] = true;
            }
        }
    }

    cout << ans << endl;

    return 0;
}


