void Main()
{
	int N;
	std::cin >> N;
	auto decode = [&](int idx)
	{
		--idx;
		return std::make_pair(idx / N, idx % N);
	};
	std::vector<std::pair<int, int>> vec;
	for (auto _ : boost::irange(N * N))
	{
		int code;
		std::cin >> code;
		vec.push_back(decode(code));
	}
	boost::multi_array<bool, 2> opened(boost::extents[N][N]), checked(boost::extents[N][N]);
	std::deque<std::tuple<int, int, int>> queue;
	int count = 0;
	auto push = [&](int a, int b, int c)
	{
		if (0 <= a && a < N && 0 <= b && b < N && !checked[a][b])
		{
			checked[a][b] = true;
			if (opened[a][b])
			{
				queue.emplace_front(a, b, c);
			}
			else
			{
				queue.emplace_back(a, b, c + 1);
			}
		}
	};
	for (auto [i, k] : vec)
	{
		for (auto x : boost::irange(N))
		{
			for (auto y : boost::irange(N))
			{
				checked[x][y] = false;
			}
		}
		opened[i][k] = true;
		push(i, k, 0);
		while (queue.size())
		{
			auto p = queue.front();
			auto [a, b, c] = p;
			lib::print::debug(a + 1, b + 1, c);
			queue.pop_front();
			if (a == 0 || a == N - 1 || b == 0 || b == N - 1)
			{
				count += c;
				break;
			}
			push(a - 1, b, c);
			push(a + 1, b, c);
			push(a, b - 1, c);
			push(a, b + 1, c);
		}
		queue.clear();
	}
	std::cout << count << std::endl;
}

