        y=(P[i]-1)%N;
        kirai+=seat[x][y];
        seat[x][y]=-seat[x][y];
        dfs(x,y,N,-seat[x][y]);
        memset(isVisited,0,MAXN);
    }
    printf("%d\n",kirai);

    return 0;
}

