		q.push(n * n - n + i);
		board[i * n] = 1;
		q.push(i * n);
		board[i * n + n - 1] = 1;
		q.push(i * n + n - 1);
	}

	while (!q.empty()) {
		k = q.front();
		q.pop();

		if (k >= n) {
			if (board[k - n] == 0 || board[k - n] > board[k] + 1) {
				board[k - n] = board[k] + 1;
				q.push(k - n);
			}
		}
		if (k < n * n - n) {
			if (board[k + n] == 0 || board[k + n] > board[k] + 1) {
				board[k + n] = board[k] + 1;
				q.push(k + n);
			}
		}
		if (k % n != 0) {
			if (board[k - 1] == 0 || board[k - 1] > board[k] + 1) {
				board[k - 1] = board[k] + 1;
				q.push(k - 1);
			}
		}
