						board[k - 1] = board[k] + 1;
						q.push(k - 1);
						visit[k - 1] = i;
					}
				}
			}
			if ((k + 1) % n != 0) {
				if (visit[k + 1] != i) {
					if (exist[k + 1] == 0) {
						board[k + 1] = min(board[k + 1], board[k]);
						q.push(k + 1);
						visit[k + 1] = i;
					} else if (board[k + 1] > board[k] + 1) {
						board[k + 1] = board[k] + 1;
						q.push(k + 1);
						visit[k + 1] = i;
					}
				}
			}
		}
	}

	printf("%d\n", ans);

	return 0;
}

