struct uset
{
    vector<int> fa;
    vector<int> val;
    uset(int n)
    {
        fa.resize(n);
        val.resize(n);
        fill(val.begin(), val.end(), 0x7fffffff);
        for (int i = 0; i < n; ++i)
            fa[i] = i;
    }
    int getfa(int a)
    {
        return fa[a] == a ? a : (fa[a] = getfa(fa[a]));
    }
    int &getval(int a)
    {
        return val[getfa(a)];
    }
    void merge(int a, int b)
    {
        if (getfa(a) == getfa(b))
            return;
        if (getval(a) < getval(b))
            fa[getfa(b)] = getfa(a);
        else
            fa[getfa(a)] = getfa(b);
    }
};
