int uesd[MAX_H][MAX_W];

int dx[4] = {1, 0, -1, 0};
int dy[4] = {0, 1, 0, -1};

int main(int argc, const char * argv[]) {
    cin >> n;

    vector<int> order;
    for(int h=0; h<n; h++){
        for(int w=0; w<n; w++){
            int number;
            cin >> number;
            order.push_back(number);
            dist[h][w] = min(min(w, h), min((n-1)-w, (n-1)-h));
            uesd[h][w] = 1;
        }
    }

    int res=0;
    for(int i=0; i<order.size(); i++){

        int x=(order[i]-1)%n;
        int y=(order[i]-1)/n;
        queue<P> que;
        que.push(P(x, y));

        res+=dist[y][x];
        uesd[y][x] = 0;

        while(que.size()){
            P p = que.front();
            que.pop();

            for(int i=0; i<4; i++){
                int nx = p.first+dx[i];
                int ny = p.second+dy[i];

                if(nx<0 || n<=nx || ny<0 || n<=ny) continue;

                if(dist[ny][nx]>dist[p.second][p.first]+uesd[p.second][p.first]){
                    dist[ny][nx]=dist[p.second][p.first]+uesd[p.second][p.first];
                    que.push(P(nx, ny));
                }
            }
        }
    }

    cout << res << endl;

    return 0;
}

