using namespace std;

int n, p[N*N];
int d[N][N], o[N][N];

stack<pip > q;
void upd(){
	while(!q.empty()){
		pip c = q.top();
		q.pop();
		c.F = -c.F;
		int i = c.S.F, j = c.S.S;
		if(d[i][j] < c.F) continue;
		d[i][j] = c.F;
		if(d[i][j]+o[i-1][j] < d[i-1][j]) q.push({-d[i][j]-o[i-1][j], {i-1, j}});
		if(d[i][j]+o[i+1][j] < d[i+1][j]) q.push({-d[i][j]-o[i+1][j], {i+1, j}});
		if(d[i][j]+o[i][j-1] < d[i][j-1]) q.push({-d[i][j]-o[i][j-1], {i, j-1}});
		if(d[i][j]+o[i][j+1] < d[i][j+1]) q.push({-d[i][j]-o[i][j+1], {i, j+1}});
	}
}

int main(){

	cin.tie(0);
	ios_base::sync_with_stdio(0);

	cin >> n;
	for(int i=0; i<n*n; i++) cin >> p[i];
	for(int i=1; i<=n; i++){
		for(int j=1; j<=n; j++){
			o[i][j] = 1;
			d[i][j] = min(min(i, n-i+1), min(j, n-j+1));
		}
	}

	int ans = 0;

	for(int k=0; k<n*n; k++){
		int i = 1+(p[k]-1)/n, j = 1+(p[k]-1)%n;
		ans += d[i][j]-1;
		o[i][j] = 0;
		q.push({-(d[i][j]-1), {i, j}});
		upd();
	}

	cout << ans << endl;

	return 0;
}

