struct coordinate{
    int x, y;
};

constexpr int MAX_N = 500;
coordinate Q[MAX_N * MAX_N];
int dist[MAX_N][MAX_N];
bool vacant[MAX_N][MAX_N];

int main(void){
    fread_unlocked(Input, 1, MAX_INPUT_SIZE, stdin);
    const int n = getint();
    {
        // initial distance
        const int p = n - 1;
        for(int i = 0; i < n; ++i){
            const int d1 = (i > p - i) ? p - i : i;
            for(int j = 0; j < n; ++j){
                const int d2 = (j > p - j) ? p - j : j;
                dist[i][j] = (d1 > d2) ? d2 : d1;
            }
        }
    }
    int res = 0;
    for(int _ = n * n; _--;){
        const int p = getint() - 1;
        {
            const int px = p / n, py = p % n;
            res += dist[px][py];
            vacant[px][py] = true;
            Q[0] = {px, py};
        }
        int head = 0, tail = 1;
        while(head != tail){
            const int x = Q[head].x, y = Q[head].y; ++head;
            const int nd = (vacant[x][y]) ? dist[x][y] : dist[x][y] + 1;
            if(x - 1 >= 0 and dist[x - 1][y] > nd){ dist[x - 1][y] = nd; Q[tail++] = {x - 1, y}; }
            if(y - 1 >= 0 and dist[x][y - 1] > nd){ dist[x][y - 1] = nd; Q[tail++] = {x, y - 1}; }
            if(y + 1 <  n and dist[x][y + 1] > nd){ dist[x][y + 1] = nd; Q[tail++] = {x, y + 1}; }
            if(x + 1 <  n and dist[x + 1][y] > nd){ dist[x + 1][y] = nd; Q[tail++] = {x + 1, y}; }
        }
    }
    printf("%d\n", res);
    return 0;
}

