    cin >> n;
    int sz = n * n;
    vector<int> p(sz);
    for(int i = 0; i < sz; ++i) cin >> p[i];
    vector<P> pos(sz + 1);
    int cur = 1;
    vector<vector<int>> board(n, vector<int>(n));
    vector<vector<int>> dist(n, vector<int>(n, INF));
    for(int i = 0; i < n; ++i){
        for(int j = 0; j < n; ++j){
