int N; 
vector<int> per;
vector<int> cost;
vector<bool> out;

void update(int curr, int c, bool first=true) {
    if (curr <= 0 || curr > N*N) return;
    if (!first && cost[curr] <= c) return;

    // if (!first)
        // cout << "\tvisito "<<curr<< " costo "<<cost[curr] << " updated to "<<c<<endl;
    cost[curr] = c;

    if (out[curr] == false) return;

    if (curr%N != 0) update(curr+1 , c, false);
    if (curr%N != 1) update(curr-1, c, false);
    update(curr+N, c, false);
    update(curr-N, c, false);
}

void solve() {
    cin >> N;
    per = vi(N*N+1);
    cost = vi(N*N+1);
    out = vector<bool>(N*N+1, false);
    for (int i=1; i<N*N+1; ++i) {
        int p; cin >> p;
        per[i] = p;
    }

    // assign cost
    for (int i=0; i<N; ++i) {
        for (int j=0; j<N; ++j) {
            cost[i*N+j+1] = min(min(i, N-i-1), min(j, N-j-1));
        }
    }
    // cout << per << cost;
    // free one by one
    ll ans = 0;
    for (auto& i : per) {
        if (i == 0) continue;
        // cout << "libero posto "<<i<<" costo "<<cost[i]<<endl;
        out[i] = true;
        ans += cost[i];
        update(i, cost[i]);
    }

    cout << ans << "\n";
}

int main () {
    solve();
    return 0;
}

