#define FOR(i,n) for (int i = 0; i < n; i++)

int dis[512][512];
int occ[512][512];

int per[512*512];
int n;

void do_relax_loop(queue<pair<int, int>> &q) {
  while (q.size()) {
    int x, y;
    x = q.front().first, y = q.front().second;
    q.pop();
    #define RELAX(i,j,cost) if (i >= 0 && j >= 0 && i < n && j < n && cost < dis[i][j]) dis[i][j] = cost, q.push(make_pair(i, j));
    RELAX(x-1,y,dis[x][y]+occ[x-1][y]);
    RELAX(x+1,y,dis[x][y]+occ[x+1][y]);
    RELAX(x,y-1,dis[x][y]+occ[x][y-1]);
    RELAX(x,y+1,dis[x][y]+occ[x][y+1]);
    #undef RELAX
  }
}

void relax_dis() {
  FOR(i,n) {
    if (dis[i][0] > occ[i][0]) dis[i][0] = occ[i][0];
    if (dis[i][n-1] > occ[i][n-1]) dis[i][n-1] = occ[i][n-1];
    if (dis[0][i] > occ[0][i]) dis[0][i] = occ[0][i];
    if (dis[n-1][i] > occ[n-1][i]) dis[n-1][i] = occ[n-1][i];
  }
  queue<pair<int, int>> q;
  FOR(i,n) FOR(j,n) if (dis[i][j] == 0) q.push(make_pair(i, j));
  FOR(i,n) FOR(j,n) if (dis[i][j] == 1) q.push(make_pair(i, j));
  do_relax_loop(q);
}

void relax_dis_near(int x, int y) {
  queue<pair<int, int>> q;
  if ((x == 0 || y == 0 || x == n-1 || y == n-1) && dis[x][y]) dis[x][y] = 0, q.push(make_pair(x, y));
  if (x > 0 && dis[x-1][y] < dis[x][y]) dis[x][y] = dis[x-1][y], q.push(make_pair(x, y));
  if (x+1<n && dis[x+1][y] < dis[x][y]) dis[x][y] = dis[x+1][y], q.push(make_pair(x, y));
  if (y > 0 && dis[x][y-1] < dis[x][y]) dis[x][y] = dis[x][y-1], q.push(make_pair(x, y));
  if (y+1<n && dis[x][y+1] < dis[x][y]) dis[x][y] = dis[x][y+1], q.push(make_pair(x, y));
  do_relax_loop(q);
}

int main() {
  scanf("%i", &n);
  FOR(i,n*n) scanf("%i", per+i), per[i]--;
  memset(dis, 1, sizeof(dis));
  FOR(i,n) FOR(j,n) occ[i][j] = 1;
  relax_dis();
  long long ans = 0;
  FOR(i,n*n) {
    int x = per[i] % n;
    int y = per[i] / n;
    ans += dis[x][y];
    occ[x][y] = 0;
    relax_dis_near(x, y);
  }
  printf("%lli\n", ans-n*n);
}

