int bfs(int x, int y) {
    que.clear();
    memset(d, 0x3f, sizeof d);
    memset(go, false, sizeof go);

    d[x][y] = 0;
    que.push_back({x, y});

    while(que.size()) {
        auto t = que.front();
        que.pop_front();

        if(go[t.x][t.y]) continue;
        go[t.x][t.y] = true;

        if(t.x == 0 || t.x == n - 1 || t.y == 0 || t.y == n - 1) {
            return d[t.x][t.y];
        }

        for(int i = 0; i < 4; i ++ ) {
            int a = t.x + dx[i], b = t.y + dy[i];
            if(go[a][b]) continue;

            // if(x == 2 && y == 2) {
            // cout << a << ' ' << b << "    " << st[a][b] << endl;
            // }

            if(st[a][b]) {
                if(d[a][b] > d[t.x][t.y]) {
                    d[a][b] = d[t.x][t.y];
                    que.push_front({a, b});
                }
            }
            else {
                if(d[a][b] > d[t.x][t.y] + 1) {
                    d[a][b] = d[t.x][t.y] + 1;
                    que.push_back({a, b});
                }
            }
        }
    }
} 

