			if (table[y][x] > k) {
				auto r = tree.root(y * n + x);
				chmin(tmp, cost[r / n][r % n] + 1);
				continue;
			}
			if (y == 0 || x == 0 || y == n - 1 || x == n - 1) {
				chmin(tmp, 0); break;
			}
			ad(y + 1, x);
			ad(y - 1, x);
			ad(y, x - 1);
			ad(y, x + 1);

		}
		ans += tmp;
		update(fy, fx, tmp, fy + 1, fx);
		update(fy, fx, tmp, fy - 1, fx);
		update(fy, fx, tmp, fy, fx + 1);
		update(fy, fx, tmp, fy, fx - 1);

	}
	cout << ans << endl;


	dump(table);
	dump(cost);


}

