int main(){
    int n;
    cin >> n;

    vv cost(n,v (n));
    vector<vector<bool>> seat(n,vector<bool> (n,true));
    for(int i=0; i<n; i++){
        for(int j=0; j<n; j++){
            cost[i][j] = min(min(i,n-1-i), min(j,n-1-j));
        }
    }

    int ans = 0;

    v di={-1,0,1,0};
    v dj={0,-1,0,1};//四方

    for(int i=0; i<n*n; i++){
        int p;
        cin >> p;
        int pi = (p-1)/n;
        int pj = (p-1)%n;

        ans += cost[pi][pj];
        seat[pi][pj] = false;

        //幅優先で距離リストを更新
        queue<P> more;
        more.push({pi,pj});

        while(!more.empty()){

            int ni = more.front().first;
            int nj = more.front().second;

            for(int l=0; l<4; l++){
                if(ni+di.at(l)<n && ni+di.at(l)>=0 && nj+dj.at(l)<n && nj+dj.at(l)>=0){

                    if(cost[ni+di[l]][nj+dj[l]]>cost[ni][nj]+seat[ni][nj]){

                        cost[ni+di[l]][nj+dj[l]] = cost[ni][nj]+seat[ni][nj];
                        more.push({ni+di[l], nj+dj[l]});

                    }
                }
            }
            more.pop();
        }
    }

    cout << ans << endl;
    return 0;
}

