int find(int a,vector<int>& uf){
  if(uf[a]<0) return a;
  return uf[a]=find(uf[a],uf);
}

void unite(int a,int b,vector<int>& uf,vector<int>& rp){
  a=find(a,uf); b=find(b,uf);
  if(a==b) return;
  if(uf[a]>uf[b]) swap(a,b);
  uf[a]+=uf[b];
  uf[b]=a;
  rp[a]=min(rp[a],rp[b]);
}

