void dfs(int x, int y) {
	for (int i = 0; i < 4; ++i) {
		int nx = x + dx[i], ny = y + dy[i];
		if (nx >= 1 && nx <= n && ny >= 1 && ny <= n && dist[nx][ny] > dist[x][y] + a[nx][ny]) {
			dist[nx][ny] = dist[x][y] + a[nx][ny];
			dfs(nx, ny);
		}
	}
}

