            b=1;
            t[y][x]=t[y-1][x]+r[y-1][x];
        }
    }
    if (y<n){
        if ((t[y+1][x]+r[y+1][x])<t[y][x]){
            b=1;
            t[y][x]=t[y+1][x]+r[y+1][x];
        }
    }
    if (x>1){
        if ((t[y][x-1]+r[y][x-1])<t[y][x]){
            b=1;
            t[y][x]=t[y][x-1]+r[y][x-1];
        }
    }
    if (y<n){
        if ((t[y][x+1]+r[y][x+1])<t[y][x]){
            b=1;
            t[y][x]=t[y][x+1]+r[y][x+1];
        }
    }
    if (b){
        if (y>1) f(y-1, x);
        if (y<n) f(y+1, x);
        if (x>1) f(y, x-1);
        if (x<n) f(y, x+1);
    }
