        int d1=std::distance(rows[l].begin(),rows[l].lower_bound(r)),d2,d3,d4,x1,y1,x2,y2;
        d2=std::distance(rows[l].begin(),rows[l].upper_bound(n));
        d3=std::distance(cols[r].begin(),cols[r].lower_bound(l));
        d4=std::distance(cols[r].begin(),cols[r].upper_bound(n));

        x1=(l-1-d3); y1=(n-l-(d4-d3));
        x2=(r-1-d1); y2=(n-r-(d2-d1));
        //cout<<d1<<" "<<d2<<" "<<d3<<" "<<d4<<"\n"; 
        if(min(x1,y1)>min(x2,y2))
           ans+=min(x2,y2);
        else 
           ans+=min(x1,y1);
        rows[l].insert(r);
        cols[r].insert(l);
    }
    cout<<ans<<"\n";
}
