int main(void)
{
    cin.sync_with_stdio(false);
    cin >> N;

    vector<int> Ps(N * N);
    REP(n, N * N) {
        cin >> Ps[n];
    }

    vector<vector<int>> seated(N, vector<int>(N, 1));
    vector<vector<int>> cost(N, vector<int>(N));
    REP(h, N) {
        REP(w, N) {
            int c = w;
            chmin(c, N - w - 1);
            chmin(c, h);
            chmin(c, N - h - 1);
            cost[h][w] = c;
        }
    }
    //debug_print(cost);

    int ans = 0;
    for(auto p: Ps) {
        auto h = (p - 1) / N;
        auto w = (p - 1) % N;
        //cout << "P " << p << ", ->" << h << "," << w << endl;

        auto c = cost[h][w]; 
        ans += c;

        seated[h][w] = 0;


        map<P, int> seen;
        seen[mp(h, w)] = c;

        queue<P> q;
        q.push(mp(h, w));

        while (!q.empty()) {
            auto p = q.front(); q.pop();

            int next_val = c;
            if (seated[p.first][p.second]) {
                next_val++;
            }

            REP(d, 4) {
                auto h2 = p.first + dh[d];
                auto w2 = p.second + dw[d];
                if (h2 < 0 || h2 >= N || w2 < 0 || w2 >= N) continue;

                if (seen.count(mp(h2, w2))) {
                    continue;
                }

                if (cost[h2][w2] <= next_val) {
                    continue;
                }

                cost[h2][w2] = next_val;
                seen[mp(h2, w2)] = next_val;
                q.push(mp(h2, w2));
            }
        }

        //cout << "ans = " << ans << endl;
        //debug_print(cost);
    }
    cout << ans << endl;

    return 0;
}

