using namespace std;

int n, p[N*N];
int d[N][N], o[N][N];

priority_queue<pip > q;
void upd(){
	while(!q.empty()){
		pip c = q.top();
		q.pop();
		c.F = -c.F;
		int i = c.S.F, j = c.S.S;
		if(d[i][j] < c.F) continue;
		d[i][j] = c.F;
		if(d[i][j]+o[i-1][j] < d[i-1][j]) q.push({-d[i][j]-o[i-1][j], {i-1, j}});
		if(d[i][j]+o[i+1][j] < d[i+1][j]) q.push({-d[i][j]-o[i+1][j], {i+1, j}});
		if(d[i][j]+o[i][j-1] < d[i][j-1]) q.push({-d[i][j]-o[i][j-1], {i, j-1}});
		if(d[i][j]+o[i][j+1] < d[i][j+1]) q.push({-d[i][j]-o[i][j+1], {i, j+1}});
	}
}

