			d[i][j] = min(min(i, n-i+1), min(j, n-j+1));
		}
	}

	int ans = 0;

	for(int k=0; k<n*n; k++){
		int i = 1+(p[k]-1)/n, j = 1+(p[k]-1)%n;
		ans += d[i][j]-1;
		o[i][j] = 0;
		q.push({-(d[i][j]-1), {i, j}});
		upd();
	}

	cout << ans << endl;

	return 0;
}

