    REP(i,0,n*n) {
        cin >> a[i];
        --a[i];
    }
    vector<vector<bool>> b(n,vector<bool>(n));
    VVI rem(n,VI(n));
    REP(i,0,n*n) {
        int x = i / n, y = i % n;
        rem[x][y] = min({x,y,n-1-x,n-1-y});
    }

