int solve(int i, vvi &g, vpii &v) {
	vvi dis(g.size(), vi(g[0].size(), INF));
	// vvi prev(g.size(), vi(g[0].size(), -1));
	vi di = { 1, 0, -1, 0 }, dj = { 0, 1, 0, -1 };
	int si, sj; tie(si, sj) = v[i];
	priority_queue<pair<int, pii>, vector<pair<int, pii>>, greater<pair<int, pii>>> pq;	
	dis[si][sj] = 0;
	pq.push(make_pair(dis[si][sj], pii(si, sj)));
	while (!pq.empty()) {
		auto t = pq.top(); pq.pop();
		int d, ui, uj; d = t.first; tie(ui, uj) = t.second;
		if (d > dis[ui][uj]) continue;
		rep(dir, 4) {
			int vi = ui + di[dir], vj = uj + dj[dir];
			if (vi < 0 or g.size() <= vi) continue;
			if (vj < 0 or g[0].size() <= vj) continue;
			if (g[vi][vj] <= i) { // 空席
				if (dis[vi][vj] > d) {
					dis[vi][vj] = d;
					if (0 < vi and vi < g.size() - 1 and 0 < vj and vj < g[0].size() - 1) {
						// 出口のマスでない場合で，かつ，距離が短くなった場合のみpqに入れる
						pq.push(make_pair(dis[vi][vj], pii(vi, vj)));
					}
				}
			} else if (dis[vi][vj] > i) { // 客がいる
				if (dis[vi][vj] > d + 1) {
					dis[vi][vj] = d + 1;
					if (0 < vi and vi < g.size() - 1 and 0 < vj and vj < g[0].size() - 1) {
						// 出口のマスでない場合で，かつ，距離が短くなった場合のみpqに入れる
						pq.push(make_pair(dis[vi][vj], pii(vi, vj)));
					}
				}
			}
		}
	}
	int res = INF;
	rep(k, g.size()) {
		chmin(res, dis[0][k]);
		chmin(res, dis[g.size() - 1][k]);
		chmin(res, dis[k][0]);
		chmin(res, dis[k][g.size() - 1]);
	}
	// dbl(i); dbvv(g); dbl(res);
	return res;
}

int main() {
	int N; cin >> N;
	vi P(N * N); rep(i, N * N) cin >> P[i];
	vvi g(N, vi(N)); vpii v;
	rep(i, N * N) {
		int x = (P[i] - 1) / N, y = (P[i] - 1) % N;
		g[x][y] = i; v.push_back(pii(x, y)); // i:0-ind
	}
	// dbvv(g); dbl(v);
	int ans = 0;
	rep(i, N * N) ans += solve(i, g, v);
	cout << ans << endl;
}

