// *X.find_by_order(i) = ith largest element (counting from zero)
// X.order_of_key(k) = number of items in X < k (strict lt)

void update(int r, int c, vi& dists, vi& empty, int N) {
    int cur = N*r + c;
    int cd = dists[cur];

    if (r > 0 && dists[N*(r-1) + c] > cd + empty[N*(r-1) + c]) {
        dists[N*(r-1) + c] = cd+ empty[N*(r-1) + c];
        update(r-1, c, dists,empty, N);
    }

    if (r+1<N && dists[N*(r+1) + c] > cd + empty[N*(r+1) + c]) {
        dists[N*(r+1) + c] = cd+ empty[N*(r+1) + c];
        update(r+1, c, dists,empty, N);
    }

    if (c > 0 && dists[N*r + c-1] > cd+ empty[N*r + c-1]) {
        dists[N*r + c-1] = cd+ empty[N*r + c-1];
        update(r, c-1, dists, empty, N);
    }

    if (c+1 < N && dists[N*r+c+1] > cd+ empty[N*r + c+1]) {
        dists[N*r + c+1] = cd+ empty[N*r + c+1];
        update(r, c+1, dists, empty,N);
    }
}

int main(){
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int N;
    cin >> N;

    vi P(N*N, 0);
    for (int i=0;i<N*N;i++) cin >> P[i];
    for (int i=0;i<N*N;i++) P[i]--;

    vi dists(N*N, N);
    vi empty(N*N, 1);
    for (int i=0;i<N*N;i++) {
        int r = i/N;
        int c = i%N;
        dists[i] = min(dists[i], c+1);
        dists[i] = min(dists[i], r+1);
        dists[i] = min(dists[i], N-c);
        dists[i] = min(dists[i], N-r);
    }

    int ans = 0;
    for (int i=0;i<N*N;i++) {
        int p = P[i];

        dists[p]--;
        empty[p]=0;
        ans += dists[p];

        update(p/N, p%N, dists, empty, N);
    }

    cout << ans << endl;

    return 0;
}

