bool used[250010];

ll bfs( ll i, ll j ) {
  ll ret = h[i*N+j];
  ll nh = h[i*N+j]+used[i*N+j];

  rep( d, 4 ) {
    ll ni = i+dy[d], nj = j+dx[d];

    if( nh < h[ni*N+nj] ) {
      h[ni*N+nj] = nh;
      bfs( ni, nj );
    }
  }

  return ret;
}

