int N;
vvb g;
vvi dis;

int solve(int s) {
	int si = (s - 1) / N, sj = (s - 1) % N;
	g[si][sj] = false; // Piに対応する座席(si,sj)の客がいなくなった
	vi di = { 1, 0, -1, 0 }, dj = { 0, 1, 0, -1 };
	rep(dir, 4) {
		int ti = si + di[dir], tj = sj + dj[dir];
		if (ti < 0 or N <= ti or tj < 0 or N <= tj) continue;
		if (g[ti][tj]) chmin(dis[si][sj], dis[ti][tj] + 1);
		else chmin(dis[si][sj], dis[ti][tj]);
	}
	queue<pii> q; q.push(pii(si, sj));
	while (!q.empty()) {
		int ui, uj; tie(ui, uj) = q.front(); q.pop();
		rep(dir, 4) {
			int vi = ui + di[dir], vj = uj + dj[dir];
			if (vi < 0 or N <= vi or vj < 0 or N <= vj) continue;
			int d = dis[ui][uj]; if (g[vi][vj]) d++;
			if (dis[vi][vj] > d) {
				dis[vi][vj] = d;
				// if (0 < vi and vi < N - 1 and 0 < vj and vj < N - 1)
				q.push(pii(vi, vj));
			}
		}
	}
	// dbs(si, sj); dbvv(g); dbvv(dis); dbl(dis[si][sj]);
	return dis[si][sj];
}

int main() {
	cin >> N;
	vi P(N * N); rep(i, N * N) cin >> P[i];
	g.assign(N, {}); rep(i, N) g[i].assign(N, true);
	dis.assign(N, {}); rep(i, N) dis[i].assign(N, -1);
	rep(i, N) rep(j, N) dis[i][j] = min({ i, (N - 1) - i, j, (N - 1) - j });
	// dbvv(g); dbvv(dis);
	int ans = 0;
	rep(i, N * N) ans += solve(P[i]);
	cout << ans << endl;
}

