}
void insert(int x,int y){
	//cout2(x,y);
	x=find(x);
	y=find(y);
	if(x==y)
		return;
	if(size1[x]<=size1[y]){
		size1[y]+=size1[x]+1;
		a[x]=y;
		l[y]=min(l[y],l[x]);
		r[y]=max(r[y],r[x]);
		u[y]=min(u[y],u[x]);
		d[y]=max(d[y],d[x]);
		return;
	}
	size1[x]+=size1[y]+1;
	a[y]=x;
	l[x]=min(l[y],l[x]);
	r[x]=max(r[y],r[x]);
	u[x]=min(u[y],u[x]);
	d[x]=max(d[y],d[x]);
}
void solve(int countu){
	int n;
	scanf("%d",&n);
	memset(a,-1,sizeof(a));
	int count=1;
	repeat(i,1,n+1){
		repeat(j,1,n+1){
			x[count]=i;
			y[count]=j;
			val[i][j]=count;
			u[count]=i;
			d[count]=i;
			l[count]=j;
			r[count]=j;
			count++;
		}
	}
	int ans=0;
	set<pint> s;
	rep(i,n*n){
		int d1;
		scanf("%d",&d1);
		rep(j,4){
			int h=x[d1]+dx[j];
			int h1=y[d1]+dy[j];
			if(s.find({h,h1})!=s.end())
				insert(d1,val[h][h1]);
		}
		s.insert({x[d1],y[d1]});
		int j=find(d1);
		ans+=min(u[j]-1,int_min(n-d[j],l[j]-1,n-r[j]));
	}
	cout1(ans);
}
