void f(int p,int &x,int &y)
{
    if (p%n==0) {x=p/n; y=n;}
    else {x=p/n+1; y=p%n;}
}
int lowbit(int x)
{
    return x&(-x);
}
void add(int c[],int x)
{
    while (x<=n) {
        c[x]+=1;
        x+=lowbit(x);
    }
}
int ask(int c[],int x)
{
    int ret ;
    ret=0;
    while (x) {
        ret+=c[x];
        x-=lowbit(x);
    }
    return ret ;
}
int main()
{
   // freopen("text.in","r",stdin);
