int main(int argc, char *argv[])
{
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n; cin >> n;

    vector<char> occ(n*n, true);

    auto outside = [&](int x, int y) {
      return !(0 <= x && x < n && 0 <= y && y < n);
    };

    auto at = [&](int x, int y) -> auto& {
      static char unocc = false;
      if (outside(x,y)) return unocc;
      return occ[x + y*n];
    };

    vi A(n*n);
    for (auto &x : A) cin >> x;
    int res = 0;
    for (auto i : A) {
        int count = -1;
        --i;
        at(i%n, i/n) = false;
        vector<char> vis(n*n, 0);
        deque<tuple<int,int,int>> Q;
        Q.push_front({i%n,i/n,0});
        while (!Q.empty()) {
          auto [x,y,d] = Q.back();
          Q.pop_back();
          if (outside(x,y)) {
            count = d;
            break;
          }

          if (vis[x + y*n]) continue;
          vis[x + y*n] = true;

          if   (at(x+1,y  )) Q.push_front({x+1,y,d+1});
          else               Q.push_back({x+1,y,d});
          if   (at(x-1,y  )) Q.push_front({x-1,y,d+1});
          else               Q.push_back({x-1,y,d});
          if   (at(x  ,y+1)) Q.push_front({x,y+1,d+1});
          else               Q.push_back({x,y+1,d});
          if   (at(x  ,y-1)) Q.push_front({x,y-1,d+1});
          else               Q.push_back({x,y-1,d});
        }
        assert(count != -1);
        res += count;
    }
    cout << res << "\n";
}

