const int N = 555;
const int dx[]={0,0,1,-1};
const int dy[]={-1,1,0,0};
int n,a[N][N],vis[N*N],d[N*N],c[N*N],clk;
int ans[N][N];
pii pos[N*N];
deque<int> q;
int main() {
	scanf("%d", &n);
	int now = 0;
	REP(i,1,n) REP(j,1,n) { 
		a[i][j] = ++now;
		pos[now] = pii(i,j);
		c[now] = 1;
		int u=min(i-1,j-1);
		int v=min(n-i,n-j);
		ans[i][j] = min(u,v);
	}
	int tot = 0;
	REP(t,1,n*n) {
		q.clear();
		int s;
		scanf("%d", &s);
		int x=pos[s].x,y=pos[s].y;
		c[s]=0;
		if (!ans[x][y]) continue;
		q.push_back(s);
		vis[s]=++clk,d[s]=0;
		while (q.size()) {
			int u(q.back()); q.pop_back();
			if (!d[u]&&!ans[pos[u].x][pos[u].y]||pos[u].x==1||pos[u].x==n||pos[u].y==1||pos[u].y==n) {
				tot += d[u];
				if (!d[u]) {
					REP(k,0,3) {
						int xx=x+dx[k],yy=y+dy[k];
						ans[xx][yy]=0;
					}
				}
				break;
			}
			REP(k,0,3) {
				int x=pos[u].x+dx[k],y=pos[u].y+dy[k];
				if (1<=x&&x<=n&&1<=y&&y<=n&&vis[a[x][y]]!=clk) {
					d[a[x][y]] = d[u]+c[a[x][y]];
					vis[a[x][y]] = clk;
					if (c[a[x][y]]) q.push_front(a[x][y]);
					else q.push_back(a[x][y]);
				}
			}
		}
	}
	printf("%d\n", tot);
}

