bool in(int x,int y){
	return x>=0&&x<n&&y>=0&&y<n;
}
int dx[4]={1,-1,0,0};
int dy[4]={0,0,1,-1};

void dfs(int x,int y){
	for(int i=0;i<4;i++){
		int nx=x+dx[i],ny=y+dy[i];
		if(in(nx,ny)){
			if(!vis[x][y]){
				if(dist[nx][ny]>dist[x][y]+1)
					dist[nx][ny]=dist[x][y]+1,dfs(nx,ny);
			}
			else{
				if(dist[nx][ny]>dist[x][y])
					dist[nx][ny]=dist[x][y],dfs(nx,ny);
			}
		}
	}
}

