int dist[505][505];
bool fil[505][505];

void solve() {
    int n; cin >> n;
    vector<int> p(n*n);
    rep (i, n*n) cin >> p[i];
    rep (i, n) {
        rep (j, n) {
            dist[i][j] = min({i,n-i-1,j,n-j-1});
            fil[i][j] = true;
        }
    }
    int ans = 0;
    rep (i, n*n) {
        p[i]--;
        int x = p[i]/n, y = p[i]%n;
        ans += dist[x][y];
        fil[x][y] = false;
        queue<pair<int, int>> cand;
        cand.push({x, y});
        while (cand.size()) {
            int X = cand.front().first, Y = cand.front().second; cand.pop();
            rep (j, 4) {
                int nx = X + dx[j], ny = Y + dy[j];
                if (nx<0||n<=nx||ny<0||n<=ny) continue;
                if (dist[nx][ny] > dist[X][Y]+fil[X][Y]) {
                    dist[nx][ny] = dist[X][Y]+fil[X][Y];
                    cand.push({nx, ny});
                }
            }
        }
    }

    cout << ans << endl;
}

signed main() {
    cin.tie(0);
    ios::sync_with_stdio(false);
    solve();
}

