    P[i]--;
  }
  vl sit(n * n, 1);
  vl cost(n * n, 0);
  REP(i, n * n) {
    ll y = i / n, x = i % n;
    cost[i] = (ll)min({y, n - 1LL - y, x, n - 1LL - x});
  }
  ll ans = 0;
  REP(i, n * n) {
    ans += cost[P[i]];
    PQ(ll) que;
    que.push(P[i]);
    sit[P[i]] = 0;
    while (!que.empty()) {
      ll q = que.top();
      que.pop();
      ll y = q / n, x = q % n;
      REP(k, 4) {
        ll yy = y + dy[k], xx = x + dx[k];
        if (0 <= yy && yy < n && 0 <= xx && xx < n &&
            cost[f(yy, xx)] > cost[f(y, x)] + sit[f(y, x)]) {
          cost[f(yy, xx)] = cost[f(y, x)] + sit[f(y, x)];
          que.push(f(yy, xx));
        }
      }
    }
  }
  cout << ans << endl;

  return 0;
