void taiseki(int nowi, int nowj, int nowseki, bool start) {
	if (nowi <= 0 || nowi >= n - 1 || nowj <= 0 || nowj >= n - 1) {
		if (start == false)
			return;
	}
	if (seki[nowi][nowj] > nowseki || (solved[nowi][nowj]==true && seki[nowi][nowj]==nowseki) ) {
		if (visit[nowi][nowj] == false) {
			seki[nowi][nowj] = nowseki;
			visit[nowi][nowj] = true;
			if (solved[nowi][nowj] == true)nowseki--;
			taiseki(nowi - 1, nowj, nowseki + 1, false);
			taiseki(nowi + 1, nowj, nowseki + 1, false);
			taiseki(nowi, nowj - 1, nowseki + 1, false);
			taiseki(nowi, nowj + 1, nowseki + 1, false);
		}
	}
	return;
}


