template <class T>
std::vector<T> vec(int len, T elem) { return std::vector<T>(len, elem); }

const std::vector<int> dx{-1, 1, 0, 0}, dy{0, 0, -1, 1};

void solve() {
    int n;
    std::cin >> n;
    int m = n * n;

    auto enc = [&](int k) {
        return std::make_pair(k / n, k % n);
    };

    auto dist = vec(n, vec(n, 0));
    for (int x = 0; x < n; ++x) {
        for (int y = 0; y < n; ++y) {
            dist[x][y] = std::min({x, n - x - 1, y, n - y - 1});
        }
    }

    auto erased = vec(n, vec(n, false));
    int ans = 0;

    for (int i = 0; i < m; ++i) {
        int p;
        std::cin >> p;
        auto [sx, sy] = enc(--p);
        ans += dist[sx][sy];

        std::queue<std::pair<int, int>> que;
        erased[sx][sy] = true;
        que.emplace(sx, sy);

        while (!que.empty()) {
            auto [x, y] = que.front();
            que.pop();

            int cost = (erased[x][y] ? 0 : 1);

            for (int j = 0; j < 4; ++j) {
                int nx = x + dx[j],
                    ny = y + dy[j];

                if (nx < 0 || n <= nx ||
                    ny < 0 || n <= ny ||
                    dist[nx][ny] != dist[x][y] + cost + 1) continue;

                dist[nx][ny] = dist[x][y] + cost;
                que.emplace(nx, ny);
            }
        }
    }

    std::cout << ans << "\n";
}

int main() {
    std::cin.tie(nullptr);
    std::ios::sync_with_stdio(false);

    solve();

    return 0;
}

