void SPFA(){
  while(!Q.empty()){
    pii u = Q.front();
    Q.pop();
    for(int i = 0; i < 4; i++){
      int x = u.fs + dx[i];
      int y = u.se + dy[i];
      if(isValid(x, y) && dist[x][y] > dist[u.fs][u.se] + !out[x][y]){
        dist[x][y] = dist[u.fs][u.se] + !out[x][y];
        Q.push(mp(x, y));
      }
    }
  }
}

