bool present[MAX_N][MAX_N];
void decrease(int i, int j, int N){
	for(int z = i,notPresent = 0; z >= 1; z--){		
		dist[z][j] = min(dist[z][j], notPresent + dist[i][j]);		
		notPresent += present[z][j];
	}

	for(int z = i, notPresent = 0; z <= N; z++){		
		dist[z][j] = min(dist[z][j], notPresent + dist[i][j]);
		notPresent += present[z][j];
	}

	for(int z = j, notPresent = 0; z <= N; z++){		
		dist[i][z] = min(dist[i][z], notPresent + dist[i][j]);		
		notPresent += present[i][z];
	}

	for(int z = j, notPresent = 0; z >= 1; z--){		
		dist[i][z] = min(dist[i][z], notPresent + dist[i][j]);
		notPresent += present[i][z];
	}
}

