int d[N][N],p[N],n,g[N][N];
const int C[4][2] = {{1,0},{0,1},{-1,0},{0,-1}};
void get(int &x,int &y,int num) {
    x = (num-1)/n+1;
    y = (num-1)%n+1;
}
int ok(int x) {return x > 0 && x <= n;}

void update(int x,int y) {
    for(int i = 0 ; i < 4 ; ++i) {
        int dx = x+C[i][0],dy = y+C[i][1];
        if(ok(dx)&&ok(dy) && d[dx][dy]>d[x][y]+g[x][y]) {
            d[dx][dy] = d[x][y]+g[x][y];
            update(dx,dy);
        }
    }
}

int getans(int x,int y) {
    int mn = N;
    for(int i = 0 ; i < 4 ; ++i) {
        int dx = x+C[i][0],dy = y+C[i][1];
        if(ok(dx) && ok(dy))
            cmin(mn,d[dx][dy]);
    }
    return mn;
}

void mdf(int x,int y) {
    update(x,y);
}

