void solve() {
    cin >> n;
    LL ans = 0;
    for(int i = 1 ; i <= n ; ++i)
        for(int j = 1 ; j <= n ; ++j) {
            d[i][j] = min(min(n - i, n - j), min(i - 1, j - 1));
            g[i][j] = 1;
        }
    for(int i = 1 ; i <= n*n ; ++i) {
        //show();

        int tmp;
        cin >> tmp;
        int x,y;
        get(x,y,tmp);
        ans += d[x][y];
        g[x][y] = 0;
        mdf(x,y);

        //show();

    }
    cout << ans << endl;
}

