		ll j=(P[t]-1)%N;
		ans+=dist[i][j];
		mp[i][j]=0;

		deque<pll> que;
		que.emplace_back(i, j);
		while (!que.empty()){
			ll ii; ll jj;  tie(ii, jj) = que.front(); que.pop_front();

			rep(didx, 0, 3){
				ll iii=ii+di[didx];
				ll jjj=jj+dj[didx];
