        //縦
        if(i&&(!seat.at(i-1).at(j)&&!seat.at(i).at(j))) {
          uf.stick((i-1)*S+j,i*S+j);
        }

        //横
        if(j&&(!seat.at(i).at(j-1)&&!seat.at(i).at(j))) {
          uf.stick(i*S+j-1,i*S+j);
        }


      }
    }






    ufind M(uf.uf);
