    int cucu=sy*S+sx;




    while(true){

      for(int i=0;i<S;i++){
        for(int j=0;j<S;j++){


          //縦

          if(i&&(!Mseat.at(i-1).at(j)&&!Mseat.at(i).at(j))) {
            M.stick((i-1)*S+j,i*S+j);
           }



