inline int nxt() {
	int x;
	scanf("%d", &x);
	return x;
}

const int N = 505;
int d[N][N];
char used[N][N];

const int xx[4] = {-1, 0, 1, 0};
const int yy[4] = {0, -1, 0, 1};

int n;
void relax(int x, int y) {
	for (int t = 0; t < 4; ++t) {
		int nx = x + xx[t], ny = y + yy[t];
		if (nx < 0 || nx >= n || ny < 0 || ny >= n) {
			continue;
		}
		if (d[nx][ny] > d[x][y] + used[nx][ny]) {
			d[nx][ny] = d[x][y] + used[nx][ny];
			relax(nx, ny);
		}
	}
}

int main() {
	n = nxt();
	for (int i = 0; i < n; ++i) {
		for (int j = 0; j < n; ++j) {
			d[i][j] = min({i + 1, n - i, j + 1, n - j});
			used[i][j] = 1;
		}
	}
	int ans = 0;
	for (int i = 0; i < n * n; ++i) {
		int pos = nxt() - 1;
		int x = pos / n, y = pos % n;
		used[x][y] = false;
		--d[x][y];
		relax(x, y);
		ans += d[x][y];
		// for (int x = 0; x < n; ++x) {
		// 	for (int y = 0; y < n; ++y) {
		// 		cerr << d[x][y] << " ";
		// 	}
		// 	cerr << "\n";
		// }
		// cerr << "\n";
	}
	cout << ans << "\n";

	return 0;
}

