void recalc_seat_cost(vector<vector<ll>>& seat_cost,vector<vector<bool>>& is_occupied, ll x, ll y){
    // assign seat_cost at (x,y) to the lowest cost of 4 neighbors
    const ll dx[] = {1,0,-1,0};
    const ll dy[] = {0,1,0,-1};
    ll cost = seat_cost[x][y];
    if(is_occupied[x][y]){
        for(int i=0; i<4; i++){
            if(cost+1 < seat_cost[x+dx[i]][y+dy[i]]){
                seat_cost[x+dx[i]][y+dy[i]] = cost+1;
                recalc_seat_cost(seat_cost, is_occupied, x+dx[i], y+dy[i]);
            }
        }
    }else{
        for(int i=0; i<4; i++){
            if(cost < seat_cost[x+dx[i]][y+dy[i]]){
                seat_cost[x+dx[i]][y+dy[i]] = cost;
                recalc_seat_cost(seat_cost, is_occupied, x+dx[i], y+dy[i]);
            }
        }
    }
}

int main(){
    ll n;
    cin >> n;
    vector<ll> p(n*n);
    for(int i=0; i<n*n; i++){
        cin >> p[i];
    }

    vector<vector<ll>> seat_cost(n+2,vector<ll>(n+2,0));
    vector<vector<bool>> is_occupied(n+2,vector<bool>(n+2,true));

    for(ll i=1; i<=(n+1)/2; i++){
        for(ll m=1; m<=(n+1)/2; m++){
            seat_cost[i][m]         = std::min(i-1,m-1);
            seat_cost[n-i+1][m]     = std::min(i-1,m-1);
            seat_cost[i][n-m+1]     = std::min(i-1,m-1);
            seat_cost[n-i+1][n-m+1] = std::min(i-1,m-1);

        }
    }
    for(int i=0; i<n+2; i++){
        is_occupied[i][0] = false;
        is_occupied[0][i] = false;
        is_occupied[i][n] = false;
        is_occupied[n][i] = false;
    }

    ll ans = 0;
    for(int i=0; i<n*n; i++){
        ll myself = p[i];
        ll myX = (myself-1) % n + 1;
        ll myY = (myself-1) / n + 1;

        ans += seat_cost[myX][myY];
        is_occupied[myX][myY] = false;

        // search for lowest costly route to outside
        recalc_seat_cost(seat_cost, is_occupied, myX, myY);
    }

    cout << ans << endl;

    return 0;
}

