int N;P watcher[250005]; int mass[505][505];
int dx[4] = { 1,-1,0,0 },dy[4]={0,0,1,-1};
int dist[505][505];
struct trans
{
	int x, y, cost;
	trans(int x, int y, int cost) :x(x), y(y), cost(cost) {}
	friend bool operator< (const trans& a, const trans& b) {
		return a.cost < b.cost;
	}
	friend bool operator> (const trans& a, const trans& b) {
		return a.cost > b.cost;
	}

};
int bfs(int x,int y) {
	rep(i, N)fill(dist[i], dist[i] + N, INF);
	priority_queue<trans, vector<trans>, greater<trans>>que;
	dist[x][y] = 0;
	que.push(trans(x, y, 0)); int res = INF;
	if (x == 0 || y == 0 || x == N - 1 || y == N - 1) {

		chmin(res, 0);
		return res;
	}
	while (!que.empty())
	{
		trans e = que.top(); que.pop();
		if (dist[e.x][e.y] < e.cost)continue;
		rep(i, 4) {
			int sx = e.x + dx[i], sy = e.y + dy[i];
			if (sx >= 0 && sx < N && sy >= 0&&sy < N) {
				if (mass[sx][sy] == 2) {
					mass[sx][sy] = 2;
					chmin(res, dist[e.x][e.y]);
					if (res == 0) {
						mass[x][y] = 2;
						return res;
					}
				}else if (dist[sx][sy] > dist[e.x][e.y] + mass[sx][sy]) {
					dist[sx][sy] = dist[e.x][e.y] + mass[sx][sy];
					que.push(trans(sx, sy, dist[sx][sy]));
					if (sx == 0 || sy == 0 || sx == N - 1 || sy == N - 1) {
						chmin(res, dist[sx][sy]);
						if (res == 0) {
							mass[x][y] = 2;
							return res;
						}
					}
				}
			}
		}

	}
	return res;

}
int32_t main() {
	cin >> N;
	rep(i, N*N) {
		int p;
		cin >> p;
		p--;
		watcher[i] = P(p/N, p%N);
	}
	ll ans = 0;
	rep(i, N)fill(mass[i], mass[i] + N, 1);
	rep(i, N*N) {
		P p = watcher[i];
		mass[p.first][p.second] = 0;

		ans += bfs(p.first, p.second);
	}
	cout << ans << endl;
}

