int main() {
    int n; std::cin >> n;
    std::vector<std::vector<int>>
        d(n, std::vector<int>(n)),
        b(n, std::vector<int>(n, 1));
    std::vector<std::pair<int, int>> t(n*n);
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            int k; std::cin >> k;
            k--;
            t[i*n + j] = { k/n, k%n };
            d[i][j] = std::min({i, j, n - 1 - i, n - 1 - j});
        }
    }
    int ans = 0;
    std::deque<std::pair<int, int>> que;
    std::vector<int> dd = { 1, 0, -1, 0, 1 };
    for (const auto &p : t) {
        ans += d[p.first][p.second];
        d[p.first][p.second]--;
        b[p.first][p.second] = 0;
        que.emplace_back(p);
        while (!que.empty()) {
            auto q = que.front();
            que.pop_front();
            for (int i = 0; i < 4; i++) {
                int u = q.first + dd[i];
                int v = q.second + dd[i + 1];
                if (!(0 <= u && u < n)) continue;
                if (!(0 <= v && v < n)) continue;
                if (d[u][v] <= d[q.first][q.second] + b[u][v])
                    continue;
                d[u][v] = d[q.first][q.second] + b[u][v];
                que.emplace_back(u, v);
            }
        }
    }
    std::cout << ans << std::endl;
    return 0;
}

