// 四方向への移動ベクトル
const int dx[4] = {1, 0, -1, 0};
const int dy[4] = {0, 1, 0, -1};


int main(){
  int n;
  cin >> n;

  if(n==2) {
    cout << 0 << endl;
    return 0;
  }

  int ans=0;

  vector<vector<bool>> p(n,vector<bool>(n,true));
  vector<vector<int>> dist(n,vector<int>(n)); // 全マスを「未訪問」に初期化
  deque<pair<int,int>> que;

  rep(i,n*n) {
    int x;
    scanf( "%d", &x );
    int a =(x-1)/n;
    int b =(x-1)%n;
    p[a][b]=false;
    if(a==0||a==n-1||b==0||b==n-1)continue;

    rep(i,n){
      rep(j,n){
        dist[i][j]=-1;
      }
    }
    dist[a][b]=0;
    pair<int,int> q=mp(a,b);
    que.pb(q);


    // BFS 開始 (キューが空になるまで探索を行う)
    while (!que.empty()) {
        pair<int,int> v = que.front(); // キューから先頭頂点を取り出す
        que.pop_front();
        //vの上下左右をすべて調べる
        rep(j,4) {
          int nh = v.fi + dx[j];
          int nw = v.se + dy[j];

          // 場外アウトしたり、移動先が壁の場合はスルー
          if (nh < 0 || nh >= n || nw < 0 || nw >= n) continue;          
          if (dist[nh][nw] != -1) continue; // すでに発見済みのマスは探索しない

          // 新たなマスについて距離情報を更新してキューに追加する
          if(p[nh][nw]){
          dist[nh][nw] = dist[v.fi][v.se] + 1;
          pair<int,int> r=mp(nh,nw);
          que.pb(r);
          }
          else {
          dist[nh][nw] = dist[v.fi][v.se];
          pair<int,int> r=mp(nh,nw);
          que.push_front(r);            
          }
        }
    }
    int sho=1000000;
    rep(j,n){
      sho=min(sho,dist[0][j]);
      if(sho==0) break;
      sho=min(sho,dist[n-1][j]);
      if(sho==0) break;
      sho=min(sho,dist[j][0]);
      if(sho==0) break;
      sho=min(sho,dist[j][n-1]);  
      if(sho==0) break;  
    }
    ans+=sho;
  }


  cout << ans << endl;       
}

