using namespace std;
#define ll long long
const int INF = 0x3f3f3f3f;
const ll inf = 0x3f3f3f3f3f3f3f3f;
const int N = 3e5 + 10;
int n;
typedef pair<int, int>pii;
pii id(int x) {
	return pii((x - 1) / n + 1, (x - 1) % n + 1);
}
int dx[]{ 0,0,-1,1 };
int dy[]{ -1,1,0,0 };
int d[510][510], gg[510][510];
bool ilg(int x, int y) {
	return x<1 || y<1 || x>n || y>n;
}
void bfs(pii p) {
	queue<pii>q;
	q.push(p);
	while (!q.empty()) {
		int x = q.front().first, y = q.front().second; q.pop();
		for (int i = 0; i < 4; i++) {
			int nx = x + dx[i], ny = y + dy[i];
			if (ilg(nx, ny) || d[nx][ny] <= d[x][y] + gg[x][y])continue;
			d[nx][ny] = d[x][y] + gg[x][y];
			q.push(pii(nx, ny));
		}
	}
}
int main() {
	scanf("%d", &n);
	int ans = 0;
	for (int i = 1; i <= n; i++)
		for (int j = 1; j <= n; j++)
			d[i][j] = min(min(n - i, n - j), min(i - 1, j - 1)), gg[i][j] = 1;
	for (int i = 0; i < n*n; i++) {
		int x, y;
		scanf("%d", &x);
		pii p = id(x);
		x = p.first, y = p.second;
		int tmp = INF;
		for (int j = 0; j < 4; j++) {
			int nx = x + dx[j], ny = y + dy[j];
			tmp = min(tmp, d[nx][ny] + gg[nx][ny]);
		}
		ans += tmp;
		d[x][y] = tmp;
		gg[x][y] = 0;
		bfs(p);
	}
	printf("%d\n", ans);
	return 0;
}

