        update(row,1,1,n,col);
        update(col+n,1,1,n,row);
        ans += min({query(row,1,1,n,1,col),query(row,1,1,n,col,n),query(col+n,1,1,n,row,n),query(col+n,1,1,n,row,n)});
    }
    cout << ans <<endl;
    return 0;
}

