struct node{
    int y, x, cost;
};

int main(){
    cin.tie(nullptr);
    ios::sync_with_stdio(false);
    cout << fixed << setprecision(10);

    int n;
    cin >> n;

    vector<int> ps(n * n);
    rep(i, n * n){
        cin >> ps[i];
        --ps[i];
    }

    vector< vector<int> > cost(n, vector<int>(n, IINF));
    deque<node> que;
    rep(i, n){
        cost[0][i] = 0;
        que.push_back({0, i, 0});
        cost[i][0] = 0;
        que.push_back({i, 0, 0});
        cost[n - 1][i] = 0;
        que.push_back({n - 1, i, 0});
        cost[i][n - 1] = 0;
        que.push_back({i, n - 1, 0});
    }

    auto inside = [&](int y, int x){
        return 0 <= y && y < n && 0 <= x && x < n;
    };

    while(!que.empty()){
        node now = que.front();
        que.pop_front();

        if(cost[now.y][now.x] < now.cost){
            continue;
        }

        rep(i, 4){
            int ny = now.y + dy4[i];
            int nx = now.x + dx4[i];
            if(inside(ny, nx) && chmin(cost[ny][nx], now.cost + 1)){
                que.push_back({ny, nx, now.cost + 1});
            }
        }
    }

    int ans = 0;
    vector< vector<bool> > iru(n, vector<bool>(n, true));

    for(auto p : ps){
        int y = p / n;
        int x = p % n;

        ans += cost[y][x];

        iru[y][x] = false;

        que.push_back({y, x, cost[y][x]});

        while(!que.empty()){
            node now = que.front();
            que.pop_front();

            if(cost[now.y][now.x] < now.cost){
                continue;
            }

            rep(i, 4){
                int ny = now.y + dy4[i];
                int nx = now.x + dx4[i];

                if(!inside(ny, nx)){
                    continue;
                }

                int nc = now.cost + iru[now.y][now.x];
                if(nc == now.cost && chmin(cost[ny][nx], nc)){
                    que.push_front({ny, nx, nc});
                }
                if(nc != now.cost && chmin(cost[ny][nx], nc)){
                    que.push_back({ny, nx, nc});
                }
            }
        }
    }

    cout << ans << endl;

    cout << flush;

    return 0;
}

