int main()
{

	int a;
	scanf("%d",&a);
	for(int i=1;i<=a*a;i++) scanf("%d",&x[i]);
	for(int i=1;i<=a;i++)
	{
		for(int j=1;j<=a;j++)
		{
			int s1 = (i-1)<(a-i)?(i-1):(a-i);
			int s2 = (j-1)<(a-j)?(j-1):(a-j);
			check[i][j] = s1<s2?s1:s2;
			check2[i][j] = 1;
		}
	}

	long long int sum = 0;
	for(int i=1;i<=a*a;i++)
	{
		int s = (x[i]-1)/a+1;
		int t = (x[i]-1)%a+1;
		check2[s][t] = 0;
		sum += check[s][t];

		for(int j=0;j<4;j++) Q.push({s+direX[j],t+direY[j],check[s][t]});
		while(!Q.empty())
		{
			int x0 = Q.top().x0;
			int y0 = Q.top().y0;
			int dist = Q.top().dist;
			Q.pop();
