struct LazySegmentTree {//遅延評価セグメント木
private:
    int n;
    vector<ll> node, lazy;

public:
    LazySegmentTree(vector<ll> v) {
        int sz = (int)v.size();
        n = 1; while(n < sz) n *= 2;
        node.resize(2*n-1);
        lazy.resize(2*n-1, 0);

        for(int i=0; i<sz; i++) node[i+n-1] = v[i];
        for(int i=n-2; i>=0; i--) node[i] = node[i*2+1] + node[i*2+2];
    }

    void eval(int k, int l, int r) {
        if(lazy[k] != 0) {
            node[k] += lazy[k];
            if(r - l > 1) {
                lazy[2*k+1] += lazy[k] / 2;
                lazy[2*k+2] += lazy[k] / 2;
            }
            lazy[k] = 0;
        }
    }

    void add(int a, int b, ll x, int k=0, int l=0, int r=-1) {
        if(r < 0) r = n;
        eval(k, l, r);
        if(b <= l || r <= a) return;
        if(a <= l && r <= b) {
            lazy[k] += (r - l) * x;
            eval(k, l, r);
        }
        else {
            add(a, b, x, 2*k+1, l, (l+r)/2);
            add(a, b, x, 2*k+2, (l+r)/2, r);
            node[k] = node[2*k+1] + node[2*k+2];
        }
    }

    ll getsum(int a, int b, int k=0, int l=0, int r=-1) {
        if(r < 0) r = n;
        eval(k, l, r);
        if(b <= l || r <= a) return 0;
        if(a <= l && r <= b) return node[k];
        ll vl = getsum(a, b, 2*k+1, l, (l+r)/2);
        ll vr = getsum(a, b, 2*k+2, (l+r)/2, r);
        return vl + vr;
    }
};
int main(){
    int n;
    std::cin >> n;
    VEC(int,p,n*n);
    std::vector<LazySegmentTree> yo(n,LazySegmentTree(std::vector<ll> (n,1)));
    std::vector<LazySegmentTree> ta(n,LazySegmentTree(std::vector<ll> (n,1)));
    ll ans=0;
    rep(i,n*n){
        p[i]--;
        ll x=p[i]%n;
        ll y=p[i]/n;
        ll dum=INF;
        yo[y].add(x,x+1,-1);
        ta[x].add(y,y+1,-1);
        chmin(dum,yo[y].getsum(0ll,x));
        chmin(dum,yo[y].getsum(x,n));
        chmin(dum,ta[x].getsum(0ll,y));
        chmin(dum,ta[x].getsum(y,n));
        ans+=dum;
    }
    std::cout <<ans << std::endl;
}

