					seat[d][e] = seat[a][b] + aitenai[d][e];
					q.push({d, e});
				}
			}
			if(b != n - 1) {
				ll d = a, e = b + 1;
				if(-aitenai[d][e] + seat[d][e] > seat[a][b]) {
					seat[d][e] = seat[a][b] + aitenai[d][e];
					q.push({d, e});
				}
			}
		}
	}
	cout << res << endl;
