#define REP(i, n) for (int i = 0; i < n; i++)
#define ALL(v) v.begin(), v.end()

int dx[4] = { 1,0,-1,0 }, dy[4] = { 0,1,0,-1 };

int main(){
	int n; cin >> n;
	VI p(n*n);
	REP(i,n*n) cin >> p[i];
	vector<vector<bool>> f(n,vector<bool>(n,1));
	int ans=0;
	REP(i,n*n){
		p[i]--;
		int sx=p[i]%n, sy=p[i]/n;
		bool ok=0;
		f[sx][sy]=0;
		priority_queue<pair<int,P>> q;
		q.push({0,{sx,sy}});
		VVI d(n,VI(n,INF)); d[sx][sy]=0;
		while(!q.empty()){
			int c=-q.top().first;
			int x=q.top().second.first;
			int y=q.top().second.second;
			q.pop();
			if(c>d[x][y])
				continue;
			REP(j,4){
				int tox=x+dx[j], toy=y+dy[j];
				if(tox>=0&&tox<n&&toy>=0&&toy<n){
					if(c+f[tox][toy]<d[tox][toy]){
						d[tox][toy]=c+f[tox][toy];
						q.push({-(c+f[tox][toy]),{tox,toy}});
					}
				}
				else{
					ok=1;
					ans+=c;
					break;
				}
			}
			if(ok)
				break;
		}
	}
	cout << ans << endl;
	return 0;
}

