int main(){
  using namespace std;
  int n;
  cin>>n;
  int p[n * n];
  REP(i, n * n) {
    cin>>p[i];
    p[i]--;
  }
  auto valid = [&n](int i, int j) -> bool {
    return 0 <= i && i < n && 0 <= j && j < n;
  };
  auto conv = [&n](int i, int j) -> int {
    return n * i + j;
  };
  int dist[n][n];
  REP(i, n){
    REP(j, n){
      int x = min(i, n - 1 - i);
      int y = min(j, n - 1 - j);
      dist[i][j] = min(x, y);
    }
  }
  bool exists[n][n];
  REP(i, n) REP(j, n) exists[i][j] = true;
  int ans = 0;
  typedef pair<int, pair<int, int>> P;
  int dx[] = {1, 0, -1, 0};
  int dy[] = {0, 1, 0, -1};
  REP(num, n * n){
    int i = num / n;
    int j = num % n;
    exists[i][j] = false;
    ans += dist[i][j];
    priority_queue<P> q;
    q.push(P(-dist[i][j], make_pair(i, j)));
    while(!q.empty()){
      P p = q.top();
      q.pop();
      int x = p.second.first, y = p.second.second;
      REP(k, 4){
        int nx = x + dx[k], ny = y + dy[k];
        if(!valid(nx, ny)) continue;
        if(exists[x][y]){
          if(dist[x][y] + 1 < dist[nx][ny]){
            dist[nx][ny] = dist[x][y] + 1;
            q.push(P(-dist[nx][ny], make_pair(nx, ny)));
          }
        }else{
          if(dist[x][y] < dist[nx][ny]){
            dist[nx][ny] = dist[x][y];
            q.push(P(-dist[nx][ny], make_pair(nx, ny)));
          }
        }
      }
    }
  }
  cout << ans << endl;   
  return 0;
}

