std::queue<int> q;
void push(int u, int v) {
    if(d[u] <= v)
        return;
    d[u] = v;
    q.push(u);
}
void bfs(int s) {
    r[s] = 1;
    q.push(s);
    while(!q.empty()) {
        int u = q.front();
        q.pop();
        for(int j = 0; j < 4; ++j) {
            int x = (u - 1) / n, y = (u - 1) % n;
            x += dxy[j][0];
            y += dxy[j][1];
            if(x < 0 || x >= n || y < 0 || y >= n)
                continue;
            int v = x * n + y + 1;
            int w = d[u] + (!r[u]);
            push(v, w);
        }
    }
}

