    int val;
    init();
    int k = 1;
    FOR1(i,n){
        FOR1(j,n){
            cin>>val;
            mp[val] = {i,j};
            a[k]=val;
            k++;
        }
    }
    cout<< solve()<<endl;
    return 0;
}

