  for(int i=0;i<N;i++){
    for(int j=0;j<N;j++){
      dist.at(i).at(j)=min({i,j,N-1-i,N-1-j});
    }
  }

  ll ans=0;
  vector<vector<bool>> leave(N,vector<bool>(N,false));
  for(int k=0;k<N*N;k++){
    int i=P.at(k)/N;
