        int nx=x+dx[l];
        int ny=y+dy[l];
        if(nx<0||ny<0||nx>=N||ny>=N){
          continue;
        }
        if(leave.at(x).at(y)){
          if(dist.at(nx).at(ny)>dist.at(x).at(y)){
            dist.at(nx).at(ny)=dist.at(x).at(y);
            q.push(make_pair(nx,ny));
          }
