int N;
vector<vector<int>> vv(500, vector<int>(500));

int bfs(int p) {

	vv.at(p/N).at(p%N) = 0;
	if (p/N == 0 || p/N == N-1 || p%N == 0 || p%N == N-1) {
		return 0;
	}

	vector<vector<int>> vt(N, vector<int>(N));
	rep(i, N) {
		rep(j, N) {
			vt.at(i).at(j) = 500;
		}
	}

	queue<int> Q;
	Q.push(p);
	vt.at(p/N).at(p%N) = 1;

	int r = 250;
	bool f;
	while (!Q.empty()) {
		int t = Q.front();
		Q.pop();
		int c = vt.at(t/N).at(t%N);
		// top
		if (t/N > 0) {
			f = chmin(vt.at(t/N-1).at(t%N), c+vv.at(t/N-1).at(t%N));
			if (f){
				if (t/N-1 == 0) {
					chmin(r, vt.at(t/N-1).at(t%N));
					if (r == 1) break;
				}
				else Q.push(t-N);
			}
		}
		// bottom
		if (t/N < N-1) {
			f = chmin(vt.at(t/N+1).at(t%N), c+vv.at(t/N+1).at(t%N));
			if (f){
				if (t/N+1 == N) {
					chmin(r, vt.at(t/N+1).at(t%N));
					if (r == 1) break;
				}
				else Q.push(t+N);
			}
		}
		// left
		if (t%N > 0) {
			f = chmin(vt.at(t/N).at(t%N-1), c+vv.at(t/N).at(t%N-1));
			if (f){
				if (t%N-1 == 0) {
					chmin(r, vt.at(t/N).at(t%N-1));
					if (r == 1) break;
				}
				else Q.push(t-1);
			}
		}
		// right
		if (t%N < N-1) {
			f = chmin(vt.at(t/N).at(t%N+1), c+vv.at(t/N).at(t%N+1));
			if (f){
				if (t%N+1 == N) {
					chmin(r, vt.at(t/N).at(t%N+1));
					if (r == 1) break;
				}
				else Q.push(t+1);
			}
		}
	}
	return r-1;
}

