#define MAXN 550
int t[MAXN][MAXN];
int cost[MAXN][MAXN];
int cost2[MAXN][MAXN];
int N;
void bfs(int v0, int v1, int id) {
  queue<pint> q;
  q.push(mp(v0, v1));
  while (!q.empty()) {
    pint ele = q.front();
    int ret = t[ele.fst][ele.snd];
    int c0 = cost[ele.fst][ele.snd];
    q.pop();
    REP(i, 4) {
      pint next = mp(ele.fst + dx[i], ele.snd + dy[i]);
      if (0 <= next.fst && next.fst < N && 0 <= next.snd && next.snd < N) {
        int val = t[next.fst][next.snd];
        int c1 = cost[next.fst][next.snd];
        if (ret <= id && val <= id) {
          if (c0 > c1) {
            cost[ele.fst][ele.snd] = c1;
            q.push(mp(ele.fst, ele.snd));
          } else if (c1 > c0) {
            cost[next.fst][next.snd] = c0;
            q.push(mp(next.fst, next.snd));
          }
        } else {
          if (c0 > c1 + 1) {
            cost[ele.fst][ele.snd] = c1 + 1;
            q.push(mp(ele.fst, ele.snd));
          } else if (c1 > c0 + 1) {
            cost[next.fst][next.snd] = c0 + 1;
            q.push(mp(next.fst, next.snd));
          }
        }
      }
    }
  }
}
