    p--;
    t[p / N][p % N] = i;
    lis.pb(mp(p / N, p % N));
  }
  REP(i, N2) {
    int i0 = i / N;
    int i1 = i % N;
    cost[i0][i1] = min({i0, i1, N - 1 - i0, N - 1 - i1});
  }
  int ans = 0;

  REP(i, N2) {
    pint ele = lis[i];
    int v0 = ele.fst;
    int v1 = ele.snd;

    bfs(v0, v1, i);
    ans += cost[v0][v1];
  }

  print(ans);
}

