const int di[] = { 0, 1, 0, -1 };
const int dj[] = { 1, 0, -1, 0 };
void rec(int i, int j) {
	REP(k, 0, 4) {
		int ni = i + di[k];
		int nj = j + dj[k];
		if (!Inside(ni, nj, N, N)) return;

		int nd = used[i][j] ? dist[i][j] : dist[i][j] + 1;
		if (dist[ni][nj] > nd) {
			dist[ni][nj] = nd;
			rec(ni, nj);
		}
	}
}

int sub(int i, int j) {
	int ret = dist[i][j];
	used[i][j] = true;
	rec(i, j);
	return ret;
}

