constexpr int DEBUG = 0;

template<typename T>
vector<vector<T>> MakeVector2D(int d1, int d2, T default_value) {
  return vector<vector<T>>(d1, vector<T>(d2, default_value));
}

int main() {
  ios::sync_with_stdio(false);
  cin.tie(0);

  int n;
  cin >> n;
  vector<Int2D> ps(n * n);
  for (int i = 0; i < n * n; i++) {
    int p;
    cin >> p;
    p--;
    int r = p / n;
    int c = p % n;
    ps[i] = {r, c};
  }

  vector<vector<int>> is_filled_m = MakeVector2D(n, n, 1);
  vector<vector<int>> cost_m = MakeVector2D(n, n, -1);
  for (int r = 0; r < n; r++) {
    for (int c = 0; c < n; c++) {
      int min_r = min(r, n - 1 - r);
      int min_c = min(c, n - 1 - c);
      cost_m[r][c] = min(min_r, min_c);
    }
  }

  int ans = 0;
  for (const auto& [r, c] : ps) {
    ans += cost_m[r][c];

    is_filled_m[r][c] = 0;
    stack<Int2D> stack({{r, c}});
    while (!stack.empty()) {
      const auto [sr, sc] = stack.top();
      stack.pop();
      for (const auto& [dr, dc] : vector<Int2D>({{1, 0}, {0, 1}, {-1, 0}, {0, -1}})) {
        int nr = sr + dr;
        int nc = sc + dc;
        if (nr < 0 || nr >= n || nc < 0 || nc >= n) continue;
        if (cost_m[nr][nc] > cost_m[sr][sc] + is_filled_m[sr][sc]) {
          cost_m[nr][nc] = cost_m[sr][sc] + is_filled_m[sr][sc];
          stack.push({nr, nc});
        }
      }
    }
  }
  cout << ans << endl;
}

