const int DIRS = 4;
const int DR[DIRS] = {-1,  0, +1,  0};
const int DC[DIRS] = { 0, +1,  0, -1};

int N;
vector<vector<int>> dist;
vector<vector<bool>> remaining;

bool valid(int r, int c) {
    return 0 <= r && r < N && 0 <= c && c < N;
}

void propagate(int row, int col, int new_dist) {
    assert(new_dist < dist[row][col]);
    dist[row][col] = new_dist;

    for (int dir = 0; dir < DIRS; dir++) {
        int nr = row + DR[dir];
        int nc = col + DC[dir];

        if (valid(nr, nc) && new_dist + remaining[nr][nc] < dist[nr][nc])
            propagate(nr, nc, new_dist + remaining[nr][nc]);
    }
}

void propagate_bfs(int row, int col) {
    queue<array<int, 3>> q;

    auto &&bfs_check = [&](int r, int c, int new_dist) {
        if (new_dist < dist[r][c]) {
            dist[r][c] = new_dist;
            q.push({r, c, new_dist});
        }
    };

    bfs_check(row, col, dist[row][col] - 1);

    while (!q.empty()) {
        array<int, 3> top = q.front(); q.pop();

        for (int dir = 0; dir < DIRS; dir++) {
            int nr = top[0] + DR[dir];
            int nc = top[1] + DC[dir];

            if (valid(nr, nc))
                bfs_check(nr, nc, top[2] + remaining[nr][nc]);
        }
    }
}

void decrement(int row, int col) {
    remaining[row][col] = false;
    // propagate(row, col, dist[row][col] - 1);
    propagate_bfs(row, col);
}

int main() {
    ios::sync_with_stdio(false);
#ifndef NEAL_DEBUG
    cin.tie(nullptr);
#endif

    cin >> N;
    dist.assign(N, vector<int>(N));
    remaining.assign(N, vector<bool>(N, true));

    for (int i = 0; i < N; i++)
        for (int j = 0; j < N; j++)
            dist[i][j] = min({i, N - 1 - i, j, N - 1 - j});

    int total = 0;

    for (int i = 0; i < N * N; i++) {
        int p;
        cin >> p;
        p--;
        int row = p / N, col = p % N;
        total += dist[row][col];

        if (dist[row][col] > 0)
            dbg(row, col, dist[row][col]);

        decrement(row, col);
    }

    cout << total << '\n';
}

