using ll=long long;
using P =pair<ll,ll>;
const ll INF =ll(1e18)+5;

ll N;

bool onBoard(int y,int x){
    if(y>=0&&y<N&&x>=0&&x<N){
        return true;
    }
    return false;
}

int main() {
    cin >> N;
    vector<vector<ll>> num(N);
    for(int i=0;i<N;i++){
        for(int j=0;j<N;j++){
            int val1 = min(i+1,j+1);
            int val2 = min(N-i,N-j);
            num[i].push_back(min(val1,val2));
        }
    }
    int dx[]= {0,1,0,-1};
    int dy[] = {1,0,-1,0};
    ll ans =0;
    map<P,int> mp;
    for(int q=0;q<N*N;q++){
        int inP;
        cin >> inP;
        --inP;
        int y = inP/N;
        int x = inP%N;
        mp[P(y,x)]++;
        // cerr <<"P="<<inP<<"y=" <<y <<"x=" <<x <<endl;
        ll temp = INF;
        for(int i=0;i<4;i++){
            int ny = y+ dy[i];
            int nx = x +dx[i];
            if(!onBoard(ny,nx)){
                temp =0;
                break;
            }
            temp = min(temp,num[ny][nx]);

        }
        //  cerr <<"temp=" <<temp <<endl;
        num[y][x] = temp;
        ans += temp;
        //更新
        priority_queue<P,vector<P>,greater<P>> pq;
        pq.push(P(temp,y*N+x));
        while(!pq.empty()){
            P p = pq.top();
            ll d = p.first;
            int py =p.second/N;
            int px = p.second%N;
            // cerr <<"py="<< py <<"px=" <<px << endl;
            pq.pop();
            if(num[py][px] < d){
                continue;
            }
            for(int i=0;i<4;i++){
                int ny = py + dy[i];
                int nx = px + dx[i];
                if(!onBoard(ny,nx)){
                    continue;
                }
                if(mp.find(P(ny,nx)) == mp.end()){
                    continue;
                }
                if(num[ny][nx] > num[py][px]){
                    num[ny][nx] = num[py][px];
                    pq.push(P(num[ny][nx],ny*N+nx));
                }
            }
        }


    }
    cout << ans << endl;
    return 0;
}

