struct UnionFind{
    vector<int> nxt;
    vector<int> numm;
    void init(int x){
        nxt.clear();
        numm.assign(x, 1);
        nxt.resize(x);
        for (int i = 0; i < x;i++){
            nxt[i] = i;
        }
    }
    int find(int x){
        if(nxt[x]==x)
            return x;
        return nxt[x] =find(nxt[x]);
    }
    int size(int x){
        return numm[x];
    }
    inline void unite(int x,int y){
        if(x==y)
            return;
        numm[find(x)] += numm[find(y)];
        nxt[find(y)] = find(x);
    }
};

ll  N, P[1000*1000];
UnionFind uf;

ll mk[1000 * 1000];
ll mk2[1000 * 1000];
ll g[8];
ll i, j, k;
int main(){
    scanf("%lld", &N);
    fornum(i,0,N*N){
        scanf("%lld", &P[i]);
        P[i]--;
    }
    fornum(i,0,N){
        fornum(j,0,N){
            mk[i * N + j] = min(min(i, N - i - 1), min(j, N - j - 1));
        }
    }
    g[0] = 1;
    g[1] = N;
    g[2] = -1;
    g[3] = -N;
    uf.init(N * N + 5);
    ll ans = 0;
    fornum(i,0,N*N){
        //printf("%lld ", P[i]);
        fornum(j,0,4){
            ll nx = P[i] + g[j];
            if(nx<0||N*N<=nx||(P[i]%N!=nx%N&&P[i]/N!=nx/N))
                continue;
            if(!mk2[nx])
                continue;
            mk[uf.find(P[i])] = min(mk[uf.find(P[i])], mk[uf.find(nx)]);
            uf.unite(P[i], nx);
        }
        ans += mk[uf.find(P[i])];
        mk2[P[i]] = 1;

    }
    printf("%lld\n", ans);
    return 0;
}

