const int d[4][2]={{0,1},{1,0},{-1,0},{0,-1}};
inline bool check(int x,int y){
	return x>=1&&y>=1&&x<=n&&y<=n;
}
void dfs(int x,int y){
	for(int i=0;i<4;++i){
		int nx=x+d[i][0],ny=y+d[i][1];
		if(check(nx,ny)&&a[nx][ny]>a[x][y]+(!vis[x][y])){
			a[nx][ny]=a[x][y]+(!vis[x][y]);
			dfs(nx,ny);
		}
	}
}
