#include <iostream>
#include <algorithm>

const int maxN = 505;
const int maxQ = maxN * maxN;

int N;
int p[maxN * maxN];
int d[maxN][maxN];
bool is[maxN][maxN];
int q[maxQ * 2];
int fi, la;

int di[] = {-1, 0, 1, 0};
int dj[] = {0, -1, 0, 1};

int main() {
  std::cin >> N;
  for (int i = 0; i < N * N; ++i) {
    std::cin >> p[i];
    p[i] -= 1;
  }
  for (int i = 0; i < N; ++i) {
    for (int j = 0; j < N; ++j) {
      is[i][j] = true;
      d[i][j] = std::min(std::min(i, N - 1 - i), std::min(j, N - 1 - j));
    }
  }
  int res = 0;
  for (int k = 0; k < N * N; ++k) {
    int i = p[k] / N;
    int j = p[k] % N;
    res += d[i][j];
    is[i][j] = false;
    fi = la = maxQ;
    q[la++] = p[k];
    while (fi < la) {
      int x = q[fi++];
      int i = x / N;
      int j = x % N;
      for (int dk = 0; dk < 4; ++dk) {
        int ii = i + di[dk];
        int jj = j + dj[dk];
        if (ii < 0 || ii >= N || jj < 0 || jj >= N) {
          continue;
        }
        if (!is[i][j]) {
          if (d[ii][jj] > d[i][j]) {
            d[ii][jj] = d[i][j];
            q[--fi] = ii * N + jj;
          }
        } else {
          if (d[ii][jj] > d[i][j] + 1) {
            d[ii][jj] = d[i][j] + 1;
            q[la++] = ii * N + jj;
          }
        }
      }
    }
  }
  std::cout << res << std::endl;
  return 0;
}

