void search(int index, int count, int ans, int *depth){
    if(count > *depth) return;
    int dest = min(min(mae[lst[index]],usiro[lst[index]]),min(migi[lst[index]],hidari[lst[index]]));
    if(dest == 0&&count == 0) {
        *depth = 0;
        return;
    }
    if(dest == 0) return;
    *depth = min(*depth, ans+dest);
    search(index-n,count+1,ans+notVacant[index], depth);
    search(index+n,count+1,ans+notVacant[index], depth);
    search(index+1,count+1,ans+notVacant[index], depth);
    search(index-1,count+1,ans+notVacant[index], depth);
}

