int N, ans, P[505], dist[505][505], dr[] = {-1, 0, 0, 1}, dc[] = {0, -1, 1, 0};
bool grid[505][505];

void calc() {
	int d, r, c;
	deque<iii> D;
	for (int i = 2; i < N; i++)
		for (int j = 2; j < N; j++)
			dist[i][j] = 1e9;
	for (int i = 1; i <= N; i++)
		D.emplace_front(grid[1][i], 1, i), dist[1][i] = grid[1][i];
	for (int i = 2; i <= N; i++)
		D.emplace_front(grid[i][1], i, 1), dist[i][1] = grid[i][1];
	for (int i = 2; i <= N; i++)
		D.emplace_front(grid[N][i], N, i), dist[N][i] = grid[N][i];
	for (int i = 2; i < N; i++)
		D.emplace_front(grid[i][N], i, N), dist[i][N] = grid[i][N];
	while (!D.empty()) {
		tie(d, r, c) = D.front();
		D.ppf();
		if (dist[r][c] < d) continue;
		for (int k = 0; k < 4; k++)
			if (1 <= r + dr[k] && r + dr[k] <= N && 1 <= c + dc[k] && c + dc[k] <= N && dist[r + dr[k]][c + dc[k]] > d + grid[r + dr[k]][c + dc[k]]) {
				dist[r + dr[k]][c + dc[k]] = d + grid[r + dr[k]][c + dc[k]];
				if (grid[r + dr[k]][c + dc[k]]) D.emplace_back(dist[r + dr[k]][c + dc[k]], r + dr[k], c + dc[k]);
				else D.emplace_front(dist[r + dr[k]][c + dc[k]], r + dr[k], c + dc[k]);
			}
	}
	for (int i = 1; i <= N; i++)
		for (int j = 1; j <= N; j++)
			dist[i][j] -= grid[i][j];
}

