	for (int i = 1, P; i <= N * N; i++) {
		cin >> P;
		ans += dist[(P - 1) / N + 1][(P - 1) % N + 1];
		grid[(P - 1) / N + 1][(P - 1) % N + 1] = 0;
		calc();
	}
	cout << ans << '\n';
}

