template<class Monoid>
class SegmentTree {
    using Func = std::function<Monoid(Monoid, Monoid)>;
    int N;

    std::vector<Monoid> segment;

    const Func op;
    const Monoid id;

    bool dirty_flag;
public:
    // id : op = max なら -INT_MAX
    SegmentTree(int n, const Func biop, const Monoid& M1)
    : op(biop), id(M1), dirty_flag(false) {
        N = 1;
        while(N < n) N *= 2;
        segment.assign(2 * N, id);
    }

    void set(int k, const Monoid &a){
        dirty_flag = true;
        segment[k + N] = a;
    }

    void build() {
        for (int k = N - 1; k > 0; --k) {
            segment[k] = op(segment[2 * k], segment[2 * k + 1]);
        } // end k
        dirty_flag = false;
    }

    void update(int k, const Monoid& a){
        k += N;
        segment[k] = a;
        while(k /= 2){
            segment[k] = op(segment[k*2], segment[k*2+1]);
        }
    }

    // -> op [a,b)
    Monoid query(unsigned a, unsigned b){
        if(dirty_flag) build();
        dirty_flag = false;
        Monoid L = id, R = id;
        for (a += N, b += N; a < b; a >>= 1u, b >>= 1u) {
            if(a & 1u) L = op(L, segment[a++]);
            if(b & 1u) R = op(segment[--b], R);
        } // end i
        return op(L, R);
    }

    Monoid operator[](const int &k) const{
        return segment[k + N];
    }
};


class solver{
    istream& is;
    ostream& os;

public:
    solver(istream& I, ostream& O) :is(I), os(O) {}

    int N;
    vector<int> P;
    vector<vector<int>> seat;
    vector<vector<bool>> sit;
    bool input() {
        is >> N;
        P.resize(N*N);
        is >> P;
        return !!is;
    }

    tuple<int, int> pos(int x) const{
        int i =  x / N;
        int j =  x % N;
        return {i+1, j+1};
    }

    void update(int x, int y){
        vector<int> dx{0, -1, 0, 1};
        vector<int> dy{-1, 0, 1, 0};
        for (int i = 0; i < 4; ++i) {
            UPMIN(seat[x][y], seat[x + dx[i]][y + dy[i]]);
        } // end i
        queue<int> qx, qy;
        qx.push(x); qy.push(y);
        while (!qx.empty()){
            x = qx.front(); qx.pop();
            y = qy.front(); qy.pop();

            for (int i = 0; i < 4; ++i) {
                if(UPMIN(seat[x + dx[i]][y + dy[i]],
                        seat[x][y] + sit[x+dx[i]][y+dy[i]])){
                    qx.push(x+dx[i]);
                    qy.push(y+dy[i]);
                }
            } // end i
        }
    }

    void run();
};

