void solver::run(){
    if(!input()) return;
    seat = VEC(N+2, N+2, 0);
    sit = VEC(N+2, N+2, false);
    for (int i = 1; i <= N; ++i) {
        for (int j = 1; j <= N; ++j) {
            seat[i][j] = min({i,j,N-i+1, N-j+1});
            sit[i][j] = true;
        } // end j
    } // end i

    ll ans = 0;

    for (auto &&pi : P) {
        int x, y;
        tie(x, y) = pos(pi-1);
        ans += seat[x][y]-1;
        sit[x][y] = false;
        update(x, y);
//        os << seat << endl;
    } // end pi
    cout << ans << endl;
}

