  if (w == f[w]) {
    return w;
  }

  f[w] = FIND(f[w]);
  return f[w];
}

bool vis[MAXN];
void UNION(int a, int b) {
  if (a == b) {
    return;
  }

  int fa = FIND(a);
  int fb = FIND(b);
  if (val[fa] == val[fb]) {
    return;
  }
  if (val[fa] < val[fb]) {
    return;
  }
  if (val[fa] < val[fb]) {
    f[fb] = fa;
  } else {
    f[fa] = fb;
  }
}

