    // 始点sから各頂点iへの最短距離を求めてd[i]に格納　O(|m|log|n|)
    auto dijkstra = [&](int sy, int sx) {
      vector<vector<int>> d(n+2,vector<int>(n+2,INF));
      priority_queue<T, vector<T>, greater<T> > que;
      d[sy][sx] = 0;
      que.push(T(0,sy,sx));
      while (!que.empty()) {
        T p = que.top(); que.pop();
        int cost, y, x;
        tie(cost,y,x) = p;
        if (d[y][x] < cost) continue; // d[v]が他の点からの更新により小さくなり、vまでにかかるコスト(=c=p.first)が最小でないならcontinue
        rep(i,4) {
          int ny = y + dy[i];
          int nx = x + dx[i];
          if (ny < 0 || y > n+2 || x < 0 || nx > n+2) continue;
          if (d[ny][nx] > d[y][x] + (c[ny][nx]== -2 || c[ny][nx] == -1 ? 0 : 1)) {
            d[ny][nx] = d[y][x] + (c[ny][nx]== -2 || c[ny][nx] == -1 ? 0 : 1);
            que.push(T(d[ny][nx],y,x));
          }
        }      
      }
      return d;
    };

    auto d = dijkstra(sy,sx);
    int res = INF;
    srep(j,1,n+1) chmin(res,d[0][j]);
    srep(j,1,n+1) chmin(res,d[n+1][j]);
    srep(i,1,n+1) chmin(res,d[i][0]);
    srep(i,1,n+1) chmin(res,d[i][n+1]);
    ans += res;
    c[sy][sx] = -2;
  }

