void work(int x, int y, int d)
{
	queue<pair<pair<int, int>, int> > q;
	q.push({{x, y}, d});
	while(!q.empty())
	{
		auto p = q.front();
		q.pop();
		int x = p.first.first;
		int y = p.first.second;
		int d = p.second;
		for(int k = 0; k < 4; k++)
