			if(nx < 1 || nx > n || ny < 1 || ny > n)
				continue;
			if(dist[nx][ny] > d + alive[x][y])
			{
				dist[nx][ny] = d + alive[x][y];
				q.push({{nx, ny}, d + alive[x][y]});
			}
		}
	}
}

