long long get_min(vector<vector<int>> &dis,int y,int x){
	if(y==0||x==0||y+1==dis.size()||x+1==dis.size())return -1;
	return min({dis[y+1][x],dis[y-1][x],dis[y][x+1],dis[y][x-1]});
}

int main(){

	int N;
	cin>>N;

	vector<int> P(N*N);

	for(int i=0;i<N*N;i++){
		scanf("%d",&P[i]);
		P[i]--;
	}

	vector<vector<int>> dis(N,vector<int>(N));

	for(int i=0;i<N;i++){
		for(int j=0;j<N;j++){
			dis[i][j] = min({i,N-1-i,j,N-1-j});
		}
	}

	long long ans = 0;

	vector<vector<bool>> B(N,vector<bool>(N,true));

	for(int i=0;i<N*N;i++){
		int y = P[i]/N;
		int x = P[i]%N;

		ans += (long long)dis[y][x];
		B[y][x] = false;
		dis[y][x] = get_min(dis,y,x);

		deque<pair<int,int>> D;
		D.emplace_back(y,x);

		while(D.size()!=0){			

			int yy = D.back().first;
			int xx = D.back().second;
			D.pop_back();

			for(int j=0;j<4;j++){
				int ny = yy;
				int nx = xx;
				if(j==0)ny++;
				if(j==1)ny--;
				if(j==2)nx++;
				if(j==3)nx--;

				if(nx<0||nx>=N||ny<0||ny>=N)continue;
				int ND = dis[yy][xx];
				if(B[ny][nx]){
					ND++;
					if(ND<dis[ny][nx]){
						dis[ny][nx] = ND;
						D.emplace_front(ny,nx);
					}
				}
				else{
					if(ND<dis[ny][nx]){
						dis[ny][nx] = ND;
						D.emplace_back(ny,nx);
					}
				}
			}
		}
	}

	cout<<ans<<endl;


	return 0;
}

