const int dir[5][2] = {{0, 0}, {1, 0}, {0, 1}, {-1, 0}, {0, -1}};
const int N = 500 + 10;
int f[N * N], c[N * N];
bool visit[N][N];

int find(int x) {
  if (f[x] != f[f[x]]) f[x] = find(f[x]);
  return f[x];
}

void join(int x, int y) {
  int rx = find(x), ry = find(y);
  if (rx == ry) return;
  f[ry] = rx;
  c[rx] = min(c[rx], c[ry]);
}

int main() {
  int n;
  scanf("%d", &n);
  for (int i = 0; i < n * n; ++i) {
    int x = i / n, y = i % n;
    f[i] = i;
    c[i] = min(min(x, y), min(n - 1 - x, n - 1 - y));
  }
  int64 ret = 0;
  for (int i = 0; i < n * n; ++i) {
    int pos;
    scanf("%d", &pos);
    --pos;
    int x = pos / n, y = pos % n;
    int cur = c[pos];
    for (int k = 1; k <= 4; ++k) {
      int nx = x + dir[k][0];
      int ny = y + dir[k][1];
      if (nx < 0 || nx >= n || ny < 0 || ny >= n || !visit[nx][ny]) continue;
      cur = min(cur, c[find(nx * n + ny)]);
    }
    // trace(x, y, cur, c[pos]);
    ret += cur;
    visit[x][y] = true;
    for (int k = 1; k <= 4; ++k) {
      int nx = x + dir[k][0];
      int ny = y + dir[k][1];
      if (nx < 0 || nx >= n || ny < 0 || ny >= n || !visit[nx][ny]) continue;
      join(x * n + y, nx * n + ny);
    }
  }
  printf("%lld\n", ret);
  return 0;
}

