                int x = i + e.f, y = j + e.s;
                if (0 <= x && x < n && 0 <= y && y < n && dist[i][j] + bad[i][j] < dist[x][y]) {
                    dist[x][y] = dist[i][j] + bad[i][j];
                    q.push(mp(x, y));
                }
            }   
        }
    }   
    cout << ans << endl;
}

