class BJoker {
public:
    void solve() {
        int n = in.readInt();
        auto p = in.readIntArray(n * n);
        decreaseByOne(p);

        arri mnR(n * n);
        arri mnC(n * n);
        arri mxR(n * n);
        arri mxC(n * n);
        arri r(n * n);
        arri c(n * n);
        for (int i : range(n)) {
            for (int j : range(n)) {
                int id = i * n + j;
                r[id] = i;
                c[id] = j;
                mnR[id] = mxR[id] = i;
                mnC[id] = mxC[id] = j;
            }
        }
        DSU dsu(n * n);
        ll answer = 0;
        arr2d<bool> done(n, n, false);
        for (int i : p) {
            for (int j : range(4)) {
                int nr = r[i] + DX4[j];
                int nc = c[i] + DY4[j];
                int id = nr * n + nc;
                if (isValidCell(nr, nc, n, n) && done(nr, nc)) {
                    int a = dsu[i];
                    int b = dsu[id];
                    if (a != b) {
                        mnR[a] = mnR[b] = min(mnR[a], mnR[b]);
                        mnC[a] = mnC[b] = min(mnC[a], mnC[b]);
                        mxR[a] = mxR[b] = max(mxR[a], mxR[b]);
                        mxC[a] = mxC[b] = max(mxC[a], mxC[b]);
                    }
                    dsu.join(a, b);
                }
            }
            done(r[i], c[i]) = true;
            i = dsu[i];
            answer += min({mnR[i], mnC[i], n - mxR[i] - 1, n - mxC[i] - 1});
        }
        out.printLine(answer);
    }
};


