	Queue.push(make_pair(row, col));
	while(!Queue.empty()) {
		int r = Queue.front().first, c = Queue.front().second;
		Queue.pop();
		for(int drow: d) {
			int new_row = r+drow;
			if(new_row>=1 and new_row<=N) {
				int ndist = dist[r][c];
				if(exist[r][c]) ndist++;
				if(ndist<dist[new_row][c]) {
					dist[new_row][c] = ndist;
					Queue.push(make_pair(new_row, c));
				}
			}
		}
		for(int dcol:d) {
			int new_col = c+dcol;
			if(new_col>=1 and new_col<=N) {
				int ndist = dist[r][c];
				if(exist[r][c]) ndist++;
				if(ndist<dist[r][new_col]) {
					dist[r][new_col] = ndist;
					Queue.push(make_pair(r, new_col));
				}
			}
		}
	}
}

