bool in (int i, int j) { return 1 <= i && i <= n && 1 <= j && j <= n; }

void upd (int i, int j) {
	for (int k = 0; k < 4; k ++) {
		int x = i + dx[k];
		int y = j + dy[k];
		if (in(x, y) && dp[i][j] + have[i][j] < dp[x][y]) {
			dp[x][y] = dp[i][j] + have[i][j];
			upd(x, y);
		}
	}
}

int main (void) {
