	for (int i = 1, x, y; i <= n * n; i ++) {
		scanf("%d", &y);
		x = (y - 1) / n + 1;
		y = (y - 1) % n + 1;
		ans += dp[x][y];
		have[x][y] = 0;
		upd(x, y);
	}
	printf("%lld\n", ans);
}

