struct union_find{
    vector<int> par;
    vector<int> rank;
    vector<int> size;
    vector<int> data;

    union_find(int n) : par(n), rank(n), size(n), data(n){
        for(int i = 0; i < n; i++){
            par[i] = i; rank[i] = 0; size[i] = 1;
        }
    }
    int root(int x){
        if(par[x] == x) return x;
        par[x] = root(par[x]);
        data[par[x]] = min(data[par[x]], data[x]);
        return par[x];
    }
    void unite(int x, int y){
        int rx = root(x);
        int ry = root(y);
        if (rx == ry) return;
        if (rank[rx] < rank[ry]){
            par[rx] = ry;
            data[ry] = min(data[ry], data[rx]);
            size[ry] += size[rx];
        }
        else{
            par[ry] = rx;
            data[rx] = min(data[rx], data[ry]);
            if (rank[rx] == rank[ry]) rank[rx]++;
            size[rx] += size[ry];
        }
    }
    bool same(int x, int y){
        int rx = root(x);
        int ry = root(y);
        return rx == ry;
    }
    int getdata(int x){
        int rx = root(x);
        return data[rx];
    }
};

