struct Node {
  // ダイクストラ法のためのデータ
  bool done;  // 確定ノードか否か
  int cost;   // このノードへの現時点で判明している最小コスト
};

const int S[4][2] = {{-1, 0}, {0, -1}, {0, 1}, {1, 0}};
Node m[502][502];
int N;
int P[502][502] = {0};
int Q[502 * 502] = {0};

int diff_solve(int num, int sx, int sy)
{
  // 周辺を差分更新
  priority_queue<tuple<int, int, int>> que;
  que.push(make_tuple(-m[sx][sy].cost, sx, sy));
  while (!que.empty())
  {
    auto next = que.top();
    que.pop();
    int c(-get<0>(next)), cx(get<1>(next)), cy(get<2>(next));

    for (int d = 0; d < 4; d++)
    {
      int x = cx + S[d][0];
      int y = cy + S[d][1];
      int cost = c + (num < P[cx][cy] ? 1 : 0);

      if (cost < m[x][y].cost)
      {
        m[x][y].cost = cost;
        auto t = make_tuple(-cost, x, y);
        que.push(t);
      }
    }
  }

  return m[sx][sy].cost;
}

