    n = read();
    for (int i = 1; i <= n; i++) {
        for (int j = 1; j <= n; j++) {
            dis[i][j] = std::min(std::min(i - 1, n - i), std::min(j - 1, n - j));
        }
    }
    for (int i = 0; i < n * n; i++) {
        int p = read();
        int x = (p - 1) / n + 1;
        int y = (p - 1) % n + 1;
        used[x][y] = true;
        std::deque<std::pair<int, int>> que;
        for (que.push_back({x, y}); !que.empty(); ) {
            x = que.front().first;
            y = que.front().second;
            que.pop_front();
            if (used[x][y]) {
                for (int k = 0; k < 4; k++) {
                    int vx = x + dx[k];
                    int vy = y + dy[k];
                    if (vx < 1 || vy < 1 || vx > n || vy > n) { continue; }
                    if (dis[vx][vy] > dis[x][y]) {
                        dis[vx][vy] = dis[x][y];
                        que.push_front({vx, vy});
