int L[501][501];
int v[501][501];
int dist[501][501];

int main() {
  ios_base::sync_with_stdio(false);
  cin.tie(nullptr);
  int n;
  cin >> n;
  for (int i = 0; i < n; i++) {
    for (int j = 0; j < n; j++) {
      dist[i][j] = min(i, min(j, min(n - i - 1, n - j - 1)));
      v[i][j] = -1;
      L[i][j] = 0;
    }
  }
  long long ans = 0;
  vector<pair<int, int>> q;
  for (int i = 0; i < n*n; i++) {
    int ind;
    cin >> ind;
    ind--;

    {
      int r = ind / n, c = ind % n;
      ans += dist[r][c];
      L[r][c] = 1;
      q.clear();
      q.emplace_back(r, c);
      v[r][c] = i;
    }
    for (int h = 0; h < q.size(); h++) {
      int r, c;
      tie(r, c) = q[h];
      // recalc
      int newdist = 1 - L[r][c] + dist[r][c];
      if (r > 0 && v[r - 1][c] < i && dist[r - 1][c] > newdist) {
        dist[r - 1][c] = newdist;
        q.emplace_back(r - 1, c);
        v[r - 1][c] = i;
      }
      if (c > 0 && v[r][c - 1] < i && dist[r][c - 1] > newdist) {
        dist[r][c - 1] = newdist;
        q.emplace_back(r, c - 1);
        v[r][c - 1] = i;
      }
      if (r + 1 < n && v[r + 1][c] < i && dist[r + 1][c] > newdist) {
        dist[r + 1][c] = newdist;
        q.emplace_back(r + 1, c);
        v[r + 1][c] = i;
      }
      if (c + 1 < n && v[r][c + 1] < i && dist[r][c + 1] > newdist) {
        dist[r][c + 1] = newdist;
        q.emplace_back(r, c + 1);
        v[r][c + 1] = i;
      }
    }
  }
  cout << ans << "\n";
  return 0;
}

