int dx[4] = {0, -1, 0, 1}, dy[4] = {1, 0, -1, 0};
void update (int x, int y) {
	for (int i = 0; i < 4; ++i) {
		int tx = x + dx[i], ty = y + dy[i];
		if (tx < 1 || ty < 1 || tx > n || ty > n) continue;
		if (f[tx][ty] > f[x][y] + (k[x][y] ^ 1))
			f[tx][ty] = f[x][y] + (k[x][y] ^ 1), update (tx, ty);
	}
}
