signed main() {
	ll n;
	cin >> n;
	VL p(n * n);
	cin >> p;

	VVL cost(n, VL(n));
	REP(k, (n + 1) / 2)	FOR(i, k, n - k) {
		cost[k][i] = k;
		cost[i][k] = k;
		cost[i][n - k - 1] = k;
		cost[n - k - 1][i] = k;
	}

	V<PAIR> order; order.reserve(n * n);
	VVL table(n, VL(n));
	REP(i, n * n) {
		order.emplace_back((p[i] - 1) / n, (p[i] - 1) % n);
		table[(p[i] - 1) / n][(p[i] - 1) % n] = i;
	}

	ll ans = 0;
	REP(k, n * n) {
		auto [fy, fx] = order[k];
		ans += cost[fy][fx];

		queue<PAIR> q;
		auto ad = [&](ll y, ll x, ll ty, ll tx) {
			if (y < 0 || x < 0 || y >= n || x >= n) { return; }
			if (cost[y][x] <= 0) { return; }
			if (cost[y][x] > cost[ty][tx] + (table[ty][tx] > k)) {
				q.emplace(y, x);
				--cost[y][x];
			}
		};
		q.emplace(fy, fx);

		while (!q.empty()) {
			auto [y, x] = q.front();
			q.pop();
			ad(y + 1, x, y, x);
			ad(y - 1, x, y, x);
			ad(y, x - 1, y, x);
			ad(y, x + 1, y, x);
		}
	}
	cout << ans << endl;

	dump(table);
	dump(cost);


}

