int main() {
  std::ios_base::sync_with_stdio(false);
  int N;
  cin >> N;

  vector<vector<int>> cnt(N, vector<int>(N, 0));
  vector<vector<bool>> dead(N, vector<bool>(N, false));

  for (int i = 0; i < N; ++i) {
    for (int j = 0; j < N; ++j) {
      cnt[i][j] = min(min(i, j), min(N - i - 1, N - j - 1));
    }
  }

  int ans = 0;
  for (int i = 0; i < N * N; ++i) {
    int v;
    cin >> v;
    v--;

    int y = v % N;
    int x = v / N;

    ans += cnt[x][y];
    dead[x][y] = true;

    queue<int> Q;
    Q.push(x);
    Q.push(y);
    while (!Q.empty()) {
      int x = Q.front();
      Q.pop();
      int y = Q.front();
      Q.pop();

      static const int dx[] = {1, 0, -1, 0};
      static const int dy[] = {0, -1, 0, 1};

      int newCost = cnt[x][y] + (dead[x][y] ? 0 : 1);
      for (int k = 0; k < 4; ++k) {
        int nx = x + dx[k];
        int ny = y + dy[k];
        if (nx < 0 || nx >= N || ny < 0 || ny >= N) continue;
        if (newCost < cnt[nx][ny]) {
          assert(newCost + 1 == cnt[nx][ny]);
          cnt[nx][ny] = newCost;
          Q.push(nx);
          Q.push(ny);
        }
      }
    }
  }

  cout << ans << "\n";
  return 0;
}

