void dfs(int i, int j){
	visited[i][j] = 1;
	if(i == 1 || j == 1 || i == n || j == n){
		minHaters = min(minHaters, haters);
		return;
	}

	if(!visited[i+1][j]){
		if(a[i+1][j] != -1) haters++;
		dfs(i+1, j);
		if(a[i+1][j] != -1) haters--;
	}
	if(!visited[i][j+1]){
		if(a[i][j+1] != -1) haters++;
		dfs(i, j+1);
		if(a[i][j+1] != -1) haters--;
	}
	if(!visited[i][j-1]){
		if(a[i][j-1] != -1) haters++;
		dfs(i, j-1);
		if(a[i][j-1] != -1) haters--;
	}
	if(!visited[i-1][j]){
		if(a[i-1][j] != -1) haters++;
		dfs(i-1, j);
		if(a[i-1][j] != -1) haters--;
	}
}

