    vector<oset<int>> cols(n+1);
    FOR1(i, n){
        for(int x = (i-1)*n+1; x <= i*n; x++ )
            rows[i].insert(x);
    }
    FOR1(i, n){
        for(int x = i; x<=n2; x+=n)
            cols[i].insert(x);
    }

    set<pii> S;
    FOR(i, n2){
        int key = p[i];
        int row = (key-1)/n + 1;
        int col = (key-1)%n + 1;

        int pr = rows[row].order_of_key(key);
        int left = pr;
        int right = rows[row].size()-1 - pr;
        int pc = cols[col].order_of_key(key);
        int up = pc;
        int down = cols[col].size()-1 - pc;

        rows[row].erase(key);
        cols[col].erase(key);

        int nb = min( min(left, right), min(up, down));
        if (nb == left){
            for(auto it : rows[row])
                if (it < key)
                    S.insert({it, key});
        }
        else if (nb == right){
            for(auto it : rows[row])
                if (it > key)
                    S.insert({key, it});
        }
        else if (nb == up){
            for(auto it : cols[col])
                if (it < key)
                    S.insert({it, key});
        }
        else if (nb == down){
            for(auto it : cols[col])
                if (it > key)
                    S.insert({key, it});
        }
    }
    cout << S.size() << endl;

    if (argc == 2 && atoi(argv[1]) == 123456789) cout << clock()*1.0/CLOCKS_PER_SEC << " sec\n";
    return 0;
}

