int main() {
	int n; cin >> n;
	vector<pair<int, int>> v;
	for(int i = 0; i < n * n; ++i) {
		int p; cin >> p;
		--p;
		v.emplace_back(p / n, p % n);
	}
	int dist[n][n];
	bool obj[n][n];
	for(int i = 0; i < n; ++i) {
		for(int j = 0; j < n; ++j) {
			dist[i][j] = min({i, j, n - 1 - i, n - 1 - j});
			obj[i][j] = true;
		}
	}
	int ans = 0;
	constexpr int dy[] = {0, 1, 0, -1};
	constexpr int dx[] = {1, 0, -1, 0};
	for(int i = 0; i < n * n; ++i) {
		auto [sy, sx] = v[i];
		ans += dist[sy][sx];
		obj[sy][sx] = false;
		for(int d = 0; d < 4; ++d) {
			int ny = sy + dy[d];
			int nx = sx + dx[d];
			if(ny < 0 or n <= ny) continue;
			if(nx < 0 or n <= nx) continue;
			dist[sy][sx] = min(dist[sy][sx], dist[ny][nx] + obj[ny][nx]);
		}
		queue<tuple<int, int, int>> que;
		que.emplace(sy, sx, dist[sy][sx]);
		while(not que.empty()) {
			auto [y, x, c] = que.front();
			que.pop();
			if(c > dist[y][x]) continue;
			for(int d = 0; d < 4; ++d) {
				int ny = y + dy[d];
				int nx = x + dx[d];
				if(ny < 0 or n <= ny) continue;
				if(nx < 0 or n <= nx) continue;
				int nc = c;
				if(obj[y][x]) ++nc;
				if(nc >= dist[ny][nx]) continue;
				dist[ny][nx] = nc;
				que.emplace(ny, nx, nc);
			}
		}
