bool min_u(int&m, int v)
{
	if(m>v)
	{
		m=v;
		return true;
	}
	return false;
}


struct solve
{
	vvi f;
	vvi used;
	int n;
	vpii vdir={{0,1},{1,0},{0,-1},{-1,0}};

	solve(int n) : n(n) {
		used.resize(n+2);
		for(auto&m:used) m.assign(n+2,0);
		f.resize(n+2);
		for(auto&m:f) m.assign(n+2,-1);

		for(int y=1;y<=n;y++)
		{
			for(int x=1;x<=n;x++)
			{
				int v=x-1;
				min_u(v, y-1);
				min_u(v, n-x);
				min_u(v, n-y);
				f[y][x]=v;
				used[y][x]=1;
			}
		}
	}
	int armin(int x, int y)
	{
		int v=n;
		for(auto [vx,vy]:vdir)
		{
			int nx=x+vx;
			int ny=y+vy;
			min_u(v, f[ny][nx]);
		}
		return v;
	}
	int remove(int x, int y)
	{
		int ret=f[y][x];

		used[y][x]=0;
		f[y][x]=armin(x, y);

		queue<pii> q;
		q.push(make_pair(x, y));
		while(!q.empty())
		{
			tie(x,y)=q.front();
			q.pop();
			for(auto [vx,vy]:vdir)
			{
				int nx=x+vx;
				int ny=y+vy;
				if(f[ny][nx]<0) continue;
				if(min_u(f[ny][nx], armin(nx, ny)+used[ny][nx]))
				{
					q.push(make_pair(nx,ny));
				}
			}
		}
		return ret;
	}
	int operator()(vpii&p) {
		int ans=0;
		for(auto [x,y]:p)
		{
			ans+=remove(x, y);
		}
		return ans;
	}
};


int main(void)
{
	int n;
	while(scanf("%d", &n)==1)
	{
		vpii p(n*n);
		for(auto&mp:p)
		{
			int v;
			scanf("%d", &v);
			mp={(v-1)%n+1, (v-1)/n+1};
		}

		printf("%d\n", solve(n)(p));
	}
	return 0;
}

