int ijToNum(int nLine, int i, int j){
  	int seatNum = j*nLine+i+1;
  	return seatNum;
}

int numToJ(int nLine, int seatNum){
 	int jGuest = ( (seatNum-1) / nLine);// [0,N-1]
  	return jGuest;
}

int numToI(int nLine, int seatNum){
 	int yGuest = numToJ(nLine, seatNum) + 1;// [1,N]
    int xGuest = seatNum - nLine*(yGuest-1);// [1,N]
  	return xGuest-1;
}

int main(){
  	int answer =0;

	int nLine;
  	cin >> nLine;
    int mvCost[nLine][nLine];
  	bool isMan[nLine][nLine];
  	for(int i=0;i<nLine;i++){
    	for(int j=0;j<nLine;j++){
          	mvCost[i][j] = std::min( {i,j,nLine-1-i,nLine-1-j} );
          	isMan[i][j] = true;
        }
    }

  	int nGuest = nLine*nLine;
  	int seatNum[nGuest];
  	for(int iGuest=0;iGuest<nGuest;iGuest++){
  		cin >> seatNum[iGuest];
    }

  	std::vector<int> subtrSeat;
  	for(int iGuest=0;iGuest<nGuest;iGuest++){
      	subtrSeat.push_back(seatNum[iGuest]);
      	answer += mvCost[numToI(nLine, subtrSeat[0])][numToJ(nLine, subtrSeat[0])];
      	isMan[numToI(nLine, subtrSeat[0])][numToJ(nLine, subtrSeat[0])] = false;

    }
      	while( (int)subtrSeat.size() > 0){
	      	int iGuest = numToI(nLine, subtrSeat[0]);
    	  	int jGuest = numToJ(nLine, subtrSeat[0]);

          	//cout << "seatNum = " << subtrSeat[0] <<endl;
          	if(0< iGuest && iGuest<nLine-1 && 0< jGuest && jGuest<nLine-1){
 	         	if(mvCost[iGuest][jGuest] < mvCost[iGuest+1][jGuest]){
    	          	subtrSeat.push_back(ijToNum(nLine,iGuest+1,jGuest));
        	    }
            }
          	if(0< iGuest && iGuest<nLine-1 && 0< jGuest && jGuest<nLine-1){
          		if(mvCost[iGuest][jGuest] < mvCost[iGuest-1][jGuest]){
              		subtrSeat.push_back(ijToNum(nLine,iGuest-1,jGuest));
    	        }
            }
          	if(0< iGuest && iGuest<nLine-1 && 0< jGuest && jGuest<nLine-1){
	          	if(mvCost[iGuest][jGuest] < mvCost[iGuest][jGuest+1]){
    	          	subtrSeat.push_back(ijToNum(nLine,iGuest,jGuest+1));
        	    }
            }
          	if(0< iGuest && iGuest<nLine-1 && 0< jGuest && jGuest<nLine-1){
            	if(mvCost[iGuest][jGuest] < mvCost[iGuest][jGuest-1]){
              		subtrSeat.push_back(ijToNum(nLine,iGuest,jGuest-1));
                }
            }
          	//cout<< "cost = "<< mvCost[iGuest][jGuest]<<endl;
          	mvCost[iGuest][jGuest]--;
      		subtrSeat.erase(subtrSeat.begin());
          	subtrSeat.shrink_to_fit();
        }
    }

  	cout << answer;
}

#include <bits/stdc++.h>
using namespace std;

const int maxn = 250010;
const int dx[] = {-1, 1, 0, 0}, dy[] = {0, 0, -1, 1};
int n, p[maxn], fa[maxn], mn[maxn];
bool chk[510][510];

int id(int x, int y) {
    return (x - 1) * n + y;
}

int find(int x) {
    return x == fa[x] ? x : fa[x] = find(fa[x]);
}

int main() {
    scanf("%d", &n);
    for (int i = 1; i <= n; i++) {
        for (int j = 1; j <= n; j++) {
            fa[id(i, j)] = id(i, j);
            mn[id(i, j)] = min({i - 1, j - 1, n - i, n - j});
        }
    }
    int ans = 0;
    for (int i = 1; i <= n * n; i++) {
        scanf("%d", &p[i]);
        int x = (p[i] - 1) / n + 1, y = p[i] - (x - 1) * n;
        chk[x][y] = 1;
        for (int k = 0; k < 4; k++) {
            int nx = x + dx[k], ny = y + dy[k];
            if (nx < 1 || nx > n || ny < 1 || ny > n) continue;
            int f1 = find(p[i]), f2 = find(id(nx, ny));
            if (f1 == f2) continue;
            if (!chk[nx][ny]) mn[f1] = min(mn[f1], mn[f2] + 1);
            else fa[f1] = f2, mn[f2] = min(mn[f2], mn[f1]);
        }
        for (int k = 0; k < 4; k++) {
            int nx = x + dx[k], ny = y + dy[k];
            if (nx < 1 || nx > n || ny < 1 || ny > n || chk[nx][ny]) continue;
            int f1 = find(p[i]), f2 = find(id(nx, ny));
            if (f1 == f2) continue;
            mn[f2] = min(mn[f2], mn[f1] + 1);
        }
        ans += mn[find(p[i])];
    }
    printf("%d\n", ans);
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

const int Maxn = 505;
const int Maxm = 255;
const int Maxd = 4;
const int dy[Maxd] = {-1, 0, 1, 0};
const int dx[Maxd] = {0, -1, 0, 1};

struct pos {
    int a, b, c;
    pos(int a = 0, int b = 0, int c = 0): a(a), b(b), c(c) {}
};

bool dp[Maxn][Maxn][Maxm];
int n;
bool fr[Maxn][Maxn];
int a[Maxn * Maxn];
pos seq[Maxn * Maxn];
int slen;
int res;

void Gen(int r, int c, int lvl)
{
    if (dp[r][c][lvl]) return;
    dp[r][c][lvl] = true;
    slen = 0;
    seq[slen++] = pos(r, c, lvl);
    for (int i = 0; i < slen; i++) {
        pos p = seq[i];
        for (int d = 0; d < Maxd; d++) {
            pos u = pos(p.a + dy[d], p.b + dx[d], p.c);
            if (0 <= u.a && u.a < n && 0 <= u.b && u.b < n) {
                if (!fr[u.a][u.b]) u.c++;
                if (u.c < Maxm && !dp[u.a][u.b][u.c]) {
                    dp[u.a][u.b][u.c] = true;
                    seq[slen++] = u;
                }
            }
        }
    }
}

int main()
{
    scanf("%d", &n);
    for (int i = 0; i < n * n; i++) {
        scanf("%d", &a[i]); a[i]--;
    }
    for (int i = 0; i < n; i++) {
        Gen(i, 0, 1);
        Gen(i, n - 1, 1);
        Gen(0, i, 1);
        Gen(n - 1, i, 1);
    }
    for (int i = 0; i < n * n; i++) {
        int r = a[i] / n, c = a[i] % n;
        int my = 0;
        while (!dp[r][c][my]) my++;
        my--;
        fr[r][c] = true;
        res += my;
        Gen(r, c, my);
    }
    cout << res << endl;
    return 0;
}

