/* How does dp change if one goes out?
 * All with a shortest path over that one have
 * a shortest path one smaller.
 * Which ones are these?
 * Can we do updates?
 * Try.
 */
void solve() {
    cini(n);
    cinai(p,n*n);

    vvi dp(n, vi(n)); /* dp[i][j]==number of haters if u use that path */
    for(int i=0; i<n; i++)
        for(int j=0; j<n; j++)
            dp[i][j]=min(i, min(j, min(n-1-i, n-1-j)));

    vvi notvis(n, vi(n,1));

    const vector<pii> d= { { -1, 0}, {1,0}, {0,-1}, {0,1}};
    int ans=0;
    for(int i=0; i<n*n; i++) {
        int r=(p[i]-1)/n;
        int c=(p[i]-1)%n;

        int mi=1e9;
        for(auto d1 : d) {
            int rr=r+d1.first;
            int cc=c+d1.second;
            if(rr>=0 && rr<n && cc>=0 && cc<n)
                mi=min(mi, dp[rr][cc]+notvis[rr][cc]);
            else
                mi=0;
        }
        ans+=mi;
        dp[r][c]=mi;
        notvis[r][c]=0;
//cerr<<"i="<<i<<" r="<<r<<" c="<<c<<" mi="<<mi<<endl;

        queue<pii> q;
        q.emplace(r,c);
        while(q.size()) {
            auto [r0,c0]=q.front();
            q.pop();
            for(auto d1 : d) {
                int rr=r0+d1.first;
                int cc=c0+d1.second;
                if(rr>=0 && rr<n && cc>=0 && cc<n && dp[rr][cc]>dp[r0][c0]+notvis[rr][cc]) {
                    dp[rr][cc]=dp[r0][c0]+notvis[rr][cc];
                    q.emplace(rr,cc);
                }
            }
        }
    }

    cout<<ans<<endl;
}

signed main() {
    solve();
}

