ll powmod(ll x, ll y) 
{ 
    ll res = 1;  
    x = x % MOD;
    while (y > 0) 
    { 
        if (y & 1) 
  	      res = (res*x) % MOD; 
        y = y>>1; // y = y/2 
        x = (x*x) % MOD;   
    } 
    return res; 
} 

int p[502*502];
bool boundary[502*502];
int dist[502*502];
bool blocked[502*502];
int n;
int solve(int i){
	for(int j=1;j<=n*n;j++)
		dist[j]=INF;

	priority_queue<pair<int,int>,vector<pair<int,int>>,greater<pair<int,int> > >pq;

 	for(int j=1;j<=n*n;){
 		pq.push(mp(blocked[j],j));
 		pq.push(mp(blocked[j+n-1],j+n-1)); 		

 		dist[j]=blocked[j];
 		dist[j+n-1]=blocked[j+n-1];
 		j+=n;
 	}
 	for(int i=2;i<n;i++){
 		dist[i]=blocked[i];
 		pq.push(mp(blocked[i],i));
 	}
 	for(int i=n*n-n+2;i<n*n;i++){
 		dist[i]=blocked[i];
 		pq.push(mp(blocked[i],i));
 	}


	while(!pq.empty()){
		pair<int,int>p=pq.top();
		pq.pop();

		if(p.ss==i){return max(0,p.ff-1);}

		vector<int>cells={p.ss+1,p.ss-1,p.ss+n,p.ss-n};		
		for(auto cell:cells)
		{
			if(!(cell>=1 and cell<=n*n))continue;
			if(blocked[cell] and dist[cell]>dist[p.ss]+1){
				dist[cell]=dist[p.ss]+1;
				pq.push(mp(dist[cell],cell));
			}
			else if(!blocked[cell] and dist[cell]>dist[p.ss]){
				dist[cell]=dist[p.ss];
				pq.push(mp(dist[cell],cell));	
			}
		}
	}

}

