            if (nx >= 1 && nx <= n && ny >= 1 && ny <= n) {
                if (ans[nx][ny] > ans[u.first][u.second]+!vis[nx][ny]) {
                    assert(ans[nx][ny] == ans[u.first][u.second]+!vis[nx][ny]+1);
                    ans[nx][ny] = ans[u.first][u.second]+!vis[nx][ny];
                    que.push(pii(nx, ny));
                }
            }
        }
    }
}

void solve() {

    scanf("%d", &n);

    for (int i = 1; i <= n; i++) {
        for (int j = 1; j <= n; j++) {
            ans[i][j] = min(min(i, n-i+1), min(j, n-j+1));
        }
    }

    int o = 0;
    for (int i = 1; i <= n*n; i++) {
