    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            if (i + 1 < n) g[i][j].pb(edge(i + 1, j, 1));
            if (i - 1 >= 0) g[i][j].pb(edge(i - 1, j, 1));
            if (j + 1 < n) g[i][j].pb(edge(i, j + 1, 1));
            if (j - 1 >= 0) g[i][j].pb(edge(i, j - 1, 1));
        }
    }

    int ans = 0;

    for (int k = 0; k < n * n; ++k) {

        int now = need[k];

        int i = (now - 1) / n;
        int j = now - i * n - 1;

        bfs(i, j);

        int now_ans = 1e9;
        for (int i = 0; i < n; ++i) {
            now_ans = min(now_ans, d[0][i]);
            now_ans = min(now_ans, d[n - 1][i]);
            now_ans = min(now_ans, d[i][0]);
            now_ans = min(now_ans, d[i][n - 1]);
        }

        ans += now_ans;

        if (i + 1 < n) {
            for (int k = 0; k < (int)g[i + 1][j].size(); ++k) {
                if (g[i + 1][j][k].a == i && g[i + 1][j][k].b == j) {
                    g[i + 1][j][k].len = 0;
                }
            }
        }
        if (i - 1 >= 0) {
            for (int k = 0; k < (int)g[i - 1][j].size(); ++k) {
                if (g[i - 1][j][k].a == i && g[i - 1][j][k].b == j) {
                    g[i - 1][j][k].len = 0;
                }
            }
        }
        if (j + 1 < n) {
            for (int k = 0; k < (int)g[i][j + 1].size(); ++k) {
                if (g[i][j + 1][k].a == i && g[i][j + 1][k].b == j) {
                    g[i][j + 1][k].len = 0;
                }
            }
        }
        if (j - 1 >= 0) {
            for (int k = 0; k < (int)g[i][j - 1].size(); ++k) {
                if (g[i][j - 1][k].a == i && g[i][j - 1][k].b == j) {
                    g[i][j - 1][k].len = 0;
                }
            }
        }

    }
    cout << ans;
    return 0;
}

