unordered_set<int> g[MID];
long long r;
int fs(int x) {
  if (p[x]!=x) p[x]=fs(p[x]);
  return p[x];
}
int un(int i, int j) {
  if (g[i].size()<g[j].size()) {
    for (auto it=g[i].begin(); it!=g[i].end(); it++) g[j].insert(*it);
    p[i]=j;
    return j;
  }
  for (auto it=g[j].begin(); it!=g[j].end(); it++) g[i].insert(*it);
  p[j]=i;
  return i;
}
int main() {
  scanf("%d",&n); m=n*n;
  for (i=1; i<=m; i++) scanf("%d",&a[i]);
  for (i=1; i<=n; i++) for (j=1; j<=n; j++) {
    cur=(i-1)*n+j;
    pr[i][j]=cur;
    p[cur]=cur;
    v[cur]=1;
  }
  for (i=0; i<=n; i++) for (j=0; j<=n; j++) {
    cur=fs(pr[i][j]);
    for (e=2; e<4; e++) {
      nx=i+dx[e];
      ny=j+dy[e];
      nxt=fs(pr[nx][ny]);
      if (cur!=nxt) {
        g[cur].insert(nxt);
        g[nxt].insert(cur);
      }
    }
  }
  q[fi=MID]=0;
  for (fr=MID+1; fi<fr; ) {
    x=q[fi++];
    //printf("initial d[%d] = %d\n",x,d[x]);
    for (auto it=g[x].begin(); it!=g[x].end(); it++) {
      y=*it;
      if (d[y]==0 && y>0) {
        d[y]=d[x]+v[y];
        if (v[y]) q[fr++]=y; else q[--fi]=y;
      }
    }
  }
  for (i=1; i<=m; i++) {
    x=(a[i]-1)/n+1;
