    rep(i,n+2){
        rep(j,n+2){
            f[i][j]  = min(min(i,n+1-i),min(j,n+1-j));
            use[i][j] = 0;
        }
    }
    int ans = 0;

    int dx[4] = {-1, 1, 0, 0};
    int dy[4] = {0, 0, -1, 1};

    int pp[n*n];
    rep(i,n*n)cin >> pp[i];

    rep(i,n*n){
        int p = pp[i];
        p--;
        int a = p/n + 1;
        int b = p%n + 1;
        ans += f[a][b] - 1;
        rep(j,4){
            f[a][b] = min(f[a][b], f[a+dx[j]][b+dy[j]]);
        }
        queue<P> que;
        que.push(P(a,b));
        while(que.size()){
            int x = que.front().first;
            int y = que.front().second;
            que.pop();
            rep(j,4){
                int nx = x+dx[j], ny = y+dy[j];
                if(use[nx][ny] == 1){
                    if(f[x+dx[j]][y+dy[j]] > f[x][y]){
                        f[x+dx[j]][y+dy[j]] = f[x][y];
