 int N; 
vi cost;
vector<bool> occ;

void dfs(int curr, int c, bool first=true) {
    if (curr <= 0 || curr > N*N) return; // out of the square
    if (!first && cost[curr] <= c) return; // do not yield improvements

    cost[curr] = c;

    c += occ[curr];
    if (curr%N != 0) dfs(curr+1 , c, false); // cell to the right
    if (curr%N != 1) dfs(curr-1, c, false); // cell to the left
    dfs(curr+N, c, false);
    dfs(curr-N, c, false);
}

void solve() {
    cin >> N;
    cost = vi(N*N+1);
    occ = vector<bool>(N*N+1, true);

    // assign cost
    for (int i=0; i<N; ++i) for (int j=0; j<N; ++j) {
            cost[i*N+j+1] = min(min(i, N-i-1), min(j, N-j-1));
    }

    ll ans = 0;
    for (int i=0; i<N*N; ++i) {
