using namespace std;

vector<vector<int>> a, cost;

vector<int> dx = {0, 0, 1, -1};
vector<int> dy = {1, -1, 0, 0};

int n;

void update(int x, int y) {
	int tot = a[x][y] + cost[x][y];
	for(int i=0; i<4; i++) {
		int nx = x + dx[i], ny = y + dy[i];
		if(nx < 0 || ny < 0 || nx >= n || ny >= n)
			continue;
		if(a[nx][ny] > tot) {
			a[nx][ny] = tot;
			update(nx, ny);
		}
	}
}

void run() {
	int i, j, p;
	cin >> n;
	a.resize(n, vector<int>(n, 0));
	cost.resize(n, vector<int>(n, 1));
	for(i=0; i<n; i++)
		for(j=0; j<n; j++)
			a[i][j] = min({i, j, n - i - 1, n - j - 1});
	int ret = 0;
	for(i=0; i<n*n; i++) {
		cin >> p;
		int x = (p - 1) / n;
		int y = (p - 1) % n;
		ret += a[x][y];
		cost[x][y] = 0;
		update(x, y);
	}
	cout << ret << endl;
}

int main() {
	ios::sync_with_stdio(false);
	cin.tie(0);		
	run();
}

