bool occupied[502][502];
ll temp[502][502];
bool passed[502][502];

ll n;
ll dx[4]={1,0,-1,0}; ll dy[4]={0,1,0,-1};

ll bfs(ll x,ll y){
    fill(passed[0],passed[0]+502*502,false);
    priority_queue<vector<ll>> que;

    vector<ll> v={0,x,y};
    que.push(v);
    passed[x][y]=true;

    while(que.size()){
        vector<ll> t=que.top(); que.pop();

        if(t[1]==0||t[1]==n+1||t[2]==0||t[2]==n+1){
            return -t[0];
        }//終了条件
        for(ll i=0;i<4;i++){ //tについて探索
            ll xx=t[1]+dx[i];
            ll yy=t[2]+dy[i];
            if(!passed[xx][yy]){
                que.push({t[0]-occupied[xx][yy],xx,yy});
                passed[xx][yy]=true;
            }
        }
    }
    return 0;
}

int main(){
	cin >> n;
    ll a[n*n];
    ll ans=0;
    fill(occupied[0],occupied[0]+502*502,false);
    fill(temp[0],temp[0]+502*502,n/2+1);
    for(ll i=1;i<=n;i++){
        for(ll j=1;j<=n;j++){
            occupied[i][j]=true;
        }
    }
    for(ll i=0;i<n*n;i++){
        cin >> a[i];
    }
    for(ll i=0;i<n*n;i++){
        ll x=0,y=1;
        while(a[i]>n){
            a[i]-=n;
            y++;
        }
        x=a[i];
        occupied[x][y]=false;
        ans= ans + bfs(x,y);
    }
    cout << ans << endl;
}

