            while(!que.empty()){
                int whe = que.front();
                que.pop();
                seen[whe] = 1;
                if(zero[whe]){
                    mindist = l;
                    break;
                }
                if(whe<=2*N){
                    chmin(mindist,l + sit[whe - N]);
                }else{
                    if(seen[whe-N]!=1){
                        if(sit[whe-N]==1){
                            next.push(whe-N);
                        }else{
                            que.push(whe-N);
                        }
                    }
                }
                if(whe>N*(N-2)){
