                        if(sit[whe+N]==1){
                            next.push(whe+N);
                        }else{
                            que.push(whe+N);
                        }
                    }
                }
                if(whe%N == 2){
                    chmin(mindist,l + sit[whe - 1]);
                }else{
                    if(seen[whe-1]!=1){
                        if(sit[whe-1]==1){
                            next.push(whe-1);
