void solution() {
  int n;
  cin >> n;
  vector<vector<int> > dist(n, vector<int>(n));
  vector<vector<int> > mat(n, vector<int>(n));
  ii pos[n * n];
  int val = 0;
  for (int i = 0; i < n; i++) {
    for (int j = 0; j < n; j++) {
      mat[i][j] = val;
      pos[val++] = ii(i, j);
      dist[i][j] = min(i, n - 1 - i);
      dist[i][j] = min(dist[i][j], min(j, n - 1 - j));
    }
  }

  function<bool(int&, int&)> valid = [&](int& a, int& b) {
    return a >= 0 && b >= 0 && a < n && b < n;
  };

  function<void(ii)> update = [&](const ii x) {
    int dx[] = {1, 0, -1, 0};
    int dy[] = {0, 1, 0, -1};

    for (int i = 0; i < 4; i++) {
      int nx = x.ff + dx[i];
      int ny = x.ss + dy[i];
      if (!valid(nx, ny)) continue;
      if (dist[x.ff][x.ss] + (mat[x.ff][x.ss] != -1) < dist[nx][ny]) {
        dist[nx][ny] = dist[x.ff][x.ss] + (mat[x.ff][x.ss] != -1);
        update(ii(nx, ny));
      }
    }
  };

  int ans = 0;
  for (int i = 0; i < n * n; i++) {
    int x;
    cin >> x;
    x--;
    ans += dist[pos[x].ff][pos[x].ss];
    mat[pos[x].ff][pos[x].ss] = -1;
    update(pos[x]);
  }
  cout << ans << endl;
}

int32_t main() {
  DESYNC;
  solution();
}

