const int maxn = 511;
int n, p[maxn * maxn], dist[maxn][maxn], a[maxn][maxn];

void update(int x, int y)
{
	std::deque<pii> q;
	static int mark[maxn][maxn], timer;
	timer++;
	q.emplace_back(x, y);
	a[x][y] = 0;
	while(!q.empty())
	{
		int x = q.front().ff, y = q.front().ss; q.pop_front();
		if(mark[x][y] == timer) continue;
		mark[x][y] = timer;
		if(dist[x-1][y] > dist[x][y] + a[x][y])
		{
			dist[x-1][y] = dist[x][y] + a[x][y];
			if(a[x][y]) q.emplace_back(x-1, y);
			else q.emplace_front(x-1, y);
		}
		if(dist[x+1][y] > dist[x][y] + a[x][y])
		{
			dist[x+1][y] = dist[x][y] + a[x][y];
			if(a[x][y]) q.emplace_back(x+1, y);
			else q.emplace_front(x+1, y);
		}
		if(dist[x][y-1] > dist[x][y] + a[x][y])
		{
			dist[x][y-1] = dist[x][y] + a[x][y];
			if(a[x][y]) q.emplace_back(x, y);
			else q.emplace_front(x, y-1);
		}
		if(dist[x][y+1] > dist[x][y] + a[x][y])
		{
			dist[x][y+1] = dist[x][y] + a[x][y];
			if(a[x][y]) q.emplace_back(x, y);
			else q.emplace_front(x, y+1);
		}
	}
}
