vector<vector<long>> grid;
vector<vector<bool>> occupied;

void dfs(long row, long col, long val) {
    if (!occupied[row][col] && grid[row][col] > val) {
        grid[row][col] = val;
        dfs(row + 1, col, val);
        dfs(row - 1, col, val);
        dfs(row, col + 1, val);
        dfs(row, col - 1, val);
    }
}  

int main() {
    ios::sync_with_stdio(false);
