void Visit(int Vcnt, int Id, int InitPnt, int y, int x)
{
	int VisitID = VisitTable[N_CEN + y - InitPnt][N_CEN + x - InitPnt] / 1000;
	int VisitCnt = VisitTable[N_CEN + y - InitPnt][N_CEN + x - InitPnt] % 1000;

	if (VisitID == Id && VisitCnt <= Vcnt)
		return;
	VisitTable[N_CEN + y - InitPnt][N_CEN + x - InitPnt] = Id * 1000 + Vcnt;

	if (Recur_Result != -1)
		if (Recur_Result <= Vcnt)
			return;

	if (Seat[N_CEN + y - InitPnt][N_CEN + x - InitPnt] == 0)
	{
		Recur_Result = Vcnt;
		return;
	}

	if (Seat[N_CEN + y - InitPnt][N_CEN + x - InitPnt] < 0)
	{
		Vcnt--;
		//Recur_Result = -Seat[N_CEN + y - InitPnt][N_CEN + x - InitPnt] + Vcnt;
		//return;
	}
	Visit(Vcnt + 1, Id, InitPnt, y, x + 1);
	Visit(Vcnt + 1, Id, InitPnt, y, x - 1);
	Visit(Vcnt + 1, Id, InitPnt, y + 1, x);
	Visit(Vcnt + 1, Id, InitPnt, y - 1, x);


}

