using namespace std;

const int maxN = 1 << 9;

int dist[maxN][maxN], oc[maxN][maxN], n;

void dfs(int i, int j)
{
	static int di[4] = {-1, 0, 1, 0};
	static int dj[4] = {0, 1, 0, -1};
	int d = dist[i][j] + oc[i][j];
	FOR(k, 0, 4)
	{
		int a = i + di[k];
		int b = j + dj[k];
		if (a >= 0 and a < n and b >= 0 and b < n and dist[a][b] > d)
			dist[a][b] = d, dfs(a, b);
	}
}

void solve()
{
	scanf ("%d", &n);
	FOR(i, 0, n) FOR(j, 0, n)
		dist[i][j] = min({i, j, n-1-i, n-1-j}), oc[i][j] = 1;

	long long res = 0;
	FOR(_, 0, n*n)
	{
		int a;
		scanf ("%d", &a);
		a--;
		int i = a / n, j = a % n;

		res += dist[i][j];
		oc[i][j] = 0;
		dfs(i, j);
	}

	printf("%lld\n", res);
}

