namespace n91 {

usize nxtp2(const usize n) {
  usize ret = 1;
  while (ret < n) {
    ret *= 2;
  }
  return ret;
}

struct my_deque {
  const usize m;
  std::vector<usize> c;
  usize f, b;

  my_deque(usize n) : m(nxtp2(n) - 1), c(m + 1), f(0), b(0) {}

  void push_front(const usize x) {
    --f;
    c[f & m] = x;
  }
  void push_back(const usize x) {
    c[b & m] = x;
    ++b;
  }

  usize pop_front() {
    ++f;
    return c[(f - 1) & m];
  }

  bool empty() { return f == b; }
};

void main_() {
  //*
  std::ios::sync_with_stdio(false);
  std::cin.tie(nullptr);
