  const usize m = n * n;

  std::vector<usize> dist(2 * m, 0);
  struct edge {
    usize to;
    usize cost;
  };
  auto g = md_vec(m * 2, 0, edge());
  for (const usize i : rep(0, m)) {
    const usize x = i % n;
    const usize y = i / n;
    dist[2 * i] = std::min({x, n - x - 1, y, n - y - 1});
    dist[2 * i + 1] = dist[2 * i] + 1;
    g[2 * i].push_back({2 * i + 1, 1});
    if (x != 0) {
      g[2 * i + 1].push_back({2 * (i - 1), 0});
    }
    if (x + 1 != n) {
      g[2 * i + 1].push_back({2 * (i + 1), 0});
    }
    if (y != 0) {
      g[2 * i + 1].push_back({2 * (i - n), 0});
    }
    if (y + 1 != n) {
      g[2 * i + 1].push_back({2 * (i + n), 0});
    }
  }

  u64 ans = 0;

  my_deque deq(m * 2);

  for (const usize loop : rep(0, m)) {
    const usize p = scan<usize>() - 1;

    { /*
       for (const auto i : rep(0, n)) {
         for (const auto j : rep(0, n)) {
           std::cout << dist[(i * n + j) * 2] << " ";
         }
         std::cout << eoln;
       }
       std::cout << eoln;
     */
    }

    ans += dist[2 * p];

    g[2 * p][0].cost = 0;

    deq.push_back(2 * p);
    while (!deq.empty()) {
      const usize v = deq.pop_front();
      const usize c = dist[v];

      for (const auto &e : g[v]) {
        if (dist[e.to] > c + e.cost) {
          dist[e.to] = c + e.cost;
          if (e.cost == 0) {
            deq.push_front(e.to);
