      if(x[1]%n==0) m_ans=0-x[0];
      if(x[1]%n==n-1) m_ans=0-x[0];
      if(m_ans==-1) {
        if(mitan[x[1]+1]&&ng[x[1]+1]) aaa.push({x[0]-1,x[1]+1});
        if(mitan[x[1]+1]&&!(ng[x[1]+1])) aaa.push({x[0],x[1]+1});
        if(mitan[x[1]+1]) mitan[x[1]+1]=false;

        if(mitan[x[1]-1]&&ng[x[1]-1]) aaa.push({x[0]-1,x[1]-1});
        if(mitan[x[1]-1]&&!(ng[x[1]-1])) aaa.push({x[0],x[1]-1});
