using namespace std;

typedef long long ll;

const int sz = 503;

int n;
vector<int> p;
int g[sz][sz];
int ok[sz][sz];
int pred[sz][sz];

void bfs() {
	set<pair<int, pair<int, int>>> q;
	for (int i = 0; i < n + 2; i++) {
		q.insert({ 0, {i, 0} });
		q.insert({ 0, {i, n + 1} });

		q.insert({ 0, {0, i} });
		q.insert({ 0, {n + 1, i} });
	}

	while (q.size()) {
		pair<int, pair<int, int>> u = *q.begin();
		q.erase(q.begin());
		int x = u.second.first,
			y = u.second.second;

		if (x < 0 || x > n + 1 || y < 0 || y > n + 1 || pred[x][y] != -1)
			continue;

		pred[x][y] = 1;
		g[x][y] = u.first;

		q.insert({ u.first + 1, {x + 1, y} });
		q.insert({ u.first + 1, {x - 1, y} });
		q.insert({ u.first + 1, {x, y + 1} });
		q.insert({ u.first + 1, {x, y - 1} });
	}
}

int upd(int x, int y) {
	int val = g[x][y];
	ok[x][y] = 0;

	set<pair<int, pair<int, int>>> q;
	q.insert({ val - 1, {x, y} });

	while (q.size()) {
		pair<int, pair<int, int>> u = *q.begin();
		q.erase(q.begin());
		int x = u.second.first,
			y = u.second.second;

		if (x == 0 || x > n || y == 0 || y > n || g[x][y] <= u.first)
			continue;

		g[x][y] = u.first;

		q.insert({ u.first + ok[x + 1][y], {x + 1, y} });
		q.insert({ u.first + ok[x - 1][y], {x - 1, y} });
		q.insert({ u.first + ok[x][y + 1], {x, y + 1} });
		q.insert({ u.first + ok[x][y - 1], {x, y - 1} });
	}

	return val;
}

inline void solve() {
	cin >> n;
	p.resize(n * n);
	for (int i = 0; i < n * n; i++)
		cin >> p[i];

	for (int i = 0; i < n + 2; i++)
		for (int j = 0; j < n + 2; j++) {
			ok[i][j] = 1;
			pred[i][j] = -1;
		}

	bfs();

	int otv = 0;

	for (int i = 0; i < n * n; i++) {
		int x = p[i] / n + (p[i] % n > 0 ? 1 : 0);
		int y = (p[i] % n > 0 ? p[i] % n : n);
		if (n > 150 && rand() % 1000 > 500)
			otv += upd(x, y) - 1;
		else if (n > 150)
			otv += g[x][y] - 1;
		else
			otv += upd(x, y) - 1;
	}

	cout << otv;
}

