            Union(p, q);
        }
        int ROOT = getroot(decode);
        ans += min({  a[ROOT].l - 1, n - a[ROOT].r, n - a[ROOT].d, a[ROOT].u-1 });
    }
    cout << ans;

    return 0;
}

