const int N = 510;

int n;

int oc[N][N];
int dd[N][N];

int dx[] = {1, -1, 0, 0};
int dy[] = {0, 0, 1, -1};

bool nm(int x, int y) {
	return x >= 0 && y >= 0 && x < n && y < n;
}

void dfs(int x, int y) {
	for (int d = 0; d < 4; ++d) {
		int nx = x + dx[d];
		int ny = y + dy[d];
		if (nm(nx, ny) && dd[nx][ny] > dd[x][y] + oc[x][y]) {
			dd[nx][ny] = dd[x][y] + oc[x][y];
			dfs(nx, ny);
		}
	}
}

int main() {
	ios_base::sync_with_stdio(false), cin.tie(0), cout.tie(0);
	cout.setf(ios::fixed), cout.precision(20);
	cin >> n;
	for (int i = 0; i < n; ++i) {
		for (int j = 0; j < n; ++j) {
			oc[i][j] = 1;
			dd[i][j] = min({i, j, n - 1 - i, n - 1 - j});
		}
	}
	int ans = 0;
	for (int it = 0; it < n * n; ++it) {
		int pp;
		cin >> pp;
		--pp;
		int x = pp / n;
		int y = pp % n;
		ans += dd[x][y];
		oc[x][y] = 0;
		dfs(x, y);
	}
	cout << ans << "\n";
	return 0;
}

