int dijkstra(int s,int N)
    {
        int cnt=INF;
        vector<int> dis((N+2)*(N+2),INF);
        dis[s]=0;
        priority_queue<pair<int,int>,vector<pair<int,int>>,greater<pair<int,int>>> que;
        que.push(mp(dis[s],s));
        int u,v;
        while (!que.empty())
        {
            u=que.top().se;
            //cout << u << endl;
            que.pop();
            vector<int> around={u-1,u+1,u+N+2,u-N-2};
            int x;
            for (int i=0;i<4;i++)
            {
                x=around[i];
                //cout << x <<"x"<< endl;
                if (dis[x]>dis[u]+graph[u][x])
                {
                    dis[x]=dis[u]+graph[u][x];
                    if (1<=x%(N+2) &&x%(N+2)<=N && N<x && (N+2)*(N+1)>x) que.push(mp(dis[x],x));
                    else
                    {
                        cnt=min(cnt,dis[x]);
                    }
                }
            } 
        }
        return cnt;
    }
int main()
{
    int N;cin >> N;
    FOR(i,0,(N+2)*(N+2)) FOR(j,0,(N+2)*(N+2)) graph[i][j]=1;
    FOR(i,1,N+1)
    {
        graph[i][i+N+2]=0;
        graph[i+N+2][i]=0;
        graph[(N+2)*i][(N+2)*i+1]=0;
        graph[(N+2)*i+1][(N+2)*i]=0;
        graph[N+1+(N+2)*i][N+(N+2)*i]=0;
        graph[N+(N+2)*i][N+1+(N+2)*i]=0;
        graph[N*N+2*N+i][N*N+3*N+i+2]=0;
        graph[N*N+3*N+i+2][N*N+2*N+i]=0;
    }
    vector<int> line(N*N);
    for (int i=0;i<N*N;i++)
    {
        cin >> line[i];
    }
    int ans=0;
    for (int i=0;i<N*N;i++)
    {
        int s,t,start;
        s=(line[i]-1)/N+1;
        t=line[i]%N;
        start=(N+2)*s+t;
        //cout << start << endl;
