        if (min(x + dx[d], y + dy[d]) < 0) continue;
        if (max(x + dx[d], y + dy[d]) >= N) continue;
        int t = now + 2;
        if (!on[x + dx[d]][y + dy[d]]) t--;
        if (seat[x + dx[d]][y + dy[d]] == t) {
          seat[x + dx[d]][y + dy[d]]--;
          q.emplace(x + dx[d], y + dy[d]);
        }
      }
    }
  }

  cout << ans << endl;
}

