int ok(int i, int j) {
	return i >= 0 && j >= 0 && i < n && j < n;
}

signed main() {
	ios_base::sync_with_stdio(false);
	cin.tie(0);	

	cin >> n;
	for (int i = 0; i < n * n; i++) {
		cin >> p[i];
		p[i]--;
	}
	for (int i = 0; i < n; i++) {
		for (int j = 0; j < n; j++) {
			ans[i][j] = min(min(i, n - 1 - i), min(j, n - 1 - j));
			sel[i][j] = 1;
		}
	}
	int res = 0;
	for (int l = 0; l < n * n; l++) {
		int i = p[l] / n;
		int j = p[l] % n;
		sel[i][j] = 0;
