        answer += d[i0][j0];
        occ[i0][j0] = 0;
        priority_queue<pair<int, pair<int, int>>> q;
        q.emplace(-d[i0][j0], make_pair(i0, j0));
        while (!q.empty()) {
            i0 = q.top().second.first;
            j0 = q.top().second.second;
            int val = -q.top().first;
            q.pop();
            for (int idx = 0; idx < 4; idx++) {
                int i = i0 + ip[idx];
                int j = j0 + jp[idx];
                if (i < 0 || i >= n || j < 0 || j >= n)
                    continue;
                if (d[i][j] > val) {
                    d[i][j] = val;
                    int newVal = val + occ[i][j];
                    q.emplace(-newVal, make_pair(i, j));
                }
            }
        }
    }
    printf("%d\n", answer);
}

