        // cout << "st : " << st.first << ", " << st.second << endl;
        vector<vector<int>> cmp(n, vector<int>(n, -1));
        cmp.at(st.first).at(st.second) = 0;
        queue<pii> q;
        q.push(st);
        int num = mp.at(st.first).at(st.second);
        int mcost = static_cast<int>(500*500+5);
        while(!q.empty())
        {
            if(mcost == 0) break;
            pii cp = q.front();
            q.pop();
            // cout << '(' << cp.first << ", " << cp.second << ")\n";
            if(cp.first == 0 || cp.first == n-1 || cp.second == 0 || cp.second == n-1)
            {
                mcost = min(mcost, cmp.at(cp.first).at(cp.second));
                // cout << mcost << '\n';
                continue;
            }
            for(int i=0, j=-1, k=0; k<4; j+=i, i=j-i, j=i-j, k++)
            {
                int ni = i + cp.first;
                int nj = j + cp.second;
                // cout << ni << ", " << nj << endl;
                int nc = cmp.at(cp.first).at(cp.second) + (num < mp.at(ni).at(nj) ? 1 : 0);
