    if(i<=n) return 0;
    else return i-n;
}

ll down(ll i){
    if(i>n*n-n) return 0;
    else return i+n;
}

ll left(ll i){
    if(i%n==1) return 0;
    else return i-1;
}

ll right(ll i){
    if(i%n==0) return 0;
    else return i+1;
}

