        }     
    }
}

void closer(int n){
    for(ll i=1;i<=n*n;i++){
        ll u=i,c1=0,ans=INF;
        u=i;
        while(u){
            u=right(u);
            c1++;
        }
        ans=min(c1,ans);
        u=i;
        c1=0;
        while(u){
            u=left(u);
            c1++;
        }
        ans=min(c1,ans);
        u=i;
        c1=0;
        while(u){
            u=up(u);
            c1++;
        }
        ans=min(c1,ans);
        u=i;
        c1=0;
        while(u){
            u=down(u);
            c1++;
        }
        ans=min(c1,ans);
        close[i]=ans-1;
    }
}

