using namespace std;

int minHates(const vector<vector<int> >& seats, int startr, int startc) {
    int N = seats.size();
    queue<int> que;
    vector<vector<int> > arrived(N, vector<int>(N, 0));

    queue<pair<int, int> > nextSearch;
    nextSearch.push(make_pair(startr, startc));
    arrived[startr][startc] == 1;
    for (int nbHates = 0; nbHates < N; ++nbHates) {
        queue<pair<int, int> > que = nextSearch;
        queue<pair<int, int> >().swap(nextSearch);
        while (!que.empty()) {
            int r = que.front().first;
            int c = que.front().second;
            que.pop();
            if (r == 0 || r == N - 1 || c == 0 || c == N - 1) {
                return nbHates;
            }

            if (arrived[r + 1][c] == 0) {
                arrived[r + 1][c] = 1;
                (seats[r + 1][c] == 0 ? que : nextSearch).push(make_pair(r + 1, c));
            }
            if (arrived[r - 1][c] == 0) {
                arrived[r - 1][c] = 1;
                (seats[r - 1][c] == 0 ? que : nextSearch).push(make_pair(r - 1, c));
            }
            if (arrived[r][c + 1] == 0) {
                arrived[r][c + 1] = 1;
                (seats[r][c + 1] == 0 ? que : nextSearch).push(make_pair(r, c + 1));
            }
            if (arrived[r][c - 1] == 0) {
                arrived[r][c - 1] = 1;
                (seats[r][c - 1] == 0 ? que : nextSearch).push(make_pair(r, c - 1));
            }
        }
    }
}

void Main() {
    int N;
    cin >> N;
    int N2 = N * N;
    vector<int> P(N2, 0);
    for (int i = 0; i < N2; ++i) {
        cin >> P[i];
        P[i] -= 1;
    }

    int ans = 0;
    vector<vector<int> > seats(N, vector<int>(N, 1));
    for (int i = 0; i < N2; ++i) {
        int p = P[i];
        int r = p / N;
        int c = p % N;
        seats[r][c] = 0;
        ans += minHates(seats, r, c);
    }
    cout << ans << endl;
}

