queue<pair<int,int>> que0,que1;
void bfs(int s,int n){
    for(int i=0;i<4;i++){
        int nw = s + dd[i];
        if(nw<0 || nw>=n*n) continue;
        que0.push({d[s],nw});
    }
    while(que0.size() || que1.size()){
        while(que0.size()){
            auto p = que0.front(); que0.pop();
            int pos = p.second,dist = p.first;
            if(d[pos]<=dist) continue;
            d[pos] = dist;
            for(int i=0;i<4;i++){
                int nw = pos + dd[i];
                if(nw<0 || nw>=n*n) continue;
                if(mp[pos]==1) que1.push({dist + 1,nw});
                else que0.push({dist,nw});
            }
        }
        if(que1.size()){
            auto p = que1.front(); que1.pop();
            int pos = p.second,dist = p.first;
            if(d[pos]<=dist) continue;
            d[pos] = dist;
            for(int i=0;i<4;i++){
                int nw = pos + dd[i];
                if(nw<0 || nw>=n*n) continue;
                if(mp[pos]==1) que1.push({dist + 1,nw});
                else que0.push({dist,nw});
            }
        }
    }
}
