int calc(int id){
  int i,j;
  tie(i,j) = rm[id];
  deque<pair<int,int>> q;
  vector<vector<int>> dist(n+2,vector<int>(n+2,1e6));
  for(int i = 1;i<=n;i++){
    q.push_back({0,i});
    q.push_back({i,0});
    q.push_back({n+1,i});
    q.push_back({i,n+1});
    dist[0][i] = 0;
    dist[i][0] = 0;
    dist[n+1][i] = 0;
    dist[i][n+1] = 0;
  }
  while(!q.empty()){
    auto u = q.front();
    q.pop_front();
    for(int k = 0; k<4; k++){
      int ni  = u.first+dx[k];
      int nj = u.second + dy[k];
      if(isvalid(ni,nj)){
        if(dist[ni][nj]>dist[u.first][u.second]+cost[ni][nj]){
          dist[ni][nj] = dist[u.first][u.second]+cost[ni][nj];
          if(cost[ni][nj] == 0){
            q.push_front({ni,nj});
          }
          else{
            q.push_back({ni,nj});
          }
        }
      }
    }
  }
  return dist[i][j];
}
