int dp[502][502];
bool has[502][502];

int dy4[] = { -1, 0, 1, 0 };
int dx4[] = { 0, 1, 0, -1 };

signed main() {
	INIT;

	VAR(int, n);
	VEC(int, p, n * n);
	REP(i, n * n) --p[i];

	REP(i, n) REP(j, n) has[i][j] = true;
	FILL(dp, INFINT);
	REP(i, n) REP(j, n) CHMIN(dp[i][j], i + 1);
	REP(i, n) REP(j, n) CHMIN(dp[i][j], n  - i);
	REP(i, n) REP(j, n) CHMIN(dp[i][j], j + 1);
	REP(i, n) REP(j, n) CHMIN(dp[i][j], n - j);

	int ans = 0;
	REP(idx, n * n) {
		int pi = p[idx] / n, pj = p[idx] % n;
		ans += dp[pi][pj] - 1;
		dp[pi][pj] = INFINT;
		has[pi][pj] = false;
		REP(d, 4) {
			int dy = pi + dy4[d];
			int dx = pj + dx4[d];
			if (!IN(0, dy, n) || !IN(0, dx, n)) {
				dp[pi][pj] = 0;
				break;
			}
			CHMIN(dp[pi][pj], dp[dy][dx]);
		}
		std::deque<PAIR> deq({ PAIR(pi, pj) });
		while (!deq.empty()) {
			PAIR now = deq.front(); deq.pop_front();
			REP(d, 4) {
				int dy = now.first + dy4[d];
				int dx = now.second + dx4[d];
				if (!IN(0, dy, n) || !IN(0, dx, n)) continue;
				int cost = dp[now.first][now.second] + has[dy][dx];
				if (dp[dy][dx] > cost) {
					dp[dy][dx] = cost;
					if (has[dy][dx]) deq.emplace_back(dy, dx);
					else deq.emplace_front(dy, dx);
				}
			}
		}
	}
	OUT(ans)BR;

	return 0;
}

