struct pnt{
    int y,x,cost;
};

vector<vector<int>> mv={{1,0},{-1,0},{0,1},{0,-1}};

int N;
int bfs(int y, int x, vector<vector<int>> &grid, vector<vector<int>> &attend){
    queue<pnt> que;
    attend[y][x]=0;
    que.push({y,x,grid[y][x]-1});
    while((int)que.size()>0){
        pnt now=que.front();
        que.pop();

        if(grid[now.y][now.x]>now.cost){
            grid[now.y][now.x]=now.cost;
        }else{
            continue;
        }

        for(auto &m:mv){
            int ny, nx;
            ny=now.y+m[0];
            nx=now.x+m[1];

            if(ny<0 || nx<0 || ny>N-1 || nx>N-1){
                continue;
            }else{
                que.push({ny,nx,now.cost+attend[ny][nx]});
            }
        }
    }
}

