void walk(int x,int y){
	if(x>1&&dis[x-1][y]>dis[x][y]+vis[x-1][y])add(x-1,y,dis[x][y]+vis[x-1][y]);
	if(y>1&&dis[x][y-1]>dis[x][y]+vis[x][y-1])add(x,y-1,dis[x][y]+vis[x][y-1]);
	if(x<n&&dis[x+1][y]>dis[x][y]+vis[x+1][y])add(x+1,y,dis[x][y]+vis[x+1][y]);
	if(y<n&&dis[x][y+1]>dis[x][y]+vis[x][y+1])add(x,y+1,dis[x][y]+vis[x][y+1]);
}
