struct UnionFind{
    vector<int> par;
    vector<ll> S;

    UnionFind(int N):par(N),S(N){
        rep(i,N){
          par[i] = i;
          S[i] = 1;
        }
    }

    int root(int x){
       while(x != par[x]){
        x =  par[x] = par[par[x]];
       }
       return x;
    }

    bool same(int x,int y){
      return root(x) == root(y);
    }

    void unite(int x,int y){
        int rx = root(x);
        int ry = root(y);
        if(!same(x,y)){
            S[root(x)] += S[root(y)];
            S[root(y)] = S[root(x)];
        }
        if(rx == ry)return;
        if(S[x] >= S[y]){
          par[ry] = rx;
        }else{
          par[rx] = ry;
        }
    }

    ll SIZE(int x){
        return S[root(x)];
    }
};

