inline void init_uf() {
    rep(i, UF_NUM) {
        parent[i] = i;
    }
}

inline li find(li x) {
    if (parent[x] == x)return x;
    else return (parent[x] = find(parent[x]));
}

inline li findVal(li x) {
    auto p = find(x);
    return value[p];
}

inline void union_(li x, li y) {
    li parent_x = find(x);
    li parent_y = find(y);
    value[parent_y] = min(value[parent_x], value[parent_y]);
    parent[parent_x] = parent_y;
}

inline PI toPos(li x) {
    return {x / n, x % n};
}

inline li fromPos(PI p) {
    return p.F * n + p.S;
}

