int main() {
    const ll inf = 5e15;
    ll dh[] = { 1, 0, -1, 0, };
    ll dw[] = { 0, 1, 0, -1, };

    ll n;
    std::cin >> n;
    vec<ll> pv(n * n);
    for (ll &e : pv) {
        std::cin >> e;
        e--;
    }

    auto make_id = [&](ll i, ll j) {
        return n * i + j;
    };

    auto valid = [&](ll i, ll j) {
        return 0 <= i && i < n &&
               0 <= j && j < n;
    };

    vec<ll> dists(n * n, inf);

    vec<bool> used(n * n, true);
    auto bfs = [&](std::queue<ll> &que) {
        while (que.size()) {
            ll cur = que.front();
            que.pop();
            for (ll i = 0; i < 4; i++) {
                ll nh = cur / n + dh[i], nw = cur % n + dw[i];
                if (!valid(nh, nw)) continue;
                ll nid = make_id(nh, nw);
                ll nd = dists[cur] + used[cur];
                if (nd < dists[nid]) {
                    dists[nid] = nd;
                    que.push(nid);
                }
            }
        }
    };

    {
        std::queue<ll> que;
        for (ll i = 0; i < n; i++) for (ll j = 0; j < n; j++) {
            if (i == 0 || i == n - 1 || j == 0 || j == n - 1) {
                dists[make_id(i, j)] = 0;
                que.push(make_id(i, j));
            }
        }
        bfs(que);
    }

    ll ans = 0;
    for (ll e : pv) {
        ans += dists[e];
        used[e] = false;
        std::queue<ll> que;
        que.push(e);
        bfs(que);
    }

    std::cout << ans << "\n";
    return 0;
}

