ii uf[505][505];
int sz[505][505];
bool ok[505][505];

ii find(int x, int y) {
  if (uf[x][y] == ii(x, y))
    return ii(x, y);
  else
    return uf[x][y] = find(uf[x][y].ff, uf[x][y].ss);
}

bool merge(int a, int b, int c, int d) {
  ii x = find(a, b);
  ii y = find(c, d);

  if (x == y) return false;
  if (sz[x.ff][x.ss] < sz[y.ff][y.ss]) swap(x, y);
  uf[y.ff][y.ss] = uf[x.ff][x.ss];
  sz[x.ff][x.ss] += sz[y.ff][y.ss];
  ok[x.ff][x.ss] |= ok[y.ff][y.ss];
  return true;
}

void solution() {
  int n;
  cin >> n;
  int mat[n + 2][n + 2];
  int dst[n + 2][n + 2];
  bool zero_path[n + 2][n + 2];
  vector<ii> pos(n * n + 1);
  int val = 1;
  for (int i = 1; i <= n; i++) {
    for (int j = 1; j <= n; j++) {
      pos[val] = ii(i, j);
      mat[i][j] = val++;
      zero_path[i][j] = false;
    }
  }

  for (int i = 0; i <= n + 1; i++) {
    mat[0][i] = mat[i][0] = mat[i][n + 1] = mat[n + 1][i] = -1;
    zero_path[0][i] = zero_path[i][0] = zero_path[i][n + 1] =
        zero_path[n + 1][i] = true;
  }

  for (int i = 0; i <= n + 1; i++) {
    for (int j = 0; j <= n + 1; j++) {
      dst[i][j] = INF;
      uf[i][j] = ii(i, j);
      sz[i][j] = 1;
      ok[i][j] = zero_path[i][j];
    }
  }

  int ans = 0;
  for (int i = 0; i < n * n; i++) {
    int st;
    cin >> st;
    int x = pos[st].ff;
    int y = pos[st].ss;
    vector<ii> vis;
    deque<ii> q;
    q.push_back(ii(x, y));
    vis.pb(ii(x, y));
    dst[x][y] = 0;
    while (q.size() > 0) {
      int cx = q.front().ff;
      int cy = q.front().ss;
      q.pop_front();

      ii grp = find(cx, cy);
      if (ok[grp.ff][grp.ss]) {
        ans += dst[cx][cy];
        break;
      }

      if (cx == 0 || cx == n + 1 || cy == 0 || cy == n + 1) {
        ans += dst[cx][cy];
        break;
      }

      // move
      if (dst[cx][cy] + (mat[cx + 1][cy] != -1) < dst[cx + 1][cy]) {
        dst[cx + 1][cy] = dst[cx][cy] + (mat[cx + 1][cy] != -1);
        vis.pb(ii(cx + 1, cy));
        if (mat[cx + 1][cy] == -1)
          q.push_front(ii(cx + 1, cy));
        else
          q.push_back(ii(cx + 1, cy));
      }

      if (dst[cx][cy] + (mat[cx - 1][cy] != -1) < dst[cx - 1][cy]) {
        dst[cx - 1][cy] = dst[cx][cy] + (mat[cx - 1][cy] != -1);
        vis.pb(ii(cx - 1, cy));
        if (mat[cx - 1][cy] == -1)
          q.push_front(ii(cx - 1, cy));
        else
          q.push_back(ii(cx - 1, cy));
      }

      if (dst[cx][cy] + (mat[cx][cy + 1] != -1) < dst[cx][cy + 1]) {
        dst[cx][cy + 1] = dst[cx][cy] + (mat[cx][cy + 1] != -1);
        vis.pb(ii(cx, cy + 1));
        if (mat[cx][cy + 1] == -1)
          q.push_front(ii(cx, cy + 1));
        else
          q.push_back(ii(cx, cy + 1));
      }

      if (dst[cx][cy] + (mat[cx][cy - 1] != -1) < dst[cx][cy - 1]) {
        dst[cx][cy - 1] = dst[cx][cy] + (mat[cx][cy - 1] != -1);
        vis.pb(ii(cx, cy - 1));
        if (mat[cx][cy - 1] == -1)
          q.push_front(ii(cx, cy - 1));
        else
          q.push_back(ii(cx, cy - 1));
      }
    }
    for (ii p : vis) dst[p.ff][p.ss] = INF;
    mat[x][y] = -1;
    if (mat[x - 1][y] == -1) merge(x - 1, y, x, y);
    if (mat[x + 1][y] == -1) merge(x + 1, y, x, y);
    if (mat[x][y - 1] == -1) merge(x, y - 1, x, y);
    if (mat[x][y + 1] == -1) merge(x, y + 1, x, y);
  }
  cout << ans << endl;
}

