ll n,ans=0;
bool s[510][510];
ll visited[510][510];
ll memo[510][510];
void dfs(ll x,ll y){
    if (x==0 or y==0 or x==n-1 or y==n-1){
        ans=min(ans,visited[x][y]);
    }else{
        for (ll i=0;i<4;i++){
            ll a=x+dx[i],b=y+dy[i];
            if (a>=0 and a<n and b>=0 and b<n and visited[a][b]>visited[x][y]){
                if (s[a][b]){
                    if (visited[a][b]==visited[x][y]+1)continue;
                    visited[a][b]=visited[x][y]+1;
                    if (ans<visited[a][b])dfs(a,b);
                }else{
                    visited[a][b]=visited[x][y];
                    if (ans<visited[a][b])dfs(a,b);
                }
            }
        }
    }
}

int main(){
    cin >> n;
    for (ll i=0;i<n;i++)fill(memo[i],memo[i]+n,INF);
    ll p[n*n],c=0;
    for (ll i=0;i<n*n;i++){
        cin >> p[i];
    }
    for (ll i=0;i<n;i++)fill(s[i],s[i]+n,true);
    for (ll i=0;i<n*n;i++){
        ans=INF;
        ll x=(p[i]-1)/n,y=(p[i]-1)%n;
        for (ll i=0;i<n;i++)fill(visited[i],visited[i]+n,INF);
        s[x][y]=false;
        visited[x][y]=0;
        for (ll i=0;i<4;i++){
            ll a=x+dx[i],b=y+dy[i];
            if (a>=0 and a<n and b>=0 and b<n){
                ans=min(memo[a][b],ans);
            }
        }
        dfs(x,y);
        c+=ans;
        memo[x][y]=ans;
    }
    cout << c << endl;
    return 0;
}

