void dfs(int i, int j, int N, vector<bools> &exist, mat &dp){
    int t = 0;
    if(exist[i][j]) t++;

    REP(k, 4){
        int x = i + dx[k], y = j + dy[k];
        if(0 <= x && x < N && 0 <= y && y < N && dp[x][y] > dp[i][j] + t){
            dp[x][y] = dp[i][j] + t;
            dfs(x, y, N, exist, dp);
        }
    }
}

