void getXY(int a, int &x, int &y) {
	x = a / n;
	y = a % n;
}

bool valid(int x, int y) {
	return (x >= 0 && x < n && y >= 0 && y < n);
}

void bfs(int x, int y) {
	// printf("bfs(%d, %d)\n", x, y);
	queue<int> qx, qy;
	qx.push(x); qy.push(y);
	inq[x][y] = true;
	st[x][y] = 0;
	while (!qx.empty() && !qy.empty()) {
		int x = qx.front(), y = qy.front();
		// printf("bfs at (%d, %d)\n", x, y);
		qx.pop(); qy.pop();
		int upd = h[x][y] + st[x][y];
		for (int i = 0; i < 4; ++i) {
			int xx = x + dx[i], yy = y + dy[i];
			if (!valid(xx, yy) || h[xx][yy] <= upd) {
				continue;
			}
			h[xx][yy] = upd; 
			if (!inq[xx][yy]) {
				qx.push(xx); qy.push(yy);
				inq[xx][yy] = true;
			}
		}
		inq[x][y] = false;
	}
}

