typedef struct UnionFindTree{
    vector<int> par;
    vector<lint> val;

    UnionFindTree(int n){
        par.resize(n, -1);
        val.resize(n, 0);
    }

    void set_val(int i, lint x){
        val[i] = x;
    }

    bool is_root(int x){
        return par[x]<0;
    }

    int find(int x){
        if(is_root(x)) return x;
        return par[x] = find(par[x]);
    }

    int size(int x){
        return -par[find(x)];
    }

    lint get_val(int x){
        return val[find(x)];
    }

    bool unite(int x, int y){
        x = find(x);
        y = find(y);
        if(x == y) return false;
        if(size(x) < size(y)) swap(x, y);
        par[x] += par[y];
        chmin(val[x], val[y]);
        par[y] = x;
        return true;
    }

    bool same(int x, int y){
        return find(x) == find(y);
    }
}UF;

