struct UnionFind{
  ll N;
  llvec p;
  llvec cnt;
  UnionFind(ll n){
    N = n;
    p=llvec(N);
    cnt=llvec(N, 0);
    rep(i, N){
      p[i] = i;
      cnt[i] = 1;
    }
  }

  void con(ll a, ll b){
    P at = root(a);
    P bt = root(b);
    if(at.second!=bt.second){
      if(at.first>bt.first){
        swap(at, bt);
        swap(a, b);
      }
      p[at.second] = bt.second;
      cnt[bt.second]+=cnt[at.second];
      p[a]=bt.second;
    }
  }

  P root(ll a){
    ll atmp = a;
    ll c=0;
    while(atmp!=p[atmp]){
      atmp = p[atmp];
      c++;
    }
    p[a] = atmp;
    return {c, atmp};
  }

  bool is_con(ll a, ll b){
    P at=root(a);
    P bt=root(b);
    return at.second == bt.second;
  }

};

struct dijkstra{
  ll N;
  llvec d;
  vector<vector<edge>> e;
  set<ll> S;
  dijkstra(ll n){
    N = n;
    //d = llvec(N, 1e18);
    e = vector<vector<edge>>(N);
  }

  void add_edge(ll from, ll to, ll cost){
    e[from].push_back({to, cost});
  }
  void add_edge_both(ll from, ll to, ll cost){
    e[from].push_back({to, cost});
    e[to].push_back({from, cost});
  }

  ll chk(){
    ll tmp = 1e18;
    ll n = sqrt(N);
    rep(i, n){
      tmp = min(tmp, d[i]);
      tmp = min(tmp, d[N-1-i]);
      tmp = min(tmp, d[n*i]);
      tmp = min(tmp, d[n*i+(n-1)]);
    }
    return tmp;
  }

  void run(ll start){
    priority_queue<P, vector<P>, greater<P>> que;
    que.push({0, start});
    d = llvec(N, 1e18);
    d[start]=0;
    while(!que.empty()){
      P q = que.top();que.pop();
      ll dc = q.first;
      ll x = q.second;
      if(dc>d[x]){
        continue;
      }else{
        for(auto ip: e[x]){
          ll c = (S.count(ip.x)>0?0:1);
          //cout << ip.x << " " << c << endl;
          if(d[ip.x]<=d[x]+c){
            continue;
          }else{
            d[ip.x]= d[x]+c;
            que.push({d[ip.x], ip.x});
          }
        }
      }
    }
  }  
};


