	q0.push(x);
	int u;
	while (!q0.empty() or !q1.empty()) {
		if (q0.empty()) u = q1.front(), q1.pop();
		else u = q0.front(), q0.pop();
		if (u == g.last) {
			g.w[x] = false;
			return dist[u];
		}
		each(v, g.adj[u]) {
			if (visit[v]) continue;
			visit[v] = true;
			dist[v] = dist[u] + g.w[v];
			g.w[v] ? q1.push(v) : q0.push(v);
		}
	}
	return 0;
}

