int dijkstra(int x, int y, vector<string> s){
    auto cmp = [](Piii a, Piii b){return a.first>b.first;};
    priority_queue<Piii,vector<Piii>,decltype(cmp)> pq(cmp);
    vector<vector<int>> dist(N,vector<int>(N,1000));
    dist[x][y] = 0;
    pq.emplace(0,make_pair(x,y));
    while(!pq.empty()){
        int cost;
        pii cur;
        tie(cost,cur) = pq.top();
        pq.pop();
        if(cur.first==0 || cur.first==N-1 || cur.second==0 ||cur.second==N-1 ) return cost;
        if(dist[cur.first][cur.second]<cost) continue;
        for (int k = 0; k < 4; k++)
        {
            int nx = cur.first+dx[k];
            int ny = cur.second+dy[k];
            int nc = cost;
            if(nx<0 || nx>=N) continue;
            if(ny<0 || ny>=N) continue;
            if(s[nx][ny]=='#') nc++;
            if(dist[nx][ny]<=nc) continue;
            dist[nx][ny]=nc;
            pq.emplace(nc,make_pair(nx,ny));
        }
    }
    return dist[0][0];
}

