int N;
vi a;
int dr[4] = { -1, 0, 1, 0 },
    dc[4] = { 0, 1, 0, -1 };

int mp[500][500][4];
int minimum[500][500];
int popu[500][500];

using P = tuple<int,int,int,int>;
deque<P> q;

inline void qpush(int val, int r, int c, int side){
    if (q.empty()){
        q.push_back({val, r, c, side});
    } else {
        int o_v,o_r,o_c,o_s;
        tie(o_v,o_r,o_c,o_s) = q.front();
        if (o_v == val){
            q.emplace_front(val, r, c, side);
        } else {
            q.emplace_back(val, r, c, side);
        }
    }
}

inline void propagate(int r, int c, int newv) {
    rep(side,4){
        int ri = r+dr[side], ci = c+dc[side];
        int contre = (side + 2)%4;
        if (IN(ri,0,N-1) && IN(ci,0,N-1)){
            if (mp[ri][ci][contre] > newv) {
                qpush(newv, ri, ci, contre);
            }
        }
    }
}

ll solve() {
    int L = N*N;
    rep(i,L) a[i]--;

    rep(r,N) rep(c,N) {
        rep(side,4) { mp[r][c][side] = INT_MAX; }
        minimum[r][c] = INT_MAX;
        popu[r][c] = 1;
    }

    rep(i,N){
        qpush(0, 0,   i, 0);
        qpush(0, N-1, i, 2);
        qpush(0, i, 0,   3);
        qpush(0, i, N-1, 1);
    }
    while (!q.empty()){
        int val,r,c,side;
        tie(val,r,c,side) = q.front(); q.pop_front();


        if (val >= mp[r][c][side]) continue;
        mp[r][c][side] = val;

        if (val >= minimum[r][c]) continue;
        minimum[r][c] = val;



        propagate(r,c, minimum[r][c] + popu[r][c]);
    }

    int ans = 0;
    rep(i,L){
        int r=a[i]/N, c=a[i]%N;

        ans += minimum[r][c];


        propagate(r,c, minimum[r][c]);

        while (!q.empty()){
            int val,r,c,side;
            tie(val,r,c,side) = q.front();
            q.pop_front();


            if (val >= mp[r][c][side]) continue;
            mp[r][c][side] = val;

            if (val >= minimum[r][c]) continue;
            minimum[r][c] = val;

            propagate(r, c, minimum[r][c] + popu[r][c]);
        }
        popu[r][c] = 0;
    }
    return ans;
}

int main() {
    scanf("%d%*c", &N);
    loadvec(a, N*N);

    cout << solve() << endl;
    return 0;
}

