LL n;
LL getf(LL x){
	if(x == f[x]) return x;
	return f[x] = getf(f[x]);
}

void mergee(LL x,LL y){
	x = getf(x); y = getf(y);
	if(x == y) return;
	f[x] = y; val[y] = min(val[x],val[y]);
}

LL id(LL x,LL y){
	return (x - 1) * n + y;
}

int main(){
	LL p,ans = 0;
	cin >> n;
	for(LL i = 1;i <= n;i ++){
		for(LL j = 1;j <= n;j ++){
			f[id(i,j)] = id(i,j);
			val[id(i,j)] = min(min(j - 1,n - j),min(i - 1,n - i));
//			cout << val[id(i,j)] << (j == n ? '\n' : ' ');
		}
	}
	for(LL i = 1;i <= n * n;i ++){
		cin >> p; vis[p] = 1;
		if(p % n != 0 && vis[p + 1]) mergee(p,p + 1);
		if(p % n != 1 && vis[p - 1]) mergee(p,p - 1);
		if(p / n != 0) if(vis[p - n]) mergee(p,p - n);
		if(p / n != n - 1 && vis[p + n]) mergee(p,p + n);
		ans += val[getf(p)];
	}
	cout << ans << '\n';
	return 0;
}

