int N, Cost[505][505];
bool occupy[505][505];
int di[4] = {0,1,0,-1}, dj[4] = {1,0,-1,0};

int DFS(int i, int j){
  int now = Cost[i][j] + occupy[i][j];
  for (int k = 0; k < 4; k++){
    int I = i + di[k], J = j + dj[k];
    if (1 <= I && I <= N && 1 <= J && J <= N){
      if (Cost[I][J] > now){
        Cost[I][J] = now;
        DFS(I, J);
      }
    }
  }
  return 0;
}

int main(){
  cin >> N;
  for (int i = 1; i <= N; i++){
    for (int j = 1; j <= N; j++){
      Cost[i][j] = min(min(i, N + 1 - i), min(j, N + 1 - j)) - 1;
      occupy[i][j] = true;
    }
  }

  int ans = 0;
  for (int i = 0; i < N * N; i++){
    int P; cin >> P;
    int I = (P + N - 1) / N, J = P % N;
    if (J == 0) J = N;
    ans += Cost[I][J];
    occupy[I][J] = false;
    DFS(I, J);
  }
  cout << ans << endl;

  return 0;
}

