// index が条件を満たすかどうか
bool isOK(vector<int> &v, int index, int key) {
    if (v[index] >= key) return true;
    else return false;
}

int bsearch(vector<int> &v, int key) {
    int ng = -1;
    int ok = (int)v.size();

    while (abs(ok - ng) > 1) {
        int mid = (ok + ng) / 2;

        if (isOK(v, mid, key)) ok = mid;
        else ng = mid;
    }
    return ok;
}

int n,p,result;
int main() {
    cin.tie(0); ios::sync_with_stdio(false); cout << fixed << std::setprecision(20);

