        x[i / n].push_back(i);
        y[i % n].push_back(i);
    }
    for(int i = 0; i < n * n; i++) {
        cin >> p;
        p--;
        auto&& col = x[p / n];
        auto&& row = y[p % n];
        auto&& itrx = lower_bound(col.begin(), col.end(), p);
        if(itrx == col.end()) itrx = col.begin();
        int ix = distance(col.begin(), itrx);
        auto&& itry = lower_bound(row.begin(), row.end(), p);
        if(itry == row.end()) itry = row.begin();
        int iy = distance(row.begin(), itry);
        result += min(ix, min(iy, min((int)col.size() - ix - 1, (int)row.size() - iy - 1)));
        col.erase(itrx);
        row.erase(itry);
    }

    cout << result;
}

