                bfs.push(P(nowi, nowj+1));
                q.push(P(nowi, nowj+1));
                check[nowi][nowj+1] = true;
            }
            if(now.first && vvv[nowi-1][nowj]) {
                if(check[nowi-1][nowj]) continue;
                q.push(P(nowi-1, nowj));
                check[nowi-1][nowj] = true;
            }
            if(nowj && vvv[nowi][nowj-1]) {
                if(check[nowi][nowj-1]) continue;
                q.push(P(nowi, nowj-1));
                check[nowi][nowj-1] = true;
            }
            if(now.first < n-1 && vvv[nowi+1][nowj]) {
                if(check[nowi+1][nowj]) continue;
                q.push(P(nowi+1, nowj));
                check[nowi+1][nowj] = true;
            }
            if(nowj < n-1 && vvv[nowi][nowj+1]) {
                if(check[nowi][nowj+1]) continue;
                q.push(P(nowi, nowj+1));
                check[nowi][nowj+1] = true;
            }
        }
        while(!bfs.empty()) {
