            bfs.pop();
            fun[now.first][now.second]--;
            if(!fun[now.first][now.second]) {
                cou--;
            }
        }
        if(fun[i][j]) {
            cou--;
            fun[i][j];
        }
        vvv[i][j]=1;
    }

