bool valid(int x, int y) {
	return 0 <= x and x < n and 0 <= y and y < n;
}

constexpr int sides = 4;
array<int, sides> dx = {0, 1, 0, -1},
				  dy = {1, 0, -1, 0};

void update(int x, int y) {
	int mn = n;
	REP(s, sides) {
		int xx = x + dx[s],
			yy = y + dy[s];
		if(valid(xx, yy))
			mn = min(mn, dist[xx][yy]);
		else
			mn = 0;
	}
	if(dist[x][y] > mn + nonfree[x][y]) {
		dist[x][y] = mn + nonfree[x][y];
		REP(s, sides) {
			int xx = x + dx[s], yy = y + dy[s];
			if(valid(xx, yy))
				update(xx, yy);
		}
	}
