const int N = 505;
int dis[N][N];
bool emp[N][N];
int n;

void relax(int si, int sj) {
  deque<PII> ord;
  ord.emplace_back(si, sj);
  while (!ord.empty()) {
    auto [i, j] = ord.front(); ord.pop_front();
    for (int ii: {i - 1, i, i + 1}) {
      for (int jj: {j - 1, j, j + 1}) {
        if (abs(i - ii) + abs(j - jj) != 1) continue;
        if (ii < 1 || ii > n || jj < 1 || jj > n) continue;
        if (dis[ii][jj] > dis[i][j] + !emp[i][j]) {
          dis[ii][jj] = dis[i][j] + !emp[i][j];
          if (emp[i][j]) {
            ord.emplace_front(ii, jj);
          } else {
            ord.emplace_back(ii, jj);
          }
        }
      }
    }
  }
}

