    idxEdge.push_back(i+N*(N-1));
  }
  for (int i = 1; i <= (N-2); i++) {
    idxEdge.push_back(i*N);
    idxEdge.push_back(i*N + (N-1));
  }


  int ans = 0;
  rep(Z, N*N) {
