        e[i].push_back((edge){left,isSit[left]});
      }
      if (i%N != (N-1)) {
        int right = i+1;
        e[i].push_back((edge){right,isSit[right]});
      }
    }


    vector<int> d(N*N);
    dijkstra(p, d, e);
    int tmp = INF;
    for (int x : idxEdge) tmp = min(tmp, d[x]);

    ans += tmp;

  }

  cout << ans << endl;

  return 0;
}

