int d[N][N];
int used[N][N][2];

vi di = {0, 0, -1, 1};
vi dj = {-1, 1, 0, 0};

const int oo = 1e9 + 10;

void smain() {
    int n;
    cin >> n;
    fori (i, n) {
        fori (j, n) {
            taken[i][j] = true;
        }
    }
    ll ans = 0;
    fori (_, n * n) {

        fori (i, n) {
            fori (j, n) {
                d[i][j] = oo;
                used[i][j][0] = used[i][j][1] = 0;
            }
        }

        int cur;
        cin >> cur;
        cur--;
        int x = cur / n;
        int y = cur % n;
        taken[x][y] = false;
        int ql = MID;
        int qr = MID;
        q[qr++] = {x, y};
        used[x][y][0] = true;
        d[x][y] = 0;
        int cans = n * n;
        while (ql < qr) {
            pii cur = q[ql++];
            int x = cur.first, y = cur.second;
            if (x == 0 || x == n - 1 || y == 0 || y == n - 1) {
                inmin(cans, d[x][y]);
                continue;
            }
            fori (dir, di.size()) {
                int xx = x + di[dir];
                int yy = y + dj[dir];
                if (taken[xx][yy] && !used[xx][yy][1]) {
                    used[xx][yy][1] = true;
                    inmin(d[xx][yy], d[x][y] + 1);
                    q[qr++] = {xx, yy};
                }
                if (!taken[xx][yy] && !used[xx][yy][0]) {
                    used[xx][yy][0] = true;
                    inmin(d[xx][yy], d[x][y]);
                    q[--ql] = {xx, yy};
                }
            }
        }
        ans += cans;
    }

    cout << ans;
}

