struct ufind{
  vector<int> uf;
  ufind(int q){
    uf=vector<int>(q);
    for(int i=0;i<q;i++)uf.at(i)=i;
  }

  ufind(vector<int> q){
   uf=q; 
  }

  void stick(int a,int b){
    if(a==b)return;
    a =fpe(a);
    b =fpe(b);
    int minx=(a<b)?a:b;
    uf.at(a)=minx;
    uf.at(b)=minx;
  }

  int fpe(int a){
   return (uf.at(a)==a)?a:uf.at(a)=fpe(uf.at(a));
  }

  bool find(int a,int b){
    if(a==b)return true;
    return fpe(a)==fpe(b);
  }


};



