template <typename T, typename S, typename R>
ll pow_mod(T p, S q, R mod = 1ll)
{
    ll ret = 1, r = p;
    while (q)
    {
        if (q % 2)
            ret *= r, ret %= mod;
        r = (r * r) % mod, q /= 2;
    }
    return ret % mod;
}

void make_frac_tables(VL &frac_list, VL &frac_inv_list)
{
    rep(i, frac_list.size() - 1)
    {
        frac_list[i + 1] *= frac_list[i] * (i + 1);
        frac_list[i + 1] %= mod;
        frac_inv_list[i + 1] *= frac_inv_list[i] * pow_mod(i + 1, mod - 2, mod);
        frac_inv_list[i + 1] %= mod;
    }
}

ll comb(int a, int b, const VL &frac_list, const VL &frac_inv_list)
{
    if (a < b)
        return 0;
    ll ret = frac_list[a];
    ret *= frac_inv_list[b];
    ret %= mod;
    ret *= frac_inv_list[a - b];
    ret %= mod;
    return ret;
}

class Weited_Unionfind
{
    vector<int> p;
    vector<int> dist;
    VVI children;

public:
    int find(int x);
    void unite(int x, int y);
    bool isunion(int x, int y);
    Weited_Unionfind(int n);
    int showdist(int n);
    void setdist(int n, int x);
    void showall();
};

Weited_Unionfind::Weited_Unionfind(int n)
{
    children.resize(n);
    for (int i = 0; i < n; i++)
    {
        p.emplace_back(i);
        dist.emplace_back(0);
        children[i].emplace_back(i);
    }
}
int Weited_Unionfind::find(int x)
{
    while (p[x] != x)
    {
        p[x] = p[p[x]];
        x = p[x];
    }
    return x;
}

void Weited_Unionfind::setdist(int n, int x)
{
    dist[n] = x;
}

int Weited_Unionfind::showdist(int n)
{
    int pn = find(n);
    return dist[pn];
}

void Weited_Unionfind::unite(int x, int y)
{
    int px, py, bigtree, smalltree;
    px = Weited_Unionfind::find(x);
    py = Weited_Unionfind::find(y);
    if (px == py)
        return;

    bigtree = (children[px].size() >= children[py].size() ? px : py);
    smalltree = (bigtree == px ? py : px);
    p[smalltree] = bigtree;
    dist[bigtree] = min(dist[smalltree], dist[bigtree]);

    for (int z : children[smalltree])
    {
        children[bigtree].emplace_back(z);
        p[z] = bigtree;
    }
    children[smalltree].clear();
}

void Weited_Unionfind::showall()
{
    show1dvec(dist);
    show1dvec(p);
}



