ll Find(ll u){
    if (lab[u] < 0) return u;
    return lab[u] = Find(lab[u]);
}
void Union(ll r,ll s){
    lab[s] = max(lab[s],lab[r]);
    lab[r] = s;
}
bool check(ll x,ll y){
    return (x <= n&&y <= n&&x >= 1&&y >= 1);
}
ll trans(ll x,ll y){
    return (x - 1)*n + y;
