            ll x = min(min(abs(i - 1),abs(i - n)),min(abs(j - 1),abs(j - n)));
            lab[trans(i,j)] = -x - 1;
        }
    }
    //cout<<lab[6]<<"\n";
    ll ans = 0;

    for (i = 1;i <= n*n;i++){
        ll p = a[i];
