                if(nni < 0 or nnj < 0 or nni > n-1 or nnj > n-1) continue;
                if(used[nni][nnj]) continue;
                if(mat[nni][nnj] > val) {
                    mat[nni][nnj] = val;
                    que.push_back(P(nni, nnj));
                    used[nni][nnj] = true;
                }
            }
            ++v;
        }

