      }
  }
  fn(i,n*n)
  {
      pp temp=mp[p[i]];
      ll r=temp.fi;ll c=temp.se;
      ll count_less=0,count_big=0;
      row[r].pb(c);
      col[c].pb(r);
      fn(j,row[r].size())
      {
          if(c>row[r][j])count_less++;
          else if(c<row[r][j]) count_big++;
      }
     // debug3(r,c,p[i]);
     // debug2(count_less,count_big);
     ll re=MM;
      if(count_less==(c-1) || count_big==(n-c))continue;
