int a[501][501], n, men, viewers;

int moveLeftRight(int i, int j) {
  int left = 0, right = 0;
  for (int k = 1; k <= n; k++) {
    if (k < j && a[i][k] != 0)
      left++;
    else if (k > j && a[i][k] != 0)
      right++;
  }
  return min(left, right);
}

int moveUpDown(int i, int j) {
  int up = 0, down = 0;
  for (int k = 1; k <= n; k++) {
    if (k < i && a[k][j] != 0)
      up++;
    else if (k > i && a[k][j] != 0)
      down++;
  }
  return min(up, down);
}

