using namespace std;

using ll = long long;

constexpr char newl = '\n';
constexpr int dh[] = {1, -1, 0, 0};
constexpr int dw[] = {0, 0, 1, -1};

void bfs(int src, int n, const vector<int>& ex, vector<int>& cost) {
    deque<int> q;
    q.push_back(src);

    while (!q.empty()) {
        int cur = q.front();
        int ch = cur / n, cw = cur % n;
        q.pop_front();

        for (int i = 0; i < 4; ++i) {
            int nh = ch + dh[i], nw = cw + dw[i];
            if (nh < 0 || nh >= n || nw < 0 || nw >= n) continue;

            int nex = nh * n + nw;
            int new_cost = cost[cur] + ex[cur];
            if (cost[nex] <= new_cost) continue;

            cost[nex] = new_cost;
            if (ex[cur]) q.push_back(nex);
            else q.push_front(nex);
        }
    }
}

int main() {
    cin.tie(nullptr);
    ios::sync_with_stdio(false);

    int n;
    cin >> n;

    int m = n * n;
    vector<int> cost(m, 0);
    vector<int> ex(m, true);
    for (int i = 0; i < m; i++) {
        int h = i / n, w = i % n;
        cost[i] = min({h, w, n - 1 - h, n - 1 - w});
    }

    ll ans = 0;
    for (int i = 0; i < m; i++) {
        int p;
        cin >> p;
        --p;

        ans += cost[p];
        ex[p] = false;
        bfs(p, n, ex, cost);
    }
    cout << ans << newl;

    return 0;
}

