            }
        }
    };
    auto unite = [&](int v, int u) -> void {
        if (sets.get(v) == sets.get(u))
            return;
        v = sets.get(v), u = sets.get(u);
        if (gr[v].size() > gr[u].size())
            swap(v, u);
        for (auto i : gr[v]) {
