int main(){
  cin.tie(0); // cut the cin and cout (default, std::flush is performed after std::cin)
  ios::sync_with_stdio(false); // cut the iostream and stdio (DON'T endl; BUT "\n";)

  ll N;
  IN(N);
  vll P(N*N);
  REP(i,N*N){
    IN(P[i]);
    P[i]--;
  }

  vvll Cost(N, vll(N, 0));
  REP(i,N){
    REP(j,N){
      Cost[i][j] = min(min(i, N-1-i), min(j, N-1-j));
    }
  }

  map<pair<pair<ll, ll>, pair<ll, ll>>, ll> mp;
  REP(i,N-1){
    REP(j,N){
      mp[mapa(i, j, i+1, j)] = 1;
      mp[mapa(i+1, j, i, j)] = 1;
      mp[mapa(j, i, j, i+1)] = 1;
      mp[mapa(j, i+1, j, i)] = 1;
    }
  }

  ll ans = 0;

  REP(i,N*N){
    ll Pi = P[i];
    ll x = Pi/N;
    ll y = Pi%N;
    ans += Cost[x][y];

    //debug_print(i, x, y);
    //mat_print(Cost);

    queue<pair<ll, ll>> que;
    set<pair<ll, ll>> used;

    if(x>0){
      mp[mapa(x-1, y, x, y)] = 0;
      que.push(make_pair(x-1, y));
    }
    if(x<N-1){
      mp[mapa(x+1, y, x, y)] = 0;
      que.push(make_pair(x+1, y));
    }
    if(y>0){
      mp[mapa(x, y-1, x, y)] = 0;
      que.push(make_pair(x, y-1));
    }
    if(y<N-1){
      mp[mapa(x, y+1, x, y)] = 0;
      que.push(make_pair(x, y+1));
    }

    while(que.size()){
      auto pos_tmp = que.front(); que.pop();
      ll x_tmp = pos_tmp.first;
      ll y_tmp = pos_tmp.second;
      if(x_tmp<=0 || x_tmp>=N-1 || y_tmp<=0 || y_tmp>=N-1) continue;
      if(used.find(make_pair(x_tmp, y_tmp))!=used.end()) continue;
      used.emplace(make_pair(x_tmp, y_tmp));

      ll New_Cost = INFLL;

      chmin(New_Cost, Cost[x_tmp-1][y_tmp] + mp[mapa(x_tmp, y_tmp, x_tmp-1, y_tmp)]);
      chmin(New_Cost, Cost[x_tmp+1][y_tmp] + mp[mapa(x_tmp, y_tmp, x_tmp+1, y_tmp)]);
      chmin(New_Cost, Cost[x_tmp][y_tmp-1] + mp[mapa(x_tmp, y_tmp, x_tmp, y_tmp-1)]);
      chmin(New_Cost, Cost[x_tmp][y_tmp+1] + mp[mapa(x_tmp, y_tmp, x_tmp, y_tmp+1)]);

      if(New_Cost>=Cost[x_tmp][y_tmp]) continue;

      //debug_print(x_tmp, y_tmp, New_Cost);

      Cost[x_tmp][y_tmp] = New_Cost;

      que.push(make_pair(x_tmp-1, y_tmp));
      que.push(make_pair(x_tmp+1, y_tmp));
      que.push(make_pair(x_tmp, y_tmp-1));
      que.push(make_pair(x_tmp, y_tmp+1));
    }

  }

  OUT(ans);


  return 0;
}

