                if(mp[pos]==1 && d[nw]>dist + 1) que1.push({dist + 1,nw});
                if(mp[pos]==0 && d[nw]>dist) que0.push({dist,nw});
            }
        }
        if(que1.size()){
            auto p = que1.front(); que1.pop();
