int dfs(int l, int r)
{
    priority_queue < pair <int, pair <int,int> > , vector <pair <int, pair <int,int> > > ,compara > q;


    map <  pair <int, pair <int,int> > , bool> ex;


    int ex2[DIM][DIM];


