        for(int j = 1; j <= n; j++)
            ex2[i][j] = INF;

    q.push({0,{l,r}});

    int dist = min(min(min(l - 1 , n - l),r - 1),n - r);

    int ans = INF;

    while(!q.empty())
    {

         if(q.top().first > ans)
                    return ans;

        int nr = q.top().first;
        int l1 = q.top().second.first;
        int r1 = q.top().second.second;
        q.pop();



        if( (l1 == 1) || (l1 == n) || (r1 == 1) || (r1 == n) )
           {
               ans = min(ans,nr);
             if(ans == 0)
                return 0;
           }

