                   {q.push({nr,{l2,r2}});
                    ex[{nr,{l2,r2}}] = true;

                        ex2[l2][r2]= nr;
                   }
                   }
                else
                    if(nr + 1 <= dist)
                    if(ex[{nr + 1,{l2,r2}}] == false && nr + 1 < ex2[l2][r2])
                    {q.push({nr + 1, {l2, r2}});
                     ex[{nr + 1,{l2,r2}}] = true;

                     ex2[l2][r2]=  nr + 1;

                    }
            }
        }


    }



    return ans;


}
