	for(int i=0;i<n;i++){vector<int> m;
	    for(int j=0;j<n;j++){m.push_back(y);y++;}
	    arr.push_back(m);
	}
	long long total=0;
	for(int i=0;i<n*n;i++){
	    int val=order[i];
	    int r=val/n,c=val%n;
	    total+=hate(arr,r,c,n);
	}

	cout<<total;
	return 0;
}

