    BIT<int> b1(N*N+2),b2(N*N+2);
    col.push_back(b1);
    row.push_back(b2);
  }
  rep2(i,1,N*N+1) {
    row[(i+N-1)/N].add(i,1);
    col[(i+2)%N+1].add(i,1);
  }

  int ans=0;
  for (auto i:P) {
