  vector<vector<int>> dist(n, vector<int>(n));
  for (int i = 0; i < n; i++) {
    for (int j = 0; j < n; j++) {
      dist[i][j] = min(min(i, j), min(n - 1 - i, n - 1 - j));
    }
  }
  vector<pair<int, int>> que;
  vector<vector<int>> inq(n, vector<int>(n, 0));
