void update(int** field, int n,int r,int c,int a) {
	bool flag=false;
	if (field[r][c] == -1) {
		flag = true;
		field[r][c] = a;
		v.push_back(make_pair(r, c));
	}
	if (r > 0) {
		if (field[r - 1][c] == -1) {
			update(field, n, r - 1, c, a);
		}
	}
	if (r < n-1) {		
		if(field[r + 1][c] == -1) {
			update(field, n, r + 1, c, a);
		}
	}
	if (c > 0) {
		if (field[r][c - 1] == -1) {
			update(field, n, r, c-1, a);
		}
	}
	if (c < n-1) {
		if (field[r][c+1] == -1) {
			update(field, n, r, c+1, a);
		}
	}
	if (r < n - 1) {
		if (field[r + 1][c] > a) {
			update(field, n, r + 1, c, field[r + 1][c]);
		}
	}
	if (c > 0) {
		if (field[r][c - 1] > a) {
			update(field, n, r, c - 1, field[r][c - 1]);
		}
	}
	if (c < n - 1) {
		if (field[r][c + 1] > a) {
			update(field, n, r, c + 1, field[r][c + 1]);
		}
	}
	if (r > 0) {
		if (field[r - 1][c] > a) {
			update(field, n, r - 1, c, field[r - 1][c]);
		}
	}
	if (!flag) {
		field[r][c]--;
	}
}

int func(int** field, int r, int c,int n) {
	priority_queue<pair<int,pair<int,int>>,vector<pair<int,pair<int,int>>>,greater<pair<int,pair<int,int>>>> pq;
	pair<int, pair<int, int>> now;
	pq.push(make_pair(0, make_pair(r, c)));
	bool** arl = new  bool*[n];
	for (int i = 0;i < n;i++) {
		arl[i] = new bool[n];
		for (int j = 0;j < n;j++) {
			arl[i][j] = false;
		}
	}
	arl[r][c] = true;
	while (1) {
		now = pq.top();
		pq.pop();
		if (now.second.first == 0 || now.second.first == n - 1 || now.second.second == 0 || now.second.second == n - 1) {
			return now.first;
		}
		if (!arl[now.second.first - 1][now.second.second]) {
			pq.push(make_pair(now.first + field[now.second.first - 1][now.second.second], make_pair(now.second.first - 1, now.second.second)));
			arl[now.second.first - 1][now.second.second] = true;
		}
		if (!arl[now.second.first + 1][now.second.second]) {
			pq.push(make_pair(now.first + field[now.second.first + 1][now.second.second], make_pair(now.second.first + 1, now.second.second)));
			arl[now.second.first + 1][now.second.second] = true;
		}
		if (!arl[now.second.first][now.second.second - 1]) {
