int N, P[int(25e4+5)], Dist[505][505];
int di[4] = {0, 1, 0, -1}, dj[4] = {1, 0, -1, 0};
bool visited[505][505], vacant[505][505];

int Calc_Dist(){
  queue <Pii> que;
  for (int i = 0; i < N; i++){
    que.push({0, i}); visited[0][i] = true;
    que.push({i, 0}); visited[i][0] = true;
    que.push({N - 1, i}); visited[N-1][i] = true;
    que.push({i, N - 1}); visited[i][N-1] = true;
  }

  while (!que.empty()){
    Pii Q = que.front(); que.pop();
    for (int k = 0; k < 4; k++){
      int I = Q.fi + di[k], J = Q.se + dj[k];
      if (0 <= I && I < N && 0 <= J && J < N){
        if (!visited[I][J]){
          visited[I][J] = true;
          Dist[I][J] = Dist[Q.fi][Q.se] + 1;
          que.push({I, J});
        }
      }
    }
  }
  return 0;
}

int main(){
  cin >> N;
  Calc_Dist();

  int ans = 0;
  for (int i = 0; i < N * N; i++){

    cin >> P[i];
    int I = (P[i] - 1) / N, J = (P[i] - 1) % N;

    ans += Dist[I][J];
    queue <Pii> que; que.push({I, J});

    while (!que.empty()){
      Pii Q = que.front(); que.pop();
      for (int k = 0; k < 4; k++){
        int II = Q.fi + di[k], JJ = Q.se + dj[k];
        if (0 <= II && II < N && 0 <= JJ && JJ < N){
          if (vacant[II][JJ] || vacant[Q.fi][Q.se]){
            if (Dist[II][JJ] > Dist[Q.fi][Q.se]){
              Dist[II][JJ] = Dist[Q.fi][Q.se];
              que.push({II, JJ});
            }
          }else{
            if (Dist[II][JJ] > Dist[Q.fi][Q.se] + 1){
              Dist[II][JJ] = Dist[Q.fi][Q.se] + 1;
              que.push({II, JJ});
            }
          }
        }
      }
    }
    vacant[I][J] = true;
  }
  cout << ans << endl;

  return 0;
}

