vector<pii> deltas = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}, {0, 0}};

void dfs(int i, int j, int k) {
	graph[i][j][k] = true;
	cur[i][j] = min(cur[i][j], k);
	for (pii d : deltas) {
		int ni = d.first + i;
		int nj = d.second + j;
		int nk = k + cover[i][j];
		if (ni < 0 || ni >= N || nj < 0 || nj >= N || nk >= N) continue;
		if (graph[ni][nj][nk]) continue;
		dfs(ni, nj, nk);
	}	
}

