				if(dis[x][y-1]>=1000) q1[++tail1]=(x-1)*n+y-1,dis[x][y-1]=dis[x][y]+1;
				if(dis[x][y+1]>=1000) q1[++tail1]=(x-1)*n+y+1,dis[x][y+1]=dis[x][y]+1;
			}
		}
	}
