const int N = 505;
const int M = N * N;
int n;
int a[N][N];
pii ord[M];
int dist[N][N];
pii q[M];
int L, R;
bool inQ[N][N];
const int DX[] = {-1, 1, 0, 0};
const int DY[] = {0, 0, -1, 1};

bool checkCell(int x, int y) {
	return min(x, y) >= 0 && max(x, y) < n + 2;
}

void addBack(int x, int y) {
	if (inQ[x][y]) return;
	inQ[x][y] = 1;
	q[R++] = mp(x, y);
	if (R == M) R = 0;
}
void addFront(int x, int y) {
	if (inQ[x][y]) return;
	inQ[x][y] = 1;
	if (L == 0) L = M;
	L--;
	q[L] = mp(x, y);
}

void BFS(int x, int y) {
	//eprintf("BFS %d %d\n", x, y);
	L = R = 0;
	addBack(x, y);
	while(L != R) {
		x = q[L].first;
		y = q[L].second;
		inQ[x][y] = false;
		L++;
		if (L == M) L = 0;
		for (int j = 0; j < 4; j++) {
			int xx = x + DX[j], yy = y + DY[j];
			if (!checkCell(xx, yy)) continue;
			//eprintf("%d %d\n", xx, yy);
			int w = dist[x][y] + a[xx][yy];
			if (dist[xx][yy] <= w) continue;
			dist[xx][yy] = w;
			if (a[xx][yy] == 0)
				addFront(xx, yy);
			else
				addBack(xx, yy);
		}
	}
}

