		ord[i] = mp(x, y);
		a[x][y] = 1;
	}
	for (int x = 0; x < n + 2; x++)
		for (int y = 0; y < n + 2; y++)
			dist[x][y] = N;
	dist[0][0] = 0;
	BFS(0, 0);
	int ans = 0;
	for (int i = 0; i < n * n; i++) {
		int x = ord[i].first, y = ord[i].second;
		a[x][y] = 0;
		dist[x][y]--;
		ans += dist[x][y];
		BFS(x, y);
	}
	printf("%d\n", ans);

	return 0;
}

