void calc(int orig=-1){
  deque<int> Q;
  if(orig == -1){
    for(int i=2; i<N; i++){
      for(int j=2; j<N; j++)
        dp[i][j] = INF;
    }
    for(int i=1; i<=N;i++){
      Q.push_back(i+N+1);
      Q.push_back(i+N*(N+1));
      Q.push_back(1+i*(N+1));
      Q.push_back(N+i*(N+1));
    }
  }
  else{
    Q.push_back(orig);
  }
  while(!Q.empty()){
    int r = Q.front()/(N+1);
    int c = Q.front()%(N+1);
    Q.pop_front();
    if(r > N || r < 1 || c < 1 || c > N)
      continue;
    for(int i=0; i<4; i++){
      if(occ[r][c]){
        if(dp[r+y[i]][c+x[i]] > dp[r][c]+occ[r][c]){
          dp[r+y[i]][c+x[i]] = dp[r][c]+occ[r][c];
          Q.push_back((r+y[i])*(N+1)+c+x[i]);
        }
      }
      else{
        if(dp[r+y[i]][c+x[i]] > dp[r][c]+occ[r][c]){
          dp[r+y[i]][c+x[i]] = dp[r][c]+occ[r][c];
          Q.push_front((r+y[i])*(N+1)+c+x[i]);
        }
      }
    }
  }
}

