    int temp[4];
    fro(int i = 0, x, y; i < n * n; i++){
        scanf("%d", a + i); a[i]--;  x = a[i] / n; y = a[i] % n; x++; y++;
        temp[0] = col[y].query(1, 1, n, 1, x - 1);
        temp[1] = row[x].query(1, 1, n, 1, y - 1);
        temp[2] = col[y].query(1, 1, n, x + 1, n);
        temp[3] = row[x].query(1, 1, n, y + 1, n);
        ans += min(temp[0], min(temp[1], min(temp[2], temp[3])));
        row[x].update(1, 1, n, y, 0);
        col[y].update(1, 1, n, x, 0);
    }
    printf("%d\n", ans);


    return 0;
}

