const ll dx[4] = { 1, 0, -1, 0 }, dy[4] = { 0, 1, 0, -1 };

ll N;
ll P[250010];
ll h[250010];
bool used[250010];

ll bfs( ll i, ll j ) {
  ll ret = h[i*N+j];
  ll nh = h[i*N+j]+used[i*N+j];

  rep( d, 4 ) {
    ll ni = i+dy[d], nj = j+dx[d];

    if( i < 0 || i >= N || j < 0 || j >= N )
      continue;

    if( nh < h[ni*N+nj] ) {
      h[ni*N+nj] = nh;
      bfs( ni, nj );
    }
  }

  return ret;
}

int main()
{
  std::cin >> N;

  rep( i, N*N )
    std::cin >> P[i], --P[i];

  rep( i, N*N ) {
    ll r = i/N, c = i%N;

    h[i] = std::min( { r, N-r-1, c, N-c-1 } );
    used[i] = true;
  }

  ll ans = 0;

  rep( i, N*N ) {
    ll r = P[i]/N;
    ll c = P[i]%N;

    used[i] = false;
    ans += bfs( r, c );
  }

  std::cout << ans << std::endl;

  return 0;
}

