        }
        else
        {
          add = 0;
        }
        if (val.at(row + 1).at(col) > val.at(row).at(col) + add)
        {
          val.at(row + 1).at(col) = val.at(row).at(col) + add;
          next.push_back(std::make_pair(row + 1, col));
        }
      }
      if ((col - 1) >= 0)
      {
        if (sit.at(row).at(col - 1) == true)
        {
          add = 1;
        }
        else
        {
          add = 0;
        }
        if (val.at(row).at(col - 1) > val.at(row).at(col) + add)
        {
          val.at(row).at(col - 1) = val.at(row).at(col) + add;
          next.push_back(std::make_pair(row, col - 1));
        }
      }
      if ((col + 1) < N)
      {
        if (sit.at(row).at(col + 1) == true)
        {
          add = 1;
        }
        else
        {
          add = 0;
        }
        if (val.at(row).at(col + 1) > val.at(row).at(col) + add)
        {
          val.at(row).at(col + 1) = val.at(row).at(col) + add;
          next.push_back(std::make_pair(row, col + 1));
