	for(int i=1;i<=n;i++)for(int j=1;j<=n;j++)
	{
		f[i][j]=i-1;chkmin(f[i][j],n-i);chkmin(f[i][j],j-1);chkmin(f[i][j],n-j);
	}
	for(int i=1;i<=n*n;i++)
	{
		int x=(p[i]-1)/n+1,y=(p[i]-1)%n+1;
		ans+=f[x][y];
