int dis[N][N][N / 2], P[N][N], n, miin[N][N];
int odrad[N][N][N / 2];
int pos[N * N];
vector < pair < pii, int > > Q[N * N];

const int px[4] = {1, -1, 0, 0};
const int py[4] = {0, 0, 1, -1};

inline int get_dis(int x, int y){
	return min(min(x, y), n - max(x, y) - 1);
}

int main(){
	memset(dis, INF, sizeof(dis));

	scanf("%d", &n);
	for(int i = 0;i < n * n;i++){
		int x; scanf("%d", &x); x--;
		P[x % n][x / n] = i;
		miin[x % n][x / n] = get_dis(x % n, x / n);
	}
	for(int i = 0;i < n;i++){
		Q[0].PB({{0, i}, 0});     dis[0][i][0] = 0;
		Q[0].PB({{n - 1, i}, 0}); dis[n - 1][i][0] = 0;	
		Q[0].PB({{i, 0}, 0});     dis[i][0][0] = 0;
		Q[0].PB({{i, n - 1}, 0}); dis[i][n - 1][0] = 0;		
	}
	for(int i = 0;i < n * n;i++){
		for(;pos[i] < (int)Q[i].size();pos[i]++){
			int cx = Q[i][pos[i]].X.X;
			int cy = Q[i][pos[i]].X.Y;
			int ck = Q[i][pos[i]].Y;
			int nova = max(dis[cx][cy][ck], P[cx][cy]);
			if(odrad[cx][cy][ck]) continue;
			odrad[cx][cy][ck] = 1;
			for(int m = 0;m < 4;m++){
				int mx = cx + px[m], my = cy + py[m];
				if(mx < 0 || mx >= n || my < 0 || my >= n) continue;
				if(ck <= miin[mx][my] && nova < dis[mx][my][ck]){
					dis[mx][my][ck] = nova;
					Q[dis[mx][my][ck]].PB({{mx, my}, ck});
				}
				if(ck < miin[mx][my] && dis[cx][cy][ck] < dis[mx][my][ck + 1]){
					dis[mx][my][ck + 1] = dis[cx][cy][ck];
					Q[dis[cx][cy][ck]].PB({{mx, my}, ck + 1});
				}
			}
		}
	}
	int odg = 0;
	for(int i = 0;i < n;i++){
		for(int j = 0;j < n;j++){
			int k = 0;
			for(;dis[i][j][k] > P[i][j];k++);
			odg += k;
		}
	}
	printf("%d\n", odg);
	return 0;
}

