const int INF = 1001001001;
const int dx[] = {1, 0, -1, 0};
const int dy[] = {0, 1, 0, -1};

struct UnionFind {
  vector<int> data;
  vector<int> minv;
  UnionFind(int n) {
    data.assign(n, -1);
    minv.assign(n, INF);
  }
  int root(int k) {
    if (data[k] < 0) return k;
    return data[k] = root(data[k]);
  }
  void unite(int x, int y) {
    x = root(x);
    y = root(y);
    if (x == y) return;
    if (data[x] > data[y]) swap(x, y);
    data[x] += data[y];
    data[y] = x;
    minv[x] = min(minv[x], minv[y]);
  }
  bool same(int x, int y) {
    return root(x) == root(y);
  }
  int size(int k) {
    return -data[root(k)];
  }
  int minvalue(int x) {
    return minv[root(x)];
  }
};

