signed main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);
    cout.tie(nullptr);

    int n, sum = 0;
    cin >> n;
    vector<vector<int>> dp(n, vector<int>(n));
    vector<vector<int>> g(n, vector<int>(n, 1));
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            dp[i][j] = min(min(i, j), min(n - 1 - i, n - 1 - j));
        }
    }

    vector<tuple<int, int>> del = {
            {-1, 0},
            {0,  -1},
            {1,  0},
            {0,  1}
    };

    auto valid = [&](int r, int c) -> bool {
        return 0 <= r && r < n && 0 <= c && c < n;
    };

    auto bfs = [&](int sr, int sc) {
        queue<tuple<int, int>> q;
        q.push({sr, sc});
        int x, y, mx, my, dx, dy;
        while (!q.empty()) {
            tie(x, y) = q.front();
            q.pop();
            int val = dp[x][y] + g[x][y];
            for (auto &i:del) {
                tie(dx, dy) = i;
                mx = x + dx;
                my = y + dy;
                if (valid(mx, my) && val < dp[mx][my]) {
                    dp[mx][my] = val;
                    q.push({mx, my});
                }
            }
        }
    };

    for (int i = 0; i < n * n; ++i) {
        int a;
        cin >> a;
        --a;
        sum += dp[a / n][a % n];
        g[a / n][a % n] = 0;
        bfs(a / n, a % n);
    }
    cout << sum << endl;
}

