using namespace std;

int minHates(const vector<vector<int> >& seats, int startr, int startc, const vector<vector<int> >& hates) {
    int N = seats.size();
    if (startr == 0 || startr == N - 1 || startc == 0 || startc == N - 1) {
        return 0;
    }
    if (seats[startr + 1][startc] == 0 && seats[startr - 1][startc] == 0 && seats[startr][startc + 1] == 0 && seats[startr][startc - 1] == 0) {
        int minHatesAround = min(hates[startr + 1][startc], min(hates[startr - 1][startc], min(hates[startr][startc + 1], hates[startr][startc - 1])));
        if (minHatesAround < N * N) {
            return minHatesAround;
        }
    }

    vector<vector<int> > arrived(N, vector<int>(N, 0));

    queue<pair<int, int> > nextSearch;
    nextSearch.push(make_pair(startr, startc));
    arrived[startr][startc] = 1;
    for (int nbHates = 0; nbHates < N; ++nbHates) {
        queue<pair<int, int> > que = nextSearch;
        queue<pair<int, int> >().swap(nextSearch);
        while (!que.empty()) {
            int r = que.front().first;
            int c = que.front().second;
            que.pop();
            if (r == 0 || r == N - 1 || c == 0 || c == N - 1 || hates[r][c] == 0) {
                return nbHates;
            }

            if (arrived[r + 1][c] == 0) {
                arrived[r + 1][c] = 1;
                (seats[r + 1][c] == 0 ? que : nextSearch).push(make_pair(r + 1, c));
            }
            if (arrived[r - 1][c] == 0) {
                arrived[r - 1][c] = 1;
                (seats[r - 1][c] == 0 ? que : nextSearch).push(make_pair(r - 1, c));
            }
            if (arrived[r][c + 1] == 0) {
                arrived[r][c + 1] = 1;
                (seats[r][c + 1] == 0 ? que : nextSearch).push(make_pair(r, c + 1));
            }
            if (arrived[r][c - 1] == 0) {
                arrived[r][c - 1] = 1;
                (seats[r][c - 1] == 0 ? que : nextSearch).push(make_pair(r, c - 1));
            }
        }
    }
}

void update(const vector<vector<int> >& seats, vector<vector<int> >& hates, int startr, int startc, int h) {
    int N = hates.size();
    queue<pair<int, int> > que;
    vector<vector<int> > arrived(N, vector<int>(N, 0));
    arrived[startr][startc] = 1;
    que.push(make_pair(startr, startc));
    hates[startr][startc] = h;
    while (!que.empty()) {
        int r = que.front().first;
        int c = que.front().second;
        que.pop();

        if (r < N - 1 && arrived[r + 1][c] == 0 && seats[r + 1][c] == 0) {
            arrived[r + 1][c] = 1;
            que.push(make_pair(r + 1, c));
            hates[r + 1][c] = h;
        }
        if (r > 0 && arrived[r - 1][c] == 0 && seats[r - 1][c] == 0) {
            arrived[r - 1][c] = 1;
            que.push(make_pair(r - 1, c));
            hates[r - 1][c] = h;
        }
        if (c < N - 1 && arrived[r][c + 1] == 0 && seats[r][c + 1] == 0) {
            arrived[r][c + 1] = 1;
            que.push(make_pair(r, c + 1));
            hates[r][c + 1] = h;
        }
        if (c > 0 && arrived[r][c - 1] == 0 && seats[r][c - 1] == 0) {
            arrived[r][c - 1] = 1;
            que.push(make_pair(r, c - 1));
            hates[r][c - 1] = h;
        }
    }
}

void Main() {
    int N;
    cin >> N;
    int N2 = N * N;
    vector<int> P(N2, 0);
    for (int i = 0; i < N2; ++i) {
        cin >> P[i];
        P[i] -= 1;
    }

    int ans = 0;
    vector<vector<int> > seats(N, vector<int>(N, 1));
    vector<vector<int> > hates(N, vector<int>(N, N * N));
    for (int i = 0; i < N2; ++i) {
        int p = P[i];
        int r = p / N;
        int c = p % N;
        seats[r][c] = 0;
        int h = minHates(seats, r, c, hates);
        update(seats, hates, r, c, h);
        ans += h;
    }
    cout << ans << endl;
}

