void solve() {
    int n;
    cin >> n;
    vector<vector<int> > d(n, vector<int>(n, n));
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            d[i][j] = min(d[i][j], i);
            d[i][j] = min(d[i][j], j);
            d[i][j] = min(d[i][j], n - 1 - i);
            d[i][j] = min(d[i][j], n - 1 - j);
        }
    }
    vector<vector<int> > used(n, vector<int> (n, 1));
    int p;
    ll res = 0;
    for (int i = 0; i < n * n; ++i) {
        int x, y;
