        x = p / n;
        y = p % n;
        res += d[x][y];
        queue<pii> q;
        q.push(pii(x, y));
        used[x][y] = 0;
        while (!q.empty()) {
            pii pp = q.front();
            x = pp.first, y = pp.second;
            q.pop();
            for (int j = 0; j < 4; ++j) {
                int x1 = x + dx[j];
                int y1 = y + dy[j];
                if ((x1 < 0) || (y1 < 0) || (x1 >= n) || (y1 >= n))
                    continue;
                if (d[x1][y1] > d[x][y] + used[x][y]) {
                    q.push(pii(x1, y1));
                    d[x1][y1] = d[x][y] + used[x][y];
                }
            }
        }
    }
    cout << res << endl;
}

