        pair<int,int> p=que.front();
        que.pop_front();
        int v=p.first;
        int d=p.second;
        if (dist[v]>d){
            dist[v]=d;
        }
        else{
            continue;
        }
        for (int i=0;i<edge[v].size();i++){
            int nv=edge[v][i];
            if (dist[nv]==INF){
                if (v==0){
                  	pair<int,int> p={nv,d};
                    que.push_front(p);
                }
                else{
                    pair<int,int> p={nv,d+1};
                    que.push_back(p);
                }
            }
        }
