using namespace std;
struct UnionFind
{
	vector<int> par; // par[i]:iの親の番号　(例) par[3] = 2 : 3の親が2

	UnionFind(int N) : par(N)
	{ //最初は全てが根であるとして初期化
		for (int i = 0; i < N; i++)
			par[i] = i;
	}

	int root(int x)
	{ // データxが属する木の根を再帰で得る：root(x) = {xの木の根}
		if (par[x] == x)
			return x;
		return par[x] = root(par[x]);
	}

	void unite(int x, int y)
	{					  // xとyの木を併合
		int rx = root(x); //xの根をrx
		int ry = root(y); //yの根をry
		if (rx == ry)
			return;	  //xとyの根が同じ(=同じ木にある)時はそのまま
		par[rx] = ry; //xとyの根が同じでない(=同じ木にない)時：xの根rxをyの根ryにつける
	}

	bool same(int x, int y)
	{ // 2つのデータx, yが属する木が同じならtrueを返す
		int rx = root(x);
		int ry = root(y);
		return rx == ry;
	}
};

int n;
const int N = 555;
int p[N * N];
int cost[N * N];
bool used[N * N];

int getId(int y, int x)
{
	return y * n + x + 1;
}

void init()
{
	cin >> n;
	rep(i, n * n) cin >> p[i];
}

void solve()
{
	UnionFind uf = UnionFind(n * n);
	rep(i, n)
	{
		rep(j, n)
		{
			int id = getId(i, j);
			cost[id] = min(min(i, j), min(n - i - 1, n - j - 1)) + 1;
			//cout << "(" << cost[id] << "," << id << ")";
		}
		//cout << endl;
	}

	int answer = 0;

	// 外側
	cost[0] = 0;
	used[0] = true;

	rep(i, n * n)
	{
		int t = p[i];
		int up = t - n;
		int down = t + n;
		int right = t + 1;
		int left = t - 1;

		used[t] = true;

		int uproot = up >= 1 ? uf.root(up) : 0;
		int downroot = down <= n * n ? uf.root(down) : 0;
		int leftroot = t % n != 1 ? uf.root(left) : 0;
		int rightroot = t % n != 0 ? uf.root(right) : 0;

		int upcost = cost[uproot];
		int downcost = cost[downroot];
		int leftcost = cost[leftroot];
		int rightcost = cost[rightroot];

		int mincost = min(min(upcost, downcost), min(leftcost, rightcost));
		answer += mincost;

		int unite = t;

		if (upcost == mincost)
			unite = uproot;

		if (downcost == mincost)
			unite = downroot;

		if (leftcost == mincost)
			unite = leftroot;

		if (rightcost == mincost)
			unite = rightroot;

		//cout << i << " " << t << " || " << uproot << " " << downroot << " " << leftroot << " " << rightroot << " + " << upcost << " " << downcost << " " << leftcost << " " << rightcost << " yy " << mincost << " " << unite << endl;
		uf.unite(t, unite);

		if (used[uproot])
			uf.unite(uproot, unite);

		if (used[downroot])
			uf.unite(downroot, unite);

		if (used[leftroot])
			uf.unite(leftroot, unite);

		if (used[rightroot])
			uf.unite(rightroot, unite);
	}

	cout << answer << endl;
}

int main()
{
	init();
	solve();
}

