typedef tuple<int, int, int> T;

int dy[4] = {-1, 0, 1, 0};
int dx[4] = {0, 1, 0, -1};
int n;
int p[250000];
int dist[500][500];
bool used[500][500];

signed main() {
	int i, j;

	cin >> n;
	rep(i, n * n) { cin >> p[i]; p[i]--; }
	rep(i, n) rep(j, n) dist[i][j] = min({i, j, n - 1 - i, n - 1 - j});

	int ans = 0;
	rep(i, n * n) {
		int sy = p[i] / n;
		int sx = p[i] % n;
		ans += dist[sy][sx];

		queue<T> que;
		que.push(T(dist[sy][sx], sy, sx));
		used[sy][sx] = true;

		while (!que.empty()) {
			T now = que.front(); que.pop();
			int cst = get<0>(now);
			int y = get<1>(now);
			int x = get<2>(now);
			rep(j, 4) {
				int ny = y + dy[j];	 //next y
				int nx = x + dx[j];
				if (ny < 0 || ny >= n || nx < 0 || nx >= n) continue;
				int ncst = cst + (used[y][x] == false);
				if (dist[ny][nx] <= ncst) continue;
				dist[ny][nx] = ncst;
				que.push(T(ncst, ny, nx));
			}
		}
	}
	cout << ans << endl;
	return 0;
}

