int BFS_labyrinth(deque<pair<int, int>>& que, vector<vector<int>>& dist, const vector<vector<int>> Remain, vector<vector<int>> cost0, int imin, int imax, int jmin, int jmax) {
	int n = dist.size();
	int m = dist.at(0).size();

	while (!que.empty()) {
		int temp_i, temp_j;
		pair<int, int> tempo = que.front(); que.pop_front();

		temp_i = tempo.first;
		temp_j = tempo.second;
		//cout << temp_i << " " << temp_j << endl;
		if (temp_i == imin || temp_i == imax || temp_j == jmin || temp_j == jmax || cost0.at(temp_i).at(temp_j) == 0) {
			//if (dist.at(temp_i).at(temp_j) == 0) return 0;
			return dist.at(temp_i).at(temp_j);
		}

		rep(k, 4) {
			int i = delta.at(k).first;
			int j = delta.at(k).second;

			if (temp_i + i < imin || imax + 1 <= temp_i + i) continue;  //範囲外
			if (temp_j + j < jmin || jmax + 1 <= temp_j + j) continue;  //範囲外
			if (dist.at(temp_i + i).at(temp_j + j) != -1) continue; //行けない領域に、既に INF などが代入されている場合はこの条件だけで ok

			dist.at(temp_i + i).at(temp_j + j) = dist.at(temp_i).at(temp_j) + Remain.at(temp_i + i).at(temp_j + j);
			if (Remain.at(temp_i + i).at(temp_j + j) == 0) {
				que.push_front(make_pair(temp_i + i, temp_j + j));
			}
			else {
				que.push_back(make_pair(temp_i + i, temp_j + j));
			}
		}
	}


	return -1;
}



void BFS_labyrinth0(queue<pair<int, int>>& que, vector<vector<int>>& dist, vector<vector<int>>& Remain) {
