void calc(int x, int y){
    int mn = 1e9;
    for(int k=0;k<4;k++){
        int nx = x+dx[k];
        int ny = y+dy[k];
        if(nx >= 0 && nx < n && ny >= 0 && ny < n){
            if(v[nx][ny] < mn) mn = v[nx][ny];
        }else{
            mn = 0;
        }
    }
    if(!usd[x][y]) mn++;
    if(mn < v[x][y]){
        v[x][y] = mn;
        for(int k=0;k<4;k++){
            int nx = x+dx[k];
            int ny = y+dy[k];
            if(nx >= 0 && nx < n && ny >= 0 && ny < n && v[nx][ny] > mn){
                calc(nx, ny);
            }
        }
    }
}

