const int N = 5e3 + 15, inf = 1e9 + 7;
int n, ans;
int p[N * N];
int val[N][N];
bool mark[N][N];
int dx[] = {-1, 0, 0, +1};
int dy[] = {0, -1, +1, 0};

bool in(int x, int y) {
	return 0 <= x && x < n && 0 <= y && y < n;
}

void dfs(int x, int y, int va) {
	val[x][y] = min(val[x][y], va);
	for (int k = 0; k < 4; k++) {
		int nx = x + dx[k], ny = y + dy[k];
		if (!in(nx, ny))
			continue;
		if (va + !mark[nx][ny] < val[nx][ny])
			dfs(nx, ny, va + !mark[nx][ny]);
	}
}

int main() {
	ios::sync_with_stdio(false), cin.tie(0);
	cin >> n;
