		for (int j = 0; j < n; j++)
			val[i][j] = min({i, j, n - i - 1, n - j - 1}) + 1;

	for (int i = 0; i < n * n; i++) {
		int x = (p[i] - 1) / n, y = (p[i] - 1) % n;
		ans += val[x][y] - 1;
		mark[x][y] = true;

		int mn = inf;
		for (int k = 0; k < 4; k++) {
			int nx = x + dx[k], ny = y + dy[k];
			if (in(nx, ny))
				mn = min(mn, val[nx][ny]);
			else
				mn = 0;
		}
		dfs(x, y, mn);
	}

	cout << ans << "\n";
	return 0;
}

