int solve(int n,const std::vector<int> &v) {
  std::vector<std::vector<int>> w(4),f(4);
  for ( int i=0; i<4; i++ ) {
    w[i].resize(n*n);
    f[i].resize(n*n);
    for ( int j=0; j<n*n; j++ )
      f[i][j]=1;
  }
  std::vector<int> c(n*n,1);
  for ( int i=0; i<n; i++ ) {
    f[0][i]=0;
    f[1][i*n]=0;
    f[2][(n-1)*n+i]=0;
    f[3][(i+1)*n-1]=0;
    int u=i,d=n-1-i;
    for ( int j=0; j<n; j++ ) {
      int k=std::min(j,n-1-j);
      if ( u<=d ) {
        w[0][i*n+j]=w[1][j*n+i]=std::min(k+1,u);
      }
      else {
        w[0][i*n+j]=w[1][j*n+i]=std::min(k+1,d+2);
      }
      if ( d<=u ) {
        w[2][i*n+j]=w[3][j*n+i]=std::min(k+1,d);
      }
      else {
        w[2][i*n+j]=w[3][j*n+i]=std::min(k+1,u+2);
      }
    }
  }
  std::vector<int> m(n*n);
  for ( int j=0; j<n*n; j++ ) {
    int x=w[0][j];
    for ( int i=1; i<4; i++ ) {
      x=std::min(x,w[i][j]);
    }
    m[j]=x;
  }
  int ans=0;
  int dir[4]={-n,-1,n,1};
  std::vector<int> q;
  for ( auto e: v ) {
    ans+=m[e];
    c[e]=0;
    q.push_back(e);
    while ( !q.empty() ) {
      int i=*q.rbegin();
      q.pop_back();
      int t=m[i]+c[i];
      for ( int d=0; d<4; d++ ) {
        if ( !f[d][i] )
          continue;
        int j=i+dir[d];
        w[d^2][j]=t;
        if ( t<m[j] ) {
          m[j]=t;
          q.push_back(j);
        }
      }
    }
  }
  return ans;
}

