    return x*n + y;
  };
  auto dec = [&](int z) {
    return make_pair(z/n, z%n);
  };
  for (int i = 0; i < n; ++i) {
    for (int j = 0; j < n; ++j) {
      d[enc(i, j)] = min(min(i, j), min(n-1-i, n-1-j));
    }
  }

  int ans = 0;
  for (auto &el : p) {
    int temp = d[el];
    ans += temp;
    priority_queue<pii, vpi, greater<pii>> q;
    q.emplace(d[el] - 1, el);
    while (!q.empty()) {
      int dist, z;
      tie(dist, z) = q.top();
      q.pop();
      if (dist >= d[z]) {
        continue;
      }
      d[z] = dist;
      dist += a[z];
      int x, y;
      tie(x, y) = dec(z);
      vi adj;
      if (x > 0) adj.push_back(enc(x-1, y));
      if (x + 1 < n) adj.push_back(enc(x+1, y));
      if (y > 0) adj.push_back(enc(x, y-1));
      if (y + 1 < n) adj.push_back(enc(x, y+1));
      for (int i : adj) {
        q.emplace(dist, i);
      }
    }
    a[el] = 0;
    d[el] = temp;
  }
  cout << ans << endl;
}

