void update(vector<vector<int>> &dist, vector<vector<bool>> &emp, int y, int x)
{
	int z = dist[y][x];
	if (!emp[y][x])
		++z;

	if (y > 0)
	{
		if (dist[y-1][x] > z)
		{
			dist[y-1][x] = z;
			update(dist, emp, y-1, x);
		}
	}
	if (y < n-1)
	{
		if (dist[y+1][x] > z)
		{
			dist[y+1][x] = z;
			update(dist, emp, y+1, x);
		}
	}
	if (x > 0)
	{
		if (dist[y][x-1] > z)
		{
			dist[y][x-1] = z;
			update(dist, emp, y, x-1);
		}
	}
	if (x < n-1)
	{
		if (dist[y][x+1] > z)
		{
			dist[y][x+1] = z;
			update(dist, emp, y, x+1);
		}
	}
}

