const int MAXN = 577;
int P[MAXN * MAXN], n;
int dp[MAXN][MAXN], dead[MAXN][MAXN];
pii Q[MAXN * MAXN * 2];
int head;
void upd(int i, int j, int x) {
	if(x < dp[i][j]) {
		dp[i][j] = x;
		Q[head++] = make_pair(i, j);
	}
}
void solve() {
	cin >> n;
	for(int i = 0; i < n * n; ++i) {
		P[i] = fetch<int>() - 1;
	}
	for(int i = 0; i < n; ++i) {
		for(int j = 0; j < n; ++j) {
			dp[i][j] = INT_INF;
			dp[i][j] = min(dp[i][j], i + 1);
			dp[i][j] = min(dp[i][j], j + 1);
			dp[i][j] = min(dp[i][j], n - i);
			dp[i][j] = min(dp[i][j], n - j);
		}
	}
	ll answ = 0;
	for(int t = 0; t < n * n; ++t) {
		int si = P[t] / n;
		int sj = P[t] % n;
		int x = dp[si][sj] - 1;
		//cout << si + 1 << ' ' << sj + 1 << ' ' << x << '\n';
		dead[si][sj] = 1;
		answ += x;
		head = 0;
		upd(si, sj, x);
		for(int ptr = 0; ptr < head; ++ptr) {
			int i = Q[ptr].first;
			int j = Q[ptr].second;
			int y = dp[i][j];
			if(i) {
				upd(i - 1, j, y + (dead[i - 1][j] ^ 1));
			}
			if(j) {
				upd(i, j - 1, y + (dead[i][j - 1] ^ 1));
			}
			if(i < n - 1) {
				upd(i + 1, j, y + (dead[i + 1][j] ^ 1));
			}
			if(j < n - 1) {
				upd(i, j + 1, y + (dead[i][j + 1] ^ 1));
			}
		}
	}
	cout << answ << '\n';
}

int main() {
	fast_io();
	solve();

	return 0;
}

