const int maxn = 5e3 + 5;
int n;
bool hav[maxn * maxn];
int dis[maxn * maxn];
int que[maxn * maxn * 3], lb, rb;

void bfs() {
	while (lb < rb) {
		int u = que[lb ++];
		if (u >= n) {
			if (dis[u - n] > dis[u] + hav[u]) {
				dis[u - n] = dis[u] + hav[u];
				if (hav[u]) que[rb ++] = u - n;
				else que[-- lb] = u - n;
			}
		}
		if (u + n < n * n) {
			if (dis[u + n] > dis[u] + hav[u]) {
				dis[u + n] = dis[u] + hav[u];
				if (hav[u]) que[rb ++] = u + n;
				else que[-- lb] = u + n;
			}
		}
		if (u % n) {
			if (dis[u - 1] > dis[u] + hav[u]) {
				dis[u - 1] = dis[u] + hav[u];
				if (hav[u]) que[rb ++] = u - 1;
				else que[-- lb] = u - 1;
			}
		}
		if ((u + 1) % n) {
			if (dis[u + 1] > dis[u] + hav[u]) {
				dis[u + 1] = dis[u] + hav[u];
				if (hav[u]) que[rb ++] = u + 1;
				else que[-- lb] = u + 1;
			}
		}
	}
}

int main() {
