	rep(i, n * n) dis[i] = 0x3f3f3f3f;
	lb = rb = maxn * maxn;
	rep(i, n - 1) que[rb ++] = i, dis[i] = 0;
	rep(i, n - 1) que[rb ++] = (i + 1) * n - 1, dis[(i + 1) * n - 1] = 0;
	rep(i, n - 1) que[rb ++] = (i + 1) * n, dis[(i + 1) * n] = 0;
	rep(i, n - 1) que[rb ++] = (n - 1) * n + i + 1, dis[(n - 1) * n + i + 1] = 0;
	bfs();
	int ans = 0;
	rep(i, n * n) {
		int u; read(u); -- u;
		ans += dis[u];
		hav[u] = 0;
		lb = rb = maxn * maxn;
		que[rb ++] = u;
		bfs();
	}
	printf("%d\n", ans);
	return 0;
}

