inline pair<ll,ll> cor(ll xx){
    xx--;
    return {(xx/n)+1,(xx%n+1)};
}

void setup(ll x){
    auto pr=cor(x);
    check[pr.fi][pr.se]=0;
    adj.clear();
    adj.resize(n*n+5);

    for (ll i=2;i<=n-1;i++){
        for (ll j=2;j<=n-1;j++){
            adj[name(i,j)].pb({name(i,j-1),check[i][j-1]+check[i][j]+(ld)(1e-7)});
            adj[name(i,j)].pb({name(i-1,j),check[i-1][j]+check[i][j]+(ld)(1e-7)});
            adj[name(i,j)].pb({name(i,j+1),check[i][j+1]+check[i][j]+(ld)(1e-7)});
            adj[name(i,j)].pb({name(i+1,j),check[i+1][j]+check[i][j]+(ld)(1e-7)});
        }
    }

    for (ll i=2;i<=n-1;i++){
        adj[name(i,1)].pb({name(i,2),check[i][2]+check[i][1]+(ld)(1e-7)});
        adj[name(i,n)].pb({name(i,n-1),check[i][n-1]+check[i][n]+(ld)(1e-7)});
        adj[name(1,i)].pb({name(2,i),check[2][i]+check[1][i]+(ld)(1e-7)});
        adj[name(n,i)].pb({name(n-1,i),check[n-1][i]+check[n][i]+(ld)(1e-7)});
    }
    adj[name(1,1)].pb({name(1,2),check[1][2]+check[1][1]+(ld)(1e-7)});
    adj[name(1,1)].pb({name(2,1),check[2][1]+check[1][1]+(ld)(1e-7)});

    adj[name(1,n)].pb({name(1,n-1),check[1][n-1]+check[1][n]+(ld)(1e-7)});
    adj[name(1,n)].pb({name(2,n),check[2][n]+check[1][n]+(ld)(1e-7)});

    adj[name(n,1)].pb({name(n-1,1),check[n-1][1]+check[n][1]+(ld)(1e-7)});
    adj[name(n,1)].pb({name(n,2),check[n][2]+check[n][1]+(ld)(1e-7)});

    adj[name(n,n)].pb({name(n-1,n),check[n-1][n]+check[n][n]+(ld)(1e-7)});
    adj[name(n,n)].pb({name(n,n-1),check[n][n-1]+check[n][n]+(ld)(1e-7)});
}

vector<ll> edges;
ll hate=0;
void bfs(ll x){
    vector<ld> dis(n*n+5,(ld)inf);

    priority_queue<pair<ld,ll>,vector<pair<ld,ll>>,greater<pair<ld,ll>>> pq;
    pq.push({0.0,x});
    dis[x]=0.0;
    while(pq.size()){
        ll curr=pq.top().second;
        pq.pop();
        for (auto xd:adj[curr]){
            ll nxt=xd.fi;
            ld wt=xd.se;
            ld ndis=dis[curr]+wt;
            if (ndis<dis[nxt]){
                dis[nxt]=ndis;
                pq.push({ndis,nxt});
            }
        }
    }

    ll mn=inf;
    for (auto xx:edges){
        auto pr=cor(xx);
        mn=min(mn,((ll)dis[xx]+check[pr.fi][pr.se])/2);
    }
    hate+=mn;
}

