#define mod (ll)(1e9 + 7)
const long long INF = 1LL << 60;

ll n;
vvll co;
vvll exist;

void update(ll x, ll y) {
  ll new_cost = co[y][x];

  queue<P> que;
  if (x > 0) {
    que.emplace(x - 1, y);
  }
  if (x < n - 1) {
    que.emplace(x + 1, y);
  }

  if (y > 0) {
    que.emplace(x, y - 1);
  }
  if (y < n - 1) {
    que.emplace(x, y + 1);
  }

  while (!que.empty()) {
    P p = que.front();
    que.pop();
    ll x = p.first;
    ll y = p.second;
    if (exist[y][x]) {
      chmin(new_cost, co[y][x] + 1);
    } else {
      chmin(new_cost, co[y][x]);
    }
  }

  ll current_cost = co[y][x];
  co[y][x] = new_cost;

  que.emplace(x, y);
  while (!que.empty()) {
    auto p = que.front();
    que.pop();
    ll x = p.first;
    ll y = p.second;
    ll c = co[y][x];

    if (exist[y][x]) {
      c = co[y][x] + 1;
    }

    if (x + 1 < n && c < co[y][x + 1]) {
      co[y][x + 1] = c;
      que.emplace(x + 1, y);
    }
    if (x - 1 > 0 && c < co[y][x - 1]) {
      co[y][x - 1] = c;
      que.emplace(x - 1, y);
    }

    if (y + 1 < n && c < co[y + 1][x]) {
      co[y + 1][x] = c;
      que.emplace(x, y + 1);
    }
    if (y - 1 > 0 && c < co[y - 1][x]) {
      co[y - 1][x] = c;
      que.emplace(x, y - 1);
    }
  }
}

