  }

  co = vvll(n, vll(n, INF));
  exist = vvll(n, vll(n, 1));

  rep(y, n) {
    rep(x, n) {
      chmin(co[y][x], y);
      chmin(co[y][x], n - 1 - y);
      chmin(co[y][x], x);
      chmin(co[y][x], n - 1 - x);
    }
  }

  ll ans = 0;
  for (ll it : p) {
    it--;
    ll x = it % n;
    ll y = it / n;
    ll c = co[y][x];
    ans += c;
    exist[y][x] = 0;
    update(x, y);
  }

  cout << ans << endl;

  return 0;
}

