int main(){
	int n;
	scanf("%d",&n);
	int N=n*n;
	int arr[N];
	for(int i=0;i<N;i++){scanf("%d",&arr[i]);arr[i]--;}
	int grid[N];for(int i=0;i<N;i++)grid[i]=1;
	int dx[]={0,0,1,-1},dy[]={1,-1,0,0};
	int dist[N]; for(int i=0;i<N;i++)dist[i]=INF;
	vector<int> added;
	deque<int> q;
	ll ans=0;
	for(int i=0;i<N;i++){
		q.pb(arr[i]);
		added.pb(arr[i]);
		dist[arr[i]]=0;
		while(!q.empty()){
			int cur=q.front();q.pop_front();
			int x=cur/n,y=cur%n;
			if(x==0||y==0||x==n-1||y==n-1){ans+=dist[cur];break;}
			int mini=INF;
			for(int j=0;j<4;j++){
				int nx=x+dx[j],ny=y+dy[j];
				if(0<=nx&&nx<n&&0<=ny&&ny<n){
					int k=nx*n+ny;
					if(dist[k]>dist[cur]+grid[k]){
						dist[k]=dist[cur]+grid[k];
						if(grid[k]==0)q.push_front(k);
						else q.pb(k);
						added.pb(k);
					}
				}
			}
		}
		//printf("\n");
		q.clear();
		while(!added.empty()){
			dist[added.back()]=INF;
			added.pop_back();
		}
		grid[arr[i]]=0;
	}
	printf("%lld",ans);
}

