					bfs[L][R]=bfs[at.first][at.second];
					Q.push(make_pair(L,R));
				}
			}else{
				if(bfs[L][R]>bfs[at.first][at.second]+1){
					bfs[L][R]=bfs[at.first][at.second]+1;
					Q.push(make_pair(L,R));
				}
			}

		}else{
			int row=at.first/a;
			int col=at.first%a;
			for(int i=0;i<4;i++){
				int tr=row+dx[i];
				int tc=col+dy[i];
				if(tr<0||tc<0||tr>=a||tc>=a)continue;
				if(bfs[tr*a+tc][0]>bfs[at.first][at.second]){
					bfs[tr*a+tc][0]=bfs[at.first][at.second];
					Q.push(make_pair(tr*a+tc,0));
				}
			}
		}
	}
}
