int n;

void update(vector<vector<int>> &dist, vector<vector<bool>> &emp, int y, int x)
{
	if (y > 0)
	{
		dist[y-1][x] = min(dist[y][x], dist[y-1][x]);
		// if (emp[y-1][x])
		// 	update(dist, emp, y-1, x);
	}
	if (y < n-1)
	{
		dist[y+1][x] = min(dist[y][x], dist[y+1][x]);
		if (emp[y+1][x])
			update(dist, emp, y+1, x);
	}
	if (x > 0)
	{
		dist[y][x-1] = min(dist[y][x], dist[y][x-1]);
		// if (emp[y][x-1])
		// 	update(dist, emp, y, x-1);
	}
	if (x < n-1)
	{
		dist[y][x+1] = min(dist[y][x], dist[y][x+1]);
		if (emp[y][x+1])
			update(dist, emp, y, x+1);
	}
}

