      pd[i][j] = -1;
      if (min(i, j) == 1 || max(i, j) == n)
        gd[(i - 1) * n + j] = 1;
    }
  int ret = 0;
  for (int i = 1; i <= n * n; i++) {
    int x, y; tie(x, y) = getP(p[i]);
    vis[x][y] = 1;
    deque<pii> pq; pq.pb(mp(x,y));
    vector<pii> ar = {mp(x, y)};
    pd[x][y] = 0;
    int val = N;
    while (sz(pq)) {
      auto cur = pq.front(); pq.pop_front();
      if (min(cur.st, cur.nd) == 1 || max(cur.st, cur.nd) == n) {
        val = min(val, pd[cur.st][cur.nd]);
        break;
      }
      for (int k = 0; k < 4; k++) {
        int nx = cur.st + dx[k], ny = cur.nd + dy[k];
        if (pd[nx][ny] != -1 || nx < 1 || nx > n || ny < 1 || ny > n || val != N)
