        ar.pb(mp(nx, ny));
        if (vis[nx][ny])
          pd[nx][ny] = pd[cur.st][cur.nd], pq.push_front(mp(nx, ny));
        else
          pd[nx][ny] = pd[cur.st][cur.nd] + 1, pq.push_back(mp(nx, ny));
      }
