void bfs(pii s)
{
	que1.push(s);
	while(!que1.empty()||!que2.empty())
	{
		pii u;
		if(que2.empty()||(!que1.empty()&&dis[que1.front().x][que1.front().y]<dis[que2.front().x][que2.front().y])) {u = que1.front(); que1.pop();}
		else {u = que2.front(); que2.pop();}
		for(int i=0; i<4; i++)
		{
			pii v = mkpr(u.x+dx[i],u.y+dy[i]);
			if(v.x>=1&&v.x<=n&&v.y>=1&&v.y<=n&&dis[v.x][v.y]>dis[u.x][u.y]+a[v.x][v.y])
			{
				dis[v.x][v.y] = dis[u.x][u.y]+a[v.x][v.y];
				if(a[v.x][v.y]==1) {que2.push(v);} else {que1.push(v);}
			}
		}
	}
}

