const int maxn = 510;
int a[maxn][maxn],val[maxn][maxn],N;
void update(int x,int y)
{
  if(x == 0 || y == 0 || x == N+1 || y == N+1) return;
  int tmp = min(min(val[x+1][y],val[x-1][y]), min(val[x][y-1],val[x][y+1])) + a[x][y];
  if(tmp != val[x][y])
  {
    val[x][y] = tmp;
    update(x+1,y);
    update(x-1,y);
    update(x,y+1);
    update(x,y-1);
  }
}
