template <class T> inline T Max(T a,T b) { return a > b ? a : b; }
template <class T> inline T Min(T a,T b) { return a < b ? a : b; }

void dfs(int sx,int sy)
{
    h = 1; t = 0;
    q[++t] = (sx - 1) * n + sy;
    while(h <= t)
    {
        int id = q[h++];
        int x = (id - 1) / n + 1,y = (id - 1) % n + 1;
        for(int k=0;k<4;++k)
        {
            int dx = x + dox[k],dy = y + doy[k];
            if(dx < 1 || dy < 1 || dx > n || dy > n) continue;
            if(dis[dx][dy] > dis[x][y] + a[x][y])
            {
                dis[dx][dy] = dis[x][y] + a[x][y];
                q[++t] = (dx - 1) * n + dy;
            }
        }
    }
}

