void solve() {
    int N; cin >> N;
    vector<int> P(N*N);
    for(int i=0; i<N*N; i++) cin >> P[i], P[i]--;

    queue< pair<int, int> > que;
    vector< vector<int> > dist(N, vector<int>(N, INF));
    vector< vector<bool> > dead(N, vector<bool>(N));
    for(int i=0; i<N; i++) {
        dist[0][i] = 0; que.emplace(0, i);
        dist[i][0] = 0; que.emplace(i, 0);
        dist[N-1][i] = 0; que.emplace(N-1, i);
        dist[i][N-1] = 0; que.emplace(i, N-1);
    }

    while(que.size()) {
        int x, y; tie(x, y) = que.front(); que.pop();
        for(int k=0; k<4; k++) {
            int nx = x + dx[k], ny = y + dy[k];
            if(nx < 0 or nx >= N or ny < 0 or ny >= N) continue;
            int c = !dead[x][y];
            if(dist[nx][ny] > dist[x][y] + c) {
                dist[nx][ny] = dist[x][y] + c;
                que.emplace(nx, ny);
            }
        }
    }

    int ans = 0;
    for(int q=0; q<N*N; q++) {
        int r = P[q] / N, c = P[q] % N;
        ans += dist[r][c];
        dead[r][c] = true;

        que.emplace(r, c);
        while(que.size()) {
            int x, y; tie(x, y) = que.front(); que.pop();
            int c = !dead[x][y];
            for(int k=0; k<4; k++) {
                int nx = x + dx[k], ny = y + dy[k];
                if(nx < 0 or nx >= N or ny < 0 or ny >= N) continue;
                if(dist[nx][ny] > dist[x][y] + c) {
                    dist[nx][ny] = dist[x][y] + c;
                    que.emplace(nx, ny);
                }
            }
        }
    }
