int main() {

    int n;
    sc.read(n);
    VV<int> g(n, V<int>(n, 1));
    VV<int> dist(n, V<int>(n));
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            dist[i][j] = min({
                i, n - 1 - i,
                j, n - 1 - j,
            });
        }
    }
    using P = pair<int, int>;
    auto dfs = [&](auto self, P p) -> void {
        for (int d = 0; d < 4; d++) {
            P np = P(p.first + d4[d][0], p.second + d4[d][1]);
            if (!(0 <= np.first && np.first < n && 0 <= np.second && np.second < n)) continue;
            if (dist[p.first][p.second] + g[p.first][p.second] < dist[np.first][np.second]) {
                dist[np.first][np.second] = dist[p.first][p.second] + g[p.first][p.second];
                self(self, np);
            }
        }
    };
    ll ans = 0;
    for (int ph = 0; ph < n * n; ph++) {
        int _p;
        sc.read(_p); _p--;
        P p = P(_p / n, _p % n);
        ans += dist[p.first][p.second];
        g[p.first][p.second] = 0;
        dfs(dfs, p);
    }
    pr.writeln(ans);
    return 0;
}

