    if(rand()%2) uf[find(j)] = find(i); }

ll closestIsland(ll x, ll y) {
    ll dist = min(min(x,n-x-1), min(y,n-y-1));
    ll disl=-1;
    FOR(i,max(0,x-n/4), min(n,x+n/4)) { // which row
        if(!isl[i].size()) continue;
        auto f=[&](ll iy, ll id) {
            id = find(id);
            ll cd = max(0,abs(i-x)-1) + 
                max(0,abs(iy-y)-1) +
                + (i!=x && iy!=y) +
                dst[id];
            if(dist>cd) {
                dist=cd;
                disl=id;
            }
        };
        auto it = isl[i].lower_bound({y,0});
        if(it!=isl[i].end()) {
            f(it->x, it->y);
        }
        if(it != isl[i].begin()) {
            it--;
            f(it->x, it->y);
        }
    }
    return dist;
}

