	FOR( p, P )
	{
		const int pi = p / N;
		const int pj = p % N;

// 		cerr << pi << ' ' << pj << endl;
		occupied[ pi ][ pj ] = 0;

		if ( distances[ pi ][ pj ] == 0 )
		{
// 			assert( false );
			continue;
		}

		res += distances[ pi ][ pj ] - 1;
		--distances[ pi ][ pj ];

		queue< PII > que;
		que.EM( pi, pj );

		const auto inside = [&]( const int y, const int x )
		{
			return 0 <= y && y < N && 0 <= x && x < N;
		};

		while ( !que.empty() )
		{
			const int y = que.front().fst;
			const int x = que.front().snd;
			que.pop();

			REP( d, 4 )
			{
				const int ny = y + dy[d];
				const int nx = x + dx[d];

				if ( inside( ny, nx ) && chmin( distances[ ny ][ nx ], distances[y][x] + occupied[ ny ][ nx ] ) )
				{
					que.EM( ny, nx );
				}
			}
		}
// 		dump_distances();
// 		DUMP( res );
	}

	cout << res << endl;

	return 0;
}

