ll num[510][510];
void dij(ll _x,ll _y) {
	swap(_x, _y);
	if (d[_x][_y] != INF)
		return;
	// 自分の番号から昇順に突き当たるところまで処理する
	pllgreaterq q;
	ll r = INF;
	ll nowp = po[num[_x][_y]];
	rep(i, 4) {
		ll tx = _x + dx[i];
		ll ty = _y + dy[i];

		ll nn = num[tx][ty];
		ll nxp = po[num[tx][ty]];
		if (nxp > nowp) {
			//番号が大きい場合+1
			r = min(r, d[tx][ty] + 1);
		}
		else {
			//番号が小さい場合その数字
			r = min(r, d[tx][ty]);
		}

	}
	q.psp2(r, num[_x][_y]);

	while (!q.empty())
	{
		auto pi = q.top();
		q.pop();
		ll cost = pi.first;
		ll x = ti[pi.second].first;
		ll y = ti[pi.second].second;
		if (d[x][y] <= cost)
			continue;
		ll cn = num[x][y];
		ll np = po[cn];
		d[x][y] = cost;

		for (int i = 0; i < 4; i++) {
			ll tx = x + dx[i];
			ll ty = y + dy[i];
			if (tx < 1 || ty < 1 || tx >n || ty > n)
				continue;
			ll nn = num[tx][ty];
			ll nxp =  po[num[tx][ty]];
			if (nxp < np)
				//次の番号が小さい場合、はじく
				continue;

			//次の番号が大きい場合のみ普通のダイクストラ
			if (d[tx][ty] > cost) {
				q.psp2(cost, nn);
			}
		}
	}
}
void solv() {
	cin >> n;
	rep2(i, 1, n * n + 1) {
		cin >> p[i];
		po[p[i]] = i;
	}

	ll x = 1;
	ll y = 1;
	rep2(i, 1, n * n + 1) {
		if (y == n + 1) {
			y = 1;
			x++;
		}
		ti[i].first = x;
		ti[i].second = y;
		y++;
	}
	ll nm = 1;
	rep2(i, 1, n + 1) {
		rep2(j, 1, n + 1) {
			num[i][j] = nm++;
		}
	}
	rep2(i, 1, n + 1)rep2(j, 1, n + 1) {
		d[i][j] = INF;
	}
	// 螺旋型に処理したい
	x = 1;
	y = 1;
	bool vis[510][510];
	all0(vis);
	rep(i, n + 1) {
		vis[0][i] = true;
		vis[i][0] = true;
		vis[n + 1][i] = true;
		vis[i][n + 1] = true;
	}

	while (true)
	{
		bool  ok = false;
		for (ll i = x; i <= n + 1; i++)
		{
			if (vis[i][y]) {
				x = i - 1;
				break;
			}

			dij(i, y);
			vis[i][y] = true;
			ok = true;
		}

		for (ll i = y + 1; i <= n + 1; i++) {
			if (vis[x][i]) {
				y = i - 1;
				break;
			}
			dij(x, i);
			vis[x][i] = true;
			ok = true;
		}

		for (ll i = x - 1; i >= 0; i--) {
			if (vis[i][y]) {
				x = i + 1;
				break;
			}
			dij(i, y);
			vis[i][y] = true;
			ok = true;
		}

		for (ll i = y - 1; i >= 0; i--) {
			if (vis[x][i]) {
				y = i + 1;
				break;
			}
			dij(x, i);
			vis[x][i] = true;
			ok = true;
		}

		if (!ok)
			break;
		x++;
	} 
	ll res = 0;
	rep2(i, 1, n + 1) {
		rep2(j, 1, n + 1) {
			res += d[i][j];
		}
	}
	cout << res << endl;

}


