        solve(x-1,y);
    }
    if(dp[x][y-1]>dis)
    {
        dp[x][y-1]=dis;
        solve(x,y-1);
    }
    if(dp[x][y+1]>dis)
    {
        dp[x][y+1]=dis;
        solve(x,y+1);
    }
}
