        done[h][w] = 0;
        while(bq.size() > 0){
            auto pt = bq.front();
            bq.pop();
            int c = mp[pt.first][pt.second]+done[pt.first][pt.second];
            for(int j = 0; j < 4; j++){
                auto next = make_pair(pt.first+dir1[j],pt.second+dir2[j]);
                if(mp[next.first][next.second] > c){
                    mp[next.first][next.second] = c;
                    bq.push(next);
                }
            }
        }
    }

    std::cout << ans << endl;
    return 0;
}

