void bfs(int x, int y)
{
    queue<pii> q;
    q.push(mp(x, y));

    while (SZ(q))
    {
        int x, y;
        tie(x, y) = q.front();
        q.pop();

        int label = fre[x][y];

        if (check(x + 1, y, used[x][y], label))
        {
            used[x + 1][y] = used[x][y] + label;
            q.push(mp(x + 1, y));
        }

        if (check(x, y + 1, used[x][y], label))
        {
            used[x][y + 1] = used[x][y] + label;
            q.push(mp(x, y + 1));
        }

        if (check(x - 1, y, used[x][y], label))
        {
            used[x - 1][y] = used[x][y] + label;
            q.push(mp(x - 1, y));
        }

        if (check(x, y - 1, used[x][y], label))
        {
            used[x][y - 1] = used[x][y] + label;
            q.push(mp(x, y - 1));
        }
    }
}


