int a[512][512];

void solve() {
  ini(N);
  vi p(N * N);
  in(p);
  each(x, p) x--;
  rep(i, N) rep(j, N) a[i][j] = 1;

  deque<P> s;

  auto ok = [&](int i, int j) {
    return i == 0 || i == N - 1 || j == 0 || j == N - 1;
  };

  int dx[] = {0,1,0,-1};
  int dy[] = {1,0,-1,0};

  vi vis(N*N);

  auto f = [&](int x) {
    int _i = x / N;
    int _j = x % N;

    fill(all(vis), inf);
    s.clear();
    a[_i][_j] = 0;
    trc(_i,_j);

    s.emplace_back(_i * 512 + _j, 0);
    vis[_i * N + _j] = 0;
    ll ans = inf;

    while(!s.empty()){
      auto cur = s.front();
      s.pop_front();
      int i = cur.first / 512;
      int j = cur.first % 512;
      int d = cur.second;
      trc(i,j,d);
      if(ok(i, j)) {ans = d; break;}

      rep(dk,4){
        int di = i + dx[dk], dj = j + dy[dk];
        int dd = d + (a[di][dj] == 1);
        if(dd >= vis[di * N + dj]) continue;
        vis[di * N + dj] = dd;
        if(a[di][dj] == 1) s.emplace_back(di * 512 + dj, dd);
        else s.emplace_front(di * 512 + dj, dd);
      }  
    }
    return ans;
  };
  ll bns = 0;
  each(x,p){bns += f(x);trc(bns);}
  out(bns);
}

