struct UnionFind{
    vector<int> nxt;
    vector<int> numm;
    void init(int x){
        nxt.clear();
        numm.assign(x, 1);
        nxt.resize(x);
        for (int i = 0; i < x;i++){
            nxt[i] = i;
        }
    }
    int find(int x){
        if(nxt[x]==x)
            return x;
        return nxt[x] =find(nxt[x]);
    }
    int size(int x){
        return numm[x];
    }
    inline void unite(int x,int y){
        if(x==y)
            return;
        numm[find(x)] += numm[find(y)];
        nxt[find(y)] = find(x);
    }
};

