int dx[4] = { 1,-1,0,0 };
int dy[4] = { 0,0,1,-1 };

void solve()
{
    int n;
    scanf("%d", &n);
    int n2 = n * n;
    vector<int> p(n2);
    int i,j;
    for (i = 0; i < n2; i++) {
        scanf("%d", &p[i]); p[i]--;
    }

    for (i = 0; i < n; i++) {
        for (j = 0; j < n; j++) {
            d[i][j] = MIN(MIN(i+1,n-i),MIN(j+1,n-j));
        }
    }

#define P(i,j) ((i)*n+(j))
    ll ans = 0;
    for (i = 0; i < n2; i++) {
        int x = p[i] / n;
        int y = p[i] % n;
        ans+=(d[x][y]- 1);
        d[x][y]--;
        flag[x][y] = 1;
        queue<int> que;
        que.push(P(x,y));
        while (!que.empty()) {
            int tmp=que.front();
            que.pop();
            int currx = tmp / n;
            int curry = tmp % n;

            int k;
            for (k = 0; k < 4; k++) {
                int x2 = currx + dx[k], y2 = curry + dy[k];
                if (x2 < 0 || x2 >= n || y2 < 0 || y2 >= n) continue;

                int dist2 = d[currx][curry] + (flag[x2][y2] ? 0 : 1);
                if (dist2 < d[x2][y2]) {
                    d[x2][y2] = dist2;
                    que.push(P(x2, y2));
                }
            }
        }
    }
    printf("%lld\n", ans);

    return;
}


