bool emp[N][N];
int n;

void relax(int si, int sj) {
  priority_queue<pair<int, PII>> heap;
  heap.emplace(dis[si][sj], PII{si, sj});
  while (!heap.empty()) {
    auto [i, j] = heap.top().second; heap.pop();
    for (int ii: {i - 1, i, i + 1}) {
      for (int jj: {j - 1, j, j + 1}) {
        if (abs(i - ii) + abs(j - jj) != 1) continue;
        if (ii < 1 || ii > n || jj < 1 || jj > n) continue;
        if (dis[ii][jj] > dis[i][j] + !emp[i][j]) {
          dis[ii][jj] = dis[i][j] + !emp[i][j];
          heap.emplace(-dis[ii][jj], PII{ii, jj});
        }
      }
    }
  }
}

