inline void bfs(int r, int c){
    deque<pii> q; ++cnt;
    q.push_back(make_pair(r,c));
    upd[r][c] = cnt;
    t_dis[r][c] = 0;

    vector<pii> v;
    while(q.size()){
        int x = q.front().first, y = q.front().second; q.pop_front();
        if(!(x == r && y == c)) v.pb(make_pair(x,y));
        for(int i=0; i<4; i++){
            int nx = x+moves[i][0], ny = y+moves[i][1];
            if(dis[nx][ny] && (upd[nx][ny] != cnt || t_dis[x][ny] > t_dis[x][y]+vals[nx][ny])){
                upd[nx][ny] = cnt;
                t_dis[nx][ny] = t_dis[x][y]+vals[nx][ny];
                if(vals[nx][ny] == 0) q.push_front(make_pair(nx,ny));
                else q.push_back(make_pair(nx,ny));
            }
        }
    }

    for(pii check:v)
        dis[check.first][check.second] = min(dis[check.first][check.second],dis[r][c]+t_dis[check.first][check.second]-1);
}

