void upd(i64 tt, i64 si, i64 sj) {
    if (a[si][sj] != p[tt]) {
        throw 1;
    }

    a[si][sj] = 0;

    vector<pair<i64, i64>> q;
    q.push_back({ si, sj });
    u[si][sj] = tt;

    //for (auto t : z) {
