    for (i64 k = 0; k < q.size(); k++) {
        i64 ci = q[k].first;
        i64 cj = q[k].second;

        i64 v = b[ci][cj] + (a[ci][cj] ? 1 : 0);
        for (auto t : z) {
            i64 ni = ci + t.first;
            i64 nj = cj + t.second;

            if (u[ni][nj] == tt) {
                continue;
