using namespace std;

int search(vector<int> s, int n, int x){
  int y = x, start, strain = 0;
  while((y % n != 0) && (y % n != 1) && y >= n && y < n*(n-1)){
    if(s[y+1] != 1)
      break;
    y++;
  }
  start = y;
  //cout << y << endl;
  while((y % n != 0) && (y % n != 1) && y >= n && y < n*(n-1)){
    switch(strain){
      case 0://右壁
        if(s[y+1] != 0){
          y += 1;
          strain = 3;
        } else if(s[y-n] != 0)
          y -= n;
        else
          strain = 1;
        break;

      case 1://上壁
        if(s[y-n] != 0){
          y -= n;
          strain = 0;
        } else if(s[y-1] != 0)
          y -= 1;
        else
          strain = 2;
        break;

	  case 2://左壁
        if(s[y-1] != 0){
          y -= 1;
          strain = 1;
        } else if(s[y+n] != 0)
          y += n;
        else
          strain = 3;
        break;

      case 3://下壁
        if(s[y+n] != 0){
          y += n;
          strain = 2;
        } else if(s[y+1] != 0)
          y += 1;
        else
          strain = 0;
        break;
    }
    //cout << "y:" << y << "str:" << strain << endl;
    if(y == start && strain == 0)
      return 1;
  }
  return 0;
}

