int find(int x) {
	if (x == par[x]) return x;
	return par[x] = find(par[x]);
}

void merge(int x, int y) {
	x = find(x);
	y = find(y);
	par[x] = y;
	cost[y] = min(cost[x], cost[y]);
}

int f(int r, int c) {
	return (r - 1) * n + c;
}

