void hantei(int x,int y, vector<vector<int>> &n){

  if(n.at(x).at(y-1) == 2){
    n.at(x).at(y-1) = 0;
    hantei(x,(y-1),n);
  }
  n.at(x).at(y-1) = 0;

  if(n.at(x).at(y+1) == 2){
    n.at(x).at(y+1) = 0;
    hantei(x,(y+1),n);
  }
  n.at(x).at(y+1) = 0;

  if(n.at(x-1).at(y) == 2){
    n.at(x-1).at(y) = 0;
    hantei((x-1),y,n);
  }
  n.at(x-1).at(y) = 0;  

  if(n.at(x+1).at(y) == 2){
    n.at(x+1).at(y) = 0; 
    hantei((x+1),y,n);
  }
  n.at(x+1).at(y) = 0;    

  return;
}

