int g[N][N];
bool read() {
	if( scanf("%d", &n) != 1) return false;		
	forn(i,n*n){
		scanf("%d", &p[i]);
	   	--p[i];
	}
	forn(r,n) forn(c,n)  {
		g[r][c] = r*n + c;
	}
	return true;
}

bool isOut(int r, int c) {
	if( 0 <= r && r < n && 0 <= c && c <n) return false;
	return true;
}

int getMin(int pi) {
	int r = pi/n;
	int c = pi%n;
	int curMin = min( { r, c, (n-1)-r , (n-1)-c });

	int dr[] = {-1, 0, 1, 0 };
	int dc[] = {0, 1, 0, -1};
	queue<pair<pii,int>> q;
	q.push(mp(mp(r,c),0));
	bool vis[n][n];
	forn(r,n) forn(c,n) vis[r][c] = false;
	while( !q.empty() ) {
		auto cur = q.front(); q.pop();
		vis[cur.f.f][cur.f.s] = true;
		forn(dir, 4) {
			int nr = cur.f.f + dr[dir];
			int nc = cur.f.s + dc[dir];
			if ( cur.s >= curMin) continue;
			if( isOut(nr,nc) ) {
				curMin = min( curMin, cur.s);	
				continue;
			}
			if( !vis[nr][nc] )  {
				q.push(mp(mp(nr,nc),cur.s + ( g[nr][nc] == -1 ? 0 : 1)));
			}
		}	
	}
	return curMin;
}

void rem(int pi) {
	int r = pi/n;
	int c = pi%n;
	g[r][c] = -1;
}

void solve() {
	int cnt = 0;
	for(int pi : p) {
		int curMin = getMin(pi);
		cnt += curMin;
		rem(pi);		
	}
	printf("%d\n",cnt);
}

