#define INF 1e+9
#define MAX_V 250010
#define GOAL 250001

struct edge {
    long long to;
    long long cost;
};

// <最短距離, 頂点の番号>
using P = pair<long long, long long>;

long long V;
vector<edge> G[MAX_V];
long long d[MAX_V];

void dijkstra(long long s) {
    priority_queue<P, vector<P>, greater<P> > que;
    fill(d, d+MAX_V, INF);
    d[s] = 0;
    que.push(P(0, s));

    while (!que.empty()) {
        P p = que.top();
        que.pop();
        long long v = p.second;
        if (d[v] < p.first) continue;
        for (long long i=0; i<G[v].size(); ++i) {
            edge e = G[v][i];
            if (d[e.to] > d[v] + e.cost) {
                d[e.to] = d[v] + e.cost;
                que.push(P(d[e.to], e.to));
            }
        }
    }
}

int main() {
    cin >> V;
    long long Pjun[V*V+1];
    long long i,j, k;
    for(k=1; k<=V*V; k++){
        cin >> Pjun[k];
    }
    for(i=0; i<=V-1; i++){
        for(j=1; j<=V-1; j++){
            edge e1 = {i*V+j+1, 1};
            G[i*V+j].push_back(e1);
            edge e2 = {i*V+j, 1};
            G[i*V+j+1].push_back(e2);
        }
    }
    for(j=1; j<=V; j++){
        for(i=0; i<=V-2; i++){
            edge e3 = {(i+1)*V+j, 1};
            G[i*V+j].push_back(e3);
            edge e4 = {i*V+j, 1};
            G[(i+1)*V+j].push_back(e4);
        }
    }
    for(j=1; j<=V; j++){
        edge e5 = {GOAL, 1};
        G[j].push_back(e5);
        edge e6 = {GOAL, 1};
        G[(V-1)*V+j].push_back(e6);
    }
    for(i=1; i<=V-2; i++){
        edge e7 = {GOAL, 1};
        G[i*V+1].push_back(e7);
        edge e8 = {GOAL, 1};
        G[i*V+V].push_back(e8);
    }
    long long ans=0;
    for(k=1; k<=V*V; k++){
        for(i=0; i<G[Pjun[k]].size(); i++){
            G[Pjun[k]][i].cost = 0;
        }
        dijkstra(Pjun[k]);
        ans += d[GOAL];
    }
    cout << ans << endl;
    return 0;
}

