int used[250000];

int dh[4] = {1,-1,0,0}, dw[4] = {0,0,1,-1};

void bfs(int src){
	deque<int> dq;
	dq.push_back(src);
	while(!dq.empty()){
		int cur = dq.front();
		int h = cur / n, w = cur % n;
		dq.pop_front();
		rep(i,4){
			int nh = h + dh[i];
			int nw = w + dw[i];
			if(nh < 0 || n <= nh) continue;
			if(nw < 0 || n <= nw) continue;
			int nex = nh * n + nw;
			int nex_cost = cost[cur] + used[cur];
			if(cost[nex] <= nex_cost) continue;
			cost[nex] = nex_cost;
			if(used[cur]) dq.push_back(nex);
			else dq.push_front(nex);
		}
	}
}

