int lmin(int i, int j, int N, vvi & flag, vvi history,int s,int A) {
	int len;
	int m1, m2, m3, m4;
	int f1, f2, f3;
	history.at(i).at(j) = 0;
	if (i == 0 || i == N - 1 || j == 0 || j == N - 1) {
		return 0;
	}
	else if (s >= A) { return s; }
	//	cout << i << j << endl;
	if (history.at(i).at(j - 1) == 0) m1 = 10000;
	else {
		s += flag.at(i).at(j - 1);
		f1 = history.at(i).at(j + 1);
		f2 = history.at(i - 1).at(j);
		f3 = history.at(i + 1).at(j);
		history.at(i).at(j + 1) = 0;
		history.at(i - 1).at(j) = 0;
		history.at(i + 1).at(j) = 0;
		m1 = lmin(i, j - 1, N, flag, history, s,A)+flag.at(i).at(j-1);
		history.at(i).at(j + 1) = f1;
		history.at(i - 1).at(j) = f2;
		history.at(i + 1).at(j) = f3;

	}

	if (history.at(i).at(j + 1) == 0) m2 = 10000;
	else {
		s += flag.at(i).at(j + 1);
		f1 = history.at(i).at(j - 1);
		f2 = history.at(i - 1).at(j);
		f3 = history.at(i + 1).at(j);
		history.at(i).at(j - 1) = 0;
		history.at(i - 1).at(j) = 0;
		history.at(i + 1).at(j) = 0;
		m2 = lmin(i, j + 1, N, flag, history,s,A) + flag.at(i).at(j + 1);
		history.at(i).at(j - 1) = f1;
		history.at(i - 1).at(j) = f2;
		history.at(i + 1).at(j) = f3;

	}
	if (history.at(i - 1).at(j) == 0) m3 = 10000;
	else {
		s += flag.at(i-1).at(j);
		f1 = history.at(i).at(j - 1);
		f2 = history.at(i).at(j + 1);
		f3 = history.at(i + 1).at(j);
		history.at(i).at(j - 1) = 0;
		history.at(i).at(j + 1) = 0;
		history.at(i + 1).at(j) = 0;
		m3 = lmin(i - 1, j, N, flag, history,s,A) + flag.at(i - 1).at(j);
		history.at(i).at(j - 1) = f1;
		history.at(i).at(j + 1) = f2;
		history.at(i + 1).at(j) = f3;
	}

	if (history.at(i + 1).at(j) == 0) m4 = 10000;
	else {
		s += flag.at(i+1).at(j);
		f1 = history.at(i).at(j - 1);
		f2 = history.at(i).at(j + 1);
		f3 = history.at(i - 1).at(j);
		history.at(i).at(j - 1) = 0;
		history.at(i).at(j + 1) = 0;
		history.at(i - 1).at(j) = 0;
		m4 = lmin(i + 1, j, N, flag, history,s,A) + flag.at(i + 1).at(j);
		history.at(i).at(j - 1) = f1;
		history.at(i).at(j + 1) = f2;
		history.at(i - 1).at(j) = f3;
	}
	len = min(min(m1, m2), min(m3, m4));

	return len;
}

