using namespace std;

int dat[501][501] = {};
int dat2[501][501] = {};
bool block[501][501] = {};


struct S {
	int x;
	int y;
	int v;
};

auto cmp = [](const S& lhs, const S& rhs)
{
	return lhs.v > rhs.v;
};

void enqueue(int x, int y, int v, int n, int m, priority_queue<S, vector<S>, decltype(cmp)>& s)
{
	if (x == -1 || x == n || y == -1 || y == n) return;
	if (dat2[x][y] == m) return;
	if (dat[x][y] <= v) return;
	s.push({ x,y,v });
}

void update(int x, int y, int v, int n, int m)
{
	priority_queue<S, vector<S>, decltype(cmp)> search(cmp);

	search.push({ x, y, v });
	while (!search.empty()) {
		S s = search.top();
		search.pop();


		dat2[s.x][s.y] = m;

		int cv = s.v;

		if (s.x == x && s.y == y) {
		}
		else {
			dat[s.x][s.y] = min(dat[s.x][s.y], cv);
		}
		if (!block[s.x][s.y]) cv++;
		//cout << "ss : " << search.size() << endl;

		enqueue(s.x - 1, s.y, cv, n, m, search);
		enqueue(s.x + 1, s.y, cv, n, m, search);
		enqueue(s.x, s.y - 1, cv, n, m, search);
		enqueue(s.x, s.y + 1, cv, n, m, search);
		//cout << search.size() << endl;
	}
}

int main()
{
	ios_base::sync_with_stdio(false);
	cin.tie(NULL);
	cout << fixed << setprecision(20);

	int n; cin >> n;

	FOR_LT(i, 0, n) {
		FOR_LT(j, 0, n) {
			int a = i;
			int b = n - i - 1;
			int c = j;
			int d = n - j - 1;
			dat[i][j] = min(min(a, b), min(c, d));
		}
	}

	int64_t ans = 0;
	REP(n * n) {
		int m;  cin >> m; m--;
		int x = m % n;
