void dfs(int x, int y)
{
	for(int i=0;i<4;i++)
	{
		int x2=x+dx[i]; int y2=y+dy[i];
		if(valid(x2,y2))
		{
			if(b[x][y]+a[x][y]<a[x2][y2])
			{
				a[x2][y2]=b[x][y]+a[x][y];
				dfs(x2,y2);
			}
		}
	}
}

