struct edge {
    int a, b, len;
    edge(int a = 0, int b = 0, int len = 0) {
        this->a = a;
        this->b = b;
        this->len = len;
    }
};

int n;
vector<vector<vector<edge>>> g;
vector<vector<int>> used;
vector<vector<int>> d;

void bfs(int i, int j) {
    used.assign(n, vector<int> (n, 0));
    d.assign(n, vector<int> (n, 1e9));
    deque<pair<int, int>> q;
    q.push_back({i, j});
    used[i][j] = 1;
    d[i][j] = 0;
    while (!q.empty()) {
        pair<int, int> now = q.front();
        q.pop_front();
        int i = now.first;
        int j = now.second;
        for (edge &to : g[i][j]) {
            int new_i = to.a;
            int new_j = to.b;
            int len = to.len;
            if (!used[new_i][new_j]) {
                used[new_i][new_j] = 1;
                d[new_i][new_j] = d[i][j] + len;
                if (len == 0) {
                    q.push_front({new_i, new_j});
                } else {
                    q.push_back({new_i, new_j});
                }
            }
        }
    }
}

