template <typename T>
class BIT {
public:
    BIT(int n = 0) : n(n), d(n + 1) {}
    void add(int i, T x) {
        for (i++; i <= n; i += i & -i)
            d[i] += x;
    }
    T sum(int i) {
        T x = 0;
        for (i++; i; i -= i & -i)
            x += d[i];
        return x;
    }

private:
    int n;
    vector<T> d;
};

void solve() {
    int n;
    cin >> n;
    vector<int> p(n * n);
    rep(i, n * n) cin >> p[i];

    vector<BIT<int>> bit(n, n), bit2(n, n);
    rep(i, n) rep(j, n) {
        bit[i].add(j, 1);
        bit2[j].add(i, 1);
    }

    int ans = 0;
    each(x, p) {
        int i = (x - 1) / n;
        int j = (x - 1) % n;
        auto tmp = bit[i].sum(j);
        auto tmp2 = bit2[j].sum(i);
        ans += min({bit[i].sum(n - 1) - tmp, tmp - 1, bit2[j].sum(n - 1) - tmp2, tmp2 - 1});
        bit[i].add(j, -1);
        bit2[j].add(i, -1);
    }
    cout << ans << endl;
}

