int main() {
  ios::sync_with_stdio(false);
  cin.tie(nullptr);
  int n;
  cin>>n;
  vecint p(n*n);
  for(auto&&e:p)cin>>e;
  int INF = 1e9;
  vecint dis(n*n, INF);
  auto id = [&] (int i, int j) {
    return i*n + j;
  };
  REP(i,n)REP(j,n) {
    dis[id(i,j)] = min({i, j, n-1-i, n-1-j});
  }
  vector<bool> emp(n*n, false);
  ll ans = 0;
  REP(n2,n*n) {
    int idx = p[n2] - 1;
    ans += dis[idx];
    emp[idx] = true;
    deque<int> q;
    q.push_front(idx);
    while (!q.empty()) {
      auto cidx = q.front();
      auto ii = cidx / n;
      auto jj = cidx % n;
      q.pop_front();
      int di[] = {1, 0, -1, 0};
      int dj[] = {0, 1, 0, -1};
      REP(k,4) {
        int ni = ii + di[k];
        int nj = jj + dj[k];
        if (ni < 0 || nj < 0 || ni >= n || nj >= n) continue;
        int nidx = id(ni, nj);
        int cst = emp[cidx] ? 0 : 1;
        if (dis[nidx] > dis[cidx] + cst) {
          dis[nidx] = dis[cidx] + cst;
          if (cst == 0) {
            q.push_front(nidx);
          } else {
            q.push_back(nidx);
          }
        }
      }
    }
  }
  cout<<ans<<endl;
  return 0;
}

