enum Dir {
    UP, RIGHT, DOWN, LEFT, DIR_NUM
};
const int64_t dx[] = { 0, 1, 0, -1 };
const int64_t dy[] = { -1, 0, 1, 0 };

int main() {
    int64_t N;
    cin >> N;
    vector<int64_t> P(N * N);
    for (int64_t& p : P) {
        cin >> p;
        p--;
    }

    vector<int64_t> value(N * N, 0);
    vector<vector<int64_t>> value_each_dir(N * N, vector<int64_t>(DIR_NUM, 0));
    for (int64_t i = 0; i < N; i++) {
        for (int64_t j = 0; j < N; j++) {
            value[i * N + j] = min({ i, N - 1 - i, j, N - 1 - j });
        }
    }

    for (int64_t i = 0; i < N; i++) {
        for (int64_t j = 0; j < N; j++) {
            for (int64_t d = 0; d < DIR_NUM; d++) {
                int64_t ni = i + dy[d];
                int64_t nj = j + dx[d];
                if (ni < 0 || N <= ni || nj < 0 || N <= nj) {
                    continue;
                }
                int64_t next_node = ni * N + nj;
                value_each_dir[i * N + j][d] = value[next_node] + 1;
            }
        }
    }

    vector<bool> there(N * N, true);

    auto print = [&]() {
        for (int64_t i = 0; i < N; i++) {
            for (int64_t j = 0; j < N; j++) {
                cout << setw(2) << value[i * N + j] << " ";
            }

            cout << "      ";
            for (int64_t j = 0; j < N; j++) {
                cout << setw(2) << i * N + j << " ";
            }

            cout << endl;
        }
        cout << endl;
    };

    int64_t ans = 0;
    for (int64_t p : P) {
//        cout << "p = " << p << "を抜きたい" << endl;
//        print();
        ans += value[p];

        //pを抜くとなにが起きるか
        there[p] = false;
        stack<int64_t> st;
        st.push(p);
        while (!st.empty()) {
            int64_t top = st.top();
            st.pop();

            int64_t i = top / N;
            int64_t j = top % N;

            //この位置に繋がっている4方のコストを下げる
            for (int64_t d = 0; d < DIR_NUM; d++) {
                int64_t ni = i + dy[d];
                int64_t nj = j + dx[d];
                if (ni < 0 || N <= ni || nj < 0 || N <= nj) {
                    continue;
                }

                int64_t next_node = ni * N + nj;

                int64_t before_min = *min_element(value_each_dir[next_node].begin(), value_each_dir[next_node].end());

                value_each_dir[next_node][(d + 2) % DIR_NUM] = value[top] + there[top];

                int64_t after_min = *min_element(value_each_dir[next_node].begin(), value_each_dir[next_node].end());
                if (after_min < before_min) {
                    value[next_node] = after_min;
                    st.push(next_node);
                }
            }
        }
    }

    cout << ans << endl;
}

