#define onEdge(i, j) (i == 0 || i == n-1 || j == 0 || j == n-1)
#define inBound(i, j) !(i < 0 || i > n-1 || j < 0 || j > n-1)

vector<pair<int,int>> order;
vector<vector<int>> dist;
vector<vector<bool>> seats;
const int dx[4] = {0, -1, 0, 1};
const int dy[4] = {-1, 0, 1, 0};
int n;

void updDist(int x1, int y1){
	vector<pair<int,int>> q;
	q.push_back({x1, y1});
	for (int i = 0; i < q.size(); i++){
		auto u = q[i];
		int x = u.first; int y = u.second;
		for (int d = 0; d < 4; d++){
			int x2, y2;
			x2 = x + dx[d];
			y2 = y + dy[d];
			if (inBound(x2,y2)){
				int newDist = dist[x][y] + seats[x2][y2];
				if (newDist < dist[x2][y2]){
					dist[x2][y2] = newDist;
					q.push_back({x2, y2});
				}
			}
		}
	}
}
int main(){
	ios::sync_with_stdio(false);
	cin.tie(NULL);

	cin>>n;
	order.resize(n*n);
	seats.assign(n, vector<bool>(n, 1));
