	for (auto &it: order){
		int a;
		cin>>a;
		a--;
		int x = a/n;
		int y = a%n;
		it.first = x; it.second = y;
	}
	for (int i = 0; i < n; i++){
		for (int j = 0; j < n; j++){
			if (onEdge(i, j)){
				dist[i][j] = 0;
				updDist(i, j);
			}
			// cout<<dist[i][j];
		}
		// cout<<'\n';
	}
	int ans = 0;
	for (auto u: order){
		ans += dist[u.first][u.second];
		dist[u.first][u.second]--;
		seats[u.first][u.second] = 0;
		updDist(u.first, u.second);
	}
	cout<<ans<<'\n';
	return 0;
}

