int dfs(int l, int r)
{
    priority_queue < pair <int, pair <int,int> > , vector <pair <int, pair <int,int> > > ,compara > q;


    map <  pair <int, pair <int,int> > , bool> ex;




    q.push({0,{l,r}});


    int ans = 1e9;

    while(!q.empty())
    {
        int nr = q.top().first;
        int l1 = q.top().second.first;
        int r1 = q.top().second.second;
        q.pop();


        if( (l1 == 1) || (l1 == n) || (r1 == 1) || (r1 == n) )
           {
               ans = min(ans,nr);
             if(ans == 0)
                return 0;
           }

        for(int i = 0; i < 4; i++)
        {
            int l2 = l1 + x[i];
            int r2 = r1 + y[i];

            if(isin(l2,r2))
            {
                if(viz[l2][r2] == false)
                   {
                    if(ex[{nr,{l2,r2}}] == false)
                   {q.push({nr,{l2,r2}});
                    ex[{nr,{l2,r2}}] = true;
                   }
                   }
                else
                    if(nr + 1 <= 2 * n)
                    if(ex[{nr + 1,{l2,r2}}] == false)
                    {q.push({nr + 1, {l2, r2}});
                     ex[{nr + 1,{l2,r2}}] = true;
                    }
            }
        }


    }



    return ans;


}
