ll powmod(ll x, ll y) 
{ 
    ll res = 1;  
    x = x % MOD;
    while (y > 0) 
    { 
        if (y & 1) 
  	      res = (res*x) % MOD; 
        y = y>>1; // y = y/2 
        x = (x*x) % MOD;   
    } 
    return res; 
} 

int p[502*502];
bool boundary[502*502];
int dist[502*502];
bool blocked[502*502];
int n;
int solve(int i){

	for(int j=1;j<=n*n;j++)
		dist[j]=INF;
	dist[i]=0;
	priority_queue<pair<int,int>,vector<pair<int,int>>,greater<pair<int,int> > >pq;
	pq.push(mp(dist[i],i));

	while(!pq.empty()){
		pair<int,int>p=pq.top();
		pq.pop();
		if(boundary[p.ss]){return p.ff;}

		vector<int>cells={p.ss+1,p.ss-1,p.ss+n,p.ss-n};		
		for(auto cell:cells)
		{
			if(blocked[cell] and dist[cell]>dist[p.ss]+1){
				dist[cell]=dist[p.ss]+1;
				pq.push(mp(dist[cell],cell));
			}
			else if(!blocked[cell] and dist[cell]>dist[p.ss]){
				dist[cell]=dist[p.ss];
				pq.push(mp(dist[cell],cell));	
			}
		}
	}
}

