const int maxN = 500 + 5;
int n, d[maxN][maxN];
int on[maxN][maxN];

const int dx[] = {1, 0, -1, 0};
const int dy[] = {0, 1, 0, -1};
queue<pii> q0, q1;
void bfs() {
	while(q0.size() || q1.size()) {
		if(q0.size() == 0) q0.swap(q1);
		int x = q0.front().first, y = q0.front().second;
		q0.pop();
		for(int i = 0; i < 4; ++i) {
			int nx = x + dx[i], ny = y + dy[i];
			if(chmin(d[nx][ny], d[x][y] + on[nx][ny])) {
				if(on[nx][ny]) q1.emplace(nx, ny);
				else q0.emplace(nx, ny);
			}
		}
	}
}

int main() {
#ifndef LOCAL
	ios::sync_with_stdio(false);
	cin.tie(0); cout.tie(0);
#endif
	cin >> n;
	memset(d, 0, sizeof(d));
	memset(on, 0, sizeof(on));
	for(int i = 1; i <= n; ++i)
		for(int j = 1; j <= n; ++j)
			d[i][j] = n, on[i][j] = 1;
	for(int i = 1; i <= n; ++i)
		d[1][i] = d[n][i] = d[i][1] = d[i][n] = 1,
		q0.emplace(1, i),
		q0.emplace(n, i),
		q0.emplace(i, 1),
		q0.emplace(i, n);
	bfs();
	LL ans = 0;
	for(int i = 1; i <= n * n; ++i) {
		int p; cin >> p;
		int x = (p - 1) / n + 1, y = (p - 1) % n + 1;
//		eprintf("dispose (%d, %d)\n", x, y);
		for(int i = 0; i < 4; ++i) {
			int nx = x + dx[i], ny = y + dy[i];
			chmin(d[x][y], d[nx][ny]);
		}
		ans += d[x][y];
		on[x][y] = false;
		q0.emplace(x, y);
		bfs();
	}
	printf("%lld\n", ans);
	return 0;
}

