int main() {
	cin.tie(0);
	ios_base::sync_with_stdio(false);
	int N;
	cin >> N;
	vector<int> X(N * N), Y(N * N);
	vector<vector<int> > dist(N, vector<int>(N));
	for (int i = 0; i < N * N; ++i) {
		int p;
		cin >> p; --p;
		X[i] = p / N;
		Y[i] = p % N;
	}
	for (int i = 0; i < N; ++i) {
		for(int j = 0; j < N; ++j) {
			dist[i][j] = min({ i + 1, N - i, j + 1, N - j });
		}
	}
	vector<vector<bool> > flee(N, vector<bool>(N, false));
	long long ans = 0;
	for (int i = 0; i < N * N; ++i) {
		--dist[X[i]][Y[i]];
		ans += dist[X[i]][Y[i]];
		flee[X[i]][Y[i]] = true;
		queue<pair<int, int> > que;
