void buildseg(long long  x,long long  l,long long  r,string &a)
{
  if(l==r)
  {
    t[x][a[l]-'a']++;
  }
  else
  {
    long long  mid=(l+r)/2;
    buildseg(2*x+1,l,mid,a);
    buildseg(2*x+2,mid+1,r,a);
    vector<int> v(26,0);
    for(long long i=0;i<26;i++)
    {
      if(t[2*x+1][i]>0)
      {
        v[i]+=t[2*x+1][i];
      }
      if(t[2*x+2][i]>0)
      {
        v[i]+=t[2*x+2][i];
      }
    }
    t[x]=v;
  }
}
