  if(l>r)
  {
    vector<int> v(26,0);
    return v;
  }
  else if(l1==l && r1==r)
  {
    return t[x];
  }
  else
  {
    long long  mid=(l1+r1)/2;
    vector<int> b;
    b=sum(2*x+1,l1,mid,l,min(r,mid));
    vector<int> d;
    d=sum(2*x+2,mid+1,r1,max(l, mid+1),r);
    vector<int> v(26,0);
    for(long long i=0;i<26;i++)
    {
     if(b[i]>0)
     {
       v[i]+=b[i];
     }
     if(d[i]>0)
     {
       v[i]+=d[i];
     }
    }
    return v;
  }
}
