{
  if(l==r)
  {

    t[x][a[pos]-'a']=max(0,t[x][a[pos]-'a']-1);
    t[x][value-'a']++;
      a[pos]=value;
  }
  else
  {
    long long  mid=(l+r)/2;
    if(mid>=pos)
    {
      update(2*x+1,l,mid,value,pos,a);
    }
    else
    {
        update(2*x+2,mid+1,r,value,pos,a);
    }
    vector<int> v(26,0);
    for(long long i=0;i<26;i++)
    {
      if(t[2*x+1][i]>0)
