      if(i/n==(n-1)|| i==n*n)
      {
        continue;
      }
      int k=i/n;
      int l=i%n-1;
      int r=n-i/n-1;
      int q=(n-(i%n))%n;
      if(l==0 || q==0)
      {
        continue;
