constexpr ll N_MAX = 500;

ll N;
vector<ll> P;

void solve() {
	scanf("%lld", &N);
	P.assign(N*N, 0);
	rep(i, N*N) { scanf("%lld", &P[i]); P[i]--;}


	ll ans = 0;
	vector<vector<ll>> dist(N, vector<ll>(N,0));
	vector<vector<bool>> occupied(N, vector<bool>(N, 1));
	rep(i,N)rep(j,N){
		dist[i][j]=min({i,j,N-1-i,N-1-j});
	}

	queue<ll> que;
	rep(n,N*N){
		ll i=P[n]%N;
		ll j=P[n]/N;
		ans+=dist[i][j];
		occupied[i][j]=0;
		rep(k,4){
			ll nx=i+dx[k];
			ll ny=j+dy[k];
			if(nx==-1||nx==N||ny==-1||ny==N)continue;
			if(chmin(dist[nx][ny],dist[i][j])){
				que.push(nx+ny*N);
			}
		}
		while(!que.empty()){
			ll z=que.front();que.pop();
			ll i=z%N;
			ll j=z/N;
			rep(k,4){
				ll nx=i+dx[k];
				ll ny=j+dy[k];
				if(nx==-1||nx==N||ny==-1||ny==N)continue;
				if(chmin(dist[nx][ny], dist[i][j]+occupied[i][j])){
					que.push(nx+ny*N);
				}
			}
		}
	}

	printf("%lld\n", ans);

}

