int bfs(vector<vector<int>> cost){
  //cout << sx << " " << sy << " " << gx << " " << gy << endl;
  int min_cost = INF;
  while(!q.empty()){
    y = q.front().y, x = q.front().x, depth = q.front().depth;
    min_cost = min(min_cost, cost[y][x]);
    //cout << y << " " << x << " " << cost[y][x] << endl;
    //cout << x << " " << y << " " << depth << endl;
    q.pop();
    if (field[y][x] == 'G') return 0;
    for (int i = 0; i < 4; ++i){
      Corr next = {y + y_vec[i], x + x_vec[i], depth + 1};
      if (0 <= next.y && next.y < height && 0 <= next.x && next.x < width && field[next.y][next.x] == '.'){
        //cout << "hoge" << endl;
        field[next.y][next.x] = 'x';
        q.push(next);
      }
    }
  }
  return min_cost;
}

