int main() {
    int n;
    cin >> n;

    vector<int> ps(n * n);
    rep(i, n * n) cin >> ps[i], ps[i]--;

    vector<vector<int>> theater(n, vector<int>(n));
    vector<vector<bool>> exists(n, vector<bool>(n, true));

    rep(y, n) {
        rep(x, n) {
            theater[y][x] = min({y, n - 1 - y, x, n - 1 - x});
        }
    }


    auto update = [&](int ys, int xs) {
        queue<P> q;
        q.push({ys, xs});

        struct Direction {
            int y, x;
        };

        vector<Direction> directions = {
                {0,  1},
                {1,  0},
                {0,  -1},
                {-1, 0},
        };
        auto reachable = [&](int y, int x) {
            if (x == -1 || x == n || y == -1 || y == n) return false;
            return true;
        };
        while (!q.empty()) {
            P p = q.front();
            int y = p.first;
            int x = p.second;
            q.pop();
            for (Direction d : directions) {
                int nx = x + d.x;
                int ny = y + d.y;
                if (!reachable(ny, nx)) {
                    continue;
                }

                if (theater[ny][nx] > theater[y][x] + exists[y][x]) {
                    theater[ny][nx] = theater[y][x] + exists[y][x];
                    q.push({ny, nx});
                }
            }

        }
    };

    ll ans = 0;
    for (ll p : ps) {
        int y = p / n;
        int x = p % n;

        ans += theater[y][x];
        exists[y][x] = false;
        update(y, x);
    }

    cout << ans << endl;

}

