int a[maxN2];
int n;
ll up[maxN][maxN],down[maxN][maxN],left1[maxN][maxN],right1[maxN][maxN];
map<int,ii>refer;
void init(){
    int k =1;
    FOR1(i,n){
        FOR1(j,n){
            refer[k] = {i,j};
            k++;
        }
    }
    FOR1(i,n){
        FOR1(j,n){
            up[i][j] = i-1;
            down[i][j] = n-i;
            left1[i][j] = j-1;
            right1[i][j] = n-j;
        }
    }
}
void updateAll(int x,int y){
    for(int i =y+1;i <=n;i++)
        left1[x][i]-=1;
    for(int i = y -1; i>=1;i--)
        right1[x][i]-=1;
    for(int i = x-1;i>=1;i--)
        down[i][y]-=1;
    for(int i = x + 1;i<=n;i++)
        up[i][y]-=1;
    left1[x][y] = 0,right1[x][y] =0,up[x][y]=0,down[x][y]=0;
}
ll findmin(ll a,ll b,ll c ,ll d){
    return min(a,min(b,min(c,d)));
}
ll solve(){
    ll ans=0;
    for(int i = 1 ; i <=n*n;i++){
        ii temp = refer[a[i]];
        int x = temp.first;
        int y = temp.second;
        // if lie at boundary
        if( x == 1 || x == n || y == 1 || y == n){
            //cout<< "here";
            updateAll(x,y);
        }
        else{
            //cout<< "here2";
            ll a=up[x][y],b=down[x][y],c=left1[x][y],d=right1[x][y];
            ll mini=findmin(a,b,c,d);
            ans+=mini;
            updateAll(x,y);
        }
    }
    return ans;
}
