			{
				continue;
			}
			v[a][b] = min(v[a][b], val);
			++val;
		}
		//Updating the top
		a = ac;
		b = bc;
		copy = val;
		while (b > 0)
		{
			--b;

			if (v[a][b] == -1)
			{
				continue;
			}
			v[a][b] = min(v[a][b], copy);
			++copy;
		}
		//Updating the bottom
