using namespace std;

const int DXS[] = {0, -1, 1, 0};
const int DYS[] = {-1, 0, 0, 1};

int main() {

	const int n = read_item();
	vector<int> ps(n * n);
	for(auto i : range(n * n)) {
		ps[i] = read_item();
		ps[i] = ps[i] - 1;
	}

	vector<vector<int>> dist(n);
	vector<vector<bool>> seat(n);
	for(auto& d : dist) {
		d.resize(n, 0);
	}
	for(auto& s : seat) {
		s.resize(n, true);
	}
	for(auto i : range(n)) {
		for(auto j : range(n)) {
			dist[i][j] = min(min(i, n - 1 - i), min(j, n - 1 - j));
		}
	}

	i64 ans = 0;
	deque<pair<pair<int,int>,int>> q;

	for(auto p_it : range(n * n)) {

		int p = ps[p_it];
		int sx = p / n;
		int sy = p % n;

		ans += dist[sx][sy];
		seat[sx][sy] = false;

		for(auto i : range(4)) {
			int x = sx + DXS[i];
			int y = sy + DYS[i];
			if(x >= 0 && y >= 0 && x < n && y < n) {
				q.push_back({{x, y}, dist[sx][sy]});
			}
		}

		while(!q.empty()) {

			int cx = q.front().first.first;
			int cy = q.front().first.second;
			int nd = q.front().second;
			q.pop_front();

			if(dist[cx][cy] <= nd) {
				continue;
			}
			dist[cx][cy] = nd;

			for(auto i : range(4)) {
				int x = cx + DXS[i];
				int y = cy + DYS[i];
				if(x >= 0 && y >= 0 && x < n && y < n) {
					if(seat[cx][cy]) {
						q.push_back({{x, y}, nd + 1});
					} else {
						q.push_front({{x, y}, nd});
					}
				}
			}
		}
	}

	printf("%lld\n", ans);

	return 0;
}

