const int N=505;
const int dx[4]={1,-1,0,0};
const int dy[4]={0,0,1,-1};
int p[N][N],f[N][N],x[N*N],y[N*N];
vector<pii> q[N];
int n,l,r;
ll ans;

int main(){
	read(n);
	int cur=0;
	rep(i,1,n) rep(j,1,n){
		int tmp;
		read(tmp);
		int xx=(tmp-1)/n+1;
		int yy=tmp-(xx-1)*n;
		p[xx][yy]=++cur;
	}
	rep(i,1,n) rep(j,1,n){
		x[p[i][j]]=i;
		y[p[i][j]]=j;
		f[i][j]=min(min(abs(1-i),abs(i-n)),
					min(abs(1-j),abs(j-n)))+1;
	}
	rep(k,1,n*n){
		//cout<<x[k]<<" "<<y[k]<<" "<<f[x[k]][y[k]]<<endl;
		ans+=--f[x[k]][y[k]];
		q[f[x[k]][y[k]]].pb(mp(x[k],y[k]));
		rep(t,0,n+1){
			while(q[t].size()){
				int x=q[t].back().fi;
				int y=q[t].back().se;
				q[t].pop_back();
				REP(d,4){
					int xx=x+dx[d];
					int yy=y+dy[d];
					if(xx<1||n<xx||yy<1||n<yy) continue;
					int w=f[x][y]+(p[xx][yy]>k);
					if(w<f[xx][yy]){
						//cout<<x<<" "<<y<<"  "<<xx<<" "<<yy<<"  "<<w<<endl;
						f[xx][yy]=w;
						q[f[xx][yy]].pb(mp(xx,yy));
					}
				}
			}
		}
	}	
	cout<<ans<<endl;
	return 0;
}

