int dis[250050],vis[250050],cp;
int main() {
    int n;
    read(n);
    for(int i=1;i<=n*n;i++){
        int l = (i-1)/n+1,r = (i-1)%n+1;
        dis[i] = min(min(l-1,n-l),min(r-1,n-r));
        vis[i] = 1;
    }
    ll ans = 0;
    for(int i=1;i<=n*n;i++){
        read(cp);
        ans+=dis[cp];
        vis[cp] = 0;
        vector<int> Q = {cp};
        for(int t=0;t<Q.size();t++){
            int a = Q[t];
            if(a>n && dis[a-n]>dis[a]+vis[a]){
                dis[a-n] = dis[a]+vis[a];
                Q.PB(a-n);
            }
            if(a+n<=n*n && dis[a+n]>dis[a]+vis[a]){
                dis[a+n] = dis[a]+vis[a];
                Q.PB(a+n);
            }
            if(a%n!=1 && dis[a-1]>dis[a]+vis[a]){
                dis[a-1] = dis[a]+vis[a];
                Q.PB(a-1);
            }
            if(a%n!=0 && dis[a+1]>dis[a]+vis[a]){
                dis[a+1] = dis[a]+vis[a];
                Q.PB(a+1);
            }
        }
        dis[cp]+=1;
    }
    cout<<ans<<endl;
    return 0;
}

