using namespace std;

int dat[501][501]= {};
int dat2[501][501] = {};
bool block[501][501] = {};


struct S {
	int x;
	int y;
	int v;
};

auto cmp = [](const S& lhs, const S& rhs)
{
	return lhs.v > rhs.v;
};

void update(int x, int y, int v, int n, int m)
{
	priority_queue<S, vector<S>, decltype(cmp)> search(cmp);

	search.push({ x, y, v });
	while (!search.empty()) {
		S s = search.top();
		search.pop();

		if (s.x == -1 || s.x == n || s.y == -1 || s.y == n) continue;

		if (dat2[s.x][s.y] == m) return;
		dat2[s.x][s.y] = m;

		int cv = s.v;

		if (s.x == x && s.y == y) {
		}
		else {
			if (dat[s.x][s.y] <= cv) continue;
			dat[s.x][s.y] = cv;
		}
		if (!block[s.x][s.y]) cv++;

		search.push({ s.x - 1, s.y, cv });
		search.push({ s.x + 1, s.y, cv });
		search.push({ s.x, s.y - 1, cv });
		search.push({ s.x, s.y + 1, cv });
	}
}

int main()
{
	ios_base::sync_with_stdio(false);
	cin.tie(NULL);
	cout << fixed << setprecision(20);

	int n; cin >> n;

	FOR_LT(i, 0, n) {
		FOR_LT(j, 0, n) {
			int a = i;
			int b = n - i - 1;
			int c = j;
			int d = n - j - 1;
			dat[i][j] = min(min(a, b), min(c, d));
		}
	}

	int64_t ans = 0;
	REP(n*n) {
		int m;  cin >> m; m--;
		int x = m % n;
		int y = m / n;
		int v = dat[x][y];
		block[x][y] = true;
		update(x, y, v, n, m + 1);
		ans += v;
	}

	cout << ans << endl;

	return 0;
}

