bool maze[MAX][MAX];

void dfs(ll x , ll y){
  ll z = d[x][y] + maze[x][y];
  // 距離が減るところをdfsで減らす
  rep(i,4){
    ll nx = x + dx[i];
    ll ny = y + dy[i];
    if(nx < 0 or ny < 0) continue;
    if(d[nx][ny] > z){
      d[nx][ny] = z;
      dfs(nx , ny);
    }
  }
}

