int n;
int trans(int i, int j) {
    return i * n + j;
}
void solve() {
    cin >> n;
    vi p(n * n);
    cin >> p;
    vi dist(n * n, 1e10);
    vi neig = {1, -1, n, -n};
    vector<set<int>> back(n * n);
    rep(i, 0, n) rep(j, 0, n) {
        int cur_d = i;
        set<int> par = {-n};
        if (n - i - 1 < cur_d) {cur_d = n - i - 1;par.clear();}
        if (n - i - 1 == cur_d) {par.insert(n);}
        if (j < cur_d) {cur_d = j;par.clear();}
        if (j == cur_d) {par.insert(-1);}
        if (n - j - 1 < cur_d) {cur_d = n - j - 1;par.clear();}
        if (n - j - 1 == cur_d) {par.insert(1);}
        dist[trans(i, j)] = cur_d;
        back[trans(i, j)] = par;
    }
    int res = 0;
    vi used(n * n, 1);
    for (int i : p) {
        --i;
        res += dist[i];
        used[i] = 0;
        queue<int> q;
        q.push(i);
        while (q.size()) {
            int v = q.front();
            q.pop();
            for (int j: neig) {
                if (v + j < 0 || v + j >= n * n) continue;
                if (dist[v + j] > dist[v] + used[v]) {
                    dist[v + j] = dist[v] + used[v];
                    q.push(v + j);
                }
            }
        }
    }
    put(res);

}


