bool rem[505][505];

inline bool out(int x,int y)
{
	return (x<0 || y<0 || x>=n || y>=n);
}

void update(int x,int y,int value)
{
	int nx,ny,cost;
	for(int k=0;k<4;k++)
	{
		nx=x+dx[k];
		ny=y+dy[k];
		if(out(nx,ny)) continue;
		cost=value+(rem[x][y]);
		if(f[nx][ny]<=cost) continue;
		f[nx][ny]=cost;
		update(nx,ny,cost);
	}
}

