    const int dy[4] = {0,0,1,-1};
    const int INF = INT32_MAX>>2;
    vector<bool> k (n,true);
    vector<int> d(n*n,INF);
    rep(i,n*n) {
        int x = i%n;
        int y = i/n;
        chmin(d[i], x);
        chmin(d[i], y);
        chmin(d[i], n-x-1);
        chmin(d[i], n-y-1);
