// 0-indexedでx, yを渡すこと
ll to_idx(ll x, ll y){
  return y * N + x;
}

void to_xy(ll idx, ll &x, ll &y){
  x = idx % N;
  y = idx / N;
}

void dfs(ll cust_idx, vector<ll> &cbuckets, vector<bool> &visited, vector<bool> &occ_buckets){

  ll x, y;
  to_xy(cust_idx, x, y);
  ll next_cost = cbuckets[cust_idx] + occ_buckets[cust_idx];

  rep(ti, 4){
    ll i = dx_4[ti];
    ll j = dy_4[ti];

    ll tmpx = x - i;
    ll tmpy = y - j;
    if (tmpx < 0 || tmpx >= N || tmpy < 0 || tmpy >= N) continue;
    else{
      ll tmpidx = to_idx(tmpx, tmpy);
      if (cbuckets[tmpidx] > next_cost){
        assert(cbuckets[tmpidx] == next_cost + 1);
        cbuckets[tmpidx] = next_cost;
        // 見つけたマスから更にbfs
        dfs(tmpidx, cbuckets, visited, occ_buckets);
      }
    }

  }

}

void exit_xy(ll cust_x, ll cust_y, vector<ll> &cbuckets, vector<bool> &occ_buckets){
