int ds[] = { -1,0,1,0 };
int dt[] = { 0,-1,0,1 };

int main() {
	int n;
	cin >> n;
	vector<vector<int>> seat(n, vector<int>(n));
	int cnt = 0;
	rep(i, n) {
		rep(j, n) {
			seat[i][j] = cnt;
			cnt++;
		}
	}
	int ans = 0;
	rep(i, n* n) {
		int p;
		cin >> p;
		p--;
		int s = p / n;
		int t = p - s * n;
		//bfsで、最も観客に嫌われない経路を探索する。
		queue<P> q;
		//すでにseat[i][j]に訪れたか？
		vector<vector<bool>> yet(n, vector<bool>(n));
		//seat[i][j]に人がいるか？
		vector<vector<bool>> check(n, vector<bool>(n, true));
		P start(s, t);
		q.push(start); 
		yet[s][t] = true;
		int hate = 0;
		bool flag = false;
		while (!q.empty()) {
			P now = q.front(); q.pop();
			check[now.first][now.second] = false;
			rep(j, 4) {
				int nexts = s + ds[i];
				int nextt = t + dt[i];
				if (nexts < 0 || nexts >= n || nextt < 0 || nextt >= n) {
					flag = true;
					break;
				}
				P next(nexts, nextt);
				if (check[nexts][nextt]) hate++;
				yet[nexts][nextt] = true;
				q.push(next);
			}
			if (flag) break;
		}
		ans += hate;
	}
	cout << ans << endl;
	return 0;
}

