typedef long long ll;

int main() {
	int n; cin >> n;
	vector<int> p(n*n);
	for (int i = 0; i < n*n; ++i) cin >> p[i];
	vector<vector<int> > d(n, vector<int>(n, -1));
	vector<vector<bool> > used(n, vector<bool>(n, false));

	for (int i = 0; i < n; ++i) {
		for (int j = 0; j < n; ++j) {
			d[i][j] = min({i, j, n-1-i, n-1-j});
		}
	}

	vector<int> DI = {1, 0, -1, 0};
	vector<int> DJ = {0, 1, 0, -1};

	ll ans = 0;
	for (int x : p) {
		x--;
		int i = x/n; int j = x%n;
		ans += d[i][j];
		used[i][j] = true;
		deque<int> q;
		for (int k = 0; k < 4; ++k) {
			int di = DI[k]; int dj = DJ[k];
			if (0 > i+di or i+di >= n or 0 > j+dj or j+dj >= n) continue;
			if (d[i+di][j+dj] > d[i][j]) {
				d[i+di][j+dj] = d[i][j];
				q.push_back((i+di)*n + j+dj);
			}
		}
		while (!q.empty()) {
			int l = q.front();
			q.pop_front();
			int i = l/n; int j = l%n;
			for (int k = 0; k < 4; ++k) {
				int di = DI[k]; int dj = DJ[k];
				if (0 > i+di or i+di >= n or 0 > j+dj or j+dj >= n) continue;
				if (used[i][j]) {
					if (d[i+di][j+dj] > d[i][j]) {
						d[i+di][j+dj] = d[i][j];
						q.push_front((i+di)*n + j+dj);
					}				
				} else {
					if (d[i+di][j+dj] > d[i][j] + 1) {
						d[i+di][j+dj] = d[i][j] + 1;
						q.push_back((i+di)*n + j+dj);
					}				
				}
			}
		}
	}
	cout << ans << endl;

	return 0;
}

