  for(int n = 0; n < N*N; ++n) {
    int P; std::cin >> P; --P;
    int i = P%N, j = P/N;
    ans += dist[i][j];
    // bfs
    std::queue<V> q;
    wall[i][j] = false;
    int mi = N;
    for(int k = 0; k < 4; ++k) {
        int nx = i + dx[k];
        int ny = j + dy[k];
        if(nx < 0 || ny < 0 || nx > N-1 || ny > N-1) continue;
        mi = std::min(mi, dist[nx][ny] + (wall[nx][ny]?1:0));
    }
    dist[i][j] = std::min(dist[i][j], mi);
    for(int k = 0; k < 4; ++k) {
        int nx = i + dx[k];
        int ny = j + dy[k];
        if(nx < 0 || ny < 0 || nx > N-1 || ny > N-1) continue;
        if(dist[nx][ny] > dist[i][j]) q.emplace(nx, ny);
    }
    while(!q.empty()) {
      V v = q.front(); q.pop();
      int mi = N;
      for(int k = 0; k < 4; ++k) {
        int nx = v.x + dx[k];
        int ny = v.y + dy[k];
        if(nx < 0 || ny < 0 || nx > N-1 || ny > N-1) continue;
        mi = std::min(mi, dist[nx][ny] + (wall[nx][ny]?1:0));
      }
      if(dist[v.x][v.y] <= mi) continue;
      dist[v.x][v.y] = std::min(dist[v.x][v.y], mi);
      for(int k = 0; k < 4; ++k) {
        int nx = v.x + dx[k];
        int ny = v.y + dy[k];
        if(nx < 0 || ny < 0 || nx > N-1 || ny > N-1) continue;
        if(dist[nx][ny] > dist[v.x][v.y]) q.emplace(nx, ny);
      }
    }
  }
  fin(ans);
  return 0;
}

