  for(Int i=0;i<m;i++){
    Int y=i/n,x=i%n;
    chmin(ds[i],y);
    chmin(ds[i],n-(y+1));
    chmin(ds[i],x);
    chmin(ds[i],n-(x+1));
  }

  Int dy[]={0,0,1,-1};
  Int dx[]={1,-1,0,0};
  auto in=[&](Int y,Int x){return 0<=y and y<n and 0<=x and x<n;};

  Int ans=0;
  for(Int p:ps){
    ans+=ds[p];
    using P = pair<Int, Int>;
    priority_queue<P, vector<P>, greater<P> > pq;
    pq.emplace(ds[p],p);

    while(!pq.empty()){
      Int v=pq.top().second;
      if(ds[v]<pq.top().first){
        pq.pop();
        continue;
      }
      pq.pop();
      Int y=v/n,x=v%n;
      for(Int k=0;k<4;k++){
