const ll M = 507;
const ll MX = M*M;
ll n;
bool valid(ll x, ll y) {
    return x>=0 && y>=0 && x<n && y<n;
}

set<pll> isl[M];
ll uf[MX];
bool isisl[MX];
ll dst[MX];
void init() { F(MX) uf[i] = i; }
int find(int e) { return uf[e] == e ? e : uf[e] = find(uf[e]); }
void mrg(int i, int j) { uf[find(i)] = find(j); }

void f(ll iy, ll id, ll&dist, ll&disl, ll x, ll i, ll y) {
    id = find(id);
    ll cd = max(0,abs(i-x)-1) + 
        max(0,abs(iy-y)-1) +
        + (i!=x && iy!=y) +
        dst[id];
    if(dist>cd) {
        dist=cd;
        disl=id;
    }
}

ll closestIsland(ll x, ll y) {
    ll dist = min(min(x,n-x-1), min(y,n-y-1));
    ll disl=-1;
    F(n) { // which row
        if(!isl[i].size()) continue;
        auto it = isl[i].lower_bound({y,0});
        if(it!=isl[i].end()) {
            f(it->x, it->y,dist,disl,x,i,y);
        }
        if(it != isl[i].begin()) {
            it--;
            f(it->x, it->y,dist,disl,x,i,y);
        }
    }
    return dist;
}

const ll dx[]={1,0,-1,0};
const ll dy[]={0,-1,0,1};
