    F(n*n) {
        ll p; cin >> p; p--;
        ll x = p/n, y=p%n;
        ll cur = x*n+y;
        // find closest island
        ll cret = closestIsland(x,y);
//         dbg(p+1,cret);
        ret += cret;
        // update islands
        set<ll> ngisl;
        vpll rowisl;
        F(D) {
            ll xx = x+dx[i], yy=y+dy[i];
            if(valid(xx,yy)) {
                ll c = find(xx*n+yy);
                if(isisl[c]) {
//                     dbg("ng:",xx,yy);
                    ngisl.insert(c);
                }
            }
        }
        if(ngisl.size()) {
            for(auto i:ngisl) {
                mrg(cur,i);
                //dbg("MRG",cur/n,cur%n,"with",i/n,i%n);
            }
        }
        cur = find(cur);
