const int maxN = 511;
const int defX[4] = {-1, 1, 0, 0};
const int defY[4] = {0, 0, -1, 1};

int n;
int cost[maxN][maxN], dist[maxN][maxN];
queue< pair<int, int> > Q;
int answer;

void move(int x, int y) {
  dist[x][y]--;
  cost[x][y] = 0;
  answer += dist[x][y];
  Q.push(mp(x, y));

  /*
  cerr << dist[x][y] << '\n';
  for (int i = 0; i < n; i++) {
    for (int j = 0; j < n; j++)
      cerr << dist[i][j] << ' ';
    cerr << '\n';
  }
  */

  while (!Q.empty()) {
    x = Q.front().first;
    y = Q.front().second;
    Q.pop();

    for (int i = 0; i < 4; i++) {
      int xx = x + defX[i];
      int yy = y + defY[i];

      if (xx < 0 || xx >= n) continue;
      if (yy < 0 || yy >= n) continue;
      if (dist[xx][yy] > dist[x][y] + cost[xx][yy]) {
        dist[xx][yy] = dist[x][y] + cost[xx][yy];
        Q.push(mp(xx, yy));
      }
    }
  }
}

int main()
{
  //freopen("test.in", "r", stdin);

  scanf("%d", &n);
  for (int i = 0; i < n; i++) {
    for (int j = 0; j < n; j++) {
      cost[i][j] = 1;
      dist[i][j] = min(min(i + 1, j + 1),
                       min(n - i, n - j));
    }
  }

  for (int i = 0; i < n * n; i++) {
    int x;

    scanf("%d", &x);
    x--;
    move(x / n, x % n);
  }

  printf("%d\n", answer);


  return 0;
}

