int bfs(int x, int y){
    queue<pi> q; q.push(make_pair(x,y));
    vvi dis(507,vi(507,-1)); dis[x][y] = 0;
    int ans = 1e9;
    while(!q.empty()){
        pi num = q.front(); q.pop();
        int x = num.first, y = num.second;
        rep(i,4){
            int xx = x+dir[i][0], yy = y+dir[i][1];
            if(xx < 0 || xx > n-1 || yy < 0 || yy > n-1){
                chmin(ans,dis[x][y]);
                if(dis[x][y] == 0) thr[x][y] = true;
                continue;
            }
            if(thr[xx][yy]){
                chmin(ans,dis[x][y]);
                if(dis[x][y] == 0) thr[x][y] = true;
                continue;
            }
            if(dis[xx][yy] != -1) continue;
            dis[xx][yy] = dis[x][y];
            if(!lea[xx][yy]) dis[xx][yy]++;
            q.push(make_pair(xx,yy));
        }
    }
    return ans;
}

