int dx[4] = {0, 1, 0, -1}; // u, r, d, l
int dy[4] = {-1, 0, 1, 0};

int main() {
  ios::sync_with_stdio(false);
  cin.tie(0);

  int N; cin >> N;
  vector<vector<bool>> grid(N, vector<bool> (N, true));
  int NN = N*N;
  vi A(NN);
  rep(i, 0, NN) {
    cin >> A[i];
    A[i]--;
  }

  vvi dist(N, vi(N));
  rep(i, 0, N) {
    rep(j, 0, N) {
      int d = N-1;
      chmin(d, N-1-i);
      chmin(d, i);
      chmin(d, N-1-j);
      chmin(d, j);
      dist[i][j] = d;
    }
  }

  int ans = 0;
  for (int a: A) {
    int x = a % N;
    int y = a / N;
    ans += dist[y][x];
    grid[y][x] = false;
    queue<int> q;
    q.push(a);
    while (!q.empty()) {
      int v = q.front(); q.pop();
      int vx = v % N;
      int vy = v / N;
      bool vp = grid[vy][vx]; // 人がまだいる
      int vd = dist[vy][vx];
      rep(i, 0, 4) {
        int ux = vx + dx[i];
        int uy = vy + dy[i];
        if (0 <= ux && ux < N && 0 <= uy && uy < N) {
          int u = uy*N + ux;
          int nxtd = vd;
          if (vp) nxtd++;

          if (dist[uy][ux] > nxtd) {
            dist[uy][ux] = nxtd;
            q.push(u);
          }
        }
      }
    }
  }

  cout << ans << endl;

  return 0;
};

