//Complexity: O(1)
//Stores what info. segment[i..j] should store
node merge(node &left, node &right){
    node temp;
    temp.data = left.data + right.data;
    return temp;
}

//Complexity: O(n)
void build(int segNum, int id = 1, int l = 0, int r = N){
    vector<node> &sg = seg[segNum];
    if(r - l < 2){
        //base case : leaf node information to be stored here
        sg[id].assign(1);
        return;
    }

    int mid = (l + r) / 2;
    int left = 2 * id, right = left + 1;
    build(segNum, left, l, mid);
    build(segNum, right, mid, r);
    sg[id] = merge(sg[left], sg[right]);
}

//Complexity: O(log n)
void update(int segNum, int p, int y, int id = 1, int l = 0, int r = N){
    vector<node> &sg = seg[segNum];
    if(r - l < 2){ 
        //base case : leaf node information to be stored here
        sg[id].assign(y);
        return;
    }

    int mid = (l + r) / 2;
    int left = 2 * id, right = left + 1;
    if(p < mid){
        update(segNum, p, y, left, l, mid);
    }else{
        update(segNum, p, y, right, mid, r);
    }
    sg[id] = merge(sg[left], sg[right]);
}

//Complexity: O(log n)
node query(int segNum, int x, int y, int id = 1, int l = 0, int r = N){
    vector<node> &sg = seg[segNum];
    if(r <= x || y <= l){ // No overlap, return useless
        node temp;
        temp.assign(0);
        return temp;
    }

    if(x <= l && r <= y){ // overlap
        return sg[id];
    }

    int mid = (l + r) / 2;
    int left = 2 * id, right = left + 1;
    node a = query(segNum, x,  y, left, l, mid);
    node b = query(segNum, x, y, right, mid, r);
    return merge(a, b);
}

