void solution() {
  int n;
  cin >> n;
  set<int> r[n + 2], c[n + 2];
  int mat[n + 2][n + 2];
  int dst[n + 2][n + 2];
  vector<ii> pos(n * n + 1);
  int val = 1;
  for (int i = 1; i <= n; i++) {
    for (int j = 1; j <= n; j++) {
      pos[val] = ii(i, j);
      mat[i][j] = val++;
    }
  }

  for (int i = 0; i <= n + 1; i++) {
    mat[0][i] = mat[i][0] = mat[i][n + 1] = mat[n + 1][i] = -1;
  }

  for (int i = 0; i <= n + 1; i++) {
    for (int j = 0; j <= n + 1; j++) {
      dst[i][j] = INF;
      r[i].insert(j);
      c[j].insert(i);
    }
  }

  int ans = 0;
  for (int i = 0; i < n * n; i++) {
    int st;
    cin >> st;
    int x = pos[st].ff;
    int y = pos[st].ss;
    vector<ii> vis;
    deque<ii> q;
    q.push_back(ii(x, y));
    vis.pb(ii(x, y));
    dst[x][y] = 0;
    // cout << "starting at " << x << " " << y << endl;
    while (q.size() > 0) {
      int cx = q.front().ff;
      int cy = q.front().ss;
      q.pop_front();
      // cout << "at " << cx << " " << cy << endl;
      if (cx == 0 || cx == n + 1 || cy == 0 || cy == n + 1) {
        ans += dst[cx][cy];
        break;
      }

      // move
      auto it = c[cy].find(cx);
      ++it;
      int add1 = *it;
      --it;
      --it;
      int sub1 = *it;
      if (dst[cx][cy] + (mat[add1][cy] != -1) < dst[add1][cy]) {
        dst[add1][cy] = dst[cx][cy] + (mat[add1][cy] != -1);
        vis.pb(ii(add1, cy));
        if (mat[add1][cy] == -1)
          q.push_front(ii(add1, cy));
        else
          q.push_back(ii(add1, cy));
      }

      if (dst[cx][cy] + (mat[sub1][cy] != -1) < dst[sub1][cy]) {
        dst[sub1][cy] = dst[cx][cy] + (mat[sub1][cy] != -1);
        vis.pb(ii(sub1, cy));
        if (mat[sub1][cy] == -1)
          q.push_front(ii(sub1, cy));
        else
          q.push_back(ii(sub1, cy));
      }

      it = r[cx].find(cy);
      ++it;
      add1 = *it;
      --it;
      --it;
      sub1 = *it;

      if (dst[cx][cy] + (mat[cx][add1] != -1) < dst[cx][add1]) {
        dst[cx][add1] = dst[cx][cy] + (mat[cx][add1] != -1);
        vis.pb(ii(cx, add1));
        if (mat[cx][add1] == -1)
          q.push_front(ii(cx, add1));
        else
          q.push_back(ii(cx, add1));
      }

      if (dst[cx][cy] + (mat[cx][sub1] != -1) < dst[cx][sub1]) {
        dst[cx][sub1] = dst[cx][cy] + (mat[cx][sub1] != -1);
        vis.pb(ii(cx, sub1));
        if (mat[cx][sub1] == -1)
          q.push_front(ii(cx, sub1));
        else
          q.push_back(ii(cx, sub1));
      }
    }
    for (ii p : vis) dst[p.ff][p.ss] = INF;
    r[x].erase(y);
    c[y].erase(x);
  }
  cout << ans << endl;
}

