ll dfs(ll s, ll N, ll x, ll y, const vvb &map, vvll &dp, vvb &ald){
    ald[x][y] = true;
    if(dp[x][y] > -1){
        return dp[x][y];
    }
    if(x == 0||x == N-1){return dp[x][y] = 0;}
    if(y == 0||y == N-1){return dp[x][y] = 0;}
    ll p = 1000000000;
    if(0<=x-1&&s != 3&&ald[x-1][y]==false){
        ll h;
        if(dp[x-1][y]<-1){
            dp[x-1][y] =  dfs(1, N, x-1, y, map, dp, ald);
        }
        h = dp[x-1][y];
        if(map[x-1][y] == true){h++;}
        p = min(p, h);
    }
    if(0<=y-1&&s != 4&&ald[x][y-1]==false){
        ll i;
        if(dp[x][y-1]<-1){
            dp[x][y-1] =  dfs(2, N, x, y-1, map, dp, ald);
        }
        i = dp[x][y-1];
        if(map[x][y-1] == true){i++;}
        p = min(p, i);
    }
    if(x+1<N&&s != 1&&ald[x+1][y]==false){
        ll j;
        if(dp[x+1][y]<-1){
            dp[x+1][y] =  dfs(3, N, x+1, y, map, dp, ald);
        }
        j = dp[x+1][y];
        if(map[x+1][y] == true){j++;}
        p = min(p, j);
    }
    if(y+1<N&&s != 2&&ald[x][y+1]==false){
        ll k;
        if(dp[x][y+1]<-1){
            dp[x][y+1] =  dfs(4, N, x, y+1, map, dp, ald);
        }
        k = dp[x][y+1];
        if(map[x][y+1] == true){k++;}
        p = min(p, k);
    }
    dp[x][y] = p; return dp[x][y];
}

int main(){
    ll N; cin >> N;
    vll p(N*N);
    rep(i, 0, N*N){
        cin >> p[i];
    }
    vvb map(N, vb(N, true));
