    rep(i, 0, N*N){
        vvll dp(N, vll(N, -10));
        vvb ald(N, vb(N, false));
        ll k = p[i];
        ll m = k % N;
        ll x, y;
        if(m == 0){
            x = N - 1; y = k/N- 1;
        }else{
