struct UnionFind{
  vector<int> par;						//par[i]:iの親の番号
  UnionFind(int N):par(N){				//最初は全てが根であるとして初期化
    for(int i=0; i<N; i++) par[i]=i;
  }

  int root(int x){						//データxが属する木の根
    if(par[x]==x) return x;
    return par[x]=root(par[x]);
  }

  void unite(int x,int y){				//xとyの木を併合
    int rx=root(x);
    int ry=root(y);
    if(rx==ry) return;
    par[rx]=ry;
  }

  bool same(int x,int y){				//x,yが属する木が同じならtrueを返す
    int rx=root(x);
    int ry=root(y);
    return rx == ry;
  }
};

int main(){
  int N,ans=0,cnt=0;
  cin>>N;
  UnionFind tree(N*N+1);
  int MN[(N+1)*(N+1)];

  bool CAN[N+2][N+2];
  for(int i=0; i<=N+1; ++i){
    for(int j=0; j<=N+1; ++j){
      CAN[i][j]=false;
      MN[i*N+j]=MAX;
    }
  }

  for(int i=1; i<=N*N; ++i){
    int P;
    cin>>P;
    cnt=MAX;
    int Y=(P+N-1)/N;
    int X=(P-1)%N+1;

    chmin(cnt,X-1);
    chmin(cnt,N-X);
    chmin(cnt,Y-1);
    chmin(cnt,N-Y);
    MN[(Y-1)*N+X]=cnt;

    for(int i=0; i<4; ++i){
      int ny=Y+dy[i],nx=X+dx[i];
      if(nx<1||nx>N||ny<1||ny>N||CAN[ny][nx]==false) continue;

      chmin(MN[(Y-1)*N+X],MN[tree.root((ny-1)*N+nx)]);
      chmin(MN[tree.root((ny-1)*N+nx)],MN[(Y-1)*N+X]);
      tree.unite((ny-1)*N+nx,(Y-1)*N+X);
    }

    CAN[Y][X]=true;
    ans+=MN[(Y-1)*N+X];
  }

  co(ans);
  return 0;
}

