	for(int i = 0; i < n * n; ++i){
		int x;
		cin >> x;
		const int r = (x - 1) / n, c = (x - 1) % n;
		p[i] = (r + 1) * m + (c + 1);
	}
	vector<int> cache(m * m);
	vector<char> done(m * m, 1);
	for(int i = 0; i < n; ++i){
		for(int j = 0; j < n; ++j){
			cache[(i + 1) * m + (j + 1)] = min({ i, n - 1 - i, j, n - 1 - j });
			done[(i + 1) * m + (j + 1)] = 0;
		}
	}
	const array<int, 4> delta = { -m, -1, 1, m };
	vector<int> q0, q1;
	int answer = 0;
	for(const auto s : p){
		const int dist = cache[s];
		answer += dist;
		done[s] = 1;
		int cost = dist;
		q0.push_back(s);
		while(!q0.empty()){
			while(!q0.empty()){
				const int c = q0.back();
				q0.pop_back();
				for(const auto d : delta){
					const int cc = c + d;
					if(cost < cache[cc]){
						cache[cc] = cost;
						if(done[cc]){
							q0.push_back(cc);
						}else{
							q1.push_back(cc);
						}
					}
				}
			}
			q0.swap(q1);
			++cost;
		}
	}
	cout << answer << endl;
	return 0;
}

