const int INF = 1e9;
//const ll mod = 1000000007;
struct SegmentTree {
private:
    int n;
    vector<int> node;

public:
    SegmentTree() {
        int sz = 500;
        n = 1; while(n < sz) n *= 2;
        node.resize(2*n-1, INF);
        for(int i=0; i<sz; i++) node[i+n-1] = INF;
        for(int i=n-2; i>=0; i--) node[i] = min(node[2*i+1], node[2*i+2]);
    }

    void update(int x, int val) {
        x += (n - 1);
        if(val >= node[x]) return;
        node[x] = val;
        while(x > 0) {
            x = (x - 1) / 2;
            node[x] = min(node[2*x+1], node[2*x+2]);
        }
    }
    // hannkaikukann 
    int getmin(int a, int b, int k=0, int l=0, int r=-1) {
        if(r < 0) r = n;
        if(r <= a || b <= l) return INF;
        if(a <= l && r <= b) return node[k];

        int vl = getmin(a, b, 2*k+1, l, (l+r)/2);
        int vr = getmin(a, b, 2*k+2, (l+r)/2, r);
        return min(vl, vr);
    }
};

ll dist[500][500];
bool a[500][500];
int dh[4] = {0, 0, 1, -1};
int dw[4] = {1, -1, 0, 0};
ll N;

void f(int h, int w, ll val) {
    chmin(dist[h][w], val);
    queue<i_i> que;
    que.push({h, w});
    while(!que.empty()) {
        auto tmp = que.front();
        que.pop();
        int nowh = tmp.first;
        int noww = tmp.second;
        for(int k = 0; k < 4; k++) {
            int newh = nowh + dh[k];
            int neww = noww + dw[k];
            if(newh < 0 or newh >= N or neww < 0 or neww >= N) continue;
            ll newc = dist[nowh][noww];
            if(a[nowh][noww]) newc++;
            if(chmin(dist[newh][neww], newc)) {
                que.push({newh, neww});
            }
        }
    }
}

int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);
    cin >> N;
    ll ans = 0;
    for(ll h = 0; h < N; h++) {
        for(ll w = 0; w < N; w++) {
            dist[h][w] = min(min(h, N - 1 - h), min(w, N - 1 - w));
            a[h][w] = true;
        }
    }
    for(int i = 0; i < N * N; i++) {
        ll p;
        cin >> p;
        p--;
        ll h = p / N;
        ll w = p % N;
        ans += dist[h][w];
        ll val = dist[h][w];
        a[h][w] = false;
        f(h, w, val);
    }
    cout << ans << endl;
    return 0;
}

