const int d[4][2] = {{1, 0}, {0, 1}, {-1, 0}, {0, -1}};
const int N = 500;
bool visit[N][N];
int dp[N][N], h[N][N];
int n;

int solve(int x, int y) {
  deque<ii> Q;
  dp[x][y] = 0;
  Q.push_back({x, y});
  vector<ii> footprint;
  int ret = INF;
  while (!Q.empty()) {
    int x = Q.front().first, y = Q.front().second;
    Q.pop_front();
    footprint.push_back({x, y});
    if (x == 0 || x == n - 1 || y == 0 || y == n - 1) {
      ret = min(ret, dp[x][y]);
    }
    for (int k = 0; k < 4; ++k) {
      int nx = x + d[k][0];
      int ny = y + d[k][1];
      if (nx < 0 || nx >= n || ny < 0 || ny >= n) continue;
      if (visit[nx][ny]) {
        if (dp[nx][ny] > dp[x][y]) {
          dp[nx][ny] = dp[x][y];
          Q.push_front({nx, ny});
        }
      } else {
        if (dp[nx][ny] > dp[x][y] + 1) {
          dp[nx][ny] = dp[x][y] + 1;
          Q.push_back({nx, ny});
        }
      }
    }
  }
  for (auto& p : footprint) {
    int x = p.first, y = p.second;
    dp[x][y] = INF;
  }
  return ret;
}

int main() {
  scanf("%d", &n);
  int64 ret = 0;
  for (int i = 0; i < n; ++i) {
    for (int j = 0; j < n; ++j) {
      dp[i][j] = INF;
    }
  }
  for (int i = 0; i < n * n; ++i) {
    int pos;
    scanf("%d", &pos);
    --pos;
    int x = pos / n, y = pos % n;
    int cur = solve(x, y);
    // trace(x, y, cur);
    ret += cur;
    visit[x][y] = true;
  }
  printf("%lld\n", ret);
  return 0;
}

