struct S {
    int x;
    int y;
    int v;
};

auto cmp = [](const S& lhs, const S& rhs)
{
    return lhs.v > rhs.v;
};

void add(int x, int y, int v, int n, int m, queue<S>& s)
{
    if (x == -1 || x == n || y == -1 || y == n) return;


    if (v < dat[x][y]) {
        dat[x][y] = v;
        int nv = v;
        if (!block[x][y]) nv++;
        s.push({ x, y, nv });
    }
}

void update(int x, int y, int v, int n, int m)
{
    queue<S> search;

    search.push({ x, y, v });
    while (!search.empty()) {
        S s = search.front(); 
        search.pop();

        int cv = s.v;

        add(s.x - 1, s.y, cv, n, m, search);
        add(s.x + 1, s.y, cv, n, m, search);
        add(s.x, s.y - 1, cv, n, m, search);
        add(s.x, s.y + 1, cv, n, m, search);
        //cout << search.size() << endl;
    }
}

