ll get_cost(int r, int c){
	map< pii , ll > d;

	d[{r,c}] = 0;
	deque<pii> q;
	q.push_front({r,c});

	while (!q.empty()) {
	    pii v = q.front();
	    q.pop_front();

	    int row = v.F;
	    int col = v.S;

	    if ( row == 0 || row == n-1 || col == 0 || col == n-1 )
	    	return d[{row,col}];

	    if ( d.find({row+1,col}) == d.end() || d[{row,col}] + mat[row+1][col] < d[{row+1,col}] ){
	    	d[{row+1,col}] = d[{row,col}] + mat[row+1][col];
	    	if ( mat[row+1][col] == 1 )
	    		q.push_back({row+1, col});
	    	else
	    		q.push_front({row+1,col});
	    }

	    if ( d.find({row-1,col}) == d.end() || d[{row,col}] + mat[row-1][col] < d[{row-1,col}] ){
	    	d[{row-1,col}] = d[{row,col}] + mat[row-1][col];
	    	if ( mat[row-1][col] == 1 )
	    		q.push_back({row-1, col});
	    	else
	    		q.push_front({row-1,col});
	    }

	    if ( d.find({row,col+1}) == d.end() || d[{row,col}] + mat[row][col+1] < d[{row,col+1}] ){
	    	d[{row,col+1}] = d[{row,col}] + mat[row][col+1];
	    	if ( mat[row][col+1] == 1 )
	    		q.push_back({row, col+1});
	    	else
	    		q.push_front({row,col+1});
	    }

	    if ( d.find({row,col-1}) == d.end() || d[{row,col}] + mat[row][col-1] < d[{row,col-1}] ){
	    	d[{row,col-1}] = d[{row,col}] + mat[row][col-1];
	    	if ( mat[row][col-1] == 1 )
	    		q.push_back({row, col-1});
	    	else
	    		q.push_front({row,col-1});
	    }

	}

}

int main(){
	ri(n);
	FOR(i,0,n){
		FOR(j,0,n){
			mat[i][j] = 1;
		}
	}

	ll ans = 0;
	FOR(i,0,n*n){
