void solve() {
	int n; cin >> n;
	vector<int> in(n*n);
	rep(i, n*n)cin >> in[i];
	rep(i, n*n) {
		in[i]--;
		a[in[i] / n][in[i] % n] = i + 1;
	}
	/*rep(i, n) {
	rep(j, n) {
	cout << a[i][j] << " ";
	}
	cout << "\n";
	}*/

	int sz = n / 2;

	int sup = n * n + 1;
	rep(i, n)rep(j, n)rep(k, sz + 1)id[i][j][k] = sup;
	rep(i, n)rep(j, n) {
		if (i == 0 || j == 0 || i == n - 1 || j == n - 1) {
			id[i][j][0] = a[i][j];
			id[i][j][1] = 0;
		}
	}
	rep(k, sz + 1) {
		vector<queue<P>> qs(sup + 1);
		vector<vector<bool>> used(n, vector<bool>(n, false));

		rep(i, n)rep(j, n) {
			if (id[i][j][k] == sup)continue;
			qs[id[i][j][k]].push({ i,j });
		}
		rep(t, sup) {
			while (!qs[t].empty()) {
				P p = qs[t].front(); qs[t].pop();
				int x = p.first, y = p.second;
				if (used[x][y])continue;
				used[x][y] = true;
				rep(d, 4) {
					int nx = x + dx[d], ny = y + dy[d];
					if (nx < 0 || ny < 0 || nx == n || ny == n)continue;
					if (used[nx][ny])continue;
					//if (a[nx][ny] < id[x][y][k])continue;
					int td = max(a[nx][ny], id[x][y][k]);
					if (td < id[nx][ny][k]) {
						id[nx][ny][k] = td;
						qs[td].push({ nx,ny });
					}
				}
			}
		}
		if (k < sz) {
			rep(x, n)rep(y, n) {
				rep(d, 4) {
					int nx = x + dx[d], ny = y + dy[d];
					if (nx < 0 || ny < 0 || nx == n - 1 || ny == n - 1)continue;
					id[nx][ny][k + 1] = min(id[nx][ny][k + 1], id[x][y][k]);
				}
			}
		}
	}
	ll ans = 0;
	rep(i, n)rep(j, n) {
		int z = 0;
		rep(k, n + 1)if (id[i][j][k] == a[i][j]) {
			z = k; break;
		}
		//cout << "? " << a[i][j] << " " << z << "\n";
		ans += z;
	}
	cout << ans << "\n";
}


