    --e;
  }
  vector d(n, vector<int>(n));
  for (int i = 0; i < n; ++i) {
    for (int j = 0; j < n; ++j) {
      d[i][j] = min({i, n - i - 1, j, n - j - 1}) + 1;
    }
  }
  auto in = [&](int i, int j) {
    return 0 <= i and i < n and 0 <= j and j < n;
  };
  array<int, 4> di{1, 0, -1, 0};
  array<int, 4> dj{0, 1, 0, -1};
  int res = 0;
  vector used(n, vector<bool>(n));
  vector<pair<int, int>> que;
  for (auto e : p) {
    int si = e / n, sj = e % n;
    used[si][sj] = true;
    que.clear();
    int bg = 0;
    res += --d[si][sj];
    que.emplace_back(si, sj);
    while (bg < (int)size(que)) {
      auto [i, j] = que[bg++];
      for (int k = 0; k < 4; ++k) {
        int ni = i + di[k];
        int nj = j + dj[k];
        if (not in(ni, nj)) continue;
        if (chmin(d[ni][nj], d[i][j] + not used[ni][nj])) {
          que.emplace_back(ni, nj);
        }
      }
    }
  }
  cout << res << '\n';
}

