vector<int> parent(vector<int> c){

    if (uf[c[0]][c[1]][0] < 0) return c;
    else{
        return vector<int>({uf[c[0]][c[1]][0],uf[c[0]][c[1]][1]}) = parent({uf[c[0]][c[1]][0],uf[c[0]][c[1]][1]});
    }
}

int get(vector<int> l){
    vector<int> p = parent(l);
    return abs(uf[p[0]][p[1]][0])-1;
}

void merge(vector<int>& a,vector<int>& b){
    if (get(b) > get(a)) swap(a,b);

    vector<int> pa = parent(a);
    vector<int> pb = parent(b);
    if (pa[0] == pb[0] && pa[1] == pb[1]) return;
    uf[pa[0]][pa[1]][0] = pb[0];
    uf[pa[0]][pa[1]][1] = pb[1];
    uf[pb[0]][pb[1]][0] = -get(b) -1;
    uf[pb[0]][pb[1]][0] = -get(b) -1;
}


