int to_h(int idx){
    return idx/N;
}

int to_w(int idx){
    return idx%N;
}

int calc_max(int h, int w){
    int ret = INF;
    for(int i = 0; i < 4; i++){
        if(in_field(h+dx[i], w+dy[i])){
            ret = min(ret, ans[h+dx[i]][w+dy[i]]);
        }else{
            ret = 0;
        }
    }
    if(used[h][w]) ret++;
    return ret;
}

void dfs(int h, int w){
    ans[h][w] = calc_max(h, w);
    for(int i = 0; i < 4; i++){
        if(in_field(h+dx[i], w+dy[i])){
            if(calc_max(h+dx[i], w+dy[i]) < ans[h+dx[i]][w+dy[i]]) dfs(h+dx[i], w+dy[i]);
        }
    }
}

