const int N = 500;
bool visit[N][N];
int dp[N][N];
int n;

void BFS(int x, int y) {
  queue<ii> Q;
  Q.push({x, y});
  while (!Q.empty()) {
    int x = Q.front().first, y = Q.front().second;
    Q.pop();
    for (int k = 0; k < 4; ++k) {
      int nx = x + d[k][0];
      int ny = y + d[k][1];
      if (nx < 0 || nx >= n || ny < 0 || ny >= n) continue;
      if (dp[nx][ny] > dp[x][y] + !visit[x][y]) {
        dp[nx][ny] = dp[x][y] + !visit[x][y];
        Q.push({nx, ny});
      }
    }
  }
}

