using namespace std;

struct pos {
    int x, y;
};

const vector<pos> moves{{1,  0},
                        {-1, 0},
                        {0,  1},
                        {0,  -1}};
int n;

bool inRange(pos &p) { return 0 <= p.x && p.x < n && 0 <= p.y && p.y < n; }

int main() {
    cin >> n;
    vector<vector<int>> dis(n, vector<int>(n));
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            dis[i][j] = min({i, j, n - 1 - i, n - 1 - j});
        }
    }

    vector<vector<bool>> used(n, vector<bool>(n));
    int ret = 0;
    for (int i = 0; i < n * n; i++) {
        int p;
        cin >> p, p--;
        ret += dis[p / n][p % n];
        used[p / n][p % n] = true;

        queue<pos> que;
        que.push({p / n, p % n});
        while (!que.empty()) {
            pos here = que.front();
            que.pop();
            for (auto move:moves) {
                pos next = {here.x + move.x, here.y + move.y};
                if (inRange(next)) {
                    int cost = dis[here.x][here.y] + (used[here.x][here.y] ? 0 : 1);
                    if (dis[next.x][next.y] > cost) {
                        dis[next.x][next.y] = cost;
                        que.push(next);
                    }
                }
            }
        }
    }

    cout << ret << endl;
    return 0;
}

