vector< pii > dirs = {{0, 1}, {1, 0}, {-1, 0}, {0,-1}};

int main() 
{
    buff();
    int n;
    cin >> n;
    auto valid = [&] (int x, int y) {
        return (x >= 0 && x < n && y >= 0 && y < n);
    };

    vector< vi > dist(n, vi(n, n));
    vector< vi > on(n, vi(n, 1));
    vi ord(n * n); 
    vector< pii > pos(n * n);
    int x;
    int sq = n * n; 
    for(int i = 0; i < sq; ++i) {
        cin >> x;
        --x;
        ord[i] = x;
        pos[i] = {(x / n), (x % n)}; 
    }

    for(int i = 0; i < n; ++i) {
        for(int j = 0; j < n; ++j) {
            int dist_vert = min(i, n - 1 - i);
            int dist_horz = min(j, n - 1 - j);
            dist[i][j] = min(dist_vert, dist_horz);
        }
    }
    // agora inicializei as distancias de todo mundo
    // vamos comecar a remover as pessoas (;
    int ans = 0; 
    function<void(pii&)> prop = [&] (pii& cur) {
        pii nxt = cur; 
        for(const auto& d : dirs) {
            nxt.first += d.first;
            nxt.second += d.second;
            if(valid(nxt.first, nxt.second)) {
                if(dist[cur.first][cur.second] + on[cur.first][cur.second] < dist[nxt.first][nxt.second]) {
                    dist[nxt.first][nxt.second] = dist[cur.first][cur.second] + on[cur.first][cur.second];
                    prop(nxt);
                }
            }
            nxt.first -= d.first;
            nxt.second -= d.second;
        }
    };

    for(auto& pr : pos) {
        ans += dist[pr.first][pr.second];
        // agora temos que fazer os updates de forma esperta
        // vai ser meio que um dijkstra pelas posicoes
        on[pr.first][pr.second] = 0;
        prop(pr);
    }

    cout << ans << '\n';
    return 0;
}

