void make_graph(int n) {
	int origin = n * n;
	shortest[origin] = 0;
	for (int i = 0; i < n; i++) {
		for (int j = 0; j < n; j++) {
			int min_x = min(j, n - 1 - j);
			int min_y = min(i, n - 1 - i);
			int pos = i * n + j;
			shortest[pos] = min(min_x, min_y);
			fill_n(&edges[pos][0], 4, origin);
			if (i > 0) {
				edges[pos][0] = pos - n;
			}
			if (i < n - 1) {
				edges[pos][1] = pos + n;
			}
			if (j > 0) {
				edges[pos][2] = pos - 1;
			}
			if (j < n - 1) {
				edges[pos][3] = pos + 1;
			}
		}
	}
}

void update(int node, int poids) {
	if (!partis[node]) {
		poids++;
	}
	for (int i = 0; i < 4; i++) {
		int other = edges[node][i];
		if (shortest[other] > poids) {
			shortest[other] = poids;
			update(other, poids);
		}
	}
}

