signed main() {

    SS(int, N);
    SV(int, P, N * N);
    EACH(e, P) --e;

    auto f = [&](int M) -> pair<int, int> {
        return make_pair(M / N, M % N);
    };

    auto mat = make_v<int>(N, N);
    REP(i, N) REP(j, N) {
        int cst = min({i, j, N - 1 - i, N - 1 - j});
        mat[i][j] = cst;
    }

    int res = 0;
    EACH(e, P) {
        auto [u, v] = f(e);
        res += mat[u][v];
        emp[u][v] = true;
        queue<pair<pair<int, int>, int>> Q;
        Q.emplace(make_pair(u, v), mat[u][v]);
        while (not Q.empty()) {
            auto [pr, c] = Q.front();   Q.pop();
            auto [x, y] = pr;
            chmin(mat[x][y], c);
            REP(k, 4) {
                int nx = x + dx[k];
                int ny = y + dy[k];
                if (nx < 0 or nx >= N or ny < 0 or ny >= N) continue;
                int nc = c + !emp[x][y];
                if (mat[nx][ny] > nc) {
                    Q.emplace(make_pair(nx, ny), nc);
                }
            }
        }
