int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);

    cin >> N;
    FOR(i,1,N){
        FOR(j,1,N){
            g[i][j] = min(min(i,N-i+1), min(j,N-j+1));
            e[i][j] = 1;
        }
    }
    int ans = 0;
    FOR(i,1,N*N){
        int P; cin >> P;
        int x = (P-1)/N + 1, y = P - (x-1)*N;
