void
solve() {
  int n;
  cin>>n;

  vector<vector<int>> v(n+2, vector<int>(n+2, 0));
  vector<vector<int>> h(n+2, vector<int>(n+2, 1));

  int len = n+2;
  for (int i=0; i<len; i++)
    for (int j=0; j<len; j++) {
      int top = i;
      int left = j;
      int right = len-1-j;
      int bottom = len-1-i;

      v[i][j] = min(min(top, left), min(right, bottom)) - 1;
    }

  int ans = 0;
  int p;
  int diff[4][2] = {{0, 1}, {1, 0}, {0, -1}, {-1, 0}};
  for (int k=0; k<n*n; k++) {
    cin>>p;

    int i = (p-1) / n + 1;
    int j = (p-1) % n + 1;
    ans += v[i][j];

    map<pair<int, int>, bool> vis;
    queue<pair<int, int>> data;
    data.push({i, j});
    vis[{i, j}] = true;
    h[i][j] = 0;

    while (data.size() > 0) {
      auto val = data.front();
      data.pop();
      v[val.first][val.second]--;

      for (int k = 0; k<4; k++) {
        int x = val.first + diff[k][0];
