int leave(int Pi)
{
	int currX = pos[Pi].first, currY = pos[Pi].second;
	occupied[currX][currY] = false;

	distances[currX][currY] = make_pair(Pi, 0);

	deque<pair<int, int> > squares;
	squares.push_front(make_pair(currX, currY));

	if(currX == 1 || currX == N || currY == 1 || currY == N)
		return 0;

	int ans = INT_MAX;
	while(!squares.empty())
	{
		int X = squares.front().first, Y = squares.front().second;
		squares.pop_front();

		if(X == 1 || X == N)
		{
			ans = min(ans, distances[X][Y].second);
			//printf("Pi = %d, X = %d, Y = %d, distances = %d\n", Pi, X, Y, distances[X][Y]);
			continue;
		}

		else if(Y == 1 || Y == N)
		{
			ans = min(ans, distances[X][Y].second);
			//printf("Pi = %d, X = %d, Y = %d, distances = %d\n", Pi, X, Y, distances[X][Y]);
			continue;
		}

		for(int deltaX = -1; deltaX <= 1; deltaX++)
		{
			for(int deltaY = -1; deltaY <= 1; deltaY++)
			{
				if(deltaX == 0 && deltaY == 0)
					continue;

				if(deltaX != 0 && deltaY != 0)
					continue;

				int finalX = X + deltaX, finalY = Y + deltaY;
				if(occupied[finalX][finalY] && (distances[X][Y].second + 1 < distances[finalX][finalY].second || distances[finalX][finalY].first != Pi))
				{
					distances[finalX][finalY] = make_pair(Pi, distances[X][Y].second + 1);
					squares.push_back(make_pair(finalX, finalY));
				}

				else if(!occupied[finalX][finalY] && (distances[X][Y].second < distances[finalX][finalY].second || distances[finalX][finalY].first != Pi))
				{
					distances[finalX][finalY] = make_pair(Pi, distances[X][Y].second);
					squares.push_front(make_pair(finalX, finalY));
				}
			}
		}
	}

	//printf("\n");
	//printf("Pi = %d, ans = %d\n", Pi, ans);
	return ans;
}

