vector<vector<bool>> &check, int y, int x)
{
	check[y][x] = true;
	if (y > 0)
	{
		dist[y-1][x] = min(dist[y][x], dist[y-1][x]);
		if (emp[y-1][x] && !check[y-1][x])
			update(dist, emp, check, y-1, x);
	}
	if (y < n-1)
	{
		dist[y+1][x] = min(dist[y][x], dist[y+1][x]);
		if (emp[y+1][x] && !check[y+1][x])
			update(dist, emp, check, y+1, x);
	}
	if (x > 0)
	{
		dist[y][x-1] = min(dist[y][x], dist[y][x-1]);
		if (emp[y][x-1] && !check[y][x-1])
			update(dist, emp, check, y, x-1);
	}
	if (x < n-1)
	{
		dist[y][x+1] = min(dist[y][x], dist[y][x+1]);
		if (emp[y][x+1] && !check[y][x+1])
			update(dist, emp, check, y, x+1);
	}
}

