int depth[500][500];
int pass[500][500];
int n;
void sub(int x, int y) {
	//cout << x << " " << y << " " << depth[x][y] << endl;
	if (depth[x][y] < 0)return;
	if (pass[x][y] < 0) return;

	int r[4][2] = { {1,0},{-1,0},{0,1},{0,-1} };
	int p = pass[x][y];
	pass[x][y] = -1;

	for (int i = 0; i < 4; i++) {
		if (x + r[i][0] < 0 || x + r[i][0] >= n || y + r[i][1] < 0 || y + r[i][1] >= n)
			continue;
		if (pass[x + r[i][0]][y + r[i][1]] < 0)
			continue;
		if (pass[x][y] == 0 || 
			depth[x][y] < depth[x + r[i][0]][y + r[i][1]] ||
			(pass[x + r[i][0]][y + r[i][1]] == 0 && depth[x][y] <= depth[x + r[i][0]][y + r[i][1]] )
			)
			sub(x + r[i][0],y + r[i][1]);
	}

	if(depth[x][y] >= 0) depth[x][y] --;
	pass[x][y] = p;
}



