void update(int x, int y)
{
	std::deque<pii> q;
	static int mark[maxn][maxn], timer;
	timer++;
	q.emplace_back(x, y);
	a[x][y] = 0;
	dist[x][y]--;
	while(!q.empty())
	{
		int x = q.front().ff, y = q.front().ss; q.pop_front();
		if(mark[x][y] == timer) continue;
		mark[x][y] = timer;
		if(dist[x-1][y] > dist[x][y] + a[x-1][y])
		{
			dist[x-1][y] = dist[x][y] + a[x-1][y];
			if(a[x-1][y]) q.emplace_back(x-1, y);
			else q.emplace_front(x-1, y);
		}
		if(dist[x+1][y] > dist[x][y] + a[x+1][y])
		{
			dist[x+1][y] = dist[x][y] + a[x+1][y];
			if(a[x+1][y]) q.emplace_back(x+1, y);
			else q.emplace_front(x+1, y);
		}
		if(dist[x][y+1] > dist[x][y] + a[x][y+1])
		{
			dist[x][y+1] = dist[x][y] + a[x][y+1];
			if(a[x][y+1]) q.emplace_back(x, y+1);
			else q.emplace_front(x, y+1);
		}
		if(dist[x][y-1] > dist[x][y] + a[x][y-1])
		{
			dist[x][y-1] = dist[x][y] + a[x][y-1];
			if(a[x][y-1]) q.emplace_back(x, y-1);
			else q.emplace_front(x, y-1);
		}
	}
}

