	vector<vector<bool> > occupied(n, vector<bool>(n, true));
	for (int i = 0; i < n; i++) {
		for (int j = 0; j < n; j++) {
			dist[i][j] = min(min(i+1, n-i), min(j+1, n-j));
		}
	}
	vector<int> bfs;
	bfs.reserve(n * n);
	const int mx[4] = {0, 1, 0, -1};
	const int my[4] = {1, 0, -1, 0};
	for (int _ = 0; _ < n * n; _++) {
