LL n; // number of viewers.
vector<LL> inuse;
vector<LL> cost;

bool is_on_edge(LL id) {
  return (id < n) || (id % n == 0) || (id % n == n - 1) || (id >= n * (n - 1));
}

LL update(LL id) {
  inuse.at(id) = 0;

  priority_queue<P, vector<P>, greater<P>> q; // Current cost, node id
  vector<bool> completed(n * n, false);

  q.push(make_pair(cost[id], id));
  while(!q.empty()) {
    const long cc = q.top().first; // pivot node cost
    const long ii = q.top().second; // pivot node id
    q.pop();

    //if (completed.at(ii)) continue;
    completed[ii] = true;
    cost[ii] = cc;

    // check four edges
    if (ii >= n && !completed[ii - n]) {
      // has upper
      if (cost[ii - n] > cc + inuse[ii]) {
        q.push(make_pair(cc + inuse[ii], ii - n));
      }
    }
    if (ii % n != 0 && !completed[ii - 1]) {
      // has left
      if (cost[ii - 1] > cc + inuse[ii]) {
        q.push(make_pair(cc + inuse[ii], ii - 1));
      }
    }
    if (ii % n != n - 1 && !completed[ii + 1]) {
      // has right
      if (cost[ii + 1] > cc + inuse[ii]) {
        q.push(make_pair(cc + inuse[ii], ii + 1));
      }
    }
    if (ii < n * (n - 1) && !completed[ii + n]) {
      // has lower
      if (cost[ii + n] > cc + inuse[ii]) {
        q.push(make_pair(cc + inuse[ii], ii + n));
      }
    }
  }



  return 0;
}

