  }

  inuse.assign(n * n, 1);
  cost.assign(n * n, 9999999999L);
  rep (i, n) {
    rep (j, n) {
      cost.at(i * n + j) = min(min(i, n - 1 - i), min(j, n - 1 - j));
    }
  }

