const int dx[4] = {0, 0, 1, -1};
const int dy[4] = {1, -1, 0, 0};

const int N = 505;

int n, ans, dis[N][N];
bool used[N][N];

int main() {
    n = read();
    for (int i = 1; i <= n; i++) {
        for (int j = 1; j <= n; j++) {
            dis[i][j] = std::min(std::min(i - 1, n - i), std::min(j - 1, n - j));
        }
    }
    for (int i = 0; i < n * n; i++) {
        int p = read();
        int x = (p - 1) / n + 1, _x = x;
        int y = (p - 1) % n + 1, _y = y;
        used[x][y] = true;
        std::deque<std::pair<int, int>> que;
        for (que.push_back({x, y}); !que.empty(); ) {
            x = que.front().first;
            y = que.front().second;
            que.pop_front();
            if (used[x][y]) {
                for (int k = 0; k < 4; k++) {
                    int vx = x + dx[k];
                    int vy = y + dy[k];
                    if (vx < 1 || vy < 1 || vx > n || vy > n) { continue; }
                    if (dis[vx][vy] > dis[x][y]) {
                        dis[vx][vy] = dis[x][y];
                        que.push_front({vx, vy});
                    }
                }
            } else {
                for (int k = 0; k < 4; k++) {
                    int vx = x + dx[k];
                    int vy = y + dy[k];
                    if (vx < 1 || vy < 1 || vx > n || vy > n) { continue; }
                    if (dis[vx][vy] > dis[x][y] + 1) {
                        dis[vx][vy] = dis[x][y] + 1;
                        que.push_back({vx, vy});
                    }
                }
            }
        }
        ans += dis[_x][_y];
    }
    printf("%d\n", ans);
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int t;
vector<vector<int>> humans;
vector<vector<int>> seats;

void bfs(int _y, int _x) {
    queue<pair<int,int>> q;
    q.push({_y,_x});
    while(!q.empty()) {
        auto&& yx = q.front(); q.pop();
        int y = yx.first, x = yx.second;
        if(y > 0 && seats[y - 1][x] > seats[y][x] + humans[y - 1][x]) {
            seats[y - 1][x] = seats[y][x] + humans[y - 1][x];
            q.push({y - 1, x});
        }
        if(y < t - 1 && seats[y + 1][x] > seats[y][x] + humans[y + 1][x]) {
            seats[y + 1][x] = seats[y][x] + humans[y + 1][x];
            q.push({y + 1, x});
        }
        if(x > 0 && seats[y][x - 1] > seats[y][x] + humans[y][x - 1]) {
            seats[y][x - 1] = seats[y][x] + humans[y][x - 1];
            q.push({y, x - 1});
        }
        if(x < t - 1 && seats[y][x + 1] > seats[y][x] + humans[y][x + 1]) {
            seats[y][x + 1] = seats[y][x] + humans[y][x + 1];
            q.push({y, x + 1});
        }
    }
}

int main() {
    cin >> t;
    for(int y = 0; y < t; y++) {
        vector<int> row;
        for(int x = 0; x < t; x++) {
            row.push_back(min({x, t - x - 1, y, t - y - 1}));
        }
        seats.push_back(row);
        vector<int> humanRow(t, 1);
        humans.push_back(humanRow);
    }
    int result = 0;
    for(int i = 0; i < t * t; i++) {
        int number;
        cin >> number;
        number--;
        int x = number % t;
        int y = number / t;
        result += seats[y][x];
        seats[y][x]--;
        humans[y][x]--;
        bfs(y, x);
    }
    cout << fixed << result;
}

