int hate(vector<vector<int>> & arr,int r,int c,int n){
    int u=r,d=r,l=c,w=c,t1=0,t2=0,t3=0,t4=0;arr[r][c]=-1;
    while(u>=0){if(arr[u][c]>=0){t1++;}u--;}
    while(d<n){if(arr[d][c]>=0){t2++;}d++;}
    while(l>=0){if(arr[r][l]>=0){t3++;}l--;}
    while(w<n){if(arr[r][w]>=0){t4++;}w++;}
    int res=min(t1,t2);
    res=min(res,t3);
    res=min(res,t4);
    return res;
}
