int N, A[MN][MN], P[MN * MN];
inline void g(int x, int &i, int &j) {
	i = (x - 1) / N + 1;
	j = (x - 1) % N + 1;
}

std::deque<std::pair<int, int>> q;
int D[MN][MN], Ans;

int main() {
	scanf("%d", &N);
	for (int i = 1; i <= N; ++i)
		for (int j = 1; j <= N; ++j) {
			A[i][j] = 1;
			D[i][j] = std::min({i - 1, N - i, j - 1, N - j});
		}
	for (int i = 1; i <= N * N; ++i) {
		int pos, x, y;
