    if (n>400) return -1;
    vector<ll> p(n*n);

    rep(i, n*n) {
        cin >> p[i];
        p[i]--;
    }
    ll ans = 0;

    vector<BIT<ll>> bitx(n, BIT<ll>(n));
    vector<BIT<ll>> bity(n, BIT<ll>(n));
    rep(i, n) {
        rep(j, n) {
            bitx[i].add(j, 1LL);
            bity[i].add(j, 1LL);
        }
    }    

    rep(i, n*n) {
        ll x = p[i]/n;
        ll y = p[i]%n;

        ll v1 = bity[x].sum(y-1);
