        ll v2 = bity[x].sum(n-1) - bity[x].sum(y);
        if (y==n-1) v2 = 0;
        ll v3 = bitx[y].sum(x-1);
        if (x==0) v3 = 0;
        ll v4 = bitx[y].sum(n-1) - bitx[y].sum(x);
        if (x==n-1) v4 = 0;
        /*
