        debug(v4);
        */

        ll res = min(min(v1, v2), min(v3, v4));
        res = max(res, 0LL);
        ans += res;
        bitx[y].add(x, -1LL);
        bity[x].add(y, -1LL);
    }




    cout << ans << endl;


    return 0;
}

