void update(int n, int x, int y, int dp[], int map[]){
    int mincost;
    if(x!=0&&x!=n-1&&y!=0&&y!=n-1){
        mincost = min(min(dp[x*n+y+n]+map[x*n+y+n], dp[x*n+y+1]+map[x*n+y+1]), min(dp[x*n+y-n]+map[x*n+y-n], dp[x*n+y-1]+map[x*n+y-1]));
    } else {
        mincost = 0;
    }
    dp[x*n+y]=mincost;

    if(x!=0&&dp[x*n+y-n]>dp[x*n+y]+map[x*n+y]){
        dp[x*n+y-n]=dp[x*n+y];
        update(n,x-1,y,dp,map);
    }
    if(x!=n-1&&dp[x*n+y+n]>dp[x*n+y]+map[x*n+y]){
        dp[x*n+y+n]=dp[x*n+y];
        update(n,x+1,y,dp,map);
    }
    if(y!=0&&dp[x*n+y-1]>dp[x*n+y]+map[x*n+y]){
        dp[x*n+y-1]=dp[x*n+y];
        update(n,x,y-1,dp,map);
    }
    if(x!=n-1&&dp[x*n+y+1]>dp[x*n+y]+map[x*n+y]){
        dp[x*n+y+1]=dp[x*n+y];
        update(n,x,y+1,dp,map);
    }
}

