int main(){
  int N;
  cin >> N;
  vector<int> P(N*N);
  for(auto& p : P){
    cin >> p;
  }
  vector<vector<int>> C(N, vector<int>(N));
  vector<vector<int>> D(N, vector<int>(N, 1));
  int l=0, r=N;
  while(l<r){
    for(int ii=l; ii<r; ii++){
      C[l][ii] = l+1;
      C[r-1][ii] = l+1;
      C[ii][l] = l+1;
      C[ii][r-1] = l+1;
    }
    l++;
    r--;
  }

  int ans = 0;
  for(auto& p : P){
    int row = (p-1)/N;
    int col = (p-1)%N;
    ans += C[row][col]-1;
    C[row][col]--;
    D[row][col]=0;
    queue<pair<int, int>> q;
    q.push({row, col});
    vector<pair<int, int>> moves = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};
    while(q.size()){
      auto current = q.front();
      q.pop();
      for(auto m : moves){
        int next_x = current.first+m.first;
        int next_y = current.second+m.second;
        if(0<=next_x && next_x<N && 0<=next_y && next_y<N){
          int tmp = C[current.first][current.second]+D[next_x][next_y];
          for(auto m2 : moves){
            if(0<=next_x+m2.first && next_x+m2.first<N && 0<=next_y+m2.second && next_y+m2.second<N){
              tmp = min(C[next_x+m2.first][next_y+m2.second]+D[next_x][next_y], tmp);
            }
          }
          if(tmp < C[next_x][next_y]){
            C[next_x][next_y]=tmp;
            q.push({next_x, next_y});
          }
        }
      }
    }
  }
  cout << ans << endl;

  return 0;
}

