// GJNM
int BIT_ROW[maxN][maxN];
int BIT_COL[maxN][maxN];
int n;

// suma de rangos [0,n-1]
void updBIT_ROW(int ind, int p, int val = 1){ 
    p++;	// esto es porque el bit esta indexado desde 1
    for(; p < maxN; p += p&-p) // se puede cambiar maxN por n+1 si hace falta mas velocidad
    	BIT_ROW[ind][p] += val;
}
int sumBIT_ROW(int ind, int p){
    p++;
    int ret = 0;
    for(; p; p -= p&-p) 
    	ret += BIT_ROW[ind][p];
    return ret;
}

void updBIT_COL(int ind, int p, int val = 1){ 
    p++;	// esto es porque el bit esta indexado desde 1
    for(; p < maxN; p += p&-p) // se puede cambiar maxN por n+1 si hace falta mas velocidad
    	BIT_COL[ind][p] += val;
}
int sumBIT_COL(int ind, int p){
    p++;
    int ret = 0;
    for(; p; p -= p&-p) 
    	ret += BIT_COL[ind][p];
    return ret;
}

int get_row(int x){
	return x/n;
}

int get_col(int x){
	return x%n;
}

int A[maxN*maxN];
ll dp[maxN*maxN][4];

ll f(int ind, int choice){ 
	if ( ind == n*n )
		return 0;
	if ( dp[ind][choice] != -1 )
		return dp[ind][choice];

	ll &ret = dp[ind][choice];
	ret = LLINF;

	// go left
	int row = get_row(A[ind]), col = get_col(A[ind]);

	if ( choice == 0 ){ // go up
		updBIT_ROW(row,col,-1);
		updBIT_COL(col,row,-1);

		ll aux = sumBIT_COL(col,row);
		FOR(i,0,4)
			ret = min(ret, aux + f(ind+1, i) );

		updBIT_ROW(row,col);
		updBIT_COL(col,row);
	}
	else if ( choice == 1 ){ // go down
		updBIT_ROW(row,col,-1);
		updBIT_COL(col,row,-1);

		ll aux = sumBIT_COL(col,n) - sumBIT_COL(col,row);
		FOR(i,0,4)
			ret = min(ret, aux + f(ind+1, i) );

		updBIT_ROW(row,col);
		updBIT_COL(col,row);
	}
	else if ( choice == 2 ){ // go left
		updBIT_ROW(row,col,-1);
		updBIT_COL(col,row,-1);

		ll aux = sumBIT_ROW(row,col);
		FOR(i,0,4)
			ret = min(ret, aux + f(ind+1, i) );

		updBIT_ROW(row,col);
		updBIT_COL(col,row);
	}
	else{ // go right
		updBIT_ROW(row,col,-1);
		updBIT_COL(col,row,-1);

		ll aux = sumBIT_ROW(row,n) - sumBIT_ROW(row,col);
		FOR(i,0,4)
			ret = min(ret, aux + f(ind+1, i) );

		updBIT_ROW(row,col);
		updBIT_COL(col,row);
	}
	return ret;
}

int main(){
	ri(n);
	FOR(i,0,n){
		FOR(j,0,n){
			updBIT_COL(j,i);
			updBIT_ROW(i,j);
		}
	}

	FOR(i,0,n*n){
		ri(A[i]);
		A[i]--;
	}

	FOR(i,0,maxN){
		dp[i][0] = dp[i][1] = dp[i][2] = dp[i][3] = -1;
	}

	printf("%lld\n", min( min( f(0,0), f(0,1) ), min( f(0,2), f(0,3) ) ) );
	return 0;
}

