void del(pos now, ll c);

void update(pos now, ll c){
    grid[now] = c;
    rep(i,0,4){
        if(now.x + dx[i] <= N-1 && now.x + dx[i] >= 0 && now.y + dy[i] >= 0 && now.y + dy[i] <= N-1){
            pos nxt = mpos(now.x + dx[i], now.y + dy[i]);
            if(grid[nxt] > grid[now]+1){
                if(gridbool[nxt])update(nxt, grid[now] + 1);
                else del(nxt, grid[now] + 1);
            }
        }
    }
}

void del(pos now, ll c){
    grid[now] = c;
    rep(i,0,4){
        if(now.x + dx[i] <= N-1 && now.x + dx[i] >= 0 && now.y + dy[i] >= 0 && now.y + dy[i] <= N-1){
            pos nxt = mpos(now.x + dx[i], now.y + dy[i]);
            if(grid[nxt] > grid[now]){
                if(gridbool[nxt])update(nxt, grid[now]);
                else del(nxt, grid[now]);
            }
        }
    }
}


