    vector<vector<int> > cost(n+2, vector<int>(n+2, 0));
    for(int y=1; y<=n; ++y){
        for(int x=1; x<=n; ++x){
            isEmpty[y][x] = false;
            cost[y][x] = min({y, x, n+1-y, n+1-x});
        }
