namespace asl
{

    template <typename T>
    std::istream &operator>>(std::istream &is, std::vector<T> &vec)
    {
        for (auto &value : vec)
            is >> value;
        return is;
    }

    int dx[4] = {-1, 0, +1, 0};
    int dy[4] = {0, +1, 0, -1};

    class TBoard
    {
    public:
        int n, m;

        TBoard(int n = 0, int m = 0) : n(n), m(m) {}

        bool inside(int x, int y)
        {
            return 0 <= x && x < n && 0 <= y && y < m;
        }

    };

    template <typename T>
    std::vector<std::vector<T>> board(int n, int m, T def)
    {
        return std::vector<std::vector<T>>(n, std::vector<T>(m, def));
    }

    template <typename T>
    std::vector<std::vector<T>> board(int n = 0, int m = 0)
    {
        return std::vector<std::vector<T>>(n, std::vector<T>(m));
    }

    enum BFSResult
    {
        SKIP = 0,
        ADD = 1,
        FIN = 2,
    };

    void bfs4(int sx, int sy, std::function<BFSResult(int, int, int, int)> fn)
    {
        std::queue<std::pair<int, int>> q;

        if (fn(sx, sy, -1, -1) == BFSResult::ADD)
        {
            q.push({sx, sy});
        }

        bool fin = false;

        while (!fin && !q.empty())
        {
            int x, y;
            std::tie(x, y) = q.front();
            q.pop();

            for (int k = 0; k < 4; ++k)
            {
                int nx = x + dx[k], ny = y + dy[k];

                auto res = fn(nx, ny, x, y);

                if (res == BFSResult::ADD)
                {
                    q.push({nx, ny});
                }
                else if (res == BFSResult::FIN)
                {
                    fin = true;
                    break;
                }
            }
        }
    }

    void bfs4(int sx, int sy, std::function<bool(int, int, int, int)> fn)
    {
        std::function<BFSResult(int, int, int, int)> inner_fn = [&](int x, int y, int fx, int fy) {
            auto res = fn(x, y, fx, fy);
            return res ? BFSResult::ADD : BFSResult::SKIP;
        };

        bfs4(sx, sy, inner_fn);
    }
} 

