                return false;

            int dist = 0;

            if (fx == -1)
            {
                dist = b[x][y] - 1;
            }
            else
            {
                dist = b[fx][fy] + u[x][y];
            }

            if (b[x][y] > dist)
            {
                b[x][y] = dist;
                return true;
            }
            else
