		board[p]--;
		exist[p] = 0;
		ans += board[p];
		q.push(p);

		while (!q.empty()) {
			k = q.front();
			q.pop();
			visit[k] = i;

			if (k >= n) {
				if (exist[k - n] == 0 && visit[k - n] != i){
					board[k - n] = board[k];
					q.push(k - n);
				} else if (board[k - n] > board[k] + 1) {
					board[k - n] = board[k] + 1;
					q.push(k - n);
				}
			}
			if (k < n * n - n) {
				if (exist[k + n] == 0 && visit[k + n] != i) {
					board[k + n] = board[k];
					q.push(k + n);
				} else if (board[k + n] > board[k] + 1) {
					board[k + n] = board[k] + 1;
					q.push(k + n);
				}
			}
			if (k % n != 0) {
				if (exist[k - 1] == 0 && visit[k - 1] != i) {
					board[k - 1] = board[k];
					q.push(k - 1);
				} else if (board[k - 1] > board[k] + 1) {
					board[k - 1] = board[k] + 1;
					q.push(k - 1);
				}
			}
			if ((k + 1) % n != 0) {
				if (exist[k + 1] == 0 && visit[k + 1] != i) {
					board[k + 1] = board[k];
					q.push(k + 1);
				} else if (board[k + 1] > board[k] + 1) {
					board[k + 1] = board[k] + 1;
					q.push(k + 1);
				}
			}
		}
	}

	printf("%d\n", ans);

