void work()
{
    int n;
    cin >>n;
    int nn = n * n;

    VVI vis(n, VI(n, 0));
    VVI dis(n, VI(n));
    VVI r(n, VI(n, 1));

    for(int i = 0; i < n; i++)
        for(int j = 0; j < n; j++)
            dis[i][j] = min({i, n - 1 - i, j, n - 1 - j});

    VI dx({0, 0, 1, -1});
    VI dy({1, -1, 0, 0});

    int ans = 0;
    for(int i = 0; i < nn; i++)
    {
        int p;
        cin >>p;
        p--;
        int x = p / n, y = p % n;
        ans += dis[x][y];
        r[x][y] = 0;
        VVI inq(n, VI(n, 0));
        queue< pair<int, int> > Q;

        Q.push(mk(x, y));
        inq[x][y] = 1;

        while(Q.size())
        {
            int px = Q.front().fi;
            int py = Q.front().se;
            Q.pop();
            inq[px][py] = 0;

            for(int i = 0; i < 4; i++)
            {
                int nx = px + dx[i];
                int ny = py + dy[i];

                if(0 <= nx && nx < n && 0 <= ny && ny < n)
                {
                    if(dis[px][py] + r[px][py] < dis[nx][ny])
                    {
                        dis[nx][ny] = dis[px][py] + r[px][py];
                        if(!inq[nx][ny])
                        {
                            inq[nx][ny] = 1;
                            Q.push(mk(nx, ny));
                        }
                    }
                }
            }
        }
    }
    cout <<ans <<endl;
}

