ll mod(ll a, ll mod){
  ll res = a%mod;
  if(res<0)res=res + mod;
  return res;
}

ll modpow(ll a, ll n, ll mod){
  ll res=1;
  while(n>0){
    if(n&1) res=res*a%mod;
    a=a*a%mod;
    n>>=1;
  }
  return res;
}

ll modinv(ll a, ll mod){
  return modpow(a, mod-2, mod);
}

ll gcd(ll a, ll b){
  ll r = a%b;
  if(r==0) return b;
  else return gcd(b, a%b);
}

bool is_prime(ll n){
  ll i = 2;
  if(n==1)return false;
  if(n==2)return true;
  bool res = true;
  while(i*i <n){
    if(n%i==0){
      res = false;
    }
    i = i+1;
  }

  //if(i==1)res = false;
  if(n%i==0)res=false;
  return res;
}

struct UnionFind{
  ll N;
  llvec p;
  llvec cnt;
  UnionFind(ll n){
    N = n;
    p=llvec(N);
    cnt=llvec(N, 0);
    rep(i, N){
      p[i] = i;
      cnt[i] = 1;
    }
  }

  void con(ll a, ll b){
    P at = root(a);
    P bt = root(b);
    if(at.second!=bt.second){
      if(at.first>bt.first){
        swap(at, bt);
        swap(a, b);
      }
      p[at.second] = bt.second;
      cnt[bt.second]+=cnt[at.second];
      p[a]=bt.second;
    }
  }

  P root(ll a){
    ll atmp = a;
    ll c=0;
    while(atmp!=p[atmp]){
      atmp = p[atmp];
      c++;
    }
    p[a] = atmp;
    return {c, atmp};
  }

  bool is_con(ll a, ll b){
    P at=root(a);
    P bt=root(b);
    return at.second == bt.second;
  }

};

struct dijkstra{
  ll N;
  ll N2;
  llvec d;
  vector<vector<edge>> e;
  llvec S;
  llvec exits;
  dijkstra(ll n){
    N = n;
    N2 = sqrt(n);
    //d = llvec(N, 1e18);
    e = vector<vector<edge>>(N);
    S = llvec(n);
    exits = llvec(n, 0);
    rep(i, n){
      S[i]=1;
      if(i/N2==0 or i/N2==N2-1 or i%N2==0 or i%N2==N2-1){
        exits[i]=1;
      }
    }
  }

  void add_edge(ll from, ll to, ll cost){
    e[from].push_back({to, cost});
  }
  void add_edge_both(ll from, ll to, ll cost){
    e[from].push_back({to, cost});
    e[to].push_back({from, cost});
  }

  ll chk(){
    ll tmp = 1e18;
    ll n = N2;
    rep(i, n){
      tmp = min(tmp, d[i]);
      tmp = min(tmp, d[N-1-i]);
      tmp = min(tmp, d[n*i]);
      tmp = min(tmp, d[n*i+(n-1)]);
    }
    return tmp;
  }

  ll run(ll start){
    priority_queue<P, vector<P>, greater<P>> que;
    que.push({0, start});
    d = llvec(N, 1e18);
    d[start]=0;
    ll minv = 1e10;
    while(!que.empty()){
      P q = que.top();que.pop();
      ll dc = q.first;
      ll x = q.second;
      if(dc>d[x]){
        continue;
      }else{
        if(exits[x]>0)return dc;
        for(auto ip: e[x]){
          ll c = S[ip.x];
          if(d[ip.x]<=d[x]+c or d[x]+c>(N2+1)/2){
            continue;
          }else{
            d[ip.x]= d[x]+c;
            que.push({d[ip.x], ip.x});
          }
        }
      }
    }
  }  
};


