int N;

void childs(int num, vi &child){
    int row = num / N;
    int col = num % N;
    if(row > 0){
        child.pb((row - 1)* N + col);
    }
    if(row < N - 1){
        child.pb((row + 1) * N + col);
    }
    if(col > 0){
        child.pb(row * N + col - 1);
    }
    if(col < N - 1){
        child.pb(row * N + col + 1);
    }
}

signed main(){
