    int n2 = N * N;
    vi perm(n2);
    rep(i, n2){
        cin >> perm[i];
        perm[i]--;
    }

    vi paths(n2);
    rep(i, n2){
        int row = i / N;
        int col = i % N;
        paths[i] = min({row, N - 1 - row, col, N - 1 - col});
    }

    int ans = 0;
    vi vals(n2, 1);

    queue<int> q;
    for(auto p : perm){
        ans += paths[p];
        vals[p] = 0;
        vector<bool> visited(n2);
        q.push(p);
        visited[p] = true;
        while(!q.empty()){
            int x = q.front();
            q.pop();
            vi child;
            childs(x, child);
            for(auto c : child){
                if(!visited[c]){
                    if(paths[c] > vals[x] + paths[x]){
                        paths[c] = vals[x] + paths[x];
                        visited[c] = true;
                        q.push(c);
                    }
                }
            }
        }
    }

    cout << ans << endl;

    return 0;
}

