	rep(i, n * n) {
		cin >> p[i];
	}

	ll tb[510][510],u[510][510];
	rep(i,n)
		rep(j, n) {
		tb[i][j] = min({i,j,n - i - 1,n - j - 1});
		u[i][j] = 1;
	}
	ll res = 0;
	rep(i, n* n) {
		ll v = p[i] - 1;
		ll x = v / n;
		ll y = v % n;
		res += tb[x][y];
		u[x][y] = 0;
		queue<pll> q;
		q.push(make_pair(x, y));

		while (!q.empty())
		{
			auto p = q.front();
			ll cx = p.first;
			ll cy = p.second;
			q.pop();
			rep (j, 4) {
				ll tx = cx + dx[j];
