				if (tx < 0 || ty < 0 || tx >= n || ty >= n)
					continue;
				if (tb[tx][ty] > tb[cx][cy] + u[cx][cy]) {
					tb[tx][ty] = tb[cx][cy] + u[cx][cy];
					q.push(make_pair(tx, ty));
				}
			}
		}

	}
	cout << res << endl;
}
