int N;
int R[500500], C[500500];
int S[512][512], I[512][512];

const int DR[] = {0, 1, 0, -1}, DC[] = {1, 0, -1, 0};

void update(int r0, int c0) {
  int g0 = S[r0][c0];
  deque<int> qr, qc, qd;
  qr.push_back(r0);
  qc.push_back(c0);
  qd.push_back(0);
  while (!qr.empty()) {
    const int r = qr[0]; qr.pop_front();
    const int c = qc[0]; qc.pop_front();
    const int d = qd[0]; qd.pop_front();
    for (int dd = 0; dd < 4; ++dd) {
      const int rr = r + DR[dd], cc = c + DC[dd];
      if (rr < 0 || cc < 0 || rr >= N || cc >= N || (rr == r0 && cc == c0)) {
        continue;
      }
      const int nd = I[rr][cc] > I[r0][c0] ? d + 1 : d;
      if (S[rr][cc] > 0 && S[rr][cc] == nd + g0) {
        // cout<<rr<<' '<<cc<<' '<<nd<<' '<<g0<<' '<<I[rr][cc]<<' '<<I[r0][c0]<<endl;
        --S[rr][cc];
        if (I[rr][cc] > I[r0][c0]) {
          qr.push_back(rr);
          qc.push_back(cc);
          qd.push_back(d + 1);
        } else {
          qr.push_front(rr);
          qc.push_front(cc);
          qd.push_front(d);
        }
      } 
    }
  }
}

