struct S {
	int x;
	int y;
	int v;
};

auto cmp = [](const S& lhs, const S& rhs)
{
	return lhs.v > rhs.v;
};

void update(int x, int y, int v, int n, int m)
{
	priority_queue<S, vector<S>, decltype(cmp)> search(cmp);

	search.push({ x, y, v });
	while (!search.empty()) {
		S s = search.top();
		search.pop();

		if (dat2[s.x][s.y] == m) return;
		dat2[s.x][s.y] = m;

		int cv = s.v;

		if (s.x == x && s.y == y) {
		}
		else {
			if (dat[s.x][s.y] <= cv) continue;
			dat[s.x][s.y] = cv;
		}
		if (!block[s.x][s.y]) cv++;

		if (x != 0) {
			search.push({ s.x - 1, s.y, cv });
		}
		if (x != n - 1) {
			search.push({ s.x + 1, s.y, cv });
		}
		if (y != 0) {
			search.push({ s.x, s.y - 1, cv });
		}
		if (y != n - 1) {
			search.push({ s.x, s.y + 1, cv });
		}
	}
}

