{
	ios_base::sync_with_stdio(false);
	cin.tie(NULL);
	cout << fixed << setprecision(20);

	int n; cin >> n;

	FOR_LT(i, 0, n) {
		FOR_LT(j, 0, n) {
			int a = i;
			int b = n - i - 1;
			int c = j;
			int d = n - j - 1;
			dat[i][j] = min(min(a, b), min(c, d));
		}
	}

	int64_t ans = 0;
	REP(n*n) {
		int m;  cin >> m; m--;
		int x = m % n;
		int y = m / n;
		int v = dat[x][y];
		block[x][y] = true;
		update(x, y, v, n, m + 1);
		ans += v;
	}

	cout << ans << endl;

	return 0;
}

