    cin >> n;
    vector<int> order(n * n);
    for (int i = 0; i < (n * n); ++i) {
        cin >> order[i];
        --order[i];
    }
    vector<vector<int>> dist(n, vector<int>(n, 1));
    vector<vector<int>> occ(n, vector<int>(n, 1));
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            dist[i][j] = 1 + min(i, min(j, min(n - i - 1, n - j - 1)));
        }
    }
    long long sum = 0;

    const int dx[4] = {-1, 1, 0, 0};
    const int dy[4] = {0, 0, -1, 1};
    for (int p: order) {
        int x = p / n;
        int y = p % n;
        assert(dist[x][y] >= 1);
        sum += (dist[x][y] - 1);
        --dist[x][y];
        --occ[x][y];
        queue<pair<int, int>> q;
        q.emplace(x, y);
        while (!q.empty()) {
            tie(x, y) = q.front(); q.pop();
            for (int i = 0; i < 4; ++i) {
                const int nx = x + dx[i];
                const int ny = y + dy[i];
                if (nx < 0 || nx >= n || ny < 0 || ny >= n)
                    continue;
                if (dist[nx][ny] > dist[x][y] + occ[nx][ny]) {
                    dist[nx][ny] = dist[x][y] + occ[nx][ny];
                    q.emplace(nx, ny);
                }
            }
        }
    }
    cout << sum << "\n";

    return 0;
}

