struct unionfind{
	private:
	public:

vector<int> par,ranks,kosuu;

	void shoki(int N){
		par.resize(N+1,0);
		ranks.resize(N+1,0);
		kosuu.resize(N+1,1);
		for(int i=0;i<=N;i++){
			par[i]=i;
			hoge[i].pb(mp(i/(n+2),i%(n+2)));
		}

	}

	int root(int x){
		return par[x]==x ? x : par[x]=root(par[x]);
	}

	bool same(int x,int y){
		return root(x)==root(y);
	}
	bool is_root(int x){
		return x==root(x);
	}
	void unite(int x,int y){
 		x=root(x);
	 	y=root(y);
		int xx=kosuu[x],yy=kosuu[y];
	 	if(x==y) return;
		if(ranks[x]<ranks[y]){
			par[x]=y;
			kosuu[y]=yy+xx;

			while(hoge[x].size()){
				hoge[y].pb(hoge[x].back());
				hoge[x].pop_back();
			}
		}
	 	else {
			par[y]=x;
			if(ranks[x]==ranks[y]) ranks[x]=ranks[x]+1;
	 		kosuu[x]=yy+xx;


			while(hoge[y].size()){
				hoge[x].pb(hoge[y].back());
				hoge[y].pop_back();
			}
	 	}
		return;
	}
};


