using namespace std;

int pos(int n, int x){
  int l,u;
  l = x % n;
  u = (x+n-1) / n;
  if(l > n - l)
    l = n - l;
  if(u > n - u)
    u = n - u;
  if(l > u)
    return u;
  else
    return l;
}

int search(vector<int> s, int n, int x){
  int y = x, start, strain = 0, minpos, j;
  while((y % n != 0) && (y % n != 1) && y >= n && y < n*(n-1)){
    if(s[y+1] != 1)
      break;
    y++;
  }
  start = y;
  minpos = pos(n, start);
  //cout << y << endl;
  while((y % n != 0) && (y % n != 1) && y >= n && y < n*(n-1)){
    switch(strain){
      case 0://右壁
        if(s[y+1] != 0){
          y += 1;
          strain = 3;
        } else if(s[y-n] != 0)
          y -= n;
        else
          strain = 1;
        break;

      case 1://上壁
        if(s[y-n] != 0){
          y -= n;
          strain = 0;
        } else if(s[y-1] != 0)
          y -= 1;
        else
          strain = 2;
        break;

	  case 2://左壁
        if(s[y-1] != 0){
          y -= 1;
          strain = 1;
        } else if(s[y+n] != 0)
          y += n;
        else
          strain = 3;
        break;

      case 3://下壁
        if(s[y+n] != 0){
          y += n;
          strain = 2;
        } else if(s[y+1] != 0)
          y += 1;
        else
          strain = 0;
        break;
    }
    //cout << "y:" << y << "str:" << strain << endl;
    if((j = pos(n, y)) < minpos)
      minpos = j;
    if(y == start && strain == 0){
      return minpos; 
    }
  }
  return 0;
}

int main(){
  int n, x, count = 0;
