    P[i]--;
  }

  vector<vector<int>> dist(N, vector<int>(N, -1));
  vector<vector<int>> state(N, vector<int>(N, -1));

  for (int i = 0; i < N; i++) {
    for (int j = 0; j < N; j++) {
      dist[i][j] = min({i + 1, j + 1, N - i, N - j});
      state[i][j] = 1;
    }
  }

  vector<int> dx = {1, 0, -1, 0};
  vector<int> dy = {0, 1, 0, -1};

  auto Inside = [&](int x, int y) {
    return 0 <= x && x < N && 0 <= y && y < N;
  };

  int ans = 0;
  for (int i = 0; i < N * N; i++) {
    int x = P[i] / N, y = P[i] % N;
    ans += --dist[x][y];
    state[x][y] = 0;

    deque<pair<pair<int, int>, int>> dq;
    dq.push_back({{x, y}, dist[x][y]});
    while (!dq.empty()) {
      int r = dq.front().first.first;
      int c = dq.front().first.second;
      int dt = dq.front().second;
      dq.pop_front();
      if (dist[r][c] != dt) continue;
      for (int d = 0; d < 4; d++) {
        int nr = r + dx[d];
        int nc = c + dy[d];
        if (!Inside(nr, nc)) continue;
        int w = state[nr][nc];
        if (dist[nr][nc] > dist[r][c] + w) {
          dist[nr][nc] = dist[r][c] + w;
          if (w) {
            dq.push_back({{nr, nc}, dist[nr][nc]});
          } else {
            dq.push_front({{nr, nc}, dist[nr][nc]});
          }
        }
      }
    }
  }

  cout << ans << "\n";
  return 0;
}

