namespace sssp
{
  template <typename weight_val>
  struct Edge
  {
    int        from;
    int        to;
    weight_val weight;

    Edge (int from, int to, const weight_val & weight)
         : from(from), to(to), weight(weight)
    {
    }
  };

  template <typename weight_val>
  struct SSSP
  {
    vector<vector<int>>      graph;
    vector<Edge<weight_val>> edges;
    weight_val               INFINITY_VAL;

    SSSP (int N, const weight_val & INFINITY_VAL)
         : INFINITY_VAL(INFINITY_VAL)
    {
      graph.resize(N);
    }

    int add_edge (int from, int to, const weight_val & weight)
    {
      edges.PB(Edge<weight_val>(from, to, weight));
      int eid = edges.size() - 1;
      graph[from].PB(eid);
      return eid;
    }

    void dijkstra (int source, int * dist, int * prev = 0)
    {
      int n = graph.size();
      int m = edges.size();
      priority_queue<pair<weight_val, int>> pq;
      vector<bool> used; 

      FOR(i, 0, n) 
      {
        dist[i] = INFINITY_VAL;
        if (prev) prev[i] = -1;
      }
      used.resize(n, false);
      dist[source] = 0;
      pq.push(MP(0, source));

      while (!pq.empty())
      {
        auto pqpair = pq.top();pq.pop();
        int x = pqpair.second;
        if (used[x]) continue;
        used[x] = true;
        FOR(i, 0, graph[x].size())
        {
          int y = x ^ edges[graph[x][i]].from ^ edges[graph[x][i]].to;
          weight_val edge_dist = edges[graph[x][i]].weight;
          if (dist[x] + edge_dist < dist[y])
          {
            dist[y] = dist[x] + edge_dist;
            pq.push(MP(-dist[y], y));
            if (prev) prev[y] = x;
          }
        }
      }
    }

    bool bellman_ford (int source, int * dist, int * prev = 0)
    {
      int n = graph.size();
      int m = edges.size();

      FOR(i, 0, n) 
      {
        dist[i] = INFINITY_VAL;
        if (prev) prev[i] = -1;
      }
      dist[source] = 0;

      FOR(phase, 0, n - 1)
      {
        FOR(i, 0, m)
        {
          if (dist[edges[i].from] + edges[i].weight < dist[edges[i].to])
          {
            dist[edges[i].to] = dist[edges[i].from] + edges[i].weight;
            if (prev) prev[edges[i].to] = edges[i].from;
          }
        }
      }

      bool is_wo_cycle = true;
      FOR(i, 0, m) if (dist[edges[i].from] + edges[i].weight < dist[edges[i].to]) 
      {
        is_wo_cycle = false;
        break;
      }

      return is_wo_cycle;
    }

  };
}

