void solve ()
{
  R(n);
  FOR(k, 0, n * n) R(p[k]);
  n2 = n + 2;
  SSSP<int> g(2 * n2 * n2, INF);
  FOR(i, 0, n2) FOR(j, 0, n2)
  {
    int inv = getv(i, j);
    int outv = getoutv(i, j);
    edg[i][j] = g.add_edge(inv, outv, 1);
    if (i > 0 && i <= n && j > 0 && j <= n)
    {
      FOR(di, -1, 2) FOR(dj, -1, 2) if (di * di + dj * dj == 1)
      {
        int targetv = getv(i + di, j + dj);
        g.add_edge(outv, targetv, 0);
      }
    }
  }
  int ci, cj;
  ci = cj = 1;
  FOR(i, 1, n * n + 1)
  {
    rmap[i] = MP(ci, cj);
    ++cj;
    if (cj > n)
    {
      cj = 1;
      ++ci;
    }
  }
  int res = 0;
  FOR(k, 0, n * n)
