const int INF = 1001001001;
const int dx[] = {1, 0, -1, 0};
const int dy[] = {0, 1, 0, -1};

void solve() {
  int n;
  cin >> n;
  vi32 p(n * n);
  cin >> p;
  rep(i, n * n) p[i]--;
  vector<vi32> b(n, vi32(n));
  rep(i, n * n) {
    int x = p[i] % n;
    int y = p[i] / n;
    b[x][y] = i;
  }
  int ans = 0;
  vector<vi32> f(n, vi32(n));
  rep(i, n * n) {
    int x = p[i] % n;
    int y = p[i] / n;
    using T = tuple<int, int, int>;
    deque<T> q;
    q.emplace_front(x, y, 0);
    vector<pair<int, int>> history;
    int co = -1;
    while (sz(q)) {
      int x, y, cost;
      tie(x, y, cost) = q.front();
      q.pop_front();
      if (f[x][y]) continue;
      f[x][y] = 1;
      history.emplace_back(x, y);
      if (x == 0 || x == n - 1 || y == 0 || y == n - 1) {
        co = cost;
        break;
      }
      rep(k, 4) {
        int nx = x + dx[k];
        int ny = y + dy[k];
        if (nx < 0 || nx >= n || ny < 0 || ny >= n) continue;
        if (b[nx][ny] < i) {
          q.emplace_front(nx, ny, cost);
        } else {
          q.emplace_back(nx, ny, cost + 1);
        }
      }
    }
    ans += co;
    for (auto h : history) {
      int x, y;
      tie(x, y) = h;
      f[x][y] = 0;
    }
  }
  cout << ans << endl;
}

