int bfs(int x, int y,vvi &A,vvi flag) {
	queue<pii> que;
	que.push(pii(x, y));
	vvi history(N,vi (N));
	AFOR(i, N) {
		AFOR(j, N) {
			history.at(i).at(j) = 0;
		}
	}
	while (que.size()) {
		pii p = que.front(); que.pop();
		history.at(p.first).at(p.second) = 1;
		AFOR(i, 4) {
			int nx = p.first + dx[i]; int ny = p.second + dy[i];
			if (history.at(nx).at(ny) == 1) continue;
			if (0 <= nx && nx < N && 0 <= ny && ny < N) {
