using namespace std;

int minHates(const vector<vector<int> >& seats, int startr, int startc) {
    int N = seats.size();
    queue<int> que;
    vector<vector<int> > arrived(N, vector<int>(N, 0));

    queue<int> nextSearch;
    nextSearch.push(startr * N + startc);
    for (int nbHates = 0; nbHates < N; ++nbHates) {
        queue<int> que = nextSearch;
        while (!que.empty()) {
            int index = que.front();
            que.pop();

            int r = index / N;
            int c = index % N;
            if (r == 0 || r == N - 1 || c == 0 || c == N - 1) {
                return nbHates;
            }

            if (arrived[r + 1][c] == 0) {
                arrived[r + 1][c] = 1;
                if (seats[r + 1][c] == 0) {
                    que.push((r + 1) * N + c);
                }
                else {
                    nextSearch.push((r + 1) * N + c);
                }
            }
            if (arrived[r - 1][c] == 0) {
                arrived[r - 1][c] = 1;
                if (seats[r - 1][c] == 0) {
                    que.push((r - 1) * N + c);
                }
                else {
                    nextSearch.push((r - 1) * N + c);
                }
            }
            if (arrived[r][c + 1] == 0) {
                arrived[r][c + 1] = 1;
                if (seats[r][c + 1] == 0) {
                    que.push(r * N + c + 1);
                }
                else {
                    nextSearch.push(r * N + c + 1);
                }
            }
            if (arrived[r][c - 1] == 0) {
                arrived[r][c - 1] = 1;
                if (seats[r][c - 1] == 0) {
                    que.push(r * N + c - 1);
                }
                else {
                    nextSearch.push(r * N + c - 1);
                }
            }
        }
    }
}

void Main() {
    int N;
    cin >> N;
    int N2 = N * N;
    vector<int> P(N2, 0);
    for (int i = 0; i < N2; ++i) {
        cin >> P[i];
        P[i] -= 1;
    }

    int ans = 0;
    vector<vector<int> > seats(N, vector<int>(N, 1));
    for (int i = 0; i < N2; ++i) {
        int p = P[i];
        int r = p / N;
        int c = p % N;
        seats[r][c] = 0;
        ans += minHates(seats, r, c);
    }
    cout << ans << endl;
}

