void spread(int now,int cg){
	int eg=cg;
	for(int i=0;i<=nn*nn;i++) wait[i].clear();
	for(int i=1+cg;i<=n-cg;i++) for(int j=1+cg;j<=n-cg;j++) vis[i][j]=0,wait[dp[now][i][j]].push_back(mp(i,j));

