//エラトステネスの篩で、prime で ないところに false を入れる。
//true で初期化された vector を代入する必要がある。
void prime_judge(vector<bool>& prime_or_not) {

	prime_or_not.at(0) = false;
	prime_or_not.at(1) = false;

	ll n = prime_or_not.size() - 1;
	ll region = (ll)sqrt(n) + 1;

	for (ll i = 2; i <= n / 2; i++) {
		prime_or_not.at(2 * i) = false;
	}


	for (ll i2 = 1; i2 < n / 2; i2++) {
		ll i = 2 * i2 + 1;  //ここからは奇数のみ探索
		if (i < region && prime_or_not.at(i)) {
			ll j = i * i;
			while (j < n + 1) {
				prime_or_not.at(j) = false;
				j += 2 * i;
			}
		}
	}
};




map<ll, ll> divide_to_prime(int target) {
	map<ll, ll> res;

	//sqrt(target) まで調べる。
	ll upper_lim = ceil(sqrt(target));
	vector<bool> prime_or_not(upper_lim + 1, true);

	if (upper_lim < 20) prime_or_not.assign(25, true);
	prime_judge(prime_or_not);

	ll tempo = target;
	rep(i, (upper_lim + 1)) {
		if (prime_or_not.at(i)) {
			while (tempo % i == 0) {
				tempo /= i;
				res[i]++;
			}
		}
	}

	if (tempo != 1) res[tempo]++; //sqrt(target) より大きな素因数は高々1つしかない。



	return res;
}




int BFS_labyrinth(deque<pair<int, int>>& que, vector<vector<int>>& dist, const vector<vector<int>> Remain) {
	int n = dist.size();
	int m = dist.at(0).size();

	while (!que.empty()) {
		int temp_i, temp_j;
		pair<int, int> tempo = que.front(); que.pop_front();

		temp_i = tempo.first;
		temp_j = tempo.second;
		//cout << temp_i << " " << temp_j << endl;
		if (temp_i == 0 || temp_i == n - 1 || temp_j == 0 || temp_j == n - 1) {
			//if (dist.at(temp_i).at(temp_j) == 0) return 0;
			return dist.at(temp_i).at(temp_j);
		}

		for (int i = -1; i <= 1; i++) {
			for (int j = -1; j <= 1; j++) {
				if (temp_i + i < 0 || n <= temp_i + i) continue;  //範囲外
				if (temp_j + j < 0 || m <= temp_j + j) continue;  //範囲外
				if (i == 0 && j == 0) continue; //動いていない
				if (i * j != 0) continue; //右上など。八近傍の場合は消す。
				if (dist.at(temp_i + i).at(temp_j + j) != -1) continue; //行けない領域に、既に INF などが代入されている場合はこの条件だけで ok

				dist.at(temp_i + i).at(temp_j + j) = dist.at(temp_i).at(temp_j) + Remain.at(temp_i + i).at(temp_j + j);
				if (Remain.at(temp_i + i).at(temp_j + j) == 0) {
					que.push_front(make_pair(temp_i + i, temp_j + j));
				}
				else {
					que.push_back(make_pair(temp_i + i, temp_j + j));
				}

				//if (temp_i + i == 0 || temp_i + i == n - 1 || temp_j + j == 0 || temp_j + j == n - 1) {
					//if (dist.at(temp_i + i).at(temp_j + j) == 0) return 0;
					//return dist.at(temp_i + i).at(temp_j + j);
				//}
			}
		}
	}


	return -1;
}



