using namespace std;

const int maxn=511;

ll dp[maxn][maxn],a[maxn*maxn],ans=0;
int n;
ll dx[4]={0,1,0,-1},dy[4]={1,0,-1,0};
bool vis[maxn][maxn];

ll nv(ll x,ll y)
{
	ll mn=1e18;

	for(int i=0;i<4;i++)
	{
		ll tx=x+dx[i],ty=y+dy[i];

		if(tx>=0&&tx<n&&ty>=0&&ty<n)
		{
			mn=min(mn,dp[tx][ty]);
		}

	}

	return mn+(vis[x][y]==0);
}

void ref(ll x,ll y)
{
	dp[x][y]--;

	for(int i=0;i<4;i++)
	{
		ll tx=x+dx[i],ty=y+dy[i];

		if(tx>=0&&tx<n&&ty>=0&&ty<n)
		{
			if(nv(tx,ty)<dp[tx][ty])
			{
				ref(tx,ty);
			}
		}

	}

	return;
}

int main(){

	fast;itt;now;

	cin>>n;

	for(int i=0;i<n*n;i++)
	{
		cin>>a[i];
		a[i]--;
	}

	for(int i=0;i<n;i++)
	{
		for(int j=0;j<n;j++)
		{
			dp[i][j]=min(min(i,n-i-1),min(j,n-j-1))+1;
		}
	}

	for(int i=0;i<n*n;i++)
	{
		ll x=a[i]/n,y=a[i]%n;
		vis[x][y]=true;

		ref(x,y);
		ans+=dp[x][y];
	}

	cout<<ans<<endl;

	return 0;
}

