#include <stdio.h>

constexpr int MAX_INPUT_SIZE = 2000'000; //'
char Input[MAX_INPUT_SIZE];
char* input = Input;

inline int getint(void){
    int res = 0, c; while((c = *input++ - '0') >= 0) res = 10 * res + c;
    return res;
}

constexpr int MAX_N = 500;
constexpr int shift = 10;
constexpr int mask = (1 << shift) - 1;
int Q[MAX_N * MAX_N];
int dist[MAX_N][MAX_N];
bool vacant[MAX_N][MAX_N];

int main(void){
    fread_unlocked(Input, 1, MAX_INPUT_SIZE, stdin);
    const int n = getint();
    {
        // initial distance
        const int p = n - 1;
        for(int i = 0; i < n; ++i){
            const int d1 = (i > p - i) ? p - i : i;
            for(int j = 0; j < n; ++j){
                const int d2 = (j > p - j) ? p - j : j;
                dist[i][j] = (d1 > d2) ? d2 : d1;
            }
        }
    }
    int res = 0;
    for(int _ = n * n; _--;){
        {
            const int p = getint() - 1;
            const int px = p / n, py = p % n;
            res += dist[px][py];
            vacant[px][py] = true;
            Q[0] = (px << shift) | py;
        }
        int head = 0, tail = 1;
        while(head != tail){
            const int x = Q[head] >> shift, y = Q[head] & mask; ++head;
            const int nd = dist[x][y] + !vacant[x][y];
            if(x - 1 >= 0 and dist[x - 1][y] > nd){ dist[x - 1][y] = nd; Q[tail++] = ((x - 1) << shift)| y; }
            if(y - 1 >= 0 and dist[x][y - 1] > nd){ dist[x][y - 1] = nd; Q[tail++] = (x << shift) | (y - 1); }
            if(y + 1 <  n and dist[x][y + 1] > nd){ dist[x][y + 1] = nd; Q[tail++] = (x << shift) | (y + 1); }
            if(x + 1 <  n and dist[x + 1][y] > nd){ dist[x + 1][y] = nd; Q[tail++] = ((x + 1) << shift) | y; }
        }
    }
    printf("%d\n", res);
    return 0;
}

