const int MAX_N=501;
int c[MAX_N][MAX_N];
int n;
int vis[MAX_N][MAX_N];
pair<int,bool> min_dist;
pair<int,bool> check(int x,int y)
{
    vis[x][y]=1;
    //cout << x  << " "<< y << khatam;
    min_dist.F = min(min_dist.F,min({x,y,n-1-x,n-1-y}));
    if(x==0 || x==n-1 || y==0 || y == n-1){
        min_dist.S = true;
        return min_dist;
    }

    if(c[x-1][y]==0 && !vis[x-1][y])
        min_dist = MP(min(min_dist.F, check(x-1,y).F),min_dist.S);
    if(c[x][y+1]==0 && !vis[x][y+1])
        min_dist = MP(min(min_dist.F, check(x,y+1).F),min_dist.S);
    if(c[x+1][y]==0 && !vis[x+1][y])
        min_dist = MP(min(min_dist.F, check(x+1,y).F),min_dist.S);
    if(c[x][y-1]==0 && !vis[x][y-1])
        min_dist = MP(min(min_dist.F, check(x,y-1).F),min_dist.S);

    return min_dist;
}

void solve()
{
    cin >> n;
    int sz = n*n;
    int f=1;
    int cnt=0,val;
    for(int i=0;i<n;i++)
    {
        for(int j=0;j<n;j++){
            c[i][j] = f;
            f++;
        }
    }
    for(int i=0;i<sz;i++){
        cin >> val;
        int x = ((val-1)/n);
        int y = ((val-1)%n);
        //cout << x << " " << y << khatam;
        min_dist = MP(10000,false);
        MEM(vis,0);
        auto it = check(x,y);
        if(it.S){
            c[x][y] = 0;
        }
        else {cnt+=it.F; c[x][y]=0;}
    }
    cout << cnt << khatam;
}

