const ll N=D2,M=1e1+5,MOD=1e9+7,OO=1e9;
int arr[N*N],n;
vector<int> conn(int x){
    vector<int> res;
    if(x%n != 0)
        res.push_back(x+1);
    if((x-1)%n != 0)
        res.push_back(x-1);
    if(x+n<=n*n)
        res.push_back(x+n);
    if(x-n >= 1)
        res.push_back(x-n);
    return res;
}
pair<int,int> getInd(int x){
    int row=(x-1)/n;
    int col=x-row*n-1;
    return {row,col};
}
int ans[N][N];
bool taken[N][N];
int main(){
    cin.sync_with_stdio(false), cin.tie(0) , cout.tie(0);
#ifndef ONLINE_JUDGE
    freopen("std/in.txt", "rt" , stdin);
    // freopen("in.txt", "wt" , stdout);
#endif // ONLINE_JUDGE
    scanf("%d",&n);
    loop(i,n*n){
        scanf("%d",&arr[i]);
    }
    loop(i,n){
        loop(j,n){
            ans[i][j] = min({i,j,n-i-1,n-j-1});
        }
    }
    int res=0;
    loop(i,n*n){
        int x=arr[i];
        auto p=getInd(x);
        taken[p.first][p.second]=true;
        int cost = ans[p.first][p.second];
        res+=cost;
        queue<int> q;
        auto nbrs=conn(x);
        for(int g:nbrs){
            auto pg=getInd(g);
            if(ans[pg.first][pg.second]>cost){
                ans[pg.first][pg.second]=cost;
                q.push(g);
            }
        }
        while(!q.empty()){
            int cur=q.front();
            q.pop();
            p=getInd(cur);
            nbrs=conn(cur);
            cost = ans[p.first][p.second]+!taken[p.first][p.second];
            for(int g:nbrs){
                auto pg=getInd(g);
                if(ans[pg.first][pg.second]>cost){
                    ans[pg.first][pg.second]=cost;
                    q.push(g);
                }
            }
        }
    }
    printf("%d\n",res);
}

#include <bits/stdc++.h>
using namespace std;

#define LL long long
#define pii pair<int, int>
#define mp make_pair

const int maxN = 505, mv[4][2] = {{1, 0}, {0, 1}, {0, -1}, {-1, 0}};

int n;
int a[maxN * maxN + 1], v[maxN * maxN + 1];
int d[maxN + 1][maxN + 1];
bool flag[maxN + 1][maxN + 1];
LL ans = 0;

inline int id(int x, int y) { return (x - 1) * n + y; }

inline void bfs(int sx, int sy)
{
	int rule = v[ id(sx, sy) ];
	queue<pii> q;
	q.push( mp(sx, sy) );
	while(!q.empty())
	{
		int x = q.front().first, y = q.front().second; q.pop();
		flag[x][y] = false;
		for(int i = 0; i < 4; i++)
		{
			int nx = x + mv[i][0], ny = y + mv[i][1];	
			if(nx < 1 || nx > n || ny < 1 || ny > n) continue;
			int t = v[ id(x, y) ] > rule;
			if(d[x][y] + t < d[nx][ny])
			{
				d[nx][ny] = d[x][y] + t;
				if(!flag[nx][ny]) flag[nx][ny] = true, q.push( mp(nx, ny) );
			}
		}
	}
}

int main()
{
	scanf("%d", &n);
	for(int i = 1; i <= n * n; i++) scanf("%d", &a[i]), v[ a[i] ] = i;

	for(int i = 1; i <= n; i++)
		for(int j = 1; j <= n; j++)
			d[i][j] = min(min(i - 1, n - i), min(j - 1, n - j));

	for(int i = 1; i <= n * n; i++)
	{
		int x = (a[i] - 1) / n + 1, y = a[i] - (x - 1) * n;
		ans += d[x][y];
		bfs(x, y);	
	}

	printf("%lld\n", ans);
	return 0;
}

