#define ll long long

int N, is_here[500][500], res[500][500];

void ready(void){
    cin >> N;
    for (int i = 0; i < N; ++i){
        for (int j = 0; j < N; ++j){
            is_here[i][j] = 1;
            res[i][j] = min(min(i, N - 1 - i), min(j, N - 1 - j));
        }
    }
}

#ifdef TEST
void show(void){
    cout << "-----res-----" << endl;
    for (int i = 0; i < N; ++i){
        for (int j = 0; j < N; ++j){
            if (res[i][j] < 10) cout << res[i][j] << "  ";
            else if (res[i][j] < 100) cout << res[i][j] << " ";
            else cout << res[i][j];
            cout << " ";
        }
        cout << endl;
    }
}
#endif

void dfs(int x, int y){
    for (int dx = -1; dx <= 1; ++dx){
        for (int dy = -1; dy <= 1; ++dy){
            if (x + dx < 0 || x + dx >= N || y + dy < 0 || y + dy >= N)
                continue;
            if (dx != 0 && dy != 0) continue;
            if (res[x][y] + is_here[x][y] < res[x + dx][y + dy]){
                res[x + dx][y + dy] = res[x][y] + is_here[x][y];
                dfs(x + dx, y + dy);
            }
        }
    }
}

int move(int p){
    --p;
    int x = p / N, y = p % N;
    int v = res[x][y];
    is_here[x][y] = 0;
    dfs(x, y);
    return v;
}

int main(void){
    ready();
    ll res = 0;
#ifdef TEST
    show();
#endif
    for (int i = 0; i < N * N; ++i){
        int p; cin >> p;
        res += move(p);
#ifdef TEST
        show();
#endif
    }
    cout << res << endl;
    return 0;
}

