            flag++;
    m=min(flag,m);
    flag==0;
    for(int i=1;i<b;i++)
        if(!arr[a][i])
            flag++;
    m=min(flag,m);
    flag=0;
    for(int i=b+1;i<=n;i++)
        if(!arr[a][i])
            flag++;
    m=min(flag,m);
    for(int j=0; j<4; j++)
        if(arr[a+x[j]][b+y[j]]&&brr[a+x[j]][b+y[j]]==0) {
