using namespace std;
typedef long long ll;

int main()
{
  ll n;
  cin >> n;
  vector<ll> ps;
  ll n_pow = n * n;

  for (auto i = 0; i < n_pow; i++)
  {
    ll p;
    cin >> p;
    ps.push_back(p);
  }

  // 初期化
  vector<vector<ll>> mat(n + 2, vector<ll>(n + 2, 0));
  ll mat_len = n + 2;
  for (ll x = 0; x < mat_len; x++)
  {
    for (ll y = 0; y < mat_len; y++)
    {
      mat[x][y] = min(min(x - 1, mat_len - x - 2), min(y - 1, mat_len - y - 2));
    }
  }
  set<ll> called;

  auto print_mat = [&mat, mat_len]() {
    for (ll x = 0; x < mat_len; x++)
    {
      for (ll y = 0; y < mat_len; y++)
      {
        printf("%2lld", mat[y][x]);
      }
      cout << endl;
    }
  };
  // print_mat();

  auto update_mat = [&mat, mat_len, &called, n](ll mat_x, ll mat_y) {
    queue<pair<ll, ll>> q;
    set<pair<ll, ll>> visited;
    int patterns[4][2] = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};

    // 抜けたやつの周囲の最小値がそこにうまる.
    ll curmin = 100000000;
    for (auto i = 0; i < 4; i++)
    {
      //最小値計算
      auto pattern = patterns[i];
      curmin = min(curmin, mat[mat_x + pattern[0]][mat_y + pattern[1]]);

      //周辺は最初の更新対象になる
      auto pp = make_pair(mat_x + pattern[0], mat_y + pattern[1]);
      if (pp.first >= 1 && pp.first <= mat_len - 1 && pp.second >= 1 && pp.second <= mat_len - 1)
      {
        q.push(pp);
        visited.insert(pp);
      }
      else
      {
        // printf("skipped x: %lld, y: %lld\n", pp.first, pp.second);
      }
    }

    mat[mat_x][mat_y] = curmin;
    auto p = make_pair(mat_x, mat_y);
    visited.insert(p);

    // 今回抜けたものの周囲を更新する
    while (!q.empty())
    {
      auto size = q.size();

      for (auto i = 0; i < size; i++)
      {
        auto p = q.front();
        q.pop();

        if (p.first == 0 || p.first == mat_len - 1 || p.second == 0 || p.second == mat_len - 1)
        {
          continue;
        }

        // 最初のやつがどのポジションにいるのかを計算しないといけない
        // 上下左右の最小値+1をすればいい。仮に自分自身が更新されていれば、その周囲のやつらもqueueに積む
        ll cur_min = 100000000;
        for (auto j = 0; j < 4; j++)
        {
          auto pattern = patterns[j];
          if ((p.first + pattern[0]) >= 0 && (p.first + pattern[0]) <= mat_len - 1 && (p.second + pattern[1]) >= 0 && (p.second + pattern[1]) <= mat_len - 1)
          {
            cur_min = min(cur_min, mat[p.first + pattern[0]][p.second + pattern[1]]);
          }
        }

        ll call_number = p.first + n * (p.second - 1);
        ll updated = called.count(call_number) > 0 ? cur_min : cur_min + 1;
        if (mat[p.first][p.second] != updated)
        {
          mat[p.first][p.second] = updated;
          for (auto j = 0; j < 4; j++)
          {
            auto pattern = patterns[j];
            auto pp = make_pair(p.first + pattern[0], p.second + pattern[1]);

            // 更新の対象にするのは外側のやつだけ
            if (visited.count(pp) == 0 && pp.first >= 1 && pp.first < mat_len - 1 && pp.second >= 1 && pp.second < mat_len - 1)
            {
              q.push(pp);
              visited.insert(pp);
            }
          }
        }
      }
    }

    return;
  };

  ll cnt = 0;
  for (auto i = 0; i < ps.size(); i++)
  {
    auto p = ps[i];
    called.insert(p);

    // mat内のindex.
    ll mat_x = (p - 1) % n + 1;
    ll mat_y = ((p - 1) / n) + 1;
    // cout << "p: " << p << " mat_x: " << mat_x << " mat_y: " << mat_y << endl;

    cnt += mat[mat_x][mat_y];
    // matを更新する
    update_mat(mat_x, mat_y);
    // print_mat();
    // printf("cnt: %lld\n", cnt);
  }

  cout << cnt << endl;

  return 0;
}

