    int N; cin >> N;
    vector<int> P(N*N);
    for(int i = 0; i < N*N; ++i) cin >> P[i],P[i]--;
    vector<int> dx = {-1,1,0,0},dy={0,0,-1,1};
    auto cost = multivector(N,N,N);
    auto vst = multivector(N,N,1);
    for(int i = 0; i < N; ++i) {
        for(int j = 0; j < N; ++j) {
            chmin(cost[i][j],i);
            chmin(cost[i][j],j);
