			if (inBound(x2,y2)){
				int newDist = dist[x][y] + seats[x2][y2];
				if (newDist < dist[x2][y2]){
					dist[x2][y2] = newDist;
					if (!inq[x2][y2]){
						inq[x2][y2] = 1;
						q.push({x2, y2});
					}
				}
			}
		}
	}
}
