ll N;
struct pos{
    ll x,y;
    bool operator<( const pos& a) const {
        if(x == a.x)return y < a.y;
        else return x < a.x;
    }
};

pos mpos(ll x,ll y){
    pos tmp ={x,y};
    return tmp;
}

ll calc(pos a){
    return a.x+1+a.y*N;
}

vector <ll> grid;
vector <bool> gridbool;

void del(pos now, ll c);

void update(pos now, ll c){
    grid[calc(now)] = c;
    rep(i,0,4){
        if(now.x + dx[i] <= N-1 && now.x + dx[i] >= 0 && now.y + dy[i] >= 0 && now.y + dy[i] <= N-1){
            pos nxt = mpos(now.x + dx[i], now.y + dy[i]);
            if(grid[calc(nxt)] > grid[calc(now)]+1){
                if(gridbool[calc(nxt)])update(nxt, grid[calc(now)] + 1);
                else del(nxt, grid[calc(now)] + 1);
            }
        }
    }
}

void del(pos now, ll c){
    grid[calc(now)] = c;
    rep(i,0,4){
        if(now.x + dx[i] <= N-1 && now.x + dx[i] >= 0 && now.y + dy[i] >= 0 && now.y + dy[i] <= N-1){
            pos nxt = mpos(now.x + dx[i], now.y + dy[i]);
            if(grid[calc(nxt)] > grid[calc(now)]){
                if(gridbool[calc(nxt)])update(nxt, grid[calc(now)]);
                else del(nxt, grid[calc(now)]);
            }
        }
    }
}


int main(){
    cin>>N;
    vector<pos> p(N*N);
    grid.resize(N*N+1);
    gridbool.resize(N*N+1);
    rep(i,0,N*N){
        ll a;
        cin>>a;
        ll tmp;
        if(a%N == 0)tmp = N;
        else tmp = a%N;
        p[i].x = tmp-1;
        p[i].y = (a-1)/N;
    }
    ll ans = 0;
    rep(i,0,N)rep(j,0,N){
        pos tmp = mpos(i,j);
        grid[calc(tmp)] = min(min(N-1-i,i),min(N-1-j,j));
        gridbool[calc(tmp)] = true;
    }

    rep(i,0,N*N){
        ans += grid[calc(p[i])];
        //cout<<p[i].x<<p[i].y<<" "<<grid[p[i]]<<endl;
        gridbool[calc(p[i])] = false;
        del(p[i], grid[calc(p[i])]);
    }
    cout<<ans;

    return 0;
}

