int x[250001],pa[250001],r[250001],oc[250001],p,n;
int find(int x){
    return pa[x]=pa[x]==x?x:find(pa[x]);
}
void merge(int x1,int x2){
    int a=find(x1),b=find(x2);
    if(a==b)return;
    if(r[a]<r[b]){
        pa[a]=b;
        x[b]=min(x[a],x[b]);
    }else{
        pa[b]=a;
        x[a]=min(x[a],x[b]);
        if(r[b]==r[a])++r[a];
    }
}

