    for(int i=0;i<n*n;i++){
        int x1=i/n;
        int y1=i%n;
        x[i]=min(x1,min(n-1-x1,min(y1,n-1-y1)));
        pa[i]=i;
        r[i]=0;
        oc[i]=1;
