struct Grider{
    ll H,W;
    vector<vector<ll>> map2d;
    vector<vector<ll>> val;
    ll dx[4]={0,-1,0,1}, dy[4]={-1,0,1,0};

    Grider(ll h, ll w): H(h), W(w), map2d(h,vector<ll>(w,1)), val(h,vector<ll>(w,INF2)) {}

    bool outmap(const ll& x, const ll& y){
        if(x<0 or x>=H) return true;
        if(y<0 or y>=W) return true;
        if(!map2d[x][y]) return true;
        return false;
    }
    ll cdir(const char& c){
        if(c=='L') return 0;
        if(c=='U') return 1;
        if(c=='R') return 2;
        if(c=='D') return 3;
        return -1;
    }

    P go(const ll& x, const ll& y, const char& c){
        ll nx=x+dx[cdir(c)], ny=y+dy[cdir(c)];
        if(outmap(nx,ny)) return {x,y};
        return {nx,ny};
    }
    P gostr(const ll& x, const ll& y, const string& s){
        ll nowx=x, nowy=y;
        for(auto& c: s){
            P buf=go(nowx,nowy,c);
            nowx=buf.first, nowy=buf.second;
        }
        return {nowx,nowy};
    }

    deque<P> Q;
    void bfs(){
        while(!Q.empty()){
            ll x=Q.front().first, y=Q.front().second;
            Q.pop_front();
            rep(dir,4){
                ll nx=x+dx[dir], ny=y+dy[dir];
                if(outmap(nx,ny)) continue;
                if(mini(val[nx][ny], val[x][y]+2-map2d[nx][ny])){
                    Q.emplace_back(nx,ny);
                }
            }
        }
    }
    void qin(ll x, ll y){
        Q.emplace_back(x, y);
        val[x][y]--;
        bfs();
    }
};
