ll bo[510][510];

bool used[510][510];

int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);
    ll N;
    cin >> N;
    ll M = N * N;
    ll P[M];
    REP(i, 0, M) {
        cin >> P[i];
        P[i]--;
    }
    // cout << "aaa" << endl;
    ll ans = 0;
    REP(i, 0, N) {
        REP(j, 0, N) {
            bo[i + 1][j + 1] = min(min(i, N - 1 - i), min(j, N - 1 - j));
        }
    }
    REP(i, 0, M) {
        // REP(j, 0, N) {
        //     REP(k, 0, N) {
        //         cout << bo[j + 1][k + 1] << " ";
        //     }
        //     cout << endl;
        // }
        ll q = P[i];
        ll x = q % N + 1;
        ll y = q / N + 1;
        // cout << x << " " << y << endl;
        ans += bo[x][y];
        // cout << bo[x][y] << endl;
        used[x][y] = true;
        queue<plglg> que;
        que.push(plglg(x, y));
        while (!que.empty()) {
            plglg p = que.front();
            que.pop();
            ll px = p.first;
            ll py = p.second;
            ll val = bo[px][py];
            if (!used[px][py]) {
                val++;
            }
            REP(j, 0, 4) {
                ll newx = px + dx[j];
                ll newy = py + dy[j];
                if (val < bo[newx][newy]) {
                    bo[newx][newy] = val;
                    que.push(plglg(newx, newy));
                }
            }
        }
    }
    cout << ans << endl;
}

