ll get_cost(int r, int c){
	FOR(i,0,n){
		FOR(j,0,n){
			d[i][j] = LLINF;
		}
	}

	d[r][c] = 0;
	deque<pii> q;
	q.push_front({r,c});

	while (!q.empty()) {
	    pii v = q.front();
	    q.pop_front();

	    int row = v.F;
	    int col = v.S;

	    if ( row == 0 || row == n-1 || col == 0 || col == n-1 )
	    	return d[v.F][v.S];

	    if ( d[row][col] + mat[row+1][col] < d[row+1][col] ){
	    	d[row+1][col] = d[row][col] + mat[row+1][col];
	    	if ( mat[row+1][col] == 1 )
	    		q.push_back({row+1, col});
	    	else
	    		q.push_front({row+1,col});
	    }

	    if ( d[row][col] + mat[row-1][col] < d[row-1][col] ){
	    	d[row-1][col] = d[row][col] + mat[row-1][col];
	    	if ( mat[row-1][col] == 1 )
	    		q.push_back({row-1, col});
	    	else
	    		q.push_front({row-1,col});
	    }

	    if ( d[row][col] + mat[row][col+1] < d[row][col+1] ){
	    	d[row][col+1] = d[row][col] + mat[row][col+1];
	    	if ( mat[row][col+1] == 1 )
	    		q.push_back({row, col+1});
	    	else
	    		q.push_front({row,col+1});
	    }

	    if ( d[row][col] + mat[row][col-1] < d[row][col-1] ){
	    	d[row][col-1] = d[row][col] + mat[row][col-1];
	    	if ( mat[row][col-1] == 1 )
	    		q.push_back({row, col-1});
	    	else
	    		q.push_front({row,col-1});
	    }

	}

}

