int main() {

    ios::sync_with_stdio(false); // stdioを使うときはコメントアウトすること
    cin.tie(nullptr);            // インタラクティブ問題ではコメントアウトすること

    ll n = in1;
    vector<ll> p = qin(n*n);
    FOREACH(x, p) x--;

    auto ngbs = [&](ll i) {
        const auto [x, y] = pair(i % n, i / n);
        vector<ll> r;
        if (x-1 >= 0) r.push_back(i-1);
        if (x+1 <  n) r.push_back(i+1);
        if (y-1 >= 0) r.push_back(i-n);
        if (y+1 <  n) r.push_back(i+n);
        return r;
    };

    vector dp(n*n, 0LL);
    REP(i, n*n) dp[i] = min({i%n, i/n, n-1-i/n, n-1-i%n});

    vector g(n*n, true);

    ll ans = 0;
    REP(i, n*n) {
        ans += dp[p[i]];
        g[p[i]] = false;
        deque<ll> q = {p[i]};
        while (q.size()) {
            ll u = q.front(); q.pop_front();
            FOREACH(v, ngbs(u)) {
                if (chmin(dp[v], dp[u] + g[u])) {
                    q.push_back(v);
                }
            }
        }
    }
    say(ans);

}

