int n;
int d[505][505], s[505][505];

void init() {
  rep(i, n) {
    rep(j, n) {
      d[i][j] = inf;
      s[i][j] = 1;
      chmin(d[i][j], i);
      chmin(d[i][j], n - 1 - i);
      chmin(d[i][j], j);
      chmin(d[i][j], n - 1 - j);
    }
  }
}

void bfs(int sy, int sx) {
  s[sy][sx] = 0;
  queue<pair<int, int>> q;
  q.push({sy, sx});
  while (!q.empty()) {
    int y = q.front().first, x = q.front().second;
    q.pop();
    rep(k, 4) {
      int ry = y + dy[k], rx = x + dx[k];
      if (ry < 0 || ry >= n || rx < 0 || rx >= n) continue;
      if (chmin(d[ry][rx], d[y][x] + s[y][x])) {
        q.push({ry, rx});
      }
    }
  }
}


