bool exist[500][500];
bool zero[500][500];
bool visited[500][500];
int n;
int reach(int x, int y) {
    if (visited[x][y]) return 9999;
    if (x<0 || x>=n || y<0 || y>=n) {
        return 0;
    }
    if (zero[x][y]) return 0;

    visited[x][y]=true;
    int mini =      reach(x+1,y);
    if (mini>0) mini = min(mini, reach(x-1,y));
    if (mini>0) mini = min(mini, reach(x,y+1));
    if (mini>0) mini = min(mini, reach(x,y-1));
    visited[x][y]=false;

    if (exist[x][y]) mini++;
    if (mini==0) zero[x][y]=true;
    return mini;
}


int main() {
    cin >> n;

    rep(i,n) {
        rep(j,n) {
            exist[i][j]=true;
            zero[i][j]=false;
            visited[i][j]=false;
        }
    }

    int ans = 0;
    rep(i,n*n) {
        int p;
        cin >> p;
        int x=(p-1)/n, y=(p-1)%n;
        exist[x][y]=false;
        int t = reach(x,y);
        ans += t;
        //cout << p << ":" << t << endl;
    }

    cout << ans << endl;

    return 0;
}

