typedef pair<int, int> ii;
int dx[4] = {1, -1, 0, 0}, dy[4] = {0, 0, 1, -1};
int main() {
	int N, P;
	scanf("%d", &N);
	int dist[N + 2][N + 2], ans = 0;
	for (int i = 0; i < N + 2; ++i) {
		for (int j = 0; j < N + 2; ++j) dist[i][j] = min(min(i, N + 1 - i), min(j, N + 1 - j));
	}
	ii pos[N * N];
	bool emptied[N + 2][N + 2];
	for (int i = 0; i < N + 2; ++i) {
		for (int j = 0; j < N + 2; ++j) emptied[i][j] = true;
	}
	for (int i = 0; i < N * N; ++i) {
		scanf("%d", &P);
		pos[i] = ii((P - 1) / N + 1, (P - 1) % N + 1);
	}
	for (int i = 0; i < N * N; ++i) {
		emptied[pos[i].F][pos[i].S] = false;
		for (int j = 0; j < 4; ++j) dist[pos[i].F][pos[i].S] = min(dist[pos[i].F][pos[i].S], dist[pos[i].F + dx[j]][pos[i].S + dy[j]]);
		queue<ii> bfs;
		bfs.push(pos[i]);
		while (!bfs.empty()) {
			ii x = bfs.front();
			bfs.pop();
			for (int j = 0; j < 4; ++j) {
				if (dist[pos[i].F][pos[i].S] + emptied[pos[i].F + dx[j]][pos[i].S + dy[j]] < dist[pos[i].F + dx[j]][pos[i].S + dy[j]]) {
					dist[pos[i].F + dx[j]][pos[i].S + dy[j]] = dist[pos[i].F][pos[i].S] + emptied[pos[i].F + dx[j]][pos[i].S + dy[j]];
					bfs.push(ii(pos[i].F + dx[j], pos[i].S + dy[j]));
				}
			}
		}
		ans += dist[pos[i].F][pos[i].S];
	}
	printf("%d", ans);
	return 0;
}

