void bordcost(int x, int y);

void Bordcost(int x, int y, int cost_t,bool ocpa) {
    if (work[x][y].cost > cost_t) {
        bool bc = !castmap[x][y];
        if (ocpa) {
            if (work[x][y].cost == cost_t + 1) {
                bc = false;
            }
            work[x][y].cost = cost_t + 1;
        }
        else {
            work[x][y].cost = cost_t;
        }
        if (bc)bordcost(x, y);
    }
}

void bordcost(int x, int y) {
    int temp = work[x][y].cost;
    int ocpa = work[x][y].ocp;
    castmap[x][y] = true;
    Bordcost(x - 1, y, temp, ocpa);
    Bordcost(x + 1, y, temp, ocpa);
    Bordcost(x, y + 1, temp, ocpa);
    Bordcost(x, y - 1, temp, ocpa);

}

int leave(int le) {
    int x = le / (SIZE-2) + 1;
    int y = le % (SIZE-2) + 1;
    int output = work[x][y].cost;
    work[x][y].ocp = false;
    bordcost(x, y);
    return output;
}

