void bfs(ll u){
        queue<pair<ll, ll>> q;
        q.push({u, d[u]});
        while (q.size()){
                pair<ll, ll> now = q.front();
                q.pop();
                for (auto j : node[now.first]){
                        if (d[j] > (now.second + 1 - pass[now.first])){
                                d[j] = now.second + 1 - pass[now.first];
                                q.push({j, d[j]});
                        }
                }
        }
}
