                ll col = p[i] % n;
                if (col){
                        row++;
                } else {
                        col = n;
                }
                d[p[i]] = min(min(row - 1, col - 1), min(n - row, n - col));
                if (row > 1){
                        node[p[i]].push_back(p[i] - n);
