						}else{
							dq.push_back({xnew,ynew});
						}
					}
				}
			}
		}

		cout << ans << endl;
	}

	void solve(){
		int tc = 1;
		for(int it = 1; it <= tc; it++){
			solveOne(it);
		}
	}
};


