const int maxn = 510;

int dp[maxn][maxn];
int f[maxn][maxn];

int dx[4] = { -1, 1, 0, 0 };
int dy[4] = { 0, 0, -1, 1 };

int n;

void dfs(int x, int y) {
	for (int it = 0; it < 4; it++) {
		int nx = x + dx[it];
		int ny = y + dy[it];

		if (0 <= nx && nx < n && 0 <= ny && ny < n && dp[nx][ny] > dp[x][y] + f[nx][ny]) {
			dp[nx][ny] = dp[x][y] + f[nx][ny];
			dfs(nx, ny);
		}
	}
}

int main() {
	cin >> n;

	for (int i = 0; i < n; i++) {
		for (int j = 0; j < n; j++) {
			dp[i][j] = min(i, min(j, min(n - 1 - i, n - 1 - j))) + 1;
			f[i][j] = 1;
		}
	}

	ll ans = 0;

	for (int i = 0; i < n * n; i++) {
		int v;
		scanf("%d", &v);

		v--;
		int x = v / n;
		int y = v % n;
		f[x][y] = 0;

		ans += dp[x][y] - 1;

		dp[x][y]--;
		dfs(x, y);
	}

	cout << ans << '\n';
}

