bool valid(ll n, ll h, ll w){
    return (0 <= h && h < n && 0 <= w && w < n);
}


ll has(ll n, ll h, ll w){
    return h * n + w;
}
class UnionFind {
public:
    vector <ll> par;
    vector <ll> siz;
    vector <ll> score;

    UnionFind(ll sz_): par(sz_*sz_), siz(sz_*sz_, 1LL) ,score(sz_*sz_){
        for (ll i = 0; i < sz_*sz_; ++i) par[i] = i;
        rep(i, sz_)rep(j, sz_){
            score[has(sz_, i, j)] = i;
            chmin(score[has(sz_, i, j)], j);
            chmin(score[has(sz_, i, j)], sz_ - j - 1);
            chmin(score[has(sz_, i, j)], sz_ - i - 1);
        }
        sz_ *= sz_;
    }
    void init(ll sz_) {
        par.resize(sz_);
        siz.assign(sz_, 1LL);
        for (ll i = 0; i < sz_; ++i) par[i] = i;
    }

    ll find(ll x) {
        while (par[x] != x) {
            x = par[x] = par[par[x]];
        }
        return x;
    }

    bool merge(ll x, ll y) {
        x = find(x);
        y = find(y);
        if (x == y) return false;
        if (siz[x] < siz[y]) swap(x, y);
        siz[x] += siz[y];
        par[y] = x;
        chmin(score[x], score[y]);
        return true;
    }

    bool issame(ll x, ll y) {
        return find(x) == find(y);
    }

    ll size(ll x) {
        return siz[find(x)];
    }
};

int main(){
    ll n; cin >> n;
    ll q = n * n;
    vector<ll> a(q); rep(i, q) cin >> a[i];
    UnionFind uf(n);
    ll ans = 0;
    rep(i, q){
        a[i]--;
        ans += uf.score[a[i]];
        ll h = a[i] / n;
        ll w = a[i] % n;
        if (valid(n, h - 1, w)) uf.merge(has(n, h + 1, w), has(n, h, w));
        if (valid(n, h + 1, w)) uf.merge(has(n, h - 1, w), has(n, h, w));
        if (valid(n, h, w - 1)) uf.merge(has(n, h, w - 1), has(n, h, w));
        if (valid(n, h, w + 1)) uf.merge(has(n, h, w + 1), has(n, h, w));
        // debug(uf.score);
    }
    pt(ans);
    return 0;
}

