		if(v[i]%n==1 || v[i]%n==0 || v[i]/n==0 || v[i]/n==n-1)
		{
			if(v[i]%n==0)
				visit[v[i]/n-1][n-1]=1;
			else if(v[i]%n==1)
				visit[v[i]/n][0]=1;
			else if(v[i]/n==0)
				visit[0][v[i]-1]=1;
			else
				visit[n-1][(v[i]%n)-1]=1;
		}
		else{
			row=v[i]/n;
			col=(v[i]%n)-1;
			cnt1=Max;
			cnt=0;
			loop(j,0,row)
				if(visit[j][col]==0)
					cnt++;
			cnt1=min(cnt,cnt1);
			cnt=0;
			loop(j,row+1,n)
				if(visit[j][col]==0)
					cnt++;
			cnt1=min(cnt,cnt1);
			cnt=0;
			loop(j,col+1,n)
				if(visit[row][j]==0)
					cnt++;
			cnt1=min(cnt,cnt1);
			cnt=0;
			loop(j,0,col)
				if(visit[row][j]==0)
					cnt++;
			cnt1=min(cnt,cnt1);
			//cout<<v[i]<<" "<<cnt1<<endl;
			ans+=cnt1;
			visit[row][col]=1;
		}
	}
	cout<<ans<<endl;
}
