					// either alive and over +2 or dead and over +1
					if(alive[i+dx][j+dy] && cost[i+dx][j+dy]>cost[i][j]+1) {
						cost[i+dx][j+dy]=cost[i][j]+1;
						que.emplace(n-cost[i+dx][j+dy],std::make_pair(i+dx,j+dy));
					}
					if(!alive[i+dx][j+dy] && cost[i+dx][j+dy]>cost[i][j]) {
						cost[i+dx][j+dy]=cost[i][j];
						que.emplace(n-cost[i+dx][j+dy],std::make_pair(i+dx,j+dy));
					}
				}
			}
		}
		debug(x,y);
		debug(cost);
		debug(alive);
	}
	print(sum);
}

