class UnionFindDX
{

public:

	vector <ll>pairent;
	vector <ll>depth;
	vector <ll>size;
	vector <ll>value;

	UnionFindDX(ll Amount) : pairent(Amount, 1), depth(Amount, 1), size(Amount, 1),value(Amount,-1) {

		for (ll i = 0; i < Amount; i++) {
			pairent[i] = i;
		}
	}


	ll FindPairent(ll x) {
		if (pairent[x] == x)return x;
		else return pairent[x] = FindPairent(pairent[x]);
	}


	ll Merge(ll x, ll y) {
		x = FindPairent(x);
		y = FindPairent(y);

		if (x != y) {
			ll v = min(value[x], value[y]);
			value[x] = v;
			value[y] = v;
			if (depth[x] > depth[y]) {
				pairent[y] = pairent[x];
				return size[x] += size[y];
			}
			else {
				pairent[x] = pairent[y];
				if (depth[x] == depth[y]) {
					depth[y] ++;
				}
				return size[y] += size[x];
			}
		}
		else {
			ll v = min(value[x], value[y]);
			value[x] = v;
			value[y] = v;
			return -1;
		}
	}



	bool IsSame(ll x, ll y) {
		if (FindPairent(x) == FindPairent(y))return true;
		else return false;
	}


	ll GetSize(ll x) {
		x = FindPairent(x);
		return size[x];
	}

	ll GetValue(ll x) {
		x = FindPairent(x);
		return value[x];
	}

};

