using P = pair<int,int>;
int dx[4] = {0,1,0,-1};
int dy[4] = {1,0,-1,0};

int main(){
  int n;
  cin >> n;
  int p[n*n];
  rep(i,n*n) {
    cin >> p[i];
    p[i]--;
  } 
  int h[n][n];
  bool u[n][n];
  rep(i,n) rep(j,n) u[i][j] = false;
  rep(i,n) rep(j,n) h[i][j] = min({i,j,n-1-i,n-1-j});
  int ans = 0;
  rep(i,n*n) {
    int x = p[i]/n, y = p[i] % n;
    ans += h[x][y];
    u[x][y] = true;
    queue<P> que;
    que.push(P(x,y));
    while(!que.empty()){
      P pos = que.front();
      que.pop();
      rep(j,4) {
        int nx = pos.first + dx[j], ny = pos.second + dy[j];
        if(nx >= 0 && nx < n && ny >= 0 && ny < n) {
          if(u[pos.first][pos.second] and h[nx][ny] > h[pos.first][pos.second]) {
            h[nx][ny] = h[pos.first][pos.second];
            que.push(P(nx,ny));
          } else if(!u[pos.first][pos.second] and h[nx][ny] > h[pos.first][pos.second] + 1) {
            h[nx][ny] = h[pos.first][pos.second] + 1;
            que.push(P(nx,ny));
          }
        }
      }
    }
  }
  cout << ans << endl;
  return 0;
}

