int n,ans;
int dis[MAXN][MAXN],w[MAXN][MAXN];
deque<pii> q;

bool check(int x,int y){
    return x >= 1 && x <= n && y >= 1 && y <= n;
}

void bfs(int x,int y){
    ans += --dis[x][y];
    w[x][y] = 0;
    while(!q.empty())
        q.pop_back();
    q.push_back(make_pair(x,y));
    while(!q.empty()){
        int x = q.front().first;
        int y = q.front().second;
        q.pop_front();
        for(int i = 0;i < 4;i++){
            int nx = x + dx[i];
            int ny = y + dy[i];
            if(!check(nx,ny))
                continue;
            if(dis[nx][ny] > dis[x][y] + w[nx][ny]){
                dis[nx][ny] = dis[x][y] + w[nx][ny];
                if(w[nx][ny])
                    q.push_back(make_pair(nx,ny));
                else
                    q.push_front(make_pair(nx,ny));
            }
        }
    }
}

