vi di = {0, 0, -1, 1};
vi dj = {-1, 1, 0, 0};

void solve() {
    int n;
    cin >> n;

    vi p(n * n);
    fori (i, n * n) {
        cin >> p[i];
        p[i]--;
    }

    vvi d(n, vi(n, 0));
    vvi used(n, vi(n, 0));
    fori (i, n) {
        fori (j, n) {
            d[i][j] = min(min(i, n - i - 1), min(j, n - j - 1));
        }
    }
    auto in_bound = [&] (int i, int j) -> bool {
        return i >= 0 && i < n && j >= 0 && j < n;
    };

    auto change = function<void(int, int)>();
    change = [&] (int i, int j) -> void {
        int ret = n * n;
        fori (dir, di.size()) {
            int ii = i + di[dir];
            int jj = j + dj[dir];
            if (in_bound(ii, jj))
                inmin(ret, d[ii][jj]);
            else
                ret = 0;
        }
        ret += !used[i][j];

        if (ret != d[i][j]) {
            d[i][j] = ret;
            fori (dir, di.size()) {
                int ii = i + di[dir];
                int jj = j + dj[dir];
                if (in_bound(ii, jj))
                    change(ii, jj);
            }
        }
    };

    ll ans = 0;
    for (auto x : p) {
        int i = x / n, j = x % n;
        used[i][j] = 1;
        change(i, j);
        ans += d[i][j];
    }
    cout << ans << '\n';
}

void smain() {
    solve();
}

