void dfs(ll x, ll y)
{
	if(dis[x-1][y] > dis[x][y] + a[x][y])
	{
		dis[x-1][y] = dis[x][y] + a[x][y];
		dfs(x-1, y);
	}
	if(dis[x][y-1] > dis[x][y] + a[x][y])
	{
		dis[x][y-1] = dis[x][y] + a[x][y];
		dfs(x, y-1);
	}
	if(dis[x+1][y] > dis[x][y] + a[x][y])
	{
		dis[x+1][y] = dis[x][y] + a[x][y];
		dfs(x+1, y);
	}
	if(dis[x][y+1] > dis[x][y] + a[x][y])
	{
		dis[x][y+1] = dis[x][y] + a[x][y];
		dfs(x, y+1);
	}
}
