vector<pii> wait[nn*nn];int vis[nn][nn];
void spread(int now,int cg){
	for(int i=0;i<nn*nn;i++) wait[i].clear();
	for(int i=1;i<=n;i++) for(int j=1;j<=n;j++) vis[i][j]=0,wait[dp[now][i][j]].push_back(mp(i,j));

	for(int i=n*n;i>=1;i--) if(wait[i].size()){
		for(int e=0;e<wait[i].size();e++){
			pii p=wait[i][e];
			int x=p.first,y=p.second;if(vis[x][y]) continue;vis[x][y]=1;
			for(int k=0;k<4;k++){
				if(x+ax[k]>=1 and x+ax[k]<=n and y+ay[k]>=1 and y+ay[k]<=n)
				if(dp[now][x+ax[k]][y+ay[k]]<min(dp[now][x][y],sig[x+ax[k]][y+ay[k]])){

					dp[now][x+ax[k]][y+ay[k]]=min(dp[now][x][y],sig[x+ax[k]][y+ay[k]]);
					wait[dp[now][x+ax[k]][y+ay[k]]].push_back(mp(x+ax[k],y+ay[k]));
				}
			}
		}
	}


	for(int i=1;i<=n;i++) for(int j=1;j<=n;j++) for(int k=0;k<4;k++) if(dp[now][i][j]>=sig[i+ax[k]][j+ay[k]]) 
			fst[i+ax[k]][j+ay[k]]=min(fst[i+ax[k]][j+ay[k]],cg);

}
