    loop(i, N * N)
    {
        P[i]--;
        ll sx = P[i] % N;
        P[i] /= N;
        ll sy = P[i];
        field[sx][sy] = '.';
        if(i<=1){
            ans+=min(min(sx,N-1-sx),min(sy,N-1-sy));
