int dis[N][N][N / 2], P[N][N], n;
int odrad[N][N][N / 2];
priority_queue < pair < int, pair < pii, int > > > Q;

const int px[4] = {1, -1, 0, 0};
const int py[4] = {0, 0, 1, -1};

int main(){
	memset(dis, INF, sizeof(dis));
	memset(odrad, -1, sizeof(odrad));
	scanf("%d", &n);
	for(int i = 0;i < n * n;i++){
		int x; scanf("%d", &x); x--;
		P[x % n][x / n] = i;
	}
	for(int i = 0;i < n;i++){
		Q.push({0,{{0, i}, 0}}); dis[0][i][0] = 0;
		Q.push({0,{{n - 1, i}, 0}}); dis[n - 1][i][0] = 0;	
		Q.push({0,{{i, 0}, 0}}); dis[i][0][0] = 0;
		Q.push({0, {{i, n - 1}, 0}}); dis[i][n - 1][0] = 0;		
	}
	for(;!Q.empty();){
		int cx = Q.top().Y.X.X;
		int cy = Q.top().Y.X.Y;
		int ck = Q.top().Y.Y;
		Q.pop();
		if(odrad[cx][cy][ck] == dis[cx][cy][ck])
			continue;
		if(ck && dis[cx][cy][ck - 1] <= dis[cx][cy][ck])
			continue;
		odrad[cx][cy][ck] = dis[cx][cy][ck];
		for(int m = 0;m < 4;m++){
			int mx = cx + px[m], my = cy + py[m];
			if(mx < 0 || mx >= n || my < 0 || my >= n) continue;
			if(max(dis[cx][cy][ck], P[cx][cy]) < dis[mx][my][ck]){
				dis[mx][my][ck] = max(dis[cx][cy][ck], P	[cx][cy]);
				Q.push({-dis[mx][my][ck], {{mx, my}, ck}});
			}
			if(ck < n / 2 && dis[cx][cy][ck] < dis[mx][my][ck + 1]){
				dis[mx][my][ck + 1] = dis[cx][cy][ck];
				Q.push({-dis[mx][my][ck + 1], {{mx, my}, ck + 1}});
			}
		}
	}
	int odg = 0;
	for(int i = 0;i < n;i++){
		for(int j = 0;j < n;j++){
			int k = 0;
			for(;dis[i][j][k] > P[i][j];k++);
			odg += k;
		}
	}
	printf("%d\n", odg);
	return 0;
}

