}

void Main()
{
	int N;
	std::cin >> N;
	auto decode = [&](int idx)
	{
		--idx;
		return std::make_pair(idx / N, idx % N);
	};
	std::vector<std::pair<int, int>> vec;
	for (auto _ : boost::irange(N* N))
	{
		int code;
		std::cin >> code;
		vec.push_back(decode(code));
	}
	boost::multi_array<bool, 2> opened(boost::extents[N][N]);
	boost::multi_array<bool, 2> checked(boost::extents[N][N]);
	boost::multi_array<bool, 2> goal(boost::extents[N][N]);
	for (auto i : boost::irange(N))
	{
		goal[i][0] = goal[i][N - 1] = goal[0][i] = goal[N - 1][i] = true;
	}
	int count = 0;
	for (auto [i, k] : vec)
	{
		std::deque<std::tuple<int, int, int>> queue;
		auto push = [&](int a, int b, int c)
		{
			if (0 <= a && a < N && 0 <= b && b < N && !checked[a][b])
			{
				checked[a][b] = true;
				if (opened[a][b])
				{
					queue.emplace_front(a, b, c);
				}
				else
				{
					queue.emplace_back(a, b, c + 1);
				}
			}
		};
		std::queue<std::pair<int, int>> goal_queue;
		auto goal_push = [&](int a, int b)
		{
			if (0 <= a && a < N && 0 <= b && b < N && opened[a][b] && !goal[a][b])
			{
				goal[a][b] = true;
				goal_queue.emplace(a, b);
			}
		};

		for (auto x : boost::irange(N))
		{
			for (auto y : boost::irange(N))
			{
				checked[x][y] = false;
			}
		}
		opened[i][k] = true;
		push(i, k, 0);
		while (queue.size())
		{
			auto [a, b, c] = queue.front();
			queue.pop_front();
			if (goal[a][b])
			{
				count += c;
				if (c == 0)
				{
					goal_push(i, k);
					while (goal_queue.size())
					{
						auto [x, y] = goal_queue.front();
						goal_queue.pop();
						goal_push(x - 1, y);
						goal_push(x + 1, y);
						goal_push(x, y - 1);
						goal_push(x, y + 1);
					}
				}
				break;
			}
			push(a - 1, b, c);
			push(a + 1, b, c);
			push(a, b - 1, c);
			push(a, b + 1, c);
		}
		queue.clear();
	}
	std::cout << count << std::endl;
}

