void updDist(int x1, int y1){
	vector<pair<int,int>> q;
	q.push_back({x1, y1});
	for (int i = 0; i < q.size(); i++){
		auto u = q[i];
		int x = u.first; int y = u.second;
		inq[x][y] = 0;
		for (int d = 0; d < 4; d++){
			int x2, y2;
			x2 = x + dx[d];
			y2 = y + dy[d];
			if (inBound(x2,y2)){
				int newDist = dist[x][y] + seats[x2][y2];
				if (newDist < dist[x2][y2] && !inq[x2][y2]){
					dist[x2][y2] = newDist;
					inq[x2][y2] = 1;
					q.push_back({x2, y2});
				}
			}
		}
	}
}
