#define MOD 1000000007LL
#define HMAX 500

int N;
vector<int> P;
int mhate[500][500];
bool sheet[500][500];
ll ans;

void update(int x, int y) {
  int nh;

  if (x<0 || x>=N || y<0 || y>=N) return;
  nh = mhate[x][y];
//printf("update(%d,%d)\n", x, y);

  if (x>0) {
    if (mhate[x-1][y] + sheet[x-1][y] < mhate[x][y]) {
      nh = min(mhate[x-1][y] + sheet[x-1][y], nh);
    }
  }
  if (x<N-1) {
    if (mhate[x+1][y] + sheet[x+1][y] < mhate[x][y]) {
      nh = min(mhate[x+1][y] + sheet[x+1][y], nh);
    }
  }
  if (y>0) {
    if (mhate[x][y-1] + sheet[x][y-1] < mhate[x][y]) {
      nh = min(mhate[x][y-1] + sheet[x][y-1], nh);
    }
  }
  if (y<N-1) {
    if (mhate[x][y+1] + sheet[x][y+1] < mhate[x][y]) {
      nh = min(mhate[x][y+1] + sheet[x][y+1], nh);
    }
  }
  if (nh < mhate[x][y]) {
//printf(" mhate[%d][%d] = %d -> %d\n", x, y, mhate[x][y], nh);
    mhate[x][y] = nh;
    update(x-1, y);update(x+1, y);update(x, y-1);update(x, y+1);
  }
}

void out(int o) {
  int x,y;

  //席o(座標(x,y))の人がいなくなった場合の座席のコスト変化

  x = (o-1)/N; y= (o-1)%N;

  ans += mhate[x][y];    //その席のコストが結果に加算される
//printf("out(%d) %d %lld\n", o, mhate[x][y], ans);
  sheet[x][y] = false;  //その席を空席にする

  //退席した人の前の人
  update(x-1, y);
  //退席した人の左の人
  update(x, y-1);
  //退席した人の後ろの人
  update(x+1, y);
  //退席した人の右の人
  update(x, y+1);
  update(x, y);
}

int main()
{

  cin >> N;
  P.resize(N*N);
  for (int i=0; i<N*N; i++) {
    cin >> P[i];
    mhate[i/N][i%N]=min(min(i/N,N-i/N-1),min(i%N, N-i%N-1));
    sheet[i/N][i%N] = 1;
  }

  for (int i=0; i<N*N; i++) {
    out(P[i]);
  }


  cout << ans << endl;
  return 0;
}

