const ll MAX_N = 200005;
bool okay = false;
ll answer = 0;
ll n;
ll w, h;
ll dist[505][505];
bool occupied[505][505];

void update(ll x, ll y, ll val){
    chmin(dist[x][y], val);
    queue<pl> q;
    q.push({x, y});

    while(!q.empty()){
        auto tmp = q.front(); q.pop();
        ll x_cur = tmp.e1, y_cur = tmp.e2;
        rep(i, 4){
            ll x_nxt = x_cur + dirs[i].x;
            ll y_nxt = y_cur + dirs[i].y;
            if (y_nxt < 0 || y_nxt >= n || x_nxt < 0 || x_nxt >= n)
                continue;
            ll d_cur = dist[x_cur][y_cur];
            if (occupied[x_cur][y_cur]) d_cur++;
            if (dist[x_nxt][y_nxt] > d_cur) 
                dist[x_nxt][y_nxt] = d_cur, q.push({x_nxt, y_nxt});
        }
    }

}

void solve(){
    rep(x, n) rep(y, n){
        dist[x][y] = min({y, n - 1 - y, x, n - 1 - x});
        occupied[x][y] = true;
    }

    rep(i, n * n){
        ll num; in1(num); num--;
        ll x = num % n, y = num / n;
        answer += dist[x][y];
        occupied[x][y] = false;
        update(x, y, dist[x][y]);
    }
    prl(answer);
}

int main(void){
    in1(n);
