int n, a[N * N], v[N * N];
int d[N][N];
bool vis[N][N];
ll ans = 0;
int Idx(int x, int y) { return (x - 1) * n + y; }
void Bfs(int sx, int sy)
{
	int now = v[ Idx(sx, sy) ];
	queue<pii> q;
	q.push( mp(sx, sy) );
	while(!q.empty())
	{
		int x = q.front().first, y = q.front().second; q.pop();
		vis[x][y] = 0;
		for(int i = 0; i < 4; i++)
		{
			int nx = x + dir[i][0], ny = y + dir[i][1];
			if(nx < 1 || nx > n || ny < 1 || ny > n) continue;
			int t = v[ Idx(x, y) ] > now;
			if(d[x][y] + t < d[nx][ny])
			{
				d[nx][ny] = d[x][y] + t;
				if (!vis[nx][ny])
					vis[nx][ny] = 1, q.push( mp(nx, ny) );
			}
		}
	}
}
