void dfs(int cx, int cy, int c, vector<vector<int>> &cost, const vector<vector<bool>> &used, bool isFirst) {
    if (!isFirst && cost[cx][cy] <= c) return;
    cost[cx][cy] = c;
    int N = (int)cost.size();
    for (int i=0; i<4; ++i) {
        int nx = cx + dx[i], ny = cy + dy[i];
        if (nx < 0 || N <= nx || ny < 0 || N <= ny) continue;
        if (used[cx][cy]) dfs(nx, ny, c, cost, used, false);
        else dfs(nx, ny, c+1, cost, used, false);
    }
}

void solve() {
    int N;
    cin >> N;
    vector<int> p(N*N);
    for (int i=0; i<N*N; ++i) {
        cin >> p[i];
        --p[i];
    }

    vector<vector<int>> cost(N, vector<int>(N));
    vector<vector<bool>> used(N, vector<bool>(N, false));
    for (int i=0; i<N; ++i) {
        for (int j=0; j<N; ++j) {
            cost[i][j] = min({i, j, N-1-i, N-1-j});
        }
    }
    int res = 0;
    for (int i=0; i<N*N; ++i) {
        int x = p[i] / N, y = p[i] % N;
        res += cost[x][y];
        used[x][y] = true;
        dfs(x, y, cost[x][y], cost, used, true);
    }
    cout << res << '\n';
}

