inline bool isin(int x, int y) {
  return x >= 0 && y >= 0 && x < n && y < n;
}

void dfs(int x, int y) {
  for (int i = 0; i < 4; i++) {
    int tx = x + dx[i], ty = y + dy[i];
    if (isin(tx, ty) && dist[x][y] + occ[x][y] < dist[tx][ty]) {
      dist[tx][ty] = dist[x][y] + occ[x][y];
      dfs(tx, ty);
    }
  }
}

