const int MAX = 505;
int N;
int qs[MAX * MAX];
int ans[MAX][MAX];
set<pii> neighs[MAX][MAX];

pii ToPosition(int p) {
  p--;
  return {p / N, p % N};
}

int ToIndex(int x, int y) { return x * N + y; }

bool Okay(int x, int y) { return x >= 0 && x < N && y >= 0 && y < N; }

int dx[] = {0, -1, 0, 1};
int dy[] = {-1, 0, 1, 0};

unordered_set<int> bio;

void dfs(int x, int y) {
  for (auto it = neighs[x][y].begin(); it != neighs[x][y].end(); it++) {
    int nx = it->first;
    int ny = it->second;
    if (!Okay(nx, ny)) continue;
    if (bio.find(ToIndex(nx, ny)) != bio.end()) continue;
    if (ans[nx][ny] != ans[x][y] + 1) continue;
    bio.insert(ToIndex(nx, ny));
    dfs(nx, ny);
  }
  ans[x][y]--;
}

void Update(int x, int y) {
  // cout << "updating: " << x << " " << y << endl;
  bio.clear();
  dfs(x, y);
  ans[x][y] = 0;

  // for (int i = 0; i < N; i++) {
  //   for (int j = 0; j < N; j++) {
  //     printf("%d ", ans[i][j]);
  //   }
  //   printf("\n");
  // }
  // printf("\n");
  for (auto it = neighs[x][y].begin(); it != neighs[x][y].end(); it++) {
    for (auto it2 = neighs[x][y].begin(); it2 != neighs[x][y].end(); it2++) {
      if (it->first == it2->first && it->second != it2->second) {
        neighs[it->first][it->second].erase(make_pair(x, y));
        neighs[it2->first][it2->second].erase(make_pair(x, y));
        neighs[it->first][it->second].insert(
            make_pair(it2->first, it2->second));
        neighs[it2->first][it2->second].insert(
            make_pair(it->first, it->second));
      } else if (it->first != it2->first && it->second == it2->second) {
        neighs[it->first][it->second].erase(make_pair(x, y));
        neighs[it2->first][it2->second].erase(make_pair(x, y));
        neighs[it->first][it->second].insert(
            make_pair(it2->first, it2->second));
        neighs[it2->first][it2->second].insert(
            make_pair(it->first, it->second));
      }
    }
  }
}

int main() {
  cin >> N;
  for (int i = 0; i < N * N; i++) {
    scanf("%d", qs + i);
  }

  for (int i = 0; i < N; i++) {
    for (int j = 0; j < N; j++) {
      ans[i][j] = min(min(i, j), min(N - 1 - i, N - 1 - j));
      for (int dd = 0; dd < 4; dd++) {
        int nx = dx[dd] + i;
        int ny = dy[dd] + j;
        if (!Okay(nx, ny)) continue;
        neighs[i][j].insert({nx, ny});
      }
    }
  }

  ll sum = 0;
  for (int i = 0; i < N * N; i++) {
    pii pos = ToPosition(qs[i]);
    sum += ans[pos.first][pos.second];
    Update(pos.first, pos.second);
  }

  cout << sum << endl;

  return 0;
}

#include <bits/stdc++.h>
using namespace std;

typedef long long ll;
typedef pair<int, int> pii;
typedef pair<ll, ll> pll;

const int MAXN = 500;
const int INF = 987654321;

int N, A[MAXN+10][MAXN+10], P[MAXN*MAXN+10];
int U[MAXN+10][MAXN+10], D[MAXN+10][MAXN+10], L[MAXN+10][MAXN+10], R[MAXN+10][MAXN+10];

ll ans;

int main()
{
	int i, j, k;

	scanf("%d", &N);
	for(i=1; i<=N*N; i++) scanf("%d", &P[i]);

	for(i=1; i<=N; i++) for(j=1; j<=N; j++) A[i][j]=min({i-1, N-i, j-1, N-j})+1;
	for(i=0; i<=N+1; i++) for(j=0; j<=N+1; j++)
	{
		U[i][j]=min(N+1, i+1);
		D[i][j]=max(0, i-1);
		L[i][j]=max(0, j-1);
		R[i][j]=min(j+1, N+1);
	}

	for(i=1; i<=N*N; i++)
	{
		int y=(P[i]-1)/N+1, x=(P[i]-1)%N+1;
		ans+=A[y][x]-1;

		D[U[y][x]][x]=D[y][x];
		U[D[y][x]][x]=U[y][x];
		L[y][R[y][x]]=L[y][x];
		R[y][L[y][x]]=R[y][x];

		queue<pii> Q;
		if(U[y][x]<=N) Q.push({U[y][x], x});
		if(D[y][x]>=1) Q.push({D[y][x], x});
		if(L[y][x]>=1) Q.push({y, L[y][x]});
		if(R[y][x]<=N) Q.push({y, R[y][x]});

		while(!Q.empty())
		{
			int y=Q.front().first, x=Q.front().second; Q.pop();

			int val=min({A[D[y][x]][x], A[U[y][x]][x], A[y][L[y][x]], A[y][R[y][x]]})+1;
			if(A[y][x]<=val) continue;
			A[y][x]=val;

			if(U[y][x]<=N) Q.push({U[y][x], x});
			if(D[y][x]>=1) Q.push({D[y][x], x});
			if(L[y][x]>=1) Q.push({y, L[y][x]});
			if(R[y][x]<=N) Q.push({y, R[y][x]});
		}
		A[y][x]=-1;
	}
	printf("%lld\n", ans);
}

