// [l, r) from l to r
struct range {
  struct itr {
    int i;
    constexpr itr(int i_): i(i_) { }
    constexpr void operator ++ () { ++i; }
    constexpr int operator * () const { return i; }
    constexpr bool operator != (itr x) const { return i != x.i; }
  };
  const itr l, r;
  constexpr range(int l_, int r_): l(l_), r(std::max(l_, r_)) { }
  constexpr itr begin() const { return l; }
  constexpr itr end() const { return r; }
};

// [l, r) from r to l
struct revrange {
  struct itr {
    int i;
    constexpr itr(int i_): i(i_) { }
    constexpr void operator ++ () { --i; }
    constexpr int operator * () const { return i; }
    constexpr bool operator != (itr x) const { return i != x.i; }
  };
  const itr l, r;
  constexpr revrange(int l_, int r_): l(l_ - 1), r(std::max(l_, r_) - 1) { }
  constexpr itr begin() const { return r; }
  constexpr itr end() const { return l; }
};

constexpr int dx[] = { 1, 0, -1, 0 };
constexpr int dy[] = { 0, 1, 0, -1 };

int main() {
  int N;
  std::cin >> N;
  std::vector<int> R(N * N), C(N * N);
  for (int i: range(0, N * N)) {
    int x;
    std::cin >> x;
    --x;
    R[i] = x / N;
    C[i] = x % N;
  }
  std::vector<std::vector<int>> dist(N, std::vector<int>(N));
  for (int i: range(0, N)) {
    for (int j: range(0, N)) {
      dist[i][j] = std::min({ i, j, N - i - 1, N - j - 1 });
    }
  }
  std::vector<std::vector<bool>> exist(N, std::vector<bool>(N, true));
  int ans = 0;
  for (int k: range(0, N * N)) {
    ans += dist[R[k]][C[k]];
    exist[R[k]][C[k]] = false;
    std::deque<std::pair<int, int>> que;
    que.emplace_back(R[k], C[k]);
    while (!que.empty()) {
      auto [x, y] = que.front();
      que.pop_front();
      if (exist[x][y]) {
        for (int l: range(0, 4)) {
          int nx = x + dx[l];
          int ny = y + dy[l];
          if (nx >= 0 && ny >= 0 && nx < N && ny < N && chmin(dist[nx][ny], dist[x][y] + 1)) {
            que.emplace_back(nx, ny);
          }
        }
      }
      else {
        for (int l: range(0, 4)) {
          int nx = x + dx[l];
          int ny = y + dy[l];
          if (nx >= 0 && ny >= 0 && nx < N && ny < N && chmin(dist[nx][ny], dist[x][y])) {
            que.emplace_front(nx, ny);
          }
        }
      }
    }
  }
  std::cout << ans << '\n';
  return 0;
}

