const int dx[4] = {1, -1, 0, 0};
const int dy[4] = {0, 0, 1, -1};

ll n;
Vec2<ll> board;
Vec2<bool> sit;

bool inBoard(ll x, ll y){
	return x >= 0 && x < n && y >= 0 && y < n;
}

void dfs(ll x, ll y, ll c){
	if (!inBoard(x, y)) return;
	if(chmin(board[x][y], c)){
		rep(i, 4) dfs(x + dx[i], y + dy[i], c + sit[x][y]);
	}
}

int main(void){
	cin >> n;
	board.resize(n);
	rep(i, n) board[i].resize(n, INF);
	sit.resize(n);
	rep(i, n) sit[i].assign(n, true);
	Vec p(n * n);
	rep(i, n * n) cin >> p[i];
	rep(i, n * n) --p[i];

	rep(i, n){
		rep(j, n){
			chmin(board[i][j], i);
			chmin(board[i][j], j);
			chmin(board[i][j], n - 1 - i);
			chmin(board[i][j], n - 1 - j);
		}
	}

	ll ans = 0;
	rep(i, n * n){
		ll x = p[i] / n, y = p[i] % n;
		ans += board[x][y];
		sit[x][y] = false;
		rep(j, 4) dfs(x + dx[j], y + dy[j], board[x][y]);
		//co({i, board[2][2]});
	}
	co(ans);

	return 0;
}

