int n , dis[N][N];
bool mark[N][N];

inline bool chk( int x , int y ) {
  if( x < 1 || y < 1 || x > n || y > n ) return false;
  return true;
}

inline int ID( int x , int y ) { 
  return ( x - 1 ) * n + y;
}

const int dir[2][4] = { { 0 , 0 , 1 , -1 } , { 1 , -1 , 0 , 0 } };

void upd( int x , int y ) {
  static pii que[N * N];
  static int he , ta;
  --dis[x][y];
  mark[x][y] = 0;
  que[he = ta = 1] = pii( x , y );
  while( he <= ta ) {
    x = que[he].fi , y = que[he].se; ++he;
    for( int k = 0 , nx , ny ; k < 4 ; ++k )
      if( chk( nx = x + dir[0][k] , ny = y + dir[1][k] ) ) {
        if( dis[nx][ny] > dis[x][y] + mark[nx][ny] ) {
          dis[nx][ny] = dis[x][y] + mark[nx][ny];
          que[++ta] = pii( nx , ny );
        }
      }
  }
}

