  _w = scanf("%d",&n);
  int m = n * n;
  for( int i = 1 ; i <= n ; ++i )
    for( int j = 1 ; j <= n ; ++j ) 
      dis[i][j] = min( min( i , j ) , min( n - i + 1 , n - j + 1 ) ) , mark[i][j] = 1;
  int x , y , id;
  long long ans = 0;
  while( m-- ) {
    _w = scanf("%d",&id);
    x = ( id - 1 ) / n + 1;
    y = ( id - 1 ) % n + 1;
    ans += dis[x][y] - 1;
    upd( x , y );
  }
  printf("%lld",ans);
  return 0;
}

