const int MAX = 505;
int alive[MAX][MAX];
int dp[MAX][MAX];

signed main(){
  cin.tie(0);
  ios::sync_with_stdio(0);

  int n;
  cin>>n;
  auto ps=read(n*n);
  for(int &p:ps) p--;

  for(int i=0;i<n;i++){
    for(int j=0;j<n;j++){
      alive[i][j]=1;
      dp[i][j]=min({i,j,n-1-i,n-1-j});
    }
  }

  int dy[]={0,0,1,-1};
  int dx[]={1,-1,0,0};
  auto in=[&](int y,int x){return 0<=y and y<n and 0<=x and x<n;};

  auto bfs=[&](int y,int x){
    using P = pair<int, int>;
    queue<P> que;
    alive[y][x]=0;
    que.emplace(y,x);
    while(!que.empty()){
      auto [y,x]=que.front();que.pop();
      for(int k=0;k<4;k++){
        int ny=y+dy[k],nx=x+dx[k];
        if(!in(ny,nx)) continue;
        int nd=dp[y][x]+alive[y][x];
        if(dp[ny][nx]>nd){
          dp[ny][nx]=nd;
          que.emplace(ny,nx);
        }
      }
    }
  };

  int ans=0;
  for(int p:ps){
    ans+=dp[p/n][p%n];
    bfs(p/n,p%n);
  }
  cout<<ans<<newl;
  return 0;
}

