    ll td=q.front().second;
    q.pop();
    if(d[id]>-1) continue;
    d[id]=td;
    if(id+1<n*n) q.push({id+1,td+1});
    if(id-1>-1) q.push({id-1,td+1});
    if(id+n<n*n) q.push({id+n,td+1});
    if(id-n>-1) q.push({id-n,td+1});
  }
  ll ans=0;
  set<ll> al;
  for(ll i=0;i<n*n;i++) {
    ll id=p[i];
    ans+=d[id];
    q.push({id,d[id]-1});
    while(q.size()) {
      ll tid=q.front().first;
      ll td=q.front().second;
      q.pop();
      if(td>=d[tid]) continue;
      if(!al.count(tid)) {
        d[tid]=td;
        td++;
      }
      else al.insert(tid);
      if(tid+1<n*n) q.push({tid+1,td});
      if(tid-1>-1) q.push({tid-1,td});
      if(tid+n<n*n) q.push({tid+n,td});
      if(tid-n>-1) q.push({tid-n,td});
    }
    al.insert(id);
    d[id]++;
  }
  cout << ans << endl;
}

