const int INF = 1e18;
constexpr pii offs[] = {{-1,0},{0,1},{1,0},{0,-1}};

vvi d;
vvi occ;

void propdists(int i, int j) {
  for (const pii& off : offs) {
    int ii = i+off.first;
    int jj = j+off.second;
    if (ii<0 || ii>=d.size() || jj<0 || jj>=d.size())
      continue;
    if (d[ii][jj] > d[i][j] + occ[i][j]) {
      d[ii][jj] = d[i][j] + occ[i][j];
      propdists(ii,jj);
    }
  }
}

void initdists() {
  const int n = d.size();
  for (int i=0; i<n; ++i) {
    d[i][0] = 0;
    propdists(i,0);
    d[i][n-1] = 0;
    propdists(i,n-1);
  }
  for (int j=1; j<n-1; ++j) {
    d[0][j] = 0;
    propdists(0,j);
    d[n-1][j] = 0;
    propdists(n-1,j);
  }
}

void unitestuff(int i, int j) {
  for (const pii& off : offs) {
    int ii = i + off.first;
    int jj = j + off.second;
    if (ii<0 || ii>=d.size() || jj<0 || jj>=d.size())
      continue;
    if (d[ii][jj] > d[i][j]) {
      d[ii][jj] = d[i][j];
      propdists(ii,jj);
    }
  }
}

