int main(){
  cin.tie(0); // cut the cin and cout (default, std::flush is performed after std::cin)
  ios::sync_with_stdio(false); // cut the iostream and stdio (DON'T endl; BUT "\n";)

  ll N;
  IN(N);
  vpll P(N*N);
  REP(i,N*N){
    ll p;
    IN(p);
    p--;
    P[i].first = p/N;
    P[i].second = p%N;
  }

  vvll Cost(N, vll(N, 0));
  REP(i,N) REP(j,N){
    Cost[i][j] = min(min(i, N-1-i), min(j, N-1-j));
  }

  vvll exists(N, vll(N, 1));

  ll ans = 0;
  REP(i,N*N){
    ll x = P[i].first;
    ll y = P[i].second;
    ans += Cost[x][y];
    exists[x][y] = 0;

    queue<pair<ll, ll>> que;
    que.push(make_pair(x-1, y));
    que.push(make_pair(x+1, y));
    que.push(make_pair(x, y-1));
    que.push(make_pair(x, y+1));

    while(que.size()){
      auto pos_tmp = que.front(); que.pop();
      ll x_tmp = pos_tmp.first;
      ll y_tmp = pos_tmp.second;
      if(x_tmp<=0 || x_tmp>=N-1 || y_tmp<=0 || y_tmp>=N-1) continue;
      ll New_Cost = INFLL;
      chmin(New_Cost, Cost[x_tmp-1][y_tmp] + exists[x_tmp-1][y_tmp]);
      chmin(New_Cost, Cost[x_tmp+1][y_tmp] + exists[x_tmp+1][y_tmp]);
      chmin(New_Cost, Cost[x_tmp][y_tmp-1] + exists[x_tmp][y_tmp-1]);
      chmin(New_Cost, Cost[x_tmp][y_tmp+1] + exists[x_tmp][y_tmp+1]);
      if(New_Cost>=Cost[x_tmp][y_tmp]) continue;

      Cost[x_tmp][y_tmp] = New_Cost;

      que.push(make_pair(x_tmp-1, y_tmp));
      que.push(make_pair(x_tmp+1, y_tmp));
      que.push(make_pair(x_tmp, y_tmp-1));
      que.push(make_pair(x_tmp, y_tmp+1));
    }
  }

  OUT(ans);

  return 0;
}

