ll lazyr[sz][sz];
ll treer[sz][sz];
ll lazyc[sz][sz];
ll treec[sz][sz];
void updater(int row,int node, int start, int end, int l, int r, int val)
{
    if(lazyr[row][node] != 0)
    { 
        // This node needs to be updated
        treer[row][node] += (end - start + 1) * lazyr[row][node] ;    // Update it
        if(start != end)
        {
            lazyr[row][node*2]  += lazyr[row][node] ;                  // Mark child as lazy
            lazyr[row][2*node+1]  += lazyr[row][node] ;                // Mark child as lazy
        }
        lazyr[row][node]  = 0;                                  // Reset it
    }
    if(start > end or start > r or end < l)              // Current segment is not within range [l, r]
        return;
    if(start >= l and end <= r)
    {
        // Segment is fully within range
        treer[row][node] += (end - start + 1) * val;
        if(start != end)
        {
            // Not leaf node
            lazyr[row][node*2] += val;
            lazyr[row][2*node+1] += val;
        }
        return;
    }
    int mid = (start + end) / 2;
    updater(row,node*2, start, mid, l, r, val);        // Updating left child
    updater(row,node*2 + 1, mid + 1, end, l, r, val);   // Updating right child
    treer[row][node] = treer[row][node*2] + treer[row][node*2+1];        // Updating root with max value 
}

void updatec(int col,int node, int start, int end, int l, int r, int val)
{
    if(lazyc[col][node] != 0)
    { 
        // This node needs to be updated
        treec[col][node] += (end - start + 1) * lazyc[col][node] ;    // Update it
        if(start != end)
        {
            lazyc[col][node*2]  += lazyc[col][node] ;                  // Mark child as lazy
            lazyc[col][2*node+1]  += lazyc[col][node] ;                // Mark child as lazy
        }
        lazyc[col][node]  = 0;                                  // Reset it
    }
    if(start > end or start > r or end < l)              // Current segment is not within range [l, r]
        return;
    if(start >= l and end <= r)
    {
        // Segment is fully within range
        treec[col][node] += (end - start + 1) * val;
        if(start != end)
        {
            // Not leaf node
            lazyc[col][node*2] += val;
