    updatec(col,node*2, start, mid, l, r, val);        // Updating left child
    updatec(col,node*2 + 1, mid + 1, end, l, r, val);   // Updating right child
    treec[col][node] = treec[col][node*2] + treec[col][node*2+1];        // Updating root with max value 
}


int queryr(int row,int node, int start, int end, int l, int r)
{
    if(start > end or start > r or end < l)
        return 0;         // Out of range
    if(lazyr[row][node] != 0)
    {
        // This node needs to be updated
        treer[row][node] += (end - start + 1) * lazyr[row][node];            // Update it
        if(start != end)
        {
            lazyr[row][node*2] += lazyr[row][node];         // Mark child as lazy
            lazyr[row][node*2+1] += lazyr[row][node];    // Mark child as lazy
        }
        lazyr[row][node] = 0;                 // Reset it
    }
    if(start >= l and end <= r)             // Current segment is totally within range [l, r]
        return treer[row][node];
    int mid = (start + end) / 2;
    int p1 = queryr(row,node*2, start, mid, l, r);         // Query left child
    int p2 = queryr(row,node*2 + 1, mid + 1, end, l, r); // Query right child
    return (p1 + p2);
}

int queryc(int col,int node, int start, int end, int l, int r)
{
    if(start > end or start > r or end < l)
        return 0;         // Out of range
    if(lazyc[col][node] != 0)
    {
        // This node needs to be updated
        treec[col][node] += (end - start + 1) * lazyc[col][node];            // Update it
        if(start != end)
        {
            lazyc[col][node*2] += lazyc[col][node];         // Mark child as lazy
            lazyc[col][node*2+1] += lazyc[col][node];    // Mark child as lazy
        }
        lazyc[col][node] = 0;                 // Reset it
    }
    if(start >= l and end <= r)             // Current segment is totally within range [l, r]
        return treec[col][node];
    int mid = (start + end) / 2;
    int p1 = queryc(col,node*2, start, mid, l, r);         // Query left child
    int p2 = queryc(col,node*2 + 1, mid + 1, end, l, r); // Query right child
    return (p1 + p2);
}
