const int INF = 1001001001;
const int dx[] = {1, 0, -1, 0};
const int dy[] = {0, 1, 0, -1};

void solve() {
  int n;
  cin >> n;
  vi32 p(n * n);
  cin >> p;
  rep(i, n * n) {
    p[i]--;
  }
  vector<vi32> dp(n, vi32(n));
  rep(i, n) rep(j, n) {
    dp[i][j] = min({i, j, n - i - 1, n - j - 1});
  }
  vector<vi32> f(n, vi32(n));
  int ans = 0;
  rep(i, n * n) {
    int x = p[i] % n;
    int y = p[i] / n;
    ans += dp[x][y];
    f[x][y] = 1;
    using T = tuple<int, int, int>;
    queue<T> q;
    rep(k, 4) {
      int nx = x + dx[k];
      int ny = y + dy[k];
      if (nx < 0 || nx >= n || ny < 0 || ny >= n) continue;
      q.emplace(nx, ny, dp[x][y]);
    }
    while (sz(q)) {
      int x, y, cost;
      tie(x, y, cost) = q.front();
      q.pop();
      if (dp[x][y] <= cost) continue;
      dp[x][y] = cost;
      rep(k, 4) {
        int nx = x + dx[k];
        int ny = y + dy[k];
        if (nx < 0 || nx >= n || ny < 0 || ny >= n) continue;
        q.emplace(nx, ny, cost + (f[x][y] ? 0 : 1));
      }
    }
  }
  cout << ans << endl;
}

