template <typename T>
class fenwick{
	private:
	vector<T> bit;
	int n;
	public:
	fenwick(){
		n=MAX;
		bit.assign(n,{0});
	}
	fenwick(int size){
		n=size;
		bit.assign(n,{0});
	}
	void update(int id, T z){
		while(id<=n){
			bit[id]= bit[id] + z;
			id+=(id & (-id));
		}
	}
	T query(int id){
		T ans=0;
		while(id>0){
			ans= ans + bit[id];
			id-=(id & (-id));
		}
		return ans;
	}
};

signed main(){
	ios_base::sync_with_stdio(false);
	cin.tie(0);cout.tie(0);
	int n,i,j;
	cin>>n;
	vector<fenwick<int> > rows(n+1,fenwick<int>(n+1)),cols(n+1,fenwick<int>(n+1));
	for(i=1;i<=n;i++){
		for(j=1;j<=n;j++){
			rows[i].update(j,1);
			cols[j].update(i,1);
		}
	}
	int ans=0;
	for(i=0;i<n*n;i++){
		int x,r,c;
		cin>>x;
		x--;
		r=x/n+1;
		c=x%n+1;
		// debug(x+1,r,c);
		int nmin=n*n, csum = cols[c].query(r),rsum = rows[r].query(c);
		for(j=1;j<=n;j++){
			int lleft = rows[j].query(c-1),rleft = rows[j].query(c),right = rows[j].query(n);
			int rem = (j<=r?csum-cols[c].query(j):cols[c].query(j)-csum);
			// debug("row:",j);
			// debug(rem,left,right);
			nmin = min(nmin, rem + min(lleft,right-rleft));
		}
		for(j=1;j<=n;j++){
			int lleft = cols[j].query(r-1),rleft = cols[j].query(r),right = cols[j].query(n);
			int rem = (j<=c?rsum-rows[r].query(j):rows[r].query(j)-rsum);
			// debug("col:",j);
			// debug(rem,left,right);
			nmin = min(nmin, rem + min(lleft,right-rleft));
		}
		// debug(nmin);
		ans+=nmin;
		rows[r].update(c,-1);
		cols[c].update(r,-1);
	}
	cout<<ans<<"\n";
	return 0;
}

