  cin >> n;
  vector<LL> p(n * n);
  rep (i, n * n) {
    cin >> p.at(i);
    p.at(i) -= 1;

    //cout << i << " " << is_on_edge(i) << endl;
  }

  if (n <= 2) {
    cout << 0 << endl;
    return 0;
  }

  inuse.assign(n * n, 1);
  cost.assign(n * n, 9999999999L);
  rep (i, n) {
    rep (j, n) {
      cost.at(i * n + j) = min(min(i, n - 1 - i), min(j, n - 1 - j));
    }
  }

  completed.assign(n * n, false);
  LL sum = 0;
  rep (i, n * n) {
//    rep(jj, n) {
//      rep(kk, n) {
//        cout << cost.at(jj * n + kk) << "\t";
//      }
//      cout << endl;
//    }
//    cout << endl;
    sum += cost.at(p.at(i));
    update(p.at(i));
  }
  cout << sum << endl;


  return 0;
  #ifdef DEBUG
