int t[] = {1,0,-1,0,1};
int main(){
	int i,j,x,y,nx,ny;
	read(n),m = n * n;
	for (i = 1; i <= m; ++i) read(p[i]),--p[i];
	for (i = 0; i < n; ++i) for (j = 0; j < n; ++j) a[i][j] = 1,dis[i][j] = min(min(i+1,n-i),min(j+1,n-j))-1;
	for (i = 1; i <= m; ++i){
		x = p[i] / n,y = p[i] % n;
		ans += dis[x][y];
		a[x][y] = 0;
		if (x) Q.push_back(mp(x-1,y)),inq[x-1][y] = 1;
		if (y) Q.push_back(mp(x,y-1)),inq[x][y-1] = 1;
		if (x+1<n) Q.push_back(mp(x+1,y)),inq[x+1][y] = 1; 
		if (y+1<n) Q.push_back(mp(x,y+1)),inq[x][y+1] = 1;
		Q.push_back(mp(x,y)),inq[x][y] = 1;
		while (!Q.empty()){
