		//	cerr<<x<<' '<<y<<' ' << dis[x][y]<<' '<<'\n';
			for (j = 0; j < 4; ++j){
				nx = x+t[j],ny = y+t[j+1];
				if (nx>=0&&ny>=0&&nx<n&&ny<n&&dis[nx][ny] > dis[x][y] + a[x][y]){
					dis[nx][ny] = dis[x][y] + a[x][y];
					if (!inq[nx][ny]){
						if (a[nx][ny]) Q.push_back(mp(nx,ny)); else Q.push_front(mp(nx,ny));
