        for(++k ; k<N ; k+=lsb(k)){
            ft[k]=(ft[k] +delta);
        }
    }

    ll sum(int k){
        ll ans=0;
        for(++k; k ;k-=lsb(k)){
            ans=(ans + ft[k]);
        }
        return ans;
    }

