    }
    if (emp.at(x+1).at(y)) {
        if (kirai.at(x+1).at(y) > kirai.at(x).at(y)) {
            kirai.at(x+1).at(y) = kirai.at(x).at(y);
            update(kirai, emp, x+1, y);
        }
    } else {
        if (kirai.at(x+1).at(y) > kirai.at(x).at(y) + 1) {
            kirai.at(x+1).at(y) = kirai.at(x).at(y) + 1;
            update(kirai, emp, x+1, y);
        }
    }
    return;
}

