int jest[505][505];

void fill() {
	FOR(i,0,n) FOR(j,0,n) dist[i][j] = min(min(i,j), min(n-1-i,n-1-j));
	FOR(i,0,n) FOR(j,0,n) jest[i][j] = 1;
}

VI dx = {1,-1,0,0};
VI dy = {0,0,1,-1};

bool inside(int a, int b) {
	return (a>=0 && b>=0 && a<n && b<n);
}

int compute(int x, int y) {
	int ans = dist[x][y];
	FOR(i,0,4) {
			int nx = x + dx[i];
			int ny = y + dy[i];
			if (!inside(nx, ny)) return 0;
			ans = min(ans, dist[nx][ny] + jest[nx][ny]);
	}
	return ans;
}
void update(int x, int y) {
	vector<PII> que;
	que.pb({x,y});
	int pos = 0;
	while (pos < que.size()) {
		int x = que[pos].st;
		int y = que[pos].nd;
		pos++;
		FOR(i,0,4) {
			int nx = x + dx[i];
			int ny = y + dy[i];
			if (!inside(nx, ny)) continue;
			int ndist = compute(nx, ny);
			if (ndist != dist[nx][ny]) {
				dist[nx][ny] = ndist;
				que.pb({nx, ny});
			}
		}
	}
}


