        if(x > 0 && seats[y][x - 1] > seats[y][x] +  1) {
            seats[y][x - 1] = seats[y][x] +  1;
            q.push({y,x - 1});
        }
        if(x < t - 1 && seats[y][x + 1] > seats[y][x] +  1) {
            seats[y][x + 1] = seats[y][x] +  1;
            q.push({y,x + 1});
