bool valid(int j, int i, int N){
  if(j < 0 || j>=N)
    return false;
  else if(i < 0 || i>= N)
    return false;
  else
    return true;
}

int main(){
  int N;
  cin >> N;
  vector<int> P(N*N);
  int ans = 0;
  for(int i=0;i<N*N;i++)
    cin >> P.at(i);
  vector<int> score(N*N);
  vector<bool> end(N*N, false);
  for(int i=0;i<N;i++){
    for(int j=0;j<N;j++){
      score.at(j*N+i) = min(min(j,N-j-1),min(i,N-i-1));
    }
  }
  int jval[4] = {0,0,1,-1};
  int ival[4] = {1,-1,0,0};
  int m[4] = {1,-1,N,-N};
  queue<int> que;
  for(int i=0;i<N*N;i++){
