  UnionFind uf(n * n);
  rep(i, n) rep(j, n) {
    int mi = min({i, n - i - 1, j, n - j - 1});
    uf.minv[b[i][j]] = mi;
  }
  i64 ans = 0;
  rep(i, n * n) {
    int x = p[i] % n;
