struct dsu {
	ll n;
	vl p, dist;

	dsu(ll n): n(n), p(n), dist(n) {
		iota(all(p),0);
	}

	ll find(ll x) {
		if (x == p[x]) return x;
		return p[x] = find(p[x]);
	}

	bool unite(ll x, ll y) {
		x = find(x), y = find(y);
		if (x == y) return false;

		if (rand()&1) swap(x,y);
		p[y] = x;
		dist[x] = min(dist[x], dist[y]);
		return true;
	}
};

