void update(int x_now, int y_now) {
    int value = dis[x_now][y_now];
    dis[x_now][y_now]--;
    rep(j, 4) {
        int x_next = x_now + x_ar[j], y_next = y_now + y_ar[j];
        if (x_next < 0 || n <= x_next || y_next < 0 || n <= y_next) {
            continue;
        }
        if (dis[x_next][y_next] == value + remain[x_next][y_next]) {
            update(x_next, y_next);
        }
    }
}

