#define SEG_LEN (1 << 9)

ll seg[2][500][SEG_LEN*2];

void add(ll ind1, ll ind2,ll ind,ll v){
    ind += SEG_LEN;
    seg[ind1][ind2][ind] += v;
    while(1){
        ind /= 2;
        if(ind <= 0) break;
        seg[ind1][ind2][ind] = seg[ind1][ind2][ind*2] + seg[ind1][ind2][ind*2+1];
    }
    return;
}

ll sum(ll ind1, ll ind2,ll l, ll r){
    l += SEG_LEN; r += SEG_LEN;
    ll res = 0;
    while(l < r){
        if(l % 2 == 1){
            res += seg[ind1][ind2][l];
            l++;
        }
        l /= 2;

        if(r % 2 == 1){
            res += seg[ind1][ind2][r-1];
            r--;
        }
        r /= 2;
    }
    return res;
}


