    queue<pair<int, int> > q;
    q.push(make_pair(x, y));
    while (!q.empty())
    {
        pair<int, int> tmp = q.front();
        q.pop();
        int xx = tmp.first, yy = tmp.second;
        for (int i = 0; i < 4; i++)
        {
            int tx = xx + dx[i], ty = yy + dy[i];
            if (tx < 1 || tx > n || ty < 1 || ty > n || dis[xx][yy] + f[xx][yy] >= dis[tx][ty])
            {
                continue;
            }
            dis[tx][ty] = dis[xx][yy] + f[xx][yy];
            q.push(make_pair(tx, ty));
        }
    }
}
