            f[i][j] = 1;
        }
    }
    long long ans = 0;
    for (int i = 1; i <= n * n; i++)
    {
        int x = (a[i] - 1) / n + 1, y = a[i] % n ? a[i] % n : n;
        ans += dis[x][y];
        f[x][y] = 0;
        bfs(x, y);
    }
    printf("%lld", ans);
    return 0;
}

