using namespace std;

const int maxn = 510;

const int inf = 1 << 29;

typedef pair<int,int> II;

int f[maxn][maxn];

int a[maxn * maxn];

int t[maxn][maxn];

bool mark[maxn][maxn];


const int hi[4] = {1, -1, 0, 0};
const int hj[4] = {0, 0, 1, -1};

int main() {
	ios::sync_with_stdio(false);
	cin.tie(0);

	int n = 0;
	cin >> n;

	for(int i = 0; i < n * n; i++) {
		cin >> a[i];
		a[i] --;
		mark[i / n][i % n] = true;
	}

	for(int i = 0 ; i < n; i++) {
		for(int j = 0; j < n; j++) {
			f[i][j] = min(i, min(j, min(n - i - 1, n - j - 1)));
		}
	}


	int res = 0;

	for(int i = 0 ; i < n ; i ++) {
		for(int j =0 ;j<n;j ++) {
			t[i][j] = inf;
		}
	}
	for(int i = 0; i < n * n; i++) {
		int v = a[i];
		int x = v / n;
		int y = v % n;
		res += f[x][y];
		queue<II> q;
		q.push(II(x, y));
		vector<II> vt;
		vt.push_back(II(x, y));
		mark[x][y] = 0;
		t[x][y] = 0;
		while (!q.empty()) {
			II u = q.front();
			q.pop();
			for(int i = 0; i < 4; i++) {
				int x1 = u.first + hi[i];
				int y1 = u.second + hj[i];
				if (x1 >= 0 && y1 >= 0 && x1 < n && y1 < n) {
					if (f[x1][y1] > f[x][y] + t[u.first][u.second]) {
						q.push(II(x1, y1));
						vt.push_back(II(x1, y1));
						f[x1][y1] = f[x][y] + t[u.first][u.second];
						t[x1][y1] = min(t[x1][y1], t[u.first][u.second] + mark[x1][y1]);
					} 
				}
			}
		}
		for(auto p:vt) t[p.first][p.second] = inf;
	}

	cout << res;
	return 0;
}

