    return x * n + y;
}

ll ANS[maxn][maxn];

void dfs(ll x, ll y) {
    for (auto p : go) {
        ll nx = x + p.first, ny = y + p.second;
        if (!in(nx, ny)) {
            continue;
        }
        ll dans = ANS[x][y];
        if (!lft[x][y]) {
            dans++;
        }
        if (dans < ANS[nx][ny]) {
            ANS[nx][ny] = dans;
            dfs(nx, ny);
        }
    }
}

