void dfs1(ll x, ll y){
    //cout << "dfs1" << x << " " << y << endl;
    seats[x][y]--;
    REP(i,4){
        ll nex = x+adj[i][0];
        ll ney = y+adj[i][1];
        if (soon[nex][ney]==1&&seats[nex][ney]==seats[x][y]+1){
