            if((y-1)%n&&!used[y-1])  a[y-n].push_back(y-1);
            if(y%n&&!used[y+1]) a[y-n].push_back(y+1);
            if(y+n<=nn&&!used[y+n]) a[y+n].push_back(y+n);
        }
        if(y+n<=nn&&!used[y+n]){

            if((y-1)%n&&!used[y-1])  a[y+n].push_back(y-1);
            if(y%n&&!used[y+1]) a[y+n].push_back(y+1);
            if (y>=n+1&&!used[y-n]) a[y-1].push_back(y-n);

        }
        if((y-1)%n&&!used[y-1]){

            if (y>=n+1&&!used[y-n]) a[y-1].push_back(y-n);
            if(y+n<=nn&&!used[y+n]) a[y-1].push_back(y+n);
            if(y%n&&!used[y+1]) a[y-1].push_back(y+1);
        }
        if(y%n&&!used[y+1]){

            if (y>=n+1&&!used[y-n]) a[y+1].push_back(y-n);
            if(y+n<=nn&&!used[y+n]) a[y+1].push_back(y+n);
            if((y-1)%n&&!used[y-1])  a[y+1].push_back(y-1);

        }
        queue<int> q;
        q.push(y);
        while(q.size()){
            int x=q.front();
            q.pop();
            if(used[x])
                ref(i,a[x].size()){
                    if(!used[a[x][i-1]]&&c[a[x][i-1]]>c[x]) {
                        c[a[x][i-1]]=c[x];
                    q.push(a[x][i-1]);
                }
            }
            else ref(i,a[x].size()){
                if(!used[a[x][i-1]]&&c[a[x][i-1]]>c[x]+1) {
                        c[a[x][i-1]]=c[x]+1;
                q.push(a[x][i-1]);
                }
            }
        }
    }
    cout<<ans;


    return 0;
