bool setmin(int &x, int y) { return x > y ? x = y, true : false; }

void update(int x, int y) {
    if (setmin(level[x][y - 1], level[x][y] + obst[x][y - 1])) {
        update(x, y - 1);
    }
    if (setmin(level[x][y + 1], level[x][y] + obst[x][y + 1])) {
        update(x, y + 1);
    }
    if (setmin(level[x - 1][y], level[x][y] + obst[x - 1][y])) {
        update(x - 1, y);
    }
    if (setmin(level[x + 1][y], level[x][y] + obst[x + 1][y])) {
        update(x + 1, y);
    }
}

