    scanf("%d", &N);
    for (int i = 1; i <= N; i++) {
        for (int j = 1; j <= N; j++) {
            level[i][j] = min(min(i, N + 1 - i), min(j, N + 1 - j));
            obst[i][j] = 1;
        }
    }
    for (int i = 1; i <= N * N; i++) {
        int p; scanf("%d", &p);
        int x = (p - 1) / N + 1, y = (p - 1) % N + 1;
        obst[x][y] = 0;
        level[x][y] = min(min(level[x - 1][y], level[x + 1][y]), min(level[x][y - 1], level[x][y + 1]));
