void dfs(ll N, ll x, ll y, vvll &cost, const vvb &m){
    ll t = cost[x][y];
    if(m[x][y]){t++;}
    if(0<=x-1){
        if(cost[x-1][y] > t){
            cost[x-1][y] = t;
            dfs(N, x-1, y, cost, m);
        }
    }
    if(0<=y-1){
        if(cost[x][y-1] > t){
            cost[x][y-1] = t;
            dfs(N, x, y-1, cost, m);
        }
    }
    if(x+1<N){
        if(cost[x+1][y] > t){
            cost[x+1][y] = t;
            dfs(N, x+1, y, cost, m);
        }
    }
    if(y+1<N){
        if(cost[x][y+1] > t){
            cost[x][y+1] = t;
            dfs(N, x, y+1, cost, m);
        }
    }
}

