    }
    void update() {
        int v = value() + 1;
        U = min(v, U);
        D = min(v, D);
        R = min(v, R);
        L = min(v, L);
    }
    bool valid() {
        int v = value();
        if(is_same) {
            if(U - v > 0 || D - v > 0 || R - v > 0 || L - v > 0) return false;
        }
        if(U - v > 1 || D - v > 1 || R - v > 1 || L - v > 1) return false;
        return true;
    }
};

int N;

// U, D, L, R
int dx[4] = {0, 0, -1, 1};
int dy[4] = {-1, 1, 0, 0};

bool is_in(int r, int c, int i) {
    return r + dy[i] >= 0 && r + dy[i] < N && c + dx[i] >= 0 && c + dx[i] < N;
}

void dfs(int r, int c, vector<vector<cell>> &A) {
    A[r][c].update();
    if(A[r][c].is_same) A[r][c].same();
    // U
    if(is_in(r, c, 0)) A[r + dy[0]][c + dx[0]].D = A[r][c].U;
    if(is_in(r, c, 1)) A[r + dy[1]][c + dx[1]].U = A[r][c].D;
    if(is_in(r, c, 2)) A[r + dy[2]][c + dx[2]].R = A[r][c].L;
    if(is_in(r, c, 3)) A[r + dy[3]][c + dx[3]].L = A[r][c].R;


    rep(i, 4) {
        if(r + dy[i] >= 0 && r + dy[i] < N && c + dx[i] >= 0 && c + dx[i] < N) {
            if(!A[r + dy[i]][c + dx[i]].valid()) {
                dfs(r + dy[i], c + dx[i], A);
            }
        }
    }
}

