const int N = 505;

int n, a[N][N], ans, par[N * N], cost[N * N];
int dr[] = {-1, 0, 1, 0};
int dc[] = {0, 1, 0, -1};

int find(int x) {
	if (x == par[x]) return x;
	return par[x] = find(par[x]);
}

void merge(int x, int y) {
	x = find(x);
	y = find(y);
	par[x] = y;
	cost[y] = min(cost[x], cost[y]);
}

int f(int r, int c) {
	return (r - 1) * n + c;
}

int main(){
	ios::sync_with_stdio(0);
