	for (int i = 1; i <= n; i++) {
		for (int j = 1; j <= n; j++) {
			a[i][j] = 1;
			cost[f(i, j)] = min(min(i-1, n-i), min(j-1, n-j));
		}
	}
	for (int i = 1; i <= n * n; i++) {
		par[i] = i;
	}
	int x;
	for (int i = 1; i <= n * n; i++) {
		cin >> x;
		int r = (x - 1) / n + 1;
		int c = x - (r - 1) * n;
		int now = cost[find(x)];
		for (int j = 1; j < 4; j++) {
			if (!a[r + dr[j]][c + dc[j]]) {
				now = min(now, cost[find(f(r + dr[j], c + dc[j]))]);
				merge(x, f(r + dr[j], c + dc[j]));
			}
		}
		ans += now;
		a[r][c] = 0;
	}
	cout << ans << "\n";
}

