int main(){
	int n;
	std::cin >> n;
	std::vector<std::vector<int>> seat(n, std::vector<int>(n));
	std::vector<std::vector<int>> me(n, std::vector<int>(n,1)); //自分が退席したら、0
	std::vector<std::pair<int, int>> p(n*n);
	for(int i=0; i<n*n; i++){
		int tmp;
		std::cin >> tmp;
		tmp--;
		p[i].first = tmp/n;
		p[i].second = tmp%n;
	}

	for(int i=0; i<n; i++){
		int yoko = std::min(i, (n-1) - i);
		for(int j=0; j<n; j++){
			int tate = std::min(j, (n-1) - j);
			seat[i][j] = std::min(yoko, tate);
		}
	}


	int ans = 0;
	for(int i=0; i<n*n; i++){
		int x = p[i].first;
		int y = p[i].second;
		//std::cout << i+1 << "回目:" << p[i].first << ", " << p[i].second <<std::endl;
		ans += seat[x][y];
		me[x][y]--;

		// seatの更新
		std::queue<std::pair<int, int>> q;
		q.emplace(x, y);
		while(!q.empty()){
			int x = q.front().first;
			int y = q.front().second;
			q.pop();
			int cost = seat[x][y] + me[x][y];
			for(int i=0; i<4; i++){
