int bfs(int S){
	memset(dist, -1, sizeof dist);
	memset(visited, 0, sizeof visited);
	dist[S] = 0;
	deque<pi> dq;
	dq.push_front({S, 0});
	while (!dq.empty()) {
		int node = dq.front().first;
		int curdist = dq.front().second;
		dq.pop_front();
		if (visited[node]) continue;
		visited[node] = 1;
		dist[node] = curdist;
		for (auto e: adjList[node]) {
			int next_n = e.first;
			int edge_w = e.second;
			if (edge_w == 0){
				dq.push_front({next_n, curdist});
			}
			else{
				dq.push_back({next_n, curdist+1});
			}
		}
	}
	int res = 1e9;
	FOR(i,1,N) res = min(res, dist[i]);
	FOR(i,N*N-N+1,V) res = min(res,dist[i]);
	for (int i=1; i<=V; i+=N) res = min(res, dist[i]);
	for (int i=N; i<=V; i+=N) res = min(res, dist[i]);
	return res;
}

void gen(int i){
	vector<int> nx;
	if (i>N) nx.pb(i-N);
	if (i<N*N-N+1) nx.pb(i+N);
	if (i%N != 1) nx.pb(i-1);
	if (i%N != 0) nx.pb(i+1);
	for (auto j:nx){
		if (active[j]) adjList[i].pb({j,1});
		else adjList[i].pb({j,0});
	}
}

