using namespace std;
int hate(vector<vector<int>> & arr,int r,int c,int n){
    int i=r,j=c,tot=0,res=n;arr[r][c]=-1;
    while(i>=0){if(arr[i][j]>=0){tot++;}i--;}
    res=min(res,tot);
    if(tot==0){return 0;}
    i=r,tot=0;
    while(j>=0){if(arr[i][j]>=0){tot++;}j--;}
    res=min(res,tot);
    if(tot==0){return 0;}
    j=c,tot=0;
    while(j<n){if(arr[i][j]>=0){tot++;}j++;}
    res=min(res,tot);
    if(tot==0){return 0;}
    j=c,tot=0;
    while(i<n){if(arr[i][j]>=0){tot++;}i++;}
    res=min(res,tot);
    if(tot==0){return 0;}
    return res;
}
