    ll mat_y = ((p - 1) / n) + 1;
    // cout << "p: " << p << " mat_x: " << mat_x << " mat_y: " << mat_y << endl;

    cnt += mat[mat_x][mat_y];
    // matを更新する
    update_mat(mat_x, mat_y);
