void upd(int x, int y) {
	if (x - 1 >= 1 && dis[x-1][y] > oc[x-1][y] + dis[x][y]) {
		dis[x-1][y] = oc[x-1][y] + dis[x][y];
		upd(x-1, y);
	}
	if (x + 1 <= n && dis[x+1][y] > oc[x+1][y] + dis[x][y]) {
		dis[x+1][y] = oc[x+1][y] + dis[x][y];
		upd(x+1, y);
	}
	if (y - 1 >= 1 && dis[x][y-1] > oc[x][y-1] + dis[x][y]) {
		dis[x][y-1] = oc[x][y-1] + dis[x][y];
		upd(x, y-1);
	}
	if (y + 1 <= n && dis[x][y+1] > oc[x][y+1] + dis[x][y]) {
		dis[x][y+1] = oc[x][y+1] + dis[x][y];
		upd(x, y+1);
	}
}

