            else if( !visit[ny][nx] && !l_visit[ny][nx])  child->hater = haters+1;

            if( ny >= 0 && nx >= 0 && ny <= n-1 && nx <= n-1){
                if( ny == 0 || nx == 0 || ny == n-1 || nx == n-1 && !l_visit[ny][nx]){
