	}
	else if (k == 3) {
		len = min(lmin(i - 1, j, N, flag, 1) + flag.at(i - 1).at(j), min(lmin(i + 1, j, N, flag, 2) + flag.at(i + 1).at(j), lmin(i, j - 1, N, flag, 3) + flag.at(i).at(j - 1)));
