void solv() {
	cin >> n;
	ll p[500 * 500];
	pll t[500 * 500];
	ll x = 0;
	ll y = 0;
	rep(i, n * n) {
		cin >> p[i];
		p[i]--;
		if (y == n)
		{
			x++;
			y = 0;
		}

		t[i].first = x;
		t[i].second = y;
		y++;
	}
	ll d[510][510];
	ll cost[510][510];
	rep(i, n) {
		rep(j, n) {
			cost[i][j] = 1;
			d[i][j] = min({ i,j,n - i - 1,n - j - 1 });
		}
	}

	ll res = 0;

	rep(i, n* n) {
		ll o = p[i];
		ll cx = t[o].first;
		ll cy = t[o].second;
		cost[cx][cy] = 0;
		res += d[cx][cy];
		queue<tuple<ll, ll, ll>> q;
		q.push(make_tuple(d[cx][cy], cx, cy));

		while (!q.empty())
		{
			auto tu = q.front();
			q.pop();
			auto cs = get<0>(tu);
			cx = get<1>(tu);
			cy = get<2>(tu);

			for (ll j = 0; j < 4; j++) {
				ll tx = cx + dx[j];
				ll ty = cy + dy[j];
				if (tx < 0 || ty < 0 || tx >= n || ty >= n) {
					continue;
				}

				if (d[tx][ty] <= cs + cost[cx][cy]) {
					continue;
				}

				d[tx][ty] = cs + cost[cx][cy];
				q.push(make_tuple(d[tx][ty], tx, ty));
			}
		}
	}
	cout << res << endl;
}





