int seki[503][503] = {0};
int perans = 100000000;
int n;

void solve(int visit[][503], int nowr, int nowc, int count){
  visit[nowr][nowc] = 1;
  //  printf("%d  %d", nowr, nowc);
  if(nowr<=1 || nowr>=n || nowc<=1 || nowc>=n){
    perans = max(perans, count);
    return;
  }

  if(visit[nowr+1][nowc] == 0){
    solve(visit, nowr+1, nowc, count+(seki[nowr+1][nowc]==0));
  }
  if(visit[nowr-1][nowc] == 0){
    solve(visit, nowr-1, nowc, count+(seki[nowr-1][nowc]==0));
  }
  if(visit[nowr][nowc+1] == 0){
    solve(visit, nowr, nowc+1, count+(seki[nowr][nowc+1]==0));
  }
  if(visit[nowr][nowc-1] == 0){
    solve(visit, nowr, nowc-1, count+(seki[nowr][nowc-1]==0));
  }
}

