const int dy[4] = {0, 0, 1, -1};

struct ele {
	int x, y;
	ele (int a = 0, int b = 0) : x(a), y(b) {}
};

queue <ele> q;
int a[N][N], dis[N][N];
int n, ans;

int main() {
	read(n);
	for (int i = 1; i <= n; i++) {
		for (int j = 1; j <= n; j++) {
			dis[i][j] = min(min(i, j), min(n - i + 1, n - j + 1));
			a[i][j] = 1;
		}
	}
	for (int i = 1; i <= n * n; i++) {
		int v, x, y; read(v);
		x = (v - 1) / n + 1; y = (v - 1) % n + 1;
		--dis[x][y]; a[x][y] = 0; ans += dis[x][y]; q.push(ele(x, y));
		while (!q.empty()) {
			ele u = q.front(); q.pop();
			for (int j = 0; j < 4; j++) {
				int _x = u.x + dx[j], _y = u.y + dy[j];
				if (dis[_x][_y] > dis[u.x][u.y] + a[_x][_y]) {
					dis[_x][_y] = dis[u.x][u.y] + a[_x][_y];
					q.push(ele(_x, _y));
				}
			}
		}
	}
	print(ans, '\n');
	return 0;
}

