void arugo(int n,int p,zaseki *z){
    int i,mleft,mright,h;
    z->now[p] = 0; //riseki
    z->front = z->back = z->left = z->right = 0;
    //front
    i = p;
    i = i-n;
    while(i>0){
        if(z->now[i]==1)z->front++;
        i = i-n;   
    }

    //back
    i = p;
    i = i+n;
    while(i<=n*n){
        if(z->now[i]==1)z->back++;
        i = i+n;
    }


    //left
    i = p%n;
    mleft = p - i + 1;
    i = p-1;
    while (i>=mleft)
    {
        if(z->now[i]==1)z->left++;
        i--;
    }

    //right
    i = p%n;
    mright = p + n - i;
    i = p+1;
    while (i<=mright)
    {
        if(z->now[i]==1)z->right++;
        i++;
    }


    h = z->front;
    if(h>z->back)h = z->back;
    else if(h>z->left)h = z->left;
    else if(h>z->right)h = z->right;
