void solve(int visit[][503], int nowr, int nowc, int count, int fr, int fc){
  visit[nowr][nowc] = 1;
  //  printf("%d  %d", nowr, nowc);
  if(nowr<=1 || nowr>=n || nowc<=1 || nowc>=n){
    printf("count : %d\n", count);
    perans = max(perans, count);
    printf("perans : %d\n", perans);
    return;
  }
  int flag = 1;
  if(visit[nowr+1][nowc] == 0){
    flag = 0;
    solve(visit, nowr+1, nowc, count+(seki[nowr+1][nowc]==0), fr, fc);
  }
  if(visit[nowr-1][nowc] == 0){
    flag = 0;
    solve(visit, nowr-1, nowc, count+(seki[nowr-1][nowc]==0), fr, fc);
  }
  if(visit[nowr][nowc+1] == 0){
    flag = 0;
    solve(visit, nowr, nowc+1, count+(seki[nowr][nowc+1]==0), fr, fc);
  }
  if(visit[nowr][nowc-1] == 0){
    flag = 0;
    solve(visit, nowr, nowc-1, count+(seki[nowr][nowc-1]==0), fr, fc);
  }
  if(flag)  return;
}

