void bfs(int stx, int sty) {
	for (int i = 0; i < n; i++) {
		for (int j = 0; j < n; j++) {
			dist[i][j] = -1;
		}
	}
	dist[sty][stx] = 0;
	int vx[4] = {0, 1, -1, 0};
	int vy[4] = {1, 0, 0, -1};
	head = tail = 0;
	qx[head] = stx;
	qy[head] = sty;
	tail++;
	while (tail != head) {
		for (int i = 0; i < 4; i++) {
			int nx = qx[head] + vx[i];
			int ny = qy[head] + vy[i];
			if (0 <= nx && nx < n && 0 <= ny && ny < n && dist[ny][nx] == -1) {
				if (!s[ny][nx])
					dist[ny][nx] = dist[qy[head]][qx[head]];
				else
					dist[ny][nx] = dist[qy[head]][qx[head]] + 1;
				qx[tail] = nx;
				qy[tail] = ny;
				tail++;
			}
		}
		head++;
	}
	return;
}
