fun parseInt(): Int {
    var digit = System.`in`.read()
    while(digit <= 32) {
        digit = System.`in`.read()
    }

    val negative = digit == '-'.toInt()
    if (negative) {
        digit = System.`in`.read()
    }
    var res = 0
    while (digit in '0'.toInt()..'9'.toInt()) {
        res *= 10
        res += digit - '0'.toInt()
        digit = System.`in`.read()
    }
    return if (negative) -res else res
}

fun gcd(x : Int, y : Int) : Int {
    var a = x
    var b = y
    var r = 0
    while(b > 0) {
        r = a % b
        a = b
        b = r
    }
    return a
}

val dl = intArrayOf(-1, 0, 1, 0)
val dc = intArrayOf(0, 1, 0, -1)

fun calc(i : Int, j : Int, dp : Array<IntArray>, rem : Array<BooleanArray>) : Boolean {
    var newVal = Int.MAX_VALUE
    for(k in 0..3) {
        val x = i + dl[k]
        val y = j + dc[k]
        if(0 <= x && x < dp.size && 0 <= y && y < dp[0].size) {
            newVal = min(newVal, dp[x][y] + 1 - (if(rem[x][y]) 1 else 0))
        } else {
            newVal = 0
        }
    }

    if(newVal == dp[i][j]) return false

    dp[i][j] = newVal
    return true
}

