fun PrintWriter.solve() {
    object {
        val n = readInt()
        val P = IntArray(n * n) { readInt() - 1 }

        val occ = Array(n) { BooleanArray(n) { true } }

        var ans = 0

        inline fun forEachNeighbor(i: Int, j: Int, yield: (ni: Int, nj: Int) -> Unit) {
            yield(i-1, j)
            yield(i+1, j)
            yield(i, j-1)
            yield(i, j+1)
        }

        init {
            for(p in P) {
                val pi = p / n
                val pj = p - n * pi
                val vis = Array(n) { BooleanArray(n) }
                occ[pi][pj] = false

                val Q = IntDeque()
                Q.add(pi); Q.add(pj); Q.add(0)

                run l@{
                    while (true) {
                        val i = Q.remove()
                        val j = Q.remove()
                        val c = Q.remove()
                        if(!vis[i][j]) {
                            vis[i][j] = true
                            forEachNeighbor(i, j) { ni, nj ->
                                if (ni !in 0 until n || nj !in 0 until n) {
                                    ans += c
                                    return@l
                                }
                                if(!vis[ni][nj]) {
                                    if (occ[ni][nj]) {
