        var ans = 0
        for(x in p) {
            val i = (x - 1) / n
            val j = (x - 1) % n
            ans += dp[i][j]
            rem[i][j] = true

            val q = LinkedList<Pair<Int, Int>>()
            q.add(Pair(i, j))

            while(!q.isEmpty()) {
                val (a, b) = q.pop()
                for(k in 0..3) {
                    val c = a + dl[k]
                    val d = b + dc[k]
                    if(0 <= c && c < dp.size && 0 <= d && d < dp[0].size && calc(c, d, dp, rem)) {
                        q.add(Pair(c, d))
                    }
                }
            }
        }

        println(ans)
    }
}

