class F(val size: Int) { // fenwick
    val a = IntArray(size + 2) { 0 }

    fun add(t: Int) {
        var x = t
        while (x <= size + 1) {
            a[x]++
            x += -x and x
        }
    }

    fun remove(t: Int) {
        var x = t
        while (x <= size + 1) {
            a[x]--
            x += -x and x
        }
    }

    fun query(t: Int): Int {
        var x = t
        var s = 0
        while (x != 0) {
            s += a[x]
            x = x and (x - 1)
        }
        return s
    }
}

