public class Main {

  public static void main(String[] args) { 
      Scanner sc = new Scanner(System.in);
      int n = sc.nextInt();
      int[] pArr = new int[n*n];
      for(int i = 0; i < n*n; i++) {
        pArr[i] = sc.nextInt();
      }
      int[][][] grid = new int[n][n][4];
      for(int i = 0; i < n; i++) {
        for(int j = 0; j < n; j++) {
          grid[i][j][0] = i;
          grid[i][j][2] = n - 1 - i;
          grid[i][j][3] = j;
          grid[i][j][1] = n - 1 - j;
        }
      }
      int cnt = 0;
      for(int p : pArr) {
        int[] pos = pos(p, n);
        int row = pos[0], col = pos[1];
        int minCnt = Integer.MAX_VALUE;
        for(int d = 0; d < 4; d++) {
          minCnt = Math.min(minCnt, grid[row][col][d]);
        }
        cnt += minCnt;
        // up: 0
        for(int i = n-1; i > row; i--) {
          grid[i][col][0]--;
        }
        // down: 2
        for(int i = 0; i < row; i++) {
          grid[i][col][2]--;
        }
        // left: 3
        for(int i = n-1; i > col; i--) {
          grid[row][i][3]--;
        }
        // right: 1
        for(int i = 0; i < col; i++) {
          grid[row][i][1]--;
        }
      }
      System.out.println(cnt);
  }

  private static int[] pos(int p, int n) {
    p--;
    return new int[] {p / n, p % n};
  }
}

import java.util.*;

public class Main {
    static int n;
	public static void main (String[] args) {
		Scanner sc = new Scanner(System.in);
		n = sc.nextInt();
		int[] costs = new int[n * n];
		boolean[] selected = new boolean[n * n];
		PriorityQueue<Path> queue = new PriorityQueue<>();
	    Arrays.fill(costs, Integer.MAX_VALUE);
		for (int i = 0; i < n * n; i++) {
		    costs[i] = Math.min(Math.min(i / n, n - 1 - i / n), Math.min(i % n, n - 1 - i % n));
		}
		int ans = 0;
		for (int i = 0; i < n * n; i++) {
		    int x = sc.nextInt() - 1;
		    int row = x / n;
		    int col = x % n;
		    int value = costs[x];
		    selected[x] = true;
	        if (x / n > 0) {
	            if (costs[x - n] > value) {
	                queue.add(new Path(x - n, value));
	            }
	        }
	        if (x / n < n - 1) {
	            if (costs[x + n] > value) {
	                queue.add(new Path(x + n, value));
	            }
	        }
	        if (x % n > 0) {
	            if (costs[x - 1] > value) {
	                queue.add(new Path(x - 1, value));
	            }
	        }
	        if (x % n < n - 1) {
	            if (costs[x + 1] > value) {
	                queue.add(new Path(x + 1, value));
	            }
	        }
		    ans += value;
		    fill(queue, costs, selected);
		}
		System.out.println(ans);
	}

	static void fill(PriorityQueue<Path> queue, int[] costs, boolean[] selected) {
	    while (queue.size() > 0) {
	        Path p = queue.poll();
	        if (costs[p.idx] <= p.value) {
	            continue;
	        }
	        costs[p.idx] = p.value;
	        int next = p.value;
	        if (!selected[p.idx]) {
	            next++;
	        }
	        if (p.idx / n > 0) {
	            if (costs[p.idx - n] > next) {
	                queue.add(new Path(p.idx - n, next));
	            }
	        }
	        if (p.idx / n < n - 1) {
	            if (costs[p.idx + n] > next) {
	                queue.add(new Path(p.idx + n, next));
	            }
	        }
	        if (p.idx % n > 0) {
	            if (costs[p.idx - 1] > next) {
	                queue.add(new Path(p.idx - 1, next));
	            }
	        }
	        if (p.idx % n < n - 1) {
	            if (costs[p.idx + 1] > next) {
	                queue.add(new Path(p.idx + 1, next));
	            }
	        }
	    }
	}


	static class Path implements Comparable<Path> {
	    int idx;
	    int value;

	    public Path(int idx, int value) {
	        this.idx = idx;
	        this.value = value;
	    }

	    public int compareTo(Path another) {
	        return value - another.value;
