			int t[] = {x, y};
			used[x][y] = true;
			ArrayDeque<int[]> q = new ArrayDeque<>();
			q.add(t);
			while(!q.isEmpty()) {
				int now[] = q.poll();
				int nowx = now[0], nowy = now[1];
				for(int j=0;j<4;j++) {
					int nx = nowx + dx[j], ny = nowy + dy[j];
					if(nx < 0 || n<=nx)continue;
					if(ny < 0 || n<=ny)continue;
					if(field[nx][ny] > field[nowx][nowy]) {
						if(used[nowx][nowy]) field[nx][ny] = field[nowx][nowy];
						else if(field[nx][ny] <= field[nowx][nowy] + 1) continue;
						else field[nx][ny] = field[nowx][nowy] + 1;
						int next[] = {nx, ny};
						q.add(next);
					}
				}
			}
			//debug(field);
		}

		out.println(ans);
	}

