import java.util.*;

public class Main {

    static int INF = 1_000_000_000;
    static boolean[][] visited;
    static int[][] removed;
    static int N;
    static int[][] H;
    static ArrayList<int[]> diff;

    public static void dfs(int y, int x) {
        if (visited[y][x]) return;
        visited[y][x] = true;

        int min = H[y][x];
        for (int i=0;i<4;i++) {
            if (0 <= y+diff.get(i)[0] && y+diff.get(i)[0] < N && 0 <= x+diff.get(i)[1] && x+diff.get(i)[1] < N) {
                int tmp = H[y+diff.get(i)[0]][x+diff.get(i)[1]]+1-removed[y][x];
                min = Math.min(min, tmp);
            } else {
                if (removed[y][x] == 1) min = 0;
            }
        }
        if (min < H[y][x]) {
            H[y][x] = min;
            for (int i=0;i<4;i++) {
                if (0 <= y+diff.get(i)[0] && y+diff.get(i)[0] < N && 0 <= x+diff.get(i)[1] && x+diff.get(i)[1] < N) {
                    dfs(y+diff.get(i)[0], x+diff.get(i)[1]);
                }
            }
        }
        for (int i=0;i<4;i++) {
            if (0 <= y+diff.get(i)[0] && y+diff.get(i)[0] < N && 0 <= x+diff.get(i)[1] && x+diff.get(i)[1] < N) {
                int tmp = H[y+diff.get(i)[0]][x+diff.get(i)[1]]+1-removed[y][x];
                min = Math.min(min, tmp);
            } else {
                if (removed[y][x] == 1) min = 0;
            }
        }
    }

    public static void init_diff() {
        diff = new ArrayList<int[]>();
        int[] add_1 = {1, 0};int[] add_2 = {-1, 0};int[] add_3 = {0, 1};int[] add_4 = {0, -1};
        diff.add(add_1);diff.add(add_2);diff.add(add_3);diff.add(add_4);
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        N = sc.nextInt();
        H = new int[N][N];
        removed = new int[N][N];
        init_diff();
        for (int i=0;i<N;i++) {
            for (int j=0;j<N;j++) {
                H[i][j] = INF;
            }
        }
        for (int i=0;i<N;i++) {
            for (int j=0;j<N;j++) {
                H[i][j] = Math.min(H[i][j], Math.min(i, j)+1);
                H[i][j] = Math.min(H[i][j], Math.min(N-1-i, N-1-j)+1);
            }
        }
        int ans = 0;
        for (int i=0;i<N*N;i++) {
            int P = sc.nextInt()-1;
            int y = P/N;
            int x = P%N;
            ans += H[y][x]-1;
            removed[y][x] = 1;
            visited = new boolean[N][N];
            dfs(y, x);
        }
        System.out.println(ans);
    }
}

import java.util.ArrayDeque;
import java.util.Deque;
import java.util.HashMap;
import java.util.Map;
import java.util.Scanner;

public class Main {

    public static void main(String[] args) {

        Scanner sc = new Scanner(System.in);

        int n = sc.nextInt();

        boolean[][] seat = new boolean[n][n];

        int count = 0;

        for(int i=0; i<n*n; i++){

            int p = sc.nextInt();

            seat[(p-1)/n][(p-1)%n] = true;
            //System.out.println((p-1)/n + " " + (p-1)%n);

            Deque<Map<String,Integer>> que = new ArrayDeque();
            Map<String,Integer> map = new HashMap<>();
            map.put("x", (p-1)%n);
            map.put("y", (p-1)/n);
            que.add(map);

            int min = n*n + 1;
            boolean[][] ary = new boolean[n][n];
            while(!que.isEmpty()){

                map = que.removeFirst();
                int x = map.get("x");
                int y = map.get("y");

                if(x == 0 || y == 0 || x == n-1 || y == n-1){
                    min = 0;
                    break;
                }
                else{
                    int xtemp = x < n-x-1 ? x : n-x-1;
                    int ytemp = y < n-y-1 ? y : n-y-1;
                    int temp = xtemp < ytemp ? xtemp : ytemp;
                    min = min<temp ? min : temp;
                }
                if(x-1 > 0 && seat[y][x-1] && !ary[y][x-1]){
                    ary[y][x-1] = true;
                    map = new HashMap<>();
                    map.put("x", x-1);
                    map.put("y", y);
                    que.add(map);
                }
                if(y-1 > 0 && seat[y-1][x] && !ary[y-1][x]){
                    ary[y-1][x] = true;
                    map = new HashMap<>();
                    map.put("x", x);
                    map.put("y", y-1);
                    que.add(map);
                }
                if(x+1 < n && seat[y][x+1] && !ary[y][x+1]){
                    ary[y][x+1]=true;
                    map = new HashMap<>();
                    map.put("x", x+1);
                    map.put("y", y);
                    que.add(map);
                }
                if(y+1 < n && seat[y+1][x] && ary[y+1][x]){
                    ary[y+1][x]= true;
                    map = new HashMap<>();
                    map.put("x", x);
                    map.put("y", y+1);
                    que.add(map);
                }
            }
            count += min;
        }

        System.out.println(count);
    }
}

