            Arrays.fill(array, true);
        }

        final int[][] distances = new int[n][n + 1];
        for (final int[] array : distances) {
            Arrays.fill(array, Integer.MAX_VALUE);
        }
        Arrays.fill(distances[0], 0);
        Arrays.fill(distances[n - 1], 0);
        for (int i = 1; i < n - 1; i++) {
            distances[i][1] = 0;
            distances[i][n] = 0;
            for (int j = 2; j < n; j++) {
                if (j > n - j + 1) {
                    break;
                }
                distances[i][j] = Math.min(Math.min(distances[i - 1][j], distances[i][j - 1]), Math.min(distances[i + 1][j], distances[i][j + 1])) + 1;
                distances[i][n - j + 1] = Math.min(Math.min(distances[i - 1][n - j + 1], distances[i][n - j]), Math.min(distances[i + 1][n - j + 1], distances[i][n - j + 2])) + 1;
            }
        }

        final UnaryOperator<Integer> bfs = point -> {
            final int x = (point - 1) / n;
            final int y = (point - 1) % n + 1;
            final int distance = distances[x][y];
            isSitting[x][y] = false;

            final Deque<Integer> queue = new ArrayDeque<>();
            queue.add(point);
            while (!queue.isEmpty()) {
                final int current = queue.pollFirst();
                final int currentX = (current - 1) / n;
                final int currentY = (current - 1) % n + 1;
                for (int i = 0; i < 4; i++) {
                    final int nextX = currentX + xMove[i];
                    final int nextY = currentY + yMove[i];
                    if (nextX == -1 || nextX == n || nextY == 0 || nextY == n + 1) {
                        continue;
                    }

                    final int nextDistance = distances[currentX][currentY] + (isSitting[currentX][currentY] ? 1 : 0);
                    if (nextDistance < distances[nextX][nextY]) {
                        final int next = nextX * n + nextY;
                        queue.add(next);
                        distances[nextX][nextY] = nextDistance;
                    }
                }
            }

            return distance;
        };

        final long sum = IntStream.range(0, n * n)
            .mapToLong(i -> bfs.apply(scanner.nextInt()))
            .sum();

        System.out.println(sum);
    }

    private static class FastScanner {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        FastScanner(final InputStream in) {
            reader = new BufferedReader(new InputStreamReader(in));
        }

        String next() {
            if (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (final IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.util.Scanner;

public class Main {

  static String isSolved = "No";
  static int N = 0;
  static int H = 0;
  static int W = 0;
  static char[][] maze;
  static boolean[][] reached;
  static int cnt = 0;

  public static void main(String[] args) {
    Scanner sc = new Scanner(System.in);
    N = sc.nextInt();
    H = N;
    W = N;

    maze = new char[H][W];
    reached = new boolean[H][W];
    int[] start = new int[2];

    int num = 1;
    for (int i = 0; i < H; i++) {
      for (int j = 0; j < W; j++) {
        maze[i][j] = (char) num;
        num++;
      }
    }

    for (int k = 0; k < N * N; k++) {
      char P = (char) sc.nextInt();
      for (int i = 0; i < H; i++) {
        for (int j = 0; j < W; j++) {
          if (P == maze[i][j]) {
            start[0] = i;
            start[1] = j;
          }
        }
      }
      isSolved = "No";
      maze[start[0]][start[1]] = 'a'; // aはすでに抜けた後
      solve(start[0], start[1], maze);

      if (isSolved.equals("No")) {
        cnt++;
      }
    }

    System.out.println(cnt);
  }

  private static void solve(int y, int x, char[][] maze) {

    if (y < 0 || y >= H || x < 0 || x >= W) {
      isSolved = "Yes";
      return;
    }
    if (maze[y][x] != 'a') return;
    if (reached[y][x]) return;

    reached[y][x] = true;

    solve(y + 1, x, maze);
    solve(y - 1, x, maze);
    solve(y, x - 1, maze);
    solve(y, x + 1, maze);

    return;
  }
}

