        boolean[] possible = new boolean[n*n];
        Arrays.fill(exist,true);
        Arrays.fill(possible,false);
        HashSet<Integer> set = new HashSet<Integer>();
        Queue<Integer> queue = new ArrayDeque<>();
        for(int i = 0; i < n; i++){
          for(int j = 0; j < n; j++){
            List<Integer> near = new ArrayList<>();
            graph.add(new ArrayList<>());
            if(i == 0 || i == n-1 || j == 0 || j == n-1){
              set.add(x);
            }
            if(x - 1 > i*n){
              graph.get(x-1).add(x-1);
            }
            if(x + 1 <= n*(i+1)){
              graph.get(x-1).add(x+1);
            }
            if(x - n > 0){
              graph.get(x-1).add(x-n);
            }
            if(x + n <= n*n){
              graph.get(x-1).add(x+n);
            }
            int p = fs.nextInt();
            queue.add(p);
            m[i][j] = x;
            x += 1;
          }
        }
        while(queue.size() > 0){
          int a = queue.poll();
          exist[a-1] = false;
          if(set.contains(a)){
            possible[a-1] = true;
          }
          if(possible[a-1] == true){
            for(int w : graph.get(a-1)){
              possible[w-1] = true;
            }
          }
          else{
            for(int w : graph.get(a-1)){
              if(possible[w-1] == true && exist[w-1] == false){
                possible[a-2] = true;
                possible[a-1-n] = true;
                possible[a] = true;
                possible[a-1+n] = true;
                possible[a-1] = true;
                count -= 1;
                break;
              }
            }
            int[] deep = new int[n*n];
            Arrays.fill(deep,1000000);
            Queue<Integer> queue2 = new ArrayDeque<>();
            queue2.add(a);
            deep[a-1] = 0;
            flag = true;
            while(flag){
              int b = queue2.poll();
              for(int w : graph.get(b-1)){
                queue2.add(w);
                if(exist[w-1] == false){
                  deep[w-1] = Math.min(deep[w-1],deep[b-1]);
                }else{
                  deep[w-1] = Math.min(deep[w-1],deep[b-1] + 1);
                }
                if(possible[w-1] == true){
                  flag = false;
                  count += deep[w-1];
                  break;
                }
                else if(set.contains(w)){
                  flag = false;
                  count += deep[w-1];
                  break;
                }
              }
            }
            if(a-2 >= 0 || a-1-n >= 0 || a <= n*n || a-1+n <= n*n){
              if((exist[a-2] == false && possible[a-2] == true) || (exist[a-1-n] == false && possible[a-1-n] == true) || (exist[a] == false && possible[a] == true) || (exist[a-1+n] == false && possible[a-1+n] == true)){
                possible[a-2] = true;
                possible[a-1-n] = true;
                possible[a] = true;
                possible[a-1+n] = true;
                possible[a-1] = true;
              }
            }
          }
        }
        System.out.print(count);
  }
