class FastScanner {
    private final InputStream in = System.in;
    private final byte[] buffer = new byte[1024];
    private int ptr = 0;
    private int buflen = 0;
    private boolean hasNextByte(){
        if(ptr < buflen){
            return true;
        }else{
            ptr = 0;
            try{
                buflen = in.read(buffer);
            }catch(IOException e){
                e.printStackTrace();
            }
            if(buflen <=0){
                return false;
            }
        }
        return true;
    }

    private int readByte(){
        if(hasNextByte())return buffer[ptr++];
        else return -1;
    }

    private static boolean isPrintableChar(int c){
        return 33<=c && c<=126;
    }
    public boolean hasNext(){
        while(hasNextByte() && !isPrintableChar(buffer[ptr]))ptr++;
        return hasNextByte();
    }

    public String next(){
        if(!hasNext()) throw new NoSuchElementException();
        StringBuilder sb = new StringBuilder();
        int b = readByte();
        while(isPrintableChar(b)){
            sb.appendCodePoint(b);
            b = readByte();
        }
        return sb.toString();
    }

    public long nextLong(){
        if(!hasNext()) throw new NoSuchElementException();
        long n = 0;
        boolean minus = false;
        int b = readByte();
        if(b == '-'){
            minus = true;
            b = readByte();
        }
        if(b < '0' || '9' < b){
            throw new NumberFormatException();
        }
        while(true){
            if('0' <= b && b<='9'){
                n*=10;
                n+=b-'0';
            }else if(b==-1 || !isPrintableChar(b)){
                return minus ? -n : n;
            }else{
                throw new NumberFormatException();
            }
            b = readByte();
        }
    }
    public int nextInt(){
        long nl = nextLong();
        if(nl < Integer.MIN_VALUE || nl > Integer.MAX_VALUE)throw new NumberFormatException();
        return (int) nl;
    }
    public double nextDoutble(){return Double.parseDouble(next());}
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.util.ArrayDeque;
import java.util.Arrays;
import java.util.Deque;
import java.util.StringTokenizer;
import java.util.function.Function;
import java.util.function.UnaryOperator;
import java.util.stream.IntStream;

public class Main {
    private static final int[] xMove = {-1, 0, 1, 0};
    private static final int[] yMove = {0, -1, 0, 1};

    public static void main(final String[] args) {
        final FastScanner scanner = new FastScanner(System.in);
        final int n = scanner.nextInt();

        final boolean[][] isSitting = new boolean[n + 1][n + 1];
        for (final boolean[] array : isSitting) {
            Arrays.fill(array, true);
        }

        final UnaryOperator<Integer> bfs = point -> {
            final int[][] distances = new int[n + 1][n + 1];
            for (final int[] array : distances) {
                Arrays.fill(array, -1);
            }
            final int x = (point - 1) / n;
            final int y = (point - 1) % n + 1;

            isSitting[x][y] = false;
            distances[x][y] = 0;
            final Deque<Integer> queue = new ArrayDeque<>();
            queue.add(point);

            while (!queue.isEmpty()) {
                final int poll = queue.pollFirst();
                final int tmpX = (poll - 1) / n;
                final int tmpY = (poll - 1) % n + 1;
                final int distance = distances[tmpX][tmpY];
                if (tmpX == 0 || tmpX == n - 1 || tmpY == 1 || tmpY == n) {
                    continue;
                }

                for (int i = 0; i < 4; i++) {
                    final int nextX = tmpX + xMove[i];
                    final int nextY = tmpY + yMove[i];
                    if (distances[nextX][nextY] != -1) {
                        continue;
                    }
                    queue.add(nextX * n + nextY);
                    distances[nextX][nextY] = distance + (isSitting[nextX][nextY] ? 1 : 0);
                }
            }

            return IntStream.concat(
                IntStream.concat(
                    IntStream.range(0, n).map(i -> distances[i][1]),
                    IntStream.range(0, n).map(i -> distances[i][n])
                ),
                IntStream.concat(
                    IntStream.rangeClosed(1, n).map(i -> distances[0][i]),
                    IntStream.rangeClosed(1, n).map(i -> distances[n - 1][i])
                )
            )
                .filter(value -> value != -1)
                .min()
                .orElse(Integer.MAX_VALUE);
        };

        final long count = IntStream.range(0, n * n)
            .map(i -> bfs.apply(scanner.nextInt()))
            .sum();

        System.out.println(count);
    }

    private static class FastScanner {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        FastScanner(final InputStream in) {
            reader = new BufferedReader(new InputStreamReader(in));
        }

        String next() {
            if (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (final IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        long nextLong() {
            return Long.parseLong(next());
        }

        double nextDouble() {
            return Double.parseDouble(next());
        }

        String nextLine() {
            if (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    return reader.readLine();
                } catch (final IOException e) {
                    throw new RuntimeException(e);
                }
            }

            return tokenizer.nextToken("\n");
        }
    }
}

import java.io.*;
import java.util.ArrayDeque;
import java.util.Deque;
import java.util.StringJoiner;
import java.util.StringTokenizer;
import java.util.function.IntUnaryOperator;
import java.util.function.LongUnaryOperator;

public class Main {
    static In in = new In();
    static Out out = new Out();
    static final long mod = 1000000007;
    static final long inf = 0x1fffffffffffffffL;
    static final int iinf = 0x3fffffff;
    static final int[] da = {-1, 0, 1, 0, -1, 1, 1, -1, -1};

    void solve() {
        int n = in.nextInt();
        int[] dist = new int[n * n];
        boolean[] used = new boolean[n * n];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                dist[i * n + j] = Math.min(Math.min(i + 1, j + 1), Math.min(n - i, n - j));
            }
        }
        int[] da = {1, -1, n, -n};
        long ans = 0;
        Deque<Integer> deque = new ArrayDeque<>();
        for (int i = 0; i < n * n; i++) {
            int p = in.nextInt() - 1;
            dist[p]--;
            ans += dist[p];
            used[p] = true;
            deque.add(p);
            while (!deque.isEmpty()) {
                int v = deque.pollLast();
                for (int j = 0; j < 4; j++) {
                    if (v % n == 0 && j == 1) {
                        continue;
                    }
                    if (v % n == n - 1 && j == 0) {
                        continue;
                    }
                    if (v < n && j == 3) {
                        continue;
                    }
                    if (v >= n * n - n && j == 2) {
                        continue;
                    }
                    int u = v + da[j];
                    if (used[u]) {
                        if (dist[u] > dist[v]) {
                            dist[u] = dist[v];
                            deque.addFirst(u);
                        }
                    } else {
                        if (dist[u] > dist[v] + 1) {
                            dist[u] = dist[v] + 1;
                            deque.addLast(u);
                        }
                    }
                }
            }
        }
        out.println(ans);
    }

    public static void main(String[]$) {
        new Main().solve();
        out.flush();
    }
}

class FastIn extends In {
    private BufferedInputStream reader = new BufferedInputStream(System.in);
    private byte[] buffer = new byte[0x10000];
    private int i = 0;
    private int length = 0;

    private int read() {
        if (length == -1) {
            throw new RuntimeException();
        }
        if (i == length) {
            i = 0;
            try {
                length = reader.read(buffer);
            } catch (IOException ignored) {
            }
            if (length == -1) {
                return -1;
            }
        }
        return buffer[i++];
    }

    String next() {
        StringBuilder builder = new StringBuilder();
        int b = read();
        while (b < '!' || '~' < b) {
            b = read();
        }
        while ('!' <= b && b <= '~') {
            builder.appendCodePoint(b);
            b = read();
        }
        return builder.toString();
    }

    int nextInt() {
        return (int)nextLong();
    }

    long nextLong() {
        int b = read();
        while (b < '!' || '~' < b) {
            b = read();
        }
        int i = 0;
        if (b == '-') {
            i = 1;
            b = read();
        }
        long n = 0;
        while ('0' <= b && b <= '9') {
            n = n * 10 + b - '0';
            b = read();
        }
        return i == 0 ? n : -n;
    }
}

