import java.util.*;

public class Main {
    static int n;
	public static void main (String[] args) {
		Scanner sc = new Scanner(System.in);
		n = sc.nextInt();
		int[][] costs = new int[n][n];
		boolean[][] selected = new boolean[n][n];
		PriorityQueue<Path> queue = new PriorityQueue<>();
		for (int i = 0; i < n; i++) {
		    Arrays.fill(costs[i], Integer.MAX_VALUE);
		    queue.add(new Path(0, i, 0));
		    queue.add(new Path(n - 1, i, 0));
		    queue.add(new Path(i, 0, 0));
		    queue.add(new Path(i, n - 1, 0));
		}
		fill(queue, costs, selected);
		int ans = 0;
		for (int i = 0; i < n * n; i++) {
		    int x = sc.nextInt() - 1;
		    int row = x / n;
		    int col = x % n;
		    int value = costs[row][col];
		    selected[row][col] = true;
	        if (row > 0) {
	            queue.add(new Path(row - 1, col, value));
	        }
	        if (row < n - 1) {
	            queue.add(new Path(row + 1, col, value));
	        }
	        if (col > 0) {
	            queue.add(new Path(row, col - 1, value));
	        }
	        if (col < n - 1) {
	            queue.add(new Path(row, col + 1, value));
	        }
		    ans += value;
		    fill(queue, costs, selected);
		}
		System.out.println(ans);
	}

	static void fill(PriorityQueue<Path> queue, int[][] costs, boolean[][] selected) {
	    while (queue.size() > 0) {
	        Path p = queue.poll();
	        if (costs[p.row][p.col] <= p.value) {
	            continue;
	        }
	        costs[p.row][p.col] = p.value;
	        int next = p.value;
	        if (!selected[p.row][p.col]) {
	            next++;
	        }
	        if (p.row > 0) {
	            queue.add(new Path(p.row - 1, p.col, next));
	        }
	        if (p.row < n - 1) {
	            queue.add(new Path(p.row + 1, p.col, next));
	        }
	        if (p.col > 0) {
	            queue.add(new Path(p.row, p.col - 1, next));
	        }
	        if (p.col < n - 1) {
	            queue.add(new Path(p.row, p.col + 1, next));
	        }
	    }
	}


	static class Path implements Comparable<Path> {
	    int row;
	    int col;
	    int value;

	    public Path(int row, int col, int value) {
	        this.row = row;
	        this.col = col;
	        this.value = value;
	    }

	    public int compareTo(Path another) {
	        return value - another.value;
	    }
	}
}

import java.io.*;
import java.util.*;

public class Main {
    FastScanner in;
    PrintWriter out;

    long d;
    long[] cost = new long[3];
    int[] divs = new int[]{2, 3, 5};

    Map<Long, Long> cache;

    long get(long n) {
        if (cache.containsKey(n)) {
            return cache.get(n);
        }
        if (n == 1) {
            return d;
        }
        long res = Long.MAX_VALUE;
        if (n * 1.0 * d < 1e17) {
            res = n * d;
        }
        for (int it = 0; it < divs.length; it++) {
            int div = divs[it];
            for (long next = n - div + 1; next < n + div; next++) {
                if (next > 1 && next % div == 0) {
                    long curRes = Math.abs(next - n) * d + get(next / div) + cost[it];
                    res = Math.min(res, curRes);
                }
            }
        }
        cache.put(n, res);
        return res;
    }

    void solve() {
        int n = in.nextInt();
        int[][] d = new int[n + 2][n + 2];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                int dist = Math.min(Math.min(i, n - i - 1), Math.min(j, n - j - 1));
                d[i + 1][j + 1] = dist;
            }
        }
        boolean[][] occupied = new boolean[n + 2][n + 2];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                occupied[i + 1][j + 1] = true;
            }
        }
        int res = 0;
        int[] checkX = new int[n * n];
        int[] checkY = new int[n * n];
        int[] dx = new int[]{0, 1, -1, 0};
        int[] dy = new int[]{-1, 0, 0, 1};
        for (int it = 0; it < n * n; it++) {
            int id = in.nextInt() - 1;
            int x = id / n + 1;
            int y = id % n + 1;
            occupied[x][y] = false;
            res += d[x][y];
            checkX[0] = x;
            checkY[0] = y;
            int checkSz = 1;
            for (int i = 0; i < checkSz; i++) {
                int cx = checkX[i], cy = checkY[i];
                int ncost = d[cx][cy] + (occupied[cx][cy] ? 1 : 0);
                for (int j = 0; j < dx.length; j++) {
                    int nx = cx + dx[j], ny = cy + dy[j];
                    if (d[nx][ny] > ncost) {
                        d[nx][ny] = ncost;
                        checkX[checkSz] = nx;
                        checkY[checkSz] = ny;
                        checkSz++;
                    }
                }
            }
        }
        out.println(res);
    }

    final int mod = 988244353;

    int mul(int x, int y) {
        return (int) ((x * 1L * y) % mod);
    }

    void run() {
        try {
            in = new FastScanner(new File("Main.in"));
            out = new PrintWriter(new File("Main.out"));

            solve();

            out.close();
        } catch (FileNotFoundException e) {
            e.printStackTrace();
        }
    }

    void runIO() {

        in = new FastScanner(System.in);
        out = new PrintWriter(System.out);

        solve();

        out.close();
    }

    class FastScanner {
        BufferedReader br;
        StringTokenizer st;

        public FastScanner(File f) {
            try {
                br = new BufferedReader(new FileReader(f));
            } catch (FileNotFoundException e) {
                e.printStackTrace();
            }
        }

        public FastScanner(InputStream f) {
            br = new BufferedReader(new InputStreamReader(f));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                String s = null;
                try {
                    s = br.readLine();
                } catch (IOException e) {
                    e.printStackTrace();
                }
                if (s == null)
                    return null;
                st = new StringTokenizer(s);
            }
            return st.nextToken();
        }

        boolean hasMoreTokens() {
            while (st == null || !st.hasMoreTokens()) {
                String s = null;
                try {
                    s = br.readLine();
                } catch (IOException e) {
                    e.printStackTrace();
                }
                if (s == null)
                    return false;
                st = new StringTokenizer(s);
            }
            return true;
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        long nextLong() {
            return Long.parseLong(next());
        }

        double nextDouble() {
            return Double.parseDouble(next());
        }
