import java.util.function.LongUnaryOperator;

public class Main {
    static In in = new In();
    static Out out = new Out();
    static final long mod = 1000000007;
    static final long inf = 0x1fffffffffffffffL;
    static final int iinf = 0x3fffffff;
    static final int[] da = {-1, 0, 1, 0, -1, 1, 1, -1, -1};

    void solve() {
        int n = in.nextInt();
        int[] dist = new int[n * n];
        int[] exist = new int[n * n];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                exist[i * n + j] = 1;
                dist[i * n + j] = Math.min(Math.min(i + 1, j + 1), Math.min(n - i, n - j));
            }
        }
        long ans = 0;
        Deque<Integer> deque = new ArrayDeque<>();
        for (int i = 0; i < n * n; i++) {
            int p = in.nextInt() - 1;
            dist[p]--;
            exist[p]--;
            ans += dist[p];
            deque.add(p);
            while (!deque.isEmpty()) {
                int v = deque.pollLast();
                if (v % n != n - 1 && dist[v + 1] > dist[v] + exist[v + 1]) {
                    dist[v + 1] = dist[v] + exist[v + 1];
                    deque.add(v + 1);
                }
                if (v % n != 0 && dist[v - 1] > dist[v] + exist[v - 1]) {
                    dist[v - 1] = dist[v] + exist[v - 1];
                    deque.add(v - 1);
                }
                if (v < n * n - n && dist[v + n] > dist[v] + exist[v + n]) {
                    dist[v + n] = dist[v] + exist[v + n];
                    deque.add(v + n);
                }
                if (v >= n && dist[v - n] > dist[v] + exist[v - n]) {
                    dist[v - n] = dist[v] + exist[v - n];
                    deque.add(v - n);
                }
            }
        }
        out.println(ans);
    }

    public static void main(String[]$) {
        new Main().solve();
        out.flush();
    }
}

class FastIn extends In {
    private BufferedInputStream reader = new BufferedInputStream(System.in);
    private byte[] buffer = new byte[0x10000];
    private int i = 0;
    private int length = 0;

    private int read() {
        if (length == -1) {
            throw new RuntimeException();
        }
        if (i == length) {
            i = 0;
            try {
                length = reader.read(buffer);
            } catch (IOException ignored) {
            }
            if (length == -1) {
                return -1;
            }
        }
        return buffer[i++];
    }

    String next() {
        StringBuilder builder = new StringBuilder();
        int b = read();
        while (b < '!' || '~' < b) {
            b = read();
        }
        while ('!' <= b && b <= '~') {
            builder.appendCodePoint(b);
            b = read();
        }
        return builder.toString();
    }

    int nextInt() {
        return (int)nextLong();
    }

    long nextLong() {
        int b = read();
        while (b < '!' || '~' < b) {
            b = read();
        }
        int i = 0;
        if (b == '-') {
            i = 1;
            b = read();
        }
        long n = 0;
        while ('0' <= b && b <= '9') {
            n = n * 10 + b - '0';
            b = read();
        }
        return i == 0 ? n : -n;
    }
}

