        int n = in.nextInt();
        int[] dist = new int[n * n];
        int[] exist = new int[n * n];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                exist[i * n + j] = 1;
                dist[i * n + j] = Math.min(Math.min(i + 1, j + 1), Math.min(n - i, n - j));
            }
        }
        long ans = 0;
        Deque<Integer> deque = new ArrayDeque<>();
        for (int i = 0; i < n * n; i++) {
            int p = in.nextInt() - 1;
            dist[p]--;
            exist[p]--;
            ans += dist[p];
            deque.add(p);
            while (!deque.isEmpty()) {
                int v = deque.pollLast();
                if (v % n != n - 1 && dist[v + 1] > dist[v] + exist[v + 1]) {
                    dist[v + 1] = dist[v] + exist[v + 1];
                    if (exist[v + 1] == 1) {
                        deque.addFirst(v + 1);
                    } else {
                        deque.addLast(v + 1);
                    }
                }
                if (v % n != 0 && dist[v - 1] > dist[v] + exist[v - 1]) {
                    dist[v - 1] = dist[v] + exist[v - 1];
                    if (exist[v - 1] == 1) {
                        deque.addFirst(v - 1);
                    } else {
                        deque.addLast(v - 1);
                    }
