                    dist[v + n] = dist[v] + exist[v + n];
                    if (exist[v + n] == 1) {
                        deque.addFirst(v + n);
                    } else {
                        deque.addLast(v + n);
                    }
                }
                if (v >= n && dist[v - n] > dist[v] + exist[v - n]) {
                    dist[v - n] = dist[v] + exist[v - n];
                    if (exist[v - n] == 1) {
                        deque.addFirst(v - n);
                    } else {
                        deque.addLast(v - n);
                    }
                }
            }
        }
        out.println(ans);
    }

