        //创建盘子 外围都是0 内层是123456排列
        int wowo_temp = 1;
        int[][] arr = new int[m + 2][m + 2];
        for (int i = 1; i < m + 1; i++) {
            for (int j = 1; j < m + 1; j++) {
                arr[i][j] = wowo_temp++;
            }
        }

        for (int i = 0; i < m + 2; i++) {
            arr[0][i] = 0;
            arr[m + 1][i] = 0;
        }
        for (int i = 0; i < m + 2; i++) {
            arr[i][0] = 0;
            arr[i][m + 1] = 0;
        }
        LOOP:
        for (int i = 0; i < m * m; i++) {
            int tmp = temp[i];
            int row = tmp / m + 1;
            int col = tmp % m;
            //得到行列数        这人出去后 将他设为0
            if (tmp % m == 0)
                col = m;
            arr[row][col] = 0;

            for (int k = row ; k < m + 2; k++) {
                if (arr[k][col] == 0 && k == m + 1) {
                    result--;
                    continue LOOP;
                } else
                    break;
            }

            for (int k = row ; k > 0; k--) {
                if (arr[k][col] == 0 && k == 1) {
                    result--;
                    continue LOOP;
                } else
                    break;
            }

            for (int k = col ; k < m + 2; k++) {
                if (arr[row][k] == 0 && k == m + 1) {
                    result--;
                    continue LOOP;
                } else
                    break;
            }

            for (int k = col ; k > 0; k--) {
                if (arr[row][k] == 0 && k == 1) {
                    result--;
                    continue LOOP;
                } else
                    break;
            }

        }
        System.out.println(result);
    }
}

