        from[0] = i;
        from[1] = j;
        int now = dijk(map, from, td);
        ret += now;
      }
    }
    System.out.println(ret);
  }

  static int[][] dir = {{0, 1}, {0, -1}, {1, 0}, {-1, 0}};

  public static int dijk(int[][] map, int[] from, final int[][] td) {
    int n = map.length;
    for (int[] v : td)
      Arrays.fill(v, Integer.MAX_VALUE / 4);
    TreeSet<int[]> q = new TreeSet<>((o1, o2) -> {
      if (td[o1[0]][o1[1]] != td[o2[0]][o2[1]]) {
        return td[o1[0]][o1[1]] - td[o2[0]][o2[1]];
      } else {
        return o1[0] != o2[0] ? o1[0] - o2[0] : o1[1] - o2[1];
      }
    });
    q.add(from);
    td[from[0]][from[1]] = 0;

    int v = map[from[0]][from[1]];

    while (q.size() > 0) {
      int[] cur = q.pollFirst();
      int cx = cur[0];
      int cy = cur[1];

      for (int[] d : dir) {
        int nx = cx + d[0];
        int ny = cy + d[1];
        if (nx < 0 || nx >= n || ny < 0 || ny >= n)
          return td[cx][cy];

        int nd = td[cx][cy] + (v < map[nx][ny] ? 1 : 0);
        if (nd < td[nx][ny]) {
          int[] next = {nx, ny};
          q.remove(next);
          td[nx][ny] = nd;
          q.add(next);
        }
      }
    }
    return -1;
  }

