class FastScanner {
    private final InputStream in = System.in;
    private final byte[] buffer = new byte[1024];
    private int ptr = 0;
    private int buflen = 0;
    private boolean hasNextByte(){
        if(ptr < buflen){
            return true;
        }else{
            ptr = 0;
            try{
                buflen = in.read(buffer);
            }catch(IOException e){
                e.printStackTrace();
            }
            if(buflen <=0){
                return false;
            }
        }
        return true;
    }

    private int readByte(){
        if(hasNextByte())return buffer[ptr++];
        else return -1;
    }

    private static boolean isPrintableChar(int c){
        return 33<=c && c<=126;
    }
    public boolean hasNext(){
        while(hasNextByte() && !isPrintableChar(buffer[ptr]))ptr++;
        return hasNextByte();
    }

    public String next(){
        if(!hasNext()) throw new NoSuchElementException();
        StringBuilder sb = new StringBuilder();
        int b = readByte();
        while(isPrintableChar(b)){
            sb.appendCodePoint(b);
            b = readByte();
        }
        return sb.toString();
    }

    public long nextLong(){
        if(!hasNext()) throw new NoSuchElementException();
        long n = 0;
        boolean minus = false;
        int b = readByte();
        if(b == '-'){
            minus = true;
            b = readByte();
        }
        if(b < '0' || '9' < b){
            throw new NumberFormatException();
        }
        while(true){
            if('0' <= b && b<='9'){
                n*=10;
                n+=b-'0';
            }else if(b==-1 || !isPrintableChar(b)){
                return minus ? -n : n;
            }else{
                throw new NumberFormatException();
            }
            b = readByte();
        }
    }
    public int nextInt(){
        long nl = nextLong();
        if(nl < Integer.MIN_VALUE || nl > Integer.MAX_VALUE)throw new NumberFormatException();
        return (int) nl;
    }
    public double nextDoutble(){return Double.parseDouble(next());}
}

import java.util.*;
public class Main {
	//模範解答の理解度確認
	static int[][] seat;
	static int[][] hate;

	public static void main(String[] args){
		Scanner sc = new Scanner(System.in);
		// 文字列の入力
		String[] lineString = sc.nextLine().split(" ");
		int n = Integer.parseInt(lineString[0]);
		seat = new int[n][n];
		hate = new int[n][n];

		for (int i = 0; i < n; i++) {
			for (int j = 0; j < n; j++) {
				seat[i][j] = 1;
				hate[i][j] = Math.min(Math.min(i, j), Math.min(n - i - 1, n - j - 1));
			}
		}

		lineString = sc.nextLine().split(" ");
		int hateCount = 0;
		for (int i = 0; i < n * n; i++) {
			int number = Integer.parseInt(lineString[i]) - 1;
			int row = number / n;
			int column = number % n;

			hateCount += hate[row][column];
			seat[row][column] = 0;

			hateCalc(row, column);
		}

		// 出力
		System.out.println(hateCount);
		sc.close();
	}

	static void hateCalc(int currentRow, int currentColumn) {
		int currentHate = hate[currentRow][currentColumn] + seat[currentRow][currentColumn];	//他からこの座標に来たときの、ここからのhateカウント。
		//前後左右のやり方も今後パクる
		int[] x = {1, 0, -1, 0};
		int[] y = {0, 1, 0, -1};

		for (int i = 0; i < 4; i++) {
			try {
				if (hate[currentRow + y[i]][currentColumn - x[i]] > currentHate) {
					//自分を通ることで、隣のhateが減る場合は、そちらを採用。
					hate[currentRow + y[i]][currentColumn - x[i]] = currentHate;
					//hateが変動した席も再計算。
					hateCalc(currentRow + y[i], currentColumn - x[i]);	//
				}
			} catch (ArrayIndexOutOfBoundsException e) {
				//配列外の探索はしない。
			}
		}
	}
}

