public class Main {
    public static void main(String[] args) throws Exception {
        FastScanner sc = new FastScanner(System.in);
        int n = sc.nextInt();
        int[][] up = new int[n][n];
        int[][] left = new int[n][n];
        int[][] right = new int[n][n];
        int[][] down = new int[n][n];
        for(int i = 0; i < n; i++){
            int upi = i;
            int downi = n-1-i;
            for(int j = 0; j < n; j++){
                int lefti = j;
                int righti = n-1-j;
                up[i][j] = upi;
                down[i][j] = downi;
                left[i][j] = lefti;
                right[i][j] = righti;

            }
        }
        long ans = 0;
        for(int i = 0; i < n*n; i++){
            int now = sc.nextInt()-1;
            int h = now/n;
            int w = now%n;
            ans += Math.min(right[h][w],Math.min(left[h][w],Math.min(up[h][w],down[h][w])));
            for(int j = 0; j < h; j++){
                down[j][w]--;
            }
            for(int j = n-1; j > h; j--){
                up[j][w]--;
            }
            for(int j = 0; j < w; j++){
                right[h][j]--;
            }
            for(int j = n-1; j > w; j--){
                left[h][j]--;
            }
        }
        System.out.println(ans);
    }
}

class FastScanner {
    private BufferedReader reader = null;
    private StringTokenizer tokenizer = null;
    public FastScanner(InputStream in) {
        reader = new BufferedReader(new InputStreamReader(in));
        tokenizer = null;
    }

    public String next() {
        if (tokenizer == null || !tokenizer.hasMoreTokens()) {
            try {
                tokenizer = new StringTokenizer(reader.readLine());
            } catch (IOException e) {
                throw new RuntimeException(e);
            }
        }
        return tokenizer.nextToken();
    }

    public String nextLine() {
        if (tokenizer == null || !tokenizer.hasMoreTokens()) {
            try {
                return reader.readLine();
            } catch (IOException e) {
                throw new RuntimeException(e);
            }
        }
        return tokenizer.nextToken("\n");
    }

    public long nextLong() {
        return Long.parseLong(next());
    }

    public int nextInt() {
        return Integer.parseInt(next());
    }

    public double nextDouble() {
         return Double.parseDouble(next());
    }

    public int[] nextIntArray(int n) {
        int[] a = new int[n];
        for (int i = 0; i < n; i++)
            a[i] = nextInt();
        return a;
    }

    public long[] nextLongArray(int n) {
        long[] a = new long[n];
        for (int i = 0; i < n; i++)
            a[i] = nextLong();
        return a;
    } 
}

import java.util.*;

public class Main {

    static int INF = 1_000_000_000;
    static int[][] removed;
    static int N;
    static int[][] H;
    static ArrayList<int[]> diff;

    public static void dfs(int y, int x) {
        int val = H[y][x] + 1-removed[y][x];
        for (int i=0;i<4;i++) {
            if (0 <= y+diff.get(i)[0] && y+diff.get(i)[0] < N && 0 <= x+diff.get(i)[1] && x+diff.get(i)[1] < N) {
                int tmp = H[y+diff.get(i)[0]][x+diff.get(i)[1]];
                if (tmp > val) {
                    H[y+diff.get(i)[0]][x+diff.get(i)[1]] = val;
                    dfs(y+diff.get(i)[0], x+diff.get(i)[1]);
                }
            }
        }
    }

    public static void init_diff() {
        diff = new ArrayList<int[]>();
        int[] add_1 = {1, 0};int[] add_2 = {-1, 0};int[] add_3 = {0, 1};int[] add_4 = {0, -1};
        diff.add(add_1);diff.add(add_2);diff.add(add_3);diff.add(add_4);
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        N = sc.nextInt();
        H = new int[N][N];
        removed = new int[N][N];
        init_diff();
        for (int i=0;i<N;i++) {
            for (int j=0;j<N;j++) {
                H[i][j] = INF;
            }
        }
        for (int i=0;i<N;i++) {
            for (int j=0;j<N;j++) {
                H[i][j] = Math.min(H[i][j], Math.min(i, j)+1);
                H[i][j] = Math.min(H[i][j], Math.min(N-1-i, N-1-j)+1);
            }
        }
        int ans = 0;
        for (int i=0;i<N*N;i++) {
            int P = Integer.parseInt(sc.next())-1;
            int y = P/N;
            int x = P%N;
            ans += H[y][x]-1;
            removed[y][x] = 1;
            dfs(y, x);
        }
        System.out.println(ans);
    }
}

