      int now = bfs(map, i, ved, q);
      ret += now;
    }
    System.out.println(ret);
  }

  static int[][] dir = {{0, 1}, {0, -1}, {1, 0}, {-1, 0}};


  public static int bfs(int[][] map, int from, int[] ved, int[][] q) {
    int n = map.length;
    int v = map[from / n][from % n];

    int m = q.length;

    int l = 0;
    int r = 0;

    q[0][0] = from;
    q[0][1] = 0;
    r++;
    ved[from] = v;

    while (r != l) {
      r--;
      if (r < 0) {
        r += m;
      }
      int[] x = q[r];

      int cur = x[0];
      int cd = x[1];
      int cy = cur / n;
      int cx = cur % n;

      for (int[] d : dir) {
        int ny = cy + d[0];
        int nx = cx + d[1];
        if (ny < 0 || nx < 0 || ny >= n || nx >= n) {
          return cd;
        }
        int nex = ny * n + nx;

        if (ved[nex] != v) {
          ved[nex] = v;
          if (map[ny][nx] < v) {
            q[r][0] = nex;
            q[r][1] = cd;
            r++;
            if (r >= m)
              r -= m;
          } else {
            l--;
            if (l < 0)
              l += m;

            q[l][0] = nex;
            q[l][1] = cd + 1;
          }
        }
      }
    }
    return -1;
  }



  public static class MinHeap {
    public int[] a;
    public int[] map;
    public int[] imap;
    public int n;
    public int pos;
    public static int INF = Integer.MAX_VALUE;

    public MinHeap(int m) {
      n = m + 2;
      a = new int[n];
      map = new int[n];
      imap = new int[n];
      Arrays.fill(a, INF);
      Arrays.fill(map, -1);
      Arrays.fill(imap, -1);
      pos = 1;
    }

    public int add(int ind, int x) {
      int ret = imap[ind];
      if (imap[ind] < 0) {
        a[pos] = x;
        map[pos] = ind;
        imap[ind] = pos;
        pos++;
        up(pos - 1);
      }
      return ret != -1 ? a[ret] : x;
    }

    public int update(int ind, int x) {
      int ret = imap[ind];
      if (imap[ind] < 0) {
        a[pos] = x;
        map[pos] = ind;
        imap[ind] = pos;
        pos++;
        up(pos - 1);
      } else {
        int o = a[ret];
        a[ret] = x;
        up(ret);
        down(ret);
        // if(a[ret] > o){
        // up(ret);
        // }else{
        // down(ret);
        // }
      }
      return x;
    }

    public int remove(int ind) {
      if (pos == 1)
        return INF;
      if (imap[ind] == -1)
        return INF;

      pos--;
      int rem = imap[ind];
      int ret = a[rem];
      map[rem] = map[pos];
      imap[map[pos]] = rem;
      imap[ind] = -1;
      a[rem] = a[pos];
      a[pos] = INF;
      map[pos] = -1;

      up(rem);
      down(rem);
      return ret;
    }

    public int min() {
      return a[1];
    }

    public int argmin() {
      return map[1];
    }

    public int size() {
      return pos - 1;
    }

    private void up(int cur) {
      for (int c = cur, p = c >>> 1; p >= 1 && a[p] > a[c]; c >>>= 1, p >>>= 1) {
        int d = a[p];
        a[p] = a[c];
        a[c] = d;
        int e = imap[map[p]];
        imap[map[p]] = imap[map[c]];
        imap[map[c]] = e;
        e = map[p];
        map[p] = map[c];
        map[c] = e;
      }
    }

    private void down(int cur) {
      for (int c = cur; 2 * c < pos;) {
        int b = a[2 * c] < a[2 * c + 1] ? 2 * c : 2 * c + 1;
        if (a[b] < a[c]) {
          int d = a[c];
          a[c] = a[b];
          a[b] = d;
          int e = imap[map[c]];
          imap[map[c]] = imap[map[b]];
          imap[map[b]] = e;
          e = map[c];
          map[c] = map[b];
          map[b] = e;
          c = b;
        } else {
          break;
        }
      }
    }
  }


