final class IntDeque implements Iterable<Integer> {
    private int head = -1;
    private int tail = 0;
    private int p[];
    private int n[];
    private static final int DEFAULT_SIZE = 64;
    public IntDeque(final int initialSize) {this(Math.max(1, initialSize - initialSize / 2), Math.max(1, initialSize / 2));}
    private IntDeque(final int pSize, final int nSize) {this.p = new int[pSize]; this.n = new int[nSize];}
    public IntDeque() {this(DEFAULT_SIZE);}
    public void addLast(final int v) {putByRawIndex(tail++, v);}
    public void addFirst(final int v) {putByRawIndex(head--, v);}
    public int pollFirst() {
        if (size() == 0) throw new NoSuchElementException("Deque is empty.");
        return getByRawIndex(++head);
    }
    public int pollLast() {
        if (size() == 0) throw new NoSuchElementException("Deque is empty.");
        return getByRawIndex(--tail);
    }
    public int get(int index) {
        index += head + 1;
        if (index >= tail) throw new IndexOutOfBoundsException("Index " + index + " out of bounds for length " + size());
        return getByRawIndex(index);
    }
    public int getFirst() {return get(0);}
    public int getLast() {return get(size() - 1);}
    public void map(int index, final IntUnaryOperator f) {
        index += head + 1;
        if (index >= tail) throw new IndexOutOfBoundsException("Index " + index + " out of bounds for length " + size());
        mapByRawIndex(index, f);
    }
    public void mapFirst(final IntUnaryOperator f) {map(0, f);}
    public void mapLast(final IntUnaryOperator f) {map(size() - 1, f);}
    public int size() {return tail - head - 1;}
    public void clear(boolean shrink) {
        head = -1; tail = 0;
        if (shrink) {
            p = new int[DEFAULT_SIZE];
            n = new int[DEFAULT_SIZE];
        }
    }
    public int[] toArray() {
        final int size = size();
        final int[] a = new int[size];
        for (int i = 0; i < size; i++) a[i] = get(i);
        return a;
    }
    private void growPos() {
        final int pSize = p.length;
        final int[] pCopy = new int[pSize << 1];
        System.arraycopy(p, 0, pCopy, 0, pSize);
        p = pCopy;
    }
    private void growNeg() {
        final int nSize = n.length;
        final int[] nCopy = new int[nSize << 1];
        System.arraycopy(n, 0, nCopy, 0, nSize);
        n = nCopy;
    }
    private int getByRawIndex(final int index) {
        if (index >= 0) return p[index];
        else return n[-(index + 1)];
    }
    private void putByRawIndex(final int index, final int v) {
        if (index < 0) {
            if (index <= -(n.length + 1)) growNeg();
            n[-(index + 1)] = v;
        } else {
            if (index >= p.length) growPos();
            p[index] = v;
        }
    }
    private void mapByRawIndex(final int index, final IntUnaryOperator f) {
        if (index >= 0) p[index] = f.applyAsInt(p[index]);
        else n[-(index + 1)] = f.applyAsInt(n[-(index + 1)]);
    }
    public PrimitiveIterator.OfInt iterator() {return new IntDequeIterator();}
    @Override
    public String toString() {
        final StringBuilder sb = new StringBuilder();
        sb.append('[');
        for (int i = 0; i < size(); i++) {
            sb.append(get(i));
            if (i < size() - 1) sb.append(" ");
        }
        sb.append(']');
        return sb.toString();
    }
    private class IntDequeIterator implements PrimitiveIterator.OfInt {
        private int i = head;
        public boolean hasNext() {return i < tail;}
        public int nextInt() {return getByRawIndex(i++);}
    }
}

import java.util.*;
public class Main {
	static int[][] seat;	//0 退場前 1 退場後
	static int n;
	static HashMap<String, Integer> memo = new HashMap<String, Integer>();

	public static void main(String[] args){
		Scanner sc = new Scanner(System.in);
		// 文字列の入力
		String[] lineString = sc.nextLine().split(" ");
		n = Integer.parseInt(lineString[0]);
		seat = new int[n][n];

		lineString = sc.nextLine().split(" ");
		int hate = 0;
		for (int i = 0; i < n * n; i++) {
			memo.clear();
			int number = Integer.parseInt(lineString[i]) - 1;
			int row = number / n;
			int column = number % n;
			int[][] moveMap = new int[n][n];

			hate += move(row, column, moveMap, Math.min(Math.min(row, column), Math.min(n - row - 1, n - column - 1)));

			seat[row][column] = 1;
		}

		// 出力
		System.out.println(hate);
		sc.close();
	}

	static int move(int currentRow, int currentColumn, int[][] moveMap, int maxHate) {
		if (currentRow == 0 || currentColumn == 0 || currentRow == n - 1 || currentColumn == n - 1) {
			return 0;
		} else if (memo.containsKey(currentRow + "," + currentColumn)) {
			return memo.get(currentRow + "," + currentColumn);
		} else {
			int resultUp = 500;
			int resultRight = 500;
			int resultDown = 500;
			int resultLeft = 500;
			int hate = 0;
			int[][] nextMoveMap = new int[n][n];
			for (int i = 0; i < n; i++) {
				System.arraycopy(moveMap[i], 0, nextMoveMap[i], 0, n);
			}
			nextMoveMap[currentRow][currentColumn] = 1;
			//通ったことがない方向のみ探索
			//上探索
			if (moveMap[currentRow - 1][currentColumn] == 0) {
				if (seat[currentRow - 1][currentColumn] == 0) {
					hate = 1;
				} else {
					hate = 0;
				}
				resultUp = hate + move(currentRow - 1, currentColumn, nextMoveMap, maxHate);
			}
			//右探索
			if (moveMap[currentRow][currentColumn + 1] == 0) {
				if (seat[currentRow][currentColumn + 1] == 0) {
					hate = 1;
				} else {
					hate = 0;
				}
				resultRight = hate + move(currentRow, currentColumn + 1, nextMoveMap, maxHate);
			}
			//下探索
			if (moveMap[currentRow + 1][currentColumn] == 0) {
				if (seat[currentRow + 1][currentColumn] == 0) {
					hate = 1;
				} else {
					hate = 0;
				}
				resultDown = hate + move(currentRow + 1, currentColumn, nextMoveMap, maxHate);
			}
			//左探索
			if (moveMap[currentRow][currentColumn - 1] == 0) {
				if (seat[currentRow][currentColumn - 1] == 0) {
					hate = 1;
				} else {
					hate = 0;
				}
				resultLeft = hate + move(currentRow, currentColumn - 1, nextMoveMap, maxHate);
			}
			int result = Math.min(Math.min(resultUp, resultRight), Math.min(resultDown, resultLeft));
			memo.put(currentRow + "," + currentColumn, result);
			return result;
		}
	}
}

