import java.util.Arrays;
import java.util.Deque;

public class Main {
	public static void main(String[] args) throws Exception {
		BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
		String[] sa = br.readLine().split(" ");
		int n = Integer.parseInt(sa[0]);
		int n2 = n * n;
		int[] p = new int[n2];
		sa = br.readLine().split(" ");
		for (int i = 0; i < n2; i++) {
			p[i] = Integer.parseInt(sa[i]) - 1;
		}
		br.close();

		int[][] a = new int[n][n];
		for (int i = 0; i < n; i++) {
			Arrays.fill(a[i], 1);
		}

		int[] dx = {-1, 1, 0, 0};
		int[] dy = {0, 0, -1, 1};
		int ans = 0;
		for (int i = 0; i < n2; i++) {
			int[][] d = new int[n][n];
			for (int j = 0; j < n; j++) {
				Arrays.fill(d[j], 512);
			}
			int x = p[i] / n;
			int y = p[i] % n;
			d[x][y] = 0;
			a[x][y] = 0;
			Deque<Integer> que = new ArrayDeque<>();
			que.add(p[i]);
			label:
			while (!que.isEmpty()) {
				int cur = que.poll();
				int cx = cur / n;
				int cy = cur % n;
				for (int k = 0; k < 4; k++) {
					int nx = cx + dx[k];
					int ny = cy + dy[k];
					if (0 <= nx && nx < n && 0 <= ny && ny < n) {
						int alt = d[cx][cy] + a[nx][ny];
						if (alt < d[nx][ny]) {
							if (alt == d[cx][cy]) {
								que.addFirst(nx * n + ny);
							} else {
								que.addLast(nx * n + ny);
							}
							d[nx][ny] = alt;
						}
					} else {
						ans += d[cx][cy];
						break label;
					}
				}
			}
		}
		System.out.println(ans);
	}
}

import java.util.ArrayDeque;
import java.util.Queue;
import java.util.Scanner;


public class Main {

	public static void main(String[] args) {
		Scanner sc = new Scanner(System.in);
		int N = sc.nextInt();
		int P[][] = new int[N][N];
		for (int i=0;i<N;i++) {
			for (int j=0;j<N;j++) {
				P[i][j] = i*N+j+1;
			}
		}
		Main main = new Main();
		int count =0;

		for (int i =0;i<N*N;i++) {
			Queue<Point> queue = new ArrayDeque<Point>();
			int temp =sc.nextInt()-1;
			int tempi = temp/N;
			int tempj = temp%N;
			int min = N-tempj-1;
			Point p = main.new Point();
			p.x = tempi;
			p.y = tempj;
			p.step = 0;
			queue.add(p);
			int tempT[][] =new int[N][N];
			for (int k=0;k<N;k++) {
				for (int j=0;j<N;j++) {
					tempT[k][j] = -1;
				}
			}
			while (queue.isEmpty()==false) {
				Point t = queue.poll();
				if (t.step>=min) {
					continue;
				}
				if(t.x==0||t.y==0||t.x==N-1||t.y==N-1) {
					min = t.step;
					continue;
				}
				if (tempT[t.x][t.y]==0) {
					continue;
				}
				if (P[t.x][t.y+1]!=0) {
					p = main.new Point();
					p.x = t.x;
					p.y = t.y+1;
					p.step= t.step+1;
					queue.add(p);
				} else {
					p = main.new Point();
					p.x = t.x;
					p.y = t.y+1;
					p.step= t.step;
					tempT[t.x][t.y] = p.step;
					queue.add(p);
				}
				if (P[t.x][t.y-1]!=0) {
					p = main.new Point();
					p.x = t.x;
					p.y = t.y-1;
					p.step= t.step+1;
					queue.add(p);
				} else {
					p = main.new Point();
					p.x = t.x;
					p.y = t.y-1;
					p.step= t.step;
					tempT[t.x][t.y] = p.step;
					queue.add(p);
				}
				if (P[t.x+1][t.y]!=0) {
					p = main.new Point();
					p.x = t.x+1;
					p.y = t.y;
					p.step= t.step+1;
					queue.add(p);
				} else {
					p = main.new Point();
					p.x = t.x+1;
					p.y = t.y;
					p.step= t.step;
					tempT[t.x][t.y] = p.step;
					queue.add(p);
				}
				if (P[t.x-1][t.y]!=0) {
					p = main.new Point();
					p.x = t.x-1;
					p.y = t.y;
					p.step= t.step+1;
					queue.add(p);
				} else {
					p = main.new Point();
					p.x = t.x-1;
					p.y = t.y;
					p.step= t.step;
					tempT[t.x][t.y] = p.step;
					queue.add(p);
				}
			}
			count +=min;
			P[tempi][tempj]= 0;
		}
		System.out.println(count);
	}

	public class Point {
		int x;
		int y;
		int step;
	}

}

import java.io.BufferedReader;
