public class Main implements Runnable{

	@SuppressWarnings("static-method")
	private void solve(FastIO io, String[] args) {
		/*
		 * author: 31536000
		 * AtCoder Grand Contest 044 B問題
		 * 考察メモ
		 * 一番手軽なのは、各マスについて01BFSすること
		 * しかし、勿論O(N^4)はTLEするので……良い性質が知りたいね
		 * 考えてみると、まず最初の人は一番近い出口へ行く→一直線に移動する
		 * 明らかに、殆ど一直線に移動するケースが多いのよ
		 * そうでないケースとはどういうものかを考えてみよう
		 * 十分に内側の人であって、出るまでの距離が十分に短くなる場合があるとする
		 * するとその人の近くはその人の場所まで移動するのが最適になる場合がある
		 * これは、ある人についてそこからひし形の領域に広がる……お、なんか良さそうじゃない？
		 * 例えば
		 * 000000000
		 * 011111110
		 * 012222210
		 * 012333210
		 * 012343210
		 * 012333210
		 * 012222210
		 * 011111110
		 * 000000000
		 * みたいな状態(通り抜けるコストは見たままね)を考える
		 * 次のような状況で、xの人が通り抜けたいとする
		 * 000000000
		 * 011111110
		 * 012222210
		 * 012333210
		 * 012343210
		 * 012333210
		 * 012x22210
		 * 011#11110
		 * 000#00000
		 * すると、周囲にひし形に、x+1, x+2, ...が伝播して、これと元の値のminを取りたくなるのね
		 * 区間min更新1点取得、これは相対セグ木では？
		 * 斜めは2本あれば再現できて、計算量はO(N^3logN)になる……重くないか
		 * ここで、xの伝播する範囲はもっと狭いのではないかという予想が立つ
		 * 例えば上の例の場合、実際はこう
		 * 000000000
		 * 011111110
		 * 012222210
		 * 012333210
		 * 012233210
		 * 012123210
		 * 011x12210
		 * 010#01110
		 * 000#00000
		 * で、xによって更新が書けられる範囲は$にした場所だけ
		 * 000000000
		 * 011111110
		 * 012222210
		 * 012$33210
		 * 012$$3210
		 * 01$$$$210
		 * 01$x$$210
		 * 010#01110
		 * 000#00000
		 * あら、結構広い……
		 *
		 * お、面白い性質に気付いた
		 * 上のような構築、盤面全体の数値の合計を求める
		 * Σ[i=0, N/2] 4i * (N - 2i - 1)=O(N^3), 最大でも20808500
		 * また、xの更新で下がる時、盤面全体の数値は単調減少
		 * つまり減るところだけ愚直BFSで間に合う
		 */
		int N = io.nextInt();
		int[][] dist = new int[N + 2][N + 2];
		for (int y = 1;y <= N;++ y) {
			for (int x = 1;x <= N;++ x) {
				dist[y][x] = 1 + Math.min(Math.min(y - 1, x - 1), Math.min(N - y, N - x));
			}
		}
		int[] P = io.nextInt(N * N);
		BreadthFirstSearch<Point> bfs = new BreadthFirstSearch<>();
		int ans = 0;
		int[][] exist = new int[N + 2][N + 2];
		for (int[] i : exist) Arrays.fill(i, 1);
		for (int i : P) {
			int y = (i + N - 1) / N, x = (i - 1) % N + 1;
			ans += -- dist[y][x];
			exist[y][x] = 0;
			bfs.push(new Point(x, y));
			for (Point p : bfs) {
				if (dist[p.y][p.x - 1] > dist[p.y][p.x] + exist[p.y][p.x - 1]) {
					dist[p.y][p.x - 1] = dist[p.y][p.x] + exist[p.y][p.x - 1];
					bfs.push(new Point(p.x - 1, p.y));
				}
				if (dist[p.y][p.x + 1] > dist[p.y][p.x] + exist[p.y][p.x + 1]) {
					dist[p.y][p.x + 1] = dist[p.y][p.x] + exist[p.y][p.x + 1];
					bfs.push(new Point(p.x + 1, p.y));
				}
				if (dist[p.y - 1][p.x] > dist[p.y][p.x] + exist[p.y - 1][p.x]) {
					dist[p.y - 1][p.x] = dist[p.y][p.x] + exist[p.y - 1][p.x];
					bfs.push(new Point(p.x, p.y - 1));
				}
				if (dist[p.y + 1][p.x] > dist[p.y][p.x] + exist[p.y + 1][p.x]) {
					dist[p.y + 1][p.x] = dist[p.y][p.x] + exist[p.y + 1][p.x];
					bfs.push(new Point(p.x, p.y + 1));
				}
			}
			bfs.clear();
			//io.debugln(i);
			//io.debugln(dist);
		}
		io.println(ans);
	}

