    void solve() {
        int n = in.nextInt();
        int[] dist = new int[n * n];
        int[] exist = new int[n * n];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                exist[i * n + j] = 1;
                dist[i * n + j] = Math.min(Math.min(i + 1, j + 1), Math.min(n - i, n - j));
            }
        }
        long ans = 0;
        Deque<Integer> deque = new ArrayDeque<>();
        for (int i = 0; i < n * n; i++) {
            int p = in.nextInt() - 1;
            System.out.println(p + ", " + Arrays.toString(dist));
            dist[p]--;
