                    matrix[i + 1][j] = matrix[i][j] + (bbb[i][j] ? 0 : 1);
                    ii.add(i + 1);
                    jj.add(j);
                }
                if (j - 1 >= 0 && matrix[i][j] + (bbb[i][j] ? 0 : 1) < matrix[i][j - 1]) {
                    matrix[i][j - 1] = matrix[i][j] + (bbb[i][j] ? 0 : 1);
