    final static int MOD = (int)1e9+7;

    void solve(){
        int N = in.nextInt();
        int[] P = in.nextIntArrayDec(N*N);

        SegmentTree[] h = new SegmentTree[N], w = new SegmentTree[N];
        long[] init = new long[N+2];
        Arrays.fill(init, 1);
        init[0] = init[N+1] = 0;
        for(int i = 0; i < N; i++){
            h[i] = new SegmentTree(init);
            w[i] = new SegmentTree(init);
        }

        long ans = 0;
        for(int i = 0; i < N * N; i++){
            int p = P[i];
            long min = Long.MAX_VALUE;
            min = Math.min(min, h[p/N].getSegment(0, p%N+1));
            min = Math.min(min, h[p/N].getSegment(p%N+2, N+2));
            min = Math.min(min, w[p%N].getSegment(0, p/N+1));
            min = Math.min(min, w[p%N].getSegment(p/N+2, N+2));
            ans += min;
            h[p/N].setPoint(p%N+1, 0);
            w[p%N].setPoint(p/N+1, 0);
        }
        out.println(ans);
    }

    class SegmentTree{
        int d;
        long[] node;

        /*二項演算で使える単位元*/
        private long e = 0;

        /*結合律が成り立つ、要素同士の二項演算*/
        private long f(long e1, long e2){
            return e1 + e2; //区間和
        }

        /*要素更新用の演算(可換でなくてもよい)*/
        private long g(long nodeVal, long val){
            return val; //更新
        }

        /* 単位元で初期化 */
        public SegmentTree(int sz){
            long[] v = new long[sz];
            Arrays.fill(v, e);
            init(v);
        }

        /* 配列vで初期化 */
        public SegmentTree(long[] v){
            init(v);
        }

        private void init(long[] v){
            d = 1;
            while(d < v.length) d *= 2;
            node = new long[2*d];
            for(int i = 0; i < v.length; i++)
                node[i+d] = v[i];
            for(int i = d-1; i > 0; i--)
                node[i] = f(node[2*i], node[2*i+1]);
        }

        public long getPoint(int x){
            return node[x+d];
        }

        /* 0-indexed:xの要素をg(node[x], val)に更新 */
        public void setPoint(int x, long val){
            x += d;
            node[x] = g(node[x], val);
            while(x > 1){
                x = x / 2;
                node[x] = f(node[2*x], node[2*x+1]);
            }
        }

        /* 指定した区間[L,R)の区間演算の結果を求めるクエリ */
        public long getSegment(int L, int R){
            L += d;
            R += d;
            long resL = e, resR = e;
            while (L < R) {
                if ((L & 1) != 0){
                    resL = f(resL, node[L]);
                    L++;
                }
                if ((R & 1) != 0){
                    --R;
                    resR = f(resR, node[R]);
                }
                L >>= 1;
                R >>= 1;
            }
            return f(resL, resR);
        }
    }

