        final FastScanner scanner = new FastScanner(System.in);
        final int n = scanner.nextInt();

        final boolean[][] isSitting = new boolean[n + 1][n + 1];
        for (final boolean[] array : isSitting) {
            Arrays.fill(array, true);
        }

        final UnaryOperator<Integer> bfs = point -> {
            final int[][] distances = new int[n + 1][n + 1];
            for (final int[] array : distances) {
                Arrays.fill(array, -1);
            }
            final int x = (point - 1) / n;
            final int y = (point - 1) % n + 1;

            isSitting[x][y] = false;
            distances[x][y] = 0;
            final Deque<Integer> queue = new ArrayDeque<>();
            queue.add(point);

            while (!queue.isEmpty()) {
                final int poll = queue.pollFirst();
                final int tmpX = (poll - 1) / n;
                final int tmpY = (poll - 1) % n + 1;
                final int distance = distances[tmpX][tmpY];
                if (tmpX == 0 || tmpX == n - 1 || tmpY == 1 || tmpY == n) {
                    return distance;
                }

                for (int i = 0; i < 4; i++) {
                    final int nextX = tmpX + xMove[i];
                    final int nextY = tmpY + yMove[i];
                    if (distances[nextX][nextY] != -1) {
                        continue;
                    }
                    queue.add(nextX * n + nextY);
                    distances[nextX][nextY] = distance + (isSitting[nextX][nextY] ? 1 : 0);
                }
            }

            return -1;
        };

        final long count = IntStream.range(0, n * n)
            .map(i -> bfs.apply(scanner.nextInt()))
            .sum();

        System.out.println(count);
    }

    private static class FastScanner {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        FastScanner(final InputStream in) {
            reader = new BufferedReader(new InputStreamReader(in));
        }

        String next() {
            if (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (final IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.util.Arrays;
import java.util.LinkedList;
import java.util.Queue;
import java.util.Scanner;

public class Main {
	static int distToEnter(int N , int row , int col){
		int ret = Math.min(row, col);
		ret = Math.min(ret, N - 1 - row);
		ret = Math.min(ret, N - 1 - col);
		return ret;
	}
	static class Point{
		int x;
		int y;
		Point(int a , int b){
			x = a;
			y = b;
		}
	}
	static long solve(int N , int P[]){		
		int dist[][] = new int[N][N];
		int occupied[][] = new int[N][N];
		for(int i = 0 ; i < N ; ++i){
			for(int j = 0 ; j < N ; ++j){
				dist[i][j] = distToEnter(N, i, j);
				occupied[i][j] = 1;
			}
		}
		long ret = 0;
		int dx[] = { 0 , 0 , 1 , -1};
		int dy[] = { 1 ,-1 , 0 ,  0};
		for(int p : P){
			int row = p / N;
			int col = p % N;
			ret += dist[row][col];
			occupied[row][col] = 0;
			Point init = new Point(col, row);
			Queue<Point> q = new LinkedList<Point>();
			q.add(init);
			while(!q.isEmpty()){
				Point cp = q.poll();
				int d = dist[cp.y][cp.x] + occupied[cp.y][cp.x];
				for(int k = 0 ; k < 4 ; ++k){
					int nx = cp.x + dx[k];
					int ny = cp.y + dy[k];
					if(nx < 0 || ny < 0 || nx >= N || ny >= N){
						continue;
					}
//					System.out.println(dist[ny][nx]+" "+d+" "+nx+" "+ny);
					if(dist[ny][nx] > d){
						dist[ny][nx] = d;
						q.add(new Point(nx , ny));
					}
				}
			}
//			System.out.println(Arrays.deepToString(dist));
		}
		return ret;
	}
	public static void main(String[] args) {
		Scanner sc = new Scanner(System.in);
		int N = sc.nextInt();
		int P[] = new int[N * N];
		for(int i = 0 ; i < P.length ; ++i){
			P[i] = sc.nextInt() - 1;
		}
		System.out.println(solve(N , P));
	}
}

