            cnt += min;
        }

        System.out.println(cnt);

    }
}

class BinaryIndexedTree{
    int size;
    long[] tree;

    public BinaryIndexedTree(int n){
        this.size = n;
        this.tree = new long[n+1];
    }

    public long sum(int i){
        long s = 0L;
        while(0<i){
            s += tree[i];
            i -= i & -i;
        }
        return s;
    }

    public void add(int i, int x){
        while(i<=size){
            tree[i] += x;
            i += i & -i;
        }
    }
}

import java.util.*;
public class Main {
	public static void main(String[] args) {
		Scanner sc = new Scanner(System.in);
		int N = sc.nextInt();
		int[][] dir = new int[][] {{1,0},{-1,0},{0,1},{0,-1}};
		boolean[][] arr = new boolean[N][N];
		int res = 0;
		for(int i = 0; i < N*N; i++) {
			Queue<int[]> q = new LinkedList<>();
			boolean[][] visit = new boolean[N][N];
			int num = sc.nextInt();
			q.offer(new int[] {(num - 1) / N, (num - 1) % N});
			visit[(num - 1) / N][(num - 1) % N] = true;
			arr[(num - 1) / N][(num - 1) % N] = true;
			boolean out = false;
			while(!q.isEmpty()) {
				int[] curr = q.poll();
				int r = curr[0];
				int c = curr[1];
				for(int j = 0; j < 4; j++) {
					int x = r + dir[j][0];
					int y = c + dir[j][1];
					if(x < 0 || x == N || y < 0 || y == N) {
						out = true;
						break;
					}
					if(arr[x][y] && !visit[x][y]) {
						q.offer(new int[] {x, y});
						visit[x][y] = true;
					}
				}
				if(out)
					break;
			}

			if(!out)
				res++;
		}
		System.out.println(res);
	}
}

import java.util.*;

public class Main {
    static int[][] DIR = new int[][]{{-1, 0}, {1, 0}, {0, -1}, {0, 1}};

    static void update(int n, int x, int y, int[][] ret, int[][] grid) {
        Queue<Integer> q = new ArrayDeque<>();
        q.add(x*n+y);
        while (!q.isEmpty()) {
            int curr = q.poll();
            int i = curr / n, j = curr % n;
            int can = ret[i][j] + grid[i][j];
            for (int[] dir : DIR) {
                int ni = i + dir[0], nj = j + dir[1];
                if (ni >= 0 && ni < n && nj >= 0 && nj < n) {
                    if (ret[ni][nj] > can) {
                        ret[ni][nj] = can;
                        q.add(ni*n+nj);
                    }
                }
            }
        }
    }

    static void solve(int N, int[] P) {
        int[][] grid = new int[N][N];
        for (int[] g : grid) Arrays.fill(g, 1);
        int[][] ret = new int[N][N];
        for (int i=0;i<N;i++) {
            for (int j=0;j<N;j++) {
                ret[i][j] = Math.min(Math.min(i, N-1-i), Math.min(j, N-1-j));
            }
        }
        int r = 0;
        for (int p : P) {
            int x = p/N, y = p%N;
            r += ret[x][y];
            grid[x][y] = 0;
            update(N, x, y, ret, grid);
        }
        System.out.println(r);
    }

    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        int N = in.nextInt();
        int[] P = new int[N*N];
        for (int i=0;i<P.length;i++) P[i] = in.nextInt() - 1;
        solve(N, P);
    }
}

