        int row = pos[0], col = pos[1];
        int minCnt = Integer.MAX_VALUE;
        for(int d = 0; d < 4; d++) {
          minCnt = Math.min(minCnt, grid[row][col][d]);
        }
        cnt += minCnt;
        // up: 0
        for(int i = n-1; i > row; i--) {
          grid[i][col][0]--;
        }
        // down: 2
        for(int i = 0; i < row; i++) {
          grid[i][col][2]--;
        }
        // left: 3
        for(int i = n-1; i > col; i--) {
          grid[row][i][3]--;
        }
