        for (int i = 0; i < (N + 1) / 2; i++) {
            for (int j = 0; j < (N + 1) / 2; j++) {
                dp[i][j] = Math.min(i, j);
                dp[i][N - 1 - j] = dp[i][j];
                dp[N - 1 - i][j] = dp[i][j];
                dp[N - 1 - i][N - 1 - j] = dp[i][j];
            }
        }


        int ans = 0;
        for (int i = 0; i < N2; i++) {
            int a = sc.nextInt();
            int row = (a - 1) / N;
            int col = (a - 1) % N;
            ans += dp[row][col];
            //TODO 更新每个人的消耗呀。
            update(dp, row, col, dp[row][col]);
            my--;

//            for (int ii = 0; ii < N; ii++) {
//                for (int j = 0; j < N; j++) {
//                    System.out.print(dp[ii][j] + "  ");
//                }
//                System.out.print("\r\n");
//            }
//            System.out.println("\r\n");
        }
        System.out.println(ans);

    }

    List<int[]> list = new ArrayList<>();

    static int my = -1;

    public static void update(int[][] dp, int x, int y, int data) {
        dp[x][y] = my;
        if (x - 1 >= 0 && data < dp[x - 1][y]) {
            if (data < dp[x - 1][y]) {
                dp[x - 1][y]--;
            } else if (dp[x - 1][y] < 0 && dp[x - 1][y] != my) {
                update(dp, x - 1, y, data);
            }
        }
        if (x + 1 < dp.length) {
            if (data < dp[x + 1][y]) {
                dp[x + 1][y]--;
            } else if (dp[x + 1][y] < 0 && dp[x + 1][y] != my) {
                update(dp, x + 1, y, data);
            }
        }

        if (y - 1 >= 0) {
            if (data < dp[x][y - 1]) {
                dp[x][y - 1]--;
            } else if (dp[x][y - 1] < 0 && dp[x][y - 1] != my) {
                update(dp, x, y - 1, data);
            }
        }

        if (y + 1 < dp.length) {
            if (data < dp[x][y + 1]) {
                dp[x][y + 1]--;
            } else if (dp[x][y + 1] < 0 && dp[x][y + 1] != my) {
                update(dp, x, y + 1, data);
            }
        }

    }


}

import java.util.Arrays;
import java.util.TreeSet;

public class Main {

  private static void solve() {
    int n = ni();
    int[] p = na(n * n);

    int[][] map = new int[n][n];
    int ptr = 0;
    for (int i = 0; i < n * n; i++) {
      p[i]--;
      int x = p[i] / n;
      int y = p[i] % n;

      map[x][y] = ptr++;
    }

    long ret = 0;
    for (int i = 0; i < n; i++) {
      for (int j = 0; j < n; j++) {
        int now = dijk(map, new int[] {i, j});
        ret += now;
      }
    }
    System.out.println(ret);
  }

  public static int dijk(int[][] map, int[] from) {
    int n = map.length;
    final int[][] td = new int[n][n];
    for (int[] v : td)
      Arrays.fill(v, Integer.MAX_VALUE / 4);
    TreeSet<int[]> q = new TreeSet<>((o1, o2) -> {
      if (td[o1[0]][o1[1]] != td[o2[0]][o2[1]]) {
        return td[o1[0]][o1[1]] - td[o2[0]][o2[1]];
      } else {
        return o1[0] != o2[0] ? o1[0] - o2[0] : o1[1] - o2[1];
      }
    });
    q.add(from);
    td[from[0]][from[1]] = 0;

    int v = map[from[0]][from[1]];

    int[][] dir = {{0, 1}, {0, -1}, {1, 0}, {-1, 0}};
    while (q.size() > 0) {
      int[] cur = q.pollFirst();
      int cx = cur[0];
      int cy = cur[1];

      for (int[] d : dir) {
        int nx = cx + d[0];
        int ny = cy + d[1];
        if (nx < 0 || nx >= n || ny < 0 || ny >= n)
          return td[cx][cy];

        int nd = td[cx][cy] + (v < map[nx][ny] ? 1 : 0);
        if (nd < td[nx][ny]) {
          int[] next = {nx, ny};
          q.remove(next);
          td[nx][ny] = nd;
          q.add(next);
        }
      }
    }
    return -1;
  }

