public partial class Deque<T> {
    private T[] _array;
    private int _head;
    private int _tail;
    public int Count { get; private set; }

    public Deque(int capacity = 16) {
        _array = new T[capacity];
        _head = 0;
        _tail = 0;
    }

    public void Clear() {
        _head = _tail = Count = 0;
    }

    public void PushBack(T value) {
        if (Count + 1 == _array.Length) { // expand
            Expand();
        }
        Count++;

        _array[_tail++] = value;
        if (_tail == _array.Length) {
            _tail = 0;
        }
    }

    public void PushFront(T value) {
        if (Count + 1 == _array.Length) { // expand
            Expand();
        }
        Count++;

        if (--_head == -1) {
            _head += _array.Length;
        }
        _array[_head] = value;
    }

    public T PopBack() {
        if (Count == 0) {
            throw new Exception("empty");
        }

        Count--;
        if (--_tail == -1) {
            _tail += _array.Length;
        }
        return _array[_tail];
    }

    public T PeekBack() {
        if (Count == 0) {
            throw new Exception("empty");
        }

        return this[Count - 1];
    }

    public T PopFront() {
        if (Count == 0) {
            throw new Exception("empty");
        }

        var ret = _array[_head];
        Count--;
        if (++_head == _array.Length) {
            _head = 0;
        }
        return ret;
    }

    public T PeekFront() {
        if (Count == 0) {
            throw new Exception("empty");
        }

        return _array[_head];
    }

    public T this[int index] {
        get {
            if (index < 0 || index >= Count) {
                throw new Exception("Invalid index");
            }
            index += _head;
            if (index >= _array.Length) index -= _array.Length;
            return _array[index];
        }
        set {
            if (index < 0 || index >= Count) {
                throw new Exception("Invalid index");
            }
            index += _head;
            if (index >= _array.Length) index -= _array.Length;
            _array[index] = value;
        }
    }

    private void Expand() {
        var newarray = new T[_array.Length * 2];

        if (_head < _tail) {
            Array.Copy(_array, _head, newarray, 0, Count);
        } else {
            Array.Copy(_array, _head, newarray, 0, _array.Length - _head);
            Array.Copy(_array, 0, newarray, _array.Length - _head, _tail);
        }

        _array = newarray;
        _head = 0;
        _tail = Count == newarray.Length ? 0 : Count;
    }

}
internal partial class Solver {

    public int[] dx = new int[] { 0, 1, 0, -1 };
    public int[] dy = new int[] { 1, 0, -1, 0 };

    public void Run() {
        var n = ni();
        var p = ni(n * n);
        //n = 500; p = E.Range(1, n * n).ToArray();
        var a = new int[n, n];
        var cost = new int[n, n];
        var weight = new int[n, n];
        var rows = new int[n * n];
        var cols = new int[n * n];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                var val = i * n + j;
                a[i, j] = val;
                weight[i, j] = 1;
                rows[val] = i;
                cols[val] = j;
                cost[i, j] = Math.Min(Math.Min(i, n - 1 - i), Math.Min(j, n - 1 - j));
            }
        }
        long ans = 0;
        var queue = new Deque<(int, int, int)>(n * n);
        var next = new Deque<(int, int, int)>(n * n);
        for (int i = 0; i < p.Length; i++) {
            var row = rows[p[i] - 1];
            var col = cols[p[i] - 1];

            ans += cost[row, col];
            weight[row, col] = 0;

            int minAdjCost = int.MaxValue;

            for (int k = 0; k < 4; k++) {
                var nr = row + dy[k];
                var nc = col + dx[k];
                if (0 <= nr && nr < n && 0 <= nc && nc < n) {
                    minAdjCost = Math.Min(minAdjCost, cost[nr, nc]);
                } else {
                    minAdjCost = -1;
                }
            }

            if (cost[row, col] > minAdjCost) {
                queue.PushBack((row, col, minAdjCost));
                while (queue.Count > 0) {
                    while (queue.Count > 0) {
                        var (crow, ccol, step) = queue.PopFront();
                        if (cost[crow, ccol] <= step) continue;
                        cost[crow, ccol] = step;
                        for (int k = 0; k < 4; k++) {
                            var nr = crow + dy[k];
                            var nc = ccol + dx[k];
                            if (0 <= nr && nr < n && 0 <= nc && nc < n) {
                                var w = weight[nr, nc];
                                if (cost[nr, nc] > step + w) {
                                    if (w == 0) {
                                        queue.PushBack((nr, nc, step));
                                    } else {
                                        next.PushBack((nr, nc, step + 1));
                                    }
                                }
                            }
                        }
                    }
                    Swap(ref queue, ref next);
                }
                //cost.Dump();
            }
        }

        cout.WriteLine(ans);
    }

    public static void Swap<T>(ref T lhs, ref T rhs) { T temp; temp = lhs; lhs = rhs; rhs = temp; }
