public class FastQueue<T> {
    private T[] _array;
    private int _head;
    private int _tail;
    public int Count { get; private set; }

    public FastQueue(int capacity = 16) {
        _array = new T[capacity];
        _head = 0;
        _tail = 0;
    }

    public void Clear() {
        _head = _tail = Count = 0;
    }

    private void Expand() {
        var newNodes = new T[_array.Length * 2];

        if (_head < _tail) {
            Array.Copy(_array, _head, newNodes, 0, Count);
        } else {
            Array.Copy(_array, _head, newNodes, 0, _array.Length - _head);
            Array.Copy(_array, 0, newNodes, _array.Length - _head, _tail);
        }

        _head = 0;
        _tail = Count == newNodes.Length ? 0 : Count;
        _array = newNodes;
    }

    public void Enqueue(T value) {
        if (Count + 1 == _array.Length) { // expand
            Expand();
        }
        Count++;
        _array[_tail++] = value;
        if (_tail == _array.Length) {
            _tail = 0;
        }
    }
    public T Dequeue() {
        var ret = _array[_head++];
        Count--;
        if (_head == _array.Length) {
            _head = 0;
        }
        return ret;
    }
}

