internal partial class Solver {

    public int[] dx = new int[] { 0, 1, 0, -1 };
    public int[] dy = new int[] { 1, 0, -1, 0 };

    public void Run() {
        var n = ni();
        var p = ni(n * n);

        //n = 500;
        //p = E.Range(1, n * n).ToArray();

        var a = new int[n, n];
        var cost = new int[n, n];
        var weight = new int[n, n];
        var rows = new int[n * n];
        var cols = new int[n * n];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                var val = i * n + j;
                a[i, j] = val;
                weight[i, j] = 1;
                rows[val] = i;
                cols[val] = j;
                cost[i, j] = Math.Min(Math.Min(i, n - 1 - i), Math.Min(j, n - 1 - j));
            }
        }
        long ans = 0;
        var visited = new BooleanArray(n * n);
        for (int i = 0; i < p.Length; i++) {
            var row = rows[p[i] - 1];
            var col = cols[p[i] - 1];

            ans += cost[row, col];
            weight[row, col] = 0;

            int minAdjCost = int.MaxValue;

            for (int k = 0; k < 4; k++) {
                var nr = row + dy[k];
                var nc = col + dx[k];
                if (0 <= nr && nr < n && 0 <= nc && nc < n) {
                    minAdjCost = Math.Min(minAdjCost, cost[nr, nc]);
                } else {
                    minAdjCost = -1;
                }
            }

            if (cost[row, col] > minAdjCost) {
                var queue = new Queue<int>();
                queue.Enqueue(row);
                queue.Enqueue(col);
                queue.Enqueue(minAdjCost);
                visited.Clear();
                while (queue.Count > 0) {
                    var next = new Queue<int>();
                    while (queue.Count > 0) {
                        var crow = queue.Dequeue();
                        var ccol = queue.Dequeue();
                        var step = queue.Dequeue();
                        if (cost[crow, ccol] <= step) continue;
                        cost[crow, ccol] = step;
                        for (int k = 0; k < 4; k++) {
                            var nr = crow + dy[k];
                            var nc = ccol + dx[k];
                            if (0 <= nr && nr < n && 0 <= nc && nc < n) {
                                var w = weight[nr, nc];
                                if (cost[nr, nc] <= step + w) continue;
                                if (w == 0) {
                                    queue.Enqueue(nr);
                                    queue.Enqueue(nc);
                                    queue.Enqueue(step);
                                } else {
                                    next.Enqueue(nr);
                                    next.Enqueue(nc);
                                    next.Enqueue(step + 1);
                                }
                            }
                        }
                    }
                    queue = next;
                }
                //cost.Dump();
            }
        }

        cout.WriteLine(ans);
    }

    public class BooleanArray {
        private readonly int[] array;
        private int trueValue = 1;

        public BooleanArray(int size) {
            array = new int[size];
        }

        public void Clear() {
            trueValue++;
        }

        public bool this[int index] {
            get {
                return array[index] == trueValue;
            }
            set {
                array[index] = value ? trueValue : trueValue - 1;
            }
        }

        public int Length {
            get {
                return array.Length;
            }
        }
    }
}

