public class Program
{
    [System.Diagnostics.DebuggerBrowsable(System.Diagnostics.DebuggerBrowsableState.Never)] private ConsoleReader cr; public Program(ConsoleReader consoleReader) { this.cr = consoleReader; }
    static void Main() => Console.WriteLine(new Program(new ConsoleReader(Console.OpenStandardInput())).Result());
    #endregion
    public string Result() => Calc() switch { bool b => b ? "Yes" : "No", double d => d.ToString("0.####################"), object o => o.ToString(), };
    public object Calc()
    {
        N = cr;
        inits = NewArray(N, 1);
        P = cr.Repeat(N * N).Select(cr => cr.Int0).Select(i => (i / N, i % N)).ToArray();

        int res = 0;

        lefts = NewArray(N, () => new BinaryIndexedTree(inits));
        rights = NewArray(N, () => new BinaryIndexedTree(inits));
        ups = NewArray(N, () => new BinaryIndexedTree(inits));
        downs = NewArray(N, () => new BinaryIndexedTree(inits));

        foreach (var (h, w) in P)
        {
            res += Math.Min(
                Math.Min(lefts[h].Sum(w), rights[h].Sum(N - w - 1)),
                Math.Min(ups[w].Sum(h), downs[w].Sum(N - h - 1))
                );
            lefts[h].Add(w, -1);
            rights[h].Add(N - w - 1, -1);
            ups[w].Add(h, -1);
            downs[w].Add(N - h - 1, -1);
        }

        return res;
    }

    int[] inits;
    BinaryIndexedTree[] lefts;
    BinaryIndexedTree[] ups;
    BinaryIndexedTree[] rights;
    BinaryIndexedTree[] downs;
    int[] costs;
    int N;
    (int h, int w)[] P;
}

[System.Diagnostics.DebuggerTypeProxy(typeof(BinaryIndexedTreeDebugView))]
class BinaryIndexedTree
{
    private int Operate(int v, int w) => v + w;
    public void Add(int i, int w)
    {
        for (++i; i < tree.Length; i += (i & -i))
            tree[i] = Operate(tree[i], w);
    }
    public int Sum(int toExclusive)
    {
        int res = 0;
        for (var i = toExclusive; i > 0; i -= (i & -i))
            res = Operate(res, tree[i]);
        return res;
    }

    public int Sum(int from, int toExclusive) => Sum(toExclusive) - Sum(from);

    private int[] tree;
    public int Length => tree.Length - 1;
    public int Slice(int from, int length) => Sum(from, from + length);

    public BinaryIndexedTree(int size)
    {
        tree = new int[size + 1];
    }
    public BinaryIndexedTree(int[] initArray) : this(initArray.Length)
    {
        System.Array.Copy(initArray, 0, tree, 1, initArray.Length);
        for (int i = 1; i < tree.Length; i++)
        {
            var ni = i + (i & -i);
            if (ni < tree.Length)
                tree[ni] = Operate(tree[i], tree[ni]);
        }
    }

    public class BinaryIndexedTreeDebugView
    {
        private BinaryIndexedTree bit;
        public BinaryIndexedTreeDebugView(BinaryIndexedTree bit)
        {
            this.bit = bit;
        }

        [System.Diagnostics.DebuggerBrowsable(System.Diagnostics.DebuggerBrowsableState.RootHidden)]
        public string[] Tree
        {
            get
            {
                var res = new string[bit.tree.Length - 1];
                for (var i = 0; i < res.Length; i++)
                {
                    res[i] = $"data:{bit.tree[i + 1]} single:{bit.Sum(i, i + 1)}";
                }
                return res;
            }
        }
    }
}

