            for (int i = 0; i < n * n; i++)
            {
                var p = ps[i];
                var startp = new P { x = (p-1) / n + 1, y = (p-1) % n + 1, d = 0 };
                var mm = new int[n + 2, n + 2];
                var done = new bool[n + 2, n + 2];
                for (int k = 0; k < n + 2; k++)
                {
                    for (int l = 0; l < n + 2; l++)
                    {
                        mm[k, l] = int.MaxValue;
                    }
                }
                var heap = new MinHeap<P>(n*n, (a,b)=>a.d.CompareTo(b.d));
                heap.Push(startp);

                while (heap.Any())
                {
                    var c = heap.Pop();
                    done[c.x, c.y] = true;
                    foreach (var next in Enumerate(c, nn, n))
                    {
                        if (done[next.x, next.y]) continue;
                        if (mm[next.x, next.y] > next.d)
                        {
                            mm[next.x, next.y] = next.d;
                            heap.Push(next);
                        }
                    }
                }

                nn[startp.x, startp.y] = true;
                sum += mm[0, 0];
            }

