        static IEnumerable<P> Enumerate(P current, bool[,] nn, int n)
        {
            if (current.x==0 || current.x==n+1 || current.y==0 || current.y==n+1)
            {
                yield break;
            }

            if (current.x == 1 || current.x == n || current.y == 1 || current.y == n)
            {
                yield return new P
                {
                    x = 0,
                    y = 0,
                    d = current.d
                };
                yield break;
            }

            yield return new P { x = current.x - 1, y = current.y, d = current.d + (nn[current.x - 1, current.y] ? 0 : 1) };
            yield return new P { x = current.x + 1, y = current.y, d = current.d + (nn[current.x + 1, current.y] ? 0 : 1) };
            yield return new P { x = current.x, y = current.y - 1, d = current.d + (nn[current.x, current.y - 1] ? 0 : 1) };
            yield return new P { x = current.x, y = current.y + 1, d = current.d + (nn[current.x, current.y + 1] ? 0 : 1) };
