	public class Program
	{
		private static readonly int[] delta4_ = { 1, 0, -1, 0, 1 };
		static void Main()
		{
			var cin = new Scanner();
			int n = cin.Int();
			int nn = n * n;
			var p = cin.ArrayInt(nn, -1);

			var nums = new int[n, n];
			int m = n / 2;
			for (int i = 0; i < m; i++) {
				for (int j = i; j < n - i; j++) {
					nums[i, j] = i;
					nums[n - 1 - i, j] = i;
					nums[j, i] = i;
					nums[j, n - 1 - i] = i;
				}
			}

			if (n % 2 == 1) {
				nums[m, m] = m;
			}

			var done = new bool[n, n];
			long ans = 0;
			for (int k = 0; k < nn; k++) {
				int i = p[k] / n;
				int j = p[k] % n;
				done[i, j] = true;
				ans += nums[i, j];

				var q = new Queue<(int i, int j)>();
				q.Enqueue((i, j));
				while (q.Count > 0) {
					var cur = q.Dequeue();
					for (int dir = 0; dir < 4; dir++) {
						int ii = cur.i + delta4_[dir];
						int jj = cur.j + delta4_[dir + 1];
						if ((uint)ii < (uint)n && (uint)jj < (uint)n) {
							int nextNum = nums[cur.i, cur.j];
							if (done[cur.i, cur.j] == false) {
								nextNum++;
							}

							if (nums[ii, jj] > nextNum) {
								nums[ii, jj] = nextNum;
								q.Enqueue((ii, jj));
							}
						}
					}
				}
			}

			Console.WriteLine(ans);
		}
	}

