	const double eps=1e-11;
	static void Main(){
		Sc sc=new Sc();
		var n=sc.I;
		var a=sc.Ia;
		var h=new int[n][];
		var g=new int[n][];
		var b=new int[n][];
		for(int i = 0;i<n;i++) {
			h[i]=new int[n];
			g[i]=new int[n];
			b[i]=new int[n];
			for(int j = 1;j<n-1;j++) {h[i][j]=Min(n-j-1,Min(n-i-1,Min(i,j)));}
		}
		var di1=new int[][]{new int[]{-1,0},new int[]{1,0},new int[]{0,-1},new int[]{0,1}};
		void Fdi(int y,int x,Action<int,int> f){for(int i=0;i<4;i++){f(y+di1[i][0],x+di1[i][1]);}}
		var qu=new Queue<Tuple<int,int>>();
		int ans=0;
		for(int i = 0;i<a.Length;i++) {
			int x=(a[i]-1)/n;
			int y=(a[i]-1)%n;
			ans+=h[x][y];
			g[x][y]=i+1;
			b[x][y]=1;
			if(y>0&&x>0&&y<n-1&&x<n-1&&b[x-1][y-1]+b[x-1][y+1]+b[x+1][y-1]+b[x+1][y+1]<=1){continue;}
			qu.Enqueue(Tuple.Create(x,y));
			while(qu.Count>0){
				var e=qu.Dequeue();
				Fdi(e.Item1,e.Item2,(xx,yy)=>{
					if(yy>=0&&xx>=0&&yy<n&&xx<n){
						h[e.Item1][e.Item2]=Min(h[e.Item1][e.Item2],h[xx][yy]+(b[xx][yy]^1));
						if(g[xx][yy]!=i+1){
							g[xx][yy]=i+1;
							qu.Enqueue(Tuple.Create(xx,yy));
						}
					}
				});
			}
		}
		Console.WriteLine("{0}",ans);
	}
}
