            }
        }

        static int countHate(int[,] map, int[,] rootmap, List<int[]> pos, int hate)
        {
            int n = map.GetLength(0);
            List<int[]> next = new List<int[]>();
            var nextMap = rootmap;
            foreach (int[] exp in pos)
            {
                if (exp[0] == 0 || exp[0] == n - 1 || exp[1] == 0 || exp[1] == n - 1)
                {
                    return hate;
                }
                if (rootmap[exp[0] - 1, exp[1]] == 0)
                {
                    next.Add(new int[] { exp[0] - 1, exp[1] });
                    if (map[exp[0] - 1, exp[1]] > 0)
                    {
                        List<int[]> nomem = new List<int[]>();
                        nomem.Add(new int[] { exp[0] - 1, exp[1] });
                        next.AddRange(makeNoMemberMap(map, nomem, nomem));
                    }
                }
                if (rootmap[exp[0] + 1, exp[1]] == 0)
                {
                    next.Add(new int[] { exp[0] + 1, exp[1] });
                    if (map[exp[0] + 1, exp[1]] > 0)
                    {
                        List<int[]> nomem = new List<int[]>();
                        nomem.Add(new int[] { exp[0] + 1, exp[1] });
                        next.AddRange(makeNoMemberMap(map, nomem, nomem));
                    }
                }
                if (rootmap[exp[0], exp[1] - 1] == 0)
                {
                    next.Add(new int[] { exp[0], exp[1] - 1 });
                    if (map[exp[0], exp[1] - 1] > 0)
                    {
                        List<int[]> nomem = new List<int[]>();
                        nomem.Add(new int[] { exp[0], exp[1] - 1 });
                        next.AddRange(makeNoMemberMap(map, nomem, nomem));
                    }
                }
                if (rootmap[exp[0], exp[1] + 1] == 0)
                {
                    next.Add(new int[] { exp[0], exp[1] + 1 });
                    if (map[exp[0], exp[1] + 1] > 0)
                    {
                        List<int[]> nomem = new List<int[]>();
                        nomem.Add(new int[] { exp[0], exp[1] + 1 });
                        next.AddRange(makeNoMemberMap(map, nomem, nomem));
                    }
                }
            }
            next.Distinct().ToList();
            foreach (int[] did in next)
            {
                rootmap[did[0], did[1]] = 1;
            }
            return countHate(map, nextMap, next, hate + 1);
        }

        static List<int[]> makeNoMemberMap(int[,] map, List<int[]> pos, List<int[]> nomem)
        {
            var NoMemberMap = nomem;
            List<int[]> next = new List<int[]>();
            int n = map.GetLength(0);
            foreach (int[] exp in pos)
            {
                if (exp[0] > 0 && map[exp[0] - 1, exp[1]] > 0 && !pos.Contains(new int[] { exp[0] - 1, exp[1] }))
                {
                    next.Add(new int[] { exp[0] - 1, exp[1] });
                }
                if (exp[1] > 0 && map[exp[0], exp[1] - 1] > 0 && !pos.Contains(new int[] { exp[0], exp[1] - 1 }))
                {
                    next.Add(new int[] { exp[0], exp[1] - 1 });
                }
                if (exp[0] < n - 1 && map[exp[0] + 1, exp[1]] > 0 && !pos.Contains(new int[] { exp[0] + 1, exp[1] }))
                {
                    next.Add(new int[] { exp[0] + 1, exp[1] });
                }
                if (exp[1] < n - 1 && map[exp[0], exp[1] + 1] > 0 && !pos.Contains(new int[] { exp[0], exp[1] + 1 }))
                {
                    next.Add(new int[] { exp[0], exp[1] + 1 });
                }
            }
            if (next.Count > 0)
            {
                NoMemberMap.AddRange(next);
                NoMemberMap = makeNoMemberMap(map, next, NoMemberMap);
            }
            return NoMemberMap;
        }
    }
}

using System;
using System.Collections;
using System.Collections.Generic;
using System.Linq;

namespace contest_Csharp
{
    class Program
    {


        static void Main(string[] args)
        {
            var sw = new System.IO.StreamWriter(Console.OpenStandardOutput()) { AutoFlush = false };
            Console.SetOut(sw);

            var vals = Console.ReadLine().Split(' ')
                .Select(x => int.Parse(x)).ToList();

            int N = vals[0];
            int ans = 0;

            List<int> P = Console.ReadLine().Split(' ')
                .Select(x => int.Parse(x)).ToList();

            //List<int> cost = new List<int>(new int[N * N]);
            int[] cost = new int[N * N];
            //List<bool> left = new List<bool>(new bool[N * N]);
            var left = new bool[N * N];

            for (int i = 0; i < N * N; i++)
            {
                cost[i] = i / N;
                cost[i] = Math.Min(cost[i], N - 1 - i / N);
                cost[i] = Math.Min(cost[i], i % N);
                cost[i] = Math.Min(cost[i], N - 1 - i % N);
            }

            foreach (var ctm in P)
            {
                ans += cost[ctm - 1];
                Queue<int> bfsQueue = new Queue<int>();
                int point = ctm - 1;
                left[ctm - 1] = true;
                bfsQueue.Enqueue(point);
                do
                {
                    point = bfsQueue.Dequeue();
                    var val = cost[point] + (left[point] ? 0 : 1);

                    if (point + N < N * N && cost[point + N] > val)
                    {
                        cost[point + N] = val;
                        bfsQueue.Enqueue(point + N);
                    }
                    if (point - N >= 0 && cost[point - N] > val)
                    {
                        cost[point - N] = val;
                        bfsQueue.Enqueue(point - N);
                    }
                    if (point % N != N - 1 && cost[point + 1] > val)
                    {
                        cost[point + 1] = val;
                        bfsQueue.Enqueue(point + 1);
                    }
                    if (point % N != 0 && cost[point - 1] > val)
                    {
                        cost[point - 1] = val;
                        bfsQueue.Enqueue(point - 1);
                    }
                } while (bfsQueue.Count() != 0);



            }

            Console.WriteLine(ans);
            Console.Out.Flush();

        }



    }

}

