                                var nstep = step + weight[nid];
                                if (cost[nid] > nstep) {
                                    dfs(nr, nc, nstep);
                                }
                            }
                        }
                    }
                    dfs(row, col, minAdjCost);
                } else {
                    var queue = new Queue<(int, int, int)>();
                    queue.Enqueue((row, col, minAdjCost));
                    while (queue.Count > 0) {
                        var (crow, ccol, step) = queue.Dequeue();
                        var id = ToIndex(crow, ccol);
                        if (cost[id] <= step) continue;
                        cost[id] = step;
                        for (int k = 0; k < 4; k++) {
                            var nr = crow + dy[k];
                            var nc = ccol + dx[k];
                            if (0 <= nr && nr < n && 0 <= nc && nc < n) {
                                var nid = ToIndex(nr, nc);
                                var w = weight[nid];
                                if (cost[nid] <= step + w) continue;
                                queue.Enqueue((nr, nc, step + w));
                            }
                        }
                    }
                }
            }
        }

