        static int n;
        static bool[,] nn;


        static int[,] mm;
        static void Main(string[] args)
        {
            n = NextInt();
            var ps = ReadIntArray();
            nn = new bool[n + 2, n + 2];

            var sum = 0;

            mm = new int[n + 2, n + 2];
            Initializemm();
            for (int i = 0; i < n * n; i++)
            {
                var p = ps[i];
                var startp = new P { x = (p-1) / n + 1, y = (p-1) % n + 1 };


                var newCost = E4(startp).Min(po => mm[po.x, po.y]);

                sum += newCost;
                mm[startp.x, startp.y] = newCost;

                nn[startp.x, startp.y] = true;
                var done = new bool[n + 2, n + 2];

                var q = new Queue<P>(n * n);
                foreach (var item in E4(startp))
                {
                    if (mm[item.x, item.y] > newCost + (nn[item.x, item.y] ? 0 : 1))
                    {
                        mm[item.x, item.y] = newCost + (nn[item.x, item.y] ? 0 : 1);
                        q.Enqueue(item);
                    }
                }
                while (q.Any())
                {
                    var next = q.Dequeue();
                    var cost = mm[next.x, next.y];
                    done[next.x, next.y] = true;
                    foreach (var item in E4(next))
                    {
                        if (done[item.x, item.y]) continue;
                        if (mm[item.x, item.y] > cost + (nn[next.x, next.y] ? 0 : 1))
                        {
                            mm[item.x, item.y] = cost + (nn[next.x, next.y] ? 0 : 1);
                            q.Enqueue(item);
                        }
                    }
                }
            }

            Console.WriteLine(sum);
