        static void Initializemm()
        {
            for (int i = 1; i <= n; i++)
            {
                for (int j = 1; j <= n; j++)
                {
                    mm[i, j] = Math.Min(Math.Min(i, n - i + 1), Math.Min(j, n - j + 1));
                }
            }
        }
        static IEnumerable<P> E4(P c)
        {
            yield return new P { x = c.x - 1, y = c.y };
            yield return new P { x = c.x + 1, y = c.y };
            yield return new P { x = c.x, y = c.y - 1 };
            yield return new P { x = c.x, y = c.y + 1 };
