public class FastQueue<T> {
    private T[] _nodes;
    private int _head;
    private int _tail;
    public int Count { get; private set; }

    public FastQueue(int capacity = 16) {
        _nodes = new T[capacity];
        _head = 0;
        _tail = 0;
    }

    public void Clear() {
        _head = _tail = Count = 0;
    }

    private void Expand() {
        var newNodes = new T[_nodes.Length * 2];

        if (_head < _tail) {
            Array.Copy(_nodes, _head, newNodes, 0, Count);
        } else {
            Array.Copy(_nodes, _head, newNodes, 0, _nodes.Length - _head);
            Array.Copy(_nodes, 0, newNodes, _nodes.Length - _head, _tail);
        }

        _head = 0;
        _tail = Count == newNodes.Length ? 0 : Count;
        _nodes = newNodes;
    }

    public void Enqueue(T value) {
        if (Count + 1 == _nodes.Length) { // expand
            Expand();
        }
        Count++;

        _nodes[_tail++] = value;
        if (_tail == _nodes.Length) _tail = 0;
        _tail %= _nodes.Length;
    }
    public T Dequeue() {
        var ret = _nodes[_head++];
        Count--;
        _head %= _nodes.Length;
        return ret;
    }
}

internal partial class Solver {

    public int[] dx = new int[] { 0, 1, 0, -1 };
    public int[] dy = new int[] { 1, 0, -1, 0 };

    public void Run() {
        var n = ni();
        var p = ni(n * n);

        //n = 500; p = E.Range(1, n * n).ToArray();

        var a = new int[n, n];
        var cost = new int[n * n];
        var weight = new int[n * n];
        var rows = new int[n * n];
        var cols = new int[n * n];
        int ToIndex(int r, int c) => r * n + c;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                var val = i * n + j;
                a[i, j] = val;
                var id = ToIndex(i, j);
                weight[id] = 1;
                rows[val] = i;
                cols[val] = j;
                cost[id] = Math.Min(Math.Min(i, n - 1 - i), Math.Min(j, n - 1 - j));
            }
        }
        long ans = 0;
        var queue = new FastQueue<(int, int, int)>((n + 2) * (n + 2));
        var next = new FastQueue<(int, int, int)>((n + 2) * (n + 2));
        for (int i = 0; i < p.Length; i++) {
            var row = rows[p[i] - 1];
            var col = cols[p[i] - 1];
            var ids = ToIndex(row, col);
            ans += cost[ids];
            weight[ids] = 0;

            int minAdjCost = int.MaxValue;

            for (int k = 0; k < 4; k++) {
                var nr = row + dy[k];
                var nc = col + dx[k];
                if (0 <= nr && nr < n && 0 <= nc && nc < n) {
                    minAdjCost = Math.Min(minAdjCost, cost[ToIndex(nr, nc)]);
                } else {
                    minAdjCost = -1;
                    break;
                }
            }

            if (cost[ids] > minAdjCost) {
                queue.Enqueue((row, col, minAdjCost));
                while (queue.Count > 0) {
                    while (queue.Count > 0) {
                        var (crow, ccol, step) = queue.Dequeue();
                        var id = ToIndex(crow, ccol);
                        if (cost[id] <= step) continue;
                        cost[id] = step;
                        {
                            var nr = crow + 1;
                            var nc = ccol + 0;
                            if (0 <= nr && nr < n && 0 <= nc && nc < n) {
                                var nid = ToIndex(nr, nc);
                                var w = weight[nid];
                                if (cost[nid] > step + w) {
                                    if (w == 0) {
                                        queue.Enqueue((nr, nc, step));
                                    } else {
                                        next.Enqueue((nr, nc, step + 1));
                                    }
                                }
                            }
                        }
                        {
                            var nr = crow + 0;
                            var nc = ccol + 1;
                            if (0 <= nr && nr < n && 0 <= nc && nc < n) {
                                var nid = ToIndex(nr, nc);
                                var w = weight[nid];
                                if (cost[nid] > step + w) {
                                    if (w == 0) {
                                        queue.Enqueue((nr, nc, step));
                                    } else {
                                        next.Enqueue((nr, nc, step + 1));
                                    }
                                }
                            }
                        }
                        {
                            var nr = crow - 1;
                            var nc = ccol + 0;
                            if (0 <= nr && nr < n && 0 <= nc && nc < n) {
                                var nid = ToIndex(nr, nc);
                                var w = weight[nid];
                                if (cost[nid] > step + w) {
                                    if (w == 0) {
                                        queue.Enqueue((nr, nc, step));
                                    } else {
                                        next.Enqueue((nr, nc, step + 1));
                                    }
                                }
                            }
                        }
                        {
                            var nr = crow + 0;
                            var nc = ccol - 1;
                            if (0 <= nr && nr < n && 0 <= nc && nc < n) {
                                var nid = ToIndex(nr, nc);
                                var w = weight[nid];
                                if (cost[nid] > step + w) {
                                    if (w == 0) {
                                        queue.Enqueue((nr, nc, step));
                                    } else {
                                        next.Enqueue((nr, nc, step + 1));
                                    }
                                }
                            }
                        }
                    }
                    Swap(ref queue, ref next);
                }
                //cost.Dump();
            }
        }

        cout.WriteLine(ans);
    }

    public static void Swap<T>(ref T lhs, ref T rhs) { T temp; temp = lhs; lhs = rhs; rhs = temp; }
}
