        static void Run()
        {
            int Testcase = 1;
            for (var _ = 0; _ < Testcase; _++) Solve();
        }
        static void Solve()
        {
            int N = Int;
            var P = ConvertAll(_ReadSplitInt, x => x - 1);

            var dp = new int[N, N];
            var used = new int[N, N];

            for(var i = 0; i < N; i++)
            {
                for(var j = 0; j < N; j++)
                {
                    dp[i, j] = Min(Min(i, j), Min(N - i - 1, N - j - 1));
                    used[i, j] = 1;
                }
            }
            var BFS = new Queue<int>();
            long ans = 0;
            for(var l = 0; l < N * N; l++)
            {
                int pi = P[l] / N;
                int pj = P[l] % N;
                BFS.Enqueue(P[l]);
                ans += dp[pi, pj];
                used[pi, pj] = 0;
                while (BFS.Any())
                {
                    var t = BFS.Dequeue();
                    int i = t / N;
                    int j = t % N;
                    for(var k = 0; k < 4; k++)
                    {
                        int ni = i + dI[k];
                        int nj = j + dJ[k];
                        if (0 <= ni && ni < N && 0 <= nj && nj < N)
                        {
                            if (dp[ni, nj] > dp[i, j] + used[i, j])
                            {
                                dp[ni, nj] = dp[i, j] + used[i, j];
                                BFS.Enqueue(ni * N + nj);
                            }
                        }
                    }
                }
            }
            OutL(ans);

        }


