				for (int j = i; j < n - i; j++) {
					nums[i, j] = i;
					nums[n - 1 - i, j] = i;
					nums[j, i] = i;
					nums[j, n - 1 - i] = i;
				}
			}

			if (n % 2 == 1) {
				nums[m, m] = m;
			}

			var done = new bool[n, n];

			long ans = 0;
			for (int i = 0; i < nn; i++) {
				int ii = p[i] / n;
				int jj = p[i] % n;
				done[ii, jj] = true;
				ans += nums[ii, jj];

				var q = new Queue<(int ti, int tj)>();
				int nextNum = nums[ii, jj];
				Helper.DoAt4(ii, jj, n, n, (iii, jjj) => {
					if (nums[iii, jjj] > nextNum) {
						nums[iii, jjj] = nextNum;
						q.Enqueue((iii, jjj));
					}
				});

				while (q.Count > 0) {
					var cur = q.Dequeue();
					Helper.DoAt4(cur.ti, cur.tj, n, n, (iii, jjj) => {
						int nnext = nextNum;
						if (done[cur.ti, cur.tj] == false) {
							nnext++;
						}

						if (nums[iii, jjj] > nnext) {
							nums[iii, jjj] = nnext;
							q.Enqueue((iii, jjj));
						}
					});
				}
			}

			Console.WriteLine(ans);
		}
	}

