            var used = new int[N * N];

            for(var i = 0; i < N; i++)
            {
                for(var j = 0; j < N; j++)
                {
                    dp[i * N + j] = Min(Min(i, j), Min(N - i - 1, N - j - 1));
                    used[i * N + j] = 1;
                }
