	public class Program
	{
		private static readonly int[] delta4_ = { 1, 0, -1, 0, 1 };
		static void Main()
		{
			var cin = new Scanner();
			int n = cin.Int();
			int nn = n * n;
			var p = cin.ArrayInt(nn, -1);

			var nums = new int[n, n];
			int m = n / 2;
			for (int i = 0; i < m; i++) {
				for (int j = i; j < n - i; j++) {
					nums[i, j] = i;
					nums[n - 1 - i, j] = i;
					nums[j, i] = i;
					nums[j, n - 1 - i] = i;
				}
			}

			if (n % 2 == 1) {
				nums[m, m] = m;
			}

			var done = new bool[n, n];

			long ans = 0;
			for (int i = 0; i < nn; i++) {
				int ii = p[i] / n;
				int jj = p[i] % n;
				done[ii, jj] = true;
				ans += nums[ii, jj];

				var q = new Queue<(int ti, int tj)>();
				int nextNum = nums[ii, jj];
				for (int nnn = 0; nnn < 4; nnn++) {
					int iii = ii + delta4_[n];
					int jjj = jj + delta4_[n + 1];
					if ((uint)iii < (uint)n && (uint)jjj < (uint)n) {
						if (nums[iii, jjj] > nextNum) {
							nums[iii, jjj] = nextNum;
							q.Enqueue((iii, jjj));
						}
					}
				}

				while (q.Count > 0) {
					var cur = q.Dequeue();
					for (int nnn = 0; nnn < 4; nnn++) {
						int iii = ii + delta4_[n];
						int jjj = jj + delta4_[n + 1];
						if ((uint)iii < (uint)n && (uint)jjj < (uint)n) {
							int nnext = nums[cur.ti, cur.tj];
							if (done[cur.ti, cur.tj] == false) {
								nnext++;
							}

							if (nums[iii, jjj] > nnext) {
								nums[iii, jjj] = nnext;
								q.Enqueue((iii, jjj));
							}
						}
					}
				}
			}

			Console.WriteLine(ans);
		}
	}

