class Solver
{
    public void Solve(Scanner sc)
    {
        var N = sc.Int;
        var dist = new int[N * N];
        for(int i=0;i<N;i++)
            for (int j = 0; j < N; j++)
            {
                dist[i * N + j] = Min(i, Min(j, Min(N - i - 1, N - j - 1)));
            }
        var Q = new Queue<int>();
        var res = 0L;
        var use = new bool[N * N];
        for (int i = 0; i < N*N; i++)
        {
            var p = sc.Next<int>() - 1;
            int h = p / N, w = p % N;
            res += dist[p];
            use[p] = true;
            Q.Enqueue(h * N + w);
            while (Q.Any())
            {
                var c = Q.Dequeue();
                h = c / N;w = c % N;
                var d = dist[h * N + w];
                if (!use[h * N + w]) d++;
                for (int k = 0; k < 4; k++)
                {
                    int y = gh[k] + h, x = gw[k] + w;
                    if (!Inside(y, x, N, N)) continue;
                    if (chmin(ref dist[y * N + x], d))
                        Q.Enqueue(y * N + x);
                }
            }
        }
        Console.WriteLine(res);
    }
    int[] gh = new[] { 0, 0, 1, -1 }, gw = new[] { 1, -1, 0, 0 };
    public static bool Inside(int h, int w, int H, int W)
        => 0 <= h && h < H && 0 <= w && w < W;
}

