                    tmpRow = seat[0];
                    tmpCol = seat[1] + 1;
                    if (tmpCol < n && !isFound[tmpRow, tmpCol] && seats[tmpRow, tmpCol] > 0 && seats[tmpRow, tmpCol] > seats[seat[0], seat[1]] + (exists[seat[0], seat[1]] ? 1 : 0))
                    {
