public class FastQueue<T> {
    private T[] _nodes;
    private int _head;
    private int _tail;
    public int Count { get; private set; }

    public FastQueue(int capacity = 16) {
        _nodes = new T[capacity];
        _head = 0;
        _tail = 0;
    }

    public void Clear() {
        _head = _tail = Count = 0;
    }

    public void Enqueue(T value) {
        Count++;
        if (Count == _nodes.Length) { // expand
            var newNodes = new T[_nodes.Length * 2];
            int nTail = 0;
            while (_head != _tail) {
                newNodes[nTail++] = _nodes[_head];
                _head++;
                if (_head == _nodes.Length) _head = 0;
            }
            _head = 0;
            _tail = nTail;
            _nodes = newNodes;
        }

        _nodes[_tail++] = value;
        if (_tail == _nodes.Length) {
            _tail = 0;
        }
    }
    public T Dequeue() {
        var ret = _nodes[_head];
        Count--;
        if (++_head == _nodes.Length) {
            _head = 0;
        }
        return ret;
    }
}

