            var used = new int[N * N];

            for(var i = 0; i < N; i++)
            {
                for(var j = 0; j < N; j++)
                {
                    dp[i * N + j] = Min(Min(i, j), Min(N - i - 1, N - j - 1));
                    used[i * N + j] = 1;
                }
            }
            var BFS = new Queue<int>();
            long ans = 0;
            for(var l = 0; l < N * N; l++)
            {
                BFS.Enqueue(P[l]);
                ans += dp[P[l]];
                used[P[l]] = 0;
                while (BFS.Any())
                {
                    var t = BFS.Dequeue();
                    int i = t / N;
                    int j = t % N;
                    for(var k = 0; k < 4; k++)
                    {
                        int ni = i + dI[k];
                        int nj = j + dJ[k];
                        if (0 <= ni && ni < N && 0 <= nj && nj < N)
                        {
                            if (dp[ni * N + nj] > dp[i * N + j] + used[i * N + j])
                            {
                                dp[ni * N + nj] = dp[i * N + j] + used[i * N + j];
                                BFS.Enqueue(ni * N + nj);
                            }
                        }
                    }
                }
            }
