class Queue<T> {
    T[] nodes;
    public int Head;
    public int Tail;
    public int Count = 0;

    public Queue(int size) {
        nodes = new T[size];
        this.Head = 0;
        this.Tail = 0;
    }

    public void Clear() {
        Head = Tail = Count = 0;
    }

    public void Enqueue(T value) {
        nodes[Tail] = value;
        Tail++;
        Count++;
        if (Tail >= nodes.Length) {
            Tail = 0;
        }
    }
    public T Dequeue() {
        int ret = Head;
        Head++;
        Count--;
        if (Head >= nodes.Length) {
            Head = 0;
        }
        return nodes[ret];
    }
}
