                    int t = s.Count() - s.LowerBound(p[i + n * j].Item2);
                    ans[i + n * j] = Math.Min(ans[i + n * j], t);
                    //u[i + n * j] = t;
                    s.Insert(p[i + n * j].Item2);
                }
                s.Clear();
            }
