        {
            int N = Int;
            var P = ConvertAll(_ReadSplitInt, x => x - 1);

            var dp = new int[N, N];
            var used = new bool[N, N];

            for(var i = 0; i < N; i++)
            {
                for(var j = 0; j < N; j++)
                {
                    dp[i, j] = Min(Min(i, j), Min(N - i - 1, N - j - 1));
                }
            }
            var BFS = new Queue<Tuple<int, int>>();
            long ans = 0;
            for(var l = 0; l < N * N; l++)
            {
                BFS.Enqueue(new Tuple<int, int>(P[l] / N, P[l] % N));
                ans += dp[P[l] / N, P[l] % N];
                used[P[l] / N, P[l] % N] = true;
                while (BFS.Any())
                {
                    var t = BFS.Dequeue();
                    int i = t.Item1;
                    int j = t.Item2;
                    for(var k = 0; k < 4; k++)
                    {
                        int ni = i + dI[k];
                        int nj = j + dJ[k];
                        if (0 <= ni && ni < N && 0 <= nj && nj < N)
                        {
                            int nxt = dp[i, j];
                            if (!used[i, j]) nxt++;
                            if (dp[ni, nj] > nxt)
                            {
                                dp[ni, nj] = nxt;
                                BFS.Enqueue(new Tuple<int, int>(ni, nj));
                            }
                        }
                    }
                }
            }
