class Solver
{
    int[][] dp;
    int N;
    int[] P;
    public void Solve(Scanner sc)
    {
        N = sc.Int;
        P = sc.ArrInt;
        dp = Create(N + 2, () => Create(N + 2, () => N));
        for(int i = 0; i <= N + 1; i++)
        {
            dp[0][i] = -1;
            dp[i][0] = -1;
            dp[i][N + 1] = -1;
            dp[N + 1][i] = -1;
        }
        for (int i = 1; i <= N; i++)
            for (int j = 1; j <= N; j++)
            {
                dp[i][j] = Min(i - 1, Min(j - 1, Min(N - i, N - j)));
            }
        var res = 0L;
        var use = Create(N + 2, () => new bool[N + 2]);
        for(int i = 0; i < P.Length; i++)
        {
            P[i]--;
            int h = P[i] / N + 1, w = P[i] % N + 1;
            for (int j = 1; j <= h; j++)
            {
                chmin(ref dp[j][w], dp[j - 1][w] + (use[j][w] ? 0 : 1));
            }
            for(int j = 1; j <= w; j++)
            {
                chmin(ref dp[h][j], dp[h][j - 1] + (use[h][j] ? 0 : 1));
            }
            for (int j = N; j >=h; j--)
            {
                chmin(ref dp[j][w], dp[j + 1][w] + (use[j][w] ? 0 : 1));
            }
            for (int j = N; j >= w; j--)
            {
                chmin(ref dp[h][j], dp[h][j + 1] + (use[h][j] ? 0 : 1));
            }
            Console.WriteLine(string.Join("\n", dp.Select(v=>string.Join(" ",v))));
            Console.WriteLine();
            res += dp[h][w];
            use[h][w] = true;
            eval(h, w, true);
            for (int j = h-1; j>=0; j--)
            {
                chmin(ref dp[j][w], dp[j + 1][w] + (use[j][w] ? 0 : 1));
            }
            for (int j = w-1; j>=0; j--)
            {
                chmin(ref dp[h][j], dp[h][j + 1] + (use[h][j] ? 0 : 1));
            }
            for (int j = h+1; j <= N; j++)
            {
                chmin(ref dp[j][w], dp[j - 1][w] + (use[j][w] ? 0 : 1));
            }
            for (int j = w + 1; j <= N; j++)
            {
                chmin(ref dp[h][j], dp[h][j - 1] + (use[h][j] ? 0 : 1));
            }
        }
        Console.WriteLine(res);
    }
    void eval(int h, int w, bool rem = false)
    {
        for (int j = 0; j < 4; j++)
        {
            int y = gh[j] + h, x = gw[j] + w;
            if (!Inside(y, x, N + 2, N + 2)) continue;
            chmin(ref dp[h][w], dp[y][x] + (rem ? 0 : 1));
        }
    }
    int[] gh = new[] { 0, 0, 1, -1 }, gw = new[] { 1, -1, 0, 0 };
    public static bool Inside(int h, int w, int H, int W)
        => 0 <= h && h < H && 0 <= w && w < W;
}

