class Queue<T> {
    T[] nodes;
    public int Head;
    public int Tail;
    public int Count = 0;

    public Queue(int size) {
        nodes = new T[size];
        this.Head = 0;
        this.Tail = 0;
    }

    public void Clear() {
        Head = Tail = Count = 0;
    }

    public void Enqueue(T value) {
        nodes[Tail] = value;
        Tail++;
        Count++;
        if (Tail >= nodes.Length) {
            Tail = 0;
        }
    }
    public T Dequeue() {
        int ret = Head;
        Head++;
        Count--;
        if (Head >= nodes.Length) {
            Head = 0;
        }
        return nodes[ret];
    }
}
internal partial class Solver {

    public int[] dx = new int[] { 0, 1, 0, -1 };
    public int[] dy = new int[] { 1, 0, -1, 0 };

    public void Run() {
        var n = ni();
        var p = ni(n * n);
        var a = new int[n, n];
        var cost = new int[n, n];
        var weight = new int[n, n];
        var rows = new int[n * n];
        var cols = new int[n * n];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                var val = i * n + j;
                a[i, j] = val;
                weight[i, j] = 1;
                rows[val] = i;
                cols[val] = j;
                cost[i, j] = Math.Min(Math.Min(i, n - 1 - i), Math.Min(j, n - 1 - j));
            }
        }
        long ans = 0;
        var visited = new BooleanArray(n * n);
        var queue = new Queue<int>((n + 2) * (n + 2) * 3);
        var next = new Queue<int>((n + 2) * (n + 2) * 3);
        for (int i = 0; i < p.Length; i++) {
            var row = rows[p[i] - 1];
            var col = cols[p[i] - 1];

            ans += cost[row, col];
            weight[row, col] = 0;

            int minAdjCost = int.MaxValue;

            for (int k = 0; k < 4; k++) {
                var nr = row + dy[k];
                var nc = col + dx[k];
                if (0 <= nr && nr < n && 0 <= nc && nc < n) {
                    minAdjCost = Math.Min(minAdjCost, cost[nr, nc]);
                } else {
                    minAdjCost = -1;
                }
            }

            if (cost[row, col] > minAdjCost) {
                queue.Clear();
                queue.Enqueue(row);
                queue.Enqueue(col);
                queue.Enqueue(minAdjCost);
                while (queue.Count > 0) {
                    next.Clear();
                    while (queue.Count > 0) {
                        var crow = queue.Dequeue();
                        var ccol = queue.Dequeue();
                        var step = queue.Dequeue();
                        if (cost[crow, ccol] <= step) continue;
                        cost[crow, ccol] = step;
                        for (int k = 0; k < 4; k++) {
                            var nr = crow + dy[k];
                            var nc = ccol + dx[k];
                            if (0 <= nr && nr < n && 0 <= nc && nc < n) {
                                var w = weight[nr, nc];
                                if (w == 0) {
                                    queue.Enqueue(nr);
                                    queue.Enqueue(nc);
                                    queue.Enqueue(step);
                                } else {
                                    next.Enqueue(nr);
                                    next.Enqueue(nc);
                                    next.Enqueue(step + 1);
                                }
                            }
                        }
                    }
                    Swap(ref queue, ref next);
                }
                //cost.Dump();
            }
        }

        cout.WriteLine(ans);
    }

    public static void Swap<T>(ref T lhs, ref T rhs) { T temp; temp = lhs; lhs = rhs; rhs = temp; }
