internal partial class Solver {

    public int[] dx = new int[] { 0, 1, 0, -1 };
    public int[] dy = new int[] { 1, 0, -1, 0 };

    public void Run() {
        var n = ni();
        var p = ni(n * n);

        //n = 500; p = E.Range(1, n * n).ToArray();

        var cost = new int[n * n];
        var weight = new int[n * n];
        var rows = new int[n * n];
        var cols = new int[n * n];
        int ToIndex(int r, int c) => r * n + c;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                var val = i * n + j;
                var id = ToIndex(i, j);
                weight[id] = 1;
                rows[val] = i;
                cols[val] = j;
                cost[id] = Math.Min(Math.Min(i, n - 1 - i), Math.Min(j, n - 1 - j));
            }
        }
        long ans = 0;
        var queue = new (int, int, int)[(n + 2) * (n * 2)];
        for (int i = 0; i < p.Length; i++) {
            var row = rows[p[i] - 1];
            var col = cols[p[i] - 1];
            var ids = ToIndex(row, col);
            ans += cost[ids];
            weight[ids] = 0;

            int minAdjCost = int.MaxValue;

            for (int k = 0; k < 4; k++) {
                var nr = row + dy[k];
                var nc = col + dx[k];
                if (0 <= nr && nr < n && 0 <= nc && nc < n) {
                    minAdjCost = Math.Min(minAdjCost, cost[ToIndex(nr, nc)]);
                } else {
                    minAdjCost = -1;
                    break;
                }
            }

            if (cost[ids] > minAdjCost) {
                if (false) {
                    void dfs(int r, int c, int step) {
                        var id = ToIndex(r, c);
                        if (cost[id] <= step) return;
                        cost[id] = step;
                        for (int k = 0; k < 4; k++) {
                            var nr = r + dy[k];
                            var nc = c + dx[k];
                            if ((0 <= nr && nr < n) && (0 <= nc && nc < n)) {
                                var nid = ToIndex(nr, nc);
                                var nstep = step + weight[nid];
                                if (cost[nid] > nstep) {
                                    dfs(nr, nc, nstep);
                                }
                            }
                        }
                    }
                    dfs(row, col, minAdjCost);
                } else {
                    var head = 0;
                    var tail = 0;
                    queue[tail++] = (row, col, minAdjCost);
                    while (head < tail) {
                        var (crow, ccol, step) = queue[head++];
                        var id = ToIndex(crow, ccol);
                        if (cost[id] <= step) continue;
                        cost[id] = step;
                        for (int k = 0; k < 4; k++) {
                            var nr = crow + dy[k];
                            var nc = ccol + dx[k];
                            if (0 <= nr && nr < n && 0 <= nc && nc < n) {
                                var nid = ToIndex(nr, nc);
                                var w = weight[nid];
                                if (cost[nid] <= step + w) continue;
                                queue[tail++] = (nr, nc, step + w);
                            }
                        }
                    }
                }
            }
        }

        cout.WriteLine(ans);
    }

    public static void Swap<T>(ref T lhs, ref T rhs) { T temp; temp = lhs; lhs = rhs; rhs = temp; }
}
