using CompLib.Util;
using System;
using System.Collections.Generic;

public class Program
{
    int N;
    int[] P;

    int[] dx = new int[] { 1, 0, -1, 0 };
    int[] dy = new int[] { 0, 1, 0, -1 };
    public void Solve()
    {
        var sc = new Scanner();
        N = sc.NextInt();
        P = sc.IntArray();
        for (int i = 0; i < N * N; i++)
        {
            P[i]--;
        }

        var dist = new int[N, N];
        for (int i = 0; i < N; i++)
        {
            for (int j = 0; j < N; j++)
            {
                dist[i, j] = Math.Min(Math.Min(i + 1, j + 1), Math.Min(N - i, N - j));
            }
        }

        long ans = 0;
        bool[,] flag = new bool[N, N];
        var xq = new Queue<int>();
        var yq = new Queue<int>();
        foreach (var i in P)
        {
            int y = i / N;
            int x = i % N;
            dist[y, x]--;
            flag[y, x] = true;
            ans += dist[y, x];
            xq.Enqueue(x);
            yq.Enqueue(y);
            while (xq.Count > 0)
            {
                int xx = xq.Dequeue();
                int yy = yq.Dequeue();
                for (int j = 0; j < 4; j++)
                {
                    int nx = xx + dx[j];
                    int ny = yy + dy[j];
                    if (nx < 0 || nx >= N) continue;
                    if (ny < 0 || ny >= N) continue;
                    int nc = dist[yy, xx] + (flag[ny, nx] ? 0 : 1);
                    if (dist[ny, nx] <= nc) continue;
                    dist[ny, nx] = nc;
                    xq.Enqueue(nx);
                    yq.Enqueue(ny);
                }
            }

        }
        Console.WriteLine(ans);
    }

    public static void Main(string[] args) => new Program().Solve();
}

