using E = System.Linq.Enumerable;
class FastQueue<T> {
    private T[] nodes;
    private int _head;
    private int _tail;
    public int Count = 0;

    public FastQueue(int size) {
        nodes = new T[size];
        _head = 0;
        _tail = 0;
    }

    public void Clear() {
        _head = _tail = Count = 0;
    }

    public void Enqueue(T value) {
        nodes[_tail++] = value;
        Count++;
        if (_tail >= nodes.Length) {
            _tail = 0;
        }
    }
    public T Dequeue() {
        var ret = nodes[_head];
        Count--;
        if (++_head >= nodes.Length) {
            _head = 0;
        }
        return ret;
    }
}
internal partial class Solver {

    public int[] dx = new int[] { 0, 1, 0, -1 };
    public int[] dy = new int[] { 1, 0, -1, 0 };

    public void Run() {
        var n = ni();
        var p = ni(n * n);
        //n = 500; p = E.Range(1, n * n).ToArray();
        var a = new int[n, n];
        var cost = new int[n, n];
        var weight = new int[n, n];
        var rows = new int[n * n];
        var cols = new int[n * n];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                var val = i * n + j;
                a[i, j] = val;
                weight[i, j] = 1;
                rows[val] = i;
                cols[val] = j;
                cost[i, j] = Math.Min(Math.Min(i, n - 1 - i), Math.Min(j, n - 1 - j));
            }
        }
        long ans = 0;
        var queue = new FastQueue<(int, int, int)>((n + 2) * (n + 2));
        var next = new FastQueue<(int, int, int)>((n + 2) * (n + 2));
        for (int i = 0; i < p.Length; i++) {
            var row = rows[p[i] - 1];
            var col = cols[p[i] - 1];

            ans += cost[row, col];
            weight[row, col] = 0;

            int minAdjCost = int.MaxValue;

            for (int k = 0; k < 4; k++) {
                var nr = row + dy[k];
                var nc = col + dx[k];
                if (0 <= nr && nr < n && 0 <= nc && nc < n) {
                    minAdjCost = Math.Min(minAdjCost, cost[nr, nc]);
                } else {
                    minAdjCost = -1;
                }
            }

            if (cost[row, col] > minAdjCost) {
                queue.Enqueue((row, col, minAdjCost));
                while (queue.Count > 0) {
                    while (queue.Count > 0) {
                        var (crow, ccol, step) = queue.Dequeue();
                        if (cost[crow, ccol] <= step) continue;
                        cost[crow, ccol] = step;
                        for (int k = 0; k < 4; k++) {
                            var nr = crow + dy[k];
                            var nc = ccol + dx[k];
                            if (0 <= nr && nr < n && 0 <= nc && nc < n) {
                                var w = weight[nr, nc];
                                if (cost[nr, nc] > step + w) {
                                    if (w == 0) {
                                        queue.Enqueue((nr, nc, step));
                                    } else {
                                        next.Enqueue((nr, nc, step + 1));
                                    }
                                }
                            }
                        }
                    }
                    Swap(ref queue, ref next);
                }
                //cost.Dump();
            }
        }

        cout.WriteLine(ans);
    }

