namespace V
{
    partial class Solver
    {
        public void Solve()
        {
            //var n = Read;
            Write(SolveLong());
            //YesNo(SolveBool());
        }

        public long SolveLong()
        {
            var n = ReadInt;
            var ps = ArrInt(n * n).Select(x => x - 1).ToArray();
            var empty = new bool[n, n];
            var cost = new int[n, n];
            for (int i = 0; i < n; i++)
            {
                for (int j = 0; j < n; j++)
                {
                    var x = i;
                    x.TryMin(j);
                    x.TryMin(n - 1 - i);
                    x.TryMin(n - 1 - j);
                    cost[i, j] = x;
                }
            }

            var ops = new (int x, int y)[]
            {
                (-1, 0),
                (0, -1),
                (1, 0),
                (0, 1)
            };

            //int Encode(int x, int y) => x * n + y;
            (int x, int y) Decode(int p) => (p / n, p % n);

            void Recalc(int x, int y)
            {
                var newCost = cost[x, y] + (empty[x, y] ? 0 : 1);

                foreach (var op in ops)
                {
                    var nx = x + op.x;
                    var ny = y + op.y;

                    if (nx < 0 || nx >= n || ny < 0 || ny >= n)
                        continue;

                    if (cost[nx, ny].TryMin(newCost))
                    {
                        Recalc(nx, ny);
                    }
                }
            }

            var res = 0L;
            foreach (var p in ps)
            {
                (var x, var y) = Decode(p);
                res += cost[x, y];
