            Console.SetOut(sw);

            var vals = Console.ReadLine().Split(' ')
                .Select(x => int.Parse(x)).ToList();

            int N = vals[0];
            int ans = 0;

            List<int> P = Console.ReadLine().Split(' ')
                .Select(x => int.Parse(x)).ToList();

            List<int> cost = new List<int>(new int[N * N]);
            List<bool> left = new List<bool>(new bool[N * N]);

            for (int i = 0; i < N*N; i++)
            {
                cost[i] = i / N;
                cost[i] = Math.Min(cost[i], N - 1 - i / N);
                cost[i] = Math.Min(cost[i], i % N);
                cost[i] = Math.Min(cost[i], N - 1 - i % N);
            }

            foreach (var ctm in P)
            {
                ans += cost[ctm - 1];
                Queue<int> bfsQueue = new Queue<int>();
                int point = ctm - 1;
                left[ctm - 1] = true;
                bfsQueue.Enqueue(point);
                do
                {
                    point = bfsQueue.Dequeue();
                    if (point + N < N * N && cost[point + N] >
                        cost[point] + (left[point] ? 0 : 1))
                    {
                        cost[point + N] = cost[point] + (left[point] ? 0 : 1);
                        bfsQueue.Enqueue(point + N);
                    }
                    if (point - N >= 0 && cost[point - N] >
                        cost[point] + (left[point] ? 0 : 1))
                    {
                        cost[point - N] = cost[point] + (left[point] ? 0 : 1);
                        bfsQueue.Enqueue(point - N);
                    }
                    if (point % N != N - 1 && cost[point + 1] >
                        cost[point] + (left[point] ? 0 : 1))
                    {
                        cost[point + 1] = cost[point] + (left[point] ? 0 : 1);
                        bfsQueue.Enqueue(point + 1);
                    }
                    if (point % N != 0 && cost[point - 1] >
                        cost[point] + (left[point] ? 0 : 1))
                    {
                        cost[point - 1] = cost[point] + (left[point] ? 0 : 1);
                        bfsQueue.Enqueue(point - 1);
                    }
                } while (bfsQueue.Count() != 0);



            }

            Console.WriteLine(ans);
            Console.Out.Flush();

        }



    }

}

