					h[e.Item1][e.Item2]=Min(h[e.Item1][e.Item2],h[e.Item1+1][e.Item2]+(b[e.Item1+1][e.Item2]?0:1));
					if(g[e.Item1+1][e.Item2]!=i+1){
						g[e.Item1+1][e.Item2]=i+1;
						qu.Enqueue(Tuple.Create(e.Item1+1,e.Item2));
					}
				}
				if(e.Item2!=n-1){
					h[e.Item1][e.Item2]=Min(h[e.Item1][e.Item2],h[e.Item1][e.Item2+1]+(b[e.Item1][e.Item2+1]?0:1));
					if(g[e.Item1][e.Item2+1]!=i+1){
						g[e.Item1][e.Item2+1]=i+1;
						qu.Enqueue(Tuple.Create(e.Item1,e.Item2+1));
