public class Solver
{
	private long[] dy = new long[] { -1, 0, 1, 0 };
	private long[] dx = new long[] { 0, -1, 0, 1 };

	public void Solve()
	{
		long N = GetLong();
		var P = Range(0, N * N).Select(_ => GetLong() - 1).ToArray();

		long conv(long i, long j) => i * N + j;
		var d = new long[N * N];
		for(long i = 0; i < N; i++)
		{
			for(long j = 0; j < N; j++)
				d[conv(i, j)] = Min(Min(i, N - 1 - i), Min(j, N - 1 - j));
		}

		var queue = new Queue<(long, long)>();
		long cnt = 0;
		var left = new bool[N * N];
		for(long i = 0; i < N * N; i++)
		{
			cnt += d[P[i]];
			left[P[i]] = true;

			queue.Enqueue((P[i], d[P[i]]));
			while(queue.Count > 0)
			{
				var (v, c) = queue.Dequeue();
				var (y, x) = (v / N, v % N);
				for(long j = 0; j < 4; j++)
				{
					var (ny, nx) = (y + dy[j], x + dx[j]);
					if(ny < 0 || ny >= N || nx < 0 || nx >= N)
						continue;

					long u = conv(ny, nx);
					if(d[u] > c)
					{
						d[conv(ny, nx)] = c;
						if(left[u])
							queue.Enqueue((u, c));
						else
							queue.Enqueue((u, c + 1));
					}
				}
			}
		}

		WriteLine(cnt);
	}
}

