    {
        static int n;
        static bool[,] nn;


        static int[,] mm;
        static void Main(string[] args)
        {
            n = NextInt();
            var ps = ReadIntArray();
            nn = new bool[n + 2, n + 2];

            long sum = 0;

            mm = new int[n + 2, n + 2];
            Initializemm();

            for (int i = 0; i < n * n; i++)
            {
                var pp = ps[i];
                var p = new P { x = (pp-1) / n + 1, y = (pp-1) % n + 1 };

                sum += mm[p.x, p.y];
                nn[p.x, p.y] = true;

                var q = new Queue<P>(n * n);
                q.Enqueue(p);
                while (q.Any())
                {
                    var c = q.Dequeue();
                    var cc = mm[c.x, c.y] + (nn[c.x, c.y] ? 0 : 1);
                    //SetNext(c);
                    if (c.x > 1 && mm[c.x - 1, c.y] > cc)
                    {
                        mm[c.x - 1, c.y] = cc;
                        q.Enqueue(new P { x = c.x - 1, y = c.y });
                    }
                    if (c.x < n && mm[c.x + 1, c.y] > cc)
                    {
                        mm[c.x + 1, c.y] = cc;
                        q.Enqueue(new P { x = c.x + 1, y = c.y });
                    }
                    if (c.y > 0 && mm[c.x, c.y - 1] > cc)
                    {
                        mm[c.x, c.y - 1] = cc;
                        q.Enqueue(new P { x = c.x, y = c.y - 1 });
                    }
                    if (c.y < n && mm[c.x, c.y + 1] > cc)
                    {
                        mm[c.x, c.y + 1] = cc;
                        q.Enqueue(new P { x = c.x, y = c.y + 1 });
                    }
                }
            }

            Console.WriteLine(sum);
        }
        static void Initializemm()
        {
            for (int i = 2; i < n; i++)
            {
                for (int j = 2; j < n; j++)
                {
                    mm[i, j] = Math.Min(Math.Min(i - 1, n - i), Math.Min(j - 1, n - j));
                }
            }
        }
