public class Program
{
    [System.Diagnostics.DebuggerBrowsable(System.Diagnostics.DebuggerBrowsableState.Never)] private ConsoleReader cr; public Program(ConsoleReader consoleReader) { this.cr = consoleReader; }
    static void Main() => Console.WriteLine(new Program(new ConsoleReader(Console.OpenStandardInput())).Result());
    #endregion
    public string Result() => Calc() switch { bool b => b ? "Yes" : "No", double d => d.ToString("0.####################"), object o => o.ToString(), };
    public object Calc()
    {
        N = cr;
        P = cr.Repeat(N * N).Select(cr => cr.Int0).Select(i => (i / N, i % N)).ToArray();
        costs = new int[N][];
        sumi = new bool[N][];
        for (int h = 0; h < N; h++)
        {
            costs[h] = new int[N];
            sumi[h] = new bool[N];
            for (int w = 0; w < N; w++)
            {
                costs[h][w] = Math.Min(
                    Math.Min(w, N - w - 1),
                    Math.Min(h, N - h - 1)
                    );
            }
        }
        long res = 0;
        foreach (var (h, w) in P)
        {
            res += costs[h][w];
            sumi[h][w] = true;
            Update(h, w, costs[h][w]);
        }

        return res;
    }

    void Update(int h, int w, int val)
    {
        var nexts = new List<(int h, int w)>(4);
        costs[h][w] = val;
        if (!sumi[h][w])
            val++;

        if (h > 0 && costs[h - 1][w] > val)
            nexts.Add((h - 1, w));

        if (w > 0 && costs[h][w - 1] > val)
            nexts.Add((h, w - 1));

        if (h + 1 < N && costs[h + 1][w] > val)
            nexts.Add((h + 1, w));
        if (w + 1 < N && costs[h][w + 1] > val)
            nexts.Add((h, w + 1));

        foreach (var nx in nexts)
            Update(nx.h, nx.w, val);
    }

    int[][] costs;
    bool[][] sumi;
    int N;
    (int h, int w)[] P;
}

