	public class Program
	{
		static void Main()
		{
			var cin = new Scanner();
			int n = cin.Int();
			int nn = n * n;
			var p = cin.ArrayInt(nn, -1);

			var nums = new int[n, n];
			int m = n / 2;
			for (int i = 0; i < m; i++) {
				for (int j = i; j < n - i; j++) {
					nums[i, j] = i;
					nums[n - 1 - i, j] = i;
					nums[j, i] = i;
					nums[j, n - 1 - i] = i;
				}
			}

			if (n % 2 == 1) {
				nums[m, m] = m;
			}

			var done = new bool[n, n];

			long ans = 0;
			for (int i = 0; i < nn; i++) {
				int ii = p[i] / n;
				int jj = p[i] % n;
				done[ii, jj] = true;
				ans += nums[ii, jj];

				var temp = new List<(int ti, int tj, int tn)>();
				var tempDone = new HashSet<(int ti, int tj)>();
				var q = new Queue<(int ti, int tj)>();
				int nextNum = nums[ii, jj];
				Helper.DoAt4(ii, jj, n, n, (iii, jjj) => {
					if (nums[iii, jjj] > nextNum) {
						temp.Add((iii, jjj, nextNum));
						if (done[iii, jjj]) {
							q.Enqueue((iii, jjj));
							tempDone.Add((iii, jjj));
						}
					}
				});

				while (q.Count > 0) {
					var cur = q.Dequeue();
					Helper.DoAt4(cur.ti, cur.tj, n, n, (iii, jjj) => {
						if (nums[cur.ti, cur.tj] == nums[iii, jjj] && tempDone.Contains((iii, jjj)) == false) {
							temp.Add((iii, jjj, nextNum));
							if (done[iii, jjj]) {
								q.Enqueue((iii, jjj));
								tempDone.Add((iii, jjj));
							}
						}
					});
				}

				foreach (var item in temp) {
					nums[item.ti, item.tj] = item.tn;
				}
			}

			Console.WriteLine(ans);
		}
	}

	public class HashMap<TKey, TValue> : Dictionary<TKey, TValue>
	{
		private readonly Func<TKey, TValue> initialzier_;
		public HashMap(Func<TKey, TValue> initialzier)
			: base()
		{
			initialzier_ = initialzier;
		}

		public HashMap(Func<TKey, TValue> initialzier, int capacity)
			: base(capacity)
		{
			initialzier_ = initialzier;
		}

		new public TValue this[TKey key]
		{
			get
			{
				if (ContainsKey(key) == false) {
					base[key] = initialzier_(key);
				}

				return base[key];
			}

			set { base[key] = value; }
		}
	}

	public static class Helper
	{
		public static void UpdateMin<T>(ref T target, T value) where T : IComparable<T>
