		private static readonly int[] delta4_ = { 1, 0, -1, 0, 1 };
		public static void DoAt4(int i, int j, int imax, int jmax, Action<int, int> action)
		{
			for (int n = 0; n < 4; n++) {
				int ii = i + delta4_[n];
				int jj = j + delta4_[n + 1];
				if ((uint)ii < (uint)imax && (uint)jj < (uint)jmax) {
					action(ii, jj);
				}
			}
		}
	}

	public class Scanner
	{
		private readonly char[] delimiter_ = new char[] { ' ' };
		private readonly string filePath_;
		private readonly Func<string> reader_;
		private string[] buf_;
		private int index_;

		public Scanner(string file = "")
		{
			if (string.IsNullOrWhiteSpace(file)) {
				reader_ = Console.ReadLine;
			} else {
				filePath_ = file;
				var fs = new StreamReader(file);
				reader_ = fs.ReadLine;
			}
			buf_ = new string[0];
			index_ = 0;
		}

		public string NextLine() => reader_();
		public string Next()
		{
			if (index_ < buf_.Length) {
				return buf_[index_++];
			}

			string st = reader_();
			while (st == "") {
				st = reader_();
			}

			buf_ = st.Split(delimiter_, StringSplitOptions.RemoveEmptyEntries);
			if (buf_.Length == 0) {
				return Next();
			}

			index_ = 0;
			return buf_[index_++];
		}

		public int Int() => int.Parse(Next());
		public long Long() => long.Parse(Next());
		public double Double() => double.Parse(Next());

		public int[] ArrayInt(int N, int add = 0)
		{
			int[] Array = new int[N];
			for (int i = 0; i < N; i++) {
				Array[i] = Int() + add;
			}
			return Array;
		}

		public long[] ArrayLong(int N, long add = 0)
		{
			long[] Array = new long[N];
			for (int i = 0; i < N; i++) {
				Array[i] = Long() + add;
			}
			return Array;
		}

		public double[] ArrayDouble(int N, double add = 0)
		{
			double[] Array = new double[N];
			for (int i = 0; i < N; i++) {
				Array[i] = Double() + add;
			}
			return Array;
		}

		public void Save(string text)
		{
			if (string.IsNullOrWhiteSpace(filePath_)) {
				return;
			}

			File.WriteAllText(filePath_ + "_output.txt", text);
		}
	}
}

using System;


class GFG
{
    static  int N; // N-.max_x and max_y  
    static int[] GetCoordinate(int n, int N)
    {
        int[] res = new int[2];
        int x = n % N;
        if (x == 0)
        {
            x = N;
        }
        int y = n / N;
        if (n % N != 0)
        {
            y = y + 1;
        }
        res[0] = x - 1;
        res[1] = y - 1;
        return res;
    }
    // A structure to hold the queries  
    public class Query
    {
        public int x1, y1; // x and y co-ordinates of bottom left  
        public int x2, y2; // x and y co-ordinates of top right  

        public Query(int x1, int y1, int x2, int y2)
        {
            this.x1 = x1;
            this.y1 = y1;
            this.x2 = x2;
            this.y2 = y2;
        }

    };

    // A function to update the 2D BIT  
    static void updateBIT(int[,] BIT, int x,
                        int y, int val)
    {
        int y1;
        for (; x <= N; x += (x & -x))
        {
            y1 = y;
            // This loop update all the 1D BIT inside the  
            // array of 1D BIT = BIT[x]  
            for (; y1 <= N; y1 += (y1 & -y1))
                BIT[x, y1] += val;
        }
        return;
    }

    // A function to get sum from (0, 0) to (x, y)  
    static int getSum(int[,] BIT, int x, int y)
    {
        int sum = 0;
        int y1;
        for (; x > 0; x -= x & -x)
        {
            y1 = y;
            // This loop sum through all the 1D BIT  
            // inside the array of 1D BIT = BIT[x]  
            for (; y1 > 0; y1 -= y1 & -y1)
            {
                sum += BIT[x, y1];
            }
        }
        return sum;
    }

    // A function to create an auxiliary matrix  
    // from the given input matrix  
    static void constructAux(int[,] mat, int[,] aux)
    {
        // Initialise Auxiliary array to 0  
        for (int i = 0; i <= N; i++)
            for (int j = 0; j <= N; j++)
                aux[i, j] = 0;

        // Conthe Auxiliary Matrix  
        for (int j = 1; j <= N; j++)
            for (int i = 1; i <= N; i++)
                aux[i, j] = mat[N - j, i - 1];

        return;
    }

    // A function to cona 2D BIT  
    static void construct2DBIT(int[,] mat,
                            int[,] BIT)
    {
        // Create an auxiliary matrix  
        int[,] aux = new int[N + 1, N + 1];
        constructAux(mat, aux);

        // Initialise the BIT to 0  
        for (int i = 1; i <= N; i++)
            for (int j = 1; j <= N; j++)
                BIT[i, j] = 0;

        for (int j = 1; j <= N; j++)
        {
            for (int i = 1; i <= N; i++)
            {
                // Creating a 2D-BIT using update function  
                // everytime we/ encounter a value in the  
                // input 2D-array  
                int v1 = getSum(BIT, i, j);
                int v2 = getSum(BIT, i, j - 1);
                int v3 = getSum(BIT, i - 1, j - 1);
                int v4 = getSum(BIT, i - 1, j);

                // Assigning a value to a particular element  
                // of 2D BIT  
                updateBIT(BIT, i, j, aux[i, j] -
                        (v1 - v2 - v4 + v3));
            }
        }
        return;
    }

    // A function to answer the queries  
    static int answerQueries(Query q, int[,] BIT)
    {

            int x1 = q.x1 + 1;
            int y1 = q.y1 + 1;
            int x2 = q.x2 + 1;
            int y2 = q.y2 + 1;

            int ans = getSum(BIT, x2, y2) -
                    getSum(BIT, x2, y1 - 1) -
                    getSum(BIT, x1 - 1, y2) +
                    getSum(BIT, x1 - 1, y1 - 1);

        return ans;
        }


    // Driver Code 
    public static void Main(String[] args)
    {

    int N;
    N = int.Parse(Console.ReadLine());
        GFG.N = N;
    int[,] mat = new int[N,N];
    int[] A = new int[N*N];
    string[] B = new string[N];
    B = Console.ReadLine().Split(' ');
    for (int i = 0; i < N*N; i++)
        A[i] = int.Parse(B[i]);
    int k = 0;
    for (int i = 0; i < N; i++) {
        for (int j = 0; j < N; j++)
        {
            mat[i,j] = A[k];
            k++;
        }
    }

        // Create a 2D Binary Indexed Tree  
    int[,] BIT = new int[N + 1, N + 1];
    construct2DBIT(mat, BIT);
        int cnt = 0;
        Query q= new Query(0,0,0,0);
        for (int i = 0; i < N; i++) {
            int p = A[i];
            int[] coor = new int[2];
            coor = GetCoordinate(p, N);
            int x = coor[0];
            int y = coor[1];
            int ans1, ans2, ans3, ans4;
            ans1 = 0;ans2 = 0;ans3 = 0;ans4 = 0;

            if (x != 0) {
                q.x1 = 0;
                q.x2 = x - 1;
                q.y1 = y;
                q.y2 = y;
                // #print(q.x1,q.y1,q.x2,q.y2)
                ans1 = answerQueries(q, BIT);
            }
            if (x != N - 1) {
                q.x1 = x + 1;
                q.x2 = N - 1;
                q.y1 = y;
                q.y2 = y;
                //#ans2=getSum(BIT,3,y)-getSum(BIT,x,y)
                //#print(q.x1,q.y1,q.x2,q.y2)
                ans2 = answerQueries(q, BIT);
                    }
            if (y != 0) {
                q.x1 = x;
                q.x2 = x;
                q.y1 = 0;
                q.y2 = y - 1;
                //#print(q.x1,q.y1,q.x2,q.y2)
                ans3 = answerQueries(q, BIT);
                    }
            if (y != N - 1) {
                q.x1 = x;
                q.x2 = x;
                q.y1 = y + 1;
                q.y2 = N - 1;
                //#print(q.x1,q.y1,q.x2,q.y2)
                ans4 = answerQueries(q, BIT);
            }
            cnt += Math.Min(Math.Min(ans1, ans2),Math.Min(ans3, ans4));
            updateBIT(BIT, x + 1, y + 1, -1);
        }
        /* Queries of the form - x1, y1, x2, y2  
        For example the query- {1, 1, 3, 2} means the sub-matrix-  
            y  
            /\  
        3 | 1 2 3 4     Sub-matrix  
        2 | 5 3 8 1     {1,1,3,2} --.     3 8 1  
        1 | 4 6 7 5                                 6 7 5  
        0 | 2 4 8 9  
            |  
        --|------ 0 1 2 3 ---. x  
            |  

            Hence sum of the sub-matrix = 3+8+1+6+7+5 = 30  
        */
        Console.WriteLine(cnt);
    }
}

function Main(input) {
  input = input.trim().split("\n");
  var N = parseInt(input[0], 10);
  var PArr = input[1].split(" ").map((n) => parseInt(n, 10));
  var zaseki = new Array(N);
  var nolike = 0;
  for (var x = 0; x < N; x++) {
    zaseki[x] = new Array(N);
  }
  var data = {};

  for (var i = 1; i <= N; i++) {
    for (var j = 1; j <= N; j++) {
      var num = (i - 1) * N + 1 + (j - 1);
      zaseki[i - 1][j - 1] = num;
      var s = num.toString(10);
      data[s] = [i, j];
    }
  }
  for (var i = 1; i <= N; i++) {
    for (var j = 1; j <= N; j++) {
      var idx = (i - 1) * N + 1 + (j - 1) - 1; //0基準
      var p = PArr[idx]; //座席の番号取得
      var id = data[p][0];
      var jd = data[p][1];
      var left = 0;
      var right = 0;
      var up = 0;
      var down = 0;
      zaseki[id - 1][jd - 1] = 0;
      if (id == 1 || jd == 1 || id == N || jd == N) {
        nolike += 0;
      } else {
        for (var a = id - 1; a > 0; a--) {
          if (zaseki[a - 1][jd - 1] != 0) left++;
        }
        for (var b = id + 1; b <= N; b++) {
          if (zaseki[b - 1][jd - 1] != 0) right++;
        }
        for (var c = id - 1; c > 0; c--) {
          if (zaseki[id - 1][c - 1] != 0) up++;
        }
        for (var d = id + 1; d <= N; d++) {
          if (zaseki[id - 1][d - 1] != 0) down++;
        }
      }
      nolike += Math.min(left, right, up, down);
    }
  }

  console.log(nolike);
}

