    ans += dist[y][x];
    grid[y][x] = 0;
    var q = [y,x];
    while(q.length){
      x = q.pop(), y = q.pop();
      var cost = dist[y][x];
      if(x && dist[y][x-1] - grid[y][x] > cost)dist[y][x-1] = cost + grid[y][x], q.push(y,x-1);
      if(y && dist[y-1][x] - grid[y][x] > cost)dist[y-1][x] = cost + grid[y][x], q.push(y-1,x);
      if(x < n-1 && dist[y][x+1] - grid[y][x] > cost)dist[y][x+1] = cost + grid[y][x], q.push(y,x+1);
      if(y < n-1 && dist[y+1][x] - grid[y][x] > cost)dist[y+1][x] = cost + grid[y][x], q.push(y+1,x);
    }
  }
  return ans;
}

