package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
)

func getScanner(fp *os.File) *bufio.Scanner {
	scanner := bufio.NewScanner(fp)
	scanner.Split(bufio.ScanWords)
	scanner.Buffer(make([]byte, 1000005), 1000005)
	return scanner
}
func getNextString(scanner *bufio.Scanner) string {
	scanner.Scan()
	return scanner.Text()
}
func getNextInt(scanner *bufio.Scanner) int {
	i, _ := strconv.Atoi(getNextString(scanner))
	return i
}
func getNextInt64(scanner *bufio.Scanner) int64 {
	i, _ := strconv.ParseInt(getNextString(scanner), 10, 64)
	return i
}
func getNextUint64(scanner *bufio.Scanner) uint64 {
	i, _ := strconv.ParseUint(getNextString(scanner), 10, 64)
	return i
}
func getNextFloat64(scanner *bufio.Scanner) float64 {
	i, _ := strconv.ParseFloat(getNextString(scanner), 64)
	return i
}
func main() {
	fp := os.Stdin
	wfp := os.Stdout
	cnt := 0
	if os.Getenv("MASPY") == "ますピ" {
		fp, _ = os.Open(os.Getenv("BEET_THE_HARMONY_OF_PERFECT"))
		cnt = 3
	}
	if os.Getenv("MASPYPY") == "ますピッピ" {
		wfp, _ = os.Create(os.Getenv("NGTKANA_IS_GENIUS10"))
	}
	scanner := getScanner(fp)
	writer := bufio.NewWriter(wfp)
	solve(scanner, writer)
	for i := 0; i < cnt; i++ {
		fmt.Fprintln(writer, "-----------------------------------")
		solve(scanner, writer)
	}
	writer.Flush()
}
func solve(scanner *bufio.Scanner, writer *bufio.Writer) {
	n := getNextInt(scanner)
	n2 := n * n
	pp := make([]int, n2)
	for i := 0; i < n2; i++ {
		pp[i] = getNextInt(scanner) - 1
	}
	dp := makeGrid(n, n)
	vv := makeGrid(n, n)
	for i := 0; i < n; i++ {
		for j := 0; j < n; j++ {
			dp[i][j] = distance(i, j, n)
			vv[i][j] = 1
		}
	}

	ans := 0
	for i := 0; i < n2; i++ {
		y := pp[i] / n
		x := pp[i] % n
		ans += dp[y][x]
		dp[y][x]--
		vv[y][x] = 0
		dfs(y, x, n, dp, vv)
	}
	fmt.Fprintln(writer, ans)
}
func dfs(y, x, n int, dp, vv [][]int) {
	dy := [4]int{-1, 0, 0, 1}
	dx := [4]int{0, -1, 1, 0}
	for i := 0; i < 4; i++ {
		yy := y + dy[i]
		xx := x + dx[i]
		if yy < 0 {
			continue
		}
		if yy >= n {
			continue
		}
		if xx < 0 {
			continue
		}
		if xx >= n {
			continue
		}
		if dp[y][x]+vv[yy][xx] < dp[yy][xx] {
			dp[yy][xx] = dp[y][x] + vv[yy][xx]
			dfs(yy, xx, n, dp, vv)
		}
	}
}
func distance(y, x, n int) int {
	ans := y
	if ans > n-1-y {
		ans = n - 1 - y
	}
	if ans > x {
		ans = x
	}
	if ans > n-1-x {
		ans = n - 1 - x
	}
	return ans
}
func makeGrid(h, w int) [][]int {
	index := make([][]int, h, h)
	data := make([]int, h*w, h*w)
	for i := 0; i < h; i++ {
		index[i] = data[i*w : (i+1)*w]
	}
	return index
}

