			node.number = i + 1

			if row > 0 {
				node.forward = &nodes[i-n]
			}
			if col > 0 {
				node.left = &nodes[i-1]
			}
			if row < n-1 {
				node.backward = &nodes[i+n]
			}
			if col < n-1 {
				node.right = &nodes[i+1]
			}

			node.cost = Min(row, col, n-1-row, n-1-col)
		}
	}

	totalCost := 0
	for pi := 0; pi < pCount; pi++ {
		nodeNum := sc.ReadInt()
		nodeExited := &nodes[nodeNum-1]
		totalCost += nodeExited.cost
		nodeExited.empty = true

		nodesToCheck := NewNodeQueue()
		nodesToCheck.Enqueue(nodeExited)
		for nodesToCheck.Len() > 0 {
			node := nodesToCheck.Dequeue()
			node.EachAround(func(nodeAround *Node) {
				var costChanged int
				if node.empty {
					costChanged = node.cost
				} else {
					costChanged = node.cost + 1
				}

				if costChanged < nodeAround.cost {
