type Node struct {
	number                         int
	empty                          bool
	cost                           int
	forward, backward, left, right *Node
}

func (node *Node) EachAround(callback func(*Node)) {
	aroundNodes := []*Node{node.forward, node.left, node.backward, node.right}
	for _, aroundNode := range aroundNodes {
		if aroundNode == nil {
			continue
		}
		callback(aroundNode)
	}
}

type NodeQueue struct {
	first *NodeQueueElem
	last  *NodeQueueElem
	len   int
}

type NodeQueueElem struct {
	child *NodeQueueElem
	value *Node
}

func NewNodeQueue() *NodeQueue {
	return &NodeQueue{nil, nil, 0}
}

func (q *NodeQueue) Len() int {
	return q.len
}

func (q *NodeQueue) Enqueue(item *Node) {
	node := NodeQueueElem{nil, item}
	if q.first == nil {
		q.first = &node
		q.last = &node
	} else {
		q.last.child = &node
		q.last = &node
	}
	q.len++
}

func (q *NodeQueue) Dequeue() *Node {
	elem := q.first
	q.first = elem.child
	q.len--
	return elem.value
}

