func Solve() {
  var N, x, y, q, c int
  var P []int
  NextInt(&N)
  NextIntVec(&P)
  C := make([][]int, N + 2)
  for i := range C { C[i] = make([]int, N + 2) }
  S := make([][]int, N + 2)
  for i := range S { S[i] = make([]int, N + 2) }
  for i := 0; i < N; i++ {
    for j := 0; j < N; j++ {
      C[i + 1][j + 1] = MinInt(i, j, N - 1 - i, N - 1 - j)
      S[i + 1][j + 1]++
    }
  }
  cnt := 0
  Q := make([]int, 0)
  for _, p := range P {
    p--
    x, y = p / N + 1, p % N + 1
    cnt += C[x][y]
    S[x][y] = 0
    Q = append(Q, p)
    for 0 < len(Q) {
      q, Q = Q[0], Q[1:]
      x, y = q / N + 1, q % N + 1
      c = C[x][y] + S[x][y]
      if c < C[x - 1][y] { C[x - 1][y] = c; Q = append(Q, q - N) }
      if c < C[x + 1][y] { C[x + 1][y] = c; Q = append(Q, q + N) }
      if c < C[x][y - 1] { C[x][y - 1] = c; Q = append(Q, q - 1) }
      if c < C[x][y + 1] { C[x][y + 1] = c; Q = append(Q, q + 1) }
    }
  }
  Write(cnt)
}

