void main()
{
	auto N = RD;
	auto P = RDA(-1);
	auto cnt = new long[][](N, N);
	foreach (i; 0..N)
	{
		auto b = N-i-1;
		foreach (j; 0..N)
		{
			auto r = N-j-1;
			cnt[i][j] = min(i, j, b, r);
		}
	}
	auto use = new long[][](N, N);
	foreach (i; 0..N)
	{
		use[i][] = 1;
	}

	void visit(long y, long x)
	{
		auto cost = cnt[y][x] + use[y][x];
		if (y != 0)
		{
			if (cost < cnt[y-1][x])
			{
				cnt[y-1][x] = cost;
				visit(y-1, x);
			}
		}
		if (y != N-1)
		{
			if (cost < cnt[y+1][x])
			{
				cnt[y+1][x] = cost;
				visit(y+1, x);
			}
		}
		if (x != 0)
		{
			if (cost < cnt[y][x-1])
			{
				cnt[y][x-1] = cost;
				visit(y, x-1);
			}
		}
		if (x != N-1)
		{
			if (cost < cnt[y][x+1])
			{
				cnt[y][x+1] = cost;
				visit(y, x+1);
			}
		}
	}
	debug writeln(cnt);

	long ans;
	foreach (e; P)
	{
		auto y = e / N;
		auto x = e % N;
		visit(y, x);
		ans += cnt[y][x];
		use[y][x] = 0;
		visit(y, x);
	}

	writeln(ans);
	stdout.flush;
	debug readln;
}

