  foreach(i; 0..N) foreach(j; 0..N) {
    xss[i][j] = min(i, j, N-i-1, N-j-1);
  }

  struct Pos {
    long x, y;
  }

  long[][] bss = new long[][](N, N);
  foreach(i; 0..N) bss[i][] = 1;

  long[] dx = [-1, 0, 1, 0];
  long[] dy = [0, -1, 0, 1];

