        ss[i][j] = min(i+1, N-i, j+1, N-j);
    }

    auto memo = new int[][](N, N);

    void recalc(int i, int j, int d, int n) {
        foreach (s; [[1,0], [0,1], [-1,0], [0,-1]]) {
            auto ii = i+s[0];
            auto jj = j+s[1];
            if (ii < 0 || ii >= N || jj < 0 || jj >= N || memo[ii][jj] == n) continue;
            memo[ii][jj] = n;
            if (ss[ii][jj] != 0) {
                if (ss[ii][jj] <= d) continue;
                ss[ii][jj] = d;
            }
            recalc(ii, jj, d + (ss[ii][jj] == 0 ? 0 : 1), n);
        }
    }

    int r;
    foreach (m, p; readln.split.to!(int[])) {
        auto i = (p-1)/N;
        auto j = (p-1)%N;
        auto n = m.to!int+1;
        auto d = ss[i][j];
        r += d-1;
        ss[i][j] = 0;
        memo[i][j] = n;
        recalc(i, j, d, n);

    }
    writeln(r);
}

import std;

immutable int dirs = 4;
immutable int [dirs] dRow = [-1,  0, +1,  0];
immutable int [dirs] dCol = [ 0, -1,  0, +1];

void main ()
{
	int n;
	while (readf !(" %s") (n) > 0)
	{
		readln;
		auto board = new int [] [] (n + 2, n + 2);
		foreach (row; 1..n + 1)
		{
			foreach (col; 1..n + 1)
			{
				board[row][col] = min (row - 1, n - row,
				    col - 1, n - col);
			}
		}
		auto mark = new bool [] [] (n + 2, n + 2);

		void recur (int row, int col)
		{
			auto cost = board[row][col] + !mark[row][col];
			foreach (dir; 0..dirs)
			{
				auto nRow = row + dRow[dir];
				auto nCol = col + dCol[dir];
				if (board[nRow][nCol] > cost)
				{
					board[nRow][nCol] = cost;
					recur (nRow, nCol);
				}
			}
		}

		int res = 0;
		foreach (cur; readln.splitter.map !(to !(int)))
		{
			cur -= 1;
			auto row = cur % n + 1;
			auto col = cur / n + 1;
			res += board[row][col];
			mark[row][col] = true;
			recur (row, col);
		}
		writeln (res);
	}
}

