void main()
{
	auto N = RD;
	auto P = RDA(-1);
	auto cnt = new long[][](N, N);
	foreach (i; 0..N)
	{
		if (i == 0 || i == N-1) continue;
		foreach (j; 0..N)
		{
			if (j == 0 || j == N-1) continue;
			cnt[i][j] = int.max;
		}
	}
	auto use = new long[][](N, N);
	foreach (i; 0..N)
	{
		use[i][] = 1;
	}

	void visit(in long[][] pos)
	{
		bool[long[]] nPos;
		foreach (e; pos)
		{
			auto y = e[0];
			auto x = e[1];
			long[] arr;
			if (y != 0)
				arr ~= cnt[y-1][x] + use[y-1][x];
			if (y != N-1)
				arr ~= cnt[y+1][x] + use[y+1][x];
			if (x != 0)
				arr ~= cnt[y][x-1] + use[y][x-1];
			if (x != N-1)
				arr ~= cnt[y][x+1] + use[y][x+1];
			auto p = arr.MIN_POS;
			//debug writeln(nPos);
			if (arr[p] < cnt[y][x])
			{
				cnt[y][x] = arr[p];
				long[] ny, nx;
				if (y != 0)
					nPos[[y-1, x].idup] = true;
				if (y != N-1)
					nPos[[y+1, x].idup] = true;
				if (x != 0)
					nPos[[y, x-1].idup] = true;
				if (x != N-1)
					nPos[[y, x+1].idup] = true;
			}
		}
		if (!nPos.empty)
			visit(nPos.keys);
	}
	visit([[1, 1]]);
	debug writeln(cnt);

	long ans;
	foreach (e; P)
	{
		auto y = e / N;
		auto x = e % N;
		//visit([[y, x]]);
		ans += cnt[y][x];
		use[y][x] = 0;

		long[][] pos;
		if (y != 0)
			pos ~= [y-1, x];
		if (y != N-1)
			pos ~= [y+1, x];
		if (x != 0)
			pos ~= [y, x-1];
		if (x != N-1)
			pos ~= [y, x+1];
		visit(pos);
	}

	writeln(ans);
	stdout.flush;
	debug readln;
}

import std.stdio, std.algorithm, std.conv, std.array, std.string, std.math, std.typecons, std.numeric, std.container, std.range;

struct S
{
    S* top, bottom, right, left;
    int depth;
}

void main()
{
    auto N = readln.chomp.to!int;
    auto ss = new S[][](N, N);
    foreach (i; 0..N) foreach (j; 0..N) {
        auto s = &ss[i][j];
        if (i) s.top = &ss[i-1][j];
        if (i < N-1) s.bottom = &ss[i+1][j];
        if (j) s.left = &ss[i][j-1];
        if (j < N-1) s.right = &ss[i][j+1];
        s.depth = min(i+1, N-i, j+1, N-j);
    }

    void recalc(S* s, int d) {
        if (s.depth <= d) return;
        s.depth = d;
        if (s.top) recalc(s.top, d+1);
        if (s.bottom) recalc(s.bottom, d+1);
        if (s.left) recalc(s.left, d+1);
        if (s.right) recalc(s.right, d+1);
    }

    int r;
    foreach (p; readln.split.to!(int[])) {
        --p;
        auto s = &ss[p/N][p%N];
        r += s.depth-1;
        if (s.top) s.top.bottom = s.bottom;
        if (s.bottom) s.bottom.top = s.top;
        if (s.left) s.left.right = s.right;
        if (s.right) s.right.left = s.left;

        if (s.top) recalc(s.top, s.depth);
        if (s.bottom) recalc(s.bottom, s.depth);
        if (s.left) recalc(s.left, s.depth);
        if (s.right) recalc(s.right, s.depth);
    }
    writeln(r);
}

