{
	auto N = RD;
	auto P = RDA(-1);
	auto cnt = new long[][](N, N);
	foreach (i; 0..N)
	{
		if (i == 0 || i == N-1) continue;
		foreach (j; 0..N)
		{
			if (j == 0 || j == N-1) continue;
			cnt[i][j] = int.max;
		}
	}
	auto use = new long[][](N, N);
	foreach (i; 0..N)
	{
		use[i][] = 1;
	}

	void visit(in long[][] pos)
	{
		long[][] nPos;
		foreach (e; pos)
		{
			auto y = e[0];
			auto x = e[1];
			long[] arr;
			if (y != 0)
				arr ~= cnt[y-1][x] + use[y-1][x];
			if (y != N-1)
				arr ~= cnt[y+1][x] + use[y+1][x];
			if (x != 0)
				arr ~= cnt[y][x-1] + use[y][x-1];
			if (x != N-1)
				arr ~= cnt[y][x+1] + use[y][x+1];
			auto p = arr.MIN_POS;
			//debug writeln(nPos);
			if (arr[p] < cnt[y][x])
			{
				cnt[y][x] = arr[p];
				long[] ny, nx;
				if (y != 0)
					nPos ~= [y-1, x];
				if (y != N-1)
					nPos ~= [y+1, x];
				if (x != 0)
					nPos ~= [y, x-1];
				if (x != N-1)
					nPos ~= [y, x+1];
			}
		}
		visit(nPos);
	}
	visit([[1, 1]]);
	debug writeln(cnt);

	long ans;
	foreach (e; P)
	{
		auto y = e / N;
		auto x = e % N;
		//visit([[y, x]]);
		ans += cnt[y][x];
		use[y][x] = 0;

		long[][] pos;
		if (y != 0)
			pos ~= [y-1, x];
		if (y != N-1)
			pos ~= [y+1, x];
		if (x != 0)
			pos ~= [y, x-1];
		if (x != N-1)
			pos ~= [y, x+1];
		visit(pos);
	}

	writeln(ans);
	stdout.flush;
	debug readln;
}

