def _i(): return int(sys.stdin.readline().strip())


def _ia(): return map(int, sys.stdin.readline().strip().split())


visited = {}


def update(n, cost, idx):
    global visited
    ci = cost[idx] + visited.get(idx, 1)

    # left
    if idx % n != 0:
        idx_ = idx - 1
        if cost[idx_] > ci:
            cost[idx_] = ci
            update(n, cost, idx_)

    # right
    idx_ = idx + 1
    if idx_ % n != 0:
        if cost[idx_] > ci:
            cost[idx_] = ci
            update(n, cost, idx_)

    # front
    idx_ = idx - n
    if idx_ >= 0:
        if cost[idx_] > ci:
            cost[idx_] = ci
            update(n, cost, idx_)

    # back
    idx_ = idx + n
    if idx_ // n < n:
        if cost[idx_] > ci:
            cost[idx_] = ci
            update(n, cost, idx_)


def main():
