    for i in range(1, n*n+1):
        if i <= n * n - n:
            nodes[i].N = nodes[i+n]
        if i > n:
            nodes[i].S = nodes[i-n]
        if i % n:
            nodes[i].E = nodes[i+1]
        if i % n != 1:
            nodes[i].W = nodes[i-1]

