def to_idx(p):
    return divmod(p, n)


def generate_dv(i, j):
    if 0 < i:
        yield -n
    if i < n-1:
        yield n
    if 0 < j:
        yield -1
    if j < n-1:
        yield 1


def bfs(init_v):
    next_v = deque([init_v])
    exist[init_v] = 0
    while next_v:
        v = next_v.popleft()
        i, j = to_idx(v)
        for dv in generate_dv(i, j):
            if cost[v+dv] <= cost[v]+exist[v]:
                continue
            cost[v+dv] = cost[v]+exist[v]
            next_v.append(v+dv)


ans = 0
for p in Ps:
    ans += cost[p]
    bfs(p)
