def bfs(loc):
    data = [True]*(N**2)
    data[loc] = 1
    s = P[loc]
    stack = [[0, loc]]
    while True:
        d, v = heapq.heappop(stack)
        # 上
        if v-N >= 0:
            if data[v-N]:
                data[v-N] = False
                if s < P[v-N]:
                    heapq.heappush(stack, [d+1, v-N])
                else:
                    heapq.heappush(stack, [d, v-N])
        else:
            return d
        # 左
        if v%N != 0:
            if data[v-1]:
                data[v-1] = False
                if s < P[v-1]:
                    heapq.heappush(stack, [d+1, v-1])
                else:
                    heapq.heappush(stack, [d, v-1])
        else:
            return d
        # 右
        if (v+1)%N != 0 and v != N**2-1:
            if data[v+1]:
                data[v+1] = False
                if s < P[v+1]:
                    heapq.heappush(stack, [d+1, v+1])
                else:
                    heapq.heappush(stack, [d, v+1])
        else:
            return d
        # 下
        if v+N < N**2:
            if data[v+N]:
                data[v+N] = False
                if s < P[v+N]:
                    heapq.heappush(stack, [d+1, v+N])
                else:
                    heapq.heappush(stack, [d, v+N])
        else:
            return d

