            if px < 0 or N <= px or py < 0 or N <= py:
                continue
            passed.add((px, py))
            q.append((px, py, v))

    for p in ps:
        y, x = divmod(p-1, N)
        v = sheets[x][y]
        total += v
        sheets[x][y] = -1

        passed = {(x, y)}
        push(q, x, y, v, passed)

        while q:
            x, y, v = q.popleft()
            sv = sheets[x][y]
            if sv == -1:
                push(q, x, y, v, passed)
            elif v < sv:
                sheets[x][y] = v
                push(q, x, y, v+1, passed)

    return total


def main():
    N = int(input())
    ps = map(int, input().split())
    print(solve(N, ps))


if __name__ == "__main__":
    main()

