        right = sum(seat[P[i]//N][P[i]%N:])-1 if sum(seat[P[i]//N][P[i]%N:])-1>=0 else 0
        if right == 0:
            seat[P[i]//N][(P[i])%N] = 0
            continue
        top = 0
        j = P[i]//N-1
        while True:
            if j >= 0:
                top += seat[j][P[i]%N]
            else:
                break
            j -= 1
        if top == 0:
            seat[P[i]//N][(P[i])%N] = 0
            continue
        bottom = 0
        j = P[i]//N+1
        while True:
            if j < N:
