def error_print(*args):
    print(*args, file=sys.stderr)


def mt(f):
    import time

    def wrap(*args, **kwargs):
        s = time.time()
        ret = f(*args, **kwargs)
        e = time.time()

        error_print(e - s, 'sec')
        return ret

    return wrap


@mt
def slv(N, P):
    P = [p-1 for p in P]
    cd = [1] * N**2
    ans = 0
    for p in P:
        q = deque()
        x = p//N
        y = p%N
        q.append((x, y, 0))
        t = INF
        done = {(x, y)}

        while q:
            x, y, c = q.popleft()
            for i, j in [(x, y-1), (x, y+1), (x-1, y), (x+1, y)]:
                if (i, j) in done:
                    continue
                done.add((i, j))
                if 0 <= i < N and 0 <= j < N:
                    if cd[i*N+j] == 0:
                        q.appendleft((i, j, c))
                    else:
                        q.append((i, j, c+1))
                else:
                    t = c
                    q = None
                    break
        ans += t
        cd[p] = 0

    return ans


