def is_edge(i, n):
    _ = i%n
    if i < n or n**2-n <= i or _==0 or _==n-1:
        return True
    else:
        return False

def dijkstra(s, n, c_list):
    _list = [float("Inf")]*(n**2)
    _list[s] = 0
    _min = n
    hq = [[0,s]]
    heapq.heapify(hq)
    while len(hq) > 0:
        _ci, _i = heapq.heappop(hq)
        if _list[_i] < _ci:
            continue
        for _cj,_j in c_list[_i]:
            if _list[_j] > (_list[_i] + _cj):
                _list[_j] = _list[_i] + _cj
                if is_edge(_j,n):
                    _min = min(_min, _list[_j])
                    if _min == 0:
                        return 0
                heapq.heappush(hq, [_list[_j],_j])
    return _min

