    stack = [[0, loc]]
    while stack:
        d, v = heapq.heappop(stack)
        # 上
        if v-N >= 0:
            if data[v-N] == -1:
                data[v-N] = 1
                if s < P[v-N]:
                    heapq.heappush(stack, [d+1, v-N])
                else:
                    heapq.heappush(stack, [d, v-N])
        else:
            return d
