        if v%N != 0:
            if data[v-1] == -1:
                data[v-1] = 1
                if s < P[v-1]:
                    heapq.heappush(stack, [d+1, v-1])
                else:
                    heapq.heappush(stack, [d, v-1])
        else:
            return d
            # ans = min(ans, d)
        # 右
        if (v+1)%N != 0 and v != N**2-1:
            if data[v+1] == -1:
                data[v+1] = 1
                if s < P[v+1]:
                    heapq.heappush(stack, [d+1, v+1])
                else:
