    global seet, N
    if j-1 >= 0:
        if seet[i][j-1] == -1:
            dfsr(i, j-1, cnt)
        else:
            if seet[i][j-1] > cnt:
                seet[i][j-1] = cnt
                dfs(i, j-1, cnt+1)

def dfsu(i, j, cnt):
    global seet, N
    if i-1 >= 0:
        if seet[i-1][j] == -1:
