fn main() {
    let n = read::<usize>();
    let p = read_vec::<usize>()
        .iter()
        .map(|x| x - 1)
        .collect::<Vec<_>>();

    let mut grid = vec![vec![0; n]; n];
    for y in 0..n {
        for x in 0..n {
            grid[y][x] = vec![x, y, n - 1 - x, n - 1 - y].into_iter().min().unwrap() as i64;
        }
    }
    let mut occ = vec![vec![1; n]; n];

    let mut ans = 0i64;
    for num in p {
        let x = num % n;
        let y = num / n;
        ans += grid[y][x];
        occ[y][x] = 0;
        dfs(x, y, &mut grid, &mut occ);
    }
    println!("{}", ans);
}

fn dfs(x: usize, y: usize, grid: &mut Vec<Vec<i64>>, occ: &mut Vec<Vec<i64>>) {
    for (adj_x, adj_y) in get_adjacents(x, y, grid.len(), grid.len()) {
        if grid[adj_y][adj_x] > grid[y][x] + occ[y][x] {
            grid[adj_y][adj_x] = grid[y][x] + occ[y][x];
            dfs(adj_x, adj_y, grid, occ);
        }
    }
}

fn get_adjacents(x: usize, y: usize, w: usize, h: usize) -> Vec<(usize, usize)> {
    let mut adjacents = vec![];
    if x > 0 {
        adjacents.push((x - 1, y));
    }
    if y > 0 {
        adjacents.push((x, y - 1));
    }
    adjacents.push((x, y));
    if y < h - 1 {
        adjacents.push((x, y + 1));
    }
    if x < w - 1 {
        adjacents.push((x + 1, y));
    }
    adjacents
}

fn read<T: std::str::FromStr>() -> T {
    let mut s = String::new();
    std::io::stdin().read_line(&mut s).ok();
    s.trim().parse().ok().unwrap()
}

fn read_vec<T: std::str::FromStr>() -> Vec<T> {
    read::<String>()
        .split_whitespace()
        .map(|e| e.parse().ok().unwrap())
        .collect()
}

use proconio::input;

fn main() {
    input! {
        n: usize,
        p: [usize; n*n],
    }
    let mut seats: Vec<Vec<_>> = (0..n).map(|_i| (0..n).map(|_j| true).collect()).collect();
    let mut table: Vec<Vec<_>> = (0..n)
        .map(|i| {
            (0..n)
                .map(|j| i.min(j).min(n - i - 1).min(n - j - 1))
                .collect()
        })
        .collect();
    let mut result = 0;
    for pi in p {
        let (i, j) = ((pi - 1) % n, (pi - 1) / n);
        seats[i][j] = false;
        result += table[i][j];
        let mut queue = std::collections::VecDeque::new();
        queue.push_back((i, j));
        while !queue.is_empty() {
            let (ii, jj) = queue.pop_front().unwrap();
            if 0 < ii && table[ii - 1][jj] > table[ii][jj] {
                table[ii - 1][jj] = table[ii][jj] + seats[ii][jj] as usize;
                queue.push_back((ii - 1, jj));
            }
            if ii < n - 1 && table[ii + 1][jj] > table[ii][jj] {
                table[ii + 1][jj] = table[ii][jj] + seats[ii][jj] as usize;
                queue.push_back((ii + 1, jj));
            }
            if 0 < jj && table[ii][jj - 1] > table[ii][jj] {
                table[ii][jj - 1] = table[ii][jj] + seats[ii][jj] as usize;
                queue.push_back((ii, jj - 1));
            }
            if jj < n - 1 && table[ii][jj + 1] > table[ii][jj] {
                table[ii][jj + 1] = table[ii][jj] + seats[ii][jj] as usize;
                queue.push_back((ii, jj + 1));
            }
        }
    }

    println!("{}", result);
}

