const BIG_STACK_SIZE: bool = true;
fn main() {
    use std::thread;
    if BIG_STACK_SIZE {
        thread::Builder::new()
            .stack_size(32 * 1024 * 1024)
            .name("solve".into())
            .spawn(solve)
            .unwrap()
            .join()
            .unwrap();
    } else {
        solve();
    }
}
fn solve() {
    let N = get!(usize);
    let P = get!([usize1]);
    let mut seats = vec![vec![0usize; N]; N];
    for i in 0..N {
        for j in 0..N {
            seats[i][j] = min!(i, j, N - 1 - i, N - 1 - j);
        }
    }
    let mut exists = vec![vec![true; N]; N];
    let mut ans = 0;
    for p in P {
        let (i, j) = pos(p, N);
        let c = seats[i][j];
        ans += c;
        exists[i][j] = false;
        let mut q = VecDeque::new();
        q.push_back((i, j, c));
        while let Some((i, j, c)) = q.pop_front() {
            seats[i][j] = c;
            let nc = if exists[i][j] { c + 1 } else { c };
            for &(dx, dy) in [(-1, 0), (1, 0), (0, -1), (0, 1)].iter() {
                let ni = i as i64 + dx;
                let nj = j as i64 + dy;
                if ni < 0 || N as i64 <= ni || nj < 0 || N as i64 <= nj {
                    continue;
                }
                if nc < seats[ni as usize][nj as usize] {
                    q.push_back((ni as usize, nj as usize, nc));
                }
            }
        }
    }

    echo!(ans);
}

fn pos(p: usize, N: usize) -> (usize, usize) {
    (p / N, p % N)
}

