// ABC086C - Traveling
// https://atcoder.jp/contests/abs/fasks/arc089_a

fn switch<T>(flag: bool, t: T, f: T) -> T {
    if flag {
        t
    } else {
        f
    }
}

fn main() {
    input! {
        n:usize,
        ps :[i32;n*n]
    }
    //create table
    let mut seats = vec![vec!(-1; n + 2); n + 2];
    seats[n + 1] = vec![-1; n + 2];
    for i in 1..n + 1 {
        for j in 1..n + 1 {
            seats[i][j] = (n * (i - 1) + (j - 1) + 1) as i32;
        }
    }

    let get_position = |seats: &Vec<Vec<i32>>, m: i32| -> Option<(usize, usize)> {
        for i in 1..=n {
            for j in 1..=n {
                if seats[i][j] == m {
                    return Some((i, j));
                }
            }
        }
        None
    };

    let mut count = 0;
    for id in ps.iter() {
        //深さ優先
        //print!("\nid={}", id);
        let mut past = BTreeSet::new();
        let mut stack = Vec::new();
        let (px, py) = get_position(&seats, *id).unwrap();
        stack.push((0i32, px, py));
        loop {
            stack.sort_by_key(|(c, _, _)| -c);
            if let Some(now) = stack.pop() {
                let (c, i, j) = now;
                //print!("({},{})-", i, j);
                if seats[i][j] == -1 {
                    count += c;
                    //println!("{}", c);
                    seats[px][py] = 0;
                    break;
                }

                if !past.contains(&(i, j + 1)) {
                    let c = switch(seats[i][j + 1] > 0, c + 1, c);
                    stack.push((c, i, j + 1));
                }
                if !past.contains(&(i, j - 1)) {
                    let c = switch(seats[i][j - 1] > 0, c + 1, c);
                    stack.push((c, i, j - 1));
                }

                if !past.contains(&(i + 1, j)) {
                    let c = switch(seats[i + 1][j] > 0, c + 1, c);
                    stack.push((c, i + 1, j));
                }

                if !past.contains(&(i - 1, j)) {
                    let c = switch(seats[i - 1][j] > 0, c + 1, c);
                    stack.push((c, i - 1, j));
                }
                past.insert((i, j));
            }
        }
    }

    println!("{}", count);
}

use proconio::{fastout, input};
use std::collections::VecDeque;

#[derive(Debug, Clone, Default)]
struct Cell {
    wait: usize,
    cost: usize,
    neighbors: Vec<usize>,
}

#[fastout]
fn main() {
    input! {in_n: usize};
    input! {in_ps: [usize; in_n * in_n]};

    let width = in_n + 2;
    let height = in_n + 2;
    let mut cells = Vec::new();

    for i in 0..(width * height) {
        let x = i % width;
        let y = i / width;
        let mut cell = Cell::default();

        if 0 < x && x < width - 1 && 0 < y && y < height - 1 {
            cell.wait = 1;
            cell.cost = *[x, width - x - 1, y, height - y - 1].iter().min().unwrap();
            cell.neighbors.push(i + 1);
            cell.neighbors.push(i - 1);
            cell.neighbors.push(i + width);
            cell.neighbors.push(i - width);
        }

        cells.push(cell);
    }

    let mut cost = 0;

    for in_p in in_ps {
        let x = (in_p - 1) % in_n + 1;
        let y = (in_p - 1) / in_n + 1;
        let i = x + y * width;

        cells[i].cost -= 1;
        cells[i].wait = 0;
        cost += cells[i].cost;

        let mut queue = VecDeque::new();

        queue.push_front(i);

        while !queue.is_empty() {
            let i = queue.pop_back().unwrap();

            for n in cells[i].neighbors.clone().iter() {
                let c = cells[i].cost + cells[*n].wait;

                if cells[*n].cost > c {
                    cells[*n].cost = c;
                    queue.push_front(*n);
                }
            }
        }
    }

    println!("{}", cost);
}

