    let mut cost = vec![vec![0usize; n]; n];
    for i in 0..n {
        for j in 0..n {
            cost[i][j] = min!(i, j, n - 1 - i, n - 1 - j);
        }
    }
    let mut exist = vec![vec![true; n]; n];
