use proconio::input;
use proconio::marker::{Bytes, Chars, Usize1};
use std::cmp::{Reverse, min, max};
use itertools::Itertools;

#[proconio::fastout]
fn main() {
    input! {
        n: usize,
        ps: [Usize1; n * n],
    }

    let mut cs = vec![vec![0; n + 2]; n + 2];
    for i in 1..=n {
        for j in 1..=n {
            cs[i][j] = *[i - 1, j - 1, n - i, n - j].iter().min().unwrap()
        }
    }

    let mut exited = vec![vec![false; n + 2]; n + 2];
    let mut ans = 0;
    for p in ps {
        let i = p / n + 1;
        let j = p % n + 1;

        exited[i][j] = true;
        ans += cs[i][j];

        let mut q = vec![(i, j)];
        while let Some((i1, j1)) = q.pop() {
            let c = cs[i1][j1] + if exited[i1][j1] { 0 } else { 1 };
            for &(i2, j2) in &[
                (i1 - 1, j1),
                (i1 + 1, j1),
                (i1, j1 - 1),
                (i1, j1 + 1),
            ] {
                if cs[i2][j2] > c {
                    cs[i2][j2] = c;
                    q.push((i2, j2));
                }
            }
        }
    }

    println!("{}", ans);
}

use std::cmp;
use std::collections::VecDeque;
fn main() {
    let (r, w) = (std::io::stdin(), std::io::stdout());
    let mut sc = IO::new(r.lock(), w.lock());
    let n: usize = sc.read();
    let p: Vec<_> = (0..(n * n)).map(|_| sc.read::<usize>() - 1).collect();
    let mut dist = vec![0; n * n];
    for x in 0..(n * n) {
        let (i, j) = (x / n, x % n);
        let h = cmp::min(i, n - 1 - i);
        let w = cmp::min(j, n - 1 - j);
        dist[x] = cmp::min(h, w);
    }

    let mut empty = vec![false; n * n];
    let mut sum = 0;
    let mut q = VecDeque::new();
    for p in p.into_iter() {
        empty[p] = true;
        let (i, j) = (p / n, p % n);
        sum += dist[p];
        for &(di, dj) in [(0, 1), (0, !0), (1, 0), (!0, 0)].iter() {
            let ni = i.wrapping_add(di);
            let nj = j.wrapping_add(dj);
            if ni >= n || nj >= n {
                continue;
            }
            let np = ni * n + nj;
            if dist[np] > dist[p] {
                dist[np] = dist[p];
                q.push_back((ni, nj));
            }
        }

        while let Some((i, j)) = q.pop_front() {
            let p = i * n + j;
            let cost = if empty[p] { 0 } else { 1 };
            for &(di, dj) in [(0, 1), (0, !0), (1, 0), (!0, 0)].iter() {
                let ni = i.wrapping_add(di);
                let nj = j.wrapping_add(dj);
                if ni >= n || nj >= n {
                    continue;
                }
                let np = ni * n + nj;
                if dist[np] > dist[p] + cost {
                    dist[np] = dist[p] + cost;
                    q.push_back((ni, nj));
                }
            }
        }
    }
    println!("{}", sum);
}

pub struct IO<R, W: std::io::Write>(R, std::io::BufWriter<W>);

impl<R: std::io::Read, W: std::io::Write> IO<R, W> {
    pub fn new(r: R, w: W) -> Self {
        Self(r, std::io::BufWriter::new(w))
    }
    pub fn write<S: ToString>(&mut self, s: S) {
        use std::io::Write;
        self.1.write(s.to_string().as_bytes()).unwrap();
    }
    pub fn read<T: std::str::FromStr>(&mut self) -> T {
        use std::io::Read;
        let buf = self
            .0
            .by_ref()
            .bytes()
            .map(|b| b.unwrap())
            .skip_while(|&b| b == b' ' || b == b'\n' || b == b'\r' || b == b'\t')
            .take_while(|&b| b != b' ' && b != b'\n' && b != b'\r' && b != b'\t')
            .collect::<Vec<_>>();
        unsafe { std::str::from_utf8_unchecked(&buf) }
            .parse()
            .ok()
            .expect("Parse error.")
    }
    pub fn vec<T: std::str::FromStr>(&mut self, n: usize) -> Vec<T> {
        (0..n).map(|_| self.read()).collect()
    }
    pub fn chars(&mut self) -> Vec<char> {
        self.read::<String>().chars().collect()
    }
}

