use proconio::input;
use proconio::marker::{Bytes, Chars, Usize1};
use std::cmp::{Reverse, min, max};
use itertools::Itertools;

#[proconio::fastout]
fn main() {
    input! {
        n: usize,
        ps: [Usize1; n * n],
    }

    let mut cs = vec![vec![0; n]; n];
    for i in 0..n {
        for j in 0..n {
            cs[i][j] = *[i, j, n - 1 - i, n - 1 - j].iter().min().unwrap();
        }
    }

    let mut exited = vec![vec![false; n]; n];
    let mut ans = 0;
    for p in ps {
        let i = p / n;
        let j = p % n;

        exited[i][j] = true;
        ans += cs[i][j];

        let mut q = vec![(i, j)];
        while let Some((i1, j1)) = q.pop() {
            let neighbors = [
                if i1 == 0     { None } else { Some((i1 - 1, j1)) },
                if i1 == n - 1 { None } else { Some((i1 + 1, j1)) },
                if j1 == 0     { None } else { Some((i1, j1 - 1)) },
                if j1 == n - 1 { None } else { Some((i1, j1 + 1)) },
            ];

            let c = cs[i1][j1] + if exited[i1][j1] { 0 } else { 1 };
            for &(i2, j2) in neighbors.iter().flatten() {
                if cs[i2][j2] > c {
                    cs[i2][j2] = c;
                    q.push((i2, j2));
                }
            }
        }
    }

    println!("{}", ans);
}

