use std::collections::VecDeque;

fn main() {
    read!(n = usize);
    let mut dist = table![0; n,n];
    for i in 0..n.ceil_div(2) {
        let beg = (i, i);
        let end = (n-i, n-i);
        let y = beg.0;
        for x in beg.1 .. end.1 {
            dist[y][x] = i;
        }
        let y = end.0 - 1;
        for x in beg.1 .. end.1 {
            dist[y][x] = i;
        }
        let x = beg.1;
        for y in beg.0 .. end.0 {
            dist[y][x] = i;
        }
        let x = end.1 - 1;
        for y in beg.0 .. end.0 {
            dist[y][x] = i;
        }
    }

    read!(ps = Vec<usize_>);
    let mut vacant = table![false; n,n];
    let mut ans = 0;
    let mut queue = VecDeque::with_capacity(n*n);
    for p in ps {
        let pos0 = (p/n, p%n);
        vacant[pos0] = true;
        ans += dist[pos0];

        queue.push_back((pos0, dist[pos0]));
        while let Some((pos, d)) = queue.pop_front() {
            let next_d = if vacant[pos] { d } else { d+1 };
            for next in dist.adjacent4_indices(pos).unwrap() {
                if dist[next] <= next_d {
                    continue;
                }
                dist[next] = next_d;
                queue.push_back((next, next_d));
            }
        }
    }
    println!("{}", ans);
}

