pub struct UnionFind {
    nodes: Vec<UnionFindNode>,
}

enum UnionFindNode {
    Root { size: usize },
    Child { parent: std::cell::RefCell<usize> },
}

impl UnionFind {
    /// Create an union find with `size` vertices.
    pub fn new(size: usize) -> Self {
        UnionFind {
            nodes: (0..size)
                .map(|_| UnionFindNode::Root { size: 1 })
                .collect::<Vec<_>>(),
        }
    }

    /// Get the root index and its component size.
    fn root_node(&self, v: usize) -> (usize, usize) {
        match &self.nodes[v] {
            &UnionFindNode::Root { size } => (v, size),
            &UnionFindNode::Child { parent: ref p } => {
                let (u, size) = self.root_node(*p.borrow());
                // Path compression.
                *p.borrow_mut() = u;
                (u, size)
            }
        }
    }

    /// Get the root index.
    pub fn root(&self, v: usize) -> usize {
        self.root_node(v).0
    }

    /// Get the size of component.
    pub fn size(&self, v: usize) -> usize {
        self.root_node(v).1
    }

    /// Determine if two vertices are in the same component.
    pub fn connects(&self, u: usize, v: usize) -> bool {
        self.root(u) == self.root(v)
    }

    /// Merge components by adding an edge between the two vertices.
    pub fn merge(&mut self, u: usize, v: usize) {
        let (u, u_size) = self.root_node(u);
        let (v, v_size) = self.root_node(v);

        if u == v {
            return;
        }

        if u_size < v_size {
            self.merge(v, u);
            return;
        }

        self.nodes[v] = UnionFindNode::Child {
            parent: std::cell::RefCell::new(u),
        };
        self.nodes[u] = UnionFindNode::Root {
            size: u_size + v_size,
        };
    }
}

fn main() {
    let mut scan = Scan::new();

    let N = scan.word::<usize>();
    let M = N * N;

    let P = scan.list::<usize>(M);

    let mut ord = vec![vec![]; N];
    let mut depth = vec![0; M];
    let mut u = 0;
    for y in 0..N {
        for x in 0..N {
            ord[y].push(u);
            u += 1;

            let d = y.min(x).min(N - 1 - y).min(N - 1 - x);
            depth[ord[y][x]] = d;
        }
    }

    let mut g = vec![vec![]; M];
    for y in 0..N {
        for x in 0..N {
            let u = ord[y][x];

            for &(dy, dx) in &[(1, 0), (0, -1), (-1, 0), (0, 1)] {
                let (y, x) = (y as isize + dy, x as isize + dx);
                if y < 0 || x < 0 || y >= N as isize || x >= N as isize {
                    continue;
                }
                let (y, x) = (y as usize, x as usize);

                let v = ord[y][x];
                g[u].push(v);
                g[v].push(u);
            }
        }
    }

    let mut uf = UnionFind::new(M);
    let mut done = vec![false; M];
    let mut q = VecDeque::new();
    let mut a = vec![];
    let mut total = 0;

    for p in P {
        let u = p - 1;
        let mut d = depth[u];

        for i in 0..g[u].len() {
            let v = g[u][i];

            let mut t = depth[uf.root(v)];
            if !done[v] {
                t += 1;
            }

            d = d.min(t);
        }

        #[cfg(debug_assertions)]
        eprintln!("\x1B[33m{}\x1B[0m = {:?}", "(p, d)", (p, d));

        total += d;
        done[u] = true;

        let mut u = u;
        q.extend(g[u].drain(..));

        while let Some(v) = q.pop_front() {
            if !done[v] {
                a.push(v);
                continue;
            }

            let v = uf.root(v);
            if v == u {
                continue;
            }

            q.extend(g[v].drain(..));

            let d = depth[u].min(depth[v]);

            uf.merge(u, v);
            u = uf.root(u);

            depth[u] = d;
        }

        std::mem::swap(&mut g[u], &mut a);
        a.clear();

        #[cfg(debug_assertions)]
        {
            for y in 0..N {
                for x in 0..N {
                    let u = y * N + x;
                    let w = uf.root(u);
                    eprint!(" {:2}", depth[w]);
                }
                eprintln!("");
            }
        }
    }

    println!("{}", total);
}

use std::collections::VecDeque;

fn main() {
    let (r, w) = (std::io::stdin(), std::io::stdout());
    let mut sc = IO::new(r.lock(), w.lock());

    let n: usize = sc.read();
    let p: Vec<usize> = (0..(n * n)).map(|_| sc.read::<usize>() - 1).collect();
    let mut board = vec![vec!['#'; n]; n];

    let mut sum = 0;
    for p in p.into_iter() {
        let i = p / n;
        let j = p % n;
        board[i][j] = ' ';
        let ans = bfs(&board, (i, j));
        sum += ans;
    }
    println!("{}", sum);
}

fn bfs(board: &Vec<Vec<char>>, start: (usize, usize)) -> usize {
    let n = board.len();
    let (si, sj) = start;
    let mut dist = vec![vec![n * n; n]; n];
    dist[si][sj] = 0;
    let mut q = VecDeque::new();
    q.push_back((si, sj));
    while let Some((i, j)) = q.pop_front() {
        if i == 0 || j == 0 || i == n - 1 || j == n - 1 {
            return dist[i][j];
        }

        for (ni, nj) in next(i, j, n).into_iter() {
            let cost = if board[ni][nj] == '#' { 1 } else { 0 };
            if dist[ni][nj] > dist[i][j] + cost {
                dist[ni][nj] = dist[i][j] + cost;
                if cost == 1 {
                    q.push_back((ni, nj));
                } else {
                    q.push_front((ni, nj));
                }
            }
        }
    }
    unreachable!()
}

fn next(i: usize, j: usize, n: usize) -> Vec<(usize, usize)> {
    let mut result = vec![];
    if i > 0 {
        result.push((i - 1, j));
    }
    if j > 0 {
        result.push((i, j - 1));
    }
    if i + 1 < n {
        result.push((i + 1, j));
    }
    if j + 1 < n {
        result.push((i, j + 1));
    }
    result
}

pub struct IO<R, W: std::io::Write>(R, std::io::BufWriter<W>);

impl<R: std::io::Read, W: std::io::Write> IO<R, W> {
    pub fn new(r: R, w: W) -> Self {
        Self(r, std::io::BufWriter::new(w))
    }
    pub fn write<S: ToString>(&mut self, s: S) {
        use std::io::Write;
        self.1.write(s.to_string().as_bytes()).unwrap();
    }
    pub fn read<T: std::str::FromStr>(&mut self) -> T {
        use std::io::Read;
        let buf = self
            .0
            .by_ref()
            .bytes()
            .map(|b| b.unwrap())
            .skip_while(|&b| b == b' ' || b == b'\n' || b == b'\r' || b == b'\t')
            .take_while(|&b| b != b' ' && b != b'\n' && b != b'\r' && b != b'\t')
            .collect::<Vec<_>>();
        unsafe { std::str::from_utf8_unchecked(&buf) }
            .parse()
            .ok()
            .expect("Parse error.")
    }
    pub fn vec<T: std::str::FromStr>(&mut self, n: usize) -> Vec<T> {
        (0..n).map(|_| self.read()).collect()
    }
    pub fn chars(&mut self) -> Vec<char> {
        self.read::<String>().chars().collect()
    }
}

