fn comp_f64(a: &f64, b: &f64) -> Ordering {
    if a < b {
        return Ordering::Less;
    } else if a > b {
        return Ordering::Greater;
    }
    Ordering::Equal
}

fn main() {

    let mut buf = String::new();
    std::io::stdin().read_to_string(&mut buf).unwrap();
    let mut buf_it = buf.split_whitespace();

    let N = buf_it.next().unwrap().parse::<usize>().unwrap();
    let P = (0..N*N).map(|_| buf_it.next().unwrap().parse::<usize>().unwrap() -1).collect::<Vec<_>>();

    let mut ans = 0;
    let mut cost = (0..N).map(|_| (0..N).map(|_| 0).collect::<Vec<_>>()).collect::<Vec<_>>();
    let mut seated = (0..N).map(|_| (0..N).map(|_| 1).collect::<Vec<_>>()).collect::<Vec<_>>();
    for i in 0..N{
        for j in 0..N{
            let mut tmp = min(i,N-1-i);
            tmp = min(tmp,j);
            tmp = min(tmp,N-1-j);
            cost[i][j] = tmp;
        }
    }

    for p in P{
        let i = p%N;
        let j = p/N;
        ans += cost[i][j];
        seated[i][j] = 0;
        let mut q = vec![(i,j)];
        while q.len()>0{
            let mut qq = Vec::new();
            while q.len()>0{
                let (i,j) = q.pop().unwrap();
                let c = cost[i][j] + seated[i][j];
                let i = i as isize;
                let j = j as isize;
                for (di,dj) in vec![(1,0),(-1,0),(0,1),(0,-1)]{
                    let i = i+di;
                    let j = j+dj;
                    if i<0 || i>=(N as isize) || j<0 || j>=(N as isize) { continue;}
                    let i = i as usize;
                    let j = j as usize;
                    if cost[i][j] <= c{ continue;}
                    cost[i][j] = c;
                    qq.push((i,j));
                }
            }
            q = qq;
        }
    }

    println!("{}",ans);

}

use std::cmp;
use std::cmp::Reverse;
use std::collections::{BinaryHeap, VecDeque};

const INF: usize = 1 << 30;
fn main() {
    let (r, w) = (std::io::stdin(), std::io::stdout());
    let mut sc = IO::new(r.lock(), w.lock());

    let n: usize = sc.read();
    let p: Vec<usize> = (0..(n * n)).map(|_| sc.read::<usize>() - 1).collect();
    let mut dist = vec![vec![INF; n]; n];
    let mut q = VecDeque::new();
    for i in 0..n {
        dist[i][0] = 0;
        q.push_back((i, 0));
        dist[i][n - 1] = 0;
        q.push_back((i, n - 1));
        dist[0][i] = 0;
        q.push_back((0, i));
        dist[n - 1][i] = 0;
        q.push_back((n - 1, i));
    }

    while let Some((i, j)) = q.pop_front() {
        for (ni, nj) in next(i, j, n).into_iter() {
            if dist[ni][nj] > dist[i][j] + 1 {
                dist[ni][nj] = dist[i][j] + 1;
                q.push_back((ni, nj));
            }
        }
    }

    let mut empty = vec![vec![false; n]; n];

    let mut heap = BinaryHeap::<(Reverse<usize>, usize, usize)>::new();
    let mut sum = 0;
    for p in p.into_iter() {
        let i = p / n;
        let j = p % n;
        let ans = dist[i][j];

        while let Some((Reverse(d), i, j)) = heap.pop() {
            if dist[i][j] < d {
                continue;
            }
            if d >= ans {
                heap.push((Reverse(d), i, j));
                break;
            }
            let cost = if empty[i][j] { 0 } else { 1 };
            for (ni, nj) in next(i, j, n).into_iter() {
                if dist[ni][nj] > dist[i][j] + cost {
                    dist[ni][nj] = dist[i][j] + cost;
                    heap.push((Reverse(dist[ni][nj]), ni, nj));
                }
            }
        }

        sum += dist[i][j];
        empty[i][j] = true;

        for (ni, nj) in next(i, j, n).into_iter() {
            if dist[ni][nj] >= dist[i][j] + 1 {
                dist[ni][nj] = dist[i][j];
                heap.push((Reverse(dist[ni][nj]), ni, nj));
            }
        }
    }
    println!("{}", sum);
}

pub struct UnionFind {
    parent: Vec<usize>,
    sizes: Vec<usize>,
    dist: Vec<usize>,
    size: usize,
}

impl UnionFind {
    pub fn new(n: usize, dist: Vec<usize>) -> UnionFind {
        UnionFind {
            parent: (0..n).map(|i| i).collect::<Vec<usize>>(),
            sizes: vec![1; n],
            dist,
            size: n,
        }
    }

    pub fn find(&mut self, x: usize) -> usize {
        if x == self.parent[x] {
            x
        } else {
            let px = self.parent[x];
            self.parent[x] = self.find(px);
            self.parent[x]
        }
    }

    pub fn unite(&mut self, x: usize, y: usize) -> bool {
        let parent_x = self.find(x);
        let parent_y = self.find(y);
        if parent_x == parent_y {
            return false;
        }

        let (large, small) = if self.sizes[parent_x] < self.sizes[parent_y] {
            (parent_y, parent_x)
        } else {
            (parent_x, parent_y)
        };

        self.parent[small] = large;
        self.sizes[large] += self.sizes[small];
        self.sizes[small] = 0;

        self.dist[large] = cmp::min(self.dist[large], self.dist[small]);
        self.dist[small] = 0;

        self.size -= 1;
        true
    }
}

fn next(i: usize, j: usize, n: usize) -> Vec<(usize, usize)> {
    let mut result = vec![];
    if i > 0 {
        result.push((i - 1, j));
    }
    if j > 0 {
        result.push((i, j - 1));
    }
    if i + 1 < n {
        result.push((i + 1, j));
    }
    if j + 1 < n {
        result.push((i, j + 1));
    }
    result
}

