use std::collections::VecDeque;

use proconio::input;

fn main() {
    input! {
        n: usize,
        pp: [usize; n * n],
    };

    let mut grid = vec![vec![true; n]; n];
    let mut ans = 0;
    for p in pp {
        let x = (p - 1) / n;
        let y = (p - 1) % n;
        let mut v = VecDeque::new();
        let mut visited = vec![vec![false; n]; n];
        v.push_back((x, y, 0));
        visited[x][y] = true;
        // println!("{} {} {}", p, x, y);
        while let Some((x, y, cost)) = v.pop_front() {
            if x == 0 || y == 0 || x + 1 == n || y + 1 == n {
                ans += cost;
                break;
            }
            visited[x][y] = true;
            for &(xx, yy) in &[(x, y - 1), (x, y + 1), (x - 1, y), (x + 1, y)] {
                if visited[xx][yy] {
                    continue;
                }
                if grid[xx][yy] {
                    v.push_back((xx, yy, cost + 1));
                } else {
                    v.push_front((xx, yy, cost));
                }
            }
        }
        grid[x][y] = false;
        // println!("{:?}", grid);
    }
    println!("{}", ans);
}

use proconio::{fastout, input};
use std::collections::VecDeque;

#[derive(Debug, Clone, Default)]
struct Cell {
    wait: usize,
    cost: usize,
    neighbors: Vec<usize>,
}

#[fastout]
fn main() {
    input! {in_n: usize};
    input! {in_ps: [usize; in_n * in_n]};

    let width = in_n + 2;
    let height = in_n + 2;
    let mut cells = Vec::new();

    for i in 0..(width * height) {
        let x = i % width;
        let y = i / width;
        let mut cell = Cell::default();

        if 0 < x && x < width - 1 && 0 < y && y < height - 1 {
            cell.wait = 1;
            cell.cost = *[x, width - x - 1, y, height - y - 1].iter().min().unwrap();
            cell.neighbors.push(i + 1);
            cell.neighbors.push(i - 1);
            cell.neighbors.push(i + width);
            cell.neighbors.push(i - width);
        }

        cells.push(cell);
    }

    let mut cost = 0;

    for in_p in in_ps {
        let x = (in_p - 1) % in_n + 1;
        let y = (in_p - 1) / in_n + 1;
        let i = x + y * width;

        cells[i].cost -= 1;
        cells[i].wait = 0;
        cost += cells[i].cost;

        let mut queue = VecDeque::new();

        queue.push_front(i);

        while !queue.is_empty() {
            let i = queue.pop_back().unwrap();

            for n in cells[i].neighbors.clone().iter() {
                let c = cells[i].cost + cells[*n].wait;

                if cells[*n].cost > c {
                    cells[*n].cost = c;
                    queue.push_front(*n);
                }
            }
        }
    }

    println!("{}", cost);
}

use proconio::input;

fn main() {
    input! {
        n: usize,
        p: [usize; n*n],
    }
    let mut seats: Vec<Vec<_>> = (0..n).map(|_i| (0..n).map(|_j| true).collect()).collect();
    let mut table: Vec<Vec<_>> = (0..n)
        .map(|i| {
            (0..n)
                .map(|j| i.min(j).min(n - i - 1).min(n - j - 1))
                .collect()
        })
        .collect();
    let mut result = 0;
    for pi in p {
        let (i, j) = ((pi - 1) % n, (pi - 1) / n);
        seats[i][j] = false;
        result += table[i][j];
        let mut queue = std::collections::VecDeque::new();
        queue.push_back((i, j));
        while !queue.is_empty() {
            let (ii, jj) = queue.pop_front().unwrap();
            if 0 < ii && table[ii - 1][jj] > table[ii][jj] {
                let prev = table[ii - 1][jj];
                table[ii - 1][jj] = table[ii][jj] + seats[ii][jj] as usize;
                if prev > table[ii - 1][jj] {
                    queue.push_back((ii - 1, jj));
                }
            }
            if ii < n - 1 && table[ii + 1][jj] > table[ii][jj] {
                let prev = table[ii + 1][jj];
                table[ii + 1][jj] = table[ii][jj] + seats[ii][jj] as usize;
                if prev > table[ii + 1][jj] {
                    queue.push_back((ii + 1, jj));
                }
            }
            if 0 < jj && table[ii][jj - 1] > table[ii][jj] {
                let prev = table[ii][jj - 1];
                table[ii][jj - 1] = table[ii][jj] + seats[ii][jj] as usize;
                if prev > table[ii][jj - 1] {
                    queue.push_back((ii, jj - 1));
                }
            }
            if jj < n - 1 && table[ii][jj + 1] > table[ii][jj] {
                let prev = table[ii][jj + 1];
                table[ii][jj + 1] = table[ii][jj] + seats[ii][jj] as usize;
                if prev > table[ii][jj + 1] {
                    queue.push_back((ii, jj + 1));
                }
            }
        }
    }

    println!("{}", result);
}

