use itertools::Itertools as _;
use proconio::input;
use proconio::marker::Usize1;
use std::cmp::min;
use std::collections::VecDeque;
fn to_pos(n: usize, y: usize, x: usize) -> usize {
    y * n + x
}
fn to_coord(n: usize, pos: usize) -> (usize, usize) {
    (pos / n, pos % n)
}
fn update(n: usize, there: &[bool], h: &mut [i64], pos: usize) {
    let mut que = VecDeque::new();
    que.push_back((pos, h[pos] - 1));
    while let Some((pos, dist)) = que.pop_front() {
        if h[pos] <= dist {
            continue;
        }
        let (y, x) = to_coord(n, pos);
        h[pos] = dist;
        if y >= 1 {
            let pos = to_pos(n, y - 1, x);
            let cost = if there[pos] { 1 } else { 0 };
            que.push_back((pos, dist + cost));
        }
        if y <= n - 2 {
            let pos = to_pos(n, y + 1, x);
            let cost = if there[pos] { 1 } else { 0 };
            que.push_back((pos, dist + cost));
        }
        if x >= 1 {
            let pos = to_pos(n, y, x - 1);
            let cost = if there[pos] { 1 } else { 0 };
            que.push_back((pos, dist + cost));
        }
        if x <= n - 2 {
            let pos = to_pos(n, y, x + 1);
            let cost = if there[pos] { 1 } else { 0 };
            que.push_back((pos, dist + cost));
        }
    }
}
fn main() {
    input! { n : usize , p : [ Usize1 ; n * n ] , }
    let mut there = vec![true; n * n];
    let mut h = vec![0; n * n];
    for i in 0..n {
        for j in 0..n {
            h[to_pos(n, i, j)] = min(min(i, n - i - 1), min(j, n - j - 1)) as i64;
        }
    }
    let mut ans = 0;
    for i in 0..(n * n) {
        ans += h[p[i]];
        there[p[i]] = false;
        update(n, &there, &mut h, p[i]);
    }
    println!("{}", ans);
}

