        }
    }

    let get_position = |seats: &Vec<Vec<i32>>, m: i32| -> Option<(usize, usize)> {
        for i in 1..=n {
            for j in 1..=n {
                if seats[i][j] == m {
                    return Some((i, j));
                }
            }
        }
        None
    };

    let mut count = 0;
    for id in ps.iter() {
        //優先度付きキュー
        //print!("\nid={}", id);
        let mut past = BTreeSet::new();
        let mut stack = BinaryHeap::new();//コストを逆順にしたいけど、ラッパーを作るのがめんどいのでマイナスにする
        let (px, py) = get_position(&seats, *id).unwrap();
        stack.push((-0i32, px, py));
        loop {
            if let Some(now) = stack.pop() {
                let (c, i, j) = now;
                //print!("({},{})-", i, j);
                if seats[i][j] == -1 {
                    count += -c;
                    if c == 0 {
                        seats[px][py] = -1;
                    }
                    //println!("{}", c);
                    seats[px][py] = 0;
                    break;
                }

                if !past.contains(&(i, j + 1)) {
                    let c = switch(seats[i][j + 1] > 0, c - 1, c);
                    stack.push((c, i, j + 1));
                }
                if !past.contains(&(i, j - 1)) {
                    let c = switch(seats[i][j - 1] > 0, c - 1, c);
                    stack.push((c, i, j - 1));
                }

                if !past.contains(&(i + 1, j)) {
                    let c = switch(seats[i + 1][j] > 0, c - 1, c);
                    stack.push((c, i + 1, j));
                }

                if !past.contains(&(i - 1, j)) {
                    let c = switch(seats[i - 1][j] > 0, c - 1, c);
                    stack.push((c, i - 1, j));
                }
                past.insert((i, j));
            }
        }
    }

    println!("{}", count);
}

