use std::ops::{AddAssign, Sub};
pub fn seq_up(init: usize, limit_exclusive: usize) -> impl Iterator<Item = usize> {
    assert!(init < limit_exclusive);
    std::iter::successors(Some(init), move |&i| {
        let next = next_up(i);
        if next < limit_exclusive {
            Some(next)
        } else {
            None
        }
    })
}
fn next_up(i: usize) -> usize {
    i | i.wrapping_add(1)
}
pub fn seq_dn(init: usize) -> impl Iterator<Item = usize> {
    assert_ne!(init, !0);
    std::iter::successors(Some(init), move |&i| {
        let next = next_down(i);
        if next != !0 {
            Some(next)
        } else {
            None
        }
    })
}
fn next_down(i: usize) -> usize {
    (i & i.wrapping_add(1)).wrapping_sub(1)
}
pub fn update<T>(fenwick: &mut [T], i: usize, delta: T)
where
    T: AddAssign + Copy + Default,
{
    for ii in seq_up(i, fenwick.len()) {
        fenwick[ii] += delta;
    }
}
pub fn prefix_sum<T>(fenwick: &[T], i: usize) -> T
where
    T: AddAssign + Copy + Default,
{
    let mut sum = T::default();
    for ii in seq_dn(i) {
        sum += fenwick[ii];
    }
    sum
}
pub fn sum<T>(fenwick: &[T], start: usize, end: usize) -> T
where
    T: AddAssign + Sub<Output = T> + Copy + Default,
{
    if start == end {
        return T::default();
    }
    let left = if start == 0 {
        Default::default()
    } else {
        prefix_sum(fenwick, start - 1)
    };
    let right = prefix_sum(fenwick, end - 1);
    right - left
}
fn main() {
    input! { n : usize , p : [ Usize1 ; n * n ] , }
    let mut horz = vec![vec![0; n]; n];
    let mut vert = vec![vec![0; n]; n];
    for i in 0..n {
        for j in 0..n {
            update(&mut horz[i], j, 1);
            update(&mut vert[i], j, 1);
        }
    }
    let mut ans = 0;
    for pos in p {
        let x = pos % n;
        let y = pos / n;
        let cost = [
            sum(&horz[y], 0, x),
            sum(&horz[y], x + 1, n),
            sum(&vert[x], 0, y),
            sum(&vert[x], y + 1, n),
        ]
        .iter()
        .copied()
        .min()
        .unwrap();
        ans += cost;
        update(&mut horz[y], x, -1);
        update(&mut vert[x], y, -1);
    }
    println!("{}", ans);
}

