//
// Based on EbTech's Scanner https://stackoverflow.com/q/56449027
//
struct Scanner<'a, R: std::io::BufRead> {
    reader: R,
    buf: String,
    iter: std::str::SplitWhitespace<'a>,
}

impl<'a, R: std::io::BufRead> Scanner<'a, R> {
    fn new(reader: R) -> Self {
        Self { reader, buf: String::new(), iter: "".split_whitespace() }
    }

    fn get_str(&mut self) -> &str {
        if let Some(t) = self.iter.next() {
            return t;
        }
        self.buf.clear();
        self.reader.read_line(&mut self.buf).expect("I/O error");
        self.iter = unsafe { std::mem::transmute(self.buf.split_whitespace()) };
        self.get_str()
    }

    fn get<T: std::str::FromStr>(&mut self) -> T {
        self.get_str().parse().ok().expect("Parse error")
    }
}

const N_MAX: usize = 500;

static mut PS: [usize; N_MAX * N_MAX] = [0; N_MAX * N_MAX];
static mut COSTS: [i32; (N_MAX + 2) * (N_MAX + 2)] =
    [0; (N_MAX + 2) * (N_MAX + 2)];
static mut EXITED: [bool; (N_MAX + 2) * (N_MAX + 2)] =
    [false; (N_MAX + 2) * (N_MAX + 2)];
static mut QUEUE: [usize; N_MAX * N_MAX] = [0; N_MAX * N_MAX];

#[proconio::fastout]
fn main() {
    let stdin = std::io::stdin();
    let mut sc = Scanner::new(stdin.lock());

    unsafe {
        let n: usize = sc.get();
        for i in 0..(n * n) {
            PS[i] = sc.get::<usize>() - 1;
        }

        for x in 1..=n {
            for y in 1..=n {
                COSTS[x * (n + 2) + y] =
                    min(min(x - 1, n - x), min(y - 1, n - y)) as i32;
            }
        }

        let mut ans = 0;
        for i in 0..(n * n) {
            let p = PS[i];
            dbg!(p);

            let x = p / n;
            let y = p % n;
            let p = (x + 1) * (n + 2) + (y + 1);

            EXITED[p] = true;
            ans += COSTS[p];

            let mut nelem = 1;
            QUEUE[0] = p;

            while nelem > 0 {
                nelem -= 1;
                let p1 = QUEUE[nelem];

                let c = COSTS[p1] + if EXITED[p1] { 0 } else { 1 };

                let p2 = p1 - 1;
                if COSTS[p2] > c {
                    COSTS[p2] = c;
                    QUEUE[nelem] = p2;
                    nelem += 1;
                }

                let p2 = p1 + 1;
                if COSTS[p2] > c {
                    COSTS[p2] = c;
                    QUEUE[nelem] = p2;
                    nelem += 1;
                }

                let p2 = p1 - (n + 2);
                if COSTS[p2] > c {
                    COSTS[p2] = c;
                    QUEUE[nelem] = p2;
                    nelem += 1;
                }

                let p2 = p1 + (n + 2);
                if COSTS[p2] > c {
                    COSTS[p2] = c;
                    QUEUE[nelem] = p2;
                    nelem += 1;
                }
            }
        }

        println!("{}", ans);
    }
}

use std::collections::VecDeque;

macro_rules! input {
    (source = $s:expr, $($r:tt)*) => {
        let mut iter = $s.split_whitespace();
        input_inner!{iter, $($r)*}
    };
    ($($r:tt)*) => {
        let mut s = {
            use std::io::Read;
            let mut s = String::new();
            std::io::stdin().read_to_string(&mut s).unwrap();
            s
        };
        let mut iter = s.split_whitespace();
        input_inner!{iter, $($r)*}
    };
}

macro_rules! input_inner {
    ($iter:expr) => {};
    ($iter:expr, ) => {};

    ($iter:expr, $var:ident : $t:tt $($r:tt)*) => {
        let $var = read_value!($iter, $t);
        input_inner!{$iter $($r)*}
    };
}

macro_rules! read_value {
    ($iter:expr, ( $($t:tt),* )) => {
        ( $(read_value!($iter, $t)),* )
    };

    ($iter:expr, [ $t:tt ; $len:expr ]) => {
        (0..$len).map(|_| read_value!($iter, $t)).collect::<Vec<_>>()
    };

    ($iter:expr, chars) => {
        read_value!($iter, String).chars().collect::<Vec<char>>()
    };

    ($iter:expr, usize1) => {
        read_value!($iter, usize) - 1
    };

    ($iter:expr, $t:ty) => {
        $iter.next().unwrap().parse::<$t>().expect("Parse error")
    };
}

#[derive(Debug, Clone, Copy)]
struct Cell {
    x: usize,
    y: usize,
    w: usize,
    c: usize,
}

fn main() {
    input! {n:usize, ps:[usize; (n * n)]};
    let w = n + 2;

    let mut cells = vec![
        vec![
            Cell {
                x: 0,
                y: 0,
                w: 0,
                c: 0,
            };
            w
        ];
        w
    ];

    for y in 1..(n + 1) {
        for x in 1..(n + 1) {
            cells[y][x].x = x;
            cells[y][x].y = y;
            cells[y][x].w = 1;
            cells[y][x].c = *[x, n - x + 1, y, n - y + 1].iter().min().unwrap();
        }
    }

    let mut cost = 0;
    let mut queue = VecDeque::new();

    for p in ps {
        let x = (p - 1) % n + 1;
        let y = (p - 1) / n + 1;

        cells[y][x].c -= 1;
        cells[y][x].w = 0;
        cost += cells[y][x].c;

        queue.push_front(x + y * w);

        while !queue.is_empty() {
            let q = queue.pop_back().unwrap();
            let (qx, qy) = (q % w, q / w);

            for [ax, ay] in [[1, 0], [-1, 0], [0, 1], [0, -1]].iter() {
                let nx = (qx as isize + ax) as usize;
                let ny = (qy as isize + ay) as usize;
                let c = cells[qy][qx].c + cells[ny][nx].w;

                if cells[ny][nx].c > c {
                    cells[ny][nx].c = c;
                    queue.push_front(nx + ny * w);
                }
            }
        }
    }

    println!("{}", cost);
}

