fn main() {
    let n = read::<usize>();
    let p = read_vec::<usize>()
        .iter()
        .map(|x| x - 1)
        .collect::<Vec<_>>();

    let mut grid = vec![vec![0; n]; n];
    for y in 0..n {
        for x in 0..n {
            grid[y][x] = vec![x, y, n - 1 - x, n - 1 - y].into_iter().min().unwrap() as i32;
        }
    }
    let mut occ = vec![vec![1; n]; n];

    let mut ans = 0i32;
    for num in p {
        let x = num % n;
        let y = num / n;
        ans += grid[y][x];
        occ[y][x] = 0;
        dfs(x, y, &mut grid, &mut occ);
    }
    println!("{}", ans);
}

fn dfs(x: usize, y: usize, grid: &mut Vec<Vec<i32>>, occ: &mut Vec<Vec<i32>>) {
    if x > 0 {
        let (adj_x, adj_y) = (x - 1, y);
        if grid[adj_y][adj_x] > grid[y][x] + occ[y][x] {
            grid[adj_y][adj_x] = grid[y][x] + occ[y][x];
            dfs(adj_x, adj_y, grid, occ);
        }
    }
    if y > 0 {
        let (adj_x, adj_y) = (x, y - 1);
        if grid[adj_y][adj_x] > grid[y][x] + occ[y][x] {
            grid[adj_y][adj_x] = grid[y][x] + occ[y][x];
            dfs(adj_x, adj_y, grid, occ);
        }
    }
    if y < grid.len() - 1 {
        let (adj_x, adj_y) = (x, y + 1);
        if grid[adj_y][adj_x] > grid[y][x] + occ[y][x] {
            grid[adj_y][adj_x] = grid[y][x] + occ[y][x];
            dfs(adj_x, adj_y, grid, occ);
        }
    }
    if x < grid.len() - 1 {
        let (adj_x, adj_y) = (x + 1, y);
        if grid[adj_y][adj_x] > grid[y][x] + occ[y][x] {
            grid[adj_y][adj_x] = grid[y][x] + occ[y][x];
            dfs(adj_x, adj_y, grid, occ);
        }
    }
}

