fn main() {
    input! {
        n: usize,
        // f: usize,
        p: [usize1; n*n]
    };

    let mut cost = dvec!(0; n, n);
    for i in 0..n {
        for j in 0..n {
            cost[i][j] = min(min(i, j), min(n-i-1, n-j-1));
        }
    }
    let dy = vec![1, 0, -1, 0];
    let dx = vec![0, 1, 0, -1];
    let mut has = dvec!(1; n, n);

    let mut deq = VecDeque::new();
    let mut ans = 0;
    for pos in p {
        let row = pos / n;
        let col = pos % n;
        // debug!(pos, ans, cost[row][col]);
        ans += cost[row][col];
        has[row][col] = 0;
        deq.push_back((row, col, cost[row][col]));
        while let Some((row, col, co)) = deq.pop_front() {
            for d in 0..4 {
                let trow = (row as i32)+dy[d];
                let tcol = (col as i32)+dx[d];
                if trow < 0 || tcol < 0 || trow >= (n as i32) || tcol >= (n as i32) {
                    continue;
                }
                let trow = trow as usize;
                let tcol = tcol as usize;
                let tco = co + has[row][col];
                if cost[trow][tcol] > tco {
                    cost[trow][tcol] = tco;
                    if tco == co {
                        deq.push_front((trow, tcol, tco));
                    } else {
                        deq.push_back((trow, tcol, tco));
                    }
                }
            }
        }
    }
    println!("{}", ans);
}

use std::cmp;
use std::collections::VecDeque;
fn main() {
    let (r, w) = (std::io::stdin(), std::io::stdout());
    let mut sc = IO::new(r.lock(), w.lock());
    let n: usize = sc.read();
    let p: Vec<_> = (0..(n * n)).map(|_| sc.read::<usize>() - 1).collect();
    let mut dist = vec![0; n * n];
    for x in 0..(n * n) {
        let (i, j) = (x / n, x % n);
        let h = cmp::min(i, n - 1 - i);
        let w = cmp::min(j, n - 1 - j);
        dist[x] = cmp::min(h, w);
    }

    let mut next = vec![vec![vec![]; n]; n];
    for i in 0..n {
        for j in 0..n {
            if i > 0 {
                next[i][j].push((i - 1, j));
            }
            if j > 0 {
                next[i][j].push((i, j - 1));
            }
            if i + 1 < n {
                next[i][j].push((i + 1, j));
            }
            if j + 1 < n {
                next[i][j].push((i, j + 1));
            }
        }
    }

    let mut empty = vec![false; n * n];
    let mut sum = 0;
    for p in p.into_iter() {
        empty[p] = true;
        let (i, j) = (p / n, p % n);
        sum += dist[p];
        let mut q = VecDeque::new();
        for &(ni, nj) in next[i][j].iter() {
            let np = ni * n + nj;
            if dist[np] > dist[p] {
                dist[np] = dist[p];
                q.push_back((ni, nj));
            }
        }

        while let Some((i, j)) = q.pop_front() {
            let p = i * n + j;
            let cost = if empty[p] { 0 } else { 1 };
            for &(ni, nj) in next[i][j].iter() {
                let np = ni * n + nj;
                if dist[np] > dist[p] + cost {
                    dist[np] = dist[p] + cost;
                    q.push_back((ni, nj));
                }
            }
        }
    }
    println!("{}", sum);
}
pub struct IO<R, W: std::io::Write>(R, std::io::BufWriter<W>);

impl<R: std::io::Read, W: std::io::Write> IO<R, W> {
    pub fn new(r: R, w: W) -> Self {
        Self(r, std::io::BufWriter::new(w))
    }
    pub fn write<S: ToString>(&mut self, s: S) {
        use std::io::Write;
        self.1.write(s.to_string().as_bytes()).unwrap();
    }
    pub fn read<T: std::str::FromStr>(&mut self) -> T {
        use std::io::Read;
        let buf = self
            .0
            .by_ref()
            .bytes()
            .map(|b| b.unwrap())
            .skip_while(|&b| b == b' ' || b == b'\n' || b == b'\r' || b == b'\t')
            .take_while(|&b| b != b' ' && b != b'\n' && b != b'\r' && b != b'\t')
            .collect::<Vec<_>>();
        unsafe { std::str::from_utf8_unchecked(&buf) }
            .parse()
            .ok()
            .expect("Parse error.")
    }
    pub fn vec<T: std::str::FromStr>(&mut self, n: usize) -> Vec<T> {
        (0..n).map(|_| self.read()).collect()
    }
    pub fn chars(&mut self) -> Vec<char> {
        self.read::<String>().chars().collect()
    }
}

