            let d = abs(p[i] / n, p[j] / n) + abs(p[i] % n, p[j] % n);
            c = min(c, uf.cost(j) + d - 1);
            if d == 1 {
                uf.unite(i, j);
            }
        }
        uf.set_cost(i, c);
        ans += c;
    }
    println!("{}", ans);
}

