struct UnionFind {
    par: Vec<usize>,
    size: Vec<usize>,
    cost: Vec<usize>,
}
impl UnionFind {
    #[allow(dead_code)]
    fn new(n: usize) -> Self {
        UnionFind {
            par: (0..n).collect(),
            size: vec![1; n],
            cost: vec![std::usize::MAX; n],
        }
    }
    #[allow(dead_code)]
    fn find(&mut self, x: usize) -> usize {
        if self.par[x] == x {
            x
        } else {
            let p = self.find(self.par[x]);
            self.par[x] = p;
            p
        }
    }
    #[allow(dead_code)]
    fn unite(&mut self, x: usize, y: usize) {
        let x = self.find(x);
        let y = self.find(y);
        if x == y {
            return;
        }
        if self.size[x] < self.size[y] {
            self.par[x] = y;
            self.size[y] += self.size[x];
            self.cost[y] = min(self.cost[y], self.cost[x]);
        } else {
            self.par[y] = x;
            self.size[x] += self.size[y];
            self.cost[x] = min(self.cost[x], self.cost[y]);
        }
    }
    #[allow(dead_code)]
