use std::cmp::min;
use std::collections::VecDeque;
fn to_pos(n: usize, y: usize, x: usize) -> usize {
    y * n + x
}
fn to_coord(n: usize, pos: usize) -> (usize, usize) {
    (pos / n, pos % n)
}
fn update(n: usize, there: &[bool], cost: &mut [i64], pos: usize) {
    let w = n + 2;
    let mut que = VecDeque::new();
    que.push_back(pos);
    while let Some(pos) = que.pop_front() {
        let cur = cost[pos];
        let next = cur + there[pos] as i64;
        assert!(next >= 0);
        for &df in [w as i64, -(w as i64), 1, -1].iter() {
            let pos = pos as i64 + df;
            assert!(pos >= 0);
            let pos = pos as usize;
            assert!(pos < w * w);
            if cost[pos] > next {
                cost[pos] = next;
                que.push_back(pos);
            }
        }
    }
}
fn main() {
    input! { n : usize , mut pos : [ Usize1 ; n * n ] , }
    let w = n + 2;
    for pos in &mut pos {
        let (y, x) = to_coord(n, *pos);
        *pos = to_pos(w, y + 1, x + 1);
    }
    let mut there = vec![true; w * w];
    let mut cost = vec![0; w * w];
    for i in 0..w {
        for j in 0..w {
            if i == 0 || i == n + 1 || j == 0 || j == n + 1 {
                cost[to_pos(w, i, j)] = -1;
            } else {
                cost[to_pos(w, i, j)] = min(min(i - 1, n - i), min(j - 1, n - j)) as i64;
            }
        }
    }
    let mut ans = 0;
    for pos in pos {
        ans += cost[pos];
        there[pos] = false;
        update(n, &there, &mut cost, pos);
    }
    println!("{}", ans);
}

