fn main() {
    input! {
        n:usize,
        p:[usize;n*n],
    }

    // 外周に1マス分の空きスペースを増やす
    let n2 = n + 2;
    let mut v: Vec<(usize, usize)> = Vec::with_capacity(n * n);

    for i in 0..n * n {
        let pp = p[i] - 1;
        let x = pp % n;
        let y = pp / n;
        v.push((x + 1, y + 1));
    }

    f(n2, &v);
}

