fn main() {
    let mut scanner = Scanner::new(stdin());
    let n = scanner.read::<usize>().unwrap();
    let arr = scanner.read_vector::<usize>().unwrap().into_iter().map(|val| ((val - 1) / n, (val - 1) % n)).collect::<Vec<_>>();
    let ans = solve(n, &arr);
    println!("{}", ans);
}

fn solve(n: usize, arr: &[(usize, usize)]) -> u64 {
    let dir = vec![(-1, 0), (1, 0), (0, -1), (0, 1)];
    let mut is_empty = vec![vec![false; n]; n];
    let mut count = 0;
    for &(s, e) in arr {
        is_empty[s][e] = true;
        let mut queue = VecDeque::new();
        let mut used = vec![vec![false; n]; n];
        queue.push_front((s, e, 0));
        while queue.len() > 0 {
            let (x, y, d) = queue.pop_back().unwrap();
            if used[x][y] {
                continue;
            }
            used[x][y] = true;
            if x == 0 || x == n - 1 || y == 0 || y == n - 1 {
                count += d;
                break;
            }
            for &(dx, dy) in dir.iter() {
                let new_x = x as i64 + dx;
                let new_y = y as i64 + dy;
                if new_x < 0 || new_y < 0 {
                    continue;
                }
                let new_x = new_x as usize;
                let new_y = new_y as usize;
                if used[new_x][new_y] {
                    continue;
                }
                if is_empty[new_x][new_y] {
                    queue.push_back((new_x, new_y, d));
                } else {
                    queue.push_front((new_x, new_y, d + 1));
                }
            }
        }
    }
    count
}

