fn solve() {
    let n = read!(usize);
    let p = read!([usize]);
    let mut dist = vec![vec![0;n];n];
    for i in 0..n {
        for j in 0..n {
            dist[i][j] = min(min(i,n-1-i),min(j,n-1-j));
        }
    }
    let mut board = vec![vec![0;n];n];
    let mut ans = 0;
    for i in 0..n*n {
        let (cx,cy) = ((p[i]-1)/n, (p[i]-1)%n);
        board[cx][cy] = 1;
        ans += dist[cx][cy];
        let mut q = VecDeque::new();
        q.push_back((cx,cy,dist[cx][cy]));
        let dx = vec![-1,0,1,0];
        let dy = vec![0,-1,0,1];
        while let Some((x,y,d)) = q.pop_front() {
            for k in 0..4 {
                let nx = x as i64 + dx[k];
                let ny = y as i64 + dy[k];
                if nx<0 || nx>=n as i64 || ny<0 || ny>=n as i64 {
                    continue;
                }
                let nd = d + if board[x][y]==1 {0} else {1};
                if nd < dist[nx as usize][ny as usize] {
                    dist[nx as usize][ny as usize] = nd;
                    q.push_back((nx as usize,ny as usize,nd));
                }
            }
        }
    }
    println!("{}", ans);
}

