    let mut rem = vec![vec![true; n]; n];
    for i in 0..n {
        for j in 0..n {
            c[i][j] = min!(i, n - i - 1, j, n - j - 1);
        }
    }
    let mut ans = 0;
    let g = GridGraph::new(n, n);
    for &k in p.iter() {
        let x = k / n;
        let y = k % n;
        ans += c[x][y];
        rem[x][y] = false;
        let mut st = vec![(x, y)];
        while let Some((x, y)) = st.pop() {
            let d = c[x][y] + rem[x][y] as usize;
            g.for_each_adjacency(x, y, |nx, ny| {
                if c[nx][ny] > d {
                    c[nx][ny] = d;
                    st.push((nx, ny));
                }
            });
        }
    }
    println!("{}", ans);
}

