use itertools::Itertools;

#[proconio::fastout]
fn main() {
    input! {
        n: usize,
        ps: [Usize1; n * n],
    }

    let mut costs = vec![0; (n + 2).pow(2)];
    let mut exited = vec![false; (n + 2).pow(2)];

    for x in 1..=n {
        for y in 1..=n {
            costs[x * (n + 2) + y] = min(min(x - 1, n - x), min(y - 1, n - y));
        }
    }

    let mut ans = 0;
    for p in ps {
        let x = p / n;
        let y = p % n;
        let p = (x + 1) * (n + 2) + (y + 1);

        exited[p] = true;
        ans += costs[p];

        let mut q = vec![p];
        while let Some(p1) = q.pop() {
            let c = costs[p1] + if exited[p1] { 0 } else { 1 };
            for &p2 in &[p1 - 1, p1 + 1, p1 - (n + 2), p1 + (n + 2)] {
                if costs[p2] > c {
                    costs[p2] = c;
                    q.push(p2);
                }
            }
        }
    }

    println!("{}", ans);
}

